			_keptNames = new HashSet<string>(from x in _prints.Values.Where(Kept)
				select x.Name);
			GrudgeLog($"LOOKS loaded {_prints.Count} looks ({_keptNames.Count} of people you know)");
			return _prints;
		}
	}

