	private void AffiliateWronged(int handle, string crime)
	{
		string text = AffiliationOf(handle);
		if (text != null && crime != null && _affilTold.Add((handle, crime)))
		{
			Gang gang = Gangs.ById(text);
			if (gang != null)
			{
				string text2 = WhoIs(handle);
				AddNotoriety(gang, (!(crime == "kill") && !(crime == "gore")) ? 1 : 2, text2 + " was a friend of theirs (" + crime + ")");
				Feed("FRIEND OF THE " + gang.Name.ToUpperInvariant() + ": " + text2 + " - word of it will reach them", gang.Accent);
				GrudgeLog("AFFILIATE " + text2 + " (" + gang.Id + ") wronged: " + crime);
			}
		}
	}

	internal Agenda AgendaOf(Gang g)
	{
		if (g == null || g.StoryOnly || IsDestroyed(g))
		{
			return null;
		}
		if (!LeaderTemper(g).HasValue)
		{
			return null;
		}
		if (!Agendas.TryGetValue(g.Id, out var value))
		{
			return null;
		}
		return value;
	}

	internal string AgendaText(Gang g, Agenda a = null)
	{
		a = a ?? AgendaOf(g);
		if (a == null)
		{
			return null;
		}
		return a.Kind switch
		{
			"expand" => "take " + (Districts.FirstOrDefault((District d) => d.Key == a.Target)?.Name ?? "more ground"), 
			"revenge" => "break the " + (Gangs.ById(a.Target)?.Name ?? "enemy"), 
			"rich" => "get rich", 
			"huntyou" => "see you dead", 
			_ => "hold what they have", 
		};
	}

	internal string LeaderKey(Gang g)
	{
		LeaderSeat leaderSeat = SeatOf(g);
		if (leaderSeat == null || leaderSeat.Fallen == null)
		{
			return "lore:" + g.Id;
		}
		if (!string.IsNullOrEmpty(leaderSeat.Successor))
		{
			return leaderSeat.Successor;
		}
		return null;
	}

	private bool RevengeFits(Gang g, Gang e)
	{
		if (e != null && e != g && !e.StoryOnly && !IsDestroyed(e) && g.TurfWars && e.TurfWars)
		{
			return Districts.Any((District d) => HoldOf(d, g.Id) >= 5 && HoldOf(d, e.Id) >= 5);
		}
		return false;
	}

	private Agenda PickAgenda(Gang g, Agenda old = null)
	{
		Personality? personality = LeaderTemper(g);
		string text = g.LeaderName ?? "their leader";
		Agenda agenda = new Agenda
		{
			By = text,
			ById = LeaderKey(g),
			SetAt = GameMinutesNow(),
			ReviewAt = GameMinutesNow() + (long)(6 + _rng.Next(4)) * 1440L
		};
		if (SeatOf(g)?.Fallen == null && LeaderLore.ContainsKey(g.Id))
		{
			switch (g.Id)
			{
			case "odriscoll":
				agenda.Kind = "huntyou";
				return agenda;
			case "bronte":
				agenda.Kind = "rich";
				return agenda;
			case "army":
				agenda.Kind = "hold";
				return agenda;
			case "wapiti":
				agenda.Kind = "hold";
				return agenda;
			}
		}
		int num = NotorietyOf(g);
		switch (personality)
		{
		case Personality.Hothead:
		{
			if (num >= 25 && _rng.Next(2) == 0)
			{
				agenda.Kind = "huntyou";
				break;
			}
			agenda.Target = WorstEnemy();
			Agenda agenda2 = agenda;
			string kind;
			if (agenda.Target != null)
			{
				kind = "revenge";
			}
			else
			{
				kind = ((num >= 10) ? "huntyou" : "hold");
			}
			agenda2.Kind = kind;
			break;
		}
		case Personality.Proud:
			agenda.Target = ExpandTarget();
			agenda.Kind = ((agenda.Target != null) ? "expand" : null);
			if (agenda.Kind == null)
			{
				agenda.Target = WorstEnemy();
				agenda.Kind = ((agenda.Target != null) ? "revenge" : "hold");
			}
			break;
		case Personality.Greedy:
		case Personality.Drifter:
			agenda.Kind = "rich";
			break;
		case Personality.Cold:
			agenda.Target = ExpandTarget();
			agenda.Kind = ((agenda.Target != null) ? "expand" : "hold");
			break;
		case Personality.Loyal:
			agenda.Target = WorstEnemy();
			agenda.Kind = ((agenda.Target != null && Grievances.Any((KeyValuePair<string, int> kv) => kv.Key.Contains(g.Id) && kv.Value >= 20)) ? "revenge" : "hold");
			if (agenda.Kind == "hold")
			{
				agenda.Target = null;
			}
			break;
		default:
			agenda.Kind = "hold";
			break;
		}
		if (old != null && agenda.Kind == old.Kind && agenda.Target == old.Target)
		{
			if (agenda.Kind != "rich")
			{
				agenda.Kind = "rich";
				agenda.Target = null;
			}
			else
			{
				agenda.Kind = "hold";
				agenda.Target = null;
			}
		}
		return agenda;
		string ExpandTarget()
		{
			return (from x in Districts
				select (d: x, h: HoldOf(x, g.Id), top: (from kv in ControlMap[x.Key]
					where kv.Key != g.Id
					select kv.Value).DefaultIfEmpty(0).Max()) into x
				where x.h >= 6 && x.top >= x.h
				orderby x.h descending
				select x).FirstOrDefault().d?.Key;
		}
		string WorstEnemy()
		{
			Gang gang = (from o in Gangs.All
				where RevengeFits(g, o)
				orderby Relation(g.Id, o.Id) - GrievanceOf(g.Id, o.Id)
				select o).FirstOrDefault();
			if (gang == null || Relation(g.Id, gang.Id) > -25)
			{
				return null;
			}
			return gang.Id;
		}
	}

	private bool AgendaMet(Gang g, Agenda a)
	{
		string kind = a.Kind;
		if (!(kind == "expand"))
		{
			if (kind == "revenge")
			{
				Gang gang = Gangs.ById(a.Target);
				if (gang == null || IsDestroyed(gang) || Relation(g.Id, gang.Id) > -10 || !RevengeFits(g, gang) || a.Wins >= 2)
				{
					return true;
				}
				LeaderSeat leaderSeat = SeatOf(gang);
				if (leaderSeat != null && leaderSeat.Fallen != null)
				{
					return leaderSeat.At > a.SetAt;
				}
				return false;
			}
			return false;
		}
		District district = Districts.FirstOrDefault((District x) => x.Key == a.Target);
		if (district == null)
		{
			return true;
		}
		int num = HoldOf(district, g.Id);
		int num2 = (from kv in ControlMap[district.Key]
			where kv.Key != g.Id
			select kv.Value).DefaultIfEmpty(0).Max();
		return num > num2;
	}

	private void DailyAgendas()
	{
		foreach (Gang item in Gangs.All.Where((Gang x) => !x.StoryOnly && !IsDestroyed(x)))
		{
			if (!LeaderTemper(item).HasValue)
			{
				continue;
			}
			string text = item.LeaderName ?? "their leader";
			string text2 = LeaderKey(item);
			Agendas.TryGetValue(item.Id, out var value);
			if (value != null && value.ById == null)
			{
				value.ById = text2;
				value.By = text;
			}
			if (value == null)
			{
				Agenda agenda = PickAgenda(item);
				Agendas[item.Id] = agenda;
				GrudgeLog("AGENDA " + item.Name + ": " + text + " means to " + AgendaText(item, agenda));
				SaveWorld();
				continue;
			}
			if (value.ById != text2)
			{
				Personality? personality = LeaderTemper(item);
				bool flag = personality == Personality.Loyal || (personality != Personality.Proud && personality != Personality.Hothead && _rng.Next(2) == 0);
				string text3 = AgendaText(item, value);
				string text4 = value.By;
				if (flag && value.Kind == "revenge" && !RevengeFits(item, Gangs.ById(value.Target)))
				{
					flag = false;
				}
				Agenda agenda2 = (flag ? new Agenda
				{
					Kind = value.Kind,
					Target = value.Target,
					By = text,
					ById = text2,
					SetAt = GameMinutesNow(),
					ReviewAt = GameMinutesNow() + (long)(6 + _rng.Next(4)) * 1440L
				} : PickAgenda(item, value));
				Agendas[item.Id] = agenda2;
				AgendaEvent(item, flag ? (text + " takes up " + text4 + "'s fight") : (text + " turns the " + item.Name + " from " + text4 + "'s aim"), flag ? ("He means to " + text3 + ", as " + text4 + " did.") : (text4 + " meant to " + text3 + ". " + text + " means to " + AgendaText(item, agenda2) + "."));
				continue;
			}
			long num = GameMinutesNow();
			bool flag2 = AgendaMet(item, value);
			if (flag2 || num >= value.ReviewAt || value.ReviewAt - num > 43200)
			{
				string text5 = AgendaText(item, value);
				Agenda agenda3 = PickAgenda(item, flag2 ? value : null);
				Agendas[item.Id] = agenda3;
				if (agenda3.Kind != value.Kind || agenda3.Target != value.Target)
				{
					AgendaEvent(item, flag2 ? ("The " + item.Name + " have what they wanted") : (text + " has new plans for the " + item.Name), (flag2 ? (text + " meant to " + text5 + " - done. ") : ("No more trying to " + text5 + ". ")) + "Now he means to " + AgendaText(item, agenda3) + ".");
				}
				else
				{
					SaveWorld();
				}
			}
		}
	}

	private void AgendaEvent(Gang g, string title, string line)
	{
		WorldEvent worldEvent = NewEvent("TURMOIL", GameMinutesNow());
		worldEvent.Gangs.Add(g.Id);
		worldEvent.Title = title;
		worldEvent.Lines.Add(line);
		worldEvent.Heard = true;
		Chronicle.Events.Add(worldEvent);
		GrudgeLog("AGENDA " + title + " - " + line);
		SaveWorld();
	}

	internal double AgendaWarMult(Gang a, Gang b, District d)
	{
		Agenda agenda = AgendaOf(a);
		if (agenda == null)
		{
			return 1.0;
		}
		if (agenda.Kind == "revenge" && agenda.Target == b.Id)
		{
			return 2.0;
		}
		if (agenda.Kind == "expand" && agenda.Target == d.Key)
		{
			return 1.8;
		}
		if (agenda.Kind == "hold")
		{
			return 0.5;
		}
		if (agenda.Kind == "rich")
		{
			return 0.7;
		}
		return 0.85;
	}

	internal double AgendaPairMult(Gang a, Gang b, District d)
	{
		return Math.Max(0.3, Math.Min(2.5, AgendaWarMult(a, b, d) * AgendaWarMult(b, a, d)));
	}

	internal int AgendaLean(Gang a, Gang b, District d)
	{
		return Math.Sign(AgendaWarMult(a, b, d) - AgendaWarMult(b, a, d));
	}

	internal void AgendaClashWon(Gang winner, Gang loser)
	{
		Agenda agenda = AgendaOf(winner);
		if (agenda != null && agenda.Kind == "revenge" && loser != null && agenda.Target == loser.Id)
		{
			agenda.Wins++;
		}
	}

	internal double AgendaAmbushMult(Gang g)
	{
		if (!(AgendaOf(g)?.Kind == "huntyou"))
		{
			return 1.0;
		}
		return 1.4;
	}

	internal bool GrievanceHeld(string a, string b)
	{
		Agenda agenda = AgendaOf(Gangs.ById(a));
		if (agenda == null || !(agenda.Kind == "revenge") || !(agenda.Target == b))
		{
			Agenda agenda2 = AgendaOf(Gangs.ById(b));
			if (agenda2 != null && agenda2.Kind == "revenge")
			{
				return agenda2.Target == a;
			}
			return false;
		}
		return true;
	}

	internal string AgendaLine()
	{
		return "aims: " + string.Join(", ", from g in Gangs.All
			where !g.StoryOnly && !IsDestroyed(g)
			select g.Id + " " + (AgendaText(g) ?? "none (seat open)"));
	}

	private int CrewRoll(NemesisRecord rec)
	{
		Gang gang = Gangs.ById(rec.Gang);
		int num = FollowerCount(rec.Rank) + CrewBonus(gang) + (Quirks.HasSkill(rec, "leader") ? 1 : 0);
		int num3;
		if (rec.Gang != null)
		{
			int num2 = gang?.CrewExtra ?? 0;
			num3 = ((_rng.Next(100) >= Config.GangAlonePercent) ? Math.Max((rec.Rank < 2) ? 1 : 2, Math.Max(1, num) + _rng.Next(-1, 3) + num2) : 0);
		}
		else
		{
			num3 = ((_rng.Next(100) >= Config.LonerAlonePercent) ? Math.Max(1, num + _rng.Next(1, 3)) : 0);
		}
		if (rec.Gang != null && num3 < 2 && NotorietyLevelOf(rec.Gang) >= 4)
		{
			num3 = 2;
			GrudgeLog("CREW " + rec.Name + ": Blood Feud - won't come without his friends");
		}
		if (rec.Gang != null && num3 > 0)
		{
			int num4 = PurseCrewShift(gang);
			if (num4 != 0)
			{
				num3 = Math.Max(1, num3 + num4);
				GrudgeLog("CREW " + rec.Name + ": " + ((num4 < 0) ? "his outfit is broke - one man fewer" : "his outfit is rich - one man more"));
			}
		}
		if (rec.Gang != null && num3 > FieldCap(gang))
		{
			GrudgeLog($"CREW {rec.Name}: his outfit has {MenOf(gang)} men left - {FieldCap(gang)} with him, not {num3}");
			num3 = FieldCap(gang);
		}
		GrudgeLog(string.Format("CREW {0} (rank {1}{2}): {3} (usual {4})", rec.Name, rec.Rank, (rec.Gang != null) ? (", " + rec.Gang) : ", loner", (num3 == 0) ? "alone" : (num3 + " men"), num));
		return num3;
	}

	internal int FollowerCount(int rank)
	{
		int[] array = new int[6] { 0, Config.FollowersRank1, Config.FollowersRank2, Config.FollowersRank3, Config.FollowersRank4, Config.FollowersRank5 };
		return Math.Max(0, array[Math.Max(1, Math.Min(5, rank))]);
	}

	internal void KeepOutfit(Ped ped, NemesisRecord rec)
	{
		if (ped == null || !ped.Exists() || rec == null)
		{
			return;
		}
		try
		{
			if (ped.Model.Hash != (int)rec.ModelHash)
			{
				return;
			}
			if (rec.OutfitHash != 0)
			{
				Function.Call(1802219197667468668uL, ped.Handle, rec.OutfitHash);
				Function.Call(14739335899491263887uL, ped.Handle, false, true, true, true, false);
			}
			else
			{
				uint num = Function.Call<uint>(3483146409871567450uL, new InputArgument[1] { ped.Handle });
				if (num != 0)
				{
					rec.OutfitHash = num;
					SaveRoster();
					GrudgeLog($"OUTFIT {rec.Name}: 0x{num:X8} kept");
				}
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("OUTFIT " + rec.Name + " failed: " + ex.Message);
		}
	}

	internal Ped SpawnNemesisPed(NemesisRecord rec, Vector3 pos, float heading, uint group, out Model model, uint fallback = 424175505u, bool releaseModel = true, bool blockEvents = true, bool factionStyle = true, uint modelOverride = 0u)
	{
		model = new Model((modelOverride != 0) ? modelOverride : rec.ModelHash);
		if (!model.IsValid || !model.IsPed)
		{
			model = new Model(fallback);
		}
		if (!releaseModel && !LoadModelSafe(model, 2000))
		{
			STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)model.Hash);
			return null;
		}
		Ped ped = SpawnPed((PedHash)model.Hash, pos, heading);
		if (releaseModel || ped == null)
		{
			STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)model.Hash);
		}
		if (ped == null)
		{
			return null;
		}
		NoteModel(ped);
		MakeOurs(ped.Handle);
		ArmForHate(ped, rec, drawNow: false);
		ApplyRankStats(ped, rec, fullHeal: true);
		ApplyScars(ped, rec);
		if (modelOverride == 0)
		{
			KeepOutfit(ped, rec);
		}
		if (rec.Limp)
		{
			_bulletImpact.ApplyCondition(ped, CrippleLevel.Limping);
		}
		if (blockEvents)
		{
			ped.BlockPermanentEvents = true;
		}
		if (group != 0)
		{
			ped.RelationshipGroup = group;
		}
		if (factionStyle)
		{
			ApplyFactionStyle(ped, rec.Gang);
			ApplyNotorietyStyle(ped, rec.Gang);
		}
		ApplyMindAi(ped, rec);
		return ped;
	}

	private uint NemesisGroup()
	{
		if (_nemesisGroup == 0)
		{
			_nemesisGroup = World.AddRelationshipGroup("NEMESIS_GROUP");
		}
		return _nemesisGroup;
	}

	private void SpawnFollowers(NemesisRecord rec, Model model, Vector3 leaderPos, float heading)
	{
		int num = _crewOverride ?? CrewRoll(rec);
		List<NemesisRecord> list = new List<NemesisRecord>();
		List<NemesisRecord> list2 = ((num > 0) ? Roster.Where((NemesisRecord n) => Free(n) && Tied(n) && (n.Gang == rec.Gang || n.Gang == null) && !Gangs.Squads(n)).ToList() : new List<NemesisRecord>());
		int num2 = Config.CrewRosterChance + ((list2.Count > 0) ? 25 : 0);
		if (num > 0 && (rec.Gang != null || list2.Count > 0) && _rng.Next(100) < num2)
		{
			List<NemesisRecord> source = Roster.Where((NemesisRecord n) => n.Gang == rec.Gang && rec.Gang != null && n.Rank < rec.Rank && Free(n)).ToList();
			NemesisRecord nemesisRecord = list2.OrderBy((NemesisRecord _) => _rng.Next()).FirstOrDefault() ?? (from _ in source
				where _.BossId == rec.Id
				orderby _rng.Next()
				select _).FirstOrDefault() ?? source.OrderByDescending((NemesisRecord n) => n.BossId != null && BossOf(n)?.BossId == rec.Id).ThenBy((NemesisRecord _) => _rng.Next()).FirstOrDefault();
			if (nemesisRecord != null)
			{
				list.Add(nemesisRecord);
				if (Tied(nemesisRecord))
				{
					GrudgeLog("CREW " + rec.Name + " rides with his " + ((nemesisRecord.KinId == rec.Id) ? nemesisRecord.KinRelation : ((rec.KinId == nemesisRecord.Id) ? Traits.Inverse(rec.KinRelation) : "friend")) + " " + nemesisRecord.Name);
				}
			}
		}
		foreach (NemesisRecord item in list)
		{
			double num3 = _rng.NextDouble() * Math.PI * 2.0;
			float num4 = 2.5f + (float)_rng.NextDouble() * 5f;
			Vector3 p = leaderPos + new Vector3((float)Math.Cos(num3) * num4, (float)Math.Sin(num3) * num4, 0f);
			p = GroundOnSpot(p);
			Ped ped = SpawnNemesisPed(item, p, heading, NemesisGroup(), out var _, (uint)model.Hash);
			if (!(ped == null))
			{
				_followers.Add(ped);
				_worldNemeses[ped.Handle] = item;
				item.TimesAmbushed++;
				item.Touch();
			}
		}
		foreach (uint crewModel in _crewModels)
		{
			STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(crewModel);
		}
		_crewModels.Clear();
		if (list.Count > 0)
		{
			GrudgeLog(string.Format("CREW {0} (rank {1}) rides with {2}; {3} hired gun(s)", rec.Name, rec.Rank, string.Join(", ", list.Select((NemesisRecord c) => c.Name)), num - list.Count));
		}
		for (int num5 = list.Count; num5 < num; num5++)
		{
			double num6 = _rng.NextDouble() * Math.PI * 2.0;
			float num7 = 2.5f + (float)_rng.NextDouble() * 5f;
			Vector3 p2 = leaderPos + new Vector3((float)Math.Cos(num6) * num7, (float)Math.Sin(num6) * num7, 0f);
			p2 = GroundOnSpot(p2);
			Ped ped2 = SpawnPed((PedHash)model.Hash, p2, heading);
			if (!(ped2 == null))
			{
				MakeOurs(ped2.Handle);
				ArmForHate(ped2, rec, drawNow: false);
				ped2.Accuracy = 20;
				ped2.BlockPermanentEvents = true;
				ped2.RelationshipGroup = _nemesisGroup;
				ApplyFactionStyle(ped2, rec.Gang);
				ApplyNotorietyStyle(ped2, rec.Gang, rec.Rank);
				_followers.Add(ped2);
				_followerOf[ped2.Handle] = rec;
			}
		}
		bool Free(NemesisRecord n)
		{
			if (n != rec && n.CanHunt && !n.PresumedDead && !Resting(n) && !_worldNemeses.ContainsValue(n))
			{
				return n != ActiveRecord;
			}
			return false;
		}
		bool Tied(NemesisRecord n)
		{
			if (!(n.KinId == rec.Id) && !(rec.KinId == n.Id))
			{
				List<string> friendIds = rec.FriendIds;
				if (friendIds == null || !friendIds.Contains(n.Id))
				{
					return n.FriendIds?.Contains(rec.Id) ?? false;
				}
			}
			return true;
		}
	}

	private void EnlistHiredGuns()
	{
		if (!Config.HiredGunsJoin)
		{
			return;
		}
		Ped character = Game.Player.Character;
		List<string> list = new List<string>();
		foreach (Ped follower in _followers)
		{
			if (follower == null || !follower.Exists() || _worldNemeses.ContainsKey(follower.Handle) || !_followerOf.TryGetValue(follower.Handle, out var value) || value == null || value.Gang == null || (follower.IsDead && !LooksKnockedOut(follower)) || follower.Position.DistanceTo(character.Position) > 150f)
			{
				continue;
			}
			Gang gang = Gangs.ById(value.Gang);
			if (gang?.Tiers != null)
			{
				var (label, rank, num) = gang.Tiers[gang.Tiers.Length - 1];
				if (Enumerable.Count(Roster, (NemesisRecord n) => n.Gang == gang.Id && n.IsAlive && !n.PresumedDead && n.Rank < ((gang.Tiers.Length > 1) ? gang.Tiers[gang.Tiers.Length - 2].MinRank : 99)) >= num + num / 2)
				{
					break;
				}
				NemesisRecord nemesisRecord = NewRecord((uint)follower.Model.Hash, GetZoneName(character.Position), gang);
				if (_named.TryGetValue(follower.Handle, out var known) && !Roster.Any((NemesisRecord n) => n.Name == known.Name))
				{
					nemesisRecord.Name = known.Name;
					_named.Remove(follower.Handle);
				}
				nemesisRecord.Gang = gang.Id;
				nemesisRecord.Rank = rank;
				nemesisRecord.Origin = GrudgeOrigin.GangMember;
				nemesisRecord.SeedMember = true;
				nemesisRecord.TimesKilledPlayer = 0;
				nemesisRecord.TimesAmbushed = 1;
				nemesisRecord.BossId = value.Id;
				nemesisRecord.KilledPlayerAt = DateTime.Now;
				StartRest(nemesisRecord);
				nemesisRecord.Hate = Math.Max(10, Math.Min(100, value.Hate - 8 + _rng.Next(12)));
				if (follower.IsDead)
				{
					nemesisRecord.TimesKnockedOutByPlayer = 1;
					nemesisRecord.AddHate(10);
				}
				nemesisRecord.Touch();
				Roster.Add(nemesisRecord);
				_worldNemeses[follower.Handle] = nemesisRecord;
				_followerOf.Remove(follower.Handle);
				if (_provoked.TryGetValue(follower.Handle, out var value2))
				{
					value2.Record = nemesisRecord;
					value2.Settled = true;
				}
				ForgetPerson(follower.Handle, nemesisRecord.Name);
				list.Add(nemesisRecord.Name);
				Feed($"JOINED {nemesisRecord.Name}: hired gun -> {gang.Name} {Singular(label)}  (hate {nemesisRecord.Hate}, under {value.Name})", gang.Accent, nemesisRecord);
			}
		}
		if (list.Count != 0)
		{
			SaveRoster();
			GrudgeLog("ENLIST " + string.Join(", ", list));
			GrudgeNotice((list.Count == 1) ? (list[0] + " lived through it. He's riding with the gang now - and he knows your face.") : (string.Join(", ", list) + " lived through it. They ride with the gang now."));
		}
	}

	private unsafe void ReleaseFollowers()
	{
		foreach (Blip followerBlip in _followerBlips)
		{
			if (followerBlip != null && followerBlip.Exists())
			{
				followerBlip.Delete();
			}
		}
		_followerBlips.Clear();
		foreach (Ped follower in _followers)
		{
			if (follower.Exists())
			{
				int handle = follower.Handle;
				ReleaseIfOurs(&handle);
			}
		}
		_followers.Clear();
	}

	private void PruneFollowerMap()
	{
		foreach (int item in _followerOf.Keys.ToList())
		{
			Ped ped = Entity.FromHandle(item) as Ped;
			if (ped == null || !ped.Exists() || ReallyDead(ped))
			{
				_followerOf.Remove(item);
			}
		}
	}

	private static void ArmForHate(Ped ped, NemesisRecord rec, bool drawNow)
	{
		WEAPON.REMOVE_ALL_PED_WEAPONS(ped.Handle, p1: true, p2: true);
		Gang gang = Gangs.Of(rec);
		if (gang != null && gang.UniformKit)
		{
			ped.GiveWeapon(gang.UniformLong, 120, (eWeaponAttachPoint)9, drawNow, !drawNow, a6: false);
			ped.GiveWeapon(gang.UniformSide, 60, (eWeaponAttachPoint)2, equipNow: false, isAmmoLoaded: false, a6: false);
			PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 5, p2: true);
			PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 93, p2: false);
		}
		else
		{
			Loadout.Arm(ped, rec, drawNow);
			bool p = Loadout.BandOf(rec) != Loadout.Band.Gun;
			PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 5, p2: true);
			PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 58, p2: true);
			PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 46, p);
			PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 93, p);
		}
	}

	private void EscalateToGuns()
	{
		NemesisRecord activeRecord = ActiveRecord;
		if (activeRecord != null && Loadout.BandOf(activeRecord) != Loadout.Band.Gun)
		{
			activeRecord.Hate = Math.Max(activeRecord.Hate, Loadout.GunAt(activeRecord) + 3);
			SaveRoster();
			ArmForHate(_activeNemesisPed, activeRecord, drawNow: true);
			TASK.TASK_COMBAT_PED(_activeNemesisPed.Handle, Game.Player.Character.Handle, 0, 16);
			ShowSubtitle(activeRecord.Name + ": \"" + Taunts.EscalateReply(_rng) + "\"");
		}
	}

	private bool ActiveNemesisKnockedOut()
	{
		if ((!_activeNemesisPed.IsIncapacitated && !_activeNemesisPed.IsRagdoll) || Game.GameTime - _activeLastPunchTime >= 10000)
		{
			_activeDownSince = -1;
			return false;
		}
		if (_activeDownSince < 0)
		{
			_activeDownSince = Game.GameTime;
		}
		return Game.GameTime - _activeDownSince >= 3000;
	}

	private static void ApplyRankStats(Ped ped, NemesisRecord rec, bool fullHeal)
	{
		ped.MaxHealth = 300 + rec.Rank * 100 + (Quirks.HasSkill(rec, "tough") ? 60 : 0) + (Quirks.HasSkill(rec, "brawler") ? 40 : 0);
		if (fullHeal)
		{
			ped.Health = ped.MaxHealth;
		}
		ped.Accuracy = Math.Min(92, 25 + rec.Rank * 10 + (Quirks.HasSkill(rec, "marksman") ? 12 : 0));
	}

	private static bool IsArmy(NemesisRecord rec)
	{
		return Gangs.Squads(rec);
	}

	private void RefreshArmyNames()
	{
		List<NemesisRecord> army = Roster.Where((NemesisRecord nemesisRecord) =>
		{
			Gang gang2 = Gangs.Of(nemesisRecord);
			return gang2 != null && gang2.RankInName && nemesisRecord.Name != null;
		}).ToList();
		if (army.Count == 0)
		{
			return;
		}
		HashSet<string> used = new HashSet<string>();
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			string[] array = new string[1] { gang.LoreLeader };
			foreach (string text in array)
			{
				if (!string.IsNullOrWhiteSpace(text) && text.Contains(' '))
				{
					used.Add(text.Substring(text.LastIndexOf(' ') + 1));
				}
			}
		}
		foreach (NemesisRecord n in from x in army
			where x.IsAlive
			orderby x.KilledPlayerAt, x.Id
			select x)
		{
			string text2 = Surname(n);
			if (used.Add(text2))
			{
				continue;
			}
			string text3 = (from l in Gangs.Of(n)?.LastNames ?? NameBank.AmericanLast
				where !used.Contains(l) && !army.Any((NemesisRecord a) => Surname(a) == l)
				orderby Seeds.Stable(n.Id + l)
				select l).FirstOrDefault();
			if (text3 != null)
			{
				n.Name = n.Name.Substring(0, n.Name.Length - text2.Length) + text3;
				used.Add(text3);
				GrudgeLog("NAMING army: two of them were " + text2 + " - this one is " + text3 + " now (kin keep their own surnames)");
			}
		}
		HashSet<string> commanders = new HashSet<string>(from id in Gangs.All.Where((Gang x) => x.RankInName).Select(SuccessorId)
			where id != null
			select id);
		List<NemesisRecord> list = (from nemesisRecord in army
			where nemesisRecord.IsAlive && nemesisRecord.Rank >= 4 && !commanders.Contains(nemesisRecord.Id)
			orderby nemesisRecord.Rank descending, nemesisRecord.Id
			select nemesisRecord).ToList();
		foreach (NemesisRecord item in army)
		{
			int num3 = list.IndexOf(item);
			(string, string) tuple;
			if (item.IsAlive && commanders.Contains(item.Id))
			{
				tuple = ("Col.", "Colonel");
			}
			else if (num3 >= 0)
			{
				tuple = OfficerGrades[Math.Min(num3, OfficerGrades.Length - 1)];
			}
			else if (item.Rank >= 4)
			{
				if (item.Name.StartsWith("Maj."))
				{
					tuple = OfficerGrades[0];
				}
				else
				{
					tuple = (item.Name.StartsWith("Capt.") ? OfficerGrades[1] : OfficerGrades[2]);
				}
			}
			else
			{
				tuple = ((item.Rank < 2) ? ("Pvt.", "Private") : ("Sgt.", "Sergeant"));
			}
			item.Title = "";
			if (item.IsAlive || !item.Name.Contains("."))
			{
				item.Name = tuple.Item1 + " " + Surname(item);
			}
		}
		static string Surname(NemesisRecord nemesisRecord)
		{
			string text4 = nemesisRecord.Name;
			string[] prefixes = Prefixes;
			foreach (string text5 in prefixes)
			{
				if (text4.StartsWith(text5))
				{
					text4 = text4.Substring(text5.Length);
					break;
				}
			}
			if (!text4.Contains(' '))
			{
				return text4;
			}
			return text4.Substring(text4.LastIndexOf(' ') + 1);
		}
	}

	private void SpawnArmyCrew(NemesisRecord rec, Vector3 leaderPos, float heading)
	{
		Gang gang = Gangs.Of(rec) ?? Gangs.Army;
		List<NemesisRecord> source = Roster.Where((NemesisRecord n) => n.Gang == rec.Gang && n != rec && n.CanHunt && !n.PresumedDead && !Resting(n) && !_worldNemeses.ContainsValue(n) && n != ActiveRecord).ToList();
		List<NemesisRecord> list = new List<NemesisRecord>();
		int num;
		if (rec.Rank >= 4)
		{
			num = 3 + _rng.Next(2) + CrewBonus(gang);
		}
		else if (rec.Rank >= 2)
		{
			int num2 = 3 + _rng.Next(2);
			if (_rng.Next(100) < Config.CrewRosterChance)
			{
				list.AddRange((from _ in source
					where _.Rank == 1
					orderby _rng.Next()
					select _).Take(1));
			}
			num = num2 - list.Count + CrewBonus(gang);
		}
		else
		{
			int num3 = 2 + _rng.Next(2);
			NemesisRecord nemesisRecord = null;
			NemesisRecord nemesisRecord2 = null;
			if (_rng.Next(100) < Config.CrewRosterChance)
			{
				nemesisRecord = (from _ in source
					where _.Rank >= 2 && _.Rank <= 3
					orderby _rng.Next()
					select _).FirstOrDefault();
				if (nemesisRecord != null)
				{
					list.Add(nemesisRecord);
				}
				else if ((nemesisRecord2 = (from _ in source
					where _.Rank == 1
					orderby _rng.Next()
					select _).FirstOrDefault()) != null)
				{
					list.Add(nemesisRecord2);
				}
			}
			num = ((nemesisRecord == null) ? 1 : 0) + (num3 - ((nemesisRecord2 != null) ? 1 : 0)) + CrewBonus(gang);
		}
		int num4 = PurseCrewShift(gang);
		if (num4 != 0)
		{
			num = Math.Max(1, num + num4);
			GrudgeLog("CREW " + rec.Name + " (Army): " + ((num4 > 0) ? "the Army is rich - one more trooper" : "the Army is broke - one fewer"));
		}
		int i = 0;
		foreach (NemesisRecord item in list)
		{
			Ped ped = SpawnNemesisPed(item, Slot(), heading, NemesisGroup(), out var _, (uint)((gang.TroopModels.Length != 0) ? gang.TroopModels[0] : ((PedHash)2150064377u)));
			if (!(ped == null))
			{
				_followers.Add(ped);
				_worldNemeses[ped.Handle] = item;
				item.TimesAmbushed++;
				item.Touch();
			}
		}
		for (int num5 = 0; num5 < num; num5++)
		{
			PedHash[] array = ((gang.TroopModels.Length != 0) ? gang.TroopModels : Troopers);
			Ped ped2 = SpawnPed(array[_rng.Next(array.Length)], Slot(), heading);
			if (!(ped2 == null))
			{
				MakeOurs(ped2.Handle);
				ArmTroop(ped2, gang, gang.UniformKit ? new eWeapon?(gang.UniformLong) : ((eWeapon?)null));
				ped2.Accuracy = gang.TroopAccuracy - 5;
				ped2.BlockPermanentEvents = true;
				ped2.RelationshipGroup = _nemesisGroup;
				ApplyFactionStyle(ped2, gang.Id);
				_followers.Add(ped2);
				_followerOf[ped2.Handle] = rec;
			}
		}
		GrudgeLog($"{gang.Id.ToUpperInvariant()} crew for {rec.Name} (rank {rec.Rank}): {list.Count} named, {num} unnamed");
		Vector3 Slot()
		{
			double num6 = (double)heading * Math.PI / 180.0 + Math.PI + ((i % 2 == 0) ? 0.5 : (-0.5));
			float num7 = 2.5f + (float)i * 1.3f;
			i++;
			return Ground(leaderPos + new Vector3((0f - (float)Math.Sin(num6)) * num7, (float)Math.Cos(num6) * num7, 0f));
		}
	}

	private unsafe static int LastDamageBone(int h)
	{
		int result = 0;
		if (!PED.GET_PED_LAST_DAMAGE_BONE(h, &result))
		{
			return 0;
		}
		return result;
	}

	private static bool HeadBone(int b)
	{
		if (b != 21030)
		{
			if (b >= 14283)
			{
				return b <= 14288;
			}
			return false;
		}
		return true;
	}

	private bool InFortWallace(Vector3 p)
	{
		return ZONE._GET_MAP_ZONE_AT_COORDS(p.X, p.Y, p.Z, 11) == 4195085991u;
	}

	private void UpdateGeneral(Ped player)
	{
		float num = player.Position.DistanceTo(FortGate);
		bool mISSION_FLAG = MISC.GET_MISSION_FLAG();
		RefreshFortBlip();
		if (!Chronicle.FortKnown)
		{
			if (_gatesAdded.Count > 0)
			{
				ReleaseFortGates();
			}
			return;
		}
		if (num < 200f && !mISSION_FLAG)
		{
			OpenFortGates();
		}
		else if (_gatesAdded.Count > 0 && ((num > 300f) | mISSION_FLAG))
		{
			ReleaseFortGates();
		}
		if (_general != null || _genEscort.Count > 0)
		{
			if (mISSION_FLAG)
			{
				GrudgeLog("ARMY fort: a mission started - the garrison goes");
				DespawnGeneral();
				return;
			}
			if (_general == null)
			{
				_genEscort.RemoveAll((Ped p) => p == null || !p.Exists());
				if (_genEscort.Count == 0 || num > 320f)
				{
					DespawnGeneral();
				}
				else if (Game.GameTime >= _nextFortHostileCheck)
				{
					_nextFortHostileCheck = Game.GameTime + 1000;
					if (AfterYou(Gangs.Army) || _genEscort.Any((Ped p) => p.Exists() && !p.IsDead && PED.IS_PED_IN_COMBAT(p.Handle, player.Handle)))
					{
						World.SetRelationshipBetweenGroups((eRelationshipType)6, _generalGroup, player.RelationshipGroup);
					}
				}
				return;
			}
			if (!_general.Exists())
			{
				DespawnGeneral();
				return;
			}
			if (_general.IsDead && _generalProtected)
			{
				GrudgeLog("ARMY fort: the story-protected commander read as dead - his seat stays, he's gone from the fort");
				_generalCooldownUntil = Game.GameTime + 3600000;
				DespawnGeneral();
				return;
			}
			if (_general.IsDead)
			{
				bool flag = PED.GET_PED_SOURCE_OF_DEATH(_general.Handle) == player.Handle || PED.GET_PED_SOURCE_OF_DEATH(_general.Handle) == 0;
				string text = _generalRec?.FullName ?? Gangs.Army.LeaderName;
				if (_generalRec == null && SeatOf(Gangs.Army)?.Fallen == null)
				{
					Fall(Gangs.Army, text, "killed at Fort Wallace", flag, null, "cs_colfavours");
				}
				DeathNotice(text + " is dead at Fort Wallace. The Army will never forget your name.");
				if (flag)
				{
					Chronicle.FortCleared = true;
					Chronicle.FortClearedAt = GameMinutesNow();
					SaveWorld();
					GrudgeLog("ARMY fort: hideout cleared - the commander is dead");
					Feed("HIDEOUT Fort Wallace cleared - its commander is dead", Theme.Gold);
					GrudgeNotice("Fort Wallace hideout cleared.");
					RefreshFortBlip();
				}
				_generalCooldownUntil = Game.GameTime + 3600000;
				DespawnGeneral();
				return;
			}
			if (!_generalProtected && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(_general.Handle, player.Handle, p2: true, p3: true))
			{
				int num2 = LastDamageBone(_general.Handle);
				bool num3 = _general.IsRagdoll || _general.IsIncapacitated || PED.IS_PED_HOGTIED(_general.Handle) || PED.IS_PED_FATALLY_INJURED(_general.Handle);
				ENTITY.CLEAR_ENTITY_LAST_DAMAGE_ENTITY(_general.Handle);
				string text2 = null;
				if (num3 && GunMelee.PlayerFiredRecently)
				{
					text2 = "executed on the ground";
				}
				else if (HeadBone(num2) && ++_generalHeadshots >= 2)
				{
					text2 = "a second shot to the head";
				}
				else if (HeadBone(num2))
				{
					_general.Health = Math.Min(_general.Health, _general.MaxHealth / 3);
					GrudgeLog($"ARMY fort: the commander took a shot to the head - health {_general.Health}");
				}
				if (text2 != null && !_general.IsDead)
				{
					GrudgeLog("ARMY fort: the commander - " + text2);
					Crumbs.Native("Army commander killed");
					PED.APPLY_DAMAGE_TO_PED(_general.Handle, 5000, 0, (num2 != 0) ? num2 : 21030, player.Handle);
					if (!_general.IsDead)
					{
						_general.Health = 0;
					}
				}
			}
			if (_generalProtected && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(_general.Handle, player.Handle, p2: true, p3: true))
			{
				ENTITY.CLEAR_ENTITY_LAST_DAMAGE_ENTITY(_general.Handle);
				if (!_general.IsRagdoll)
				{
					PED.SET_PED_TO_RAGDOLL(_general.Handle, 3000, 4000, 0, p4: false, p5: false, "");
				}
				if (Game.GameTime - _generalHitLogged > 10000)
				{
					_generalHitLogged = Game.GameTime;
					GrudgeLog("ARMY fort: the commander was hit - story-protected, he goes down but lives");
				}
			}
			if (Game.GameTime >= _nextFortHostileCheck)
			{
				_nextFortHostileCheck = Game.GameTime + 1000;
				if (AfterYou(Gangs.Army) || _genEscort.Concat(new Ped[1] { _general }).Any((Ped p) => p != null && p.Exists() && !p.IsDead && PED.IS_PED_IN_COMBAT(p.Handle, player.Handle)))
				{
					World.SetRelationshipBetweenGroups((eRelationshipType)6, _generalGroup, player.RelationshipGroup);
				}
			}
			if ((num > 320f) | mISSION_FLAG)
			{
				DespawnGeneral();
			}
		}
		else if (Game.GameTime >= _nextGeneralCheck)
		{
			_nextGeneralCheck = Game.GameTime + 3000;
			if (!((!Config.ArmyGeneral || Game.GameTime < _generalCooldownUntil) | mISSION_FLAG) && !(num > 180f) && !Chronicle.FortCleared && PLAYER.IS_PLAYER_CONTROL_ON(Game.Player.Handle) && NoSpawnReason(player, place: true) == null && !IsDestroyed(Gangs.Army))
			{
				SpawnFortHQ(player);
			}
		}
	}

	private void OpenFortGates()
	{
		if (Game.GameTime < _nextGateOrder && _gatesAdded.Count == FortGateDoors.Length)
		{
			return;
		}
		_nextGateOrder = Game.GameTime + 5000;
		uint[] fortGateDoors = FortGateDoors;
		foreach (uint num in fortGateDoors)
		{
			try
			{
				if (!_gatesAdded.Contains(num))
				{
					if (!Function.Call<bool>(13930693845672184001uL, new InputArgument[1] { num }))
					{
						Crumbs.Native("Army door");
						Function.Call(15677639426206622342uL, num, true, true, false, 0, 0, false);
						_gatesAdded.Add(num);
						_gatesWeAdded.Add(num);
					}
					else
					{
						_gatesAdded.Add(num);
						Crumbs.Native("Army door");
						try
						{
							_gateStateWas[num] = OBJECT.DOOR_SYSTEM_GET_DOOR_STATE(num);
						}
						catch
						{
						}
					}
					GrudgeLog($"ARMY fort gate {num}: in the door system, unlocking and opening");
				}
				Crumbs.Native("Army door");
				Function.Call(7758457796463198035uL, num, 0);
				Crumbs.Native("Army door");
				Function.Call(13179498064365429932uL, num, (num == FortGateDoors[0]) ? 1f : (-1f), true);
			}
			catch (Exception ex)
			{
				GrudgeLog("ARMY fort gate failed: " + ex.Message);
			}
		}
	}

	private void ReleaseFortGates()
	{
		if (_gatesAdded.Count == 0)
		{
			return;
		}
		foreach (uint item in _gatesAdded)
		{
			try
			{
				Crumbs.Native("Army door");
				int value;
				if (_gatesWeAdded.Contains(item))
				{
					Function.Call(5065861373067882468uL, item);
				}
				else if (_gateStateWas.TryGetValue(item, out value))
				{
					Function.Call(7758457796463198035uL, item, value);
				}
			}
			catch
			{
			}
		}
		_gatesAdded.Clear();
		_gatesWeAdded.Clear();
		_gateStateWas.Clear();
		GrudgeLog("ARMY fort gates handed back to the game");
	}

	private void SpawnFortHQ(Ped player)
	{
		_generalCooldownUntil = Game.GameTime + 600000;
		if (_generalGroup == 0)
		{
			_generalGroup = World.AddRelationshipGroup("NEMESIS_GENERAL");
		}
		LeaderSeat leaderSeat = SeatOf(Gangs.Army);
		bool flag = leaderSeat == null || leaderSeat.Fallen == null;
		_generalRec = (flag ? null : FindRecord(leaderSeat.Successor));
		if (!flag && _generalRec == null)
		{
			GrudgeLog("ARMY fort: the commander's seat is empty - the garrison holds without him");
		}
		_generalProtected = false;
		_generalHeadshots = 0;
		uint num = (flag ? MISC.GET_HASH_KEY("cs_colfavours") : (_generalRec?.ModelHash ?? 722236839));
		if (!STREAMING.IS_MODEL_IN_CDIMAGE(num))
		{
			num = 722236839u;
		}
		Model m = new Model((int)num);
		if (!LoadModelSafe(m, 3000))
		{
			STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(num);
			return;
		}
		bool flag2 = AfterYou(Gangs.Army);
		if (flag || _generalRec != null)
		{
			Vector3 vector = FortSpot(player, FortCommanderSpot, 25f, out var heading, out var point);
			_general = SpawnPed((PedHash)num, vector, heading);
			if (_general != null)
			{
				MakeOurs(_general.Handle);
				_general.RelationshipGroup = _generalGroup;
				_general.BlockPermanentEvents = false;
				_general.GiveWeapon((eWeapon)2075992054u, 60, (eWeaponAttachPoint)2, equipNow: true, isAmmoLoaded: false, a6: false);
				_general.Accuracy = 55;
				_general.MaxHealth = 1200;
				_general.Health = 1200;
				if (_generalProtected)
				{
					ENTITY.SET_ENTITY_INVINCIBLE(_general.Handle, p1: true);
					Kids.StoryProtected.Add(_general.Handle);
				}
				if (_generalRec != null)
				{
					_worldNemeses[_general.Handle] = _generalRec;
					ApplyScars(_general, _generalRec);
				}
				if (point != 0)
				{
					SitAt(_general, point, vector, heading);
				}
				else
				{
					TASK.TASK_START_SCENARIO_IN_PLACE_HASH(_general.Handle, MISC.GET_HASH_KEY("WORLD_HUMAN_GUARD_LAZY"), -1, p3: true, 0u, -1f, p6: false);
				}
				GrudgeLog(string.Format("ARMY fort: the commander at {0:0},{1:0},{2:0} ({3})", vector.X, vector.Y, vector.Z, (point != 0) ? "a scenario point" : "his spot"));
				string text = _generalRec?.FullName ?? Gangs.Army.LeaderName;
				Crumbs.Native("Army blip add (V2)");
				_genBlip = _general.AddBlip(flag2 ? ((BlipType)831283580u) : ((BlipType)2545348716u));
				if (_genBlip != null)
				{
					Function.Call(11290983183885202434uL, _genBlip.Handle, new InputArgument(UiDraw.VarString(text)));
				}
			}
		}
		STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(num);
		Vector3[] fortGuardSpots = FortGuardSpots;
		for (int i = 0; i < fortGuardSpots.Length; i++)
		{
			Vector3 vector2 = fortGuardSpots[i];
			bool flag3 = vector2.DistanceTo(FortGate) < 12f;
			int point2 = 0;
			Vector3 vector3;
			float heading2;
			if (flag3)
			{
				vector3 = GroundAbove(vector2);
				heading2 = HeadingTo(vector2, FortGate) + 180f;
			}
			else
			{
				vector3 = FortSpot(player, vector2, 18f, out heading2, out point2);
			}
			Ped ped = SpawnPed(Troopers[_rng.Next(Troopers.Length)], vector3, heading2);
			if (!(ped == null))
			{
				MakeOurs(ped.Handle);
				ped.GiveWeapon((eWeapon)4111948705u, 100, (eWeaponAttachPoint)9, equipNow: true, isAmmoLoaded: false, a6: false);
				ped.RelationshipGroup = _generalGroup;
				ped.BlockPermanentEvents = false;
				ApplyFactionStyle(ped, Gangs.Army.Id);
				if (point2 != 0)
				{
					SitAt(ped, point2, vector3, heading2);
				}
				else
				{
					TASK.TASK_START_SCENARIO_IN_PLACE_HASH(ped.Handle, MISC.GET_HASH_KEY((_rng.Next(2) == 0) ? "WORLD_HUMAN_GUARD_SCOUT" : "WORLD_HUMAN_GUARD_LAZY"), -1, p3: true, 0u, -1f, p6: false);
				}
				_genEscort.Add(ped);
			}
		}
		World.SetRelationshipBetweenGroups(flag2 ? ((eRelationshipType)6) : ((eRelationshipType)3), _generalGroup, player.RelationshipGroup);
		if (flag2)
		{
			foreach (Ped item in _genEscort)
			{
				TASK.TASK_COMBAT_PED(item.Handle, player.Handle, 0, 16);
			}
		}
		GrudgeLog(string.Format("ARMY fort: {0} + {1} soldiers at Fort Wallace, hostile={2}, story-protected={3}", (!(_general != null)) ? "no commander" : (_generalRec?.Name ?? Gangs.Army.LeaderName), _genEscort.Count, flag2, _generalProtected));
		if (flag2)
		{
			GrudgeNotice("Fort Wallace is up in arms - they know who you are.");
		}
	}

	private bool KnowsFort(NemesisRecord rec)
	{
		(string, int, int)[] tiers = Gangs.Army.Tiers;
		int num = ((tiers != null && tiers.Length != 0) ? tiers[0].Item2 : 4);
		if (rec != null && rec.Gang == Gangs.Army.Id)
		{
			return rec.Rank >= num;
		}
		return false;
	}

