	private void CheckGameEventNear(Ped player)
	{
		if (Game.GameTime < _nextGameEventCheck)
		{
			return;
		}
		_nextGameEventCheck = Game.GameTime + 500;
		Vector3 position = player.Position;
		foreach (var (ped, vector) in PedSnapshot(player))
		{
			if (!(ped == null) && !(vector.DistanceTo(position) > 100f) && GameEventPed(ped) && !ped.IsDead)
			{
				int handle = ped.Handle;
				if (!_gameEventFirstSeen.TryGetValue(handle, out var value))
				{
					value = (_gameEventFirstSeen[handle] = Game.GameTime);
					GrudgeLog($"GAMEEVENT {NameOf(handle)} ({Models.Name(ped)}) {vector.DistanceTo(position):0} m off - no encounters of ours, and your shots aren't taken as an attack, while he's near (5 min at most)");
				}
				if (Game.GameTime - value <= 300000)
				{
					_gameEventNearAt = Game.GameTime;
					_gameEventWho = NameOf(handle);
				}
			}
		}
		if (_gameEventFirstSeen.Count <= 50)
		{
			return;
		}
		foreach (int item in (from kv in _gameEventFirstSeen
			where Game.GameTime - kv.Value > 600000
			select kv.Key).ToList())
		{
			_gameEventFirstSeen.Remove(item);
		}
	}

	internal string NoSpawnReason(Ped player, bool place = false)
	{
		try
		{
			CheckGameEventNear(player);
		}
		catch (Exception ex)
		{
			GrudgeLog("GAMEEVENT check failed: " + ex.Message);
		}
		if (!Config.CalmEnabled)
		{
			return null;
		}
		if (Game.GameTime >= _nextCalmCheck)
		{
			_nextCalmCheck = Game.GameTime + 500;
			string text = null;
			if (MISC.GET_MISSION_FLAG())
			{
				text = "on a mission";
			}
			else
			{
				string text2 = StoryScene(player);
				if (text2 != null)
				{
					text = text2;
				}
				else if (Game.GameTime < _graceUntil)
				{
					text = $"settling in ({(_graceUntil - Game.GameTime) / 1000}s, {_graceWhy})";
				}
				else if (PED.IS_PED_IN_ANY_TRAIN(player.Handle))
				{
					text = "on a train";
				}
				else if (AtGangCamp(player))
				{
					text = "at the gang's camp";
				}
				else
				{
					CampSite campSite = Camps.RetiredNear(player.Position, 300f);
					if (campSite != null)
					{
						text = "on " + campSite.Name + " (the game puts your guns away there)";
					}
					else
					{
						string text3 = StoryBansWeapons(player.Position);
						if (text3 != null)
						{
							text = text3;
						}
					}
				}
			}
			_calmPlaceReason = text;
			if (text == null)
			{
				if (INTERIOR.GET_INTERIOR_FROM_ENTITY(player.Handle) != 0)
				{
					text = "indoors";
				}
				else if (PED.IS_PED_USING_ANY_SCENARIO(player.Handle))
				{
					text = "resting (sitting / at a fire)";
				}
				else if (Config.CalmWhileWanted && LawAfterYou())
				{
					text = "the law is after you";
				}
				else if (Game.GameTime - _gameEventNearAt < 3000)
				{
					text = "one of the game's own events nearby (" + _gameEventWho + ")";
				}
			}
			_calmReason = text;
		}
		if (!place)
		{
			return _calmReason;
		}
		return _calmPlaceReason;
	}

	internal void NoteQuietForScene(Ped player, bool quiet)
	{
		try
		{
			if (quiet)
			{
				_sceneCandidates.Clear();
				_sceneQuietAt = Game.GameTime;
				_sceneQuietPos = player.Position;
				{
					foreach (var (ped, vector) in PedSnapshot(player))
					{
						if (!(ped == null) && ped.Exists() && ped.Handle != player.Handle && !(vector.DistanceTo(player.Position) > 30f) && Models.Name(ped).StartsWith("cs_", StringComparison.OrdinalIgnoreCase) && ENTITY.IS_ENTITY_A_MISSION_ENTITY(ped.Handle) && !BelongsToUs(ped.Handle) && !IsCompanion(ped.Handle))
						{
							_sceneCandidates.Add(ped.Handle);
						}
					}
					return;
				}
			}
			if (_sceneQuietAt >= 0)
			{
				int num = Game.GameTime - _sceneQuietAt;
				_sceneQuietAt = -1;
				if (num >= 6000 && _sceneCandidates.Count != 0 && !(player.Position.DistanceTo(_sceneQuietPos) > 100f))
				{
					_scenePeds = _sceneCandidates.ToList();
					Ped ped2 = Entity.FromHandle(_scenePeds[0]) as Ped;
					ref string sceneWho = ref _sceneWho;
					string text;
					if (ped2 != null)
					{
						text = (_named.TryGetValue(ped2.Handle, out var value) ? value.Name : Models.Name(ped2));
					}
					else
					{
						text = "a story character";
					}
					sceneWho = text;
					_sceneUntil = Game.GameTime + 900000;
					GrudgeLog($"CALM a story scene with {_sceneWho} ({num / 1000} s cutscene, no mission flag - a stranger mission?) - nothing new comes while he's about");
				}
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("CALM story scene check failed: " + ex.Message);
		}
	}

	internal bool InStoryScene(Vector3 at)
	{
		if (_scenePeds.Count == 0 || Game.GameTime >= _sceneUntil)
		{
			return false;
		}
		if (Game.GameTime - _scenePosAt > 500)
		{
			_scenePosAt = Game.GameTime;
			_scenePos.Clear();
			foreach (int scenePed in _scenePeds)
			{
				Entity entity = Entity.FromHandle(scenePed);
				if ((object)entity != null && entity.Exists() && !entity.IsDead)
				{
					_scenePos.Add(entity.Position);
				}
			}
		}
		return _scenePos.Any((Vector3 s) => s.DistanceTo(at) < 150f);
	}

	private string StoryScene(Ped player)
	{
		if (_scenePeds.Count == 0)
		{
			return null;
		}
		if (Game.GameTime >= _sceneUntil || !_scenePeds.Any((int h) =>
		{
			Entity entity = Entity.FromHandle(h);
			return entity != null && entity.Exists() && !entity.IsDead && entity.Position.DistanceTo(player.Position) < 200f;
		}))
		{
			GrudgeLog("CALM the story scene with " + _sceneWho + " is over");
			_scenePeds.Clear();
			return null;
		}
		return "a story scene (" + _sceneWho + ")";
	}

	internal string CalmDebugLine(Ped player)
	{
		string text = NoSpawnReason(player);
		if (text != null)
		{
			return $"HELD: {text}  ({GangCamps.Count} gang camps known)";
		}
		return $"calm: nothing holding them back ({GangCamps.Count} gang camps known)";
	}

	private static DoorsContent BuiltInDoors()
	{
		try
		{
			using Stream stream = typeof(NemesisMod).Assembly.GetManifestResourceStream("doors.json");
			using StreamReader streamReader = new StreamReader(stream);
			return JsonConvert.DeserializeObject<DoorsContent>(streamReader.ReadToEnd()) ?? new DoorsContent();
		}
		catch
		{
			return new DoorsContent();
		}
	}

	private void LoadDoors()
	{
		int num = LoadOrWrite(Path.Combine(ContentDir, "doors.json"), BuiltInDoors, (DoorsContent c) =>
		{
			if (c?.Doors == null || c.Doors.Count == 0)
			{
				return 0;
			}
			_doors = c.Doors.Where((DoorRow d) => d.Hash != 0).ToList();
			return _doors.Count;
		});
		GrudgeLog($"CONTENT doors.json: {num} doors");
	}

	private void UnlockHideout(CampSite site)
	{
		if (site == null || !site.Hideout || site.Imap != 0 || _campDoors.ContainsKey(site.Id) || MISC.GET_MISSION_FLAG())
		{
			return;
		}
		List<DoorWas> list = new List<DoorWas>();
		foreach (DoorRow door in _doors)
		{
			float num = door.X - site.X;
			float num2 = door.Y - site.Y;
			if ((float)Math.Sqrt(num * num + num2 * num2) > ((door.Model != null && door.Model.IndexOf("gate", StringComparison.OrdinalIgnoreCase) >= 0) ? 90f : 45f))
			{
				continue;
			}
			try
			{
				DoorWas doorWas = new DoorWas
				{
					Hash = door.Hash
				};
				if (!Function.Call<bool>(13930693845672184001uL, new InputArgument[1] { door.Hash }))
				{
					Crumbs.Native("CampDoors door add");
					Function.Call(15677639426206622342uL, door.Hash, true, true, false, 0, 0, false);
					doorWas.WeAdded = true;
				}
				else
				{
					doorWas.State = Function.Call<int>(1588259609567639992uL, new InputArgument[1] { door.Hash });
					Crumbs.Native("CampDoors door owner");
					Function.Call(10977356922902395972uL, door.Hash);
				}
				Crumbs.Native("CampDoors door unlock");
				Function.Call(7758457796463198035uL, door.Hash, 0);
				list.Add(doorWas);
			}
			catch (Exception ex)
			{
				GrudgeLog($"CAMPDOORS {site.Label}: door {door.Hash} failed - {ex.Message}");
			}
		}
		_campDoors[site.Id] = list;
		if (list.Count > 0)
		{
			GrudgeLog($"CAMPDOORS {site.Label}: {list.Count} doors / gates unlocked ({Enumerable.Count(list, (DoorWas x) => x.WeAdded)} registered by us)");
		}
	}

	private void RefreshHideoutDoors(Ped player)
	{
		if (Game.GameTime < _nextDoorRefresh || _campDoors.Count == 0)
		{
			return;
		}
		_nextDoorRefresh = Game.GameTime + 3000;
		if (MISC.GET_MISSION_FLAG())
		{
			return;
		}
		foreach (KeyValuePair<string, List<DoorWas>> campDoor in _campDoors)
		{
			CampSite campSite = Camps.ById(campDoor.Key);
			if (campSite == null || new Vector3(campSite.X - player.Position.X, campSite.Y - player.Position.Y, 0f).Length() > 120f)
			{
				continue;
			}
			int num = 0;
			foreach (DoorWas item in campDoor.Value)
			{
				try
				{
					if (Function.Call<int>(1588259609567639992uL, new InputArgument[1] { item.Hash }) != 0)
					{
						Crumbs.Native("CampDoors door re-unlock");
						Function.Call(7758457796463198035uL, item.Hash, 0);
						num++;
					}
				}
				catch
				{
				}
			}
			if (num > 0)
			{
				GrudgeLog($"CAMPDOORS {campSite.Label}: {num} doors had locked again - unlocked");
			}
		}
	}

	private void RelockHideout(CampSite site, bool missionStart = false)
	{
		if (site == null || !_campDoors.TryGetValue(site.Id, out var value))
		{
			return;
		}
		_campDoors.Remove(site.Id);
		bool flag = false;
		try
		{
			flag = CAM.IS_SCREEN_FADED_OUT() || (MISC.GET_MISSION_FLAG() && !missionStart);
		}
		catch
		{
		}
		if (flag)
		{
			return;
		}
		foreach (DoorWas item in value)
		{
			try
			{
				Crumbs.Native("CampDoors door restore");
				if (item.WeAdded)
				{
					Function.Call(5065861373067882468uL, item.Hash);
				}
				else
				{
					Function.Call(7758457796463198035uL, item.Hash, item.State);
				}
			}
			catch
			{
			}
		}
		GrudgeLog($"CAMPDOORS {site.Label}: {value.Count} doors put back");
	}

	internal void RelockAllHideouts()
	{
		RelockAllHideouts(missionStart: false);
	}

	internal void RelockAllHideouts(bool missionStart)
	{
		foreach (string item in _campDoors.Keys.ToList())
		{
			RelockHideout(Camps.ById(item), missionStart);
		}
	}

	private unsafe void FindHideoutPoints(CampSite site)
	{
		List<(Vector3, float, int)> list = new List<(Vector3, float, int)>();
		_hideoutPoints[site.Id] = list;
		ulong* ptr = stackalloc ulong[272];
		for (int i = 0; i < 272; i++)
		{
			ptr[i] = 0uL;
		}
		*ptr = 256uL;
		Crumbs.Native("CampDoors scenario points");
		int num = TASK.GET_SCENARIO_POINTS_IN_AREA(site.X, site.Y, site.Z, _indoorOnly ? 55f : 85f, ptr, 256);
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		_hideoutIndoorProbe.Remove(site.Id);
		HashSet<int> hashSet = new HashSet<int>();
		for (int j = 1; j <= Math.Min(num + 1, 256); j++)
		{
			int num5 = (int)(ptr[j] & 0xFFFFFFFFu);
			if (num5 == 0 || !hashSet.Add(num5) || !TASK.DOES_SCENARIO_POINT_EXIST(num5))
			{
				continue;
			}
			if (TASK._GET_PED_USING_SCENARIO_POINT(num5) != 0)
			{
				num4++;
				continue;
			}
			Vector3 c = TASK._GET_SCENARIO_POINT_COORDS(num5, p1: true);
			int num6 = INTERIOR.GET_INTERIOR_AT_COORDS(c.X, c.Y, c.Z);
			if (num6 != 0)
			{
				if (!INTERIOR.IS_INTERIOR_READY(num6))
				{
					num3++;
					if (!_hideoutIndoorProbe.ContainsKey(site.Id))
					{
						_hideoutIndoorProbe[site.Id] = c;
					}
					continue;
				}
				_ = _indoorOnly;
				num2++;
			}
			if ((!_indoorOnly || (num6 != 0 && Enclosed(c))) && !list.Any(((Vector3, float, int) x) => x.Item1.DistanceTo(c) < 3f))
			{
				list.Add((c, TASK._GET_SCENARIO_POINT_HEADING(num5, p1: true), num5));
			}
		}
		List<(Vector3, float, int)> list2 = list.ToList();
		List<(Vector3, float, int)> order = new List<(Vector3, float, int)>();
		if (list2.Count > 0)
		{
			int index = _rng.Next(list2.Count);
			order.Add(list2[index]);
			list2.RemoveAt(index);
		}
		while (list2.Count > 0)
		{
			List<(int, float)> list3 = (from t in list2.Select(((Vector3, float, int) x, int k) => (k: k, d: order.Min(((Vector3, float, int) o) => o.Item1.DistanceTo(x.Item1))))
				orderby t.d descending
				select t).Take(3).ToList();
			int item = list3[_rng.Next(list3.Count)].Item1;
			order.Add(list2[item]);
			list2.RemoveAt(item);
		}
		list.Clear();
		list.AddRange(order);
		GrudgeLog($"CAMP {site.Label}: {list.Count} places for its men ({num2} inside, {num3} inside but not loaded yet, {num4} in use) of {num} points");
	}

	internal int HoldBackForIndoors(CampSite site, int hired)
	{
		if (!_hideoutIndoorProbe.ContainsKey(site.Id))
		{
			return 0;
		}
		return Math.Min(hired, Math.Max(2, (hired + 1) / 2));
	}

	private void CheckHideoutIndoors(LiveCamp lc)
	{
		try
		{
			RefreshHideoutDoors(Game.Player.Character);
		}
		catch
		{
		}
		if (lc.IndoorPending <= 0 || lc.Engaged || !_hideoutIndoorProbe.TryGetValue(lc.Site.Id, out var value))
		{
			return;
		}
		int num = INTERIOR.GET_INTERIOR_AT_COORDS(value.X, value.Y, value.Z);
		if (num == 0 || !INTERIOR.IS_INTERIOR_READY(num))
		{
			return;
		}
		_indoorOnly = true;
		try
		{
			FindHideoutPoints(lc.Site);
		}
		finally
		{
			_indoorOnly = false;
		}
		int indoorPending = lc.IndoorPending;
		lc.IndoorPending = 0;
		int num2 = 0;
		int num3 = ((indoorPending >= 3) ? (1 + _rng.Next(2)) : ((indoorPending == 2) ? 1 : 0));
		int num4 = 0;
		for (int i = 0; i < indoorPending; i++)
		{
			if (!_hideoutPoints.TryGetValue(lc.Site.Id, out List<(Vector3, float, int)> value2) || value2.Count == 0)
			{
				break;
			}
			_forceIndoor = true;
			int count = lc.Peds.Count;
			try
			{
				SpawnCampPed(lc, lc.Boss, SitePos(lc.Site), lc.Peds.Count, named: false);
			}
			finally
			{
				_forceIndoor = false;
			}
			bool flag = lc.Peds.Count > count;
			if (flag)
			{
				num2++;
			}
			if (!flag || num4 >= num3)
			{
				continue;
			}
			Ped w = lc.Peds[lc.Peds.Count - 1];
			if ((object)w != null && w.Exists())
			{
				_seating.RemoveAll((Seating s) => s.Ped != null && s.Ped.Handle == w.Handle);
				Vector3 position = w.Position;
				TASK.CLEAR_PED_TASKS(w.Handle, p1: true, p2: true);
				Function.Call(16164602603745899285uL, w.Handle, position.X, position.Y, position.Z, 6f, 2f, 8f, 0);
				num4++;
			}
		}
		GrudgeLog($"CAMP {lc.Site.Label}: the house is loaded - {num2} of his men inside ({num4} walking the rooms)");
	}

	private static bool Enclosed(Vector3 c)
	{
		Vector3 vector = c + new Vector3(0f, 0f, 1.2f);
		if (!Ray.Blocked(vector, vector + new Vector3(0f, 0f, 5f), 17, 0))
		{
			return false;
		}
		int num = 0;
		Vector3[] array = new Vector3[4]
		{
			new Vector3(8f, 0f, 0f),
			new Vector3(-8f, 0f, 0f),
			new Vector3(0f, 8f, 0f),
			new Vector3(0f, -8f, 0f)
		};
		foreach (Vector3 vector2 in array)
		{
			if (Ray.Blocked(vector, vector + vector2, 17, 0))
			{
				num++;
			}
		}
		return num >= 3;
	}

	private (Vector3 pos, float heading, int pt)? NextHideoutPlace(CampSite site)
	{
		if (!_hideoutPoints.TryGetValue(site.Id, out List<(Vector3, float, int)> value) || value.Count == 0)
		{
			return null;
		}
		(Vector3, float, int) value2 = value[0];
		value.RemoveAt(0);
		return value2;
	}

	private void UpdateCampObjectives(Ped player)
	{
		if (Game.GameTime < _nextObjectiveCheck)
		{
			return;
		}
		_nextObjectiveCheck = Game.GameTime + 1000;
		foreach (string siteId in (from s in _liveSupplies.Values
			where !s.Town
			select s.SiteId).Concat(_liveTreasuries.Keys).Distinct().ToList())
		{
			if (!_liveCamps.TryGetValue(siteId, out var value))
			{
				continue;
			}
			int count = value.Peds.Count;
			int num = Enumerable.Count(value.Peds, (Ped p) => p.Exists() && !p.IsDead && !LooksKnockedOut(p));
			if (count <= 0 || (num != 0 && (!value.Engaged || num > Math.Max(1, count / 4))))
			{
				continue;
			}
			_liveSupplies.TryGetValue(siteId, out var value2);
			_liveTreasuries.TryGetValue(siteId, out var value3);
			Gang gang = value2?.Gang ?? value3?.Gang;
			if (gang == null)
			{
				continue;
			}
			List<(string, Vector3, string)> list = new List<(string, Vector3, string)>();
			List<(string, Ped)> list2 = new List<(string, Ped)>();
			if (value2 != null)
			{
				foreach (SupplyCrate item2 in value2.Crates.Where((SupplyCrate c) => !c.Gone))
				{
					list.Add(($"crate{item2.At.X:0}{item2.At.Y:0}", item2.At, item2.Big ? "Their stores - dynamite" : "Their crates"));
				}
				if (value2.Wagon != null && value2.Wagon.Exists() && !value2.WagonCounted)
				{
					list.Add(("wagon", value2.Wagon.Position, "Their supply wagon"));
				}
				foreach (var horse in value2.Horses)
				{
					Ped item = horse.horse;
					if (item != null && item.Exists() && !item.IsDead && !value2.HorsesCounted.Contains(item.Handle))
					{
						list2.Add(($"horse{item.Handle}", item));
					}
				}
			}
			if (value3 != null)
			{
				foreach (Strongbox item3 in value3.Boxes.Where((Strongbox b) => !b.Opened && b.Obj != 0))
				{
					list.Add(($"box{item3.At.X:0}{item3.At.Y:0}", item3.At, "Strongbox"));
				}
			}
			int num2 = list.Count + list2.Count;
			if (!_objShown.Contains(siteId))
			{
				_objShown.Add(siteId);
				if (num2 == 0)
				{
					continue;
				}
				string text = ShortOutfit(gang);
				text += (text.EndsWith("s") ? "'" : "'s");
				string text2 = ((value3 != null) ? ("The " + text + " treasury is yours for the taking - rob the strongboxes.") : ("The " + text + " supply camp is broken - blow up their stores, shoot up their crates, take or wreck the wagon, run off their horses."));
				ShowNotification(text2);
				GrudgeNotice(text2);
				GrudgeLog($"OBJECTIVE {siteId}: {text2} ({num2} targets)");
			}
			if (!_objBlips.TryGetValue(siteId, out var value4))
			{
				value4 = (_objBlips[siteId] = new Dictionary<string, int>());
			}
			HashSet<string> want = new HashSet<string>(list.Select(((string key, Vector3 at, string name) c) => c.key));
			foreach (string item4 in value4.Keys.Where((string k) => !want.Contains(k)).ToList())
			{
				RemoveObjBlip(value4, item4);
			}
			foreach (var (text3, vector, text4) in list)
			{
				if (value4.ContainsKey(text3))
				{
					if (text3 == "wagon")
					{
						MAP.SET_BLIP_COORDS(value4[text3], vector.X, vector.Y, vector.Z);
					}
					continue;
				}
				Crumbs.Native("objective blip");
				int num3 = MAP.BLIP_ADD_FOR_COORDS(Joaat.Of("BLIP_STYLE_OBJECTIVE"), vector.X, vector.Y, vector.Z);
				Function.Call(11290983183885202434uL, num3, new InputArgument(UiDraw.ForeverVarString(text4)));
				value4[text3] = num3;
			}
			HashSet<string> horseKeys = new HashSet<string>(list2.Select(((string key, Ped horse) h) => siteId + h.key));
			foreach (string item5 in _objHorseBlips.Keys.Where((string k) => k.StartsWith(siteId + "horse") && !horseKeys.Contains(k)).ToList())
			{
				Blip blip = _objHorseBlips[item5];
				if (blip != null && blip.Exists())
				{
					blip.Delete();
				}
				_objHorseBlips.Remove(item5);
			}
			foreach (var (text5, ped) in list2)
			{
				if (!_objHorseBlips.ContainsKey(siteId + text5))
				{
					Crumbs.Native("objective horse blip");
					Blip blip2 = ped.AddBlip((BlipType)Joaat.Of("BLIP_STYLE_OBJECTIVE"));
					if (blip2 != null)
					{
						Function.Call(11290983183885202434uL, blip2.Handle, new InputArgument(UiDraw.ForeverVarString("Their horses")));
						_objHorseBlips[siteId + text5] = blip2;
					}
				}
			}
			if (num2 == 0 && !_objDone.Contains(siteId))
			{
				_objDone.Add(siteId);
				string text6 = ((value3 != null) ? "The strongboxes are empty." : "Nothing left of their supplies here.");
				ShowNotification(text6);
				GrudgeLog("OBJECTIVE " + siteId + ": done");
			}
		}
	}

