		string text = TownAt(SitePos(s));
		value = (_townSite[s.Id] = text == "Saint Denis");
		if (value)
		{
			GrudgeLog("CAMP site " + s.Id + " (" + s.Label + ") is in " + text + " - never a supply camp");
