	}

	private void AuditWetSites()
	{
		if (_wetAudited || !MapSettled())
		{
			return;
		}
		_wetAudited = true;
		int num = 0;
		foreach (CampSite allSite in Camps.AllSites)
		{
			if (WetSite(allSite))
			{
				num++;
			}
		}
		GrudgeLog($"CAMP water check: {num} of {Camps.AllSites.Count()} camp sites are in the water");
	}

