		int num2 = Math.Min(Config.CheatDeathMaxChance, Config.CheatDeathBaseChance + Config.CheatDeathPerRank * (rec.Rank - 1));
		bool flag6 = !executed && !flag4 && !flag5 && !IsLeaderCopy(rec) && (Config.CheatDeathAlways || _rng.Next(100) < num2);
