	private string KillerDesc(int src)
	{
		if (src == 0)
		{
			return "someone";
		}
		if (_worldNemeses.TryGetValue(src, out var value))
		{
			return value.Name;
		}
		Raid raid = _raids.FirstOrDefault((Raid x) => x.Men.Any((Ped m) => m != null && m.Exists() && m.Handle == src));
		if (raid != null)
		{
			return "the " + raid.Gang.Name;
		}
		if (_skirmish.Any((Ped p) => p != null && p.Exists() && p.Handle == src))
		{
			return "the " + (Gangs.ById((ModGroupOf(src) == _sideA) ? _skirmishGangA : _skirmishGangB)?.Name ?? "other side");
		}
		if (_liveCamps.Values.Any((LiveCamp c) => c.Peds.Any((Ped p) => p != null && p.Exists() && p.Handle == src)))
		{
			return "the O'Driscoll Boys";
		}
		return "someone";
	}

	private void KinReact(NemesisRecord dead, string onlyId = null)
	{
		foreach (var item3 in (from n in Roster
			where n.IsAlive && n != dead && (onlyId == null || n.Id == onlyId) && (n.KinId == dead.Id || dead.KinId == n.Id)
			select (n: n, (n.KinId == dead.Id) ? Relative(n.KinRelation, toThem: true) : (dead.KinRelation ?? "kin"))).Concat(from f in FriendsOf(dead)
			where f.IsAlive && (onlyId == null || f.Id == onlyId) && f.KinId != dead.Id && dead.KinId != f.Id
			select (f: f, "friend")).ToList())
		{
			NemesisRecord item = item3.Item1;
			string item2 = item3.Item2;
			int hate = item.Hate;
			int fear = item.Fear;
			(int hate, int fear, string why) tuple = GriefReaction(item, item2);
			int num = tuple.hate;
			int num2 = tuple.fear;
			string text = tuple.why;
			Tie tie = Mind.TieTo(item, dead.Id);
			if (tie != null)
			{
				float num3 = Math.Max(0.3f, Math.Min(1.5f, (float)(tie.Strength + 30) / 100f));
				num = (int)Math.Round((float)num * num3);
				num2 = (int)Math.Round((float)num2 * num3);
				text += $", tie {tie.Strength}";
			}
			Remember(item, "Grief", Math.Max(40, Math.Min(95, 60 + (tie?.Strength ?? 50) / 3)), "you killed his " + item2 + ", " + dead.Name);
			if (Mind.F(item, "Anger") >= 45 || item.Personality == Personality.Loyal)
			{
				Mind.SetGoal(item, new Goal
				{
					Type = "Avenge",
					Target = "you",
					Text = "avenge his " + item2 + " " + dead.Name,
					Since = GameMinutesNow()
				});
			}
			item.AddYourNotoriety(15);
			item.Hate = Math.Max(0, Math.Min(100, item.Hate + (int)Math.Round((float)num * Balance.HateGainScale)));
			item.Fear = Math.Max(0, Math.Min(100, item.Fear + (int)Math.Round((float)num2 * Balance.FearGainScale)));
			item.Touch();
			Feed(((item2 == "friend") ? "FRIEND" : "KIN") + " " + item.Name + " heard his " + item2 + " " + dead.Name + " died: hate " + Delta(hate, item.Hate) + "  fear " + Delta(fear, item.Fear) + "  (" + text + ")", (item.Fear - fear > item.Hate - hate) ? (150, 170, 210) : Theme.Blood, item);
			GrudgeNotice((item.Fear - fear > item.Hate - hate) ? (item.FullName + " heard you killed his " + item2 + ", " + dead.Name + ". He's afraid he's next.") : (item.FullName + " heard you killed his " + item2 + ", " + dead.Name + ". He's coming for blood."));
		}
	}

	private (int hate, int fear, string why) GriefReaction(NemesisRecord k, string rel)
	{
		float num = Traits.KinWeight(rel);
		float h = 25f * num;
		float f = 6f * num;
		List<string> why = new List<string> { rel };
		switch (k.Personality)
		{
		case Personality.Loyal:
			H(1.4f, "loyal");
			break;
		case Personality.Proud:
			H(1.2f, "proud");
			break;
		case Personality.Hothead:
			H(1.2f, "hothead");
			break;
		case Personality.Cold:
			H(0.6f, "cold");
			break;
		case Personality.Drifter:
			H(0.5f, "drifter");
			break;
		case Personality.Coward:
			H(0.4f, "coward");
			F(3f, "scared");
			break;
		}
		if (k.TraitsRolled)
		{
			H(0.8f + (float)k.Aggression / 250f, Traits.Aggr(k.Aggression).ToLowerInvariant());
			if (k.Disposition == Disposition.Friendly)
			{
				H(0.85f, "friendly");
			}
			if (k.Devotion == Devotion.Devout)
			{
				H(0.85f, "devout");
			}
			if (k.Family == "married" && k.Children > 0)
			{
				F(1.4f, "family man");
			}
			else if (k.Family == "single")
			{
				H(1.1f, "nothing to lose");
			}
			if (k.Smarts == Smarts.Sharp)
			{
				F(1.2f, "sharp");
			}
		}
		return (hate: (int)Math.Round(h), fear: (int)Math.Round(f), why: string.Join(", ", why));
		void F(float m, string tag)
		{
			if (Math.Abs(m - 1f) > 0.01f)
			{
				f *= m;
				why.Add(tag);
			}
		}
		void H(float m, string tag)
		{
			if (Math.Abs(m - 1f) > 0.01f)
			{
				h *= m;
				why.Add(tag);
			}
		}
	}

	private static string Relative(string what, bool toThem)
	{
		return Traits.Inverse(what);
	}

	private static (string key, string pack, string description)? ScarFromWound(WoundReport w)
	{
		DamageItem damageItem = w?.Damage.FirstOrDefault((DamageItem x) => !FinalWounds.Contains(x.Key));
		if (damageItem == null)
		{
			return null;
		}
		if (damageItem.Key.StartsWith("burn:"))
		{
			return (damageItem.Key, "PD_ODR3_Arthur_Wound_Shoulder_L_Cauterized", "burn scars over his " + damageItem.Key.Substring(5));
		}
		if (damageItem.Key.StartsWith("shrapnel:"))
		{
			return (damageItem.Key, "PD_ODR3_Arthur_Wound_Shoulder_L", "shrapnel scars in his " + damageItem.Key.Substring(9));
		}
		if (damageItem.Key == "concussion")
		{
			return (damageItem.Key, "PD_Right_cut_cheek", "ears that still ring from the blast");
		}
		string text = WoundKeys.Side(damageItem.Key);
		switch (WoundKeys.Base(damageItem.Key))
		{
		case "lung":
			return (damageItem.Key, "PD_ODR3_Arthur_Wound_Shoulder_L", "a bullet scar over his " + text + " lung");
		case "liver":
		case "stomach":
		case "intestines":
			return (damageItem.Key, "PD_ODR6_Duster_Slash_Belly", "a puckered bullet scar in his gut");
		case "kidney":
			return (damageItem.Key, "PD_ODR6_Duster_Slash_Belly", "a bullet scar low on his back");
		case "ribs":
		case "sternum":
		case "scapula":
			return (damageItem.Key, "PD_ODR3_Arthur_Wound_Shoulder_L", "ribs that knitted back crooked");
		case "carotid":
		case "windpipe":
			return (damageItem.Key, "PD_Ped_Throat_slash", "a ragged bullet scar across his throat");
		case "jaw":
			return (damageItem.Key, "PD_Right_cut_cheek", "a jaw wired back together");
		case "skull":
			return (damageItem.Key, "PD_Right_cut_cheek", "a dent in his skull where your bullet glanced off");
		case "bladder":
		case "pelvis":
			return (damageItem.Key, "PD_ODR6_Duster_Slash_Belly", "a hip that grinds with every step");
		case "foot":
		case "knee":
		case "femur":
		case "tibia":
		case "femoral":
			return (damageItem.Key, "PD_ODR3_Arthur_Wound_Shoulder_L", ("a " + text + " leg that healed crooked").Replace("  ", " "));
		case "hand":
		case "humerus":
		case "forearm":
		case "clavicle":
			return (damageItem.Key, "PD_ODR3_Arthur_Wound_Shoulder_L", ("a " + text + " arm that never set right").Replace("  ", " "));
		case "spine":
			return (damageItem.Key, "PD_ODR3_Arthur_Wound_Shoulder_L", "a back that's never been straight since");
		default:
			return (damageItem.Key, "PD_ODR3_Arthur_Wound_Shoulder_L", "a bullet scar");
		}
	}

	private unsafe ScarOption PickScar(Ped ped, NemesisRecord rec)
	{
		uint num = PED.GET_PED_CAUSE_OF_DEATH(ped.Handle);
		uint num2 = ((num != 0) ? WEAPON.GET_WEAPONTYPE_GROUP(num) : 0u);
		int num3 = PED.GET_PED_SOURCE_OF_DEATH(ped.Handle);
		Entity entity = ((num3 != 0) ? Entity.FromHandle(num3) : null);
		int num4 = 0;
		PED.GET_PED_LAST_DAMAGE_BONE(ped.Handle, &num4);
		BoneID boneID = (BoneID)num4;
		string text = boneID.ToString();
		ScarOption[] array = ((entity != null && entity.IsAnimal) ? ClawScars : (num2 switch
		{
			3566412244u => BladeScars, 
			2685387236u => BeatingScars, 
			3053283277u => ArrowScars, 
			1548507267u => BurnScars, 
			_ => (!text.Contains("NECK") && !text.Contains("JAW")) ? GunshotScars : NeckScars, 
		}));
		ScarOption[] array2 = array.Where((ScarOption o) => rec.Scars.All((Scar s) => s.DamagePack != o.Pack)).ToArray();
		ScarOption[] array3 = ((array2.Length != 0) ? array2 : array);
		return array3[_rng.Next(array3.Length)];
	}

	private static void ApplyScars(Ped ped, NemesisRecord rec)
	{
		foreach (Scar scar in rec.Scars)
		{
			PED.APPLY_PED_DAMAGE_PACK(ped.Handle, scar.DamagePack, 0f, 1f);
		}
	}

	private Gang TownHolder(string town, out District d)
	{
		d = null;
		if (!TownCore(town, out var centre, out var _))
		{
			return null;
		}
		d = DistrictAt(centre);
		(Gang, Gang)? tuple = ((d == null) ? (((Gang, Gang)?)null) : WarIn(d));
		if (!tuple.HasValue)
		{
			return null;
		}
		District dd = d;
		return (from g in new Gang[2]
			{
				tuple.Value.Item1,
				tuple.Value.Item2
			}
			where g != null && !g.StoryOnly && !IsDestroyed(g) && FactionModels.ContainsKey(g.Id) && HoldOf(dd, g.Id) > 0
			orderby HoldOf(dd, g.Id) descending
			select g).FirstOrDefault();
	}

	private string TownNear(Vector3 me)
	{
		if (_currentTown != null)
		{
			return _currentTown;
		}
		foreach (string repTown in RepTowns)
		{
			if (TownCore(repTown, out var centre, out var radius) && new Vector3(me.X - centre.X, me.Y - centre.Y, 0f).Length() < radius * 1.8f)
			{
				return repTown;
			}
		}
		return null;
	}

	private List<(Vector3 at, float road)> EntrancesOf(string town)
	{
		if (_entrances.TryGetValue(town, out List<(Vector3, float)> value))
		{
			return value;
		}
		if (!TownCore(town, out var c, out var radius))
		{
			return new List<(Vector3, float)>();
		}
		List<(Vector3, float)> list = new List<(Vector3, float)>();
		for (int i = 0; i < 360; i += 6)
		{
			if (list.Count >= 6)
			{
				break;
			}
			double num = (double)i * Math.PI / 180.0;
			Vector3 at = new Vector3(c.X + (float)Math.Cos(num) * radius * 1.15f, c.Y + (float)Math.Sin(num) * radius * 1.15f, c.Z);
			Vector3? node = RoadNodeNear(at, 30f, out var heading, 0);
			if (node.HasValue)
			{
				float num2 = new Vector3(node.Value.X - c.X, node.Value.Y - c.Y, 0f).Length();
				if (!(num2 < radius * 0.85f) && !(num2 > radius * 1.5f) && !list.Any(((Vector3 at, float road) e) => e.at.DistanceTo(node.Value) < 70f) && Dry(node.Value))
				{
					list.Add((node.Value, heading));
				}
			}
		}
		if (list.Count > 0)
		{
			_entrances[town] = list;
			GrudgeLog($"CHECKPOINT {town}: {list.Count} ways in - " + string.Join("; ", list.Select(((Vector3 at, float road) e) => $"{e.at.X:0},{e.at.Y:0} ({CompassTo(c, e.at)})")));
		}
		return list;
	}

	private void UpdateCheckpoint(Ped player)
	{
		if (Game.GameTime < _nextCheckpoint)
		{
			return;
		}
		_nextCheckpoint = Game.GameTime + 1000;
		Vector3 me = player.Position;
		bool flag = MISC.GET_MISSION_FLAG() || player.IsDead;
		District d;
		foreach (Roadblock item in _roadblocks.ToList())
		{
			List<Ped> list = item.Men.Where((Ped p) => p.Exists() && !p.IsDead).ToList();
			float num = item.At.DistanceTo(me);
			int num2;
			if (!item.Spawner)
			{
				if (!item.OnRoad)
				{
					Gang gang = TownHolder(item.Town, out d);
					num2 = ((gang != null && gang == item.Gang) ? 1 : 0);
				}
				else
				{
					num2 = (RoadBlockHolds(item) ? 1 : 0);
				}
			}
			else
			{
				num2 = 1;
			}
			bool flag2 = (byte)num2 != 0;
			if (flag || list.Count == 0 || (item.Spawner && TownNear(me) != item.Town) || (!item.Hostile && (!flag2 || (num > 280f && (HiddenFromView(player, item.At) || num > 350f)))))
			{
				DropRoadblock(item, player, wipe: false);
			}
			else
			{
				RunRoadblock(item, player, list);
			}
		}
		foreach (Walkers item2 in _walkers.ToList())
		{
			List<Ped> list2 = item2.Men.Where((Ped p) => p.Exists() && !p.IsDead).ToList();
			Gang gang2 = TownHolder(item2.Town, out d);
			bool flag3 = gang2 != null && gang2 == item2.Gang;
			if (flag || list2.Count == 0 || (!item2.Hostile && (_currentTown != item2.Town || !flag3)))
			{
				DropWalkers(item2, player, wipe: false);
			}
			else
			{
				RunWalkers(item2, player, list2);
			}
		}
		if (flag || NoSpawnReason(player, place: true) != null || WorldBusy(player))
		{
			return;
		}
		string town = TownNear(me);
		if (town == null)
		{
			TryRoadBlock(player);
			return;
		}
		Gang gang3 = TownHolder(town, out var d2);
		if (gang3 == null)
		{
			return;
		}
		string text = TownWarTier(town);
		int num3 = ((text == "cold") ? 1 : 3);
		int num4 = Enumerable.Count(_roadblocks, (Roadblock r) => !r.Spawner);
		List<(Vector3 at, float road)> ways = EntrancesOf(town);
		foreach (int i in from k in Enumerable.Range(0, ways.Count)
			orderby ways[k].at.DistanceTo(me)
			select k)
		{
			if (num4 >= num3)
			{
				break;
			}
			(Vector3, float) tuple = ways[i];
			if (_roadblocks.Any((Roadblock r) => r.Town == town && r.Entrance == i) || (_wayClearedAt.TryGetValue(town + "|" + i, out var value) && Game.GameTime - value < 600000))
			{
				continue;
			}
			float num5 = tuple.Item1.DistanceTo(me);
			if (!(num5 > 200f) && !(num5 < 35f) && (!(num5 < 140f) || HiddenFromView(player, tuple.Item1 + new Vector3(0f, 0f, 1f))))
			{
				Roadblock roadblock = BuildRoadblock(player, gang3, tuple.Item1, tuple.Item2, town, i, spawner: false, text);
				if (roadblock != null)
				{
					num4++;
					GrudgeLog($"CHECKPOINT {town}: the {gang3.Name} hold the way in {CompassTo(TownCoreCentre(town), tuple.Item1)} ({roadblock.Men.Count} men, {text}, {num5:0} m from you) - the war in {d2?.Name}");
				}
				break;
			}
		}
		int num6 = ((text == "cold" || text == "truce") ? 1 : 2);
		if (_currentTown == town && Game.GameTime >= _nextWalkerSpawn && Enumerable.Count(_walkers, (Walkers w) => w.Town == town) < num6)
		{
			_nextWalkerSpawn = Game.GameTime + 20000;
			if (text == "cold" && _rng.Next(2) == 0)
			{
				_nextWalkerSpawn = Game.GameTime + 120000;
			}
			else
			{
				SpawnWalkers(player, gang3, town);
			}
		}
	}

	private Vector3 TownCoreCentre(string town)
	{
		if (!TownCore(town, out var centre, out var _))
		{
			return Vector3.Zero;
		}
		return centre;
	}

	private bool RoadBlockHolds(Roadblock rb)
	{
		District d = DistrictAt(rb.At);
		WarRecord warRecord = ((d == null) ? null : Wars.FirstOrDefault((WarRecord x) => x.Result == null && x.District == d.Key));
		if (warRecord == null || warRecord.Paused)
		{
			return false;
		}
		InitHeat(warRecord);
		if (warRecord.Heat >= 45)
		{
			if (!(warRecord.A == rb.Gang.Id))
			{
				return warRecord.B == rb.Gang.Id;
			}
			return true;
		}
		return false;
	}

	internal void DebugRoadBlock(Ped player)
	{
		if (TownNear(player.Position) != null)
		{
			SpawnerSays("ride out of town first - this is a roadblock out on the roads.");
			return;
		}
		if (!WarHere.HasValue)
		{
			SpawnerSays("no war in this district - use 'Start a war here' first.");
			return;
		}
		_forceRoadBlock = true;
		_nextRoadBlockRoll = 0;
		_roadBlockAllowed = 0;
		foreach (Roadblock item in _roadblocks.Where((Roadblock r) => r.OnRoad).ToList())
		{
			DropRoadblock(item, player, wipe: false);
		}
		SpawnerSays("a roadblock goes up on the road ahead (out of your view).");
	}

	private void TryRoadBlock(Ped player)
	{
		if (Game.GameTime < _nextRoadBlockRoll)
		{
			return;
		}
		_nextRoadBlockRoll = Game.GameTime + (_forceRoadBlock ? 3000 : 120000);
		if (_roadblocks.Any((Roadblock r) => r.OnRoad) || Game.GameTime < _roadBlockAllowed || player.IsDead)
		{
			return;
		}
		District d = CurrentDistrict;
		WarRecord warRecord = ((d == null) ? null : Wars.FirstOrDefault((WarRecord x) => x.Result == null && x.District == d.Key));
		if (warRecord == null || warRecord.Paused)
		{
			return;
		}
		InitHeat(warRecord);
		if (warRecord.Heat < 60 && !_forceRoadBlock)
		{
			return;
		}
		int num = _rng.Next(100);
		if (num >= 30 && !_forceRoadBlock)
		{
			GrudgeLog($"CHECKPOINT road roll in {d.Name} (heat {warRecord.Heat:0}): 30%, rolled {num} - not now");
			return;
		}
		Gang gang = Gangs.ById(warRecord.A);
		Gang gang2 = Gangs.ById(warRecord.B);
		List<Gang> list = (from x in new Gang[2] { gang, gang2 }
			where x != null && FactionModels.ContainsKey(x.Id) && FieldCap(x) >= 3
			orderby HoldOf(d, x.Id) descending
			select x).ToList();
		if (list.Count == 0)
		{
			return;
		}
		Gang gang3 = list[0];
		Vector3 position = player.Position;
		double num2 = Math.Atan2(Forward(player).Y, Forward(player).X);
		for (int num3 = 0; num3 < 24; num3++)
		{
			double num4 = num2 + (_rng.NextDouble() - 0.5) * Math.PI * ((num3 < 16) ? 0.5 : 1.2);
			float num5 = 140f + (float)_rng.NextDouble() * 80f;
			Vector3? vector = RoadNodeNear(new Vector3(position.X + (float)Math.Cos(num4) * num5, position.Y + (float)Math.Sin(num4) * num5, position.Z), 30f, out var heading, (num3 >= 16) ? 1 : 0);
			if (!vector.HasValue)
			{
				continue;
			}
			Vector3 vector2 = Ground(vector.Value);
			if (Math.Abs(vector2.Z - vector.Value.Z) > 3f || !Dry(vector.Value) || InsideAnyTown(vector.Value))
			{
				continue;
			}
			float num6 = vector.Value.DistanceTo(position);
			if (!(num6 < 120f) && !(num6 > 240f) && HiddenFromView(player, vector.Value + new Vector3(0f, 0f, 1.5f)))
			{
				Vector3 vector3 = new Vector3(vector.Value.X, vector.Value.Y, vector2.Z);
				Roadblock roadblock = BuildRoadblock(player, gang3, vector3, heading, d.Name, -1, spawner: false, "hot", onRoad: true);
				if (roadblock != null)
				{
					_roadBlockAllowed = Game.GameTime + 480000;
					_forceRoadBlock = false;
					GrudgeLog($"CHECKPOINT road: the {gang3.Name} hold the road in {d.Name} ({roadblock.Men.Count} men, heat {warRecord.Heat:0}) - {num6:0} m {CompassTo(position, vector3)} of you");
				}
				return;
			}
		}
		GrudgeLog("CHECKPOINT road: no road out of your view 140-220 m ahead in " + d.Name);
	}

	private string TownWarTier(string town)
	{
		District d = DistrictAt(TownCoreCentre(town));
		WarRecord warRecord = ((d == null) ? null : Wars.FirstOrDefault((WarRecord x) => x.Result == null && x.District == d.Key));
		if (warRecord == null)
		{
			return "warm";
		}
		if (warRecord.Paused)
		{
			return "truce";
		}
		InitHeat(warRecord);
		if (warRecord.Heat >= 30)
		{
			if (warRecord.Heat >= 60)
			{
				return "hot";
			}
			return "warm";
		}
		return "cold";
	}

	private void EnsureCheckpointGroup(Ped player)
	{
		if (_checkpointGroup == 0)
		{
			_checkpointGroup = World.AddRelationshipGroup("NEMESIS_CHECKPOINT");
		}
		World.SetRelationshipBetweenGroups((eRelationshipType)3, _checkpointGroup, player.RelationshipGroup);
		World.SetRelationshipBetweenGroups((eRelationshipType)3, player.RelationshipGroup, _checkpointGroup);
		_nextRelations = 0;
	}

	private Ped CheckpointMan(Gang g, Vector3 pos, float heading, string scenario, bool rifle = false)
	{
		PedHash[] array = FactionModels[g.Id];
		Crumbs.Native("checkpoint man " + g.Id);
		Ped ped = SpawnPed(array[_rng.Next(array.Length)], pos, heading);
		if (ped == null)
		{
			return null;
		}
		MakeOurs(ped.Handle);
		WEAPON.REMOVE_ALL_PED_WEAPONS(ped.Handle, p1: true, p2: true);
		eWeapon eWeapon2;
		if (rifle)
		{
			eWeapon2 = (eWeapon)1999408598u;
		}
		else if ((g.TroopLongGuns || _rng.Next(3) > 0) && !ShortOfArms(g))
		{
			eWeapon2 = ((_rng.Next(2) == 0) ? ((eWeapon)4111948705u) : ((eWeapon)2823250668u));
		}
		else
		{
			eWeapon2 = (eWeapon)379542007u;
		}
		if (g.TribalKit && !rifle)
		{
			ArmTroop(ped, g);
		}
		else
		{
			ped.GiveWeapon(eWeapon2, 120, (eWeapon2 == (eWeapon)379542007u) ? ((eWeaponAttachPoint)2) : ((eWeaponAttachPoint)9), equipNow: true, isAmmoLoaded: false, a6: false);
		}
		ped.RelationshipGroup = GroupFor(g);
		ped.BlockPermanentEvents = false;
		ApplyFactionStyle(ped, g.Id);
		ENTITY.SET_ENTITY_HEADING(ped.Handle, heading);
		if (scenario == "ARMED")
		{
			try
			{
				WEAPON.SET_CURRENT_PED_WEAPON(ped.Handle, (uint)eWeapon2, p2: true, 0, p4: false, p5: false);
			}
			catch
			{
			}
			TASK.TASK_STAND_STILL(ped.Handle, -1);
		}
		else if (scenario != null)
		{
			TASK.TASK_START_SCENARIO_IN_PLACE_HASH(ped.Handle, MISC.GET_HASH_KEY(scenario), -1, p3: true, 0u, -1f, p6: false);
		}
		return ped;
	}

	private Roadblock BuildRoadblock(Ped player, Gang g, Vector3 at, float roadHeading, string town, int entrance, bool spawner = false, string tier = null, bool onRoad = false)
	{
		EnsureCheckpointGroup(player);
		tier = tier ?? TownWarTier(town);
		Roadblock rb = new Roadblock
		{
			Town = town,
			Entrance = entrance,
			Gang = g,
			At = at,
			Road = roadHeading,
			Spawner = spawner,
			Tier = tier,
			OnRoad = onRoad
		};
		double num = (double)roadHeading * Math.PI / 180.0;
		Vector3 side = new Vector3((float)Math.Cos(num), (float)Math.Sin(num), 0f);
		Vector3 vector = new Vector3(0f - (float)Math.Sin(num), (float)Math.Cos(num), 0f);
		Vector3 vector2 = player.Position - at;
		vector2.Z = 0f;
		Vector3 vector3 = at - TownCoreCentre(town);
		vector3.Z = 0f;
		Vector3 vector4 = (((spawner | onRoad) || vector3.Length() < 1f) ? vector2 : vector3);
		Vector3 front = vector * ((vector.X * vector4.X + vector.Y * vector4.Y >= 0f) ? 1f : (-1f));
		for (int i = 0; i < 2; i++)
		{
			float num2 = ((i == 0) ? 1f : (-1f));
			Prop(BigCrateModels, "crate", Shoulder(5.5f * num2, 0f), roadHeading + (float)_rng.Next(-10, 11));
			Prop(BarrelModels, "barrel", Shoulder(6.3f * num2, 1.3f), _rng.Next(360));
			if (i == 0)
			{
				Prop(HayModels, "hay", Shoulder(7.2f * num2, -1f), roadHeading + 90f);
			}
		}
		Vector3? vector5 = ((tier == "hot") ? ((Vector3?)null) : Shoulder(9.5f, -3.5f));
		if (vector5.HasValue)
		{
			int num3 = MakeFire(vector5.Value);
			if (num3 != 0)
			{
				rb.Props.Add(num3);
			}
		}
		int num4;
		if (tier == "cold")
		{
			num4 = 2 + _rng.Next(2);
		}
		else if (tier == "hot")
		{
			num4 = 4 + _rng.Next(2);
		}
		else
		{
			num4 = ((tier == "truce") ? 3 : (3 + _rng.Next(2)));
		}
		float num5 = HeadingTo(at, at + front * 10f);
		string[] array = Stances();
		for (int j = 0; j < num4; j++)
		{
			string text = array[Math.Min(j, array.Length - 1)];
			bool flag = text.StartsWith("WORLD_HUMAN_FIRE") && vector5.HasValue;
			Vector3? vector6 = (flag ? new Vector3?(vector5.Value - side * 1.3f + front * ((float)_rng.NextDouble() - 0.5f)) : (j switch
			{
				4 => Shoulder(6f, -2.6f), 
				3 => Shoulder(-7.6f, -2.8f), 
				1 => Shoulder(-6.7f, -0.7f), 
				0 => Shoulder(6.7f, -0.7f), 
				_ => Shoulder(7.6f, -2.8f), 
			}));
			if (!vector6.HasValue)
			{
				vector6 = Shoulder((j % 2 == 0) ? 6.5f : (-6.5f), -2.5f);
			}
			if (!vector6.HasValue)
			{
				continue;
			}
			if (text.StartsWith("WORLD_HUMAN_FIRE") && !vector5.HasValue)
			{
				text = ((tier == "cold" || tier == "truce") ? "WORLD_HUMAN_SMOKE" : "ARMED");
			}
			float heading;
			if (flag)
			{
				heading = HeadingTo(vector6.Value, vector5.Value);
			}
			else
			{
				heading = ((j == 3) ? faceLane(vector6.Value) : (num5 + (float)_rng.Next(-30, 31)));
			}
			bool rifle = tier == "hot" && j == 0;
			Ped ped = CheckpointMan(g, vector6.Value, heading, text, rifle);
			if (!(ped != null))
			{
				continue;
			}
			if (tier == "truce" || tier == "cold")
			{
				try
				{
					WEAPON.SET_CURRENT_PED_WEAPON(ped.Handle, 2725352035u, p2: true, 0, p4: false, p5: false);
				}
				catch
				{
				}
			}
			rb.Men.Add(ped);
		}
		if (rb.Men.Count == 0)
		{
			DropProps(rb.Props, player, wipe: true);
			GrudgeLog("CHECKPOINT " + town + ": nobody spawned");
			return null;
		}
		if (_debugOn)
		{
			try
			{
				Crumbs.Native("checkpoint debug blip");
				rb.Blip = MAP.BLIP_ADD_FOR_COORDS(2545348716u, at.X, at.Y, at.Z);
				Function.Call(11290983183885202434uL, rb.Blip, new InputArgument(UiDraw.ForeverVarString(MemberWord(g) + " roadblock (debug)")));
			}
			catch (Exception ex)
			{
				GrudgeLog("CHECKPOINT debug blip failed: " + ex.Message);
			}
		}
		_roadblocks.Add(rb);
		return rb;
		void Prop(string[] list, string key, Vector3? v, float hd)
		{
			if (v.HasValue)
			{
				_propModel.TryGetValue(key, out var value);
				int num6 = MakeCheckpointProp(list, v.Value, hd, ref value);
				if (value != null)
				{
					_propModel[key] = value;
				}
				if (num6 != 0)
				{
					rb.Props.Add(num6);
				}
			}
		}
		Vector3? Shoulder(float lat, float fwd)
		{
			float num6 = Math.Sign(lat);
			float num7 = Math.Abs(lat);
			for (float num8 = 0f; num8 <= 3f; num8++)
			{
				Vector3 vector7 = GroundOnSpot(at + side * (num6 * (num7 + num8)) + front * fwd);
				if (vector7 != Vector3.Zero && Math.Abs(vector7.Z - at.Z) <= 1.2f && Dry(vector7))
				{
					return vector7;
				}
			}
			return null;
		}
		string[] Stances()
		{
			return tier switch
			{
				"cold" => new string[3] { "WORLD_HUMAN_SMOKE", "WORLD_HUMAN_DRINKING", "WORLD_HUMAN_FIRE_SIT" }, 
				"truce" => new string[3] { "WORLD_HUMAN_FIRE_SIT", "WORLD_HUMAN_SMOKE", "WORLD_HUMAN_FIRE_STAND" }, 
				"hot" => new string[5] { "ARMED", "ARMED", "ARMED", "ARMED", "WORLD_HUMAN_GUARD_SCOUT" }, 
				_ => new string[4]
				{
					"ARMED",
					(_rng.Next(2) == 0) ? "WORLD_HUMAN_GUARD_SCOUT" : "ARMED",
					"WORLD_HUMAN_FIRE_STAND",
					(_rng.Next(2) == 0) ? "WORLD_HUMAN_SMOKE" : "ARMED"
				}, 
			};
		}
		float faceLane(Vector3 p)
		{
			return HeadingTo(p, at);
		}
	}

	private void RunRoadblock(Roadblock rb, Ped player, List<Ped> alive)
	{
		Vector3 me = player.Position;
		if (!rb.Hostile && rb.Men.Any((Ped p) => p.Exists() && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(p.Handle, player.Handle, p2: true, p3: true)))
		{
			GroupFight(rb.Men, player, ref rb.Hostile, "CHECKPOINT " + rb.Town + ": a fight at the roadblock - you hurt one of them");
		}
		if (!rb.Hostile && rb.Men.Any((Ped p) => p.Exists() && !p.IsDead && PED.IS_PED_IN_COMBAT(p.Handle, player.Handle)))
		{
			GroupFight(rb.Men, player, ref rb.Hostile, "CHECKPOINT " + rb.Town + ": the roadblock opened fire - their outfit is after you");
		}
		if (rb.Hostile)
		{
			return;
		}
		if (rb.Warned)
		{
			if (Game.GameTime - rb.WarnedAt > 5000 && me.DistanceTo(rb.At) < 6f)
			{
				ShowSubtitle(rb.Gang.Name + " man: I said turn back!");
				GroupFight(rb.Men, player, ref rb.Hostile, "CHECKPOINT " + rb.Town + ": you rode through after they turned you back");
			}
			else if (me.DistanceTo(rb.At) > 40f)
			{
				rb.Warned = false;
			}
		}
		else
		{
			if (rb.Spoke)
			{
				return;
			}
			Ped ped = alive.OrderBy((Ped p) => p.Position.DistanceTo(me)).First();
			if (ped.Position.DistanceTo(me) > ((rb.Tier == "hot") ? 14f : 10f))
			{
				return;
			}
			rb.Spoke = true;
			if (_raids.Any((Raid r) => r.Gang == rb.Gang && r.Hostile))
			{
				ShowSubtitle(rb.Gang.Name + " man: That's him! That's the one!");
				GroupFight(rb.Men, player, ref rb.Hostile, "CHECKPOINT " + rb.Town + ": a fight at the roadblock - a patrol of theirs is after you");
			}
			else if (rb.Tier == "cold")
			{
				foreach (Ped item in alive)
				{
					TASK.TASK_LOOK_AT_ENTITY(item.Handle, player.Handle, 4000, 0, 51, 0);
				}
				GrudgeLog("CHECKPOINT " + rb.Town + ": the " + rb.Gang.Name + " watched you by (cold war)");
			}
			else if (rb.Tier == "truce")
			{
				TASK.TASK_LOOK_AT_ENTITY(ped.Handle, player.Handle, 5000, 0, 51, 0);
				ShowSubtitle(rb.Gang.Name + " man: " + TruceLines[_rng.Next(TruceLines.Length)]);
				GrudgeLog("CHECKPOINT " + rb.Town + ": the " + rb.Gang.Name + " waved you through (truce)");
			}
			else if (rb.Tier == "hot" && !AfterYou(rb.Gang) && NotorietyOf(rb.Gang) >= 20)
			{
				TASK.TASK_AIM_GUN_AT_ENTITY(ped.Handle, player.Handle, 5000, p3: false, 0);
				ShowSubtitle(rb.Gang.Name + " man: " + TurnBackLines[_rng.Next(TurnBackLines.Length)]);
				rb.Warned = true;
				rb.WarnedAt = Game.GameTime;
				GrudgeLog($"CHECKPOINT {rb.Town}: the {rb.Gang.Name} turned you back (hot war, notoriety {NotorietyOf(rb.Gang)})");
			}
			else if (AfterYou(rb.Gang))
			{
				ShowSubtitle(rb.Gang.Name + " man: That's him! That's the one!");
				GroupFight(rb.Men, player, ref rb.Hostile, "CHECKPOINT " + rb.Town + ": a fight at the roadblock - they know your face");
			}
			else
			{
				TASK.CLEAR_PED_TASKS(ped.Handle, p1: true, p2: false);
				TASK.TASK_TURN_PED_TO_FACE_ENTITY(ped.Handle, player.Handle, 3000, 0f, 0f, 0f);
				TASK.TASK_LOOK_AT_ENTITY(ped.Handle, player.Handle, 6000, 0, 51, 0);
				string[] array = (CheckpointLines.TryGetValue(rb.Gang.Id, out var value) ? value : new string[0]).Concat(CheckpointLines[""]).ToArray();
				ShowSubtitle(rb.Gang.Name + " man: " + array[_rng.Next(array.Length)]);
				GrudgeLog("CHECKPOINT " + rb.Town + ": the " + rb.Gang.Name + " stopped you and let you by");
			}
		}
	}

	private void GroupFight(List<Ped> men, Ped player, ref bool hostile, string log)
	{
		hostile = true;
		foreach (Ped item in men.Where((Ped p) => p.Exists() && !p.IsDead))
		{
			item.BlockPermanentEvents = false;
			item.RelationshipGroup = PED.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH(item.Handle);
			ForgetSwitch(item.Handle);
			TASK.CLEAR_PED_TASKS(item.Handle, p1: true, p2: false);
			TASK.TASK_COMBAT_PED(item.Handle, player.Handle, 0, 16);
		}
		GrudgeLog(log);
	}

	private unsafe void DropRoadblock(Roadblock rb, Ped player, bool wipe)
	{
		int num = Enumerable.Count(rb.Men, (Ped p) => p.Exists() && p.IsDead);
		if (num > 0 && !rb.Men.Any((Ped p) => p.Exists() && !p.IsDead))
		{
			_wayClearedAt[rb.Town + "|" + rb.Entrance] = Game.GameTime;
			if (Enumerable.Count(rb.Men, (Ped p) => p.Exists() && p.IsDead && PED.GET_PED_SOURCE_OF_DEATH(p.Handle) == player.Handle) > 0 && rb.Gang != null)
			{
				try
				{
					string text = (rb.OnRoad ? "roadblock on the road" : ("checkpoint" + ((rb.Town != null) ? (" outside " + rb.Town) : "")));
					ChronicleDeed("roadblock", "You cleared the " + OutfitPoss(rb.Gang) + " " + text, (rb.OnRoad || rb.Town == null) ? ("near " + GetZoneName(rb.At)) : ("by " + rb.Town), rb.At, rb.Gang.Id);
				}
				catch
				{
				}
			}
		}
		foreach (Ped item in rb.Men.ToList())
		{
			if (!(item == null) && item.Exists())
			{
				if (wipe)
				{
					Wipe(item);
				}
				else
				{
					DeleteOrRelease(item);
				}
			}
		}
		GrudgeLog($"CHECKPOINT {rb.Town}: roadblock down ({num} dead)");
		rb.Men.Clear();
		if (rb.Blip != 0)
		{
			int blip = rb.Blip;
			rb.Blip = 0;
			try
			{
				MAP.REMOVE_BLIP(&blip);
			}
			catch
			{
			}
		}
		DropProps(rb.Props, player, wipe);
		_roadblocks.Remove(rb);
	}

	private void SpawnWalkers(Ped player, Gang g, string town)
	{
		if (!TownCore(town, out var centre, out var radius))
		{
			return;
		}
		EnsureCheckpointGroup(player);
		Vector3? vector = null;
		for (int i = 0; i < 20; i++)
		{
			if (vector.HasValue)
			{
				break;
			}
			double num = _rng.NextDouble() * Math.PI * 2.0;
			float num2 = radius * (0.2f + (float)_rng.NextDouble() * 0.6f);
			Vector3? vector2 = RoadNodeNear(new Vector3(centre.X + (float)Math.Cos(num) * num2, centre.Y + (float)Math.Sin(num) * num2, centre.Z), 25f, out var heading);
			if (!vector2.HasValue)
			{
				continue;
			}
			double num3 = (double)heading * Math.PI / 180.0;
			Vector3 vector3 = GroundOnSpot(vector2.Value + new Vector3((float)Math.Cos(num3), (float)Math.Sin(num3), 0f) * 4.5f);
			if (!(vector3 == Vector3.Zero) && Dry(vector3))
			{
				float num4 = vector3.DistanceTo(player.Position);
				if (!(num4 < 40f) && !(num4 > 150f) && HiddenFromView(player, vector3 + new Vector3(0f, 0f, 1f)) && !OurPeopleNear(vector3, 12f))
				{
					vector = vector3;
				}
			}
		}
		if (!vector.HasValue)
		{
			return;
		}
		Walkers walkers = new Walkers
		{
			Town = town,
			Gang = g,
			NextMove = 0
		};
		int num5 = 2 + _rng.Next(2);
		for (int j = 0; j < num5; j++)
		{
			Ped ped = CheckpointMan(g, vector.Value + new Vector3((float)j * 1.2f, (float)(-j) * 0.8f, 0f), _rng.Next(360), null);
			if (ped != null)
			{
				walkers.Men.Add(ped);
			}
		}
		if (walkers.Men.Count != 0)
		{
			_walkers.Add(walkers);
			GrudgeLog($"CHECKPOINT {town}: {walkers.Men.Count} {g.Name} men walk the streets ({vector.Value.DistanceTo(player.Position):0} m from you)");
		}
	}

	private void RunWalkers(Walkers w, Ped player, List<Ped> alive)
	{
		Vector3 me = player.Position;
		if (!w.Hostile && w.Men.Any((Ped p) => p.Exists() && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(p.Handle, player.Handle, p2: true, p3: true)))
		{
			GroupFight(w.Men, player, ref w.Hostile, "CHECKPOINT " + w.Town + ": a fight with the men walking the street - you hurt one of them");
		}
		if (w.Hostile)
		{
			return;
		}
		Ped ped = alive[0];
		float num = alive.Min((Ped p) => p.Position.DistanceTo(me));
		float num2 = ((TownWarTier(w.Town) == "hot") ? 22f : 12f);
		if (num < num2 && !w.Stared)
		{
			w.Stared = true;
			if (AfterYou(w.Gang))
			{
				ShowSubtitle(w.Gang.Name + " man: Hey - that's him!");
				GroupFight(w.Men, player, ref w.Hostile, "CHECKPOINT " + w.Town + ": the men walking the street know your face");
				return;
			}
			foreach (Ped item in alive)
			{
				TASK.TASK_LOOK_AT_ENTITY(item.Handle, player.Handle, 5000, 0, 51, 0);
			}
		}
		else if (num > 25f)
		{
			w.Stared = false;
		}
		if (Game.GameTime < w.NextMove)
		{
			return;
		}
		w.NextMove = Game.GameTime + 25000 + _rng.Next(20000);
		if (!TownCore(w.Town, out var centre, out var radius))
		{
			return;
		}
		for (int num3 = 0; num3 < 10; num3++)
		{
			double num4 = _rng.NextDouble() * Math.PI * 2.0;
			float num5 = radius * (0.1f + (float)_rng.NextDouble() * 0.7f);
			Vector3? vector = RoadNodeNear(new Vector3(centre.X + (float)Math.Cos(num4) * num5, centre.Y + (float)Math.Sin(num4) * num5, centre.Z), 25f, out var heading);
			if (!vector.HasValue)
			{
				continue;
			}
			double num6 = (double)heading * Math.PI / 180.0;
			Vector3 vector2 = vector.Value + new Vector3((float)Math.Cos(num6), (float)Math.Sin(num6), 0f) * 4.5f;
			if (!(vector2.DistanceTo(ped.Position) < 30f))
			{
				Crumbs.Native("walkers move");
				TASK.TASK_FOLLOW_NAV_MESH_TO_COORD(ped.Handle, vector2.X, vector2.Y, vector2.Z, 1f, -1, 1.5f, 0, 0f);
				for (int num7 = 1; num7 < alive.Count; num7++)
				{
					TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(alive[num7].Handle, ped.Handle, (num7 % 2 == 0) ? 1.2f : (-1.2f), -1.5f * (float)num7, 0f, 1f, -1, 1.5f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
				}
				break;
			}
		}
	}

	private void DropWalkers(Walkers w, Ped player, bool wipe)
	{
		foreach (Ped item in w.Men.ToList())
		{
			if (!(item == null) && item.Exists())
			{
				if (wipe)
				{
					Wipe(item);
				}
				else
				{
					DeleteOrRelease(item);
				}
			}
		}
		w.Men.Clear();
		_walkers.Remove(w);
	}

	private void EndCheckpoint(Ped player, bool wipe)
	{
		foreach (Roadblock item in _roadblocks.ToList())
		{
			DropRoadblock(item, player, wipe);
		}
		foreach (Walkers item2 in _walkers.ToList())
		{
			DropWalkers(item2, player, wipe);
		}
	}

	private unsafe void DropProps(List<int> props, Ped player, bool wipe)
	{
		foreach (int prop in props)
		{
			int current = prop;
			if (ENTITY.DOES_ENTITY_EXIST(current))
			{
				Vector3 vector = ENTITY.GET_ENTITY_COORDS(current, p1: false, p2: false);
				Crumbs.Native("checkpoint prop drop");
				if (wipe || player == null || !player.Exists() || player.Position.DistanceTo(vector) > 80f || HiddenFromView(player, vector))
				{
					OBJECT.DELETE_OBJECT(&current);
				}
				else
				{
					ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(&current);
				}
			}
		}
		props.Clear();
	}

	private Vector3? CheckpointSpot(Ped player, string town, bool mustHide, out string why)
	{
		Vector3 position = player.Position;
		bool flag = TownCore(town, out var centre, out var radius);
		double num = Math.Atan2(Forward(player).Y, Forward(player).X);
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		int num5 = 0;
		int num6 = 0;
		int num7 = 0;
		for (int i = 0; i < 36; i++)
		{
			double num8 = num + (_rng.NextDouble() - 0.5) * Math.PI * ((i < 24) ? 1.2 : 2.0);
			float num9 = 40f + (float)_rng.NextDouble() * 60f;
			Vector3 at = new Vector3(position.X + (float)Math.Cos(num8) * num9, position.Y + (float)Math.Sin(num8) * num9, position.Z);
			Vector3? vector = RoadNodeNear(at, 30f, out var heading, (i >= 24) ? 1 : 0);
			if (!vector.HasValue)
			{
				num2++;
				continue;
			}
			Vector3 vector2 = GroundOnSpot(vector.Value);
			if (vector2 == Vector3.Zero)
			{
				vector2 = vector.Value;
			}
			if (flag && new Vector3(vector2.X - centre.X, vector2.Y - centre.Y, 0f).Length() > radius * 1.35f)
			{
				num3++;
				continue;
			}
			float num10 = vector2.DistanceTo(position);
			if (num10 < 30f || num10 > 115f)
			{
				num4++;
				continue;
			}
			if (!Dry(vector2))
			{
				num5++;
				continue;
			}
			if (OurPeopleNear(vector2, 10f))
			{
				num6++;
				continue;
			}
			if (mustHide && !HiddenFromView(player, vector2 + new Vector3(0f, 0f, 1f)))
			{
				num7++;
				continue;
			}
			why = null;
			_checkpointRoad = heading;
			return vector2;
		}
		why = $"36 tries: no road {num2}, out of town {num3}, too near / far {num4}, water {num5}, our people {num6}, in your view {num7}";
		return null;
	}

	private int MakeCheckpointProp(string[] models, Vector3 at, float heading, ref string cache, bool freeze = true)
	{
		string[] array = ((cache == null) ? models : new string[1] { cache });
		foreach (string text in array)
		{
			Model m = new Model(text);
			if (!m.IsValid || !m.IsInCdImage || !LoadModelSafe(m, 1500))
			{
				continue;
			}
			Crumbs.Native("checkpoint prop");
			int num = OBJECT.CREATE_OBJECT((uint)m.Hash, at.X, at.Y, at.Z, p4: false, p5: false, p6: false, p7: false, p8: true);
			STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)m.Hash);
			if (num != 0)
			{
				OBJECT.PLACE_OBJECT_ON_GROUND_PROPERLY(num, p1: false);
				ENTITY.SET_ENTITY_HEADING(num, heading);
				if (freeze)
				{
					ENTITY.FREEZE_ENTITY_POSITION(num, p1: true);
				}
				ENTITY.SET_ENTITY_AS_MISSION_ENTITY(num, p1: true, p2: true);
				if (cache == null)
				{
					GrudgeLog("CHECKPOINT prop model: " + text);
				}
				cache = text;
				return num;
			}
		}
		if (_propMissLogged.Add(models[0]))
		{
			GrudgeLog("CHECKPOINT none of these props could be made: " + string.Join(", ", models));
		}
		return 0;
	}

	private static string CompassTo(Vector3 from, Vector3 to)
	{
		double num = (Math.Atan2(to.X - from.X, to.Y - from.Y) * 180.0 / Math.PI + 360.0) % 360.0;
		return (new string[8] { "north", "north-east", "east", "south-east", "south", "south-west", "west", "north-west" })[(int)Math.Round(num / 45.0) % 8];
	}

	private Kid KidFor(Ped p)
	{
		if (p == null || !p.Exists())
		{
			return null;
		}
		if (_kids.TryGetValue(p.Handle, out var value))
		{
			value.SeenAt = Game.GameTime;
			return value;
		}
		Random random = new Random(p.Handle ^ 0x5EED17);
		bool flag = !Models.Female((uint)p.Model.Hash);
		string text = null;
		try
		{
			text = TownAt(p.Position);
		}
		catch
		{
		}
		string[] array = ((text != null && TownWork.TryGetValue(text, out var value2)) ? value2 : AnyWork);
		string text2 = array[random.Next(array.Length)];
		string text3 = (flag ? "his" : "her");
		string text4 = (flag ? "he" : "she");
		string text5 = NameBank.AmericanLast[random.Next(NameBank.AmericanLast.Length)];
		Kid kid = new Kid();
		kid.Boy = flag;
		kid.Age = 5 + random.Next(10);
		kid.SeenAt = Game.GameTime;
		kid.Temper = (new string[7] { "Hothead", "Proud", "Cold", "Coward", "Greedy", "Loyal", "Drifter" })[random.Next(7)];
		kid.Name = (flag ? BoyNames[random.Next(BoyNames.Length)] : GirlNames[random.Next(GirlNames.Length)]) + " " + text5;
		kid.Home = (new string[9]
		{
			Cap(text3) + " pa works " + text2,
			Cap(text3) + " ma works " + text2,
			"Lives above " + text2 + " with " + text3 + " folks",
			Cap(text3) + " folks farm outside " + (text ?? "town"),
			"An orphan - sleeps in the hayloft at the livery",
			"Lives with " + text3 + " grandmother by the river",
			Cap(text3) + " pa is a deputy",
			"Helps " + text3 + " ma take in washing",
			Cap(text3) + " pa went west for work and hasn't written"
		})[random.Next(9)];
		kid.Quirk = (new string[10]
		{
			"Keeps a frog in " + text3 + " pocket",
			"Sells newspapers on the corner",
			"Can't read yet - pretends " + text4 + " can",
			"Collects arrowheads",
			"Knows every horse in town by name",
			"Never wears shoes",
			"Has a slingshot " + text4 + " isn't supposed to have",
			"Draws on everything with charcoal",
			"Saves every penny " + text4 + " finds",
			"Talks to the dogs more than to people"
		})[random.Next(10)];
		kid.Want = (new string[10]
		{
			"wants to be a cowboy",
			"wants to be a lawman",
			"wants to drive a train",
			"wants to be a gunslinger like in the dime novels",
			"wants to be a doctor",
			"wants to see the ocean",
			"wants a horse of " + text3 + " own",
			"is saving up for a harmonica",
			"wants to be a trick rider in a show",
			"wants to go to school in the city"
		})[random.Next(10)];
		value = kid;
		if (_kids.Count >= 60)
		{
			int num = (from kv in _kids
				orderby kv.Value.Met ? 1 : 0, kv.Value.SeenAt
				select kv.Key).FirstOrDefault();
			if (num != 0)
			{
				_kids.Remove(num);
			}
		}
		_kids[p.Handle] = value;
		return value;
	}

	private void MeetKid(int handle, Kid k)
	{
		if (k == null)
		{
			return;
		}
		k.SeenAt = Game.GameTime;
		if (!k.Met)
		{
			k.Met = true;
			try
			{
				SetPromptName(handle, k.Name);
			}
			catch
			{
			}
			Feed($"CHILD {k.Name}, {k.Age} ({k.Temper.ToLowerInvariant()}). {k.Home}. {k.Quirk}. {Cap(k.Want)}.", Theme.Dim);
			GrudgeLog("CHILD met " + k.Name + " (" + k.Short + "): " + k.Home + "; " + k.Quirk + "; " + k.Want);
		}
	}

	private bool ChildPed(int handle, out Ped p)
	{
		p = Entity.FromHandle(handle) as Ped;
		if (p != null && p.Exists() && p.IsHuman && !p.IsPlayer && Kids.IsChild(p))
		{
			return !IsStoryPed(p);
		}
		return false;
	}

	private void ForgetKids()
	{
		foreach (KeyValuePair<int, Kid> item in _kids.ToList())
		{
			bool num = !ENTITY.DOES_ENTITY_EXIST(item.Key) || ENTITY.IS_ENTITY_DEAD(item.Key);
			int num2 = (item.Value.Met ? 1800000 : 120000);
			if (num || Game.GameTime - item.Value.SeenAt > num2)
			{
				_kids.Remove(item.Key);
			}
		}
	}

	internal bool IsCompanionReal(int h)
	{
		return _comps.Any((Companion c) => c.IsReal && c.Ped != null && c.Ped.Exists() && c.Ped.Handle == h);
	}

	private bool IsCompPed(Companion c, int h)
	{
		if (!(c.Ped != null) || !c.Ped.Exists() || c.Ped.Handle != h)
		{
			if (c.Real != null && c.Real.Exists())
			{
				return c.Real.Handle == h;
			}
			return false;
		}
		return true;
	}

	internal bool IsCompanion(int h)
	{
		return _comps.Any((Companion c) => c.State != 2 && IsCompPed(c, h));
	}

	internal string CompanionName(int h)
	{
		return _comps.FirstOrDefault((Companion c) => IsCompPed(c, h))?.Name;
	}

	internal bool IsCompanionKiller(int src)
	{
		if (src != 0)
		{
			return _comps.Any((Companion c) => c.State == 1 && c.Ped != null && c.Ped.Exists() && c.Ped.Handle == src);
		}
		return false;
	}

	internal IEnumerable<Ped> CompanionPeds()
	{
		foreach (Companion c in _comps)
		{
			if (c.Ped != null)
			{
				yield return c.Ped;
			}
			if (c.Horse != null)
			{
				yield return c.Horse;
			}
		}
	}

	private void UpdateCompanion(Ped player)
	{
		if (_companionsOffDone)
		{
			return;
		}
		_companionsOffDone = true;
		try
		{
			if (_comps.Count > 0)
			{
				LetCompanionsGo("riding together is off");
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("COMPANION off: send-home failed: " + ex.Message);
		}
		try
		{
			HideAskPrompt();
		}
		catch
		{
		}
		GrudgeLog("COMPANION riding together is off in this build (Companion.cs CompanionsAvailable)");
	}

	private void MissionGiverNear(Ped player)
	{
		if (Game.GameTime < _nextGiverScan || !_comps.Any((Companion c) => c.State == 1))
		{
			return;
		}
		_nextGiverScan = Game.GameTime + 1000;
		if (AtGangCamp(player))
		{
			return;
		}
		HashSet<int> hashSet = new HashSet<int>(from c in _comps
			where c.Ped != null && c.Ped.Exists()
			select c.Ped.Handle);
		Vector3 position = player.Position;
		Ped ped = null;
		string who = null;
		foreach (var (ped2, vector) in PedSnapshot(player))
		{
			if (!(ped2 == null) && !((vector - position).Length() >= 45f) && !hashSet.Contains(ped2.Handle) && ped2.Exists() && !ped2.IsDead && CampKeyOfModel.TryGetValue((uint)ped2.Model.Hash, out who) && !IsOurs(ped2.Handle))
			{
				ped = ped2;
				break;
			}
		}
		if (ped == null)
		{
			return;
		}
		who = who ?? "someone";
		string text = StoryRoster.FirstOrDefault((NemesisRecord r) => r.Id == "vdl_" + who)?.Name ?? who;
		GrudgeLog($"COMPANION mission giver near: {text} ({ped.Position.DistanceTo(player.Position):0} m) - everyone riding with you heads back to camp");
		bool flag = true;
		foreach (Companion item in _comps.Where((Companion c) => c.State == 1).ToList())
		{
			if (flag && item.Ped != null && item.Ped.Exists())
			{
				ShowSubtitle(item.Name.Split(' ')[0] + ": \"" + string.Format(GiverLines[_rng.Next(GiverLines.Length)], text.Split(' ')[0]) + "\"");
			}
			flag = false;
			SendHome(item, text + " has work for you");
		}
	}

	private void UpdateAsk(Ped player)
	{
		if (_menu.IsOpen || _convo != null || _tg != null || player.IsInCombat)
		{
			HideAskPrompt();
			return;
		}
		if (Game.GameTime >= _nextCompScan)
		{
			_nextCompScan = Game.GameTime + 400;
			_askPed = null;
			_askKey = null;
			_askComp = null;
			if (!player.IsOnMount)
			{
				foreach (Companion comp in _comps)
				{
					if (comp.State == 1 && comp.Ped != null && comp.Ped.Exists() && comp.Ped.Position.DistanceTo(player.Position) < 3.2f)
					{
						_askPed = comp.Ped;
						_askKey = comp.Key;
						_askComp = comp;
						break;
					}
				}
			}
			if (_askPed == null && Enumerable.Count(_comps, (Companion c) => c.State != 2) < 3 && AtGangCamp(player))
			{
				Vector3 position = player.Position;
				Dictionary<string, Ped> dictionary = new Dictionary<string, Ped>();
				Ped ped = null;
				foreach (var (ped2, vector) in PedSnapshot(player))
				{
					if (!(ped2 == null) && CampKeyOfModel.TryGetValue((uint)ped2.Model.Hash, out var value))
					{
						if (value == "kieran" && ped == null && ped2.Exists() && !ped2.IsDead)
						{
							ped = ped2;
						}
						if ((vector - position).Length() < 3.4f && ped2.Exists() && !ped2.IsDead && !dictionary.ContainsKey(value))
						{
							dictionary[value] = ped2;
						}
					}
				}
				foreach (KeyValuePair<string, (string, int)> kv in CampPeople)
				{
					if (_comps.Any((Companion c) => c.Key == kv.Key) || StoryCompanionBlock(kv.Key) != null || NeverRide.Contains(kv.Key) || NoRidePrompt.Contains(kv.Key))
					{
						continue;
					}
					if (kv.Key == "kieran" && !_kieranSeenFree)
					{
						Ped ped3 = ped;
						if (ped3 != null && ENTITY.GET_ENTITY_VELOCITY(ped3.Handle, 0).Length() > 0.8f && !ped3.IsHogtied)
						{
							_kieranSeenFree = true;
							GrudgeLog("COMPANION Kieran is walking about camp - free to ride");
						}
					}
					if ((!(kv.Key == "kieran") || !KieranTied) && dictionary.TryGetValue(kv.Key, out var value2) && !(value2.Position.DistanceTo(player.Position) >= 3f) && !IsOurs(value2.Handle))
					{
						_askPed = value2;
						_askKey = kv.Key;
						break;
					}
				}
			}
		}
		Ped askPed = _askPed;
		if (askPed == null || !askPed.Exists() || askPed.Position.DistanceTo(player.Position) > 3.5f)
		{
			HideAskPrompt();
			return;
		}
		bool flag = _askComp != null;
		int num = HUD._UI_PROMPT_GET_GROUP_ID_FOR_TARGET_ENTITY(askPed.Handle);
		if (_pAsk == 0 || !PromptValid(_pAsk) || _pAskFor != askPed.Handle || _pAskGroup != num)
		{
			Crumbs.Native("Companion prompt delete");
			if (PromptValid(_pAsk))
			{
				HUD._UI_PROMPT_DELETE(_pAsk);
			}
			_pAsk = MakePrompt((eInputType)1980406895u, flag ? "Send Home" : "Ride With Me", hold: true, num);
			_pAskFor = askPed.Handle;
			_pAskGroup = num;
		}
		HUD._UI_PROMPT_SET_VISIBLE(_pAsk, p1: true);
		HUD._UI_PROMPT_SET_ENABLED(_pAsk, p1: true);
		HideTalkPrompt();
		if (!HUD._UI_PROMPT_HAS_HOLD_MODE_COMPLETED(_pAsk))
		{
			_askArmed = true;
		}
		else if (_askArmed)
		{
			_askArmed = false;
			Companion askComp = _askComp;
			HideAskPrompt();
			if (flag)
			{
				SendHome(askComp, "you sent him home");
			}
			else
			{
				Ask(askPed, _askKey, player);
			}
		}
	}

	private void HideTalkPrompt()
	{
		if (_pTalk != 0)
		{
			Crumbs.Native("Companion prompt delete");
			if (PromptValid(_pTalk))
			{
				HUD._UI_PROMPT_DELETE(_pTalk);
			}
			_pTalk = 0;
			_pTalkFor = 0;
		}
	}

	private void HideAskPrompt()
	{
		HideTalkPrompt();
		if (_pAsk != 0)
		{
			Crumbs.Native("Companion prompt delete");
			if (PromptValid(_pAsk))
			{
				HUD._UI_PROMPT_DELETE(_pAsk);
			}
			_pAsk = 0;
			_pAskFor = 0;
		}
	}

	private static string Line(Dictionary<string, string[]> pool, string key, Random rng)
	{
		string[] array = (pool.TryGetValue(key ?? "", out var value) ? value : pool[""]);
		return array[rng.Next(array.Length)];
	}

	private void Ask(Ped ped, string key, Ped player)
	{
		NemesisRecord nemesisRecord = StoryRoster.FirstOrDefault((NemesisRecord r) => r.Id == "vdl_" + key);
		string text = nemesisRecord?.Name ?? StoryCast.People.Values.FirstOrDefault((StoryCast.Person p) => p.Name != null && p.Name.ToLowerInvariant().Contains(key))?.Name ?? key;
		string text2 = text.Split(' ')[0];
		TASK.TASK_TURN_PED_TO_FACE_ENTITY(ped.Handle, player.Handle, 1500, 0f, 0f, 0f);
		long num = GameMinutesNow();
		if (CompHurt.TryGetValue(key, out var value) && value > num)
		{
			ShowSubtitle(text2 + ": \"Still healing up from last time, Arthur. Give me a day.\"");
			GrudgeLog($"COMPANION {text} is laid up ({(value - num) / 60}h left)");
			return;
		}
		if (_saidNo.TryGetValue(key, out var value2) && Game.GameTime - value2 < 240000)
		{
			ShowSubtitle(text2 + ": \"" + ((RegardOf(key) < 0) ? "I said no." : "I told you, Arthur - not now.") + "\"");
			return;
		}
		List<Companion> list = _comps.Where((Companion c) => c.State != 2).ToList();
		bool flag = LoreRiders.Contains(key);
		int num2 = (flag ? ((key == "uncle") ? 50 : 100) : 0);
		bool flag2 = _rng.Next(100) < num2;
		if (!flag)
		{
			NeverRide.Add(key);
			SaveWorld();
		}
		string text3 = ((((list.Count > 0) & flag2) && TieBetween(key, list[0].Key) <= -30) ? (" ...With " + list[0].Name.Split(' ')[0] + "? Fine. Whatever.") : "");
		ShowSubtitle(text2 + ": \"" + Line(flag2 ? Yes : No, key, _rng) + text3 + "\"");
		SayAny(ped, flag2 ? "agree2" : "refuse2", flag2 ? AgreeVoice : RefuseVoice, player);
		GrudgeLog(string.Format("COMPANION asked {0}: {1} ({2}%{3}, {4} already with you)", text, flag2 ? "yes" : "no", num2, flag ? "" : ", doesn't ride - no prompt from now on", list.Count));
		if (!flag2)
		{
			_saidNo[key] = Game.GameTime;
			return;
		}
		Companion companion = new Companion
		{
			Key = key,
			Name = text,
			Model = CampPeople[key].model,
			Rec = nemesisRecord,
			Camp = player.Position,
			State = 0,
			AskedAt = Game.GameTime,
			Real = ped,
			Slot = _comps.Count
		};
		_comps.Add(companion);
		int num3 = PED.GET_PED_GROUP_INDEX(player.Handle);
		PED.SET_PED_AS_GROUP_MEMBER(ped.Handle, num3);
		PED.SET_GROUP_SEPARATION_RANGE(num3, 400f);
		TASK.CLEAR_PED_TASKS(ped.Handle, p1: true, p2: false);
		TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(ped.Handle, player.Handle, 1.2f, -1.5f, 0f, 1.6f, -1, 1.5f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
		GrudgeLog($"COMPANION {text}: the real one follows you from camp (group member: {PED.IS_PED_GROUP_MEMBER(ped.Handle, num3, p2: false)})");
		Adopt(companion, ped, player);
	}

	private int TieBetween(string a, string b)
	{
		return (StoryRoster.FirstOrDefault((NemesisRecord r) => r.Id == "vdl_" + a)?.Ties?.FirstOrDefault((Tie x) => x.Id == "vdl_" + b))?.Strength ?? 0;
	}

	private void WaitToJoin(Companion c, Ped player)
	{
		Ped real = c.Real;
		bool flag = real != null && real.Exists() && !real.IsDead;
		if (flag && Game.GameTime >= c.NudgeAt)
		{
			c.NudgeAt = Game.GameTime + 2500;
			float num = real.Position.DistanceTo(player.Position);
			int p = PED.GET_PED_GROUP_INDEX(player.Handle);
			if (!PED.IS_PED_GROUP_MEMBER(real.Handle, p, p2: false))
			{
				PED.SET_PED_AS_GROUP_MEMBER(real.Handle, p);
			}
			if (num > 4f && !TASK.IS_PED_RUNNING(real.Handle) && !TASK.IS_PED_WALKING(real.Handle))
			{
				TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(real.Handle, player.Handle, 1.2f, -1.5f, 0f, (num > 20f) ? 3f : 1.6f, -1, 1.5f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
			}
			if (player.Position.DistanceTo(c.Camp) > 110f && num < 60f && !WorldBusy(player))
			{
				Adopt(c, real, player);
				return;
			}
		}
		if (Game.GameTime - c.AskedAt > 600000)
		{
			GrudgeLog("COMPANION " + c.Name + " gave up waiting");
			ReleaseReal(c);
			_comps.Remove(c);
		}
		else if (!(player.Position.DistanceTo(c.Camp) < 150f) && !WorldBusy(player))
		{
			if (flag)
			{
				GrudgeLog($"COMPANION {c.Name}: the real one stayed {real.Position.DistanceTo(player.Position):0} m back - his copy rides out");
				ReleaseReal(c);
			}
			if (!SpawnCompanion(c, player) && ++c.SpawnFails > 20)
			{
				GrudgeLog("COMPANION " + c.Name + " couldn't be placed - stays in camp");
				_comps.Remove(c);
			}
		}
	}

	private void Adopt(Companion c, Ped ped, Ped player)
	{
		MakeOurs(ped.Handle);
		c.SavedRel = (int)PED.GET_PED_RELATIONSHIP_GROUP_HASH(ped.Handle);
		c.SavedFlags = SavedFlagIds.Select((int f) => Function.Call<bool>(9143768600959694099uL, new InputArgument[3] { ped.Handle, f, true })).ToArray();
		c.SavedMaxHp = ped.MaxHealth;
		c.SavedDamageable = ENTITY._GET_ENTITY_CAN_BE_DAMAGED(ped.Handle);
		c.SavedAccuracy = PED.GET_PED_ACCURACY(ped.Handle);
		c.SavedAttr5 = PED._GET_PED_COMBAT_ATTRIBUTE(ped.Handle, 5);
		c.SavedAttr46 = PED._GET_PED_COMBAT_ATTRIBUTE(ped.Handle, 46);
		try
		{
			Crumbs.Native("Companion outfit read");
			c.RealOutfit = PED._GET_PED_META_OUTFIT_HASH(ped.Handle);
		}
		catch
		{
			c.RealOutfit = 0u;
		}
		c.Saved = true;
		ENTITY.SET_ENTITY_INVINCIBLE(ped.Handle, p1: true);
		c.Ped = ped;
		c.IsReal = true;
		Setup(c, ped, player);
		GrudgeLog("COMPANION " + c.Name + " rides with you (the real one)");
	}

	private bool RealHandsOff(Companion c, Ped p)
	{
		if (!c.IsReal || p == null || !p.Exists())
		{
			return false;
		}
		bool flag = false;
		try
		{
			flag = MISC.GET_MISSION_FLAG();
		}
		catch
		{
		}
		if (!flag)
		{
			return !BelongsToUs(p.Handle);
		}
		return true;
	}

	private void ReleaseReal(Companion c)
	{
		Ped real = c.Real;
		if (!(real == null) && real.Exists())
		{
			bool flag = false;
			try
			{
				flag = MISC.GET_MISSION_FLAG();
			}
			catch
			{
			}
			if (flag || (c.IsReal && !BelongsToUs(real.Handle)))
			{
				c.Real = null;
				return;
			}
			PED.REMOVE_PED_FROM_GROUP(real.Handle);
			TASK.CLEAR_PED_TASKS(real.Handle, p1: true, p2: false);
			c.Real = null;
		}
	}

	private unsafe void Setup(Companion c, Ped ped, Ped player)
	{
		int num = PED.GET_PED_GROUP_INDEX(player.Handle);
		ped.RelationshipGroup = player.RelationshipGroup;
		PED.SET_PED_CONFIG_FLAG(ped.Handle, 130, p2: false);
		PED.SET_PED_CONFIG_FLAG(ped.Handle, 297, p2: true);
		PED.SET_PED_CONFIG_FLAG(ped.Handle, 301, p2: false);
		if (!PED.IS_PED_GROUP_MEMBER(ped.Handle, num, p2: false))
		{
			PED.SET_PED_AS_GROUP_MEMBER(ped.Handle, num);
		}
		PED.SET_PED_CAN_TELEPORT_TO_GROUP_LEADER(ped.Handle, num, p2: false);
		PED.SET_GROUP_SEPARATION_RANGE(num, 400f);
		if (ped.MaxHealth < 400)
		{
			ped.MaxHealth = 400;
			ped.Health = 400;
		}
		PED.SET_PED_ACCURACY(ped.Handle, 55);
		PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 5, p2: true);
		PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 46, p2: true);
		Give((eWeapon)4111948705u, 120, (eWeaponAttachPoint)9, equip: false, left: true);
		Give((eWeapon)379542007u, 60, (eWeaponAttachPoint)2, equip: true, left: false);
		if (c.Key == "charles")
		{
			Give((eWeapon)2292731996u, 20, (eWeaponAttachPoint)7, equip: false, left: true);
		}
		if (c.Horse == null || !c.Horse.Exists())
		{
			Vector3 pos = ped.Position + new Vector3((float)Math.Sin((double)ped.Heading * Math.PI / 180.0) * -3.5f, (float)Math.Cos((double)ped.Heading * Math.PI / 180.0) * -3.5f, 0f);
			int num2 = PED.GET_MOUNT(player.Handle);
			if (num2 == 0)
			{
				num2 = PED._GET_LAST_MOUNT(player.Handle);
			}
			if (num2 != 0 && ENTITY.DOES_ENTITY_EXIST(num2) && !ENTITY.IS_ENTITY_DEAD(num2) && ENTITY.GET_ENTITY_COORDS(num2, p1: true, p2: true).DistanceTo(player.Position) < 120f)
			{
				Vector3 vector = ENTITY.GET_ENTITY_COORDS(num2, p1: true, p2: true);
				float num3 = ENTITY.GET_ENTITY_HEADING(num2) * (float)Math.PI / 180f;
				Vector3 vector2 = new Vector3((float)Math.Cos(num3), (float)Math.Sin(num3), 0f);
				Vector3 vector3 = new Vector3((float)Math.Sin(num3), 0f - (float)Math.Cos(num3), 0f);
				pos = vector + vector2 * (2.2f + 1.8f * (float)c.Slot) + vector3 * (0.8f * (float)c.Slot);
			}
			float z = 0f;
			if (MISC.GET_GROUND_Z_FOR_3D_COORD(pos.X, pos.Y, pos.Z + 2f, &z, p4: false))
			{
				pos.Z = z;
			}
			Ped ped2 = SpawnPed(RiderHorses[_rng.Next(RiderHorses.Length)], pos, ped.Heading);
			if (ped2 != null)
			{
				MakeOurs(ped2.Handle);
				TackUp(ped2);
				c.Horse = ped2;
				Crumbs.Native("Companion onto mount");
				if (player.IsOnMount && !c.IsReal)
				{
					PED.SET_PED_ONTO_MOUNT(ped.Handle, ped2.Handle, -1, p3: true);
				}
				GrudgeLog($"COMPANION {c.Name}: his horse is ready ({pos.DistanceTo(ped.Position):0.0} m from him, {pos.DistanceTo(player.Position):0} m from you)");
			}
		}
		if (c.Blip == null || !c.Blip.Exists())
		{
			Crumbs.Native("Companion blip add (V2)");
			c.Blip = ped.AddBlip((BlipType)4205537449u);
			if (c.Blip != null)
			{
				Function.Call(11290983183885202434uL, c.Blip.Handle, new InputArgument(UiDraw.ForeverVarString(c.Name)));
			}
		}
		c.State = 1;
		c.Since = GameMinutesNow();
		c.NextChat = Game.GameTime + 40000 + _rng.Next(40000);
		c.MaskOn = false;
		c.MaskAdded = 0u;
		Feed("COMPANION " + c.Name + " rides with you", Theme.Good);
		void Give(eWeapon w, int ammo, eWeaponAttachPoint at, bool equip, bool left)
		{
			if (!c.IsReal || !Function.Call<bool>(10226742572059207868uL, new InputArgument[4]
			{
				ped.Handle,
				(uint)w,
				0,
				false
			}))
			{
				ped.GiveWeapon(w, ammo, at, equip, left, a6: false);
				if (c.IsReal)
				{
					c.AddedWeapons.Add((uint)w);
				}
			}
		}
	}

	private bool SpawnCompanion(Companion c, Ped player)
	{
		Vector3 vector = OutOfSightSpot(player, 35f, 60f, ahead: false, allowSeen: true);
		if (vector == Vector3.Zero)
		{
			return false;
		}
		Model m = new Model(MISC.GET_HASH_KEY(c.Model));
		if (!m.IsValid || !m.IsPed)
		{
			GrudgeLog("COMPANION model " + c.Model + " not found");
			_comps.Remove(c);
			return false;
		}
		if (!LoadModelSafe(m, 3000))
		{
			return false;
		}
		Ped ped = SpawnPed((PedHash)m.Hash, vector, player.Heading);
		STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)m.Hash);
		if (ped == null)
		{
			return false;
		}
		NoteModel(ped);
		MakeOurs(ped.Handle);
		Crumbs.Native("Companion prompt name");
		Function.Call(5352729231319872684uL, ped.Handle, UiDraw.ForeverString(c.Name));
		c.Ped = ped;
		c.IsReal = false;
		if (c.Horse != null && c.Horse.Exists() && !c.Horse.IsDead)
		{
			c.Horse.Position = vector + new Vector3(2.5f, 0f, 0f);
		}
		Setup(c, ped, player);
		Crumbs.Native("Companion onto mount");
		if (player.IsOnMount && c.Horse != null && c.Horse.Exists())
		{
			PED.SET_PED_ONTO_MOUNT(ped.Handle, c.Horse.Handle, -1, p3: true);
		}
		GrudgeLog(string.Format("COMPANION {0} joined you at {1:0},{2:0} ({3}, {4:0} m back)", c.Name, vector.X, vector.Y, player.IsOnMount ? "mounted" : "on foot", vector.DistanceTo(player.Position)));
		return true;
	}

	private unsafe void Ride(Companion c, Ped player)
	{
		Ped ped = c.Ped;
		if (ped == null || !ped.Exists())
		{
			if (c.Swaps < 3 && !WorldBusy(player))
			{
				c.Swaps++;
				c.Ped = null;
				c.IsReal = false;
				if (SpawnCompanion(c, player))
				{
					GrudgeLog("COMPANION " + c.Name + ": the game took the real one - his copy rides on");
					return;
				}
			}
			GrudgeLog("COMPANION " + c.Name + "'s ped is gone");
			Cleanup(c);
			_comps.Remove(c);
			return;
		}
		float num = player.Position.DistanceTo(c.Camp);
		if (!c.LeftCamp && num > 130f)
		{
			c.LeftCamp = true;
			GrudgeLog("COMPANION " + c.Name + " left camp with you");
		}
		if (c.LeftCamp && num < 90f)
		{
			SendHome(c, "back at camp");
			return;
		}
		if (ped.IsDead || (float)ped.Health < (float)ped.MaxHealth * 0.3f)
		{
			ENTITY.SET_ENTITY_INVINCIBLE(ped.Handle, p1: true);
			ShowSubtitle(c.Name.Split(' ')[0] + ": \"" + HurtLines[_rng.Next(HurtLines.Length)] + "\"");
			CompHurt[c.Key] = GameMinutesNow() + 1440;
			PED.REMOVE_PED_FROM_GROUP(ped.Handle);
			if (c.IsReal)
			{
				HeadHome(c, 3f);
			}
			else
			{
				Flee(ped, player, 200f, -1, 3f);
			}
			c.State = 2;
			c.LeaveAt = Game.GameTime;
			if (c.Blip != null && c.Blip.Exists())
			{
				c.Blip.Delete();
			}
			GrudgeLog("COMPANION " + c.Name + " was hurt - laid up for a day");
			Feed("COMPANION " + c.Name + " was hurt and rode back to camp", Theme.Warn);
			Chronicle_Ride(c, hurt: true);
			return;
		}
		Crumbs.Mark("companion " + c.Key + " fight");
		CompanionFight(c, player);
		Crumbs.Mark("companion " + c.Key + " ride");
		if (Game.GameTime >= c.RideAt)
		{
			c.RideAt = Game.GameTime + 1500;
			float num2 = ped.Position.DistanceTo(player.Position);
			bool flag = ped.IsInCombat || player.IsInCombat;
			if (c.Horse != null && c.Horse.Exists() && !c.Horse.IsDead && !flag)
			{
				bool flag2 = !ped.IsOnMount && PED.GET_MOUNT(ped.Handle) == 0;
				if (flag2 && c.WasRiding && Game.GameTime - c.DismountOrderedAt > 4000)
				{
					GrudgeLog(Pron.Her(string.Format("COMPANION {0}: came off his horse - not our order ({1}, you {2}, {3:0} m, horse {4})", c.Name, ped.IsRagdoll ? "ragdoll: a fall" : "no ragdoll", player.IsOnMount ? "riding" : "on foot", ped.Position.DistanceTo(player.Position), c.Horse.IsDead ? "dead" : $"{c.Horse.Position.DistanceTo(ped.Position):0} m from him"), !PED.IS_PED_MALE(ped.Handle)));
				}
				c.WasRiding = !flag2;
				if (!flag2)
				{
					c.OffHorseSince = -1;
				}
				else if (c.OffHorseSince < 0)
				{
					c.OffHorseSince = Game.GameTime;
				}
				if ((player.IsOnMount & flag2) && Game.GameTime - c.OffHorseSince > 2000)
				{
					if (Game.GameTime >= c.MountAt)
					{
						c.MountAt = Game.GameTime + 8000;
						float num3 = c.Horse.Position.DistanceTo(ped.Position);
						if (num3 > 40f)
						{
							Vector3 vector = ped.Position + new Vector3((float)Math.Sin((double)ped.Heading * Math.PI / 180.0) * -4f, (float)Math.Cos((double)ped.Heading * Math.PI / 180.0) * -4f, 0f);
							float z = 0f;
							if (MISC.GET_GROUND_Z_FOR_3D_COORD(vector.X, vector.Y, vector.Z + 2f, &z, p4: false))
							{
								vector.Z = z;
							}
							if (!ScreenSees(vector))
							{
								c.Horse.Position = vector;
							}
							else
							{
								TASK.TASK_GO_TO_ENTITY(c.Horse.Handle, ped.Handle, -1, 3f, 2.5f, 0f, 0);
							}
							GrudgeLog($"COMPANION {c.Name}: his horse was {num3:0} m off - it comes to him");
						}
						TASK.TASK_MOUNT_ANIMAL(ped.Handle, c.Horse.Handle, 20000, -1, 2f, 1, 0uL, 0uL);
						GrudgeLog($"COMPANION {c.Name}: you mounted - he goes for his horse ({c.Horse.Position.DistanceTo(ped.Position):0} m)");
					}
				}
				else if (!player.IsOnMount && ped.IsOnMount && num2 < 15f && _youOffSince > 0 && Game.GameTime - _youOffSince > 2500)
				{
					TASK.TASK_DISMOUNT_ANIMAL(ped.Handle, 0, 0uL, 0uL, 0uL, 0);
					c.DismountOrderedAt = Game.GameTime;
					GrudgeLog($"COMPANION {c.Name}: you got down - he gets down too ({num2:0} m)");
				}
				if (player.IsOnMount && ped.IsOnMount && num2 > 25f && Game.GameTime >= c.FollowAt)
				{
					c.FollowAt = Game.GameTime + 10000;
					(float, float) tuple = RideSlots[Math.Min(RideSlots.Length - 1, Math.Max(0, c.Slot))];
					TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(ped.Handle, player.Handle, tuple.Item1, tuple.Item2, 0f, (num2 > 40f) ? 4f : 2.5f, -1, 3f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
				}
			}
			if (num2 > 180f && !flag)
			{
				Vector3 vector2 = OutOfSightSpot(player, 35f, 60f, ahead: false, allowSeen: true);
				if (vector2 != Vector3.Zero)
				{
					if (ped.IsOnMount && c.Horse != null && c.Horse.Exists())
					{
						c.Horse.Position = vector2;
						ped.Position = vector2 + new Vector3(0f, 0f, 1f);
						Crumbs.Native("Companion onto mount");
						PED.SET_PED_ONTO_MOUNT(ped.Handle, c.Horse.Handle, -1, p3: true);
					}
					else
					{
						ped.Position = vector2;
					}
					GrudgeLog($"COMPANION {c.Name} caught up (was {num2:0} m behind)");
				}
			}
		}
		if (Game.GameTime >= c.NextChat)
		{
			bool flag3 = player.IsInCombat || ped.IsInCombat;
			c.NextChat = Game.GameTime + (flag3 ? (12000 + _rng.Next(10000)) : (70000 + _rng.Next(70000)));
			if (ped.Position.DistanceTo(player.Position) < 25f && Game.GameTime >= _banterBusyUntil)
			{
				ShowSubtitle(c.Name.Split(' ')[0] + ": \"" + (flag3 ? FightLines[_rng.Next(FightLines.Length)] : Line(Chat, c.Key, _rng)) + "\"");
			}
		}
		Crumbs.Mark("companion " + c.Key + " idle");
		CompanionIdle(c, player);
	}

	private unsafe void CompanionFight(Companion c, Ped player)
	{
		if (Game.GameTime < c.FightAt)
		{
			return;
		}
		c.FightAt = Game.GameTime + 800;
		Ped ped = c.Ped;
		if (Game.GameTime >= _threatScanAt)
		{
			_threatScanAt = Game.GameTime + 800;
			_threatNear = player.IsInCombat || PedsAround(player).Any((Ped p) => p != null && p.Exists() && !p.IsDead && p.IsHuman && !IsOurs(p.Handle) && p.Position.DistanceTo(player.Position) < 100f && PED.IS_PED_IN_COMBAT(p.Handle, player.Handle));
		}
		int num = 0;
		if (GunMelee.PlayerFiredRecently && PLAYER.GET_ENTITY_PLAYER_IS_FREE_AIMING_AT(Game.Player.Handle, &num) && num != 0 && num != c.LastTarget && ENTITY.IS_ENTITY_A_PED(num) && !ENTITY.IS_ENTITY_DEAD(num) && !IsOurs(num) && PED.IS_PED_HUMAN(num) && (!ENTITY.IS_ENTITY_A_MISSION_ENTITY(num) || BelongsToUs(num)) && !GameNamed(Models.Name(ENTITY.GET_ENTITY_MODEL(num))))
		{
			c.LastTarget = num;
			TASK.TASK_COMBAT_PED(ped.Handle, num, 0, 16);
			GrudgeLog($"COMPANION {c.Name}: takes your target (ped {num})");
		}
		else if (_threatNear && !PED.IS_PED_IN_COMBAT(ped.Handle, 0))
		{
			PED.REGISTER_HATED_TARGETS_AROUND_PED(ped.Handle, 120f);
			TASK.TASK_COMBAT_HATED_TARGETS_AROUND_PED(ped.Handle, 120f, 0, 0uL);
			if (!c.WasFighting)
			{
				GrudgeLog("COMPANION " + c.Name + ": into the fight");
			}
			c.WasFighting = true;
		}
		else if (!_threatNear)
		{
			c.WasFighting = false;
			c.LastTarget = 0;
		}
	}

