	private void GoingHome(Companion c, Ped player)
	{
		int num;
		int num2;
		if (!(c.Ped == null))
		{
			num = ((!c.Ped.Exists()) ? 1 : 0);
			if (num == 0)
			{
				num2 = ((c.Ped.Position.DistanceTo(player.Position) > 120f) ? 1 : 0);
				goto IL_0045;
			}
		}
		else
		{
			num = 1;
		}
		num2 = 0;
		goto IL_0045;
		IL_0045:
		bool flag = (byte)num2 != 0;
		if (((uint)num | (flag ? 1u : 0u)) != 0 || Game.GameTime - c.LeaveAt > 20000)
