	internal static string TextHash(string s)
	{
		using SHA1 sHA = SHA1.Create();
		return BitConverter.ToString(sHA.ComputeHash(Encoding.UTF8.GetBytes(s ?? ""))).Replace("-", "");
	}

	internal void RefreshBuiltIn(string path, string builtIn)
	{
		string path2 = path + ".builtin";
		try
		{
			if (!File.Exists(path))
			{
				SafeFile.Write(path, builtIn);
				File.WriteAllText(path2, TextHash(builtIn));
				return;
			}
			string text = File.ReadAllText(path);
			string text2 = TextHash(text);
			string text3 = (File.Exists(path2) ? File.ReadAllText(path2).Trim() : null);
			if (text == builtIn)
			{
				if (text3 != text2)
				{
					File.WriteAllText(path2, text2);
				}
			}
			else if (text3 == null || !(text3 != text2))
			{
				File.Copy(path, path + ".before-update-" + DateTime.Now.ToString("yyyyMMdd-HHmmss"), overwrite: true);
				SafeFile.Write(path, builtIn);
				File.WriteAllText(path2, TextHash(builtIn));
				GrudgeLog("CONTENT " + Path.GetFileName(path) + ": the built-in content changed - file updated (old copy kept as .before-update-*)");
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("CONTENT " + Path.GetFileName(path) + ": built-in refresh failed - " + ex.Message);
		}
	}

	private int LoadOrWrite<T>(string path, Func<T> export, Func<T, int> import) where T : class
	{
		T val = null;
		string text = null;
		try
		{
			val = export();
			text = JsonConvert.SerializeObject(val, Formatting.Indented, new JsonSerializerSettings
			{
				NullValueHandling = NullValueHandling.Ignore,
				DefaultValueHandling = DefaultValueHandling.Ignore
			});
		}
		catch (Exception ex)
		{
			GrudgeLog("CONTENT " + Path.GetFileName(path) + ": built-in export failed - " + ex.Message);
		}
		try
		{
			if (text != null)
			{
				RefreshBuiltIn(path, text);
			}
			if (File.Exists(path))
			{
				T arg = JsonConvert.DeserializeObject<T>(File.ReadAllText(path));
				int num = import(arg);
				if (num > 0)
				{
					return num;
				}
				GrudgeLog("CONTENT " + Path.GetFileName(path) + " had nothing usable - built-in content used");
			}
			else if (text != null)
			{
				SafeFile.Write(path, text);
			}
		}
		catch (Exception ex2)
		{
			KeepBadFile(path, ex2);
		}
		if (val == null)
		{
			return 0;
		}
		try
		{
			return import(val);
		}
		catch (Exception ex3)
		{
			GrudgeLog("CONTENT " + Path.GetFileName(path) + ": the built-in content failed to load too - " + ex3.Message);
			return 0;
		}
	}

	private static TalesContent ExportTales()
	{
		TalesContent talesContent = new TalesContent
		{
			Lore = LoreRows.ToList()
		};
		foreach (KeyValuePair<string, (string, string, string[], string, int, string)[]> gangTale in GangTales)
		{
			talesContent.Tales[gangTale.Key] = gangTale.Value.Select(((string kind, string title, string[] places, string foe, int heard, string line) t) => new TaleRow
			{
				Kind = t.kind,
				Title = t.title,
				Places = t.places.ToList(),
				Foe = t.foe,
				HeardPercent = t.heard,
				Line = t.line
			}).ToList();
		}
		return talesContent;
	}

	private static int ImportTales(TalesContent c)
	{
		if (c == null)
		{
			return 0;
		}
		int num = 0;
		if (c.Lore != null)
		{
			c.Lore.RemoveAll((LoreRow r) => r == null);
		}
		if (c.Lore != null && c.Lore.Count > 0)
		{
			LoreRows = c.Lore;
			num += c.Lore.Count;
		}
		FixLore(LoreRows);
		if (c.Tales != null)
		{
			foreach (KeyValuePair<string, List<TaleRow>> item in c.Tales.Where((KeyValuePair<string, List<TaleRow>> kv) => kv.Key != null && kv.Value != null && kv.Value.Any((TaleRow t) => t != null)))
			{
				GangTales[item.Key] = (from t in item.Value
					where t != null && !string.IsNullOrEmpty(t.Title)
					select (t.Kind ?? "RAID", Title: t.Title, (t.Places ?? new List<string>()).DefaultIfEmpty("the backcountry").ToArray(), Foe: t.Foe, HeardPercent: t.HeardPercent, t.Line ?? "")).ToArray();
				num += item.Value.Count;
			}
		}
		return num;
	}

	private static string SaidText(Convo c)
	{
		if (c.Kind != ConvoKind.Interrogate || !((c.It?.Gang?.Id ?? c.Rec?.Gang) == Gangs.NightFolk.Id))
		{
			return "\"" + c.Line + "\"";
		}
		string text = NightFolkSilence[(uint)(c.Line ?? "").GetHashCode() % (uint)NightFolkSilence.Length];
		if (!text.StartsWith("*"))
		{
			return "\"" + text + "\"";
		}
		return text;
	}

	private static string Pick(string[] lines, Random rng)
	{
		return lines[rng.Next(lines.Length)];
	}

	private void StartConvo(ConvoKind kind, Ped ped, NemesisRecord rec, Interrogation it = null)
	{
		HiddenSlip(rec, "questioned");
		Convo convo = new Convo
		{
			Kind = kind,
			Ped = ped,
			Rec = rec,
			It = it
		};
		Ped character = Game.Player.Character;
		InterroLines.PlayerName = ((Models.Name(character) == "player_three") ? "John Marston" : "Arthur Morgan");
		ped.BlockPermanentEvents = true;
		TASK.TASK_LOOK_AT_ENTITY(ped.Handle, character.Handle, -1, 0, 0, 0);
		Personality personality = rec.Personality ?? Personality.Cold;
		if (kind == ConvoKind.Interrogate)
		{
			convo.Line = InterroLines.Pick((it != null && it.Terror >= 50f) ? "open_scared" : "open", it?.Gang ?? Gangs.ById(rec.Gang), it?.Temper ?? rec.Personality, _rng, null, null, LeaderOut(it?.Gang ?? Gangs.ById(rec.Gang), it?.Rec ?? rec)) ?? (personality switch
			{
				Personality.Hothead => "You're a dead man, you hear me? DEAD.", 
				Personality.Proud => "Get your hands off me.", 
				Personality.Coward => "W-what do you want? I don't know nothin'!", 
				_ => "...What.", 
			});
		}
		_convo = convo;
		BuildOptions(convo);
		GrudgeLog($"CONVO {kind} with {rec.Name} ({rec.Personality}, hate {rec.Hate}, fear {EffectiveFear(rec)})");
		Feed($"INTERROGATION {rec.Name}: conversation opened  (hate {rec.Hate}, fear {EffectiveFear(rec)}, {rec.Personality})", Theme.Gold);
	}

	private static int Clamp(int v, int lo = 5, int hi = 92)
	{
		return Math.Max(lo, Math.Min(hi, v));
	}

	private void BuildOptions(Convo c)
	{
		if (c.EndAt >= 0)
		{
			c.Options.Clear();
			return;
		}
		string keepKey = ((c.Sel >= 0 && c.Sel < c.Options.Count) ? c.Options[c.Sel].Key : null);
		NemesisRecord rec = c.Rec;
		rec.Touch();
		_ = rec.Personality ?? Personality.Cold;
		EffectiveFear(rec);
		Math.Max(rec.YourNotoriety, NotorietyOf(Gangs.ById(rec.Gang)));
		c.Options.Clear();
		BuildInterroOptions(c);
		foreach (string u in c.Used)
		{
			c.Options.RemoveAll((ConvoOption x) => x.Key == u);
		}
		int num = ((keepKey != null) ? c.Options.FindIndex((ConvoOption o) => o.Key == keepKey) : (-1));
		if (num >= 0)
		{
			c.Sel = num;
		}
		else if (keepKey == "ibribe")
		{
			c.Sel = Math.Max(0, c.Options.FindIndex((ConvoOption o) => o.Key == "ithreat") - 1);
		}
		c.Sel = Math.Max(0, Math.Min(c.Sel, c.Options.Count - 1));
		ConvoNote = $"{c.Kind}: " + string.Join("  ", c.Options.Select((ConvoOption x) => x.Key + " " + ((x.Odds >= 0) ? (x.Odds + "%") : "-") + (x.Enabled ? "" : "(x)")));
	}

	private bool HandleConvoKey(Keys key)
	{
		Convo convo = _convo;
		if (convo == null || convo.EndAt >= 0)
		{
			return convo != null;
		}
		int num = -1;
		switch (key)
		{
		case Keys.Up:
			convo.Sel = (convo.Sel - 1 + convo.Options.Count) % convo.Options.Count;
			return true;
		case Keys.Down:
			convo.Sel = (convo.Sel + 1) % convo.Options.Count;
			return true;
		case Keys.Return:
			num = convo.Sel;
			break;
		case Keys.Right:
			if (convo.Kind == ConvoKind.Interrogate && convo.Sel < convo.Options.Count && convo.Options[convo.Sel].Cat && !convo.Options[convo.Sel].Open && convo.Options[convo.Sel].Enabled)
			{
				ToggleCategory(convo, convo.Options[convo.Sel].Key.Substring(4), true);
			}
			return true;
		case Keys.Left:
			if (convo.Kind == ConvoKind.Interrogate && convo.It?.OpenCat != null)
			{
				ToggleCategory(convo, convo.It.OpenCat, false);
			}
			return true;
		case Keys.D1:
		case Keys.D2:
		case Keys.D3:
		case Keys.D4:
		case Keys.D5:
		case Keys.D6:
		case Keys.D7:
		case Keys.D8:
		case Keys.D9:
			num = (int)(key - 49);
			break;
		case Keys.Back:
			if (convo.Kind == ConvoKind.Interrogate)
			{
				Feed("INTERROGATION " + convo.Rec.Name + ": you closed it", Theme.Dim, convo.It?.Rec);
				EndConvo("closed");
				return true;
			}
			return true;
		default:
			return false;
		}
		if (num >= 0 && num < convo.Options.Count && (convo.Options[num].Enabled || convo.Options[num].Cat))
		{
			Choose(convo, convo.Options[num]);
		}
		return true;
	}

	private bool Roll(ConvoOption o)
	{
		if (o.Odds >= 0)
		{
			return _rng.Next(100) < o.Odds;
		}
		return true;
	}

	private void Choose(Convo c, ConvoOption o)
	{
		ChooseInterro(c, o);
	}

	private void Close(Convo c, bool walkAway = false, bool flee = false, bool fight = false)
	{
		c.EndAt = Game.GameTime + 2200;
		c.Options.Clear();
		ref string convoAfter = ref _convoAfter;
		string text;
		if (fight)
		{
			text = "fight";
		}
		else if (flee)
		{
			text = "flee";
		}
		else
		{
			text = (walkAway ? "walk" : "none");
		}
		convoAfter = text;
	}

	private void EndConvo(string why)
	{
		Convo convo = _convo;
		_convo = null;
		if (convo == null)
		{
			return;
		}
		_convoClosedAt = Game.GameTime;
		_upLatchAfterClose = true;
		GrudgeLog("CONVO end (" + why + ", then " + _convoAfter + ")");
		if (convo.Ped != null && convo.Ped.Exists())
		{
			convo.Ped.BlockPermanentEvents = StaysBlocked(convo.Ped);
		}
		if (convo.Kind == ConvoKind.Interrogate)
		{
			_convoAfter = "none";
			if (_interro != null)
			{
				EndInterrogation(released: true, why != "respawn" && why != "interrupted");
			}
			return;
		}
		Ped character = Game.Player.Character;
		if (!convo.Ped.Exists() || convo.Ped.IsDead)
		{
			return;
		}
		TASK.TASK_CLEAR_LOOK_AT(convo.Ped.Handle);
		string text = ((why == "leave") ? "walk" : _convoAfter);
		_convoAfter = "none";
		if (!(text == "fight"))
		{
			if (text == "flee")
			{
				TASK.CLEAR_PED_TASKS(convo.Ped.Handle, p1: true, p2: true);
				Flee(convo.Ped.Handle, character.Handle, 150f, -1, 3f);
				EndPeacefully(convo);
			}
			else
			{
				TASK.CLEAR_PED_TASKS(convo.Ped.Handle, p1: true, p2: true);
				TASK.TASK_WANDER_STANDARD(convo.Ped.Handle, 10f, 10);
				EndPeacefully(convo);
			}
			return;
		}
		TownMan townMan = TownManFor(convo.Ped.Handle);
		if (townMan != null)
		{
			EngageTownMan(townMan, character);
			return;
		}
		if (_activeNemesisPed != null && convo.Ped.Handle == _activeNemesisPed.Handle && _enc != null)
		{
			EngageEncounter(character, blip: true);
			return;
		}
		if (_nemesisGroup == 0)
		{
			_nemesisGroup = World.AddRelationshipGroup("NEMESIS_GROUP");
		}
		convo.Ped.RelationshipGroup = _nemesisGroup;
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _nemesisGroup, character.RelationshipGroup);
		ArmForHate(convo.Ped, convo.Rec, drawNow: true);
		TASK.TASK_COMBAT_PED(convo.Ped.Handle, character.Handle, 0, 16);
	}

	private void EndPeacefully(Convo c)
	{
		if (_activeNemesisPed != null && c.Ped.Handle == _activeNemesisPed.Handle)
		{
			World.SetRelationshipBetweenGroups((eRelationshipType)3, _nemesisGroup, Game.Player.Character.RelationshipGroup);
			BandFromEncounter();
			_encEnd = ("BACKED OFF", "it ended without a fight");
			EndEncounter();
			ReleaseActive();
		}
	}

	private void UpdateConvo(Ped player)
	{
		Convo convo = _convo;
		AfterPanelControls();
		if (convo == null)
		{
			return;
		}
		if (!convo.Ped.Exists() || convo.Ped.IsDead || player.IsDead || convo.Ped.Position.DistanceTo(player.Position) > 15f)
		{
			_convoAfter = "none";
			EndConvo("broken off");
			return;
		}
		if (convo.EndAt >= 0 && Game.GameTime >= convo.EndAt)
		{
			EndConvo("done");
			return;
		}
		LockPlayerInPlace();
		if (convo.Kind != ConvoKind.Interrogate)
		{
			Game.DisableControlThisFrame((eInputType)130948705u);
			Game.DisableControlThisFrame((eInputType)4165969743u);
		}
		if (convo.Kind == ConvoKind.Interrogate)
		{
			HoldPanelButtons(grappled: false);
			_panelClosedAt = Game.GameTime;
		}
		else
		{
			PAD.DISABLE_ALL_CONTROL_ACTIONS(0);
			PAD.ENABLE_CONTROL_ACTION(0, 2844205919u, p2: true);
			PAD.ENABLE_CONTROL_ACTION(0, 3523508616u, p2: true);
			HUD._UI_PROMPT_DISABLE_PROMPTS_THIS_FRAME();
		}
		UiDraw.FrameReserve = 60;
		DrawConvo(convo);
		if (UiDraw.LastFrameSkipped > 0 && Game.GameTime >= _nextConvoTextLog)
		{
			_nextConvoTextLog = Game.GameTime + 5000;
			GrudgeLog($"TEXT panel open: {UiDraw.LastFrameSlots} text slots last frame, {UiDraw.LastFrameSkipped} texts cut (reserve {UiDraw.FrameReserve})");
		}
	}

	private void AfterPanelControls()
	{
		if (_convo == null && Game.GameTime - _panelClosedAt <= 700)
		{
			PAD.DISABLE_ALL_CONTROL_ACTIONS(0);
			PAD.ENABLE_CONTROL_ACTION(0, 2844205919u, p2: true);
			PAD.ENABLE_CONTROL_ACTION(0, 3523508616u, p2: true);
			PAD.ENABLE_CONTROL_ACTION(0, 4165969743u, p2: true);
		}
	}

	private static void HoldPanelButtons(bool grappled)
	{
		PAD.DISABLE_ALL_CONTROL_ACTIONS(0);
		eInputType[] panelKeep = PanelKeep;
		foreach (eInputType eInputType2 in panelKeep)
		{
			if (grappled || !MeleeKeep.Contains(eInputType2))
			{
				PAD.ENABLE_CONTROL_ACTION(0, (uint)eInputType2, p2: true);
			}
		}
	}

	private List<(string, (int r, int g, int b), bool)> InterroChips(Interrogation it)
	{
		List<(string, (int, int, int), bool)> list = new List<(string, (int, int, int), bool)>();
		if (it.Rec != null && it.Rec.TemperKnown)
		{
			foreach (string item2 in it.Rec.Quirks ?? new List<string>())
			{
				list.Add((Quirks.Label(item2), (170, 150, 220), false));
			}
		}
		if (TooScaredToLie(it))
		{
			list.Add(("TOO SCARED TO LIE", Theme.Good, true));
		}
		foreach (string startTag in it.StartTags)
		{
			list.Add((startTag, (150, 170, 210), false));
		}
		foreach (string item3 in it.ActOrder)
		{
			int num = it.ActCount[item3];
			(int r, int g, int b) tuple;
			switch (item3)
			{
			default:
				tuple = (r: 170, g: 168, b: 160);
				break;
			case "THREATENED":
				tuple = Theme.Gold;
				break;
			case "HIT":
			case "LOOTED":
				tuple = (r: 206, g: 190, b: 140);
				break;
			case "STABBED":
			case "SHOT NEAR HIM":
				tuple = Theme.Warn;
				break;
			case "SHOT":
			case "SAW A KILL":
				tuple = Theme.Blood;
				break;
			}
			(int, int, int) item = tuple;
			list.Add(((num > 1) ? $"{item3}  x{num}" : item3, item, true));
		}
		return list;
	}

	internal static (int r, int g, int b) TemperColor(Personality p)
	{
		return p switch
		{
			Personality.Cold => (r: 170, g: 190, b: 200), 
			Personality.Loyal => (r: 140, g: 180, b: 120), 
			Personality.Greedy => (r: 200, g: 170, b: 90), 
			Personality.Proud => Theme.Gold, 
			Personality.Coward => (r: 150, g: 170, b: 210), 
			Personality.Hothead => Theme.Blood, 
			_ => (r: 180, g: 170, b: 150), 
		};
	}

