	private void OpenCopiesWarning()
	{
		(int, string[]) value = _copiesWarning.Value;
		_copiesWarning = null;
		_copiesNotice = null;
		_welcome.OpenWarning("Two copies of enRAGE", (value.Item1 == 1) ? "Another copy of the mod is installed alongside this one" : $"{value.Item1} other copies of the mod are installed alongside this one", new string[2]
		{
			"Both copies run at once: the menus draw over each other (overlapping text, names off their boxes), and the world is played - and saved - twice. An old copy can overwrite your world with an older format.",
			(value.Item1 == 1) ? "The extra copy is here:" : ("The extra copies are here" + ((value.Item2.Length > 3) ? " (the first 3)" : "") + ":")
		}, string.Join("\n", value.Item2.Take(3)), new string[3] { "Quit the game.", "Delete the extra file above (or the whole folder it's in, if it came from an old zip).", "Keep one copy - the newest - as scripts\\NemesisMod.dll, then start the game again." });
		GrudgeLog("COPIES warning window shown");
	}

	private void CheckOtherCopies()
	{
		Assembly assembly = typeof(NemesisMod).Assembly;
		string text = SafePath(assembly);
		_copyId = $"{Theme.ModVersion}|{text}|{Guid.NewGuid():N}";
		Version version = assembly.GetName().Version;
		bool flag = string.Equals(Path.GetFileName(text), "NemesisMod.dll", StringComparison.OrdinalIgnoreCase) && string.Equals(Path.GetFileName(Path.GetDirectoryName(text) ?? ""), "scripts", StringComparison.OrdinalIgnoreCase);
		bool flag2 = false;
		List<string> list = new List<string>();
		Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
		foreach (Assembly assembly2 in assemblies)
		{
			if (assembly2 != assembly && assembly2.GetName().Name == assembly.GetName().Name)
			{
				list.Add($"{SafePath(assembly2)} (v{assembly2.GetName().Version}, loaded)");
				if (assembly2.GetName().Version > version || (assembly2.GetName().Version == version && !flag && IsMainFile(SafePath(assembly2))))
				{
					flag2 = true;
				}
			}
		}
		try
		{
			string directoryName = Path.GetDirectoryName(text);
			if (!string.IsNullOrEmpty(directoryName))
			{
				foreach (string f in Directory.EnumerateFiles(directoryName, "*.dll", SearchOption.AllDirectories))
				{
					if (string.Equals(Path.GetFullPath(f), Path.GetFullPath(text), StringComparison.OrdinalIgnoreCase))
					{
						continue;
					}
					string text2 = null;
					try
					{
						text2 = AssemblyName.GetAssemblyName(f).Name;
					}
					catch
					{
					}
					if (!(text2 != assembly.GetName().Name))
					{
						if (!list.Any((string o) => o.StartsWith(f, StringComparison.OrdinalIgnoreCase)))
						{
							list.Add(f);
						}
						Version version2 = null;
						try
						{
							version2 = AssemblyName.GetAssemblyName(f).Version;
						}
						catch
						{
						}
						if (version2 != null && (version2 > version || (version2 == version && !flag && IsMainFile(f))))
						{
							flag2 = true;
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("COPIES couldn't look through scripts\\: " + ex.Message);
		}
		if (flag2)
		{
			_standingDown = true;
			GrudgeLog($"COPIES this copy ({text}, v{version}) stands down - a newer copy, or scripts\\NemesisMod.dll, runs instead");
			return;
		}
		if (list.Count == 0)
		{
			GrudgeLog("COPIES only this copy of the mod is here");
		}
		else
		{
			GrudgeLog(string.Format("COPIES {0} other cop{1} of the mod besides {2} - two copies draw over each other:", list.Count, (list.Count == 1) ? "y" : "ies", text));
			foreach (string item in list)
			{
				GrudgeLog("COPIES   " + item);
			}
			string p = list[0].Split(' ')[0];
			_copiesNotice = "enRAGE: another copy of the mod is installed (" + ShortScriptsPath(p) + "). Two copies draw over each other - delete the extra one and press Insert. (Details: grudges.log, COPIES.)";
			_copiesWarning = (list.Count, list.Select((string o) => o.Split(new string[1] { " (v" }, StringSplitOptions.None)[0]).Distinct(StringComparer.OrdinalIgnoreCase).ToArray());
		}
		try
		{
			if (!(AppDomain.CurrentDomain.GetData("enRAGE.active") is string text3) || text3.IndexOf("|" + text + "|", StringComparison.OrdinalIgnoreCase) >= 0 || NewerThan(_copyId, text3))
			{
				AppDomain.CurrentDomain.SetData("enRAGE.active", _copyId);
			}
		}
		catch
		{
		}
	}

	private bool ActiveCopy()
	{
		try
		{
			string text = AppDomain.CurrentDomain.GetData("enRAGE.active") as string;
			bool flag = text == null || text == _copyId;
			if (!flag && !_standingDown)
			{
				_standingDown = true;
				GrudgeLog("COPIES a newer copy runs (" + text + ") - this one (" + _copyId + ") stands down");
			}
			return flag;
		}
		catch
		{
			return true;
		}
	}

	private static bool IsMainFile(string p)
	{
		try
		{
			return string.Equals(Path.GetFileName(p), "NemesisMod.dll", StringComparison.OrdinalIgnoreCase) && string.Equals(Path.GetFileName(Path.GetDirectoryName(p) ?? ""), "scripts", StringComparison.OrdinalIgnoreCase);
		}
		catch
		{
			return false;
		}
	}

	private static bool NewerThan(string a, string b)
	{
		return V(a) > V(b);
		static Version V(string id)
		{
			try
			{
				return new Version(id.Split('|')[0]);
			}
			catch
			{
				return new Version(0, 0);
			}
		}
	}

	private static string SafePath(Assembly a)
	{
		try
		{
			string codeBase = a.CodeBase;
			if (!string.IsNullOrEmpty(codeBase))
			{
				return new Uri(codeBase).LocalPath;
			}
		}
		catch
		{
		}
		try
		{
			return a.Location;
		}
		catch
		{
			return "?";
		}
	}

	private static string ShortScriptsPath(string p)
	{
		int num = p.IndexOf("scripts", StringComparison.OrdinalIgnoreCase);
		if (num < 0)
		{
			return Path.GetFileName(p);
		}
		return p.Substring(num);
	}

	internal void CountYourCrime(string crime)
	{
		if (crime != null)
		{
			Dictionary<string, int> dictionary = Chronicle.YourCrimes ?? (Chronicle.YourCrimes = new Dictionary<string, int>());
			dictionary[crime] = ((!dictionary.TryGetValue(crime, out var value)) ? 1 : (value + 1));
			SaveWorld();
		}
	}

	private static string CrimeBadge(string text)
	{
		string text2 = (text ?? "").ToLowerInvariant();
		if (text2.Contains("horse"))
		{
			return "HORSE THIEF";
		}
		if (text2.Contains("train") || text2.Contains("stage") || text2.Contains("mail") || text2.Contains("coach"))
		{
			return "HOLDUP";
		}
		if (text2.Contains("bank"))
		{
			return "BANK JOB";
		}
		if (text2.Contains("rob") || text2.Contains("stole") || text2.Contains("theft") || text2.Contains("thie"))
		{
			return "ROBBERY";
		}
		if (text2.Contains("kill") || text2.Contains("murder") || text2.Contains("shot"))
		{
			return "KILLING";
		}
		if (text2.Contains("sisika") || text2.Contains("jail") || text2.Contains("prison") || text2.Contains("escape") || text2.Contains("broke out"))
		{
			return "PRISON";
		}
		if (text2.Contains("card") || text2.Contains("cheat"))
		{
			return "CARDS";
		}
		if (text2.Contains("fire") || text2.Contains("burn"))
		{
			return "ARSON";
		}
		if (text2.Contains("cattle") || text2.Contains("rustl"))
		{
			return "RUSTLING";
		}
		return "CRIME";
	}

	internal static (int r, int g, int b) OutcomeColor(string o)
	{
		switch (o)
		{
		default:
			return Theme.Dim;
		case "DISTINGUISHED":
		case "WON":
			return Theme.Good;
		case "WOUNDED":
		case "LOST":
			return Theme.Warn;
		case "KILLED":
			return Theme.Blood;
		}
	}

	internal CrimeProfile CrimeSheet(NemesisRecord n)
	{
		if (_crimeCache != null && _crimeCacheFor == n && _crimeCacheDebug == _debugOn && UiDraw.RealMs - _crimeCacheAt < 500)
		{
			return _crimeCache;
		}
		_crimeCache = BuildCrimeSheet(n);
		_crimeCacheFor = n;
		_crimeCacheAt = UiDraw.RealMs;
		_crimeCacheDebug = _debugOn;
		return _crimeCache;
	}

	private CrimeProfile BuildCrimeSheet(NemesisRecord n)
	{
		if (n.Id == YouId)
		{
			return YourCrimeSheet();
		}
		CrimeProfile crimeProfile = new CrimeProfile();
		bool flag = n.TemperKnown || _debugOn;
		List<PastEntry> list = (from e in n.Past ?? new List<PastEntry>()
			where PastShown(e) && e.Kind == "crime" && (e.Known || (e.Public && n.TemperKnown) || _debugOn)
			orderby e.Year descending
			select e).ToList();
		foreach (PastEntry item in list.Take(4))
		{
			crimeProfile.Crimes.Add((item.WhenText, item.Text, CrimeBadge(item.Text)));
		}
		crimeProfile.CrimesTitle = "KNOWN CRIMES";
		ref string crimesNote = ref crimeProfile.CrimesNote;
		string text;
		if (list.Count != 0)
		{
			if (list.Count > 4)
			{
				text = $"and {list.Count - 4} more";
			}
			else
			{
				text = ((!flag) ? "There may be more - make him talk" : null);
			}
		}
		else
		{
			text = (flag ? "Nothing you know of" : "Unknown - make him talk");
		}
		crimesNote = text;
		List<WorldEvent> list2 = (from e in Chronicle.Events
			where e.People != null && e.People.Any((WorldPart p) => p.Id == n.Id) && e.Kind != "LIFE" && e.Kind != "RANKS"
			orderby e.GameMin descending
			select e).ToList();
		int num = Enumerable.Count(list2, (WorldEvent e) => e.People.Any((WorldPart p) => p.Id != n.Id && p.Outcome == "KILLED") && e.People.First((WorldPart p) => p.Id == n.Id).Outcome != "KILLED");
		foreach (WorldEvent item2 in list2.Take(4))
		{
			string text2 = (item2.People.First((WorldPart p) => p.Id == n.Id).Outcome ?? "").ToUpperInvariant();
			crimeProfile.Events.Add((KindLabel(item2.Kind), KindColor(item2.Kind), item2.Title ?? "", text2, OutcomeColor(text2)));
		}
		ref string eventsNote = ref crimeProfile.EventsNote;
		string text3;
		if (list2.Count != 0)
		{
			text3 = ((list2.Count > 4) ? $"and {list2.Count - 4} more" : null);
		}
		else
		{
			text3 = "Nothing on record";
		}
		eventsNote = text3;
		Gang gang = ((n.Gang != null) ? Gangs.ById(n.Gang) : null);
		if (gang != null)
		{
			crimeProfile.Side = gang.Name.ToUpperInvariant();
			crimeProfile.SideCol = gang.Accent;
			crimeProfile.SideFilled = true;
		}
		else if ((n.Affiliation != null) & flag)
		{
			Gang gang2 = Gangs.ById(n.Affiliation);
			crimeProfile.Side = "IN WITH THE " + (gang2?.Name ?? n.Affiliation).ToUpperInvariant();
			crimeProfile.SideCol = gang2?.Accent ?? Theme.Warn;
		}
		else
		{
			crimeProfile.Side = "NO GANG";
			crimeProfile.SideCol = Theme.Dim;
		}
		int num2 = 5 * list.Count + 15 * n.TimesKilledPlayer + 10 * n.TimesRobbedPlayer + 8 * num + 10 * Math.Max(0, n.Rank - 1) + ((n.Gang != null) ? 10 : 0);
		if (n.Story)
		{
			crimeProfile.BannerLabel = "RIDES WITH YOU";
			crimeProfile.BannerValue = "";
			crimeProfile.BannerWord = "the law knows the gang, not the man";
			crimeProfile.BannerCol = Theme.Dim;
		}
		else
		{
			ref string bannerLabel = ref crimeProfile.BannerLabel;
			string text4;
			if (num2 >= 60)
			{
				text4 = "WANTED";
			}
			else
			{
				text4 = ((num2 > 0) ? "SMALL TIME" : "NOBODY'S PAYING");
			}
			bannerLabel = text4;
			crimeProfile.BannerValue = ((num2 > 0) ? $"${num2}" : "-");
			crimeProfile.BannerWord = ((num2 > 0) ? "word on the trail" : "no price on him");
			ref(int r, int g, int b) bannerCol = ref crimeProfile.BannerCol;
			(int r, int g, int b) tuple;
			if (num2 >= 60)
			{
				tuple = Theme.Blood;
			}
			else
			{
				tuple = ((num2 > 0) ? Theme.Gold : Theme.Dim);
			}
			bannerCol = tuple;
		}
		if (!n.Story && !n.Person)
		{
			crimeProfile.TilesTitle = "AGAINST YOU";
			crimeProfile.Tiles.Add((n.TimesKilledPlayer.ToString(), "KILLED YOU", (n.TimesKilledPlayer > 0) ? Theme.Blood : Theme.Dim));
			crimeProfile.Tiles.Add((n.TimesRobbedPlayer.ToString(), "ROBBED YOU", (n.TimesRobbedPlayer > 0) ? Theme.Warn : Theme.Dim));
			crimeProfile.Tiles.Add((n.TimesAmbushed.ToString(), "CAME FOR YOU", (n.TimesAmbushed > 0) ? Theme.Text : Theme.Dim));
		}
		return crimeProfile;
	}

	private void FixJohnRecord()
	{
		WorldState c = Chronicle;
		if (c.JohnRecordFixed || c.EraTurnAt <= 0)
		{
			return;
		}
		c.JohnRecordFixed = true;
		if (!(c.Past ?? new List<WorldEvent>()).Any((WorldEvent e) => e.Kind == "ERA" && e.Title == "Eight years later"))
		{
			SaveWorld();
			return;
		}
		HashSet<string> since = new HashSet<string>(from id in c.Events.Where((WorldEvent e) => e.GameMin >= c.EraTurnAt && e.People != null).SelectMany((WorldEvent e) => from p in e.People
				where p.Outcome == "KILLED"
				select p.Id)
			where id != null
			select id);
		int num = 0;
		foreach (NemesisRecord item in Roster.Where((NemesisRecord r) => r.KilledByPlayer && !since.Contains(r.Id)))
		{
			item.KilledByPlayer = false;
			num++;
		}
		GrudgeLog($"EPILOGUE John's record: {num} of Arthur's kills taken off it");
		SaveRoster();
		SaveWorld();
	}

	private CrimeProfile YourCrimeSheet()
	{
		CrimeProfile crimeProfile = new CrimeProfile
		{
			You = true
		};
		int num = 0;
		try
		{
			num = BountyDollars;
		}
		catch
		{
		}
		string regionName = RegionName;
		crimeProfile.BannerLabel = ((num > 0) ? "WANTED" : "NO BOUNTY");
		crimeProfile.BannerValue = ((num > 0) ? $"${num}" : "-");
		crimeProfile.BannerWord = ((regionName != "?") ? ("in " + regionName) : "where you are");
		crimeProfile.BannerCol = ((num > 0) ? Theme.Blood : Theme.Dim);
		crimeProfile.Rep = OverallReputation();
		Dictionary<string, int> d = Chronicle.YourCrimes ?? new Dictionary<string, int>();
		crimeProfile.TilesTitle = "ON RECORD";
		foreach (var item in CrimeKinds.Where(((string key, string label) k) => d.TryGetValue(k.key, out var value) && value > 0))
		{
			crimeProfile.Tiles.Add((d[item.key].ToString(), item.label.ToUpperInvariant(), (item.key == "kill" || item.key == "gore") ? Theme.Blood : Theme.Warn));
		}
		FixJohnRecord();
		List<NemesisRecord> list = (from r in Roster
			where !r.IsAlive && r.KilledByPlayer
			orderby r.Rank descending
			select r).ToList();
		crimeProfile.Dead = (from r in list.Take(8)
			select r.Name).ToList();
		crimeProfile.DeadMore = Math.Max(0, list.Count - 8);
		int num2 = Enumerable.Count(People, (Acquaintance a) => a.Witnessed != null && a.Witnessed.Any((string w) => w.StartsWith("saw you")));
		int num3 = Enumerable.Count(People, (Acquaintance a) => a.Reported);
		int num4 = Enumerable.Count(People, (Acquaintance a) => a.KeptQuiet);
		crimeProfile.Witnesses.Add((num2.ToString(), "SAW SOMETHING", (num2 > 0) ? Theme.Text : Theme.Dim));
		crimeProfile.Witnesses.Add((num3.ToString(), "TOLD THE LAW", (num3 > 0) ? Theme.Blood : Theme.Dim));
		crimeProfile.Witnesses.Add((num4.ToString(), "KEPT QUIET", (num4 > 0) ? Theme.Good : Theme.Dim));
		crimeProfile.Towns = (from x in (from t in RepTowns
				select (t: t, p: TownRep(t)) into x
				where x.p.Known > 0 || x.p.Illwill > 0
				orderby Math.Abs(x.p.Rep) descending
				select x).Take(5)
			select (t: x.t, Rep: x.p.Rep)).ToList();
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			int num6 = NotorietyOf(gang);
			if (num6 > 0)
			{
				crimeProfile.Factions.Add((gang.Name, num6, gang.Accent));
			}
		}
		crimeProfile.Factions = crimeProfile.Factions.OrderByDescending(((string name, int value, (int r, int g, int b) col) f) => f.value).ToList();
		List<WorldEvent> list2 = (from e in Chronicle.Events
			where e.Kind == "YOU" && (e.Tag == "mission" || e.Tag == "stranger")
			orderby e.GameMin descending
			select e).ToList();
		foreach (WorldEvent item2 in list2.Take(4))
		{
			crimeProfile.Events.Add(((item2.Tag == "mission") ? "THE GANG" : "STRANGER", (item2.Tag == "mission") ? VdlAccent : (150, 170, 200), item2.Title ?? "", (item2.When ?? "").Split(new string[1] { "  " }, StringSplitOptions.None)[0], Theme.Dim));
		}
		crimeProfile.EventsNote = ((list2.Count > 4) ? $"and {list2.Count - 4} more in the World tab" : null);
		return crimeProfile;
	}

	internal bool MapSettled()
	{
		try
		{
			Ped character = Game.Player.Character;
			if (character == null || !character.Exists() || WorldBusy(character))
			{
				return false;
			}
			if (Game.GameTime - _loadedAt < 15000 || Game.GameTime - _quietEndedAt < 15000)
			{
				return false;
			}
			if (CAM.IS_SCREEN_FADED_OUT() || CAM.IS_SCREEN_FADING_OUT() || CAM.IS_SCREEN_FADING_IN())
			{
				return false;
			}
			return true;
		}
		catch
		{
			return false;
		}
	}

	private void RunPendingMap()
	{
		if (_mapPending.Count == 0 || !MapSettled())
		{
			return;
		}
		List<Action> list = _mapPending.ToList();
		_mapPending.Clear();
		foreach (Action item in list)
		{
			try
			{
				item();
			}
			catch (Exception ex)
			{
				GrudgeLog("MAP refresh failed: " + ex.Message);
			}
		}
	}

