	private void HandlePlayerDeath(Ped player)
	{
		int num = PED.GET_PED_SOURCE_OF_DEATH(player.Handle);
		Ped ped = ((num != 0) ? (Entity.FromHandle(num) as Ped) : null);
		NemesisRecord nemesisRecord = null;
		NemesisRecord value;
		NemesisRecord value2;
		if (ped != null && _activeNemesisPed != null && ped.Handle == _activeNemesisPed.Handle)
		{
			nemesisRecord = ActiveRecord;
		}
		else if (ped != null && _worldNemeses.TryGetValue(ped.Handle, out value) && Roster.Contains(value))
		{
			nemesisRecord = value;
		}
		else if (ped != null && _followerOf.TryGetValue(ped.Handle, out value2) && Roster.Contains(value2))
		{
			nemesisRecord = value2;
		}
		if (nemesisRecord != null)
		{
			NemesisRecord nemesisRecord2 = nemesisRecord;
			if (nemesisRecord2.Origin == GrudgeOrigin.GangMember)
			{
				nemesisRecord2.Origin = GrudgeOrigin.Killed;
				nemesisRecord2.KillLocation = GetZoneName(player.Position);
			}
			nemesisRecord2.TimesKilledPlayer++;
			nemesisRecord2.Touch();
			NoteOutcome(nemesisRecord2, "killed you");
			CheckSkills(nemesisRecord2, Loadout.For(nemesisRecord2).Band.ToString());
			Remember(nemesisRecord2, "Pride", 65, "killed you");
			if (Mind.HasAgainstYou(nemesisRecord2, "Prove"))
			{
				nemesisRecord2.Goals.RemoveAll((Goal g) => g.Type == "Prove");
				Remember(nemesisRecord2, "Joy", 50, "proved himself on you");
			}
			nemesisRecord2.KilledPlayerAt = DateTime.Now;
			int hate = nemesisRecord2.Hate;
			nemesisRecord2.AddHate(10);
			bool flag = nemesisRecord2.Gang == null && nemesisRecord2.Rank < 5;
			if (flag)
			{
				nemesisRecord2.Rank++;
			}
			else if (nemesisRecord2.Gang != null)
			{
				GainRankXp(nemesisRecord2, 3, "killed you");
			}
			History(nemesisRecord2, "KILLED YOU near " + GetZoneName(player.Position) + ": hate " + Delta(hate, nemesisRecord2.Hate) + (flag ? $"  -> rank {nemesisRecord2.Rank}" : ""), Theme.Blood);
			WorldPart worldPart = PartFor(nemesisRecord2, "KILLED YOU", nemesisRecord2.Title);
			worldPart.Effects.Add($"hate {hate} -> {nemesisRecord2.Hate}");
			if (flag)
			{
				worldPart.Effects.Add($"rank {nemesisRecord2.Rank}");
			}
			ChronicleDeed("died", nemesisRecord2.Name + " killed you", "near " + GetZoneName(player.Position), player.Position, nemesisRecord2.Gang, worldPart);
			SaveRoster();
			GrudgeNotice(flag ? $"{nemesisRecord2.FullName} got you again. His legend grows: Rank {nemesisRecord2.Rank}." : (nemesisRecord2.FullName + " got you again."));
			ReleaseActive();
		}
		else
		{
			if (ped == null || ped.IsPlayer || !ped.IsHuman)
			{
				return;
			}
			bool flag2 = MissionMemoryOk(ped);
			if (Kids.IsChild(ped) || IsStoryPed(ped) || IsCompanion(ped.Handle) || (GameOwned(ped) && !flag2) || IsLawman(ped) || (MISC.GET_MISSION_FLAG() && !flag2))
			{
				GrudgeLog($"KILLER ped={ped.Handle} is not nemesis material (child / story / companion / mission / law) -> no nemesis");
				return;
			}
			string zoneName = GetZoneName(player.Position);
			_provoked.TryGetValue(ped.Handle, out var value3);
			_provoked.Remove(ped.Handle);
			if (PlayerMasked(player) && (value3 == null || !value3.SawFace))
			{
				DisguiseSaves++;
				GrudgeLog($"KILLER ped={ped.Handle} never saw your face (masked) -> no nemesis");
				Feed("KILLED BY " + WhoIs(ped.Handle) + ": never saw your face (masked) -> no nemesis", Theme.Good);
				return;
			}
			NemesisRecord nemesisRecord3 = NewRecord((uint)ped.Model.Hash, zoneName);
			nemesisRecord3.TimesKilledPlayer = 1;
			nemesisRecord3.Touch();
			StartRest(nemesisRecord3);
			if (_named.TryGetValue(ped.Handle, out var value4))
			{
				nemesisRecord3.Name = value4.Name;
				_named.Remove(ped.Handle);
			}
			nemesisRecord3.HasOrigin = true;
			nemesisRecord3.OriginX = player.Position.X;
			nemesisRecord3.OriginY = player.Position.Y;
			nemesisRecord3.OriginZ = player.Position.Z;
			nemesisRecord3.Origin = OriginForKiller(value3);
			nemesisRecord3.TimesAntagonized = value3?.Insults ?? 0;
			nemesisRecord3.TimesGreeted = value3?.Greetings ?? 0;
			if (value3 != null)
			{
				nemesisRecord3.Personality = value3.Temper;
				CopyTraits(value3.Shadow, nemesisRecord3);
				FitKinToLife(nemesisRecord3);
			}
			nemesisRecord3.Hate = Math.Max(Hate.Initial(nemesisRecord3.Origin), Hate.MurderousAt);
			if (value3 != null && value3.Ledger.Count > 0)
			{
				History(nemesisRecord3, "as a stranger: " + string.Join(", ", value3.Ledger), Theme.Dim);
			}
			History(nemesisRecord3, $"KILLED YOU near {zoneName} and became your nemesis ({nemesisRecord3.Origin}): hate {nemesisRecord3.Hate}", Theme.Blood);
			Roster.Add(nemesisRecord3);
			_bulletImpact.TagVictim(ped.Handle, nemesisRecord3.Id, nemesisRecord3.FullName ?? "");
			ForgetPerson(ped.Handle, nemesisRecord3.Name);
			WorldPart worldPart2 = PartFor(nemesisRecord3, "KILLED YOU", "a new nemesis");
			worldPart2.Effects.Add($"hate {nemesisRecord3.Hate}");
			ChronicleDeed("died", nemesisRecord3.Name + " killed you - and swore to do it again", "near " + zoneName, player.Position, nemesisRecord3.Gang, worldPart2);
			SaveRoster();
			string text;
			if (nemesisRecord3.Origin == GrudgeOrigin.Wounded)
			{
				text = "You shot him and left him breathing. He didn't return the favor.";
			}
			else if (nemesisRecord3.Origin == GrudgeOrigin.Slashed)
			{
				text = "You cut him. He answered with lead.";
			}
			else if (nemesisRecord3.Origin == GrudgeOrigin.HorseKilled)
			{
				text = "You killed his horse. He killed you.";
			}
			else if (nemesisRecord3.Origin == GrudgeOrigin.Kidnapped)
			{
				text = "You hogtied him. He got loose.";
			}
			else if (nemesisRecord3.Origin == GrudgeOrigin.Robbed)
			{
				text = "You robbed him. He took your life instead.";
			}
			else if (nemesisRecord3.Origin == GrudgeOrigin.KnockedOut)
			{
				text = "You knocked him out. He came to, and came for you.";
			}
			else if (nemesisRecord3.Origin == GrudgeOrigin.Beaten)
			{
				text = "You beat him with your fists. He answered with lead.";
			}
			else if (nemesisRecord3.Origin == GrudgeOrigin.Insulted)
			{
				text = "You ran your mouth; he answered with lead.";
			}
			else
			{
				text = ((nemesisRecord3.Origin == GrudgeOrigin.Greeted) ? "You tipped your hat. He didn't." : ("He killed you near " + zoneName + "."));
			}
			GrudgeNotice("A nemesis rises: " + nemesisRecord3.FullName + ". " + text);
		}
	}

	private void ResetGangsIfFlagged()
	{
		string path = Path.Combine(_saveDir, "reset-xray.flag");
		if (File.Exists(path))
		{
			try
			{
				_bulletImpact.ClearXRayLog();
				File.Delete(path);
				ShowNotification("X-ray log cleared.");
			}
			catch (Exception ex)
			{
				ShowNotification("X-ray reset failed: " + ex.Message);
			}
		}
		string path2 = Path.Combine(_saveDir, "forget.flag");
		if (File.Exists(path2))
		{
			try
			{
				List<string> keys = (from l in File.ReadAllLines(path2)
					select l.Trim() into l
					where l.Length > 0
					select l).ToList();
				List<NemesisRecord> list = Roster.Where((NemesisRecord r) => keys.Any((string k) => string.Equals(k, r.Name, StringComparison.OrdinalIgnoreCase) || k == r.Id)).ToList();
				foreach (NemesisRecord item in list)
				{
					RemoveRecord(item, "forget.flag");
				}
				int count = list.Count;
				File.Delete(path2);
				if (count > 0)
				{
					SaveRoster();
					ShowNotification($"Forgot {count} nemesis record(s).");
				}
			}
			catch (Exception ex2)
			{
				ShowNotification("Forget failed: " + ex2.Message);
			}
		}
		string path3 = Path.Combine(_saveDir, "seed-loners.flag");
		if (File.Exists(path3))
		{
			try
			{
				File.Delete(path3);
				_seedLonersOnLoad = true;
			}
			catch
			{
			}
		}
		string path4 = Path.Combine(_saveDir, "reset-all.flag");
		if (File.Exists(path4))
		{
			try
			{
				int num = ResetEverything();
				File.Delete(path4);
				ShowNotification($"Fresh start: {num} records cleared, notoriety wiped. New faction rosters are being drawn up.");
				return;
			}
			catch (Exception ex3)
			{
				ShowNotification("Full reset failed: " + ex3.Message);
				return;
			}
		}
		string path5 = Path.Combine(_saveDir, "reset-gangs.flag");
		if (!File.Exists(path5))
		{
			return;
		}
		try
		{
			if (File.Exists(_savePath))
			{
				File.Copy(_savePath, Path.Combine(_saveDir, $"nemeses.before-gang-reset-{DateTime.Now:yyyyMMdd-HHmmss}.json"), overwrite: true);
			}
			List<NemesisRecord> list2 = Roster.Where((NemesisRecord n) => n.Gang != null).ToList();
			foreach (NemesisRecord item2 in list2)
			{
				RemoveRecord(item2, "gang reset");
			}
			ReapplyLeaders(list2);
			int count2 = list2.Count;
			Config.SeededGangs = "";
			Config.Save();
			SaveRoster();
			File.Delete(path5);
			ShowNotification($"Gangs reset: {count2} gang members cleared. Fresh rosters are being drawn up.");
		}
		catch (Exception ex4)
		{
			ShowNotification("Gang reset failed: " + ex4.Message);
		}
	}

	private void BackupRoster(string tag)
	{
		try
		{
			if (File.Exists(_savePath))
			{
				File.Copy(_savePath, Path.Combine(_saveDir, $"nemeses.before-{tag}-{DateTime.Now:yyyyMMdd-HHmmss}.json"), overwrite: true);
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("BACKUP failed: " + ex.Message);
		}
	}

	internal void GiveHomeTown(NemesisRecord rec, Gang gang)
	{
		if (gang == null || gang.HomeTown == null || rec.HasOrigin)
		{
			return;
		}
		rec.KillLocation = gang.HomeTown;
		if (TownSpots.TryGetValue(gang.HomeTown, out (Vector3?, Vector3?) value))
		{
			Vector3? item = value.Item2;
			Vector3? vector;
			if (!item.HasValue)
			{
				(vector, _) = value;
			}
			else
			{
				vector = item;
			}
			Vector3? vector2 = vector;
			if (vector2.HasValue)
			{
				Vector3 valueOrDefault = vector2.GetValueOrDefault();
				rec.HasOrigin = true;
				rec.OriginX = valueOrDefault.X + (float)_rng.Next(-120, 121);
				rec.OriginY = valueOrDefault.Y + (float)_rng.Next(-120, 121);
				rec.OriginZ = valueOrDefault.Z;
			}
		}
	}

	private int ResetEverything()
	{
		_rosterGen++;
		_worldGen++;
		BackupRoster("full-reset");
		int count = Roster.Count;
		Roster.Clear();
		Config.SeededGangs = "";
		Config.ArmyTopUp = true;
		Gang[] defined = Gangs.Defined;
		foreach (Gang gang in defined)
		{
			Config.Notoriety[gang.Id] = 0;
		}
		_bulletImpact.ClearXRayLog();
		_chron = new WorldState();
		Gangs.SetEra(1899);
		if (IsEpiloguePlayer())
		{
			StartWorldIn1907("a fresh start");
		}
		SaveWorld();
		Config.ClearedCamps = "";
		_cleared = null;
		Config.LastSuccessionDay = 0;
		Config.NextSuccessionDay = 0;
		Config.LastDecayDay = 0;
		_successionCard = null;
		_people = new List<Acquaintance>();
		_acqOf.Clear();
		_witnessBatches.Clear();
		_peopleDirty = true;
		SavePeople(force: true);
		_prints = new Dictionary<string, Print>();
		_keptNames = new HashSet<string>();
		_fpOf.Clear();
		_printsDirty = true;
		SavePrints();
		_named.Clear();
		_provoked.Clear();
		Tension = 20f;
		StoreTension();
		Config.Save();
		SaveRoster();
		return count;
	}

	internal int SeedTestLoners(int count)
	{
		Personality[] array = new Personality[6]
		{
			Personality.Hothead,
			Personality.Coward,
			Personality.Proud,
			Personality.Cold,
			Personality.Greedy,
			Personality.Drifter
		};
		string[] array2 = new string[7] { "Valentine", "Valentine", "Valentine", "Rhodes", "Strawberry", "Blackwater", "Saint Denis" };
		int num = 0;
		for (int i = 0; i < count; i++)
		{
			string text = array2[_rng.Next(array2.Length)];
			NemesisRecord nemesisRecord = NewRecord((uint)TestLonerModels[_rng.Next(TestLonerModels.Length)], text);
			nemesisRecord.Gang = null;
			nemesisRecord.Personality = array[i % array.Length];
			Traits.Roll(nemesisRecord, _rng, null);
			nemesisRecord.PastRolled = false;
			EnsurePast(nemesisRecord);
			nemesisRecord.MindRolled = false;
			EnsureMind(nemesisRecord);
			int num2 = _rng.Next(100);
			if (num2 < 40)
			{
				nemesisRecord.Hate = 15 + _rng.Next(24);
				nemesisRecord.Origin = (new GrudgeOrigin[4]
				{
					GrudgeOrigin.Insulted,
					GrudgeOrigin.Beaten,
					GrudgeOrigin.KnockedOut,
					GrudgeOrigin.Threatened
				})[_rng.Next(4)];
			}
			else if (num2 < 75)
			{
				nemesisRecord.Hate = 42 + _rng.Next(27);
				nemesisRecord.Origin = (new GrudgeOrigin[4]
				{
					GrudgeOrigin.Robbed,
					GrudgeOrigin.Kidnapped,
					GrudgeOrigin.Slashed,
					GrudgeOrigin.Gunfight
				})[_rng.Next(4)];
			}
			else
			{
				nemesisRecord.Hate = 72 + _rng.Next(24);
				nemesisRecord.Origin = (new GrudgeOrigin[3]
				{
					GrudgeOrigin.Wounded,
					GrudgeOrigin.HorseKilled,
					GrudgeOrigin.Killed
				})[_rng.Next(3)];
			}
			if (nemesisRecord.Origin == GrudgeOrigin.Killed)
			{
				nemesisRecord.TimesKilledPlayer = 1;
			}
			nemesisRecord.Fear = ((_rng.Next(100) < 35) ? (20 + _rng.Next(45)) : _rng.Next(15));
			if (TownSpots.TryGetValue(text, out (Vector3?, Vector3?) value))
			{
				Vector3? item = value.Item2;
				Vector3? vector;
				if (!item.HasValue)
				{
					(vector, _) = value;
				}
				else
				{
					vector = item;
				}
				Vector3? vector2 = vector;
				if (vector2.HasValue)
				{
					Vector3 valueOrDefault = vector2.GetValueOrDefault();
					nemesisRecord.HasOrigin = true;
					nemesisRecord.OriginX = valueOrDefault.X + (float)_rng.Next(-60, 60);
					nemesisRecord.OriginY = valueOrDefault.Y + (float)_rng.Next(-60, 60);
					nemesisRecord.OriginZ = valueOrDefault.Z;
				}
			}
			nemesisRecord.RestUntil = 0L;
			nemesisRecord.Touch();
			History(nemesisRecord, $"TEST loner seeded in {text}: {nemesisRecord.Origin}, hate {nemesisRecord.Hate}, fear {nemesisRecord.Fear}", Theme.Dim);
			Roster.Add(nemesisRecord);
			num++;
		}
		SaveRoster();
		GrudgeLog($"TEST seeded {num} loners");
		return num;
	}

	internal void DebugReset(string what, Gang gang = null)
	{
		try
		{
			switch (what)
			{
			case "all":
			{
				WipeWorldAfterRespawn();
				int num = ResetEverything();
				DespawnAftermath();
				ClearAftermathBlips();
				SeedGangRosters();
				AssignCamps();
				EnsureWorldHistory();
				SaveRoster();
				ShowNotification($"Fresh start: {num} records cleared, notoriety, X-rays and world events wiped. New rosters drawn up.");
				break;
			}
			case "safecamps":
				ForgetSafeCamps();
				ShowNotification("Safe camps forgotten - the next one is learned when you're seen there twice.");
				break;
			case "loners":
				ShowNotification($"{SeedTestLoners(12)} test loners added to the Unaffiliated list.");
				break;
			case "xray":
				_bulletImpact.ClearXRayLog();
				ShowNotification("X-ray log cleared.");
				break;
			case "world":
			{
				DespawnAftermath();
				ClearAftermathBlips();
				int era = Gangs.Era;
				_chron = new WorldState
				{
					Era = ((era >= 1907) ? 1907 : 0)
				};
				if (era >= 1907)
				{
					_chron.EraTurnAt = GameMinutesNow();
					_chron.EraFuneralsFixed = true;
					_chron.WoffordFixed = true;
					_chron.HomeStrongholdsRestored = true;
					Apply1907Camps();
				}
				EnsureWorldHistory();
				SaveWorld();
				ShowNotification("World events cleared - the years before you written anew.");
				break;
			}
			case "faction":
			{
				BackupRoster((gang != null) ? (gang.Id + "-reset") : "loners-reset");
				WipeWorldAfterRespawn();
				_rosterGen++;
				List<NemesisRecord> list = Roster.Where((NemesisRecord x) => x.Gang == gang?.Id).ToList();
				foreach (NemesisRecord item in list)
				{
					RemoveRecord(item, "faction reset");
				}
				ReapplyLeaders(list);
				int count = list.Count;
				if (gang != null)
				{
					Config.SeededGangs = string.Join(",", from id in Config.SeededGangs.Split(',')
						select id.Trim() into id
						where id.Length > 0 && id != gang.Id
						select id);
					Config.Notoriety[gang.Id] = 0;
					if (gang == Gangs.Army)
					{
						Config.ArmyTopUp = true;
					}
				}
				Config.Save();
				SeedGangRosters();
				AssignCamps();
				SaveRoster();
				ShowNotification(string.Format("{0} reset: {1} records cleared{2}.", gang?.Name ?? "Unaffiliated", count, (gang != null) ? ", a fresh roster drawn up" : ""));
				break;
			}
			}
			GrudgeLog("RESET " + what + ((what == "faction") ? (" " + (gang?.Id ?? "loners")) : "") + " (debug menu)");
		}
		catch (Exception ex)
		{
			ShowNotification("Reset failed: " + ex.Message);
			GrudgeLog("RESET failed: " + ex);
		}
	}

	private int SeedFootSoldierHate(Gang gang, NemesisRecord rec)
	{
		if (!gang.MixedFootSoldiers)
		{
			return 50 + _rng.Next(28);
		}
		int num = _rng.Next(100);
		if (rec.Personality == Personality.Hothead)
		{
			num += 25;
		}
		if (rec.Personality == Personality.Proud)
		{
			num += 10;
		}
		if (rec.Personality == Personality.Coward)
		{
			num -= 25;
		}
		if (num < 35)
		{
			return 22 + _rng.Next(16);
		}
		if (num < 70)
		{
			return Hate.VengefulAt + 2 + _rng.Next(Hate.MurderousAt - Hate.VengefulAt - 4);
		}
		return Hate.MurderousAt + 2 + _rng.Next(12);
	}

	private int TopUpFromSeed(Gang gang)
	{
		if (gang?.Seed == null)
		{
			return 0;
		}
		int num = 0;
		(int, int, PedHash[])[] seed = gang.Seed;
		for (int i = 0; i < seed.Length; i++)
		{
			(int, int, PedHash[]) tuple = seed[i];
			int rank = tuple.Item1;
			int item = tuple.Item2;
			PedHash[] item2 = tuple.Item3;
			for (int num2 = Enumerable.Count(Roster, (NemesisRecord n) => n.Gang == gang.Id && n.IsAlive && !n.PresumedDead && ((rank < 4) ? (n.Rank == rank) : (n.Rank >= 4))); num2 < item; num2++)
			{
				NemesisRecord nemesisRecord = NewRecord((uint)item2[_rng.Next(item2.Length)], "", gang, rank);
				nemesisRecord.Gang = gang.Id;
				nemesisRecord.Rank = rank;
				nemesisRecord.Origin = GrudgeOrigin.GangMember;
				nemesisRecord.SeedMember = true;
				nemesisRecord.TimesKilledPlayer = 0;
				nemesisRecord.KilledPlayerAt = DateTime.Now;
				NemesisRecord nemesisRecord2 = nemesisRecord;
				int hate;
				if (gang.SeedHate.HasValue)
				{
					hate = gang.SeedHate.Value.min + _rng.Next(Math.Max(1, gang.SeedHate.Value.max - gang.SeedHate.Value.min + 1));
				}
				else
				{
					hate = ((rank >= 2) ? (72 + _rng.Next(10)) : SeedFootSoldierHate(gang, nemesisRecord));
				}
				nemesisRecord2.Hate = hate;
				if (rank >= 2 && !gang.SeedHate.HasValue && nemesisRecord.Personality == Personality.Hothead)
				{
					nemesisRecord.Hate = Math.Min(100, nemesisRecord.Hate + 6);
				}
				if (rank >= 2 && nemesisRecord.Personality == Personality.Coward)
				{
					nemesisRecord.Hate -= 12;
				}
				GiveHomeTown(nemesisRecord, gang);
				Roster.Add(nemesisRecord);
				num++;
			}
		}
		if (num > 0)
		{
			GrudgeLog($"ROSTER {gang.Name}: {num} men added to bring it up to its starting table");
		}
		return num;
	}

	private void SeedGangRosters(string again = null)
	{
		HashSet<string> seeded = new HashSet<string>(Config.SeededGangs.Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries));
		foreach (NemesisRecord item4 in Roster.Where((NemesisRecord n) => n.Origin == GrudgeOrigin.GangMember))
		{
			item4.SeedMember = true;
		}
		foreach (Gang item5 in Gangs.All.Where((Gang g) => Roster.Any((NemesisRecord n) => n.Gang == g.Id && n.SeedMember)))
		{
			seeded.Add(item5.Id);
		}
		if (again != null)
		{
			seeded.Remove(again);
		}
		foreach (Gang item6 in Gangs.All.Where((Gang g) => g.Seed != null && !seeded.Contains(g.Id)))
		{
			int num = 0;
			(int, int, PedHash[])[] seed = item6.Seed;
			for (int num2 = 0; num2 < seed.Length; num2++)
			{
				(int, int, PedHash[]) tuple = seed[num2];
				int item = tuple.Item1;
				int item2 = tuple.Item2;
				PedHash[] item3 = tuple.Item3;
				for (int num3 = 0; num3 < item2; num3++)
				{
					NemesisRecord nemesisRecord = NewRecord((uint)item3[_rng.Next(item3.Length)], "", item6, item);
					nemesisRecord.Gang = item6.Id;
					nemesisRecord.Rank = item;
					nemesisRecord.Origin = GrudgeOrigin.GangMember;
					nemesisRecord.SeedMember = true;
					nemesisRecord.TimesKilledPlayer = 0;
					nemesisRecord.KilledPlayerAt = DateTime.Now;
					NemesisRecord nemesisRecord2 = nemesisRecord;
					int hate;
					if (item6.SeedHate.HasValue)
					{
						hate = item6.SeedHate.Value.min + _rng.Next(Math.Max(1, item6.SeedHate.Value.max - item6.SeedHate.Value.min + 1));
					}
					else
					{
						hate = ((item >= 2) ? (72 + _rng.Next(10)) : SeedFootSoldierHate(item6, nemesisRecord));
					}
					nemesisRecord2.Hate = hate;
					if (item >= 2 && !item6.SeedHate.HasValue && nemesisRecord.Personality == Personality.Hothead)
					{
						nemesisRecord.Hate = Math.Min(100, nemesisRecord.Hate + 6);
					}
					if (item >= 2 && nemesisRecord.Personality == Personality.Coward)
					{
						nemesisRecord.Hate -= 12;
					}
					GiveHomeTown(nemesisRecord, item6);
					Roster.Add(nemesisRecord);
					num++;
				}
			}
			seeded.Add(item6.Id);
			GrudgeNotice($"{item6.Name}: {num} men now stand under {item6.LeaderName}.");
		}
		if (!Config.ArmyTopUp && seeded.Contains(Gangs.Army.Id))
		{
			for (int num4 = Enumerable.Count(Roster, (NemesisRecord n) => n.Gang == Gangs.Army.Id && n.SeedMember && n.Rank == 1); num4 < 14; num4++)
			{
				NemesisRecord nemesisRecord3 = NewRecord(2150064377u, "", Gangs.Army);
				nemesisRecord3.Rank = 1;
				nemesisRecord3.Origin = GrudgeOrigin.GangMember;
				nemesisRecord3.SeedMember = true;
				nemesisRecord3.TimesKilledPlayer = 0;
				nemesisRecord3.KilledPlayerAt = DateTime.Now;
				nemesisRecord3.Hate = 50 + _rng.Next(28);
				Roster.Add(nemesisRecord3);
			}
			Config.ArmyTopUp = true;
		}
		Config.SeededGangs = string.Join(",", seeded);
		Config.Save();
		SaveRoster();
	}

	private void TrimGangRosters()
	{
		int num = 0;
		foreach (Gang gang in Gangs.All.Where((Gang g) => g.Seed != null))
		{
			string succ = SuccessorId(gang);
			List<NemesisRecord> source = Roster.Where((NemesisRecord n) => n.Gang == gang.Id && n.IsAlive && !n.PresumedDead && n.Id != succ).ToList();
			for (int num2 = 0; num2 < gang.Tiers.Length; num2++)
			{
				(string, int, int) tuple = gang.Tiers[num2];
				int minRank = tuple.Item2;
				int item = tuple.Item3;
				int maxRank = ((num2 == 0) ? int.MaxValue : (gang.Tiers[num2 - 1].MinRank - 1));
				List<NemesisRecord> list = source.Where((NemesisRecord n) => n.Rank >= minRank && n.Rank <= maxRank).ToList();
				List<NemesisRecord> list2 = (from n in list
					where n.Origin == GrudgeOrigin.GangMember && n.TimesAmbushed == 0 && n.TimesKilledPlayer == 0 && n.LoreModel == null && n.FormerGang == null && !_worldNemeses.ContainsValue(n) && n != ActiveRecord
					orderby n.KilledPlayerAt descending
					select n).ToList();
				for (int num3 = 0; num3 < list.Count - item && num3 < list2.Count; num3++)
				{
					RemoveRecord(list2[num3], "gang roster trimmed");
					num++;
				}
			}
		}
		if (num > 0)
		{
			SaveRoster();
			GrudgeLog($"ROSTER gang rosters trimmed back to their seats ({num} extra men removed)");
		}
	}

	private NemesisRecord PickAmbusher(List<NemesisRecord> candidates)
	{
		List<NemesisRecord> list = candidates.Where((NemesisRecord n) => !_worldNemeses.ContainsValue(n) && n != ActiveRecord).ToList();
		if (list.Count == 0)
		{
			return null;
		}
		candidates = list;
		double num = ((IEnumerable<NemesisRecord>)candidates).Sum((Func<NemesisRecord, double>)AmbushWeightOf);
		if (num <= 0.0)
		{
			return null;
		}
		double num2 = _rng.NextDouble() * num;
		foreach (NemesisRecord candidate in candidates)
		{
			double num3 = AmbushWeightOf(candidate);
			if (!(num3 <= 0.0))
			{
				num2 -= num3;
				if (num2 <= 0.0)
				{
					return candidate;
				}
			}
		}
		return candidates.LastOrDefault((NemesisRecord n) => AmbushWeightOf(n) > 0.0);
	}

	internal double AmbushWeightOf(NemesisRecord n)
	{
		double num = ((n.Origin == GrudgeOrigin.GangMember && n.TimesAmbushed == 0) ? ((double)Config.GangAmbushWeight) : 1.0) * (n.Personality.HasValue ? Personalities.AmbushWeight(n.Personality.Value) : 1.0);
		Gang gang = Gangs.ById(n.Gang);
		if (gang != null)
		{
			num *= ((CurrentDistrict != null) ? gang.EncounterRate : gang.AmbushBase) * Notoriety.Ambush(NotorietyOf(gang)) * RegionMult(gang);
		}
		if (gang != null && !ReasonMet(gang))
		{
			num = 0.0;
		}
		if (gang != null && IsDestroyed(gang))
		{
			num = 0.0;
		}
		if (gang != null)
		{
			LeaderSeat leaderSeat = SeatOf(gang);
			if (leaderSeat != null && leaderSeat.Fallen != null && leaderSeat.Successor == null)
			{
				num *= 0.5;
			}
		}
		if (gang != null)
		{
			int cLOCK_HOURS = CLOCK.GET_CLOCK_HOURS();
			num *= ((cLOCK_HOURS >= 21 || cLOCK_HOURS < 5) ? gang.NightWeight : gang.DayWeight);
		}
		num *= 1.0 - Math.Min(0.8, (double)EffectiveFear(n) / 150.0);
		num *= (double)((n.HateTier == HateTier.Murderous) ? Balance.WildMurderous : ((n.HateTier == HateTier.Vengeful) ? Balance.WildVengeful : Balance.WildResentful));
		num *= Mind.AmbushMult(n);
		if (gang != null)
		{
			num *= RankEncounterMult(n.Rank);
		}
		if (gang != null)
		{
			num *= AgendaAmbushMult(gang);
		}
		return num;
	}

	internal static double RankEncounterMult(int rank)
	{
		if (rank > 1)
		{
			return rank switch
			{
				4 => 0.35, 
				3 => 0.55, 
				2 => 0.75, 
				_ => 0.2, 
			};
		}
		return 1.0;
	}

	internal bool ManCooling(NemesisRecord n)
	{
		long num = GameMinutesNow();
		if (n.LastCameAt > 0 && n.LastCameAt <= num)
		{
			return num - n.LastCameAt < (long)Balance.ManCooldownHours * 60L;
		}
		return false;
	}

	internal bool CoolingOff(NemesisRecord n)
	{
		if (!ManCooling(n))
		{
			if (n.HateTier == HateTier.Murderous)
			{
				return MurderousCooling;
			}
			return false;
		}
		return true;
	}

	internal float HateGainOf(NemesisRecord n)
	{
		return n.HateGainMult * Balance.HateGainScale;
	}

	internal string HateGainWhy(NemesisRecord n)
	{
		List<string> list = new List<string>();
		if (n.Personality.HasValue && Math.Abs(Personalities.GainMult(n.Personality.Value) - 1f) > 0.01f)
		{
			list.Add($"{n.Personality.Value.ToString().ToLowerInvariant()} x{Personalities.GainMult(n.Personality.Value):0.00}");
		}
		float num = Traits.HateGain(n);
		if (Math.Abs(num - 1f) > 0.01f)
		{
			list.Add($"traits x{num:0.00}");
		}
		if (list.Count != 0)
		{
			return " (" + string.Join(", ", list) + ")";
		}
		return "";
	}

	internal void NoteCame(NemesisRecord n)
	{
		long lastMurderousAt = (n.LastCameAt = GameMinutesNow());
		if (n.HateTier == HateTier.Murderous)
		{
			_lastMurderousAt = lastMurderousAt;
		}
	}

	internal int EffectiveFear(NemesisRecord r)
	{
		return Math.Min(100, r.Fear + Math.Max(r.YourNotoriety, NotorietyOf(Gangs.ById(r.Gang))) / Math.Max(1, Balance.NotorietyFearDivisor));
	}

	internal Intent IntentOf(NemesisRecord r)
	{
		int effectiveFear = EffectiveFear(r);
		return Mind.ShiftIntent(r, Traits.IntentOf(r, effectiveFear), effectiveFear);
	}

	internal int NotorietyOf(Gang g)
	{
		if (g == null || !Config.Notoriety.TryGetValue(g.Id, out var value))
		{
			return 0;
		}
		return value;
	}

	private void AddNotoriety(Gang g, int amount, string why)
	{
		if (g == null || amount <= 0)
		{
			return;
		}
		bool flag = false;
		try
		{
			flag = PlayerMasked(Game.Player.Character);
		}
		catch
		{
		}
		if (flag)
		{
			Dictionary<string, float> dictionary = Chronicle.MaskedNotoriety ?? (Chronicle.MaskedNotoriety = new Dictionary<string, float>());
			dictionary.TryGetValue(g.Id, out var value);
			value += (float)amount * Balance.NotorietyGainScale / 4f;
			Dictionary<string, float> dictionary3 = Chronicle.MaskedWithheld ?? (Chronicle.MaskedWithheld = new Dictionary<string, float>());
			dictionary3.TryGetValue(g.Id, out var value2);
			dictionary3[g.Id] = value2 + (float)amount * Balance.NotorietyGainScale * 0.75f;
			int num = (int)value;
			dictionary[g.Id] = value - (float)num;
			SaveWorld();
			if (num <= 0)
			{
				GrudgeLog($"NOTORIETY {g.Id} stays {NotorietyOf(g)} - you were masked ({why}): a quarter counts, {value:0.00} of a point so far");
				return;
			}
			why += " - masked, a quarter";
			amount = num;
		}
		else
		{
			amount = Math.Max(1, (int)Math.Round((float)amount * Balance.NotorietyGainScale));
		}
		int num2 = NotorietyOf(g);
		int num3 = Math.Min(100, num2 + amount);
		Config.Notoriety[g.Id] = num3;
		(Chronicle.NotorietyGainDay ?? (Chronicle.NotorietyGainDay = new Dictionary<string, int>()))[g.Id] = GameDayKey();
		Config.Save();
		GrudgeLog($"NOTORIETY {g.Id} {num2} -> {num3} ({why})");
		Feed($"NOTORIETY {g.Name} {num2} -> {num3} ({why})", g.Accent);
		if (Notoriety.Level(num3) > Notoriety.Level(num2))
		{
			GrudgeNotice(g.Name + ": your notoriety rises - " + Notoriety.LevelName(num3) + ". More of them will come for you.");
		}
	}

	private void NoteFactionHit(int victim)
	{
		if (_worldNemeses.ContainsKey(victim) || (_activeNemesisPed != null && victim == _activeNemesisPed.Handle))
		{
			return;
		}
		uint model = ENTITY.GET_ENTITY_MODEL(victim);
		if (LoreModels.Count <= 0 || !LoreModels.Contains(Models.Name(model)))
		{
			Gang gang = Gangs.ForModel(model);
			if (gang != null)
			{
				_factionHits[victim] = (gang, Game.GameTime);
			}
		}
	}

	private void PollFactionKills()
	{
		if (_factionHits.Count == 0 || Game.GameTime < _nextFactionPoll)
		{
			return;
		}
		_nextFactionPoll = Game.GameTime + 500;
		foreach (KeyValuePair<int, (Gang, int)> item in _factionHits.ToList())
		{
			int key = item.Key;
			if (!ENTITY.DOES_ENTITY_EXIST(key) || !ENTITY.IS_ENTITY_A_PED(key) || Game.GameTime - item.Value.Item2 > 20000)
			{
				_factionHits.Remove(key);
				continue;
			}
			if (_worldNemeses.ContainsKey(key))
			{
				_factionHits.Remove(key);
				continue;
			}
			Ped ped = new Ped(key);
			if (!ped.IsDead || LooksKnockedOut(ped))
			{
				continue;
			}
			_factionHits.Remove(key);
			int num = PED.GET_PED_SOURCE_OF_DEATH(key);
			int handle = Game.Player.Character.Handle;
			if (num != 0 && num != handle && !IsCompanionKiller(num))
			{
				NoteKill(ped, item.Value.Item1?.Id);
				continue;
			}
			NoteKill(ped, item.Value.Item1?.Id);
			try
			{
				NoteFairKill(item.Value.Item1, ped);
			}
			catch (Exception ex)
			{
				GrudgeLog("FAIRGAME failed: " + ex.Message);
			}
			try
			{
				MercyTakenBack("h" + key);
			}
			catch
			{
			}
			string key2 = item.Value.Item1?.Id ?? "";
			int num2 = Math.Max(1, item.Value.Item1?.UnnamedKillsPerPoint ?? Balance.UnnamedKillsPerPoint);
			Dictionary<string, int> dictionary = Chronicle.UnnamedKills ?? (Chronicle.UnnamedKills = new Dictionary<string, int>());
			dictionary.TryGetValue(key2, out var value);
			value++;
			if (value >= num2)
			{
				value = 0;
				AddNotoriety(item.Value.Item1, Notoriety.ForKill(0), (num2 == 1) ? "killed one of their men" : $"killed {num2} of their men");
			}
			try
			{
				ControlAfterKill(item.Value.Item1, 0, ped.Position);
			}
			catch
			{
			}
			dictionary[key2] = value;
			SaveWorld();
		}
	}

	private NemesisRecord NewRecord(uint modelHash, string zone, Gang forGang = null, int rank = 1)
	{
		Gang gang = forGang ?? Gangs.ForModel(modelHash) ?? (RallyModel(modelHash) ? Gangs.Klan : null);
		string[] array = gang?.FirstNames ?? NameBank.AmericanFirst;
		string[] array2 = gang?.LastNames ?? NameBank.AmericanLast;
		string[] array3 = gang?.Titles ?? NameBank.AmericanTitles;
		if (Models.Female(modelHash) && array != NameBank.WapitiFirst)
		{
			array = FemaleFirstFor(array);
			array3 = NameBank.FemaleTitles;
		}
		string name = null;
		string text = null;
		for (int i = 0; i < 30; i++)
		{
			name = array[_rng.Next(array.Length)] + " " + array2[_rng.Next(array2.Length)];
			text = array3[_rng.Next(array3.Length)];
			string sur = name.Substring(name.LastIndexOf(' ') + 1);
			bool num = gang != null && gang.RankInName && Roster.Any((NemesisRecord n) => n.Gang == gang.Id && n.Name != null && n.Name.EndsWith(" " + sur));
			bool flag = gang?.ExcludedNames != null && gang.ExcludedNames.Contains(name);
			if (!num && !flag && !Roster.Any((NemesisRecord n) => n.Name == name) && !Gangs.All.Any((Gang g) => g.LeaderName.EndsWith(name)))
			{
				break;
			}
		}
		NemesisRecord nemesisRecord = new NemesisRecord
		{
			Id = NewId(12),
			Rank = rank,
			Gang = gang?.Id,
			Name = name,
			Title = (HasNickname(name, gang != null) ? text : ""),
			ModelHash = modelHash,
			KillLocation = zone,
			KilledPlayerAt = DateTime.Now
		};
		RollNewLife(nemesisRecord, Roster);
		return nemesisRecord;
	}

	private void DrainKeys()
	{
		int num = 0;
		while (_keyQueue.Count > 0 && num++ < 32)
		{
			var (flag, e) = _keyQueue.Dequeue();
			if (flag)
			{
				Guard("key " + e.KeyCode, () =>
				{
					OnKeyDown(null, e);
				});
				continue;
			}
			try
			{
				_bulletImpact.HandleKeyUp(e.KeyCode);
			}
			catch (Exception ex)
			{
				GrudgeLog("ERROR in key up: " + ex.Message);
			}
		}
	}

	private void OnKeyDown(object sender, KeyEventArgs e)
	{
		XPad.NoteKeyboard();
		UiMouse.NoteKey(e.KeyCode);
		if (_iniPanel.Capturing)
		{
			_iniPanel.Capture(e.KeyCode, e.Modifiers & Keys.Modifiers);
			return;
		}
		if (_welcome.Capturing)
		{
			_welcome.Capture(e.KeyCode, e.Modifiers & Keys.Modifiers);
			return;
		}
		Keys rosterMenuKey = Config.RosterMenuKey;
		(Keys, Keys, Keys) tuple = KeyCombo.Extras(rosterMenuKey);
		if (tuple.Item1 != Keys.None && KeyCombo.Is(e, rosterMenuKey, tuple.Item1))
		{
			if (!_iniPanel.IsOpen && (_menu.IsOpen || _bulletImpact.ViewerOpen || _convo != null || _tg != null))
			{
				ShowNotification("enRAGE: close the menu first to open the settings.");
			}
			else
			{
				_iniPanel.Toggle();
			}
		}
		else
		{
			if (_iniPanel.IsOpen && _iniPanel.HandleKey(e.KeyCode, e.Shift))
			{
				return;
			}
			if (_welcome.IsOpen)
			{
				_welcome.HandleKey(e.KeyCode);
			}
			else
			{
				if (PaperKey(e.KeyCode))
				{
					return;
				}
				if (e.Control && !e.Alt && !e.Shift && e.KeyCode == Config.ForceAmbushKey)
				{
					if (_debugOn || _spawnMenuOpen)
					{
						ToggleSpawnMenu();
					}
				}
				else if (_spawnMenuOpen)
				{
					SpawnMenuKey(e.KeyCode);
				}
				else if (_search != null)
				{
					if (!e.Control && !e.Alt)
					{
						if (!UiMouse.Sending)
						{
							_search.Pad = false;
							_search.OnKeys = false;
						}
						SearchKey(e.KeyCode, e.Shift);
					}
				}
				else if (e.Control && e.KeyCode == Keys.F && (_menu.IsOpen || _bulletImpact.ViewerOpen))
				{
					OpenSearch(pad: false);
				}
				else if (e.KeyCode == Keys.Tab && !e.Control && !e.Alt && !UiMouse.Sending && (_menu.IsOpen || _bulletImpact.ViewerOpen))
				{
					if (_tabDownAt == 0)
					{
						_tabDownAt = Environment.TickCount | 1;
					}
				}
				else if (tuple.Item3 != Keys.None && KeyCombo.Is(e, rosterMenuKey, tuple.Item3))
				{
					if (Config.DebugEnabled || _debugOn)
					{
						ToggleDebug();
					}
				}
				else if (tuple.Item2 != Keys.None && KeyCombo.Is(e, rosterMenuKey, tuple.Item2))
				{
					UndoRestore();
				}
				else if (KeyCombo.Is(e, rosterMenuKey))
				{
					Dispatch(rosterMenuKey);
				}
				else
				{
					if (e.KeyCode == KeyCombo.Base(rosterMenuKey))
					{
						MenuKeyNote("got " + KeyCombo.Name(e.KeyCode | (e.Modifiers & Keys.Modifiers)) + " - not the menu key (the modifiers differ)", routine: true);
					}
					if ((KeyCombo.Mods(rosterMenuKey) != Keys.None || e.KeyCode != KeyCombo.Base(rosterMenuKey)) && e.KeyCode != Config.ForceAmbushKey)
					{
						Dispatch(e.KeyCode);
					}
				}
			}
		}
	}

	internal static void UiSound(string name)
	{
		try
		{
			string text;
			string text2;
			if (UiSounds.TryGetValue(name, out (string, string) value))
			{
				(text, text2) = value;
			}
			else
			{
				text2 = "HUD_PLAYER_MENU";
				text = name;
			}
			Crumbs.Native("cs sound release");
			while (_uiSoundIds.Count > 0 && (_uiSoundIds.Count > 12 || UiDraw.RealMs - _uiSoundIds.Peek().at > 2000))
			{
				AUDIO.RELEASE_SOUND_ID(_uiSoundIds.Dequeue().id);
			}
			if (text2 != "HUD_PLAYER_MENU")
			{
				Crumbs.Native("cs soundset prepare");
				if (!AUDIO.PREPARE_SOUNDSET(text2, p1: false) && _soundSetMissLogged.Add(text2))
				{
					SoundLog?.Invoke("SOUND set " + text2 + " not loaded yet (asked for it) - '" + text + "' may be silent");
				}
			}
			int sOUND_ID = AUDIO.GET_SOUND_ID();
			if (sOUND_ID < 0)
			{
				if (_soundSetMissLogged.Add("#id"))
				{
					SoundLog?.Invoke($"SOUND no sound id free ({_uiSoundIds.Count} held) - '{text}' skipped");
				}
				return;
			}
			Crumbs.Native("cs sound");
			Function.Call(14870059130450844401uL, sOUND_ID, text, text2, true);
			_uiSoundIds.Enqueue((sOUND_ID, UiDraw.RealMs));
		}
		catch
		{
		}
	}

	internal static void ReleaseUiSounds()
	{
		Crumbs.Native("cs sound release all");
		while (_uiSoundIds.Count > 0)
		{
			try
			{
				AUDIO.RELEASE_SOUND_ID(_uiSoundIds.Dequeue().id);
			}
			catch
			{
			}
		}
	}

	private void MenuKeySound(Keys key)
	{
		if (!_menu.IsOpen && !_bulletImpact.ViewerOpen && _convo == null && _tg == null)
		{
			return;
		}
		switch (key)
		{
		case Keys.Up:
			UiSound("NAV_UP");
			return;
		case Keys.Down:
			UiSound("NAV_DOWN");
			return;
		case Keys.Left:
			UiSound("NAV_LEFT");
			return;
		case Keys.Right:
			UiSound("NAV_RIGHT");
			return;
		case Keys.Return:
			UiSound("SELECT");
			return;
		case Keys.Back:
		case Keys.Escape:
			UiSound("BACK");
			return;
		case Keys.Prior:
		case Keys.Q:
			UiSound("BUMPER_LEFT");
			return;
		case Keys.Tab:
		case Keys.Next:
		case Keys.E:
			UiSound("BUMPER_RIGHT");
			return;
		}
		if (key >= Keys.D1 && key <= Keys.D9 && (_convo != null || _tg != null))
		{
			UiSound("SELECT");
		}
	}

	private void Dispatch(Keys key)
	{
		if (key == Keys.Escape && (_menu.IsOpen || _bulletImpact.ViewerOpen || _convo != null || _tg != null))
		{
			key = Keys.Back;
		}
		if (key == Keys.O && (_menu.IsOpen || _bulletImpact.ViewerOpen) && _convo == null && _tg == null)
		{
			_bulletImpact.CloseViewer();
			OpenSetupScreen();
			return;
		}
		MenuKeySound(key);
		if ((_convo != null && HandleConvoKey(key)) || (_tg != null && HandleTelegraphKey(key)) || (key == Config.TelegraphKey && !_menu.IsOpen && !_bulletImpact.ViewerOpen && OnTelegraphKey()))
		{
			return;
		}
		if (_bulletImpact.ViewerOpen)
		{
			if (key == Config.RosterMenuKey)
			{
				_bulletImpact.CloseViewer();
				_menu.Open();
			}
			else if (key == Keys.Home)
			{
				_bulletImpact.CloseViewer();
				_menu.Open();
				_menu.ShowArthur();
				UiSound("SELECT");
			}
			else
			{
				_bulletImpact.HandleKey(key, allowOpen: false);
			}
		}
		else if (_menu.IsOpen && key == Keys.Tab)
		{
			if (!_menu.InWorld)
			{
				_menu.ShowWorld();
				return;
			}
			_menu.Toggle();
			_bulletImpact.OpenViewer();
		}
		else
		{
			if (_menu.IsOpen && _menu.HandleKey(key))
			{
				return;
			}
			bool flag = _convo != null || _tg != null;
			bool allowOpen = !flag && !_menu.IsOpen && !WorldBusy(Game.Player.Character);
			if (_bulletImpact.HandleKey(key, allowOpen))
			{
				return;
			}
			if (key == Config.CivicMenuKey && !_menu.IsOpen)
			{
				OpenCivicDeskHotkey();
			}
			else if (key == Config.InterrogateKey && !_menu.IsOpen)
			{
				OnInterrogateKey();
			}
			else
			{
				if (key != Config.RosterMenuKey)
				{
					return;
				}
				bool soft = false;
				string text;
				if (_menu.IsOpen)
				{
					text = null;
				}
				else
				{
					text = (flag ? "a panel is open" : MenuBlocked(out soft));
				}
				if (((text != null) & soft) && _menuHeld && Environment.TickCount - _menuHeldAt < 4000)
				{
					_menuHeld = false;
					MenuKeyNote("opened anyway (second press) - " + text);
					text = null;
				}
				if (text != null)
				{
					MenuKeyNote("blocked - " + text);
					if (soft)
					{
						_menuHeld = true;
						_menuHeldAt = Environment.TickCount;
						ShowNotification("enRAGE: a game screen seems to be open, so the menu waited. Press " + KeyCombo.MenuText + " again to open it anyway.");
					}
					else
					{
						ShowNotification("enRAGE: the menu can't open while " + MenuBlockedText(text) + ".");
					}
					return;
				}
				if (!_menu.IsOpen)
				{
					try
					{
						OpenLastTab();
						MenuKeyNote("opened", routine: true);
						return;
					}
					catch (Exception ex)
					{
						GrudgeLog($"ERROR opening the menu: {ex}");
						MenuKeyNote("error - " + ex.Message);
						ShowNotification("enRAGE: the menu hit an error and didn't open. It's in grudges.log (Documents, Rockstar Games, Red Dead Redemption 2, enRAGE).");
						return;
					}
				}
				_menu.Toggle();
				MenuKeyNote("closed", routine: true);
			}
		}
	}

	private void DrawMenu()
	{
		try
		{
			_menu.Draw();
			_menuDrawFails = 0;
		}
		catch
		{
			if (++_menuDrawFails >= 3 && _menu.IsOpen)
			{
				_menuDrawFails = 0;
				_menu.Toggle();
				MenuKeyNote("closed - it failed to draw 3 frames running");
				ShowNotification("enRAGE: the menu hit an error and closed. It's in grudges.log (Documents, Rockstar Games, Red Dead Redemption 2, enRAGE).");
			}
			throw;
		}
	}

	private void WatchSettingsFile()
	{
		if (!_settingsEdited && !_iniPanel.IsOpen && Config.EditedOutside())
		{
			Config.ReadEdited();
		}
		if (_settingsEdited)
		{
			_settingsEdited = false;
			GrudgeLog("SETTINGS NemesisMod.ini was changed outside the game - read in (menu key " + KeyCombo.Name(Config.RosterMenuKey) + ")");
			if (Config.KeysNote != null)
			{
				GrudgeLog("KEYS " + Config.KeysNote);
			}
			ShowNotification("enRAGE: NemesisMod.ini changed, your settings are read in. Menu key: " + KeyCombo.MenuText + "." + ((Config.KeysNote != null) ? (" " + Config.KeysNote) : ""));
		}
	}

	private static string MenuBlockedText(string why)
	{
		if (!why.StartsWith("pause menu"))
		{
			if (!why.Contains("dead"))
			{
				if (!why.Contains("arrest"))
				{
					if (!why.Contains("fade"))
					{
						if (!why.Contains("control"))
						{
							if (!why.StartsWith("the catalog is open"))
							{
								if (!(why == "a panel is open"))
								{
									return why;
								}
								return "a conversation or the telegraph is open";
							}
							return "a game screen is open" + why.Substring("the catalog is open".Length);
						}
						return "the game has your controls (a shop, a cutscene, a scripted moment or another mod)";
					}
					return "the screen is fading";
				}
				return "you're being arrested";
			}
			return "you're dead";
		}
		return "the pause menu is up";
	}

	private void MenuKeyNote(string what, bool routine = false)
	{
		if (!routine || _menuKeyNotes < 12)
		{
			if (routine)
			{
				_menuKeyNotes++;
			}
			GrudgeLog("MENU key " + KeyCombo.MenuText + ": " + what);
		}
	}

	private void StampNemesisHandles()
	{
		DateTime now = DateTime.UtcNow;
		List<KeyValuePair<int, NemesisRecord>> list = _worldNemeses.ToList();
		if (_activeNemesisPed != null && ActiveRecord != null)
		{
			list.Add(new KeyValuePair<int, NemesisRecord>(_activeNemesisPed.Handle, ActiveRecord));
		}
		foreach (KeyValuePair<int, NemesisRecord> item in list)
		{
			if (item.Value != null && ENTITY.DOES_ENTITY_EXIST(item.Key) && !ENTITY.IS_ENTITY_DEAD(item.Key))
			{
				item.Value.LastHandle = item.Key;
				item.Value.LastHandleModel = ENTITY.GET_ENTITY_MODEL(item.Key);
				item.Value.LastHandleUtc = now;
			}
		}
		SaveRoster();
		Chronicle.Bodies = (from kv in _nemesisBodies
			where kv.Value != null && ENTITY.DOES_ENTITY_EXIST(kv.Key)
			select $"{kv.Key}|{ENTITY.GET_ENTITY_MODEL(kv.Key)}|{now.Ticks}|{kv.Value.Id}").ToList();
		SaveWorld();
	}

	internal bool KnownBody(int h, uint model)
	{
		if (_nemesisBodies.ContainsKey(h))
		{
			return true;
		}
		List<string> bodies = Chronicle.Bodies;
		if (bodies == null)
		{
			return false;
		}
		long ticks = DateTime.UtcNow.Ticks;
		foreach (string item in bodies)
		{
			string[] array = item.Split('|');
			if (array.Length >= 3 && int.TryParse(array[0], out var result) && uint.TryParse(array[1], out var result2) && long.TryParse(array[2], out var result3) && result == h && result2 == model && ticks - result3 < 18000000000L)
			{
				return true;
			}
		}
		return false;
	}

