	internal string CampLine(NemesisRecord n)
	{
		if (!n.IsAlive)
		{
			return "-";
		}
		if (IsOfficer(n))
		{
			CampSite campSite = CampOf(n);
			if (campSite == null)
			{
				return "No camp";
			}
			if (!n.CampKnown)
			{
				return "Unknown - interrogate his men to find it";
			}
			return campSite.Label + "  (" + GetZoneName(SitePos(campSite)) + ")";
		}
		NemesisRecord nemesisRecord = BossOf(n);
		if (nemesisRecord != null)
		{
			Gang gang = Gangs.Of(nemesisRecord);
			if (gang == null || !gang.RankInName)
			{
				return "Rides with " + OfficerTitle(nemesisRecord) + " " + nemesisRecord.FullName;
			}
			return "Serves under " + nemesisRecord.Name;
		}
		return "Drifting - no captain";
	}

	internal Vector3? HomeOf(NemesisRecord n)
	{
		if (n.Gang != null)
		{
			CampSite campSite = CampOf(IsOfficer(n) ? n : BossOf(n));
			if (campSite != null)
			{
				return SitePos(campSite);
			}
		}
		if (!n.HasOrigin)
		{
			return null;
		}
		return new Vector3(n.OriginX, n.OriginY, n.OriginZ);
	}

	internal bool InHuntingRange(NemesisRecord n, Vector3 playerPos)
	{
		if (n.HateTier == HateTier.Murderous)
		{
			return true;
		}
		Vector3? vector = HomeOf(n);
		if (!vector.HasValue)
		{
			return true;
		}
		return playerPos.DistanceTo(vector.Value) <= ((n.HateTier == HateTier.Vengeful) ? Config.VengefulRange : Config.ResentfulRange) * (Quirks.HasSkill(n, "tracker") ? 1.5f : 1f);
	}

	internal string RoamText(NemesisRecord n)
	{
		if (n.HateTier == HateTier.Murderous)
		{
			return "hunts you anywhere";
		}
		string arg = ((n.Gang != null && HomeOf(n).HasValue) ? "his camp" : n.KillLocation);
		int num = (int)((n.HateTier == HateTier.Vengeful) ? Config.VengefulRange : Config.ResentfulRange);
		if (HomeOf(n).HasValue)
		{
			return $"won't stray far from {arg} (about {num} m)";
		}
		return "stays near where it happened";
	}

	internal bool CanTrackCamp(NemesisRecord n)
	{
		if (IsOfficer(n) && n.CampKnown && CampOf(n) != null && n.CanHunt)
		{
			return !n.PresumedDead;
		}
		return false;
	}

	private void OnNemesisCrippled(string id, CrippleLevel level)
	{
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == id);
		if (nemesisRecord == null)
		{
			return;
		}
		nemesisRecord.AddFear(Balance.FearPerCripple);
		nemesisRecord.AddYourNotoriety(10);
		if (level >= CrippleLevel.SpineBroken)
		{
			if (!nemesisRecord.Paralyzed)
			{
				GrudgeNotice(nemesisRecord.FullName + " will never walk again.");
			}
			nemesisRecord.Paralyzed = true;
		}
		else
		{
			nemesisRecord.Limp = true;
		}
		SaveRoster();
	}

	private NemesisTag NemesisTagFor(int handle)
	{
		NemesisRecord nemesisRecord = null;
		bool flag = false;
		NemesisRecord value;
		NemesisRecord value2;
		if (_activeNemesisPed != null && ActiveRecord != null && handle == _activeNemesisPed.Handle)
		{
			nemesisRecord = ActiveRecord;
		}
		else if (_worldNemeses.TryGetValue(handle, out value))
		{
			nemesisRecord = value;
		}
		else if (_followerOf.TryGetValue(handle, out value2))
		{
			nemesisRecord = value2;
			flag = true;
		}
		else if (_sightingPed != null && handle == _sightingPed.Handle)
		{
			nemesisRecord = _sightingRec;
		}
		string text = (_named.TryGetValue(handle, out var value3) ? value3.Name : null);
		if (nemesisRecord == null)
		{
			if (text != null)
			{
				return new NemesisTag
				{
					PersonName = text
				};
			}
			return null;
		}
		return new NemesisTag
		{
			Id = nemesisRecord.Id,
			Name = (nemesisRecord.FullName ?? ""),
			IsFollower = flag,
			PersonName = (flag ? text : nemesisRecord.Name)
		};
	}

	private NemesisFate FateOf(string id)
	{
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == id);
		if (nemesisRecord == null)
		{
			return NemesisFate.Unknown;
		}
		if (!nemesisRecord.IsAlive)
		{
			return NemesisFate.Dead;
		}
		if (nemesisRecord.PresumedDead)
		{
			return NemesisFate.PresumedDead;
		}
		if (nemesisRecord.TimesCheatedDeath <= 0)
		{
			return NemesisFate.Hunting;
		}
		return NemesisFate.CheatedDeath;
	}

