	private void Guard(string what, Action a)
	{
		Crumbs.Mark(what);
		if (StartupTrace.TicksLeft > 0)
		{
			StartupTrace.Write("  " + what);
		}
		long elapsedTicks = _saveClock.ElapsedTicks;
		double modelWaitMs = ModelWaitMs;
		int num = _guardDepth++;
		try
		{
			a();
		}
		catch (ThreadAbortException)
		{
			_guardDepth = num;
			throw;
		}
		catch (Exception ex2)
		{
			ErrorCount++;
			string key = what + ":" + ex2.GetType().Name + ":" + ex2.Message;
			LastError = what + ": " + ex2.GetType().Name + " " + ex2.Message;
			if (!_errorLoggedAt.TryGetValue(key, out var value) || Game.GameTime - value > 60000)
			{
				_errorLoggedAt[key] = Game.GameTime;
				GrudgeLog($"ERROR in {what}: {ex2}");
			}
		}
		_guardDepth = num;
		double num2 = (double)(_saveClock.ElapsedTicks - elapsedTicks) * 1000.0 / (double)Stopwatch.Frequency;
		double num3 = Math.Max(0.0, ModelWaitMs - modelWaitMs);
		double num4 = Math.Max(0.0, num2 - num3);
		NotePerf(what, num4, num3);
		switch (num)
		{
		case 1:
			_systemsMs += num4;
			if (num4 > _tickTopMs)
			{
				_tickTopMs = num4;
				_tickTop = what;
			}
			break;
		case 0:
			if (what == "tick")
			{
				NotePerf("(outside the systems)", Math.Max(0.0, num4 - _systemsMs), 0.0);
				_systemsMs = 0.0;
				_lastTickHeld = num4;
				_lastTickWaited = num3 > 0.0;
				_lastTickTop = _tickTop;
				_lastTickTopMs = _tickTopMs;
				_tickTop = null;
				_tickTopMs = 0.0;
			}
			break;
		}
		if (num4 >= 8.0 && what != "saves" && (!_slowLoggedAt.TryGetValue(what, out var value2) || Game.GameTime - value2 > 60000))
		{
			_slowLoggedAt[what] = Game.GameTime;
			GrudgeLog((num3 >= 1.0) ? $"SLOW {what} held the frame {num4:0} ms (and waited {num3:0} ms for models to load - the game ran on meanwhile)" : $"SLOW {what} took {num4:0} ms");
		}
	}

	private void NoteFrame()
	{
		double num = (double)_saveClock.ElapsedTicks * 1000.0 / (double)Stopwatch.Frequency;
		if (_lastTickAt > 0.0)
		{
			double num2 = num - _lastTickAt;
			if (!_lastTickWaited && !_busy && num2 >= 50.0 && num2 < 1500.0)
			{
				_slowFrames++;
				if (_lastTickHeld >= num2 * 0.5)
				{
					_slowFramesMod++;
					if (Environment.TickCount - _slowFrameLoggedAt > 1000)
					{
						_slowFrameLoggedAt = Environment.TickCount;
						GrudgeLog(string.Format("SLOWFRAME {0:0} ms - the mod held {1:0} ms of it, most in {2} ({3:0} ms)", num2, _lastTickHeld, _lastTickTop ?? "(between its systems)", _lastTickTopMs));
					}
				}
			}
		}
		_lastTickAt = num;
	}

	private void NotePerf(string what, double ms, double waited)
	{
		if (!_perf.TryGetValue(what, out var value))
		{
			_perf[what] = new PerfStat
			{
				First = ms,
				Waited = waited
			};
			return;
		}
		value.Total += ms;
		value.Calls++;
		value.Waited += waited;
		if (ms > value.Worst)
		{
			value.Worst = ms;
		}
		if (ms >= 16.0)
		{
			value.Over16++;
		}
	}

	private void WritePerf(bool force = false)
	{
		int num = Environment.TickCount - _perfSince;
		if (!force && num < 600000)
		{
			return;
		}
		_perfSince = Environment.TickCount;
		if (!_perf.TryGetValue("tick", out var value) || value.Calls == 0)
		{
			return;
		}
		int calls = value.Calls;
		int[] array = new int[3]
		{
			GC.CollectionCount(0),
			GC.CollectionCount(1),
			GC.CollectionCount(2)
		};
		double num2 = ((_perf.TryGetValue("(outside the systems)", out var value2) && value2.Calls > 0) ? (value2.Total / (double)calls) : 0.0);
		GrudgeLog($"PERF {(double)num / 60000.0:0.0} min, {calls} frames: the mod {value.Total / (double)calls:0.00} ms a frame (worst {value.Worst:0}, over 16 ms {value.Over16}x; outside the systems {num2:0.00}) | " + $"slow frames (50 ms+) {_slowFrames}, the mod's {_slowFramesMod} | " + $"GC {array[0] - _gcAt[0]} / {array[1] - _gcAt[1]} / {array[2] - _gcAt[2]} (gen 0/1/2) | mod {(double)GC.GetTotalMemory(forceFullCollection: false) / 1048576.0:0} MB");
		_gcAt = array;
		foreach (KeyValuePair<string, PerfStat> item in (from kv in _perf
			where kv.Key != "tick" && kv.Value.Calls > 0
			orderby kv.Value.Total descending
			select kv).Take(15).ToList())
		{
			GrudgeLog(string.Format("PERF   {0,-22} {1,6:0.00} ms a frame  {2:0.0} s in all  worst {3,4:0}  over 16 ms {4}x{5}", item.Key, item.Value.Total / (double)calls, item.Value.Total / 1000.0, item.Value.Worst, item.Value.Over16, (item.Value.Waited >= 100.0) ? $"  (+{item.Value.Waited / 1000.0:0.0} s waiting for models)" : ""));
		}
		List<KeyValuePair<string, PerfStat>> list = (from kv in _perf
			where kv.Value.First >= 5.0
			orderby kv.Value.First descending
			select kv).Take(8).ToList();
		if (list.Count > 0)
		{
			GrudgeLog("PERF   first calls (compiling, once): " + string.Join(", ", list.Select((KeyValuePair<string, PerfStat> kv) => $"{kv.Key} {kv.Value.First:0}")));
		}
		foreach (PerfStat value3 in _perf.Values)
		{
			value3.Total = (value3.Worst = (value3.Waited = 0.0));
			value3.Calls = (value3.Over16 = 0);
			value3.First = 0.0;
		}
		_slowFrames = (_slowFramesMod = 0);
	}

