	private void MoveForeignXRays()
	{
		HashSet<string> hashSet = new HashSet<string>(from r in Roster
			where r.Id != null && (r.Origin != GrudgeOrigin.GangMember || (r.Scars?.Count ?? 0) > 0 || !r.IsAlive)
			select r.Id);
		try
		{
			List<NemesisRecord> list = SafeFile.Read<List<NemesisRecord>>(Path.Combine(_saveDir, "fallen.json"));
			if (list != null)
			{
				foreach (NemesisRecord item in list)
				{
					if (item != null && item.Id != null)
					{
						hashSet.Add(item.Id);
					}
				}
			}
		}
		catch
		{
		}
		if (hashSet.Count != 0)
		{
			string text = Path.Combine(_saveDir, $"xray_log.other-world-{DateTime.Now:yyyyMMdd-HHmmss}.json");
			int num = _bulletImpact.MoveForeignAside(hashSet.Contains, text, out var men);
			if (num > 0)
			{
				GrudgeLog($"XRAY {num} shots on {men} men from another playthrough moved out of this world's X-ray log ({Path.GetFileName(text)})");
			}
		}
	}

	private void LoadRoster()
	{
		List<NemesisRecord> list = SafeFile.Read<List<NemesisRecord>>(_savePath, GrudgeLog, out var found, out var from);
		if ((list == null) & found)
		{
			_rosterLoadFailed = true;
			GrudgeLog("LOAD every copy of nemeses.json is unreadable - the roster won't be saved this session (files kept as .unreadable-*)");
		}
		_rosterGen++;
		ReapplyLeaders();
		_leaderDupesCleaned = false;
		if (list != null)
		{
			Roster = list.Where((NemesisRecord r) => r != null).ToList();
		}
		if (from != null && from != _savePath)
		{
			ShowNotification("enRAGE: nemeses.json was unreadable - loaded the backup (" + Path.GetFileName(from) + ").");
			SaveRoster();
		}
		if ((from == null) & found)
		{
			ShowNotification("enRAGE: your nemeses couldn't be read - nothing will be saved over them this session. The files are kept in the enRAGE folder (.unreadable-*).");
		}
		if (from == _savePath && SafeFile.Daily(_savePath, Path.Combine(_saveDir, "backups")))
		{
			GrudgeLog("LOAD daily roster backup written");
		}
		int num = 0;
		foreach (NemesisRecord item in Roster.ToList())
		{
			try
			{
				MigrateRecord(item);
			}
			catch (Exception ex)
			{
				num++;
				GrudgeLog("LOAD " + item.Name + " (" + item.Id + ") migration failed - kept as is: " + ex.Message);
			}
		}
		if (num > 0)
		{
			ShowNotification(string.Format("{0}: {1} records couldn't be updated (see grudges.log).", "enRAGE", num));
		}
		ArchiveFallen();
	}

	private void MigrateRecord(NemesisRecord rec)
	{
		rec.Scars = rec.Scars ?? new List<Scar>();
		rec.EnsureHate();
		rec.EnsureId();
		if (rec.Gang == null)
		{
			rec.Gang = Gangs.ForModel(rec.ModelHash)?.Id;
		}
		if (!rec.TraitsRolled)
		{
			Traits.Roll(rec, _rng, null);
			_personalitiesAssigned = true;
		}
		rec.Past = rec.Past ?? new List<PastEntry>();
		if (!rec.Personality.HasValue)
		{
			rec.Personality = Personalities.Pick(_rng, rec.Gang != null);
			if (rec.Gang == null && rec.TimesKilledPlayer == 0 && rec.Origin != GrudgeOrigin.Killed)
			{
				rec.Hate = Math.Max(10, Math.Min(100, rec.Hate + Personalities.StartingHate(rec.Personality.Value, rec.Origin) - Hate.Initial(rec.Origin)));
			}
			_personalitiesAssigned = true;
		}
		if (!rec.PastRolled)
		{
			EnsurePast(rec);
			_personalitiesAssigned = true;
		}
		if (!rec.MindRolled)
		{
			EnsureMind(rec);
			_personalitiesAssigned = true;
		}
		if (rec.IsAlive && rec.KinId != null && rec.PastRolled)
		{
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == rec.KinId);
			if (nemesisRecord != null && !Backstory.KinAgeFits(rec, nemesisRecord))
			{
				int bornYear = rec.BornYear;
				Backstory.FitKinAge(rec, nemesisRecord, Seeds.For(rec, "kin"), GameYear());
				Backstory.Roll(rec, Seeds.For(rec, "life"), GameYear(), GameMonth(), derive: false);
				rec.Woven = false;
				GrudgeLog($"HISTORY {rec.Name}: {rec.KinRelation} of {nemesisRecord.Name} was born {bornYear} (his {nemesisRecord.BornYear}) - now {rec.BornYear}, past rewritten");
				_personalitiesAssigned = true;
			}
		}
	}

	private void ArchiveFallen()
	{
		try
		{
			List<NemesisRecord> list = Roster.Where((NemesisRecord n) => !n.IsAlive && !n.PresumedDead).ToList();
			if (list.Count <= 200)
			{
				return;
			}
			List<NemesisRecord> living = Roster.Where((NemesisRecord n) => n.IsAlive).ToList();
			List<NemesisRecord> list2 = (from d in list
				where !Tied(d)
				orderby d.LastDealt
				select d).Take(list.Count - 200).ToList();
			if (list2.Count == 0)
			{
				return;
			}
			string path = Path.Combine(_saveDir, "fallen.json");
			List<NemesisRecord> list3 = SafeFile.Read<List<NemesisRecord>>(path, GrudgeLog, out var found, out var _);
			if ((list3 == null) & found)
			{
				GrudgeLog("LOAD fallen.json unreadable - kept aside, nothing archived this time");
				return;
			}
			list3 = list3 ?? new List<NemesisRecord>();
			HashSet<string> ids = new HashSet<string>(from d in list2
				select d.Id into i
				where i != null
				select i);
			int num = list3.RemoveAll((NemesisRecord a) => a != null && a.Id != null && ids.Contains(a.Id));
			list3.AddRange(list2);
			list3 = (from a in list3
				where a != null
				group a by a.Id ?? Guid.NewGuid().ToString() into g
				select g.Last()).ToList();
			if (num > 0)
			{
				GrudgeLog($"LOAD fallen.json: {num} men already there replaced (no duplicates)");
			}
			SafeFile.Write(path, JsonConvert.SerializeObject(list3), keepBak: true);
			foreach (NemesisRecord item in list2)
			{
				Roster.Remove(item);
			}
			GrudgeLog($"LOAD archived {list2.Count} long-dead men to fallen.json ({list3.Count} there now)");
			SaveRoster();
			bool Tied(NemesisRecord d)
			{
				if (d.TimesKilledPlayer <= 0 && (d.Id == null || (!d.Id.StartsWith("fallen_") && !d.Id.StartsWith("lore_"))))
				{
					return living.Any((NemesisRecord l) =>
					{
						if (!(l.KinId == d.Id) && !(d.KinId == l.Id))
						{
							List<string> friendIds = l.FriendIds;
							if (friendIds == null || !friendIds.Contains(d.Id))
							{
								return l.BossId == d.Id;
							}
						}
						return true;
					});
				}
				return true;
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("LOAD fallen archive failed: " + ex.Message);
		}
	}

	private void SaveRoster()
	{
		_rosterDirty = true;
	}

	internal void FlushRosterSave(bool force = false, bool sliced = false)
	{
		if (!_rosterDirty || (!force && Game.GameTime < _nextRosterSave) || (sliced && !force && Slicing("roster")))
		{
			return;
		}
		_nextRosterSave = Game.GameTime + 60000;
		_lastRosterFlushAt = Game.GameTime;
		if (force)
		{
			_rosterGen++;
			if (SafeFile.WaitWrites())
			{
				if (SaveRosterNow())
				{
					_rosterDirty = false;
				}
				return;
			}
			if (_rosterLoadFailed)
			{
				_rosterDirty = false;
				return;
			}
			RefreshArmyNames();
			string text;
			try
			{
				text = JsonConvert.SerializeObject(Roster);
			}
			catch (Exception ex)
			{
				GrudgeLog("SAVE roster failed to serialize: " + ex.Message);
				return;
			}
			_rosterDirty = false;
			try
			{
				Directory.CreateDirectory(_saveDir);
			}
			catch
			{
			}
			SafeFile.WriteLater(_savePath, text, keepBak: true, (Exception err) =>
			{
				if (err != null)
				{
					_rosterDirty = true;
					_rosterWriteError = err.Message;
				}
			});
			GrudgeLog("SAVE roster: the background writer is busy - queued behind it");
			return;
		}
		if (_rosterLoadFailed)
		{
			_rosterDirty = false;
			return;
		}
		RefreshArmyNames();
		if (sliced)
		{
			_rosterDirty = false;
			try
			{
				Directory.CreateDirectory(_saveDir);
			}
			catch
			{
			}
			StartSlice("roster", _savePath, Roster, _rosterGen, (Exception err) =>
			{
				if (err != null)
				{
					_rosterDirty = true;
					_rosterWriteError = err.Message;
				}
			});
			return;
		}
		_rosterGen++;
		string text2;
		try
		{
			text2 = JsonConvert.SerializeObject(Roster);
		}
		catch (Exception ex2)
		{
			GrudgeLog("SAVE roster failed to serialize: " + ex2.Message);
			return;
		}
		_rosterDirty = false;
		try
		{
			Directory.CreateDirectory(_saveDir);
		}
		catch
		{
		}
		SafeFile.WriteLater(_savePath, text2, keepBak: true, (Exception err) =>
		{
			if (err != null)
			{
				_rosterDirty = true;
				_rosterWriteError = err.Message;
			}
		});
	}

	private bool SaveRosterNow()
	{
		if (_rosterLoadFailed)
		{
			GrudgeLog("SAVE roster skipped - it failed to load this session (nemeses.json left as it is)");
			return true;
		}
		RefreshArmyNames();
		try
		{
			Directory.CreateDirectory(_saveDir);
			SafeFile.Write(_savePath, JsonConvert.SerializeObject(Roster), keepBak: true);
			if (_rosterSaveFailedShown)
			{
				GrudgeLog("SAVE roster written again");
			}
			_rosterSaveFailedShown = false;
			return true;
		}
		catch (Exception ex)
		{
			GrudgeLog("SAVE roster failed (tried again on the next pass): " + ex.Message);
			if (!_rosterSaveFailedShown)
			{
				ShowNotification("enRAGE save failed: " + ex.Message + " - trying again.");
			}
			_rosterSaveFailedShown = true;
			return false;
		}
	}

	private void QueueDeathNews(NemesisRecord dead, bool byYou, string by, WorldEvent ev, Vector3? pos)
	{
		List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.IsAlive && n != dead && (n.KinId == dead.Id || dead.KinId == n.Id)).ToList();
		foreach (NemesisRecord item4 in FriendsOf(dead))
		{
			if (item4.IsAlive && !list.Contains(item4))
			{
				list.Add(item4);
			}
		}
		if (byYou && pos.HasValue)
		{
			try
			{
				QueuePeopleNews(dead.Name, dead.KillLocation, dead.CircleAcq, pos.Value, dead);
			}
			catch (Exception ex)
			{
				GrudgeLog("NEWS failed: " + ex.Message);
			}
		}
		if (list.Count == 0)
		{
			return;
		}
		long num = GameMinutesNow();
		List<DeathNews> list2 = Chronicle.DeathNews ?? (Chronicle.DeathNews = new List<DeathNews>());
		foreach (NemesisRecord item5 in list)
		{
			(long minutes, string why) tuple = NewsDelay(item5, dead, ev, pos);
			long item = tuple.minutes;
			string item2 = tuple.why;
			DeathNews item3 = new DeathNews
			{
				DeadId = dead.Id,
				DeadName = dead.Name,
				KinId = item5.Id,
				ByYou = byYou,
				By = by,
				EventId = ev?.Id,
				At = num,
				DueAt = num + item
			};
			list2.Add(item3);
			if (item <= 0)
			{
				_nextNewsCheck = Math.Min(_nextNewsCheck, Game.GameTime + 1500);
				GrudgeLog(Pron.Her("NEWS " + item5.FullName + " saw " + dead.FullName + " go down (" + item2 + ")", Models.Female(item5.ModelHash)));
			}
			else
			{
				GrudgeLog(Pron.Her($"NEWS {item5.FullName} will hear of {dead.FullName}'s death in {(float)item / 60f:0.#} h ({item2})", Models.Female(item5.ModelHash)));
			}
		}
		SaveWorld();
	}

	private (long minutes, string why) NewsDelay(NemesisRecord k, NemesisRecord dead, WorldEvent ev, Vector3? pos)
	{
		if (ev != null && ev.People.Any((WorldPart p) => p.Id == k.Id))
		{
			return (minutes: 0L, why: "he was there");
		}
		if (pos.HasValue)
		{
			foreach (KeyValuePair<int, NemesisRecord> worldNemese in _worldNemeses)
			{
				if (worldNemese.Value == k)
				{
					Ped ped = Entity.FromHandle(worldNemese.Key) as Ped;
					if (ped != null && ped.Exists() && !ped.IsDead && ped.Position.DistanceTo(pos.Value) < 60f)
					{
						return (minutes: 0L, why: "he saw it");
					}
				}
			}
			if (ActiveRecord == k && _activeNemesisPed != null && _activeNemesisPed.Exists() && _activeNemesisPed.Position.DistanceTo(pos.Value) < 60f)
			{
				return (minutes: 0L, why: "he saw it");
			}
		}
		if (k.Gang != null && k.Gang == dead.Gang)
		{
			(int, string) tuple = (((k.CampId != null && k.CampId == dead.CampId) || k.BossId == dead.Id || dead.BossId == k.Id || (k.BossId != null && k.BossId == dead.BossId)) ? (H(2, 8), "his crew carried it") : (H(6, 24), "word through the outfit"));
			return (minutes: tuple.Item1, why: tuple.Item2);
		}
		if (k.HasOrigin && pos.HasValue && new Vector3(k.OriginX - pos.Value.X, k.OriginY - pos.Value.Y, 0f).Length() < 800f)
		{
			return (minutes: H(4, 16), why: "it happened near his home");
		}
		return (minutes: H(24, 72), why: "word travels slow");
		int H(int lo, int hi)
		{
			return (lo + _rng.Next(hi - lo + 1)) * 60 + _rng.Next(60);
		}
	}

	private void UpdateDeathNews()
	{
		if (Game.GameTime < _nextNewsCheck)
		{
			return;
		}
		_nextNewsCheck = Game.GameTime + 5000;
		UpdatePeopleNews();
		List<DeathNews> deathNews = Chronicle.DeathNews;
		if (deathNews == null || deathNews.Count == 0)
		{
			return;
		}
		long now = GameMinutesNow();
		List<DeathNews> list = (from n in deathNews
			where n.DueAt <= now
			orderby n.DueAt
			select n).ToList();
		if (list.Count == 0)
		{
			return;
		}
		foreach (DeathNews item in list)
		{
			deathNews.Remove(item);
			DeliverNews(item);
		}
		SaveWorld();
	}

	private void DeliverNews(DeathNews n)
	{
		NemesisRecord nemesisRecord = FindRecord(n.KinId);
		NemesisRecord nemesisRecord2 = FindRecord(n.DeadId);
		if (nemesisRecord == null || !nemesisRecord.IsAlive || nemesisRecord2 == null)
		{
			GrudgeLog("NEWS of " + n.DeadName + " dropped (he's gone)");
			return;
		}
		if (nemesisRecord2.IsAlive && !nemesisRecord2.PresumedDead)
		{
			GrudgeLog("NEWS of " + n.DeadName + " dropped (he's alive)");
			return;
		}
		if (n.DueAt > n.At)
		{
			GrudgeLog($"NEWS {nemesisRecord.FullName} hears of {nemesisRecord2.FullName}'s death ({(float)(GameMinutesNow() - n.At) / 60f:0.#} h after)");
		}
		if (n.ByYou)
		{
			KinReact(nemesisRecord2, nemesisRecord.Id);
			return;
		}
		OffscreenGrief(nemesisRecord2, n.By, (n.EventId != null) ? Chronicle.Events.FirstOrDefault((WorldEvent e) => e.Id == n.EventId) : null, nemesisRecord.Id, n.DueAt > n.At);
	}

	internal string DeathNewsLine()
	{
		List<DeathNews> deathNews = Chronicle.DeathNews;
		if (deathNews == null || deathNews.Count == 0)
		{
			return "death news: nothing on the road";
		}
		long num = GameMinutesNow();
		DeathNews deathNews2 = deathNews.OrderBy((DeathNews n) => n.DueAt).First();
		return string.Format("death news: {0} on the road - next: {1} hears of {2} in {3:0.#} h", deathNews.Count, FindRecord(deathNews2.KinId)?.Name ?? "?", deathNews2.DeadName, (float)Math.Max(0L, deathNews2.DueAt - num) / 60f);
	}

	internal static string Compass(Vector3 from, Vector3 to)
	{
		double num = Math.Atan2(to.X - from.X, to.Y - from.Y) * 180.0 / Math.PI;
		if (num < 0.0)
		{
			num += 360.0;
		}
		return (new string[8] { "north", "north-east", "east", "south-east", "south", "south-west", "west", "north-west" })[(int)Math.Round(num / 45.0) % 8];
	}

	private void ToggleDebug()
	{
		DebugMode = (DebugMode + 1) % DebugModeNames.Length;
		_debugOn = DebugMode != 0;
		XRayViewer.DebugOn = _debugOn;
		NemesisRecord.ShowSecrets = _debugOn;
		if (!_debugOn)
		{
			HideMapIcons();
		}
		ShowNotification(_debugOn ? ("enRAGE debug: " + DebugModeNames[DebugMode] + " (Ctrl+F11: next)") : "enRAGE debug overlay off.");
	}

	private bool DebugShows(string section)
	{
		switch (DebugMode)
		{
		case 1:
			if (section != "WORLD EVENTS" && section != "REPUTATION" && section != "PEOPLE NEAR YOU")
			{
				return section != "RECENT";
			}
			return false;
		case 2:
			switch (section)
			{
			default:
				return section == "NEARBY NEMESES";
			case "TENSION":
			case "ENCOUNTERS":
			case "REGION / FACTIONS":
				return true;
			}
		case 3:
			switch (section)
			{
			default:
				return section == "NAMING / SYSTEM";
			case "NEARBY NEMESES":
			case "RECENT ACTIONS":
			case "WITNESSES":
			case "NERVE":
				return true;
			}
		case 4:
			if (!(section == "WORLD"))
			{
				return section == "WORLD EVENTS";
			}
			return true;
		case 5:
			switch (section)
			{
			default:
				return section == "WITNESSES";
			case "REPUTATION":
			case "PEOPLE NEAR YOU":
			case "RECENT":
			case "NERVE":
				return true;
			}
		default:
			return false;
		}
	}

	internal static string Away(Vector3 me, Vector3 at)
	{
		return $"{at.DistanceTo(me):0} m {Compass(me, at)}";
	}

	private List<(string, (int r, int g, int b))> HappeningNow(Ped player)
	{
		List<(string, (int, int, int))> list = new List<(string, (int, int, int))>();
		Vector3 me = player.Position;
		if (_enc != null && ActiveRecord != null && _activeNemesisPed != null && _activeNemesisPed.Exists())
		{
			_activeNemesisPed.Position.DistanceTo(me);
			string text;
			if (_enc.Surrendered)
			{
				text = "SURRENDERED";
			}
			else if (_enc.Engaged)
			{
				text = "FIGHTING YOU";
			}
			else
			{
				text = (_enc.Spotted ? "spotted you" : "hasn't seen you");
			}
			list.Add(("NOW " + _enc.Kind.ToString().ToUpperInvariant() + " [" + _enc.Card?.Id + "]: " + ActiveRecord.FullName + ((_followers.Count > 0) ? $" + {Enumerable.Count(_followers, (Ped f) => f.Exists() && !f.IsDead)} men" : "") + ((_enc.Activity != "") ? (", " + _enc.Activity) : "") + " - " + Away(me, _activeNemesisPed.Position) + " - " + text, _enc.Engaged ? Theme.Blood : Theme.Warn));
		}
		foreach (TownMan item in _townMen.Where((TownMan t) => t.Ped != null && t.Ped.Exists()))
		{
			list.Add(("NOW TOWN: " + item.Rec.Name + " in " + item.Town + " (" + (item.Hunter ? "hunting you" : item.Intent.ToString()) + ") - " + Away(me, item.Ped.Position) + " - " + (item.Engaged ? "FIGHTING YOU" : (item.Spotted ? "spotted you" : "hasn't seen you")), item.Engaged ? Theme.Blood : Theme.Gold));
		}
		foreach (LiveCamp value in _liveCamps.Values)
		{
			Vector3 at = SitePos(value.Site);
			list.Add((string.Format("NOW CAMP: {0} at {1} - {2}{3} - {4} men - {5}", value.Boss.Name, value.Site.Label, Away(me, at), (value.Site.Id != null && value.Boss.CampKnown) ? "" : " (not on your map)", Enumerable.Count(value.Peds, (Ped p) => p.Exists() && !p.IsDead), value.Engaged ? "FIGHTING" : $"suspicion {value.Suspicion:0}"), value.Engaged ? Theme.Blood : Theme.Gold));
		}
		list.AddRange(PatrolLines(player));
		string text2 = WarEncounterLine();
		if (text2 != null)
		{
			list.Add((text2, Theme.Warn));
		}
		if (_skirmish.Count > 0)
		{
			List<Ped> list2 = _skirmish.Where((Ped p) => p != null && p.Exists() && !p.IsDead).ToList();
			if (list2.Count > 0)
			{
				Vector3 at2 = new Vector3(list2.Average((Ped p) => p.Position.X), list2.Average((Ped p) => p.Position.Y), list2.Average((Ped p) => p.Position.Z));
				list.Add(($"NOW SKIRMISH: {SkirmishNote} - {Away(me, at2)} - {list2.Count} still standing", Theme.Warn));
			}
			else
			{
				list.Add(("NOW SKIRMISH: " + SkirmishNote + " - all down", Theme.Warn));
			}
		}
		List<Ped> list3 = (from h in _hunters
			where h != null && h.Exists() && !h.IsDead
			orderby h.Position.DistanceTo(me)
			select h).ToList();
		if (list3.Count > 0)
		{
			list.Add(($"NOW BOUNTY HUNTERS: {list3.Count} riding - {Away(me, list3[0].Position)}", Theme.Blood));
		}
		if (_general != null && _general.Exists() && !_general.IsDead)
		{
			list.Add(("NOW THE GENERAL: " + Gangs.Army.LeaderName + "'s column - " + Away(me, _general.Position), Gangs.Army.Accent));
		}
		if (_sightingPed != null && _sightingPed.Exists() && _sightingRec != null)
		{
			list.Add(("NOW SIGHTING: " + _sightingRec.Name + " - " + Away(me, _sightingPed.Position), Theme.Gold));
		}
		return list;
	}

	private void DrawDebug(Ped player)
	{
		if (!_debugOn || _menu.IsOpen || _bulletImpact.ViewerOpen || _iniPanel.IsOpen || DebugMode == 6)
		{
			return;
		}
		List<(Ped, NemesisRecord)> list = new List<(Ped, NemesisRecord)>();
		if (DebugShows("NEARBY NEMESES"))
		{
			foreach (KeyValuePair<int, NemesisRecord> worldNemese in _worldNemeses)
			{
				Ped ped = new Ped(worldNemese.Key);
				if (ped.Exists() && ped.Position.DistanceTo(player.Position) < 90f)
				{
					list.Add((ped, worldNemese.Value));
				}
			}
		}
		if (DebugShows("NEARBY NEMESES") && _activeNemesisPed != null && _activeNemesisPed.Exists() && ActiveRecord != null)
		{
			list.Add((_activeNemesisPed, ActiveRecord));
		}
		list = (from x in list.GroupBy(((Ped ped, NemesisRecord rec) x) => x.ped.Handle).Select((IGrouping<int, (Ped ped, NemesisRecord rec)> g) => g.First())
			orderby x.ped.Position.DistanceTo(player.Position)
			select x).Take(10).ToList();
		List<(int kind, string text, (int r, int g, int b) c)> lines = new List<(int, string, (int, int, int))>();
		long nowM = GameMinutesNow();
		if (Config.TensionEnabled && DebugShows("TENSION"))
		{
			H("TENSION");
			string t = TensionDebugLine();
			(int r, int g, int b) value;
			if (Tension >= FireLevel)
			{
				value = Theme.Blood;
			}
			else
			{
				value = ((Tension >= FireLevel * 0.75f) ? Theme.Warn : Theme.Title);
			}
			L(t, value);
			lines.Add((3, "", Theme.Dim));
			L(TensionMarksLine(), Theme.Faint);
		}
		if (DebugShows("ENCOUNTERS"))
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			int num5 = 0;
			foreach (NemesisRecord item6 in Roster.Where((NemesisRecord r) => r.IsAlive))
			{
				switch (IntentOf(item6))
				{
				case Intent.Hunts:
					num++;
					break;
				case Intent.WontHunt:
					num2++;
					break;
				case Intent.ProvokedOnly:
					num3++;
					break;
				default:
					num4++;
					break;
				}
				if (HiresHunters(item6))
				{
					num5++;
				}
			}
			int num6 = Math.Max(0, (_nextAmbushCheck - Game.GameTime) / 1000);
			H("ENCOUNTERS");
			List<(string, (int r, int g, int b))> list2 = HappeningNow(player);
			if (list2.Count == 0)
			{
				L("nothing happening around you", Theme.Dim);
			}
			foreach (var (t2, c) in list2)
			{
				B(t2, c);
			}
			if (ActiveRecord != null)
			{
				L(ActiveNerveLine(), Theme.Warn);
			}
			bool flag = _currentTown != null;
			foreach (string item7 in CardReportLines())
			{
				L(item7, (item7.StartsWith("   ") && item7.Contains("no:")) ? Theme.Faint : Theme.Dim);
			}
			if (TownCalmNote != "")
			{
				L("town calm: " + TownCalmNote, Theme.Dim);
			}
			if (!Config.TensionEnabled)
			{
				L(string.Format("next roll in {0}s  -  {1} chance{2}", num6, flag ? $"in town every {Balance.TownEncounterSeconds}s, {Balance.TownEncounterChance}%" : $"every {EncounterIntervalMs() / 1000}s, {Config.AmbushChancePercent}%", Config.RandomAmbushes ? "" : "  -  RANDOM ENCOUNTERS OFF"));
			}
