	internal unsafe bool PlayerMasked(Ped player)
	{
		if (Game.GameTime < _nextMaskCheck)
		{
			return _masked;
		}
		_nextMaskCheck = Game.GameTime + 400;
		if (_maskUp == 0)
		{
			_maskUp = MISC.GET_HASH_KEY("mask_up");
		}
		bool flag = false;
		int num = Function.Call<int>(10394376663872179841uL, new InputArgument[1] { player.Handle });
		ulong* ptr = stackalloc ulong[1];
		ulong* ptr2 = stackalloc ulong[1];
		int num2 = 0;
		for (int i = 1; i < 2; i++)
		{
			if (flag)
			{
				break;
			}
			for (int j = 0; j < num && j < 64; j++)
			{
				if (flag)
				{
					break;
				}
				*ptr = 0uL;
				*ptr2 = 0uL;
				if (Function.Call<uint>(8627268931001909819uL, new InputArgument[5]
				{
					player.Handle,
					j,
					i == 1,
					new InputArgument((ulong)ptr),
					new InputArgument((ulong)ptr2)
				}) != 0)
				{
					num2++;
					if ((uint)(*ptr2 & 0xFFFFFFFFu) == _maskUp)
					{
						flag = true;
					}
				}
			}
		}
		if (!flag)
		{
			HashSet<uint> hashSet = new HashSet<uint>(from c in Config.DisguiseCategories.Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries)
				select MISC.GET_HASH_KEY(c.Trim().ToUpperInvariant()));
			if (hashSet.Contains(1963323202u))
			{
				hashSet.Add(1249071452u);
			}
			int num3 = Function.Call<int>(11971384123627577485uL, new InputArgument[1] { player.Handle });
			for (int num4 = 0; num4 < num3 && num4 < 48; num4++)
			{
				if (flag)
				{
					break;
				}
				if (hashSet.Contains(Function.Call<uint>(14751957644553774639uL, new InputArgument[2] { player.Handle, num4 })))
				{
					flag = true;
				}
			}
			HashSet<uint> hashSet2 = new HashSet<uint>();
			for (int num5 = 0; num5 < num && num5 < 64; num5++)
			{
				uint num6 = Function.Call<uint>(11209604758464182439uL, new InputArgument[3] { player.Handle, num5, 0 });
				if (num6 != 0)
				{
					hashSet2.Add(num6);
					if (hashSet.Contains(num6))
					{
						flag = true;
					}
				}
			}
			if (num > 0 && num2 >= num - 1 && _lastPieceCats != null && !hashSet2.SetEquals(_lastPieceCats))
			{
				List<string> list = hashSet2.Except(_lastPieceCats).Select(CatName).ToList();
				List<string> list2 = _lastPieceCats.Except(hashSet2).Select(CatName).ToList();
				GrudgeLog(string.Format("DISGUISE clothes changed:{0}{1} - masked {2}", (list.Count > 0) ? (" on " + string.Join(", ", list)) : "", (list2.Count > 0) ? (" off " + string.Join(", ", list2)) : "", flag));
			}
			if (num > 0 && num2 >= num - 1)
			{
				_lastPieceCats = hashSet2;
			}
		}
		bool masked = _masked;
		_masked = flag && Config.DisguiseEnabled;
		if (_masked != masked)
		{
			GrudgeLog(string.Format("DISGUISE {0} ({1} components, {2} read)", _masked ? "ON" : "off", num, num2));
		}
		return _masked;
	}

	private void UpdateTheft(Ped player)
	{
		if (Game.GameTime < _nextTheftCheck)
		{
			return;
		}
		_nextTheftCheck = Game.GameTime + 400;
		Vehicle[] allVehicles = World.GetAllVehicles();
		foreach (Vehicle vehicle in allVehicles)
		{
			if (!(vehicle == null) && vehicle.Exists() && !(vehicle.Position.DistanceTo(player.Position) > 10f))
			{
				int num = VEHICLE.GET_PED_IN_VEHICLE_SEAT(vehicle.Handle, -1);
				if (num != 0 && num != player.Handle)
				{
					_vehicleDrivers[vehicle.Handle] = (num, Game.GameTime);
				}
			}
		}
		int mount = PED.GET_MOUNT(player.Handle);
		if (mount != _lastMount)
		{
			_lastMount = mount;
			if (mount != 0 && mount != PLAYER._GET_ACTIVE_HORSE_FOR_PLAYER(Game.Player.Handle) && mount != PLAYER._GET_SADDLE_HORSE_FOR_PLAYER(Game.Player.Handle))
			{
				Ped ped = (from p in PedsAround(player)
					where p != null && p.Exists() && !p.IsPlayer && p.IsHuman && !p.IsDead && p.Position.DistanceTo(player.Position) < 40f && PED._GET_LAST_MOUNT(p.Handle) == mount
					orderby p.Position.DistanceTo(player.Position)
					select p).FirstOrDefault();
				TheftNote = ((ped != null) ? $"horse {mount}: owner {ped.Handle} -> grudge" : $"horse {mount}: no owner near");
				GrudgeLog("THEFT " + TheftNote);
				if (ped != null)
				{
					Provocation provocation = RememberStranger(ped.Handle);
					if (provocation != null)
					{
						if (!provocation.HorseStolen)
						{
							Grudge(ped.Handle, provocation, GrudgeAction.HorseStolen);
						}
						provocation.HorseStolen = true;
					}
				}
			}
		}
		int num2 = (PED.IS_PED_IN_ANY_VEHICLE(player.Handle, p1: false) ? PED.GET_VEHICLE_PED_IS_IN(player.Handle, p1: false) : 0);
		if (num2 != _lastVehicle)
		{
			_lastVehicle = num2;
			if (num2 != 0 && VEHICLE.GET_PED_IN_VEHICLE_SEAT(num2, -1) == player.Handle && _vehicleDrivers.TryGetValue(num2, out (int, int) value) && Game.GameTime - value.Item2 < 8000)
			{
				Ped ped2 = Entity.FromHandle(value.Item1) as Ped;
				bool flag = ped2 != null && ped2.Exists() && !ped2.IsDead;
				TheftNote = string.Format("wagon {0}: driver {1} {2}", num2, value.Item1, flag ? "-> grudge" : "(dead)");
				GrudgeLog("THEFT " + TheftNote);
				if (flag)
				{
					Provocation provocation2 = RememberStranger(value.Item1);
					if (provocation2 != null)
					{
						if (!provocation2.WagonStolen)
						{
							Grudge(value.Item1, provocation2, GrudgeAction.WagonStolen);
						}
						provocation2.WagonStolen = true;
					}
				}
			}
		}
		foreach (int item in (from kv in _vehicleDrivers
			where Game.GameTime - kv.Value.at > 30000
			select kv.Key).ToList())
		{
			_vehicleDrivers.Remove(item);
		}
	}

	private bool CampAroundFire(Ped lead, List<Ped> crew)
	{
		Vector3 vector = GroundOnSpot(lead.Position + new Vector3(1.2f, 0.8f, 0f));
		if (vector == Vector3.Zero)
		{
			return false;
		}
		int num = MakeFire(vector);
		if (num == 0)
		{
			return false;
		}
		_encFire = num;
		List<Ped> list = new List<Ped> { lead }.Concat(crew.Where((Ped c) => c != null && c.Exists())).ToList();
		double num2 = _rng.NextDouble() * Math.PI * 2.0;
		for (int num3 = 0; num3 < list.Count; num3++)
		{
			Ped ped = list[num3];
			double num4 = num2 + (double)num3 * (Math.PI * 2.0 / (double)list.Count) + (_rng.NextDouble() - 0.5) * 0.35;
			float num5 = 2.1f + (float)_rng.NextDouble() * 0.5f;
			Vector3 vector2 = GroundOnSpot(vector + new Vector3((float)Math.Cos(num4) * num5, (float)Math.Sin(num4) * num5, 0f));
			if (!(vector2 == Vector3.Zero))
			{
				Crumbs.Native("encounter camp: place man");
				ENTITY.SET_ENTITY_COORDS(ped.Handle, vector2.X, vector2.Y, vector2.Z, p4: false, p5: false, p6: false, p7: false);
				ENTITY.SET_ENTITY_HEADING(ped.Handle, HeadingTo(vector2, vector));
				string p = ((ped == lead) ? "WORLD_HUMAN_FIRE_SIT" : FireCrew[_rng.Next(FireCrew.Length)]);
				Crumbs.Native("encounter camp: scenario");
				NoteSeatTask();
				TASK.TASK_START_SCENARIO_IN_PLACE_HASH(ped.Handle, MISC.GET_HASH_KEY(p), -1, p3: true, 0u, -1f, p6: false);
			}
		}
		GrudgeLog($"ENCOUNTER camp: a fire ({_fireModel}) at {vector.X:0},{vector.Y:0} - {list.Count} men round it");
		return true;
	}

	internal int MakeFire(Vector3 at)
	{
		string[] array = ((_fireModel == null) ? FireModels : new string[1] { _fireModel });
		foreach (string text in array)
		{
			Model m = new Model(text);
			if (m.IsValid && m.IsInCdImage && LoadModelSafe(m, 1500))
			{
				Crumbs.Native("encounter camp: create fire");
				int num = OBJECT.CREATE_OBJECT((uint)m.Hash, at.X, at.Y, at.Z, p4: false, p5: false, p6: false, p7: false, p8: true);
				STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)m.Hash);
				if (num != 0)
				{
					OBJECT.PLACE_OBJECT_ON_GROUND_PROPERLY(num, p1: false);
					ENTITY.FREEZE_ENTITY_POSITION(num, p1: true);
					ENTITY.SET_ENTITY_AS_MISSION_ENTITY(num, p1: true, p2: true);
					_fireModel = text;
					return num;
				}
			}
		}
		if (!_fireLogged)
		{
			_fireLogged = true;
			GrudgeLog("ENCOUNTER camp: none of the campfire models could be made - they stand about instead");
		}
		return 0;
	}

	private unsafe void DropCampfire(bool force = false)
	{
		if (_encFire == 0)
		{
			return;
		}
		int encFire = _encFire;
		_encFire = 0;
		if (ENTITY.DOES_ENTITY_EXIST(encFire))
		{
			Ped character = Game.Player.Character;
			Vector3 vector = ENTITY.GET_ENTITY_COORDS(encFire, p1: false, p2: false);
			Crumbs.Native("encounter camp: drop fire");
			if (force || character == null || !character.Exists() || HiddenFromView(character, vector) || character.Position.DistanceTo(vector) > 80f)
			{
				OBJECT.DELETE_OBJECT(&encFire);
			}
			else
			{
				ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(&encFire);
			}
		}
	}

	private void SquareUp(Ped player, Ped lead, float d)
	{
		List<Ped> list = new List<Ped> { lead }.Concat(_followers.Where((Ped f) => f != null && f.Exists() && !f.IsDead)).ToList();
		if (!_squaredUp)
		{
			_squaredUp = true;
			foreach (Ped item in list)
			{
				if (PED.IS_PED_USING_ANY_SCENARIO(item.Handle))
				{
					TASK.CLEAR_PED_TASKS(item.Handle, p1: false, p2: false);
				}
				TASK.TASK_LOOK_AT_ENTITY(item.Handle, player.Handle, -1, 0, 0, 0);
				TASK.TASK_TURN_PED_TO_FACE_ENTITY(item.Handle, player.Handle, 2500, 0f, 0f, 0f);
			}
			_leadWalking = d > 14f;
			if (_leadWalking)
			{
				TASK.TASK_GO_TO_ENTITY(lead.Handle, player.Handle, -1, 9f, 1.1f, 0f, 0);
			}
			return;
		}
		foreach (Ped item2 in list)
		{
			if (item2 == lead && _leadWalking)
			{
				if (d > 10.5f)
				{
					continue;
				}
				_leadWalking = false;
			}
			TASK.TASK_TURN_PED_TO_FACE_ENTITY(item2.Handle, player.Handle, 2500, 0f, 0f, 0f);
		}
	}

	private bool EncounterContextOk(Ped player, out bool town, out bool mounted)
	{
		town = TownAt(player.Position) != null;
		mounted = PED.IS_PED_ON_MOUNT(player.Handle);
		if (player.IsDead)
		{
			return false;
		}
		if (INTERIOR.GET_INTERIOR_FROM_ENTITY(player.Handle) != 0)
		{
			return false;
		}
		if (MISC.GET_MISSION_FLAG())
		{
			return false;
		}
		if (!PLAYER.IS_PLAYER_CONTROL_ON(Game.Player.Handle))
		{
			return false;
		}
		return true;
	}

	private NemesisRecord PickTownCaller(List<NemesisRecord> pool)
	{
		double num = ((IEnumerable<NemesisRecord>)pool).Sum((Func<NemesisRecord, double>)W);
		if (num <= 0.0)
		{
			return null;
		}
		double num2 = _rng.NextDouble() * num;
		foreach (NemesisRecord item in pool)
		{
			num2 -= W(item);
			if (num2 <= 0.0)
			{
				return item;
			}
		}
		return pool[pool.Count - 1];
		double W(NemesisRecord n)
		{
			return (n.Personality.HasValue ? Personalities.AmbushWeight(n.Personality.Value) : 1.0) * (1.0 - Math.Min(0.8, (double)EffectiveFear(n) / 150.0)) * (double)((n.HateTier == HateTier.Murderous) ? Balance.TownMurderousW : ((n.HateTier == HateTier.Vengeful) ? Balance.TownVengefulW : Balance.TownResentful));
		}
	}

	private void RunRandomEncounter(Ped player, bool test)
	{
		string text = (test ? null : NoSpawnReason(player));
		bool lawOnly = text == "the law is after you";
		if (text != null && !lawOnly)
		{
			LastEncounterNote = "held: " + text;
		}
		else
		{
			if (!EncounterContextOk(player, out var town, out var mounted) && !test)
			{
				return;
			}
			if (!PLAYER.IS_PLAYER_CONTROL_ON(Game.Player.Handle))
			{
				LastEncounterNote = "no player control (cutscene / mission)";
			}
			else
			{
				if (_spawnForce == null && RunWorldCards(player, town, lawOnly))
				{
					return;
				}
				List<NemesisRecord> source;
				NemesisRecord rec;
				if (town && !test && !lawOnly)
				{
					string here = _currentTown ?? TownAt(player.Position);
					if (!NearTownCore(player, here))
					{
						LastEncounterNote = "edge of " + here + ": waiting till you're in town";
						return;
					}
					if (Game.GameTime - _visitStartedAt < 60000)
					{
						LastEncounterNote = $"{here}: letting you settle in ({(60000 - (Game.GameTime - _visitStartedAt)) / 1000}s)";
						return;
					}
					source = Roster.Where((NemesisRecord n) => n.CanHunt && !n.PresumedDead && !Resting(n) && !CoolingOff(n) && !IsArmy(n) && !NoTowns(n) && IntentOf(n) != Intent.None && !_worldNemeses.ContainsValue(n) && n != ActiveRecord && (n.HateTier != HateTier.Murderous || n.Hate >= Balance.TownMurderousMinHate) && (IntentOf(n) == Intent.Hunts || n.KillLocation == here || (n.HasOrigin && new Vector3(n.OriginX, n.OriginY, n.OriginZ).DistanceTo(player.Position) < 600f))).ToList();
					source = source.Where((NemesisRecord n) => n.HateTier == HateTier.Murderous && HasReason(n)).ToList();
					if (source.Count == 0)
					{
						LastEncounterNote = "town: no murderous man free to call you out";
						return;
					}
					if (_roadAmbush != null)
					{
						LastEncounterNote = "town: " + _roadAmbush.Rec.Name + " is waiting outside";
						return;
					}
					rec = PickTownCaller(source);
					if (rec == null)
					{
						LastEncounterNote = "town: nobody picked";
						return;
					}
				}
				else
				{
					source = Roster.Where((NemesisRecord n) => n.CanHunt && !_nemesisBodies.ContainsValue(n) && (test || (!Resting(n) && !CoolingOff(n) && InHuntingRange(n, player.Position) && (IntentOf(n) == Intent.Hunts || HiresHunters(n)))) && (!lawOnly || HiresHunters(n))).ToList();
					if (lawOnly && source.Count == 0)
					{
						LastEncounterNote = "held: the law is after you";
						return;
					}
					if (source.Count == 0)
					{
						LastEncounterNote = $"no hunters in range ({Enumerable.Count(Roster, (NemesisRecord n) => n.CanHunt)} able)";
						return;
					}
					rec = PickAmbusher(source);
				}
				if (_spawnForce != null && source.Count > 0)
				{
					List<NemesisRecord> list = source.Where((NemesisRecord n) => Cards.Any((EncounterCard c) => c.Enabled && c.Stage == _spawnForce && CardFits(c, n, town, mounted, test: true))).ToList();
					if (list.Count > 0)
					{
						rec = PickAmbusher(list) ?? list[_rng.Next(list.Count)];
					}
					else if (rec == null)
					{
						rec = source[_rng.Next(source.Count)];
					}
				}
				if (rec == null)
				{
					LastEncounterNote = $"{source.Count} in range, none with a reason (weights 0)";
					return;
				}
				LastEncounterNote = $"{source.Count} hunters -> {rec.Name} ({rec.Personality}, hate {rec.Hate}, fear {EffectiveFear(rec)})";
				if (_spawnForce == null && HiresHunters(rec) && IntentOf(rec) != Intent.Hunts)
				{
					if (!HuntersCardOn)
					{
						LastEncounterNote += " - would hire hunters (card off)";
						return;
					}
					LastEncounterNote += " - hired bounty hunters";
					SendBountyHunters(rec, player);
					return;
				}
				EncounterCard encounterCard = PickCard(rec, town, mounted, test);
				if (_spawnForce != null)
				{
					encounterCard = (from c in Cards
						where c.Enabled && c.Stage == _spawnForce
						orderby CardFits(c, rec, town, mounted, test: true) descending
						select c).FirstOrDefault() ?? BuiltInCards().FirstOrDefault((EncounterCard c) => c.Stage == _spawnForce) ?? encounterCard;
					LastCardNote = "spawner: card " + encounterCard?.Id + " for " + rec.Name;
				}
				if ((encounterCard == null) & test)
				{
					encounterCard = Cards.FirstOrDefault((EncounterCard c) => c.Enabled && c.Stage == (town ? "callout" : "idle")) ?? BuiltInCards().First((EncounterCard c) => c.Stage == (town ? "callout" : "idle"));
				}
				if (encounterCard == null)
				{
					LastEncounterNote = LastEncounterNote + " - " + LastCardNote;
					return;
				}
				EncounterKind encounterKind = StageKind(encounterCard.Stage);
				GrudgeLog($"ENCOUNTER {encounterKind} {rec.FullName} town={town} mounted={mounted} test={test} - {LastCardNote}");
				if (town && !test && !lawOnly && !TakeAggressorSlot(out var why))
				{
					LastEncounterNote = "town: no call-out (" + why + ")";
					return;
				}
				_encForced = test;
				try
				{
					SpawnEncounter(rec, encounterKind, player, encounterCard);
				}
				finally
				{
					_encForced = false;
				}
				if (town && !test && !lawOnly && ActiveRecord != rec)
				{
					_visitAggressors = Math.Max(0, _visitAggressors - 1);
					GrudgeLog("TOWNCALM " + rec.Name + "'s call-out never made it into " + _currentTown + " - the slot is free again");
				}
			}
		}
	}

	private unsafe static Vector3 Ground(Vector3 p)
	{
		float z = default;
		if (MISC.GET_GROUND_Z_FOR_3D_COORD(p.X, p.Y, p.Z + 100f, &z, p4: false))
		{
			p.Z = z;
		}
		return p;
	}

	internal unsafe static bool Raised(Vector3 p)
	{
		float[] array = new float[3] { 1f, 2.5f, 4f };
		float num2 = default;
		foreach (float num in array)
		{
			if (MISC.GET_GROUND_Z_FOR_3D_COORD(p.X, p.Y, p.Z - num, &num2, p4: false) && num2 < p.Z - 1.5f && num2 > p.Z - 40f)
			{
				return true;
			}
		}
		Vector3 safeCoordForPed = World.GetSafeCoordForPed(p);
		if ((safeCoordForPed.X != 0f || safeCoordForPed.Y != 0f) && new Vector3(safeCoordForPed.X - p.X, safeCoordForPed.Y - p.Y, 0f).Length() < 4f)
		{
			return safeCoordForPed.Z < p.Z - 2f;
		}
		return false;
	}

	private bool UpHigh(Vector3 p)
	{
		if (Raised(p))
		{
			return true;
		}
		string text = TownAt(p) ?? _currentTown;
		if (text == null || !TownCore(text, out var centre, out var _) || centre.Z == 0f)
		{
			return false;
		}
		float z = Game.Player.Character.Position.Z;
		if (p.Z > centre.Z + 6f)
		{
			return p.Z > z + 6f;
		}
		return false;
	}

	internal unsafe static Vector3 GroundOnSpot(Vector3 p)
	{
		float num = default;
		if (MISC.GET_GROUND_Z_FOR_3D_COORD(p.X, p.Y, p.Z + 4f, &num, p4: false) && Math.Abs(num - p.Z) < 12f)
		{
			p.Z = num;
			return p;
		}
		Vector3 safeCoordForPed = World.GetSafeCoordForPed(p);
		if ((safeCoordForPed.X != 0f || safeCoordForPed.Y != 0f) && new Vector3(safeCoordForPed.X - p.X, safeCoordForPed.Y - p.Y, 0f).Length() < 8f && Math.Abs(safeCoordForPed.Z - p.Z) < 12f)
		{
			return safeCoordForPed;
		}
		return Ground(p);
	}

	internal static float HeadingTo(Vector3 from, Vector3 to)
	{
		return (float)(Math.Atan2(0f - (to.X - from.X), to.Y - from.Y) * 180.0 / Math.PI);
	}

	private static Vector3 Forward(Ped p)
	{
		double num = (double)p.Heading * Math.PI / 180.0;
		return new Vector3(0f - (float)Math.Sin(num), (float)Math.Cos(num), 0f);
	}

	private Vector3 HighGround(Vector3 around, Ped player = null)
	{
		Vector3 vector = Vector3.Zero;
		Vector3 result = Ground(around + new Vector3(90f, 0f, 0f));
		for (int i = 0; i < 12; i++)
		{
			double num = (double)i * Math.PI / 6.0 + _rng.NextDouble() * 0.3;
			float num2 = 80f + (float)_rng.NextDouble() * 30f;
			Vector3 vector2 = Ground(around + new Vector3((float)Math.Cos(num) * num2, (float)Math.Sin(num) * num2, 0f));
			if (vector2.Z > result.Z)
			{
				result = vector2;
			}
			if ((!(player != null) || (Dry(vector2) && HiddenFromView(player, vector2))) && (vector == Vector3.Zero || vector2.Z > vector.Z))
			{
				vector = vector2;
			}
		}
		if (!(player == null))
		{
			return vector;
		}
		return result;
	}

	private unsafe (Vector3 pos, float heading, string note)? RoadAhead(Ped player)
	{
		Vector3 position = player.Position;
		Vector3 vector = Forward(player);
		double num = Math.Atan2(vector.Y, vector.X);
		float[] array = new float[4] { 120f, 100f, 145f, 160f };
		float[] array2 = new float[7] { 0f, 25f, -25f, 50f, -50f, 80f, -80f };
		(Vector3, float, string)? tuple = null;
		ulong* ptr = stackalloc ulong[3];
		ulong* ptr2 = stackalloc ulong[1];
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		int num5 = 0;
		float[] array3 = array2;
		foreach (float num6 in array3)
		{
			float[] array4 = array;
			foreach (float num7 in array4)
			{
				num2++;
				double num8 = num + (double)num6 * Math.PI / 180.0;
				Vector3 vector2 = position + new Vector3((float)Math.Cos(num8) * num7, (float)Math.Sin(num8) * num7, 0f);
				*ptr = (ptr[1] = (ptr[2] = 0uL));
				*ptr2 = 0uL;
				if (!Function.Call<bool>(2580559617774072660uL, new InputArgument[8]
				{
					vector2.X,
					vector2.Y,
					vector2.Z,
					new InputArgument((ulong)ptr),
					new InputArgument((ulong)ptr2),
					1,
					3f,
					0f
				}))
				{
					num3++;
					continue;
				}
				Vector3 vector3 = new Vector3(*(float*)ptr, *(float*)(ptr + 1), *(float*)(ptr + 2));
				float num9 = vector3.DistanceTo(position);
				if (vector3.DistanceTo(new Vector3(vector2.X, vector2.Y, vector3.Z)) > 45f || num9 < 80f || num9 > 190f)
				{
					num4++;
					continue;
				}
				Vector3 vector4 = Ground(vector3);
				if (Math.Abs(vector4.Z - vector3.Z) > 3f)
				{
					num5++;
					continue;
				}
				float num10 = *(float*)ptr2;
				double num11 = (double)num10 * Math.PI / 180.0;
				Vector3 vector5 = new Vector3(0f - (float)Math.Sin(num11), (float)Math.Cos(num11), 0f);
				Vector3 vector6 = position - vector3;
				vector6.Z = 0f;
				if (vector5.X * vector6.X + vector5.Y * vector6.Y < 0f)
				{
					num10 += 180f;
				}
				(Vector3, float, string) tuple2 = (new Vector3(vector3.X, vector3.Y, vector4.Z + 0.3f), num10, $"road {num9:0} m off, {num6:+0;-0;0} deg from where you face");
				if (HiddenFromView(player, vector3))
				{
					return tuple2;
				}
				tuple = tuple ?? tuple2;
			}
		}
		GrudgeLog(string.Format("ROAD none ahead out of view: {0} points - {1} no node, {2} too far / near, {3} on a ledge{4}", num2, num3, num4, num5, tuple.HasValue ? ", the rest in view" : ""));
		return null;
	}

	private Vector3? RoadNodeNear(Vector3 at, float maxOff)
	{
		float heading;
		return RoadNodeNear(at, maxOff, out heading);
	}

	private unsafe Vector3? RoadNodeNear(Vector3 at, float maxOff, out float heading, int nodeType = 1)
	{
		heading = 0f;
		ulong* ptr = stackalloc ulong[3];
		ulong* ptr2 = stackalloc ulong[1];
		*ptr = (ptr[1] = (ptr[2] = 0uL));
		*ptr2 = 0uL;
		if (!Function.Call<bool>(2580559617774072660uL, new InputArgument[8]
		{
			at.X,
			at.Y,
			at.Z,
			new InputArgument((ulong)ptr),
			new InputArgument((ulong)ptr2),
			nodeType,
			3f,
			0f
		}))
		{
			return null;
		}
		Vector3 value = new Vector3(*(float*)ptr, *(float*)(ptr + 1), *(float*)(ptr + 2));
		heading = *(float*)ptr2;
		if (!(value.DistanceTo(new Vector3(at.X, at.Y, value.Z)) <= maxOff))
		{
			return null;
		}
		return value;
	}

	private void DriveRoadWagon(Ped driver, Vehicle veh, Ped player)
	{
		WagonDrive(driver, veh, _roadWagonTo = RoadNodeNear(player.Position, 40f) ?? WagonGoal(player.Position, 150f) ?? RoadNodeNear(player.Position, 150f) ?? player.Position);
	}

	private void UpdateRoadWagon(Ped player)
	{
		if (_encVehicle == null || !_encVehicle.Exists() || _enc == null || _enc.Spotted || _enc.Engaged || Game.GameTime < _roadWagonCheck)
		{
			return;
		}
		_roadWagonCheck = Game.GameTime + 8000;
		if (_roadWagonWalked)
		{
			if (_roadWagonWalkSent)
			{
				return;
			}
			_roadWagonWalkSent = true;
			{
				foreach (Ped item in from p in new Ped[1] { _activeNemesisPed }.Concat(_followers)
					where p != null && p.Exists() && !p.IsDead && !PED.IS_PED_IN_ANY_VEHICLE(p.Handle, p1: false)
					select p)
				{
					TASK.TASK_FOLLOW_NAV_MESH_TO_COORD(item.Handle, player.Position.X, player.Position.Y, player.Position.Z, 1f, -1, 6f, 0, 0f);
				}
				return;
			}
		}
		int num = VEHICLE.GET_PED_IN_VEHICLE_SEAT(_encVehicle.Handle, -1);
		float num2 = ENTITY.GET_ENTITY_SPEED(_encVehicle.Handle);
		float num3 = _encVehicle.Position.DistanceTo(player.Position);
		bool flag = num2 < 1f;
		if (flag != _roadWagonStill > 0 || (flag && _roadWagonStill == 2))
		{
			GrudgeLog(string.Format("WAGON {0:0} m from you, {1}{2}", num3, flag ? $"stopped ({(_roadWagonStill + 1) * 8} s)" : $"moving {num2:0.0} m/s", (num == 0) ? " - NO DRIVER" : ""));
		}
		_roadWagonStill = (flag ? (_roadWagonStill + 1) : 0);
		if (!flag && _roadWagonTryN > 0)
		{
			WagonRolled("road wagon", _roadWagonTryN, _roadWagonTryWhat);
			_roadWagonTryN = 0;
		}
		if (_roadWagonStill > 3 && num3 > 15f)
		{
			_roadWagonWalked = true;
			foreach (Ped item2 in from p in new Ped[1] { _activeNemesisPed }.Concat(_followers)
				where p != null && p.Exists() && !p.IsDead && PED.IS_PED_IN_VEHICLE(p.Handle, _encVehicle.Handle, p2: false)
				select p)
			{
				Crumbs.Native("road wagon: get down");
				TASK.TASK_LEAVE_ANY_VEHICLE(item2.Handle, 0, 0);
			}
			GrudgeLog($"WAGON stuck {_roadWagonStill * 8} s, {num3:0} m from you - they get down and come on foot");
		}
		else
		{
			if (num == 0 || num3 < 15f)
			{
				return;
			}
			Ped ped = Entity.FromHandle(num) as Ped;
			if (ped == null)
			{
				return;
			}
			if (flag && _roadWagonStill >= 1 && _roadWagonStill <= 3)
			{
				if (_roadWagonTo == Vector3.Zero)
				{
					_roadWagonTo = RoadNodeNear(player.Position, 40f) ?? player.Position;
				}
				Vector3 to = _roadWagonTo;
				bool wandering = _roadWagonWander;
				string text = WagonTry(_roadWagonStill, ped, _encVehicle, ref to, ref wandering);
				_roadWagonWander = wandering;
				_roadWagonTo = to;
				_roadWagonTryN = _roadWagonStill;
				_roadWagonTryWhat = text;
				GrudgeLog($"WAGONDIAG road wagon stopped {_roadWagonStill * 8} s, try {_roadWagonStill}: {text} | {WagonState(_encVehicle, ped)}");
			}
			else if (!flag && !_roadWagonWander)
			{
				Vector3? vector = RoadNodeNear(player.Position, 40f);
				if (vector.HasValue && vector.GetValueOrDefault().DistanceTo(_roadWagonTo) > 25f)
				{
					DriveRoadWagon(ped, _encVehicle, player);
				}
			}
		}
	}

	private bool PutOnWagon(Ped ped, NemesisRecord rec, Vector3 pos, float heading, Ped player)
	{
		string text = ((rec.Wealth == Wealth.Rich || rec.Rank >= 4) ? "stagecoach001x" : RoadWagonModels[_rng.Next(RoadWagonModels.Length)]);
		uint num = MISC.GET_HASH_KEY(text);
		if (!STREAMING.IS_MODEL_IN_CDIMAGE(num))
		{
			GrudgeLog("WAGON " + text + " not in the game files");
			return false;
		}
		Vehicle vehicle = SpawnVehicle((VehicleHash)num, pos, heading);
		if (vehicle == null)
		{
			GrudgeLog("WAGON could not create " + text);
			return false;
		}
		MakeOurs(vehicle.Handle);
		VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(vehicle.Handle, p1: false);
		_encVehicle = vehicle;
		PED.SET_PED_INTO_VEHICLE(ped.Handle, vehicle.Handle, -1);
		int num2 = 0;
		foreach (Ped item in _followers.Where((Ped f) => f.Exists()).Take((text == "stagecoach001x") ? 5 : 2))
		{
			PED.SET_PED_INTO_VEHICLE(item.Handle, vehicle.Handle, num2++);
		}
		ped.BlockPermanentEvents = true;
		_roadWagonTo = Vector3.Zero;
		_roadWagonCheck = Game.GameTime + 8000;
		_roadWagonStill = 0;
		_roadWagonWalked = false;
		_roadWagonWalkSent = false;
		_roadWagonTryN = 0;
		_roadWagonTryWhat = null;
		_roadWagonWander = false;
		DriveRoadWagon(ped, vehicle, player);
		GrudgeLog($"WAGON {rec.Name} drives a {text} with {num2} men aboard, {pos.DistanceTo(player.Position):0} m ahead - coming your way");
		return true;
	}

	private bool HeadSeesHead(Ped watcher, Ped target)
	{
		Vector3 vector = PED.GET_PED_BONE_COORDS(watcher.Handle, 21030, 0f, 0f, 0f);
		Vector3 to = PED.GET_PED_BONE_COORDS(target.Handle, 21030, 0f, 0f, 0f);
		if (vector.X == 0f && vector.Y == 0f)
		{
			vector = watcher.Position + new Vector3(0f, 0f, 0.7f);
		}
		if (to.X == 0f && to.Y == 0f)
		{
			to = target.Position + new Vector3(0f, 0f, 0.3f);
		}
		return !Ray.Blocked(vector, to, 17, watcher.Handle);
	}

	private void SpawnEncounter(NemesisRecord rec, EncounterKind kind, Ped player, EncounterCard card = null)
	{
		card = card ?? Cards.FirstOrDefault((EncounterCard c) => c.Enabled && c.Stage == kind.ToString().ToLowerInvariant()) ?? new EncounterCard
		{
			Id = "plain",
			Stage = kind.ToString().ToLowerInvariant()
		};
		SetWorldPaused(paused: false);
		if (_enc != null)
		{
			EndEncounter();
		}
		if (_worldNemeses.ContainsValue(rec))
		{
			GrudgeLog("ENCOUNTER skipped: " + rec.Name + " is already out in the world");
			return;
		}
		Vector3 fwd = Forward(player);
		Vector3 side = new Vector3(fwd.Y, 0f - fwd.X, 0f);
		bool flag = card.Stage == "wagon";
		float? num = null;
		if (flag && !_spawnAt.HasValue)
		{
			(Vector3, float, string)? tuple = RoadAhead(player);
			if (!tuple.HasValue)
			{
				flag = false;
				GrudgeLog("WAGON no road near you - " + rec.Name + " comes on foot instead");
			}
			else
			{
				_wagonRoad = tuple.Value.Item1;
				num = tuple.Value.Item2;
				GrudgeLog("WAGON " + tuple.Value.Item3);
			}
		}
		Vector3 vector;
		switch (kind)
		{
		case EncounterKind.Riders:
			vector = GoodSpot(player, () => Ground(player.Position - fwd * 130f + side * ((float)_rng.NextDouble() * 40f - 20f)));
			if (vector == Vector3.Zero)
			{
				GrudgeLog("ENCOUNTER riders for " + rec.Name + ": no dry ground behind you - not sent");
				LastEncounterNote = "riders: no dry ground";
				return;
			}
			break;
		case EncounterKind.Ahead:
		{
			(Vector3, float, string)? tuple3 = RoadAhead(player);
			if (!tuple3.HasValue)
			{
				GrudgeLog("ENCOUNTER ahead for " + rec.Name + ": no road near you - not sent");
				LastEncounterNote = "ahead: no road near you";
				return;
			}
			vector = tuple3.Value.Item1;
			num = tuple3.Value.Item2;
			GrudgeLog("ENCOUNTER ahead for " + rec.Name + ": " + tuple3.Value.Item3);
			break;
		}
		case EncounterKind.Sniper:
			vector = HighGround(player.Position, player);
			if (vector == Vector3.Zero)
			{
				GrudgeLog("ENCOUNTER sniper for " + rec.Name + ": no high ground out of your view - not sent");
				LastEncounterNote = "sniper: no hidden high ground";
				return;
			}
			break;
		case EncounterKind.Idle:
		{
			(Vector3, float, int)? tuple2 = (((_spawnAt.HasValue | flag) || TownAt(player.Position) != null) ? (((Vector3, float, int)?)null) : FindSeat(player, 55f, 120f));
			if (tuple2.HasValue && Travelling(player, out var dir))
			{
				Vector3 vector2 = tuple2.Value.Item1 - player.Position;
				vector2.Z = 0f;
				float num2 = vector2.Length();
				if (num2 > 1f && (vector2.X * dir.X + vector2.Y * dir.Y) / num2 < 0.17f)
				{
					GrudgeLog($"ENCOUNTER idle: the seat found was behind you ({num2:0} m) - a spot ahead instead");
					tuple2 = null;
				}
			}
			if (_spawnAt.HasValue)
			{
				vector = _spawnAt.Value;
			}
			else if (flag)
			{
				vector = _wagonRoad;
			}
			else
			{
				vector = (tuple2.HasValue ? StandIn(tuple2.Value.Item1, tuple2.Value.Item2) : OutOfSightSpot(player, 70f, 120f));
			}
			if (vector == Vector3.Zero && !_spawnAt.HasValue && !flag)
			{
				vector = OutOfSightSpot(player, 120f, 180f);
				if (vector != Vector3.Zero)
				{
					GrudgeLog($"ENCOUNTER idle for {rec.Name}: nothing hidden at 70-120 m - placed {vector.DistanceTo(player.Position):0} m out");
				}
			}
			if (vector == Vector3.Zero)
			{
				GrudgeLog("ENCOUNTER idle for " + rec.Name + ": no spot out of your view - not sent");
				LastEncounterNote = "idle: no spot out of view";
				return;
			}
			GrudgeLog(string.Format("ENCOUNTER idle (wild) spot for {0}: {1:0},{2:0} {3:0} m from you, zone {4} (you: {5}, current town {6})", rec.Name, vector.X, vector.Y, vector.DistanceTo(player.Position), TownAt(vector) ?? "wild", TownAt(player.Position) ?? "wild", _currentTown ?? "none"));
			break;
		}
		default:
		{
			string text = _currentTown ?? TownAt(player.Position);
			_calloutSeat = FindTownSeat(player, text, 60f);
			vector = (_calloutSeat.HasValue ? StandIn(_calloutSeat.Value.pos, _calloutSeat.Value.heading) : NaturalTownSpot(player, text).pos);
			if (vector == Vector3.Zero)
			{
				GrudgeLog("ENCOUNTER callout for " + rec.Name + ": no spot in " + text + " - not placed");
				LastEncounterNote = "callout: no spot in town";
				return;
			}
			GrudgeLog("ENCOUNTER callout spot for " + rec.Name + ": " + SpotNote(vector, text, player));
			break;
		}
		}
		float heading = HeadingTo(vector, player.Position);
		bool flag2 = kind == EncounterKind.Idle || kind == EncounterKind.Callout;
		Ped ped = SpawnNemesisPed(rec, vector, heading, NemesisGroup(), out var model, 424175505u, releaseModel: false, !flag2);
		if (flag2 && ped != null)
		{
			MakeSociable(ped);
		}
		if (ped == null)
		{
			return;
		}
		NoteCame(rec);
		World.SetRelationshipBetweenGroups((kind == EncounterKind.Ahead || kind == EncounterKind.Callout || kind == EncounterKind.Idle) ? ((eRelationshipType)3) : ((eRelationshipType)6), _nemesisGroup, player.RelationshipGroup);
		if (IsArmy(rec) && kind != EncounterKind.Sniper && kind != EncounterKind.Callout && card?.Id != "plan-habit-drink")
		{
			SpawnArmyCrew(rec, vector, heading);
		}
		else if (kind == EncounterKind.Riders || kind == EncounterKind.Ahead || kind == EncounterKind.Idle)
		{
			List<int> list = card.Cast?.Crew;
			_crewOverride = ((list != null && list.Count == 2) ? new int?(list[0] + _rng.Next(Math.Max(1, list[1] - list[0] + 1))) : ((int?)null));
			SpawnFollowers(rec, model, vector, heading);
			_crewOverride = null;
		}
		STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)model.Hash);
		switch (kind)
		{
		case EncounterKind.Riders:
			MountOnHorse(ped);
			foreach (Ped item in _followers.Where((Ped f) => f.Exists()))
			{
				MountOnHorse(item);
			}
			break;
		case EncounterKind.Sniper:
			WEAPON.REMOVE_ALL_PED_WEAPONS(ped.Handle, p1: true, p2: true);
			ped.GiveWeapon((_rng.Next(2) == 0) ? ((eWeapon)1999408598u) : ((eWeapon)3788682007u), 60, (eWeaponAttachPoint)9, equipNow: true, isAmmoLoaded: false, a6: false);
			ped.Accuracy = Math.Min(90, 40 + rec.Rank * 10);
			PED.SET_PED_COMBAT_MOVEMENT(ped.Handle, 0);
			PED.SET_PED_COMBAT_RANGE(ped.Handle, 2);
			break;
		case EncounterKind.Ahead:
			foreach (Ped item2 in from p in new Ped[1] { ped }.Concat(_followers)
				where p.Exists()
				select p)
			{
				TASK.TASK_START_SCENARIO_IN_PLACE_HASH(item2.Handle, MISC.GET_HASH_KEY((_rng.Next(2) == 0) ? "WORLD_HUMAN_GUARD_SCOUT" : "WORLD_HUMAN_GUARD_LAZY"), -1, p3: true, 0u, -1f, p6: false);
			}
			break;
		}
		if (flag2)
		{
			foreach (Ped item3 in _followers.Where((Ped f) => f.Exists()))
			{
				item3.BlockPermanentEvents = false;
			}
		}
		if (flag2)
		{
			foreach (Ped item4 in _followers.Where((Ped f) => f.Exists()))
			{
				MakeSociable(item4);
			}
			HandToGame(ped);
			foreach (Ped item5 in _followers.Where((Ped f) => f.Exists()))
			{
				HandToGame(item5);
			}
		}
		if (flag2 && rec.Gang == null)
		{
			foreach (Ped item6 in from p in new Ped[1] { ped }.Concat(_followers)
				where p.Exists()
				select p)
			{
				item6.RelationshipGroup = PED.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH(item6.Handle);
				ForgetSwitch(item6.Handle);
			}
		}
		_encVehicle = null;
		if (flag)
		{
			PutOnWagon(ped, rec, vector, num ?? HeadingTo(vector, player.Position), player);
		}
		string text2;
		if (flag && _encVehicle != null)
		{
			text2 = "driving a wagon up the road";
		}
		else
		{
			text2 = ((kind == EncounterKind.Idle) ? SetAtEase(ped, _followers.Where((Ped f) => f.Exists()).ToList(), vector, card.Activity == "patrol" || (card.Activity == null && IsArmy(rec)), (card.Activity != "patrol") ? card.Activity : null) : "");
		}
		bool presumedDead = rec.PresumedDead;
		string text3 = CardTaunt(card, rec, presumedDead);
		rec.PresumedDead = false;
		if (presumedDead && rec.Gang == null)
		{
			TryRankUp(rec, "came back from the dead");
		}
		rec.TimesAmbushed++;
		rec.Touch();
		string zoneName = GetZoneName(Game.Player.Character.Position);
		NemesisMod nemesisMod = this;
		NemesisRecord rec2 = rec;
		string text4;
		if (presumedDead && string.IsNullOrEmpty(card.History))
		{
			text4 = "CAME BACK from the dead to hunt you";
		}
		else
		{
			text4 = ((!string.IsNullOrEmpty(card.History)) ? card.History.Replace("{kind}", card.Title ?? card.Stage).Replace("{place}", zoneName) : ("CAME FOR YOU (" + (card.Title ?? kind.ToString()).ToLowerInvariant() + ") near " + zoneName));
		}
		nemesisMod.History(rec2, text4, presumedDead ? Theme.Blood : Theme.Warn);
		UseCard(card);
		SaveRoster();
		_activeNemesisPed = ped;
		ActiveRecord = rec;
		_enc = new Encounter
		{
			Kind = kind,
			Start = Game.GameTime,
			Taunt = text3,
			Activity = text2,
			Card = card
		};
		if (kind == EncounterKind.Idle)
		{
			GrudgeLog($"ENCOUNTER idle: {rec.Name} + {_followers.Count} men {text2}, {vector.DistanceTo(player.Position):0} m off");
		}
		Feed(string.Format("ENCOUNTER {0} [{1}]: {2}{3}{4}, {5:0} m off", kind.ToString().ToUpperInvariant(), card.Id, rec.FullName, (_followers.Count > 0) ? $" + {_followers.Count} men" : "", (text2 != "") ? (", " + text2) : "", vector.DistanceTo(player.Position)), Theme.Warn, rec);
		string text5 = rec.FullName ?? "";
		string text6 = ((_followers.Count > 0) ? $" and {_followers.Count} men" : "");
		if (_encForced && _activeBlip == null && ped.Exists())
		{
			Crumbs.Native("Encounters blip add (V2)");
			_activeBlip = ped.AddBlip((BlipType)2545348716u);
			if (_activeBlip != null)
			{
				Function.Call(11290983183885202434uL, _activeBlip.Handle, new InputArgument(UiDraw.ForeverVarString(rec.FullName ?? "")));
			}
		}
		switch (kind)
		{
		case EncounterKind.Riders:
			EngageEncounter(player, blip: true);
			ShowSubtitle(rec.Name + ": \"" + text3 + "\"");
			GrudgeNotice("Riders coming up behind you: " + text5 + text6 + ".");
			break;
		case EncounterKind.Sniper:
			EngageEncounter(player, blip: false);
			break;
		case EncounterKind.Callout:
			if (_calloutSeat.HasValue)
			{
				SitAt(ped, _calloutSeat.Value.point, _calloutSeat.Value.pos, _calloutSeat.Value.heading);
			}
			else
			{
				PlaceNaturally(ped, vector);
			}
			Crumbs.Native("Encounters blip add (V2)");
			if (_activeBlip == null)
			{
				_activeBlip = ped.AddBlip((BlipType)2545348716u);
			}
			if (_activeBlip != null)
			{
				Function.Call(11290983183885202434uL, _activeBlip.Handle, new InputArgument(UiDraw.ForeverVarString(rec.FullName + " (looking for you)")));
			}
			break;
		case EncounterKind.Ahead:
		case EncounterKind.Holdup:
		case EncounterKind.Idle:
			break;
		}
	}

	private string SetAtEase(Ped lead, List<Ped> crew, Vector3 at, bool patrol = false, string scenario = null)
	{
		if (!string.IsNullOrEmpty(scenario) && !patrol)
		{
			SettleInWorld(lead, 30f, scenario, -1f);
			foreach (Ped item in crew)
			{
				SettleInWorld(item, 10f, scenario, HeadingTo(item.Position, lead.Position));
			}
			return scenario.Replace("WORLD_HUMAN_", "").Replace('_', ' ').ToLowerInvariant();
		}
		if (patrol || _rng.Next(100) < 50)
		{
			TASK.TASK_WANDER_STANDARD(lead.Handle, 10f, 10);
			foreach (Ped item2 in crew)
			{
				TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(item2.Handle, lead.Handle, (float)(_rng.NextDouble() * 4.0 - 2.0), -2f - (float)_rng.NextDouble() * 3f, 0f, 1f, -1, 2f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
			}
			if (!patrol)
			{
				return "on the move";
			}
			return "on patrol";
		}
		if (CampAroundFire(lead, crew))
		{
			return "round a fire";
		}
		(string, string, string[]) tuple = Activities[_rng.Next(Activities.Length)];
		SettleInWorld(lead, 30f, tuple.Item2, -1f);
		foreach (Ped item3 in crew)
		{
			SettleInWorld(item3, 10f, tuple.Item3[_rng.Next(tuple.Item3.Length)], HeadingTo(item3.Position, lead.Position));
		}
		return tuple.Item1;
	}

	private void TackUp(Ped horse, bool army = false)
	{
		if (!(horse == null) && horse.Exists())
		{
			_tackModel[horse.Handle] = (uint)horse.Model.Hash;
			if (!Function.Call<bool>(11582290322814659388uL, new InputArgument[1] { horse.Handle }))
			{
				_tackPending.Add((horse, army, Game.GameTime + 10000));
			}
			else
			{
				TackNow(horse, army);
			}
		}
	}

	private bool TackStillHim(Ped horse)
	{
		if (horse != null && horse.Exists() && !horse.IsDead && _tackModel.TryGetValue(horse.Handle, out var value) && value == (uint)horse.Model.Hash)
		{
			return BelongsToUs(horse.Handle);
		}
		return false;
	}

	private void TackNow(Ped horse, bool army)
	{
		try
		{
			List<uint> list = new List<uint>
			{
				Pick(army ? ArmySaddles : PlainSaddles),
				Pick(Blankets),
				Pick(Stirrups)
			};
			if (_rng.Next(100) < 60)
			{
				list.Add(Pick(Bedrolls));
				list.Add(Pick(Saddlebags));
			}
			ApplyTack(horse, list, (_tackWay >= 0) ? _tackWay : 0);
			_tackChecks.Add((horse, list, (_tackWay >= 0) ? _tackWay : 0, Game.GameTime + 700));
		}
		catch (Exception ex)
		{
			if (!_tackLogged)
			{
				_tackLogged = true;
				GrudgeLog("HORSE tack failed: " + ex.Message);
			}
		}
		uint Pick(uint[] a)
		{
			return a[_rng.Next(a.Length)];
		}
	}

	private static void ApplyTack(Ped horse, List<uint> items, int way)
	{
		int handle = horse.Handle;
		if (way == 4)
		{
			int num = PED.GET_NUM_META_PED_OUTFITS(handle);
			Crumbs.Native("Encounters outfit");
			if (num > 1)
			{
				PED._EQUIP_META_PED_OUTFIT_PRESET(handle, 1 + new Random(handle).Next(num - 1), p2: false);
			}
		}
		else
		{
			foreach (uint item in items)
			{
				switch (way)
				{
				case 1:
					PED._APPLY_SHOP_ITEM_TO_PED(handle, item, p2: true, p3: true, p4: true);
					break;
				case 2:
					PED._APPLY_SHOP_ITEM_TO_PED(handle, item, p2: false, p3: false, p4: true);
					break;
				default:
					PED._APPLY_SHOP_ITEM_TO_PED(handle, item, p2: true, p3: false, p4: false);
					break;
				}
			}
		}
		if (way == 3)
		{
			PED._REFRESH_META_PED_SHOP_ITEMS(handle, 0);
		}
		Crumbs.Native("Encounters ped variation");
		PED._UPDATE_PED_VARIATION(handle, p1: false, p2: true, p3: true, p4: true, p5: false);
	}

	private static bool HasSaddle(Ped horse)
	{
		if (!ArmySaddles.Concat(PlainSaddles).Any((uint s) => WearsComponent(horse.Handle, s)))
		{
			return WearsComponent(horse.Handle, 3131565592u);
		}
		return true;
	}

	internal static bool WearsComponent(int ped, uint component)
	{
		return Function.Call<bool>(18106882544748776897uL, new InputArgument[2] { ped, component });
	}

	private void UpdateTack()
	{
		for (int num = _tackPending.Count - 1; num >= 0; num--)
		{
			var (ped, army, num2) = _tackPending[num];
			if (!TackStillHim(ped))
			{
				_tackPending.RemoveAt(num);
				if (ped != null)
				{
					_tackModel.Remove(ped.Handle);
				}
			}
			else if (Function.Call<bool>(11582290322814659388uL, new InputArgument[1] { ped.Handle }))
			{
				_tackPending.RemoveAt(num);
				TackNow(ped, army);
			}
			else if (Game.GameTime > num2)
			{
				_tackPending.RemoveAt(num);
				GrudgeLog($"HORSE {ped.Handle} never got ready to render - no tack");
			}
		}
		for (int num3 = _tackChecks.Count - 1; num3 >= 0; num3--)
		{
			var (ped2, list, num4, num5) = _tackChecks[num3];
			if (Game.GameTime >= num5)
			{
				_tackChecks.RemoveAt(num3);
				if (TackStillHim(ped2))
				{
					if (HasSaddle(ped2))
					{
						if (_tackWay != num4)
						{
							GrudgeLog($"HORSE saddle took with way {num4} - used for every horse from now on");
						}
						_tackWay = num4;
					}
					else if (num4 >= 4)
					{
						if (!_tackLogged)
						{
							_tackLogged = true;
							GrudgeLog("HORSE no way put a saddle on (ways 0-4 all failed the check)");
						}
					}
					else
					{
						GrudgeLog($"HORSE saddle check: way {num4} didn't take - trying way {num4 + 1}");
						ApplyTack(ped2, list, num4 + 1);
						_tackChecks.Add((ped2, list, num4 + 1, Game.GameTime + 700));
					}
				}
			}
		}
	}

	private Ped MountOnHorse(Ped rider)
	{
		Vector3 pos = rider.Position + new Vector3(1.5f, 0f, 0f);
		Ped ped = SpawnPed(RiderHorses[_rng.Next(RiderHorses.Length)], pos, rider.Heading);
		if (ped == null)
		{
			return null;
		}
		MakeOurs(ped.Handle);
		TackUp(ped, Gangs.ForModel((uint)rider.Model.Hash) == Gangs.Army);
		Crumbs.Native("Encounters onto mount");
		PED.SET_PED_ONTO_MOUNT(rider.Handle, ped.Handle, -1, p3: true);
		_encHorses.Add(ped);
		return ped;
	}

	private bool EncounterAttacked(Ped ped, Ped player, float d)
	{
		if (!(from p in new Ped[1] { ped }.Concat(_followers)
			where p != null && p.Exists() && !p.IsDead
			select p).Any((Ped p) => PED.IS_PED_IN_COMBAT(p.Handle, player.Handle) || ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(p.Handle, player.Handle, p2: true, p3: true)))
		{
			if (FiredInAnger && d < 90f)
			{
				return WEAPON.IS_PED_ARMED(player.Handle, 4);
			}
			return false;
		}
		return true;
	}

	private void EngageEncounter(Ped player, bool blip)
	{
		if (_activeNemesisPed == null || !_activeNemesisPed.Exists())
		{
			GrudgeLog("ENCOUNTER engage skipped - he's gone");
			return;
		}
		_enc.Engaged = true;
		if (ActiveRecord?.Needs != null)
		{
			ActiveRecord.Needs["Violence"] = 0;
		}
		if (_currentTown != null && InTownForArrivals(player, _currentTown) && ActiveRecord != null)
		{
			try
			{
				TownFightReaction(_activeNemesisPed, player, _currentTown, Loadout.BandOf(ActiveRecord) == Loadout.Band.Gun);
			}
			catch (Exception ex)
			{
				GrudgeLog("FIGHT town reaction failed: " + ex.Message);
			}
		}
		ClaimBack(_activeNemesisPed);
		foreach (Ped follower in _followers)
		{
			ClaimBack(follower);
		}
		if (_activeNemesisPed != null && _activeNemesisPed.Exists())
		{
			_activeNemesisPed.BlockPermanentEvents = true;
			_activeNemesisPed.RelationshipGroup = NemesisGroup();
		}
		foreach (Ped item in _followers.Where((Ped f) => f.Exists()))
		{
			item.BlockPermanentEvents = true;
			item.RelationshipGroup = NemesisGroup();
		}
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _nemesisGroup, player.RelationshipGroup);
		Ped activeNemesisPed = _activeNemesisPed;
		if (blip && _activeBlip != null && _activeBlip.Exists())
		{
			_activeBlip.Delete();
			_activeBlip = null;
		}
		Crumbs.Native("Encounters blip add (V2)");
		if (blip && _activeBlip == null)
		{
			_activeBlip = activeNemesisPed.AddBlip((BlipType)831283580u);
		}
		TASK.TASK_COMBAT_PED(activeNemesisPed.Handle, player.Handle, 0, 16);
		PED.SET_PED_KEEP_TASK(activeNemesisPed.Handle, p1: true);
		foreach (Ped item2 in _followers.Where((Ped f) => f.Exists() && !f.IsDead))
		{
			Crumbs.Native("Encounters blip add (V2)");
			if (blip)
			{
				_followerBlips.Add(item2.AddBlip((BlipType)831283580u));
			}
			TASK.TASK_COMBAT_PED(item2.Handle, player.Handle, 0, 16);
			PED.SET_PED_KEEP_TASK(item2.Handle, p1: true);
		}
	}

	private bool FightsHandToHand(Ped p)
	{
		if (p == _activeNemesisPed && ActiveRecord != null)
		{
			return Loadout.BandOf(ActiveRecord) != Loadout.Band.Gun;
		}
		if (_worldNemeses.TryGetValue(p.Handle, out var value))
		{
			return Loadout.BandOf(value) != Loadout.Band.Gun;
		}
		uint num = WEAPON.GET_WEAPONTYPE_GROUP(WEAPON._GET_PED_CURRENT_HELD_WEAPON(p.Handle));
		if (num != 3566412244u)
		{
			return num == 2685387236u;
		}
		return true;
	}

	private void GetOffForAFight(Ped player)
	{
		if (_enc == null || !_enc.Engaged)
		{
			return;
		}
		List<Ped> list = new List<Ped>();
		if (_activeNemesisPed != null)
		{
			list.Add(_activeNemesisPed);
		}
		list.AddRange(_followers);
		foreach (Ped item in list)
		{
			if (item == null || !item.Exists() || item.IsDead || NerveOut(item.Handle))
			{
				continue;
			}
			bool flag = PED.IS_PED_ON_MOUNT(item.Handle);
			_dismountOrderedAt.TryGetValue(item.Handle, out var value);
			if (flag)
			{
				if (!(item.Position.DistanceTo(player.Position) > 30f) && FightsHandToHand(item) && (value == 0 || Game.GameTime - value >= 4000))
				{
					TASK.TASK_DISMOUNT_ANIMAL(item.Handle, 0, 0uL, 0uL, 0uL, 0);
					_dismountOrderedAt[item.Handle] = Game.GameTime;
					GrudgeLog($"ENCOUNTER {item.Handle} gets off his horse to fight on foot");
				}
			}
			else if (value != 0)
			{
				_dismountOrderedAt.Remove(item.Handle);
				TASK.TASK_COMBAT_PED(item.Handle, player.Handle, 0, 16);
				PED.SET_PED_KEEP_TASK(item.Handle, p1: true);
			}
		}
	}

	private void StartStandoff(Ped player, Ped ped, NemesisRecord rec)
	{
		if (_encVehicle != null && _encVehicle.Exists())
		{
			foreach (Ped item in from p in new Ped[1] { ped }.Concat(_followers)
				where p.Exists() && PED.IS_PED_IN_ANY_VEHICLE(p.Handle, p1: false)
				select p)
			{
				item.BlockPermanentEvents = false;
				TASK.TASK_LEAVE_ANY_VEHICLE(item.Handle, 0, 0);
			}
		}
		if (rec.Needs != null)
		{
			rec.Needs["Violence"] = Math.Max(0, Mind.N(rec, "Violence") - 20);
		}
		int num;
		if (_enc.Card != null && _enc.Card.StandoffSeconds > 0)
		{
			num = _enc.Card.StandoffSeconds;
		}
		else if (rec.HateTier == HateTier.Murderous)
		{
			num = Balance.StandoffMurderous;
		}
		else
		{
			num = ((rec.HateTier == HateTier.Vengeful) ? Balance.StandoffVengeful : Balance.StandoffResentful);
		}
		_enc.Spotted = true;
		_squaredUp = false;
		_leadWalking = false;
		_enc.StandoffUntil = Game.GameTime + num * 1000;
		_enc.NextRetask = 0;
		if (!_enc.Spoke)
		{
			_enc.Spoke = true;
			ShowSubtitle(rec.Name + ": \"" + _enc.Taunt + "\"");
			Say(ped, _enc.Card?.Voice ?? "CHALLENGE_THREATEN", player);
			TauntEmote(ped, rec);
		}
		MusicStandoff();
		Crumbs.Native("Encounters blip add (V2)");
		if (_activeBlip == null)
		{
			_activeBlip = ped.AddBlip((BlipType)4108623209u);
		}
		if (rec.OwesYou)
		{
			rec.OwesYou = false;
			ShowSubtitle(rec.Name + ": \"I owed you my life. That's paid. Next time, I won't stop.\"");
			History(rec, "PAID HIS DEBT - backed down because he owed you his life", Theme.Good);
			Feed("STANDOFF " + rec.Name + ": he owed you - he backs down", Theme.Good, rec);
			BackDown(ped, rec, "he paid his debt");
		}
		else
		{
			GrudgeLog($"ENCOUNTER standoff with {rec.Name} ({rec.HateTier}): {num}s to talk him down, or not");
			Feed($"STANDOFF {rec.Name}: {num}s - greet to talk him down ({BackDownChance(rec)}%), antagonize / draw / hit = fight", Theme.Warn, rec);
		}
	}

	private int BackDownChance(NemesisRecord r)
	{
		int num = ((r.HateTier != HateTier.Murderous) ? ((r.HateTier == HateTier.Vengeful) ? 15 : 35) : 0);
		num += Mind.BackDownBonus(r);
		num += EffectiveFear(r) / 2;
		switch (r.Personality)
		{
		case Personality.Coward:
			num += 25;
			break;
		case Personality.Drifter:
			num += 15;
			break;
		case Personality.Cold:
			num += 5;
			break;
		case Personality.Hothead:
			num -= 20;
			break;
		case Personality.Proud:
			num -= 15;
			break;
		}
		if (r.TraitsRolled && r.Disposition == Disposition.Friendly)
		{
			num += 10;
		}
		if (r.TraitsRolled && r.Disposition == Disposition.Surly)
		{
			num -= 10;
		}
		if (r.TimesKilledPlayer > 0)
		{
			num -= 20;
		}
		return Math.Max(0, Math.Min(85, num));
	}

	private void UpdateStandoff(Ped player, Ped ped, NemesisRecord rec, float d, bool attacked)
	{
		bool flag = PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(Game.Player.Handle, ped.Handle) && WEAPON.IS_PED_ARMED(player.Handle, 6);
		if (!attacked && !flag && Game.GameTime > _enc.StandoffUntil && _enc.Card?.Id == "plan-funeral" && _funeral != null)
		{
			GrudgeLog("ENCOUNTER standoff with " + rec.Name + " at the funeral ends peacefully - back to the grave");
			_enc.StandoffUntil = -1;
			_enc.Spotted = false;
			_enc.Calmed = true;
			MusicStandoffOver();
			if (_activeBlip != null && _activeBlip.Exists())
			{
				_activeBlip.Delete();
				_activeBlip = null;
			}
			StandRoundCasket();
			return;
		}
		if (!attacked && !flag && Game.GameTime > _enc.StandoffUntil)
		{
			EncounterCard card = _enc.Card;
			if (card != null && card.EndsPeacefully)
			{
				GrudgeLog("ENCOUNTER standoff with " + rec.Name + " ends peacefully (" + _enc.Card.Id + ")");
				int hate = rec.Hate;
				rec.AddHate(_enc.Card.BackDownHate);
				History(rec, "SAID HIS PIECE and went (hate " + Delta(hate, rec.Hate) + ")", Theme.Good);
				BackDown(ped, rec, "he said his piece and went");
				return;
			}
		}
		if ((attacked | flag) || Game.GameTime > _enc.StandoffUntil)
		{
			NemesisMod nemesisMod = this;
			string name = rec.Name;
			string text;
			if (attacked)
			{
				text = "you hit / shot";
			}
			else
			{
				text = (flag ? "you drew on him" : "time ran out");
			}
			nemesisMod.GrudgeLog("ENCOUNTER standoff with " + name + " over: " + text);
			_enc.StandoffUntil = -1;
			MusicStandoffBroke();
			EngageEncounter(player, blip: true);
		}
		else if (Game.GameTime >= _enc.NextRetask)
		{
			_enc.NextRetask = Game.GameTime + 3000;
			SquareUp(player, ped, d);
		}
	}

	private void BackDown(Ped ped, NemesisRecord rec, string how)
	{
		foreach (Ped item in from p in new Ped[1] { ped }.Concat(_followers)
			where p != null && p.Exists()
			select p)
		{
			TASK.TASK_WANDER_STANDARD(item.Handle, 10f, 10);
		}
		BandFromEncounter();
		_encEnd = ("BACKED OFF", how);
		if (_enc != null)
		{
			_enc.StandoffUntil = -1;
		}
		BackDownEmote(ped);
		MusicStandoffOver();
		SaveRoster();
		EndEncounter();
		ReleaseActive();
	}

	private void TalkEndedQuietly(Ped man, bool letGo)
	{
		if (_enc == null || _enc.Engaged || man == null || !man.Exists() || _activeNemesisPed == null || (man.Handle != _activeNemesisPed.Handle && !_followers.Any((Ped f) => f != null && f.Exists() && f.Handle == man.Handle)))
		{
			return;
		}
		string text = WhoIs(man.Handle);
		string text2 = ActiveRecord?.Name ?? "the encounter";
		if (_enc.StandoffUntil > 0 || _enc.Spotted)
		{
			MusicStandoffOver();
		}
		if (_activeBlip != null && _activeBlip.Exists())
		{
			_activeBlip.Delete();
			_activeBlip = null;
		}
		_enc.StandoffUntil = -1;
		_enc.EngageAt = 0;
		if (_enc.Kind == EncounterKind.Idle)
		{
			_enc.Spotted = false;
			_enc.Calmed = true;
			_enc.TalkedAt = Game.GameTime;
			GrudgeLog("ENCOUNTER " + text2 + ": you questioned " + text + " and left it there - his crew leave it too (only an attack starts it now)");
			return;
		}
		if (letGo)
		{
			GrudgeLog("ENCOUNTER " + text2 + ": you questioned " + text + " and let him go - no fight starts of it");
			return;
		}
		GrudgeLog("ENCOUNTER " + text2 + ": you questioned " + text + " and left it there - they go their way");
		foreach (Ped item in from p in new Ped[1] { _activeNemesisPed }.Concat(_followers)
			where p != null && p.Exists() && !p.IsDead && p.Handle != man.Handle
			select p)
		{
			TASK.TASK_WANDER_STANDARD(item.Handle, 10f, 10);
		}
		if (_nemesisGroup != 0)
		{
			World.SetRelationshipBetweenGroups((eRelationshipType)3, _nemesisGroup, Game.Player.Character.RelationshipGroup);
		}
		BandFromEncounter();
		_encEnd = ("BACKED OFF", "you questioned " + text + " and left it there");
		SaveRoster();
		EndEncounter();
		ReleaseActive();
	}

	private bool StandoffGreeted(NemesisRecord rec)
	{
		if (_enc == null || _enc.StandoffUntil < 0 || _enc.GreetRolled || _activeNemesisPed == null)
		{
			return false;
		}
		_enc.GreetRolled = true;
		int num = BackDownChance(rec);
		int num2 = _rng.Next(100);
		bool flag = num2 < num;
		Feed(string.Format("STANDOFF {0}: you greeted him - {1}%, rolled {2} -> {3}", rec.Name, num, num2, flag ? "he backs down" : "no"), flag ? Theme.Good : Theme.Blood, rec);
		if (flag)
		{
			ShowSubtitle(rec.Name + ": \"" + ((rec.Personality == Personality.Coward) ? "...Fine. Fine! Another time." : "Not worth it. Not today.") + "\"");
			int hate = rec.Hate;
			rec.AddHate(_enc.Card?.BackDownHate ?? (-5));
			History(rec, "BACKED DOWN when you greeted him (hate " + Delta(hate, rec.Hate) + ")", Theme.Good);
			Remember(rec, (Mind.F(rec, "Pride") >= 60) ? "Shame" : "Joy", 35, "backed down from you");
			BackDown(_activeNemesisPed, rec, "you talked him down");
		}
		else
		{
			ShowSubtitle(rec.Name + ": \"" + ((rec.HateTier == HateTier.Resentful) ? "Don't you 'howdy' me." : "Too late for pleasantries.") + "\"");
			_enc.StandoffUntil = Math.Min(_enc.StandoffUntil, Game.GameTime + 1500);
		}
		SaveRoster();
		return true;
	}

	private void UpdateEncounter(Ped player)
	{
		if (_enc == null)
		{
			return;
		}
		if (_activeNemesisPed == null || ActiveRecord == null)
		{
			EndEncounter();
			return;
		}
		if (!_enc.Engaged && !_enc.Spotted && _enc.StandoffUntil < 0 && Game.GameTime - _enc.Start > 480000)
		{
			GrudgeLog(string.Format("ENCOUNTER {0} with {1} timed out ({2})", _enc.Kind, ActiveRecord.Name, (_enc.TalkedAt > 0) ? "you'd talked with them and moved on" : "never crossed paths"));
			EndEncounter();
			ReleaseActive();
			return;
		}
		Ped activeNemesisPed = _activeNemesisPed;
		if (!activeNemesisPed.Exists() || activeNemesisPed.IsDead)
		{
			return;
		}
		NemesisRecord activeRecord = ActiveRecord;
		if (_enc.EngageAt > 0 && !_enc.Engaged && (Game.GameTime >= _enc.EngageAt || PED.IS_PED_IN_COMBAT(activeNemesisPed.Handle, player.Handle) || ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(activeNemesisPed.Handle, player.Handle, p2: true, p3: true)))
		{
			_enc.EngageAt = 0;
			GrudgeLog("ENCOUNTER " + activeRecord.Name + ": after the words, the fight");
			EngageEncounter(player, blip: true);
		}
		float num = activeNemesisPed.Position.DistanceTo(player.Position);
		GetOffForAFight(player);
		if (_enc.Surrendered)
		{
			if ((!(_interro?.Ped != null) || !_interro.Ped.Exists() || _interro.Ped.Handle != activeNemesisPed.Handle) && (Game.GameTime - _enc.SurrenderedAt > 20000 || num > 40f))
			{
				TASK.CLEAR_PED_TASKS(activeNemesisPed.Handle, p1: true, p2: true);
				Flee(activeNemesisPed.Handle, player.Handle, 200f, -1, 3f);
				bool flag = SparedNotSlipped(activeNemesisPed.Handle, activeNemesisPed.Position);
				Feed("SURRENDERED " + activeRecord.Name + ": " + (flag ? "you let him run" : "he slipped away while the fight was on"), Theme.Dim, activeRecord);
				GrudgeLog("ENCOUNTER " + activeRecord.Name + " surrendered and ran" + (flag ? "" : " - slipped away, not spared"));
				if (flag)
				{
					SparedHim(activeRecord, "surrendered and you let him run");
				}
				else
				{
					SlippedAway(activeRecord, "surrendered, then ran");
				}
				_encEnd = ("SURRENDERED", "threw up his hands, then ran");
				EndEncounter();
				ReleaseActive();
			}
			return;
		}
		switch (_enc.Kind)
		{
		case EncounterKind.Ahead:
			if (!_enc.Engaged && EncounterAttacked(activeNemesisPed, player, num))
			{
				GrudgeLog("ENCOUNTER ahead: " + activeRecord.Name + "'s men were attacked / heard your gun");
				EngageEncounter(player, blip: true);
			}
			else if (!_enc.Engaged && num < 45f)
			{
				ShowSubtitle(activeRecord.Name + ": \"" + _enc.Taunt + "\"");
				Say(activeNemesisPed, _enc.Card?.Voice ?? "CHALLENGE_THREATEN", player);
				EngageEncounter(player, blip: true);
			}
			break;
		case EncounterKind.Callout:
			if (_enc.Engaged)
			{
				break;
			}
			if (_enc.StandoffUntil <= 0 && EncounterAttacked(activeNemesisPed, player, num))
			{
				_enc.Spotted = true;
				GrudgeLog($"ENCOUNTER callout: {activeRecord.Name} was attacked / heard your gun ({num:0} m)");
				EngageEncounter(player, blip: true);
				break;
			}
			if (!_enc.Spotted)
			{
				if (Sees(activeNemesisPed, player, SightFor(player, 30f), out var _))
				{
					_enc.Spotted = true;
					_enc.Start = Game.GameTime;
					TASK.CLEAR_PED_TASKS(activeNemesisPed.Handle, p1: true, p2: true);
					TASK.TASK_GO_TO_ENTITY(activeNemesisPed.Handle, player.Handle, -1, 3f, 1.2f, 0f, 0);
					if (_activeBlip != null && _activeBlip.Exists())
					{
						_activeBlip.Delete();
					}
					Crumbs.Native("Encounters blip add (V2)");
					_activeBlip = activeNemesisPed.AddBlip((BlipType)831283580u);
					GrudgeNotice(activeRecord.FullName + " spotted you - he's coming over.");
				}
				else if (num > 250f)
				{
					EndEncounter();
					ReleaseActive();
				}
				break;
			}
			if (!_enc.Spoke && num < 12f)
			{
				_enc.Spoke = true;
				if (_currentTown != null && RollWaitOutside(activeRecord, _currentTown, activeNemesisPed, player, callout: true))
				{
					_encEnd = null;
					EndEncounter();
					ReleaseActive();
					break;
				}
				ShowSubtitle(activeRecord.Name + ": \"" + _enc.Taunt + "\"");
				Say(activeNemesisPed, _enc.Card?.Voice ?? "CHALLENGE_THREATEN", player);
			}
			if (_enc.StandoffUntil > 0)
			{
				UpdateStandoff(player, activeNemesisPed, activeRecord, num, PED.IS_PED_IN_COMBAT(activeNemesisPed.Handle, player.Handle) || ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(activeNemesisPed.Handle, player.Handle, p2: true, p3: true));
			}
			else if (num < 6f || Game.GameTime - _enc.Start > 25000)
			{
				EncounterCard card = _enc.Card;
				if (card != null && card.Standoff == false)
				{
					EngageEncounter(player, blip: true);
				}
				else
				{
					StartStandoff(player, activeNemesisPed, activeRecord);
				}
			}
			else if (Game.GameTime >= _enc.NextRetask)
			{
				_enc.NextRetask = Game.GameTime + 3000;
				TASK.TASK_GO_TO_ENTITY(activeNemesisPed.Handle, player.Handle, -1, 3f, 1.2f, 0f, 0);
			}
			break;
		case EncounterKind.Idle:
		{
			RideInTick();
			RideInSettleTick();
			ProcessionTick();
			if (_enc.Engaged || (_enc.StandoffUntil < 0 && Game.GameTime < _enc.NextSpotCheck))
			{
				break;
			}
			_enc.NextSpotCheck = Game.GameTime + 200;
			List<Ped> list = (from p in new Ped[1] { activeNemesisPed }.Concat(_followers)
				where p.Exists() && !p.IsDead
				select p).ToList();
			Ped questioned = _interro?.Ped;
			bool talking = questioned != null && list.Any((Ped p) => p.Handle == questioned.Handle);
			Sight s = SightFor(player, (_enc.Card != null && _enc.Card.SightRange > 0f) ? _enc.Card.SightRange : 38f);
			Ped ped = null;
			float num2 = 0f;
			foreach (Ped item in list)
			{
				if (Sees(item, player, s, out var d))
				{
					ped = item;
					num2 = d;
					break;
				}
			}
			bool flag2 = ped != null;
			if (flag2)
			{
				_enc.SpotNote = string.Format("{0} at {1:0} m, you {2} (sight {3:0} m)", (ped == activeNemesisPed) ? activeRecord.Name : "one of his men", num2, s.Stance, s.Range);
			}
			bool flag3 = list.Any((Ped p) => ((!talking || p.Handle != questioned.Handle) && PED.IS_PED_IN_COMBAT(p.Handle, player.Handle)) || ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(p.Handle, player.Handle, p2: true, p3: true));
			bool flag4 = FiredInAnger && num < 90f && WEAPON.IS_PED_ARMED(player.Handle, 4);
			if (_enc.Card?.Id == "plan-funeral")
			{
				flag4 = flag4 && num < 35f;
				bool flag5 = WEAPON._GET_PED_CURRENT_HELD_WEAPON(player.Handle) != 2725352035u;
				bool flag6 = list.Any((Ped m) => PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(Game.Player.Handle, m.Handle));
				if (flag2 && !flag6 && (_enc.Calmed || !flag5))
				{
					flag2 = false;
				}
			}
			if (flag2 && (talking || (_enc.TalkedAt > 0 && (Game.GameTime - _enc.TalkedAt < 10000 || !list.Any((Ped m) => PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(Game.Player.Handle, m.Handle))))))
			{
				flag2 = false;
			}
			if (_enc.StandoffUntil > 0)
			{
				UpdateStandoff(player, activeNemesisPed, activeRecord, num, flag3 | flag4);
			}
			else if (flag2 | flag3 | flag4)
			{
				_enc.Spotted = true;
				ShowSubtitle(activeRecord.Name + ": \"" + _enc.Taunt + "\"");
				Say(activeNemesisPed, _enc.Card?.Voice ?? "CHALLENGE_THREATEN", player);
				NemesisMod nemesisMod = this;
				string name = activeRecord.Name;
				string arg;
				if (flag3)
				{
					arg = "were attacked";
				}
				else
				{
					arg = (flag4 ? "heard your gun" : ("saw you - " + _enc.SpotNote));
				}
				nemesisMod.GrudgeLog($"ENCOUNTER idle: {name}'s men {arg} ({num:0} m from him)");
				bool flag7 = _enc.Card?.Standoff ?? (!IsArmy(activeRecord));
				if ((flag3 | flag4) || !flag7)
				{
					EngageEncounter(player, blip: true);
				}
				else
				{
					StartStandoff(player, activeNemesisPed, activeRecord);
				}
			}
			else if (num > (RidingIn ? 520f : 300f))
			{
				GrudgeLog((_enc.TalkedAt > 0) ? ("ENCOUNTER idle: you rode off after talking with " + activeRecord.Name + "'s men - " + ((_funeral != null) ? "left them to their funeral" : "left them be")) : ("ENCOUNTER idle: you never crossed paths with " + activeRecord.Name));
				EndEncounter();
				ReleaseActive();
			}
			break;
		}
		case EncounterKind.Sniper:
			if (!_enc.Spotted && (PED.IS_PED_SHOOTING(activeNemesisPed.Handle) || num < 35f))
			{
				_enc.Spotted = true;
				Crumbs.Native("Encounters blip add (V2)");
				if (_activeBlip == null)
				{
					_activeBlip = activeNemesisPed.AddBlip((BlipType)831283580u);
				}
				ShowSubtitle(activeRecord.Name + ": \"" + _enc.Taunt + "\"");
				GrudgeNotice("Sniper! " + activeRecord.FullName + " is on the high ground.");
			}
			break;
		case EncounterKind.Holdup:
			break;
		}
	}

	private unsafe void EndEncounter()
	{
		_lastEncFought = _enc?.Engaged ?? false;
		if (_rideIn != null && _funeral != null)
		{
			if (_rideIn.Wagon != null)
			{
				_funeral.Wagon = _rideIn.Wagon;
			}
			if (_rideIn.Coffin != 0 && !_funeral.Props.Contains(_rideIn.Coffin))
			{
				_funeral.Props.Add(_rideIn.Coffin);
			}
		}
		_rideIn = null;
		_rideInSettle = null;
		if (_proc != null)
		{
			foreach (Ped item in EncounterMen())
			{
				item.BlockPermanentEvents = false;
			}
			_proc = null;
		}
		if (_enc != null && _enc.Kind == EncounterKind.Callout && _enc.Engaged)
		{
			NoteTownFightOver();
		}
		_dismountOrderedAt.Clear();
		foreach (Ped encHorse in _encHorses)
		{
			if (!(encHorse == null) && encHorse.Exists())
			{
				int handle = encHorse.Handle;
				ReleaseIfOurs(&handle);
			}
		}
		_encHorses.Clear();
		if (_encVehicle != null && _encVehicle.Exists())
		{
			int handle2 = _encVehicle.Handle;
			ReleaseIfOurs(&handle2);
		}
		_encVehicle = null;
		DropCampfire();
		_enc = null;
	}

	private void UpdateEnemyDots(Ped player)
	{
		if (Game.GameTime < _nextEnemyDots)
		{
			return;
		}
		_nextEnemyDots = Game.GameTime + 500;
		HashSet<int> hashSet = new HashSet<int>();
		IEnumerable<(Ped, OurRole)> second = from h in _followerOf.Keys.Concat(_worldNemeses.Keys).Distinct().ToList()
			select (Entity.FromHandle(h) as Ped, WorldNemesis: OurRole.WorldNemesis);
		foreach (var (ped, ourRole) in OurPeds().Concat(second))
		{
			if ((ped != null && IsCompanion(ped.Handle)) || ourRole == OurRole.Companion || ourRole == OurRole.Regular || ped == null || !ped.Exists() || ped.IsDead || !ped.IsHuman)
			{
				continue;
			}
			int handle = ped.Handle;
			if (!hashSet.Add(handle))
			{
				continue;
			}
			bool flag = PED.IS_PED_IN_COMBAT(handle, player.Handle);
			if (_enemyDots.TryGetValue(handle, out (Blip, int) value))
			{
				if (flag)
				{
					_enemyDots[handle] = (value.Item1, Game.GameTime);
				}
			}
			else if (flag && MAP.GET_BLIP_FROM_ENTITY(handle) == 0)
			{
				Crumbs.Native("EnemyDots blip add (V2)");
				Blip blip = ped.AddBlip((BlipType)831283580u);
				if (blip != null)
				{
					_enemyDots[handle] = (blip, Game.GameTime);
				}
			}
		}
		foreach (int item in _enemyDots.Keys.ToList())
		{
			var (blip2, num) = _enemyDots[item];
			if (!ENTITY.DOES_ENTITY_EXIST(item) || ENTITY.IS_ENTITY_DEAD(item) || !hashSet.Contains(item) || Game.GameTime - num > 8000)
			{
				if (blip2 != null && blip2.Exists())
				{
					blip2.Delete();
				}
				_enemyDots.Remove(item);
			}
		}
	}

	private void ClearEnemyDots()
	{
		foreach (var value in _enemyDots.Values)
		{
			Blip item = value.blip;
			if (item != null && item.Exists())
			{
				item.Delete();
			}
		}
		_enemyDots.Clear();
	}

	internal void NoteModel(Ped p)
	{
		if (p != null && p.Exists())
		{
			_modelOf[p.Handle] = (uint)p.Model.Hash;
		}
	}

