	private void PruneEntities()
	{
		if (Game.GameTime < _nextEntityPrune)
		{
			return;
		}
		_nextEntityPrune = Game.GameTime + 1000;
		List<(string, ICollection<int>, Action<int>)> list = BookkeepingMaps().ToList();
		List<(string, ICollection<int>, Action<int>)> list2 = LifecycleMaps().ToList();
		HashSet<int> all = new HashSet<int>();
		foreach (var item2 in list.Concat(list2))
		{
			foreach (int item3 in item2.Item2)
			{
				all.Add(item3);
			}
		}
		foreach (var item4 in OurPeds())
		{
			Ped item = item4.p;
			if (item != null)
			{
				all.Add(item.Handle);
			}
		}
		foreach (Ped item5 in _encHorses.Concat(_hunterHorses).Concat(_warHorses).Concat(_supplyWagonHorses)
			.Concat(_raids.SelectMany((Raid r) => r.Horses)))
		{
			if (item5 != null)
			{
				all.Add(item5.Handle);
			}
		}
		CalibrateOwnCheck();
		PruneOwn();
		_affilTold.RemoveWhere(((int, string) t) => !ENTITY.DOES_ENTITY_EXIST(t.Item1));
		foreach (int h in all)
		{
			if (!ENTITY.DOES_ENTITY_EXIST(h))
			{
				foreach (var item6 in list)
				{
					if (item6.Item2.Contains(h))
					{
						item6.Item3(h);
					}
				}
				GunMelee.Forget(h);
				Downed.Forget(h);
				if (!list2.Any(((string name, ICollection<int> keys, Action<int> remove) m) => m.keys.Contains(h)))
				{
					_modelOf.Remove(h);
					HandlesGone++;
				}
				continue;
			}
			uint num = ENTITY.GET_ENTITY_MODEL(h);
			if (!_modelOf.TryGetValue(h, out var value))
			{
				_modelOf[h] = num;
			}
			else
			{
				if (value == num)
				{
					continue;
				}
				List<string> values = list.Concat(list2).Where(((string name, ICollection<int> keys, Action<int> remove) m) => m.keys.Contains(h)).Select(((string name, ICollection<int> keys, Action<int> remove) m) => m.name)
					.ToList();
				foreach (var item7 in list.Concat(list2))
				{
					if (item7.Item2.Contains(h))
					{
						item7.Item3(h);
					}
				}
				GunMelee.Forget(h);
				Downed.Forget(h);
				_modelOf[h] = num;
				HandlesReused++;
				GrudgeLog(string.Format("ENTITY handle {0} reused (model 0x{1:X8} -> 0x{2:X8}): dropped from {3}", h, value, num, string.Join(", ", values)));
			}
		}
		foreach (int item8 in _modelOf.Keys.Where((int k) => !all.Contains(k)).ToList())
		{
			_modelOf.Remove(item8);
		}
	}

	internal string EntityDebugLine()
	{
		return $"entities: {EntitiesTracked} handles held - {HandlesReused} reused, {HandlesGone} gone (pruned in one place)";
	}

	internal static bool IsEpiloguePlayer()
	{
		try
		{
			Ped character = Game.Player.Character;
			return character != null && character.Exists() && Models.Name(character) == "player_three";
		}
		catch
		{
			return false;
		}
	}

	internal void MarkYouInStoryGang()
	{
		bool flag = IsEpiloguePlayer();
		NemesisRecord nemesisRecord = StoryRoster.FirstOrDefault((NemesisRecord r) => r.Id == "vdl_arthur");
		NemesisRecord nemesisRecord2 = StoryRoster.FirstOrDefault((NemesisRecord r) => r.Id == "vdl_john");
		if (nemesisRecord != null)
		{
			nemesisRecord.Title = (flag ? "an enforcer" : "(you)");
		}
		if (nemesisRecord2 != null)
		{
			nemesisRecord2.Title = (flag ? "(you)" : "a gun");
		}
	}

	internal void EightYearsLater(string why, bool debug = false, bool alreadyEpilogue = false)
	{
		WorldState chronicle = Chronicle;
		if (chronicle.Era >= 1907)
		{
			GrudgeLog("EPILOGUE already 1907 - nothing to do");
			return;
		}
		try
		{
			BenchLeaderCopies("the turn to 1907");
		}
		catch (Exception ex)
		{
			GrudgeLog("EPILOGUE leaders' copies: " + ex.Message);
		}
		if (_menu.IsOpen)
		{
			_menu.Close();
		}
		try
		{
			_bulletImpact.CloseViewer();
		}
		catch
		{
		}
		if (!debug && (alreadyEpilogue || chronicle.HistoryYear >= 1906 || (chronicle.Events.Count > 0 && !chronicle.Events.Any((WorldEvent e) => e.GameMin > 0 && GameDate.FromMinutes(e.GameMin).Year < 1906))))
		{
			OutfitsOf1907(why);
			return;
		}
		long num = (from e in chronicle.Events
			where Old(e.GameMin)
			select e.GameMin).DefaultIfEmpty(0L).Max();
		if (Old(chronicle.LastClockMin))
		{
			num = Math.Max(num, chronicle.LastClockMin);
		}
		if (num <= 0)
		{
			num = (Old(GameMinutesRaw()) ? GameMinutesRaw() : GameDate.ToMinutes(new DateTime(1899, 12, 31, 12, 0, 0)));
		}
		string text = TakeSavePoint("before 1907", sync: true, num);
		if (!debug)
		{
			chronicle.StoryChapter = 7;
			chronicle.StoryChapterAt = GameMinutesNow();
		}
