	private void UpdateRegion(Ped player)
	{
		if (Game.GameTime >= _nextRegionCheck)
		{
			_nextRegionCheck = Game.GameTime + 2000;
			Vector3 position = player.Position;
			_rawState = ZONE._GET_MAP_ZONE_AT_COORDS(position.X, position.Y, position.Z, 0);
			_regionDistrict = ZONE._GET_MAP_ZONE_AT_COORDS(position.X, position.Y, position.Z, 10);
			_regionPrinted = ZONE._GET_MAP_ZONE_AT_COORDS(position.X, position.Y, position.Z, 11);
			ref uint regionState = ref _regionState;
			uint num;
			if (KnownState(_rawState))
			{
				num = _rawState;
			}
			else
			{
				num = (DistrictState.TryGetValue(_regionDistrict, out var value) ? value : _rawState);
			}
			regionState = num;
			_nearFort = _regionPrinted == 4195085991u || _regionDistrict == 1835499550;
			if (_regionState != _lastLoggedState || _regionDistrict != _lastLoggedDistrict)
			{
				_lastLoggedState = _regionState;
				_lastLoggedDistrict = _regionDistrict;
				GrudgeLog(string.Format("REGION {0}{1} - state 0x{2:X8} district 0x{3:X8} printed 0x{4:X8}", RegionName, _nearFort ? " (Army ground)" : "", _rawState, _regionDistrict, _regionPrinted));
			}
		}
	}

	private static bool KnownState(uint h)
	{
		if (h != 4073907364u && h != 10837344 && h != 3005831075u && h != 1246494439 && h != 3047819085u && h != 2321575796u)
		{
			return h == 2045157995;
		}
		return true;
	}

	internal double RegionMult(Gang g)
	{
		if (g == null)
		{
			return 1.0;
		}
		District currentDistrict = CurrentDistrict;
		if (currentDistrict != null)
		{
			if (g.OnlyDistricts != null && !g.OnlyDistricts.Contains(_regionDistrict))
			{
				return 0.0;
			}
			if (_nearFort && g.WeightNearFort >= 0.0)
			{
				return g.WeightNearFort;
			}
			return HoldMult(currentDistrict, g);
		}
		if (g.OnlyDistricts != null)
		{
			if (g.OnlyDistricts.Contains(_regionDistrict))
			{
				if (g.DistrictWeights == null || !g.DistrictWeights.TryGetValue(_regionDistrict, out var value))
				{
					return g.DistrictWeight;
				}
				return value;
			}
			return 0.0;
		}
		if (_nearFort && g.WeightNearFort >= 0.0)
		{
			return g.WeightNearFort;
		}
		if (!North)
		{
			if (!South)
			{
				return g.WeightElsewhere;
			}
			return g.WeightSouth;
		}
		return g.WeightNorth;
	}

	internal bool HasReason(NemesisRecord n)
	{
		Gang gang = ((n == null || n.Gang == null) ? null : Gangs.ById(n.Gang));
		if (gang != null && gang.NeedsReason && n.Origin == GrudgeOrigin.GangMember)
		{
			return ReasonMet(gang);
		}
		return true;
	}

	internal bool ReasonMet(Gang g)
	{
		if (g != null && g.NeedsReason && NotorietyOf(g) < Balance.ArmyNotorietyGate)
		{
			if (g.ReasonFromBounty)
			{
				return BountyDollars >= Balance.ArmyBountyGate;
			}
			return false;
		}
		return true;
	}

	internal int CrewBonus(Gang g)
	{
		if (g != null)
		{
			return Math.Max(0, Notoriety.Level(NotorietyOf(g)) - 2);
		}
		return 0;
	}

	internal int EncounterIntervalMs()
	{
		int num = Gangs.All.Max((Gang g) => Notoriety.Level(NotorietyOf(g)));
		return (int)((double)(Config.AmbushIntervalSeconds * 1000) * (1.0 - 0.08 * (double)num));
	}

	internal static void ApplyFactionStyle(Ped ped, string gangId)
	{
		if (ped == null || !ped.Exists() || gangId == null)
		{
			return;
		}
		Gang gang = Gangs.ById(gangId);
		if (gang != null)
		{
			if (gang.CombatMovement.HasValue)
			{
				PED.SET_PED_COMBAT_MOVEMENT(ped.Handle, gang.CombatMovement.Value);
			}
			if (gang.CombatAbility.HasValue)
			{
				PED.SET_PED_COMBAT_ABILITY(ped.Handle, gang.CombatAbility.Value);
			}
			if (gang.CombatRange.HasValue)
			{
				PED.SET_PED_COMBAT_RANGE(ped.Handle, gang.CombatRange.Value);
			}
			if (gang.MayFlee)
			{
				PED.SET_PED_COMBAT_ATTRIBUTES(ped.Handle, 58, p2: false);
			}
			if (gang.AccuracyMin > 0)
			{
				ped.Accuracy = Math.Max(ped.Accuracy, gang.AccuracyMin);
			}
			if (gang.AccuracyMax < 100)
			{
				ped.Accuracy = Math.Min(ped.Accuracy, gang.AccuracyMax);
			}
		}
	}

	private void RaiderInfighting()
	{
		Gang g = Gangs.LemoyneRaiders;
		if (_rng.Next(100) >= Balance.RaiderShakeupChance)
		{
			return;
		}
		string succ = SuccessorId(g);
		List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.Gang == g.Id && n.IsAlive && !n.PresumedDead && !_worldNemeses.ContainsValue(n) && n != ActiveRecord && n.Id != succ && !(n.Id?.StartsWith("lore_") ?? false)).ToList();
		if (list.Count < 3)
		{
			return;
		}
		NemesisRecord upstart = (from _ in list
			where _.Rank < 4
			orderby _rng.Next()
			select _).FirstOrDefault();
		NemesisRecord nemesisRecord = ((upstart == null) ? null : (from n in list
			where n.Rank > upstart.Rank
			orderby n.Rank
			select n).ThenBy((NemesisRecord _) => _rng.Next()).FirstOrDefault());
		if (upstart != null && nemesisRecord != null)
		{
			int num = _rng.Next(100);
			WorldEvent worldEvent = NewEvent("FEUD", GameMinutesNow());
			worldEvent.Gangs.Add(g.Id);
			worldEvent.Place = "in the Raiders' camp";
			WorldPart worldPart = new WorldPart
			{
				Id = upstart.Id,
				Name = upstart.Name,
				Gang = g.Id
			};
			WorldPart worldPart2 = new WorldPart
			{
				Id = nemesisRecord.Id,
				Name = nemesisRecord.Name,
				Gang = g.Id
			};
			worldEvent.People.Add(worldPart);
			worldEvent.People.Add(worldPart2);
			if (num < 45)
			{
				int rank = nemesisRecord.Rank;
				worldEvent.Title = upstart.Name + " shot " + nemesisRecord.Name + " for his place";
				OffscreenDeath(nemesisRecord, worldEvent, worldPart2, upstart.Name, gun: true);
				upstart.Rank = rank;
				worldPart.Outcome = "PROMOTED";
				worldPart.Note = "took his place as " + What(upstart);
				History(upstart, "SHOT " + nemesisRecord.Name.ToUpperInvariant() + " and took his place as " + What(upstart), g.Accent);
				GrudgeNotice("Lemoyne Raiders: " + upstart.FullName + " shot " + nemesisRecord.Name + " and took his place as " + What(upstart) + ".");
			}
			else if (num < 80)
			{
				NemesisRecord nemesisRecord2 = upstart;
				NemesisRecord nemesisRecord3 = nemesisRecord;
				int rank2 = nemesisRecord.Rank;
				int rank3 = upstart.Rank;
				nemesisRecord2.Rank = rank2;
				nemesisRecord3.Rank = rank3;
				worldEvent.Title = upstart.Name + " pushed " + nemesisRecord.Name + " aside";
				worldPart.Outcome = "PROMOTED";
				worldPart.Note = What(upstart) + " now";
				worldPart2.Outcome = "DEMOTED";
				worldPart2.Note = What(nemesisRecord) + " now";
				History(upstart, "PUSHED " + nemesisRecord.Name.ToUpperInvariant() + " ASIDE - " + What(upstart) + " now", g.Accent);
				History(nemesisRecord, "PUSHED ASIDE by " + upstart.Name + " - " + What(nemesisRecord) + " now", Theme.Warn);
				Remember(nemesisRecord, "Shame", 60, "pushed aside by " + upstart.Name, upstart.Id);
				GrudgeNotice("Lemoyne Raiders: " + upstart.FullName + " pushed " + nemesisRecord.Name + " aside - he's " + What(upstart) + " now.");
			}
			else
			{
				worldEvent.Title = upstart.Name + " drew on " + nemesisRecord.Name + " and lost";
				OffscreenDeath(upstart, worldEvent, worldPart, nemesisRecord.Name, gun: true);
				worldPart2.Outcome = "WON";
				worldPart2.Note = "put down an upstart";
				GrudgeNotice("Lemoyne Raiders: " + upstart.FullName + " drew on " + nemesisRecord.Name + ". He lost.");
			}
			worldEvent.Heard = WordReachesYou(worldEvent, Game.Player.Character);
			Chronicle.Events.Add(worldEvent);
			SaveWorld();
			GrudgeLog($"RAIDERS shakeup roll={num} upstart={upstart.Name} above={nemesisRecord.Name}");
			SaveRoster();
		}
		static string What(NemesisRecord r)
		{
			if (r.Rank < 4)
			{
				if (r.Rank < 2)
				{
					return "Raider";
				}
				return "Sergeant";
			}
			return "Captain";
		}
	}

	private unsafe bool DrewOnYou(int h)
	{
		uint num = 0u;
		if (!WEAPON.GET_CURRENT_PED_WEAPON(h, &num, p2: true, 0, p4: true) || num == 0)
		{
			return false;
		}
		uint num2 = WEAPON.GET_WEAPONTYPE_GROUP(num);
		if (num2 != 2685387236u)
		{
			return num2 != 308416707;
		}
		return false;
	}

	private void NoteFairKill(Gang g, Ped victim)
	{
		if (g == null || victim == null || g.OrdersNotFeelings || g.StoryOnly || g == Gangs.Wapiti)
		{
			return;
		}
		int handle = victim.Handle;
		OurRole ourRole = RoleOf(handle);
		if (ourRole != OurRole.Camp && ourRole != OurRole.Active && ourRole != OurRole.Crew && ourRole != OurRole.HiredGun && ourRole != OurRole.Patrol && ourRole != OurRole.Skirmish && ourRole != OurRole.Hunter && ourRole != OurRole.Rival && (!_combatants.TryGetValue(handle, out var value) || Game.GameTime - value >= 15000) && !CameAtYou(handle))
		{
			GrudgeLog(_outlawSwitched.ContainsKey(handle) ? ("FAIRGAME " + AttackerLabel(handle) + " killed - not fighting you, but an outlaw to the game (its " + GroupName(_outlawSwitched[handle].game) + "): no crime") : ("FAIRGAME " + AttackerLabel(handle) + " killed - he wasn't fighting you: the law may count it"));
			return;
		}
		bool flag = Game.GameTime > _fairUntil;
		OpenFair(g, kill: true);
		if (flag)
		{
			GrudgeLog("FAIRGAME your kill of " + AttackerLabel(handle) + " (" + ShortOutfit(g) + ") - a fight with outlaws: its disturbance crimes wait until it's over");
		}
	}

	private static bool FieldRole(OurRole role)
	{
		if (role != OurRole.Camp && role != OurRole.Active && role != OurRole.Crew && role != OurRole.HiredGun && role != OurRole.Patrol && role != OurRole.Skirmish && role != OurRole.Hunter)
		{
			return role == OurRole.Rival;
		}
		return true;
	}

	private static bool FairOutfit(Gang g)
	{
		if (g != null && !g.OrdersNotFeelings && !g.StoryOnly)
		{
			return g != Gangs.Wapiti;
		}
		return false;
	}

	private void FairFightPulse(Ped player)
	{
		if (Game.GameTime < _nextFairPulse)
		{
			return;
		}
		_nextFairPulse = Game.GameTime + 1000;
		Gang gang = null;
		string text = null;
		foreach (LiveCamp value2 in _liveCamps.Values)
		{
			if (!value2.Engaged || !FairOutfit(Gangs.ById(value2.Boss?.Gang)) || !(SitePos(value2.Site).DistanceTo(player.Position) < 160f) || !value2.Peds.Any((Ped x) => x != null && x.Exists() && !x.IsDead && PED.IS_PED_IN_COMBAT(x.Handle, player.Handle)))
			{
				continue;
			}
			gang = Gangs.ById(value2.Boss.Gang);
			text = "camp fight";
			foreach (Ped ped2 in value2.Peds)
			{
				if (ped2 != null && ped2.Exists())
				{
					_fairMen[ped2.Handle] = gang;
				}
			}
			break;
		}
		string text2 = null;
		foreach (KeyValuePair<int, int> combatant in _combatants)
		{
			if (Game.GameTime - combatant.Value > 15000 || !ENTITY.DOES_ENTITY_EXIST(combatant.Key) || RoleOf(combatant.Key) == OurRole.Companion || IsLawman(new Ped(combatant.Key)) || XRayHandsOff(combatant.Key))
			{
				continue;
			}
			Gang gang2 = Gangs.ById(RecordAt(combatant.Key)?.Gang) ?? Gangs.ForModel(ENTITY.GET_ENTITY_MODEL(combatant.Key));
			if (FairOutfit(gang2))
			{
				_fairMen[combatant.Key] = gang2;
				if (gang == null)
				{
					gang = gang2;
					text = (FieldRole(RoleOf(combatant.Key)) ? "a fight" : (AttackerLabel(combatant.Key) + " came at you"));
				}
			}
			else
			{
				if ((RoleOf(combatant.Key) == OurRole.None && RecordAt(combatant.Key) == null && !_provoked.ContainsKey(combatant.Key)) || !CameAtYou(combatant.Key))
				{
					continue;
				}
				if (!ENTITY.IS_ENTITY_DEAD(combatant.Key) && DrewOnYou(combatant.Key))
				{
					_drewOnYouAt[combatant.Key] = Game.GameTime;
				}
				if (_drewOnYouAt.TryGetValue(combatant.Key, out var value) && Game.GameTime - value <= 15000)
				{
					_fairMen[combatant.Key] = null;
					if (text2 == null)
					{
						text2 = AttackerLabel(combatant.Key);
					}
				}
			}
		}
		if (_drewOnYouAt.Count > 64)
		{
			foreach (int item in (from x in _drewOnYouAt
				where Game.GameTime - x.Value > 60000
				select x.Key).ToList())
			{
				_drewOnYouAt.Remove(item);
			}
		}
		if (gang == null && _convo != null && _convo.Kind == ConvoKind.Interrogate && _convo.Ped != null && _convo.Ped.Exists() && FieldRole(RoleOf(_convo.Ped.Handle)))
		{
			Gang gang3 = _convo.It?.Gang ?? Gangs.ById(_convo.Rec?.Gang);
			if (FairOutfit(gang3))
			{
				gang = gang3;
				text = "questioning";
				_fairMen[_convo.Ped.Handle] = gang3;
			}
		}
		if (_fairMen.Count > 64)
		{
			_fairMen.Clear();
		}
		if (gang != null)
		{
			bool flag = Game.GameTime > _fairUntil;
			OpenFair(gang, kill: false);
			if (flag)
			{
				GrudgeLog("FAIRGAME " + text + " with the " + ShortOutfit(gang) + " - outlaws: its disturbance crimes wait until it's over");
			}
			return;
		}
		if (text2 != null)
		{
			bool flag2 = Game.GameTime > _fairUntil;
			OpenFair(null, kill: false, fight: true, text2);
			if (flag2)
			{
				GrudgeLog("FAIRGAME " + text2 + " came at you and drew a weapon - defending yourself: the fight's disturbance crimes wait until it's over");
			}
			return;
		}
		foreach (int item2 in _fairMen.Keys.ToList())
		{
			Ped ped = Entity.FromHandle(item2) as Ped;
			if (ped == null || !ped.Exists() || Downed.IsFinished(item2) || (ped.IsDead && !LooksKnockedOut(ped)))
			{
				_fairMen.Remove(item2);
				continue;
			}
			float num = ped.Position.DistanceTo(player.Position);
			if (num > 40f)
			{
				if (num > 150f)
				{
					_fairMen.Remove(item2);
				}
				continue;
			}
			if (Game.GameTime - _fairFightAt <= 180000)
			{
				OpenFair(_fairMen[item2], kill: false, fight: false, (_fairMen[item2] == null) ? AttackerLabel(item2) : null);
				if (_fairHeldSaid != "hurt")
				{
					_fairHeldSaid = "hurt";
					GrudgeLog(string.Format("FAIRGAME kept open - {0} from the fight lies {1} {2:0} m from you", AttackerLabel(item2), ped.IsDead ? "out cold" : "hurt", num));
				}
			}
			break;
		}
	}

	internal void FairNow(Gang g, string who)
	{
		if (!LawTestOn && !MISC.GET_MISSION_FLAG())
		{
			bool flag = Game.GameTime > _fairUntil;
			OpenFair(g, kill: false, fight: true, (g == null) ? who : null);
			if (!_fairPostponed)
			{
				Crumbs.Native("FairGame postpone disturbance");
				Function.Call(3900265406721784602uL, Game.Player.Handle, true);
				_fairPostponed = true;
			}
			if (flag)
			{
				GrudgeLog("FAIRGAME " + who + " squared up to you" + ((g != null) ? (" (" + ShortOutfit(g) + ")") : "") + " - the fight's disturbance crimes wait until it's over");
			}
		}
	}

	private void OpenFair(Gang g, bool kill, bool fight = true, string who = null)
	{
		if (!LawTestOn)
		{
			if (Game.GameTime > _fairUntil)
			{
				_fairHeldSaid = null;
			}
			_fairUntil = Game.GameTime + 60000;
			if (fight)
			{
				_fairFightAt = Game.GameTime;
			}
			_fairWho = who ?? ((g != null) ? ("the " + ShortOutfit(g)) : _fairWho);
		}
	}

	private void UpdateFairGame(Ped player)
	{
		try
		{
			FairFightPulse(player);
		}
		catch (Exception ex)
		{
			GrudgeLog("FAIRGAME pulse failed: " + ex.Message);
		}
		bool flag = !MISC.GET_MISSION_FLAG() && Game.GameTime <= _fairUntil;
		if (flag != _fairPostponed)
		{
			Crumbs.Native("FairGame postpone disturbance");
			Function.Call(3900265406721784602uL, Game.Player.Handle, flag);
			_fairPostponed = flag;
			if (!flag)
			{
				GrudgeLog("FAIRGAME closed - disturbance crimes back to normal");
			}
		}
	}

	internal void FairGameOff()
	{
		if (_fairPostponed)
		{
			Function.Call(3900265406721784602uL, Game.Player.Handle, false);
			_fairPostponed = false;
		}
	}

	internal void Feed(string text, (int r, int g, int b)? color, NemesisRecord rec)
	{
		if (rec != null)
		{
			text = Pron.Her(text, Models.Female(rec.ModelHash));
		}
		Feed(text, color);
		if ((rec == null || _interro == null || _interro.Rec != rec || text.StartsWith("INTEL") || text.StartsWith("PAST") || text.StartsWith("WANTS")) && rec != null)
		{
			History(rec, text, color);
		}
	}

	internal void History(NemesisRecord rec, string text, (int r, int g, int b)? color = null)
	{
		if (rec == null)
		{
			return;
		}
		text = UiDraw.TheFix(text);
		if (rec.Name != null)
		{
			text = text.Replace(" " + rec.Name + " ", " ").Replace(" " + rec.Name + ":", ":").Replace(" " + rec.Name, "");
		}
		text = Pron.Her(text, Models.Female(rec.ModelHash));
		if (rec.History == null)
		{
			rec.History = new List<HistoryEntry>();
		}
		int cLOCK_MONTH = CLOCK.GET_CLOCK_MONTH();
		string when = $"{Months[Math.Max(0, Math.Min(11, cLOCK_MONTH))]} {CLOCK.GET_CLOCK_DAY_OF_MONTH()}  {CLOCK.GET_CLOCK_HOURS():00}:{CLOCK.GET_CLOCK_MINUTES():00}";
		if (_historyAt.HasValue)
		{
			DateTime dateTime = GameDate.FromMinutes(_historyAt.Value);
			when = $"{Months[dateTime.Month - 1]} {dateTime.Day}  {dateTime.Hour:00}:{dateTime.Minute:00}";
		}
		HistoryEntry historyEntry = ((rec.History.Count > 0) ? rec.History[rec.History.Count - 1] : null);
		if (historyEntry != null && IsRunningLine(text) && IsRunningLine(historyEntry.Text) && historyEntry.Secret == rec.PresumedDead && (DateTime.Now - historyEntry.At).TotalMinutes < 10.0 && HitsOf(text) > HitsOf(historyEntry.Text))
		{
			historyEntry.Text = text;
			historyEntry.At = DateTime.Now;
			return;
		}
		rec.History.Add(new HistoryEntry
		{
			At = DateTime.Now,
			When = when,
			Text = text,
			Color = (color ?? Theme.Text),
			Secret = rec.PresumedDead
		});
		if (rec.History.Count > 60)
		{
			rec.History.RemoveAt(0);
		}
	}

	private static bool IsRunningLine(string t)
	{
		return t?.StartsWith("PUNCHED (", StringComparison.Ordinal) ?? false;
	}

	private static int HitsOf(string t)
	{
		int num = t.IndexOf('(');
		int num2 = ((num < 0) ? (-1) : t.IndexOf(' ', num));
		if (num < 0 || num2 <= num || !int.TryParse(t.Substring(num + 1, num2 - num - 1), out var result))
		{
			return 0;
		}
		return result;
	}

	private void CollapsePunchRuns()
	{
		int num = 0;
		foreach (NemesisRecord item in Roster)
		{
			List<HistoryEntry> history = item.History;
			if (history == null || history.Count < 2)
			{
				continue;
			}
			List<HistoryEntry> list = new List<HistoryEntry>(history.Count);
			foreach (HistoryEntry item2 in history)
			{
				HistoryEntry historyEntry = ((list.Count > 0) ? list[list.Count - 1] : null);
				if (historyEntry != null && IsRunningLine(historyEntry.Text) && IsRunningLine(item2.Text) && historyEntry.Secret == item2.Secret && Math.Abs((item2.At - historyEntry.At).TotalMinutes) < 10.0 && HitsOf(item2.Text) > HitsOf(historyEntry.Text))
				{
					historyEntry.Text = item2.Text;
					historyEntry.At = item2.At;
					num++;
				}
				else
				{
					list.Add(item2);
				}
			}
			if (list.Count != history.Count)
			{
				item.History = list;
			}
		}
		if (num != 0)
		{
			SaveRoster();
			GrudgeLog($"HISTORY {num} repeated PUNCHED lines folded into one a fight");
		}
	}

	internal void Feed(string text, (int r, int g, int b)? color = null)
	{
		text = UiDraw.TheFix(text);
		_feed.Add((UiDraw.RealMs, text, color ?? Theme.Text));
		if (_feed.Count > 30)
		{
			_feed.RemoveAt(0);
		}
		GrudgeLog("FEED " + text);
		string[] repPrefixes = RepPrefixes;
		foreach (string value in repPrefixes)
		{
			if (text.StartsWith(value))
			{
				RepNote(text);
				break;
			}
		}
	}

	private NemesisRecord RecordAt(int handle)
	{
		if (_activeNemesisPed != null && handle == _activeNemesisPed.Handle)
		{
			return ActiveRecord;
		}
		if (_worldNemeses.TryGetValue(handle, out var value))
		{
			return value;
		}
		TownMan townMan = TownManFor(handle);
		if (townMan != null)
		{
			return townMan.Rec;
		}
		if (_sightingPed != null && handle == _sightingPed.Handle)
		{
			return _sightingRec;
		}
		return null;
	}

	private string WhoIs(int handle)
	{
		NemesisRecord nemesisRecord = RecordAt(handle);
		if (nemesisRecord != null)
		{
			return nemesisRecord.Name;
		}
		if (_named.TryGetValue(handle, out var value))
		{
			if (!value.Met)
			{
				return value.Name + " (stranger)";
			}
			return value.Name;
		}
		return "a stranger";
	}

	private static string Delta(int before, int after)
	{
		if (before != after)
		{
			return $"{before} -> {after}";
		}
		return $"{after}";
	}

	internal List<NemesisRecord> FriendsOf(NemesisRecord r)
	{
		if (r?.FriendIds != null)
		{
			return (from id in r.FriendIds
				select Roster.FirstOrDefault((NemesisRecord x) => x.Id == id) into x
				where x != null
				select x).ToList();
		}
		return new List<NemesisRecord>();
	}

	private void RollFriends()
	{
		bool flag = false;
		foreach (NemesisRecord r in Roster.Where((NemesisRecord x) => !x.FriendsRolled && x.Id != null).ToList())
		{
			r.FriendsRolled = true;
			flag = true;
			if (r.FriendIds == null)
			{
				r.FriendIds = new List<string>();
			}
			if (!r.IsAlive || _rng.Next(100) >= ((r.Gang != null) ? Traits.FriendChanceGang : Traits.FriendChanceLoner))
			{
				continue;
			}
			int num = ((_rng.Next(100) >= 30) ? 1 : 2);
			for (int num2 = 0; num2 < num; num2++)
			{
				if (r.FriendIds.Count >= 3)
				{
					break;
				}
				bool other = _rng.Next(100) < Traits.FriendOtherFaction;
				List<NemesisRecord> list = Roster.Where((NemesisRecord x) =>
				{
					if (x != r && x.IsAlive && x.Id != null && !r.FriendIds.Contains(x.Id) && (x.FriendIds?.Count ?? 0) < 3 && x.KinId != r.Id && r.KinId != x.Id)
					{
						if (!other)
						{
							return x.Gang == r.Gang;
						}
						if (x.Gang != r.Gang)
						{
							Gang gang = Gangs.Of(x);
							if (gang == null || !gang.KeepsToItsOwn)
							{
								Gang gang2 = Gangs.Of(r);
								if (gang2 == null)
								{
									return true;
								}
								return !gang2.KeepsToItsOwn;
							}
						}
						return false;
					}
					return false;
				}).ToList();
				if (list.Count != 0)
				{
					NemesisRecord nemesisRecord = list[_rng.Next(list.Count)];
					if (nemesisRecord.FriendIds == null)
					{
						nemesisRecord.FriendIds = new List<string>();
					}
					r.FriendIds.Add(nemesisRecord.Id);
					nemesisRecord.FriendIds.Add(r.Id);
					GrudgeLog("FRIENDS " + r.Name + " (" + (r.Gang ?? "loner") + ") <-> " + nemesisRecord.Name + " (" + (nemesisRecord.Gang ?? "loner") + ")");
				}
			}
		}
		if (flag)
		{
			SaveRoster();
		}
	}

	private void OnRestrained(int handle, string how)
	{
		if (_restrainedAt.TryGetValue(handle, out var value) && Game.GameTime - value < 20000)
		{
			return;
		}
		_tiedCounted.RemoveWhere((int h) => !ENTITY.DOES_ENTITY_EXIST(h) || !PED.IS_PED_HOGTIED(h));
		if (_tiedCounted.Contains(handle))
		{
			return;
		}
		_restrainedAt[handle] = Game.GameTime;
		NemesisRecord nemesisRecord = RecordAt(handle);
		if (nemesisRecord != null)
		{
			nemesisRecord.Touch();
			int hate = nemesisRecord.Hate;
			int fear = nemesisRecord.Fear;
			nemesisRecord.AddHate(10);
			nemesisRecord.AddFear(8);
			nemesisRecord.AddYourNotoriety(5);
			nemesisRecord.TimesHogtied++;
			HiddenSlip(nemesisRecord, "violence");
			CrimeSeen(handle, CrimeOf(GrudgeAction.Hogtie));
			_tiedCounted.Add(handle);
			Remember(nemesisRecord, "Shame", 55, "you tied him up like an animal");
			if (nemesisRecord.Origin == GrudgeOrigin.GangMember)
			{
				nemesisRecord.Origin = GrudgeOrigin.Kidnapped;
				nemesisRecord.KillLocation = GetZoneName(Game.Player.Character.Position);
			}
			SaveRoster();
			Feed($"{how.ToUpperInvariant()} {nemesisRecord.Name}: hate {Delta(hate, nemesisRecord.Hate)}  fear {Delta(fear, nemesisRecord.Fear)}  (tied up {nemesisRecord.TimesHogtied}x)", Theme.Warn, nemesisRecord);
			WorldPart worldPart = PartFor(nemesisRecord, "HOGTIED", (nemesisRecord.TimesHogtied > 1) ? $"tied up {nemesisRecord.TimesHogtied} times now" : nemesisRecord.Title);
			worldPart.Effects.Add($"hate {hate} -> {nemesisRecord.Hate}");
			worldPart.Effects.Add($"fear {fear} -> {nemesisRecord.Fear}");
			Vector3 position = Game.Player.Character.Position;
			ChronicleDeed("hogtie", "You " + how.ToLowerInvariant() + " " + nemesisRecord.Name, "near " + GetZoneName(position), position, nemesisRecord.Gang, worldPart);
			if (nemesisRecord.TimesHogtied == 1)
			{
				GrudgeNotice(nemesisRecord.FullName + " won't forget the rope.");
			}
			return;
		}
		Mark(handle, (Provocation p) =>
		{
			if (!p.Kidnapped)
			{
				Grudge(handle, p, GrudgeAction.Hogtie);
			}
			p.Kidnapped = true;
		});
		if (PED.IS_PED_HOGTIED(handle))
		{
			_tiedCounted.Add(handle);
		}
	}

	private int NotorietyLevelOf(string gangId)
