				Print print = Prints.Values.FirstOrDefault((Print x) => x.Handle == p.Handle && x.Model == model && !x.Dead && (DateTime.Now - x.Last).TotalMinutes < 15.0 && Game.GameTime - _loadedAt < 60000);
				if (print != null && print.Fp != text3)
				{
					pr = print;
					text4 = LinkBlock(pr, p.Handle);
					if (text4 == null)
					{
						LookLog(pr.Name + " | " + model + " | " + text2 + " | SAME MAN after a reload (his look changed: " + pr.Fp + " -> " + text3 + ") - keeps his name");
					}
				}
				else if (Prints.TryGetValue(text3, out pr))
				{
					text4 = LinkBlock(pr, p.Handle);
				}
			}
		}
		if (pr != null && text4 == null)
		{
			TimeSpan t = DateTime.Now - pr.Last;
			Named named = new Named
			{
				Name = pr.Name,
				Title = (pr.Title ?? ""),
				Met = pr.Met,
				Importance = (Kept(pr) ? 3 : 0),
				SeenAt = Game.GameTime,
				NamedAt = Game.GameTime,
				Affil = pr.Affil
			};
			pr.Seen++;
			pr.Last = DateTime.Now;
			pr.LastGameMin = GameMinutesNow();
			pr.Handle = p.Handle;
			pr.Town = text2;
			_lookLinked++;
			_printsDirty = true;
			Acquaintance acquaintance = ((pr.AcqId != null) ? People.FirstOrDefault((Acquaintance x) => x.Id == pr.AcqId) : null);
			if (acquaintance != null && !acquaintance.Dead)
			{
				_acqOf[p.Handle] = acquaintance;
				acquaintance.LastSeen = DateTime.Now;
				acquaintance.LastGameMin = GameMinutesNow();
				acquaintance.TimesSeen++;
				_peopleSoft = true;
				_named[p.Handle] = named;
				if (acquaintance.Grudge > 0)
				{
					RestoreGrudge(p.Handle, acquaintance);
				}
			}
			LookLog(string.Format("{0} | {1} | {2} | LINKED (seen {3}x, last {4} ago{5}{6}) | {7}", pr.Name, model, text2, pr.Seen, Ago(t), pr.Met ? ", you've met" : "", (acquaintance != null && acquaintance.Grudge > 0) ? $", grudge {acquaintance.Grudge}" : "", text3));
			if (pr.Met || (acquaintance != null && acquaintance.Grudge > 0))
			{
				Feed("KNOWN " + pr.Name + " - seen " + (PED.IS_PED_MALE(p.Handle) ? "him" : "her") + " before (" + Ago(t) + " ago" + ((acquaintance != null && acquaintance.Grudge > 0) ? $", still sore: grudge {acquaintance.Grudge}" : "") + ")", Theme.Dim);
			}
			return named;
		}
		if (pr != null && text4 == "he's a nemesis")
		{
			NemesisRecord rec = FindRecord(pr.NemesisId);
			bool flag = rec != null && _worldNemeses.Any((KeyValuePair<int, NemesisRecord> kv) => kv.Key != p.Handle && kv.Value == rec && ENTITY.DOES_ENTITY_EXIST(kv.Key) && !ENTITY.IS_ENTITY_DEAD(kv.Key));
			int num4;
			if (rec != null)
			{
				Gang gang = Gangs.ById(rec.Gang);
				num4 = (((gang != null && gang.UniformKit) || rec.Gang == "lemoyneraiders") ? 1 : 0);
			}
			else
			{
				num4 = 0;
			}
			bool flag2 = (byte)num4 != 0;
			bool flag3 = pr.Handle == p.Handle && Game.GameTime - _loadedAt < 60000 && (DateTime.Now - pr.Last).TotalMinutes < 15.0;
			if (rec != null && !flag3)
			{
				LookLog(rec.Name + " | " + model + " | " + text2 + " | NOT " + rec.Name + ": only looks like him (not the same ped right after a reload)" + (flag2 ? ", and they wear a uniform" : ""));
			}
			if (((rec != null && rec.IsAlive && !rec.PresumedDead && !flag) & flag3) && !flag2)
			{
				_worldNemeses[p.Handle] = rec;
				NoteModel(p);
				pr.Seen++;
				pr.Last = DateTime.Now;
				pr.LastGameMin = GameMinutesNow();
				pr.Handle = p.Handle;
				pr.Town = text2;
				_printsDirty = true;
				LookLog(rec.Name + " | " + model + " | " + text2 + " | SAME NEMESIS - back on his record | " + text3);
				return new Named
				{
					Name = rec.Name,
					Title = (rec.Title ?? ""),
					Met = true,
					Importance = 3,
					SeenAt = Game.GameTime,
					NamedAt = Game.GameTime
				};
			}
		}
		(string, string) tuple2 = FreshName((uint)p.Model.Hash, !PED.IS_PED_MALE(p.Handle));
		string item = tuple2.Item1;
		string item2 = tuple2.Item2;
		Named named2 = new Named
		{
			Name = item,
			Title = item2,
			SeenAt = Game.GameTime,
			NamedAt = Game.GameTime,
			Affil = RollAffiliation(p)
		};
		if (text3 != null)
		{
			if (pr == null || text4 == "expired")
			{
				Prints[text3] = new Print
				{
					Fp = text3,
					Look = look,
					Name = item,
					Title = item2,
					Model = model,
					Town = text2,
					Pieces = num2,
					Seen = 1,
					First = DateTime.Now,
					Last = DateTime.Now,
					LastGameMin = GameMinutesNow(),
					Handle = p.Handle,
					Affil = named2.Affil
				};
				_lookNew++;
				_printsDirty = true;
				LookLog(string.Format("{0} | {1} | {2} | {3} | {4} | {5}/{6} pieces", item, model, text2, (pr == null) ? "NEW" : ("NEW (the look of " + pr.Name + " expired)"), text3, num2, num3));
			}
			else
			{
				if (text4 == "twin")
				{
					_lookTwins++;
				}
				else
				{
					_lookBlocked++;
				}
				LookLog(item + " | " + model + " | " + text2 + " | NOT " + pr.Name + ": " + text4 + " | " + text3);
			}
		}
		return named2;
	}

	private static string Ago(TimeSpan t)
	{
		if (!(t.TotalMinutes < 1.0))
		{
			if (!(t.TotalHours < 1.0))
			{
				if (!(t.TotalDays < 1.0))
				{
					return $"{t.TotalDays:0.0} days";
				}
				return $"{t.TotalHours:0.0} h";
			}
			return $"{t.TotalMinutes:0} min";
		}
		return $"{t.TotalSeconds:0} s";
	}

	private void LookLog(string text)
	{
		if (!Config.Verbose)
		{
			return;
		}
		try
		{
			SafeFile.Append(PrintsLog, $"{DateTime.Now:HH:mm:ss} | {text}{Environment.NewLine}");
		}
		catch
		{
		}
	}

	private void LookSync(Ped player)
	{
		if (!Config.LinkLooks)
		{
			return;
		}
		Vector3 position = player.Position;
		long num = GameMinutesNow();
		int num2 = 0;
		foreach (KeyValuePair<int, Named> item in _named.ToList())
		{
			int key = item.Key;
			Named value = item.Value;
			if (value.Story || _fpOf.ContainsKey(key) || num2 >= 6 || !ENTITY.DOES_ENTITY_EXIST(key) || !ENTITY.IS_ENTITY_A_PED(key) || ENTITY.IS_ENTITY_DEAD(key))
			{
				continue;
			}
			Ped ped = new Ped(key);
			if (!(ped.Position.DistanceTo(position) > Config.NamingRadius))
			{
				num2++;
				(string, string, int, int) tuple;
				try
				{
					tuple = Fingerprint(ped);
				}
				catch
				{
					_fpOf[key] = "";
					continue;
				}
				Dictionary<int, string> fpOf = _fpOf;
				string value2;
				if (tuple.Item3 > 0)
				{
					(value2, _, _, _) = tuple;
				}
				else
				{
					value2 = "";
				}
				fpOf[key] = value2;
				if (tuple.Item3 != 0 && !Prints.ContainsKey(tuple.Item1))
				{
					Prints[tuple.Item1] = new Print
					{
						Fp = tuple.Item1,
						Look = tuple.Item2,
						Name = value.Name,
						Title = value.Title,
						Pieces = tuple.Item3,
						Seen = 1,
						First = DateTime.Now,
						Last = DateTime.Now,
						LastGameMin = num,
						Handle = key,
						Town = (_currentTown ?? TownAt(ped.Position) ?? GetZoneName(ped.Position)),
						Model = Models.Name((uint)ped.Model.Hash)
					};
					_printsDirty = true;
					LookLog(value.Name + " | " + Prints[tuple.Item1].Model + " | " + Prints[tuple.Item1].Town + " | STORED (named elsewhere) | " + tuple.Item1);
				}
			}
		}
		foreach (int item2 in _worldNemeses.Keys.Concat(from t in _townMen
			where t.Ped != null
			select t.Ped.Handle).Concat((!(_activeNemesisPed != null)) ? new int[0] : new int[1] { _activeNemesisPed.Handle }).Distinct()
			.ToList())
		{
			if (num2 >= 6 || _fpOf.ContainsKey(item2) || !ENTITY.DOES_ENTITY_EXIST(item2) || !ENTITY.IS_ENTITY_A_PED(item2) || ENTITY.IS_ENTITY_DEAD(item2))
			{
				continue;
			}
			NemesisRecord nemesisRecord = RecordAt(item2);
			if (nemesisRecord == null)
			{
				continue;
			}
			Ped ped2 = new Ped(item2);
			if (ped2.Position.DistanceTo(position) > Config.NamingRadius || !LookReadable(ped2))
			{
				continue;
			}
			num2++;
			(string, string, int, int) tuple3;
			try
			{
				tuple3 = Fingerprint(ped2);
			}
			catch
			{
				_fpOf[item2] = "";
				continue;
			}
			Dictionary<int, string> fpOf2 = _fpOf;
			string value3;
			if (tuple3.Item3 > 0)
			{
				(value3, _, _, _) = tuple3;
			}
			else
			{
				value3 = "";
			}
			fpOf2[item2] = value3;
			if (tuple3.Item3 != 0)
			{
				if (!Prints.TryGetValue(tuple3.Item1, out var value4))
				{
					Prints[tuple3.Item1] = new Print
					{
						Fp = tuple3.Item1,
						Look = tuple3.Item2,
						Name = nemesisRecord.Name,
						Title = nemesisRecord.Title,
						Pieces = tuple3.Item3,
						Seen = 1,
						First = DateTime.Now,
						Last = DateTime.Now,
						LastGameMin = num,
						Handle = item2,
						Town = (_currentTown ?? TownAt(ped2.Position) ?? GetZoneName(ped2.Position)),
						Model = Models.Name((uint)ped2.Model.Hash),
						NemesisId = nemesisRecord.Id,
						Met = true
					};
					LookLog(nemesisRecord.Name + " | " + Prints[tuple3.Item1].Model + " | " + Prints[tuple3.Item1].Town + " | STORED (nemesis in the world) | " + tuple3.Item1);
				}
				else if (value4.NemesisId != nemesisRecord.Id)
				{
					value4.NemesisId = nemesisRecord.Id;
					value4.Name = nemesisRecord.Name;
					value4.Handle = item2;
					LookLog(nemesisRecord.Name + " | look now his (nemesis in the world) | " + tuple3.Item1);
				}
				_printsDirty = true;
			}
		}
		foreach (KeyValuePair<int, string> item3 in _fpOf.ToList())
		{
			if (item3.Value == "" || !Prints.TryGetValue(item3.Value, out var value5) || value5.Handle != item3.Key)
			{
				continue;
			}
			int key2 = item3.Key;
			if (!ENTITY.DOES_ENTITY_EXIST(key2))
			{
				continue;
			}
			bool flag = false;
			NemesisRecord nemesisRecord2 = RecordAt(key2);
			if (nemesisRecord2 != null && value5.NemesisId != nemesisRecord2.Id)
			{
				value5.NemesisId = nemesisRecord2.Id;
				value5.Name = nemesisRecord2.Name;
				flag = true;
			}
			if (_named.TryGetValue(key2, out var value6) && value6.Name == value5.Name)
			{
				if (value6.Met && !value5.Met)
				{
					value5.Met = true;
					flag = true;
				}
				if (!string.IsNullOrEmpty(value6.Title) && value6.Title != value5.Title)
				{
					value5.Title = value6.Title;
					flag = true;
				}
			}
			if (_acqOf.TryGetValue(key2, out var value7) && (value5.AcqId != value7.Id || value5.Grudge != value7.Grudge || value5.Temper != value7.Temper))
			{
				value5.AcqId = value7.Id;
				value5.Grudge = value7.Grudge;
				value5.Temper = value7.Temper;
				flag = true;
			}
			Ped ped3 = new Ped(key2);
			if (!value5.Dead && ped3.IsDead && !LooksKnockedOut(ped3))
			{
				value5.Dead = true;
				flag = true;
				LookLog(value5.Name + " | died - his look won't come back as him");
			}
			if (!ped3.IsDead && ped3.Position.DistanceTo(position) <= Config.NamingRadius && num - value5.LastGameMin >= 10)
			{
				value5.LastGameMin = num;
				value5.Last = DateTime.Now;
				flag = true;
			}
			if (flag)
			{
				_printsDirty = true;
				if (Kept(value5))
				{
					_keptNames.Add(value5.Name);
				}
			}
		}
	}

	private void SavePrints(bool later = false)
	{
		if (_prints == null || !_printsDirty)
		{
			return;
		}
		try
		{
			long now = GameMinutesNow();
			foreach (string item in (from kv in _prints
				where !Kept(kv.Value) && !kv.Value.Dead && Math.Abs(now - kv.Value.LastGameMin) > (long)Config.LookMemoryDays * 1440L
				select kv.Key).ToList())
			{
				_prints.Remove(item);
			}
			if (_prints.Count > Config.LookCap)
			{
				foreach (string item2 in (from kv in (from kv in _prints
						orderby Kept(kv.Value), kv.Value.LastGameMin
						select kv).Take(_prints.Count - Config.LookCap)
					select kv.Key).ToList())
				{
					_prints.Remove(item2);
				}
			}
			string text = JsonConvert.SerializeObject(_prints, Formatting.None);
			if (later)
			{
				SafeFile.WriteLater(PrintsPath, text, keepBak: true, (Exception err) =>
				{
					if (err != null)
					{
						_printsDirty = true;
					}
				});
			}
			else if (SafeFile.WaitWrites())
			{
				SafeFile.Write(PrintsPath, text, keepBak: true);
			}
			else
			{
				SafeFile.WriteLater(PrintsPath, text, keepBak: true, (Exception err) =>
				{
					if (err != null)
					{
						_printsDirty = true;
					}
				});
			}
			_printsDirty = false;
		}
		catch (Exception ex)
		{
			GrudgeLog("LOOKS save failed: " + ex.Message);
		}
	}

	private void RestoreGrudge(int handle, Acquaintance a)
	{
		Provocation provocation = RememberStranger(handle);
		if (provocation == null)
		{
			return;
		}
		provocation.Score = a.Grudge;
		provocation.LastActionAt = Game.GameTime;
		provocation.SawFace = a.SawFace ?? true;
		provocation.Settled = a.GrudgeSettled;
		provocation.SettledScore = provocation.Score;
		if (Enum.TryParse<Personality>(a.Temper, out var result))
		{
			provocation.Temper = result;
			if (provocation.Shadow != null)
			{
				provocation.Shadow.Personality = result;
			}
		}
	}

	internal string FingerprintDebugLine()
	{
		if (Config.LinkLooks)
		{
			return $"looks: {Prints.Count} stored ({_keptNames?.Count ?? 0} people you know) - this session {_lookLinked} recognised, {_lookNew} new, {_lookTwins} twins, {_lookBlocked} blocked, {_lookEmpty} unreadable";
		}
		return "looks: name linking OFF ([People] LinkLooks)";
	}

	internal bool UnderArrest(int h)
	{
		if (h != 0)
		{
			if (h != _peaceAggressor || (_peaceStep < 3 && !_peaceArrested))
			{
				return _lawTook.Contains(h);
			}
			return true;
		}
		return false;
	}

	internal bool LawTook(int h)
	{
		if (h != 0)
		{
			if (!_lawTook.Contains(h))
			{
				if (h == _peaceAggressor)
				{
					return _peaceStep >= 3;
				}
				return false;
			}
			return true;
		}
		return false;
	}

	private string NameOf(int h)
	{
		string text = RecordAt(h)?.Name;
		if (text == null)
		{
			if (!_named.TryGetValue(h, out var value))
			{
				return "a stranger";
			}
			text = value.Name;
		}
		return text;
	}

	internal void NoteAntagonized(int target)
	{
		if (target != 0)
		{
			_antagAt[target] = Game.GameTime;
		}
	}

	internal bool YouStartedIt(int h, Ped player, out string why)
	{
		why = null;
		if (WentForYouQuestioned(h))
		{
			return false;
		}
		int value;
		int value2;
		if (ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(h, player.Handle, p2: true, p3: true) || _hitByYouAt.ContainsKey(h))
		{
			why = "you hurt him first";
		}
		else if (_shotAtAt.TryGetValue(h, out value) && Game.GameTime - value < 30000)
		{
			why = "you shot at him";
		}
		else if (WEAPON.IS_PED_ARMED(player.Handle, 4) && (PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(Game.Player.Handle, h) || PLAYER.IS_PLAYER_TARGETTING_ENTITY(Game.Player.Handle, h, p2: false)))
		{
			why = "you had a gun on him";
		}
		else if (_gunOnAt.TryGetValue(h, out value2) && Game.GameTime - value2 < 10000)
		{
			why = "you had a gun on him a moment ago";
		}
		else if (Game.GameTime - GunMelee.LastShotAt < 10000 && ENTITY.GET_ENTITY_COORDS(h, p1: true, p2: true).DistanceTo(player.Position) < 50f)
		{
			why = "you'd just fired your gun near him";
		}
		else if (_gunOnAt.Any((KeyValuePair<int, int> kv) => kv.Key != h && Game.GameTime - kv.Value < 10000 && ENTITY.DOES_ENTITY_EXIST(kv.Key) && ENTITY.GET_ENTITY_COORDS(kv.Key, p1: true, p2: true).DistanceTo(ENTITY.GET_ENTITY_COORDS(h, p1: true, p2: true)) < 50f))
		{
			why = "you'd drawn on someone near him";
		}
		else if (Game.GameTime - _yourCrimeAt < 30000 && ENTITY.GET_ENTITY_COORDS(h, p1: true, p2: true).DistanceTo(_yourCrimePos) < 40f)
		{
			why = "you were in the middle of a crime (" + _yourCrimeWhat + ")";
		}
		return why != null;
	}

	private void NoteFirstBlow(Ped him, Ped player)
	{
		if (him == null || !him.Exists() || him.IsDead)
		{
			return;
		}
		int handle = him.Handle;
		string text = NameOf(handle);
		if (_peaceAggressor != 0)
		{
			GrudgeLog("PEACE " + text + " is fighting you - the law's already busy with " + _peaceName);
			return;
		}
		if (Game.GameTime < _peaceCooldownUntil)
		{
			GrudgeLog($"PEACE {text} is fighting you - a fight just ended here ({(_peaceCooldownUntil - Game.GameTime) / 1000} s)");
			return;
		}
		if (IsLawman(him))
		{
			GrudgeLog("PEACE " + text + " is a lawman - not his own case");
			return;
		}
		if (!InsideAnyTown(player.Position))
		{
			OurRole ourRole = RoleOf(handle);
			if ((ourRole != OurRole.None && ourRole != OurRole.Regular) || Gangs.ForModel((uint)him.Model.Hash) != null || RecordAt(handle)?.Gang != null)
			{
				return;
			}
		}
		if (OutfitFighter(handle))
		{
			return;
		}
		Gang gang = Gangs.ById(RecordAt(handle)?.Gang) ?? Gangs.ForModel((uint)him.Model.Hash);
		if (gang != null && gang.OrdersNotFeelings)
		{
			GrudgeLog("PEACE " + text + " is a soldier - not the town law's business");
			return;
		}
		if (Kids.IsChild(him) || (IsStoryPed(him) && RecordAt(handle) == null) || GameOwned(him))
		{
			GrudgeLog("PEACE " + text + " is fighting you - a child / story / mission ped, left to the game");
			return;
		}
		if (PLAYER.GET_PLAYER_WANTED_LEVEL(Game.Player.Handle) > 0)
		{
			GrudgeLog("PEACE " + text + " is fighting you - you're already wanted, the law stays out");
			return;
		}
		if (YouStartedIt(handle, player, out var why))
		{
			LawComesForYou(him, player, why);
			return;
		}
		_selfDefence.Add(handle);
		try
		{
			Gang gang2 = Gangs.ById(RecordAt(handle)?.Gang) ?? Gangs.ForModel((uint)him.Model.Hash);
			FairNow(FairOutfit(gang2) ? gang2 : null, text);
			SwitchOutlaw(handle, "he swung at you", Game.GameTime);
		}
		catch (Exception ex)
		{
			GrudgeLog("PEACE fair window failed: " + ex.Message);
		}
		if (LAW.IS_LAW_INCIDENT_ACTIVE(Game.Player.Handle))
		{
			GrudgeLog("PEACE note: a law incident is open (the game's own) - siding with you anyway, he swung first");
		}
		bool flag = _antagAt.TryGetValue(handle, out var value) && Game.GameTime - value < 120000;
		bool flag2 = WEAPON.IS_PED_ARMED(handle, 5);
		Ped ped = FreeLawman(player, flag2 ? 110f : 70f);
		if (ped == null)
		{
			_peaceWaiting[handle] = (flag, Game.GameTime);
			GrudgeLog("PEACE " + text + " swung first" + (flag ? " (you baited him)" : "") + " - no lawman near who saw it yet, watching for one");
		}
		else
		{
			StartPeace(him, ped, flag, flag2, player);
		}
	}

	private Ped FreeLawman(Ped player, float range)
	{
		Vector3 me = player.Position;
		return (from t in PedSnapshot(player)
			where t.p != null && t.p.Exists() && !t.p.IsDead && IsLawman(t.p) && !IsOurs(t.p.Handle) && !GameOwned(t.p) && !IsStoryPed(t.p) && !GameEventPed(t.p) && !PED.IS_PED_IN_COMBAT(t.p.Handle, 0) && (t.pos - me).Length() < range
			select t.p into p
			orderby p.Position.DistanceTo(me)
			select p).FirstOrDefault((Ped p) => p.Position.DistanceTo(me) < 15f || ENTITY.HAS_ENTITY_CLEAR_LOS_TO_ENTITY(p.Handle, player.Handle, 17));
	}

	private void CheckPeaceWaiting(Ped player)
	{
		foreach (KeyValuePair<int, (bool, int)> item in _peaceWaiting.ToList())
		{
			int key = item.Key;
			Ped ped = new Ped(key);
			if (!ENTITY.DOES_ENTITY_EXIST(key) || ped.IsDead || Game.GameTime - item.Value.Item2 > 60000 || !PED.IS_PED_IN_COMBAT(key, player.Handle) || PLAYER.GET_PLAYER_WANTED_LEVEL(Game.Player.Handle) > 0)
			{
				_peaceWaiting.Remove(key);
				continue;
			}
			bool flag = WEAPON.IS_PED_ARMED(key, 5);
			bool flag2 = PED.IS_PED_SHOOTING(key);
			NemesisMod nemesisMod = this;
			Ped player2 = player;
			float range;
			if (flag2)
			{
				range = 130f;
			}
			else
			{
				range = (flag ? 110f : 70f);
			}
			Ped ped2 = nemesisMod.FreeLawman(player2, range);
			if (ped2 == null)
			{
				continue;
			}
			_peaceWaiting.Remove(key);
			GrudgeLog(string.Format("PEACE a lawman came in range of {0}'s fight ({1} s in{2})", NameOf(key), (Game.GameTime - item.Value.Item2) / 1000, flag2 ? ", he's shooting" : ""));
			StartPeace(ped, ped2, item.Value.Item1, flag, player);
			break;
		}
	}

	private void StartPeace(Ped him, Ped law, bool baited, bool armed, Ped player)
	{
		int handle = him.Handle;
		Vector3 position = player.Position;
		_peaceAggressor = handle;
		_peaceLaw = law.Handle;
		_peaceSince = Game.GameTime;
		_peaceStep = 0;
		_peaceQuietSince = 0;
		bool flag = WEAPON.IS_PED_ARMED(handle, 4) || PED.IS_PED_SHOOTING(handle);
		bool flag2 = !flag && WEAPON.IS_PED_ARMED(handle, 1);
		_peaceBaited = baited;
		_peaceArmed = flag;
		_peaceBlade = flag2;
		_peaceName = NameOf(handle);
		_peaceHogtieTried = false;
		_peaceArrested = false;
		_peaceArrestAt = 0;
		_peaceBeatenAt = 0;
		_peaceWarnedAt = 0;
		_peaceCarrying = false;
		_peaceTieOrderAt = 0;
		_peaceTieFallback = false;
		_peaceLastHitSeen = (_hitByYouAt.TryGetValue(handle, out var value) ? value : 0);
		float num = law.Position.DistanceTo(position);
		string text;
		if (flag)
		{
			text = "WITH A GUN";
		}
		else
		{
			text = (flag2 ? "with a blade" : "with his fists");
		}
		GrudgeLog(string.Format("PEACE {0} swung first{1} {2} - lawman {3} {4:0} m off {5}", _peaceName, baited ? " (you baited him)" : "", text, law.Handle, num, flag ? "goes for him" : "comes to arrest him"));
		Feed("PEACE " + _peaceName + " went for you " + text + (baited ? " - you goaded him" : "") + ": the law " + (flag ? "steps in" : "comes to arrest him"), Theme.Good);
		if (flag)
		{
			LawTakesHim(law, "Drop it!");
			return;
		}
		Crumbs.Native("FirstBlow law runs over");
		TASK.TASK_GO_TO_ENTITY(law.Handle, handle, 20000, 2.5f, flag2 ? 2.6f : 2f, 0f, 0);
		CrowdWatches(player, him);
	}

	private void LawTakesHim(Ped law, string line)
	{
		Crumbs.Native("FirstBlow law combat");
		ShowSubtitle("Lawman: " + line);
		TASK.TASK_COMBAT_PED(law.Handle, _peaceAggressor, 0, 16);
		_peaceStep = 2;
	}

	private void CrowdWatches(Ped player, Ped him)
	{
		Vector3 mid = (player.Position + him.Position) * 0.5f;
		int num = 0;
		foreach (var item in from t in PedSnapshot(player)
			orderby (t.pos - mid).Length()
			select t)
		{
			if (num >= 4)
			{
				break;
			}
			var (ped, _) = item;
			if (!(ped == null) && ped.Exists() && !ped.IsDead && ped.IsHuman && ped.Handle != him.Handle && ped.Handle != _peaceLaw && !((item.pos - mid).Length() > 25f) && !IsOurs(ped.Handle) && !IsLawman(ped) && !Kids.IsChild(ped) && !IsStoryPed(ped) && !GameOwned(ped) && !GameEventPed(ped) && !PED.IS_PED_IN_COMBAT(ped.Handle, 0) && !ped.IsHogtied && !PED.IS_PED_IN_ANY_VEHICLE(ped.Handle, p1: false) && !PED.IS_PED_ON_MOUNT(ped.Handle))
			{
				Crumbs.Native("FirstBlow crowd looks");
				TASK.TASK_TURN_PED_TO_FACE_ENTITY(ped.Handle, him.Handle, 3000, 0f, 0f, 0f);
				TASK.TASK_LOOK_AT_ENTITY(ped.Handle, him.Handle, 12000, 0, 51, 0);
				num++;
			}
		}
		if (num > 0)
		{
			GrudgeLog($"PEACE {num} townsfolk stop to watch");
		}
	}

	private void UpdatePeace(Ped player)
	{
		if (_lawOnYou != 0 && (Game.GameTime - _lawOnYouAt > 30000 || !ENTITY.DOES_ENTITY_EXIST(_lawOnYou)))
		{
			GrudgeLog("PEACE the lawman who came for you is done");
			_lawOnYou = 0;
		}
		if (_peaceAggressor == 0)
		{
			if (_peaceWaiting.Count > 0 && Game.GameTime >= _peaceCooldownUntil)
			{
				CheckPeaceWaiting(player);
			}
			return;
		}
		Ped ped = new Ped(_peaceAggressor);
		Ped ped2 = new Ped(_peaceLaw);
		bool flag = !ENTITY.DOES_ENTITY_EXIST(_peaceLaw) || ped2.IsDead;
		bool flag2 = !ENTITY.DOES_ENTITY_EXIST(_peaceAggressor);
		bool flag3 = PLAYER.GET_PLAYER_WANTED_LEVEL(Game.Player.Handle) > 0;
		if ((flag || (Game.GameTime - _peaceSince > 120000 && _peaceStep != 4 && _peaceStep != 5)) | flag3)
		{
			NemesisMod nemesisMod = this;
			string why;
			if (flag)
			{
				why = "the lawman is gone";
			}
			else
			{
				why = (flag3 ? "you became wanted - the law's business now" : "2 minutes passed");
			}
			nemesisMod.EndPeace(why, clean: false);
		}
		else if (_peaceStep == 4)
		{
			UpdateCarryOff(ped, ped2, player);
		}
		else
		{
			if (YouKeptAtHim(ped, ped2, player))
			{
				return;
			}
			bool flag4 = flag2 || ped.IsDead || ped.IsHogtied || LooksKnockedOut(ped);
			if (!flag2 && ped.IsDead && _peaceStep == 3 && !_peaceArrested)
			{
				int num = PED.GET_PED_SOURCE_OF_DEATH(_peaceAggressor);
				NemesisMod nemesisMod2 = this;
				string peaceName = _peaceName;
				string text;
				if (num == player.Handle)
				{
					text = "you";
				}
				else if (num == _peaceLaw)
				{
					text = "the lawman";
				}
				else
				{
					text = ((num == 0) ? "nobody known" : ("ped " + num));
				}
				nemesisMod2.GrudgeLog("PEACE " + peaceName + " died during the arrest - killed by " + text);
				EndPeace("he died", clean: false);
				return;
			}
			bool flag5 = !flag4 && PED.IS_PED_IN_COMBAT(_peaceAggressor, player.Handle);
			if (_peaceStep != 2 && !flag4 && !_peaceArrested && (WEAPON.IS_PED_ARMED(_peaceAggressor, 4) || PED.IS_PED_SHOOTING(_peaceAggressor)))
			{
				GrudgeLog("PEACE " + _peaceName + " pulled a gun - the law goes for him");
				LawTakesHim(ped2, "Drop that gun!");
			}
			if (_peaceStep == 0 && !flag4 && ped2.Position.DistanceTo(ped.Position) < 6f)
			{
				StartArrest(ped, ped2);
			}
			if (_peaceStep == 3)
			{
				if (Game.GameTime - _peaceBeatAt >= 5000)
				{
					_peaceBeatAt = Game.GameTime;
					GrudgeLog($"PEACE arresting {_peaceName}: {(Game.GameTime - _peaceArrestAt) / 1000} s - fighting {flag5}, lawman {ped2.Position.DistanceTo(ped.Position):0.0} m");
				}
				if (flag5 && Game.GameTime - _peaceArrestAt > 4000)
				{
					GrudgeLog("PEACE " + _peaceName + " won't come quietly - the law goes for him");
					LawTakesHim(ped2, "Fine - the hard way!");
				}
				else if (ped2.Position.DistanceTo(ped.Position) < 2.4f || Game.GameTime - _peaceArrestAt > 10000)
				{
					StartMarch(ped, ped2, player);
				}
			}
			else if (_peaceStep == 5)
			{
				UpdateMarch(ped, ped2, player, flag5);
			}
			else if (flag5)
			{
				_peaceQuietSince = 0;
			}
			else if (_peaceQuietSince == 0)
			{
				_peaceQuietSince = Game.GameTime;
			}
			else if (Game.GameTime - _peaceQuietSince >= 3000 || flag4)
			{
				string text2;
				if (_currentTown != null && TownReputation(_currentTown) <= -20)
				{
					text2 = (new string[3] { "Can't say I care for you, mister. But he swung first. Go on.", "Folks here want you gone, and so do I. Still - he started it. Move along.", "I know who you are. But I saw him throw first. Get out of my sight." })[_rng.Next(3)];
				}
				else
				{
					text2 = (_peaceBaited ? (new string[3] { "You goaded him, mister - but he swung first. Move along.", "I heard you rile him. Still, he started it. Go on.", "Don't go baiting folk in my town. He threw first, so go on." })[_rng.Next(3)] : (new string[3] { "I saw it - he swung first. Go on about your business.", "He started it. You're free to go.", "That was self-defence. Move along." })[_rng.Next(3)]);
				}
				if (ped2.Position.DistanceTo(player.Position) < 25f)
				{
					ShowSubtitle("Lawman: " + text2);
				}
				EndPeace(flag4 ? "he's down" : "it's over", clean: true);
			}
		}
	}

	private void StartArrest(Ped him, Ped law)
	{
		_peaceStep = 3;
		_peaceArrestAt = Game.GameTime;
		ShowSubtitle("Lawman: " + (_peaceBlade ? (new string[3] { "Drop the knife! Drop it - now!", "Put that blade down! You're under arrest!", "Knife on the ground! Hands where I can see 'em!" })[_rng.Next(3)] : (new string[3] { "That's enough! You're under arrest!", "Hands up! You're coming with me!", "Hold it right there - you're under arrest!" })[_rng.Next(3)]));
		int handle = him.Handle;
		Crumbs.Native("FirstBlow arrest");
		if (_peaceBlade)
		{
			WEAPON.MAKE_PED_DROP_WEAPON(handle, p1: true, 0, p3: true, p4: true);
		}
		him.BlockPermanentEvents = true;
		him.RelationshipGroup = PED.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH(handle);
		ForgetSwitch(handle);
		TASK.CLEAR_PED_TASKS_IMMEDIATELY(handle, p1: false, p2: true);
		TASK.TASK_HANDS_UP(handle, 15000, law.Handle, -1, p4: false);
		TASK.TASK_GO_TO_ENTITY(law.Handle, handle, 10000, 1f, 1.8f, 0f, 0);
		_peaceTieAt = 0;
		_peaceTieOrderAt = 0;
		_peaceTieFallback = false;
		_peaceCarrying = false;
		if (_peaceBeatenAt == 0)
		{
			_peaceBeatenAt = Game.GameTime;
		}
		_lawTook.Add(handle);
		GrudgeLog(string.Format("PEACE lawman {0} arrests {1}{2}", law.Handle, _peaceName, _peaceBlade ? " (knife dropped)" : ""));
	}

	private void ArrestedByLaw(Ped him)
	{
		NemesisRecord nemesisRecord = RecordAt(him.Handle);
		string text = _currentTown ?? TownAt(him.Position) ?? "town";
		GrudgeLog("PEACE " + _peaceName + " ARRESTED in " + text);
		Feed("ARRESTED " + _peaceName + " - the law took him in for going for you", Theme.Good, nemesisRecord);
		BookArrestedPedIntoCourt(him, nemesisRecord, text);
		if (nemesisRecord != null)
		{
			nemesisRecord.RestUntil = Math.Max(nemesisRecord.RestUntil, GameMinutesNow() + 2880);
			History(nemesisRecord, "ARRESTED in " + text + " - the law saw him go for you first", Theme.Warn);
			Remember(nemesisRecord, "Shame", 50, "arrested in " + text + " for going for you");
			nemesisRecord.Touch();
			SaveRoster();
		}
	}

	private void LawComesForYou(Ped him, Ped player, string why)
	{
		string text = NameOf(him.Handle);
		if (WEAPON.IS_PED_ARMED(player.Handle, 5))
		{
			GrudgeLog("PEACE " + text + " is fighting you - you started it (" + why + ") with a weapon: the game's own law");
			return;
		}
		if (_lawOnYou != 0 || Game.GameTime < _lawOnYouCooldown)
		{
			GrudgeLog("PEACE " + text + " is fighting you - you started it (" + why + ")");
			return;
		}
		Vector3 me = player.Position;
		Ped ped = (from t in PedSnapshot(player)
			where t.p != null && t.p.Exists() && !t.p.IsDead && IsLawman(t.p) && !IsOurs(t.p.Handle) && !GameOwned(t.p) && !IsStoryPed(t.p) && !GameEventPed(t.p) && !PED.IS_PED_IN_COMBAT(t.p.Handle, 0) && (t.pos - me).Length() < 40f && ENTITY.HAS_ENTITY_CLEAR_LOS_TO_ENTITY(t.p.Handle, player.Handle, 17)
			select t.p into p
			orderby p.Position.DistanceTo(me)
			select p).FirstOrDefault();
		if (ped == null)
		{
			GrudgeLog("PEACE " + text + " is fighting you - you started it (" + why + "), no lawman saw it");
			return;
		}
		_lawOnYou = ped.Handle;
		_lawOnYouAt = Game.GameTime;
		_lawOnYouCooldown = Game.GameTime + 90000;
		ShowSubtitle("Lawman: " + (new string[3] { "You there! I saw that - you're under arrest!", "Hold it! You threw the first punch, mister!", "That's enough! You're coming with me!" })[_rng.Next(3)]);
		Crumbs.Native("FirstBlow law arrests you");
		TASK.TASK_ARREST_PED(ped.Handle, player.Handle);
		GrudgeLog($"PEACE you started it with {text} ({why}) - lawman {ped.Handle} {ped.Position.DistanceTo(me):0} m off saw it and comes to arrest you");
		Feed("PEACE you swung first at " + text + " - the law saw it", Theme.Warn);
	}

	private void StartMarch(Ped him, Ped law, Ped player)
	{
		_peaceStep = 5;
		_peaceMarchAt = Game.GameTime;
		_peaceMarchNudge = Game.GameTime;
		Vector3 vector = him.Position - player.Position;
		vector.Z = 0f;
		if (vector.Length() < 0.5f)
		{
			vector = new Vector3(1f, 0f, 0f);
		}
		vector.Normalize();
		Vector3 vector2 = him.Position + vector * (70f + (float)_rng.NextDouble() * 20f);
		Vector3 safeCoordForPed = World.GetSafeCoordForPed(vector2);
		_peaceCarryTo = ((safeCoordForPed.X == 0f && safeCoordForPed.Y == 0f) ? vector2 : safeCoordForPed);
		Crumbs.Native("FirstBlow march");
		TASK.CLEAR_PED_TASKS(_peaceAggressor, p1: true, p2: true);
		TASK.TASK_FOLLOW_NAV_MESH_TO_COORD(_peaceAggressor, _peaceCarryTo.X, _peaceCarryTo.Y, _peaceCarryTo.Z, 1f, -1, 1f, 0, 0f);
		TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(_peaceLaw, _peaceAggressor, 0f, -1.6f, 0f, 1.2f, -1, 1f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
		ShowSubtitle("Lawman: " + (new string[3] { "Walk. Nice and slow.", "Move it - a night in the cells'll cool you off.", "Go on. The judge can sort you out." })[_rng.Next(3)]);
		if (!_peaceArrested)
		{
			_peaceArrested = true;
			ArrestedByLaw(him);
		}
		GrudgeLog($"PEACE the lawman marches {_peaceName} off ({him.Position.DistanceTo(_peaceCarryTo):0} m to go)");
	}

	private void UpdateMarch(Ped him, Ped law, Ped player, bool fighting)
	{
		if (!ENTITY.DOES_ENTITY_EXIST(_peaceAggressor) || him.IsDead)
		{
			EndPeace("marched off", clean: true);
			return;
		}
		if (fighting)
		{
			GrudgeLog("PEACE " + _peaceName + " broke loose and fights - the law goes for him");
			LawTakesHim(law, "Fine - the hard way!");
			return;
		}
		if (Game.GameTime - _peaceMarchNudge > 5000 && ENTITY.GET_ENTITY_SPEED(_peaceAggressor) < 0.3f && him.Position.DistanceTo(_peaceCarryTo) > 3f)
		{
			_peaceMarchNudge = Game.GameTime;
			Crumbs.Native("FirstBlow march on");
			TASK.TASK_FOLLOW_NAV_MESH_TO_COORD(_peaceAggressor, _peaceCarryTo.X, _peaceCarryTo.Y, _peaceCarryTo.Z, 1f, -1, 1f, 0, 0f);
		}
		float num = law.Position.DistanceTo(player.Position);
		bool flag = num > 45f && HiddenFromView(player, him.Position + new Vector3(0f, 0f, 1f));
		if (flag || Game.GameTime - _peaceMarchAt >= 90000)
		{
			if (BelongsToUs(_peaceAggressor))
			{
				Crumbs.Native("FirstBlow cells");
				him.Delete();
			}
			GrudgeLog(string.Format("PEACE {0} marched off to the cells ({1:0} m from you, {2})", _peaceName, num, flag ? "out of sight" : "90 s"));
			EndPeace("marched off to the cells", clean: true);
		}
	}

	private void StartCarryOff(Ped him, Ped law, Ped player)
	{
		_peaceStep = 4;
		_peaceCarryAt = Game.GameTime;
		_peaceCarrying = false;
		Crumbs.Native("FirstBlow pick up");
		TASK.TASK_PICKUP_CARRIABLE_ENTITY(_peaceLaw, _peaceAggressor);
		Vector3 vector = him.Position - player.Position;
		vector.Z = 0f;
		if (vector.Length() < 0.5f)
		{
			vector = new Vector3(1f, 0f, 0f);
		}
		vector.Normalize();
		Vector3 vector2 = him.Position + vector * (70f + (float)_rng.NextDouble() * 20f);
		Vector3 safeCoordForPed = World.GetSafeCoordForPed(vector2);
		_peaceCarryTo = ((safeCoordForPed.X == 0f && safeCoordForPed.Y == 0f) ? vector2 : safeCoordForPed);
		GrudgeLog("PEACE the lawman picks " + _peaceName + " up to carry him off");
	}

	private void UpdateCarryOff(Ped him, Ped law, Ped player)
	{
		if (!ENTITY.DOES_ENTITY_EXIST(_peaceAggressor))
		{
			EndPeace("carried off", clean: true);
			return;
		}
		bool flag = ENTITY.IS_ENTITY_ATTACHED(_peaceAggressor);
		if (!_peaceCarrying)
		{
			if (flag)
			{
				_peaceCarrying = true;
				Crumbs.Native("FirstBlow carry off");
				TASK.TASK_FOLLOW_NAV_MESH_TO_COORD(_peaceLaw, _peaceCarryTo.X, _peaceCarryTo.Y, _peaceCarryTo.Z, 1f, -1, 1.5f, 0, 0f);
				ShowSubtitle("Lawman: " + (new string[3] { "Come on, you. A night in the cells'll cool you off.", "Let's go. The judge can sort you out.", "You're done for today." })[_rng.Next(3)]);
				GrudgeLog($"PEACE the lawman carries {_peaceName} off ({law.Position.DistanceTo(_peaceCarryTo):0} m to go)");
			}
			else if (Game.GameTime - _peaceCarryAt > 6000)
			{
				GrudgeLog("PEACE the lawman couldn't pick " + _peaceName + " up - he stays tied where he lies");
				EndPeace("arrested", clean: true);
			}
			return;
		}
		float num = law.Position.DistanceTo(player.Position);
		bool flag2 = num > 45f && HiddenFromView(player, law.Position + new Vector3(0f, 0f, 1f));
		if (!flag2 && Game.GameTime - _peaceCarryAt < 90000)
		{
			return;
		}
		if (BelongsToUs(_peaceAggressor))
		{
			Crumbs.Native("FirstBlow cells");
			ENTITY.DETACH_ENTITY(_peaceAggressor, p1: true, p2: true);
			Ped ped = new Ped(_peaceAggressor);
			if (ped.Exists())
			{
				ped.Delete();
			}
		}
		GrudgeLog(string.Format("PEACE {0} carried off to the cells ({1:0} m from you, {2})", _peaceName, num, flag2 ? "out of sight" : "90 s"));
		EndPeace("carried off to the cells", clean: true);
	}

	private bool YouKeptAtHim(Ped him, Ped law, Ped player)
	{
		int peaceAggressor = _peaceAggressor;
		if (_peaceBeatenAt == 0 && _fighters.TryGetValue(peaceAggressor, out var value) && (value.Broke || value.State == "fled" || value.State == "surrendered"))
		{
			_peaceBeatenAt = Game.GameTime;
		}
		if (_peaceBeatenAt == 0)
		{
			return false;
		}
		if (!_hitByYouAt.TryGetValue(peaceAggressor, out var value2) || value2 <= _peaceLastHitSeen || value2 < _peaceBeatenAt + 300)
		{
			return false;
		}
		_peaceLastHitSeen = value2;
		if (law.Position.DistanceTo(player.Position) > 40f || !ENTITY.HAS_ENTITY_CLEAR_LOS_TO_ENTITY(_peaceLaw, player.Handle, 17))
		{
			return false;
		}
		if (_peaceWarnedAt == 0)
		{
			_peaceWarnedAt = Game.GameTime;
			ShowSubtitle("Lawman: " + (new string[3] { "That's enough - he's done!", "Back off! He's had enough!", "Leave him be, mister - I've got him!" })[_rng.Next(3)]);
			GrudgeLog("PEACE you hit " + _peaceName + " after he was beaten - the lawman warns you");
			Feed("PEACE the lawman warned you off " + _peaceName, Theme.Warn);
			return false;
		}
		if (Game.GameTime - _peaceWarnedAt < 800)
		{
			return false;
		}
		GrudgeLog("PEACE you kept at " + _peaceName + " after the warning - the lawman comes for you");
		Feed("PEACE you wouldn't leave " + _peaceName + " be - the law comes for you", Theme.Blood);
		ShowSubtitle("Lawman: " + (new string[3] { "I warned you! You're under arrest!", "That's it - you're coming with me!", "Told you to back off. Hands up!" })[_rng.Next(3)]);
		Crumbs.Native("FirstBlow law arrests you");
		_lawOnYou = _peaceLaw;
		_lawOnYouAt = Game.GameTime;
		_lawOnYouCooldown = Game.GameTime + 90000;
		int peaceLaw = _peaceLaw;
		EndPeace("you kept hitting him", clean: false);
		TASK.TASK_ARREST_PED(peaceLaw, player.Handle);
		return true;
	}

	private void EndPeace(string why, bool clean)
	{
		GrudgeLog("PEACE over (" + why + ")" + (clean ? (" - the lawman saw " + _peaceName + " start it" + (_peaceBaited ? " (you baited him)" : "")) : ""));
		if (ENTITY.DOES_ENTITY_EXIST(_peaceLaw) && !IsOurs(_peaceLaw) && !GameOwned(new Ped(_peaceLaw)) && !PED.IS_PED_IN_COMBAT(_peaceLaw, 0))
		{
			Crumbs.Native("FirstBlow law released");
			TASK.CLEAR_PED_TASKS(_peaceLaw, p1: false, p2: false);
		}
		_peaceAggressor = 0;
		_peaceLaw = 0;
		_peaceStep = 0;
		_peaceCooldownUntil = Game.GameTime + 20000;
	}

	private void PollGamepad()
	{
		if (XPad.Log == null)
		{
			XPad.Log = GrudgeLog;
		}
		XPad.Poll();
		if (!XPad.Connected)
		{
			ReleasePadHeld();
			return;
		}
		if (_search != null)
		{
			_viewDownAt = 0;
			Keys? keys = null;
			if (XPad.Pressed(1))
			{
				keys = Keys.Up;
			}
			else if (XPad.Pressed(2))
			{
				keys = Keys.Down;
			}
			else if (XPad.Pressed(4))
			{
				keys = Keys.Left;
			}
			else if (XPad.Pressed(8))
			{
				keys = Keys.Right;
			}
			else if (XPad.Pressed(4096))
			{
				keys = Keys.Return;
			}
			else if (XPad.Pressed(8192))
			{
				keys = Keys.Escape;
			}
			else if (XPad.Pressed(16384))
			{
				keys = Keys.Back;
			}
			else if (XPad.Pressed(32768))
			{
				keys = Keys.Space;
			}
			else if (XPad.Pressed(512))
			{
				keys = Keys.Tab;
			}
			else if (XPad.Pressed(256))
			{
				keys = Keys.Q;
			}
			if (Math.Max(Math.Abs(XPad.LX), Math.Abs(XPad.LY)) > 0.6f)
			{
				if (!keys.HasValue && UiDraw.RealMs >= _nextStickMove)
				{
					_nextStickMove = UiDraw.RealMs + 180;
					Keys value;
					if (Math.Abs(XPad.LX) > Math.Abs(XPad.LY))
					{
						value = ((XPad.LX > 0f) ? Keys.Right : Keys.Left);
					}
					else
					{
						value = ((XPad.LY > 0f) ? Keys.Up : Keys.Down);
					}
					keys = value;
				}
			}
			else
			{
				_nextStickMove = 0;
			}
			if (keys.HasValue)
			{
				PadSearchKey(keys.Value);
			}
			return;
		}
		bool isOpen = _menu.IsOpen;
		bool viewerOpen = _bulletImpact.ViewerOpen;
		if (_iniPanel.IsOpen)
		{
			bool shift = XPad.Held(16384);
			if (XPad.Pressed(1))
			{
				_iniPanel.HandleKey(Keys.Up, shift);
			}
			if (XPad.Pressed(2))
			{
				_iniPanel.HandleKey(Keys.Down, shift);
			}
			if (XPad.Pressed(4))
			{
				_iniPanel.HandleKey(Keys.Left, shift);
			}
			if (XPad.Pressed(8))
			{
				_iniPanel.HandleKey(Keys.Right, shift);
			}
			if (XPad.Pressed(256))
			{
				_iniPanel.HandleKey(Keys.Q, shift);
			}
			if (XPad.Pressed(512))
			{
				_iniPanel.HandleKey(Keys.E, shift);
			}
			if (XPad.Pressed(8192))
			{
				_iniPanel.HandleKey(Keys.Back, shift);
			}
		}
		else if (_spawnMenuOpen)
		{
			if (XPad.Pressed(1))
			{
				SpawnMenuKey(Keys.Up);
			}
			if (XPad.Pressed(2))
			{
				SpawnMenuKey(Keys.Down);
			}
			if (XPad.Pressed(4096))
			{
				SpawnMenuKey(Keys.Return);
			}
			if (XPad.Pressed(8192))
			{
				SpawnMenuKey(Keys.Back);
			}
		}
		else if (_paperShown != null)
		{
			if (XPad.Pressed(4096) || XPad.Pressed(8192))
			{
				ClosePaper();
			}
		}
		else if (_welcome.InSetup)
		{
			if (XPad.Pressed(1))
			{
				_welcome.HandleKey(Keys.Up);
			}
			if (XPad.Pressed(2))
			{
				_welcome.HandleKey(Keys.Down);
			}
			if (XPad.Pressed(4))
			{
				_welcome.HandleKey(Keys.Left);
			}
			if (XPad.Pressed(8))
			{
				_welcome.HandleKey(Keys.Right);
			}
			if (XPad.Pressed(4096))
			{
				_welcome.HandleKey(Keys.Return);
			}
			if (XPad.Pressed(8192))
			{
				_welcome.HandleKey(Keys.Back);
			}
		}
		else if (_welcome.IsOpen)
		{
			if (XPad.Pressed(4) || XPad.Pressed(256))
			{
				_welcome.HandleKey(Keys.Left);
			}
			if (XPad.Pressed(8) || XPad.Pressed(512))
			{
				_welcome.HandleKey(Keys.Right);
			}
			if (XPad.Pressed(4096))
			{
				_welcome.HandleKey(Keys.Return);
			}
			if (XPad.Pressed(8192))
			{
				_welcome.HandleKey(Keys.Back);
			}
		}
		else if (_tg != null)
		{
			if (XPad.Pressed(1))
			{
				Dispatch(Keys.Up);
			}
			if (XPad.Pressed(2))
			{
				Dispatch(Keys.Down);
			}
			if (_tg.Page == "read" && XPad.Pressed(4))
			{
				Dispatch(Keys.Left);
			}
			if (_tg.Page == "read" && XPad.Pressed(8))
			{
				Dispatch(Keys.Right);
			}
			if (XPad.Pressed(4096))
			{
				Dispatch(Keys.Return);
			}
			if (XPad.Pressed(8192))
			{
				Dispatch(Keys.Back);
			}
		}
		else if (_convo != null)
		{
			_ = _convo;
			if (XPad.Pressed(1))
			{
				Dispatch(Keys.Up);
			}
			if (XPad.Pressed(2))
			{
				Dispatch(Keys.Down);
			}
			if (XPad.Pressed(4))
			{
				Dispatch(Keys.Left);
			}
			if (XPad.Pressed(8))
			{
				Dispatch(Keys.Right);
			}
			if (XPad.Pressed(4096))
			{
				Dispatch(Keys.Return);
			}
			if (XPad.Pressed(8192) && _convo != null)
			{
				Dispatch(Keys.Back);
			}
		}
		else if (!isOpen && !viewerOpen)
		{
			ReleasePadHeld();
			int padMenuOpen = Config.PadMenuOpen;
			if (padMenuOpen == 3)
			{
				if (Game.GameTime - _padHoldSeen > 250)
				{
					_padHoldSince = -1;
					_padHoldFired = XPad.Held(8);
				}
				_padHoldSeen = Game.GameTime;
				if (!XPad.Held(8))
				{
					_padHoldSince = -1;
					_padHoldFired = false;
				}
				else if (_padHoldSince < 0)
				{
					_padHoldSince = Game.GameTime;
				}
				else if (!_padHoldFired && Game.GameTime - _padHoldSince >= 800)
				{
					_padHoldFired = true;
					PadOpen();
				}
			}
			else if (padMenuOpen < 4 && XPad.Pressed(padMenuOpen switch
			{
				2 => (ushort)2, 
				1 => (ushort)4, 
				_ => (ushort)8, 
			}))
			{
				if (Game.GameTime - _lastRightTap <= 350)
				{
					_lastRightTap = -100000;
					PadOpen();
				}
				else
				{
					_lastRightTap = Game.GameTime;
				}
			}
		}
		else
		{
			if (XPad.Held(1) && _dpadUpSince == int.MaxValue)
			{
				return;
			}
			_dpadUpSince = -1;
			if (XPad.Pressed(1))
			{
				Dispatch(Keys.Up);
			}
			if (XPad.Pressed(2))
			{
				Dispatch(Keys.Down);
			}
			if (!viewerOpen && XPad.Pressed(4))
			{
				Dispatch(Keys.Left);
			}
			if (!viewerOpen && XPad.Pressed(8))
			{
				Dispatch(Keys.Right);
			}
			if (Math.Max(Math.Abs(XPad.LX), Math.Abs(XPad.LY)) > 0.6f && (!viewerOpen || !(Math.Abs(XPad.LX) > Math.Abs(XPad.LY))))
			{
				if (UiDraw.RealMs >= _nextStickMove)
				{
					_nextStickMove = UiDraw.RealMs + 180;
					NemesisMod nemesisMod = this;
					Keys key;
					if (Math.Abs(XPad.LX) > Math.Abs(XPad.LY))
					{
						key = ((XPad.LX > 0f) ? Keys.Right : Keys.Left);
					}
					else
					{
						key = ((XPad.LY > 0f) ? Keys.Up : Keys.Down);
					}
					nemesisMod.Dispatch(key);
				}
			}
			else
			{
				_nextStickMove = 0;
			}
			if (XPad.Pressed(4096))
			{
				Dispatch(Keys.Return);
			}
			if (XPad.Pressed(8192))
			{
				Dispatch(Keys.Back);
			}
			if (XPad.Pressed(32))
			{
				_viewDownAt = Environment.TickCount | 1;
			}
			if (_viewDownAt != 0)
			{
				if (!XPad.Held(32))
				{
					_viewDownAt = 0;
					Dispatch(Keys.Tab);
				}
				else if (Environment.TickCount - _viewDownAt > 600)
				{
					_viewDownAt = 0;
					OpenSearch(pad: true);
					return;
				}
			}
			if ((XPad.Pressed(16) & isOpen) && !viewerOpen)
			{
				OpenSetupScreen();
				return;
			}
			if (viewerOpen)
			{
				if (XPad.Pressed(16384))
				{
					Dispatch(Keys.Home);
				}
				if (XPad.Pressed(256))
				{
					Dispatch(Keys.Q);
				}
				if (XPad.Pressed(512))
				{
					Dispatch(Keys.E);
				}
				if (XPad.Pressed(32768))
				{
					Dispatch(Keys.Space);
				}
				if (XPad.Pressed(128))
				{
					Dispatch(Keys.R);
				}
				PadHold(XPad.RT > 0.4f, Keys.Z);
				PadHold(XPad.LT > 0.4f, Keys.X);
				if (XPad.RX != 0f || XPad.RY != 0f)
				{
					_bulletImpact.Orbit(XPad.RX * 140f * UiDraw.RealDt, XPad.RY * 90f * UiDraw.RealDt);
				}
				return;
			}
			ReleasePadHeld();
			if (XPad.Pressed(16384))
			{
				Dispatch(Keys.Home);
			}
			if (XPad.Pressed(32768))
			{
				Dispatch(Keys.R);
			}
			if (XPad.Pressed(256))
			{
				Dispatch(Keys.Q);
			}
			if (XPad.Pressed(512))
			{
				Dispatch(Keys.E);
			}
			if (XPad.Pressed(128))
			{
				Dispatch(Keys.C);
			}
			if (XPad.Pressed(64))
			{
				Dispatch(Keys.N);
			}
			TriggerTap(XPad.LT, ref _ltWas, Keys.OemMinus);
			TriggerTap(XPad.RT, ref _rtWas, Keys.Oemplus);
		}
		void PadOpen()
		{
			string text = PadMenuBlocked();
			if (text == null)
			{
				OpenLastTab();
			}
			else
			{
				GrudgeLog("MENU pad open blocked: " + text);
			}
		}
	}

	internal string PadMenuBlocked()
	{
		bool soft;
		return MenuBlocked(out soft);
	}

	internal string MenuBlocked(out bool soft)
	{
		soft = false;
		try
		{
			if (HUD.IS_PAUSE_MENU_ACTIVE())
			{
				return "pause menu";
			}
			Ped character = Game.Player.Character;
			if (character != null && character.Exists() && WorldBusy(character))
			{
				return "the game is busy (" + QuietWhy + ")";
			}
			if (!PLAYER.IS_PLAYER_CONTROL_ON(Game.Player.Handle))
			{
				return "no player control (catalog / cutscene)";
			}
			string[] catalogApps = CatalogApps;
			foreach (string text in catalogApps)
			{
				if (UIAPPS.IS_UIAPP_RUNNING(text))
				{
					return "the catalog is open (" + text + ")";
				}
			}
			if (UIAPPS.IS_ANY_UIAPP_RUNNING())
			{
				soft = true;
				return "a game screen is open (crafting / cooking / ...)";
			}
			if (INTERIOR.GET_INTERIOR_FROM_ENTITY(Game.Player.Character.Handle) != 0)
			{
				GrudgeLog($"MENU pad open indoors: any ui app active {UIAPPS.IS_ANY_UIAPP_ACTIVE()} running {UIAPPS.IS_ANY_UIAPP_RUNNING()}");
			}
		}
		catch
		{
		}
		return null;
	}

	private void TriggerTap(float value, ref bool was, Keys key)
	{
		bool flag = value > 0.5f;
		if (flag && !was)
		{
			Dispatch(key);
		}
		was = flag;
	}

	private void PadHold(bool down, Keys key)
	{
		if (down && _padHeld.Add(key))
		{
			Dispatch(key);
		}
		else if (!down && _padHeld.Remove(key))
		{
			_bulletImpact.HandleKeyUp(key);
		}
	}

	private void ReleasePadHeld()
	{
		foreach (Keys item in _padHeld)
		{
			_bulletImpact.HandleKeyUp(item);
		}
		_padHeld.Clear();
	}

	private static string WeatherKindOf(uint h)
	{
		if (WeatherKinds.Count == 0)
		{
			K("fog", new string[3] { "FOG", "MISTY", "WHITEOUT" });
			K("storm", new string[6] { "THUNDERSTORM", "HURRICANE", "THUNDER", "BLIZZARD", "GROUNDBLIZZARD", "SANDSTORM" });
			K("rain", new string[5] { "RAIN", "DRIZZLE", "SHOWER", "SLEET", "HAIL" });
			K("snow", new string[2] { "SNOW", "SNOWLIGHT" });
			K("clear", new string[6] { "SUNNY", "CLOUDS", "OVERCAST", "OVERCASTDARK", "HIGHPRESSURE", "SNOWCLEARING" });
		}
		if (!WeatherKinds.TryGetValue(h, out var value))
		{
			return "clear";
		}
		return value;
		static void K(string kind, string[] names)
		{
			foreach (string p in names)
			{
				WeatherKinds[MISC.GET_HASH_KEY(p)] = kind;
			}
		}
	}

	private unsafe void UpdateWeather()
	{
		if (Game.GameTime < _nextWeather)
		{
			return;
		}
		_nextWeather = Game.GameTime + 5000;
		uint num = 0u;
		uint num2 = 0u;
		float num3 = 0f;
		MISC.GET_CURR_WEATHER_STATE(&num, &num2, &num3);
		uint num4 = ((num3 >= 0.5f && num2 != 0) ? num2 : num);
		if (num4 != _weatherHash)
		{
			_weatherHash = num4;
			string weather = _weather;
			_weather = WeatherKindOf(num4);
			if (weather != _weather)
			{
				GrudgeLog($"GAMESYS weather {weather} -> {_weather} (0x{num4:X8})");
			}
		}
	}

	internal float WeatherSightMult()
	{
		if (!Config.GsWeather)
		{
			return 1f;
		}
		switch (_weather)
		{
		case "fog":
			return 0.55f;
		case "storm":
			return 0.65f;
		case "rain":
		case "snow":
			return 0.8f;
		default:
			return 1f;
		}
	}

	internal float WeatherTensionMult()
	{
		if (!Config.GsWeather || !(_weather == "storm"))
		{
			return 1f;
		}
		return 0.7f;
	}

	internal void ApplyMindAi(Ped ped, NemesisRecord rec)
	{
		if (!Config.GsMinds || ped == null || !ped.Exists() || rec == null)
		{
			return;
		}
		try
		{
			Ped character = Game.Player.Character;
			float num = Math.Min(1f, (float)EffectiveFear(rec) / 100f);
			float num2 = Math.Min(1f, (float)rec.Hate / 100f);
			float num3 = (float)Mind.F(rec, "Bravery") / 100f;
			Function.Call(491572505205262965uL, ped.Handle, 1, num, 0);
			Function.Call(491572505205262965uL, ped.Handle, 2, num2, character.Handle);
			Function.Call(491572505205262965uL, ped.Handle, 7, num3, 0);
			string text = null;
			if (rec.Personality == Personality.Hothead || (rec.TraitsRolled && rec.Aggression >= 75))
			{
				text = "ChargeAttack";
			}
			else if (rec.Personality == Personality.Coward && Loadout.BandOf(rec) == Loadout.Band.Gun)
			{
				text = "StrafeOnly_Low";
			}
			if (text != null)
			{
				Function.Call(10001374397760965212uL, ped.Handle, MISC.GET_HASH_KEY(text), 1, -1f);
			}
			if (Quirks.Has(rec, "drunk"))
			{
				int cLOCK_HOURS = CLOCK.GET_CLOCK_HOURS();
				Function.Call(4642313281418361555uL, ped.Handle, true, (cLOCK_HOURS >= 20 || cLOCK_HOURS < 4) ? 0.5f : 0.25f);
			}
			if (_mindAiLogged++ < 20)
			{
				GrudgeLog(string.Format("GAMESYS mind AI {0}: fear {1:0.00}, anger {2:0.00}, brave {3:0.00}{4}{5}", rec.Name, num, num2, num3, (text != null) ? (", style " + text) : "", Quirks.Has(rec, "drunk") ? ", drunk" : ""));
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("GAMESYS mind AI failed: " + ex.Message);
		}
	}

	internal void TauntEmote(Ped ped, NemesisRecord rec)
	{
		if (Config.GsBody && !(ped == null) && ped.Exists() && !ped.IsOnMount)
		{
			uint[] array = ((rec != null && rec.Personality.HasValue && TauntEmotes.TryGetValue(rec.Personality.Value, out var value)) ? value : TauntEmotes[Personality.Proud]);
			uint num = array[_rng.Next(array.Length)];
			Function.Call(12905671096162301951uL, ped.Handle, 2, 0, num, false, true, false, false, false);
		}
	}

	internal void BackDownEmote(Ped ped)
	{
		if (Config.GsBody && !(ped == null) && ped.Exists() && !ped.IsOnMount)
		{
			uint num = ((_rng.Next(2) == 0) ? 772373429u : 3472337526u);
			Function.Call(12905671096162301951uL, ped.Handle, 0, 0, num, false, true, false, false, false);
		}
	}

	private void InterroFace()
	{
		if (Config.GsBody && _convo?.It != null)
		{
			Interrogation it = _convo.It;
			if (!(it.Ped == null) && it.Ped.Exists() && !it.Ped.IsDead)
			{
				uint num;
				if (it.Terror >= 75f)
				{
					num = MoodPanic;
				}
				else if (it.Terror >= 50f)
				{
					num = MoodScared;
				}
				else if (it.Terror >= 25f)
				{
					num = MoodNervous;
				}
				else if (it.Temper == Personality.Proud)
				{
					num = MoodSmug;
				}
				else
				{
					num = ((it.Temper == Personality.Hothead || it.Temper == Personality.Greedy) ? MoodCocky : MoodAngry);
				}
				Function.Call(10032737698875811003uL, it.Ped.Handle, num, 6);
			}
		}
	}

	private void Music(string cue, string why)
	{
		if (Config.GsMusic && cue != null && !(cue == _music) && (!MISC.GET_MISSION_FLAG() || !(cue != "MC_MUSIC_STOP")))
		{
			try
			{
				Crumbs.Mark("music " + cue);
				FlushGrudgeLog(force: true);
				Function.Call<bool>(2184674316064724362uL, new InputArgument[1] { UiDraw.CString(cue) });
				bool flag = Function.Call<bool>(8101227722246563600uL, new InputArgument[1] { UiDraw.CString(cue) });
				GrudgeLog("GAMESYS music " + cue + " (" + why + ")" + (flag ? "" : " - the game didn't take it"));
			}
			catch (Exception ex)
			{
				GrudgeLog("GAMESYS music failed: " + ex.Message);
			}
			_music = ((cue == "MC_MUSIC_STOP" || cue.EndsWith("_STOP") || cue.EndsWith("_END_OS")) ? null : cue);
			_musicStopAt = -1;
		}
	}

	private void MusicStopSoon(int ms)
	{
		if (_music != null && _musicStopAt < 0)
		{
			_musicStopAt = Game.GameTime + ms;
		}
	}

	internal void MusicStandoff()
	{
		Music("DUEL_GENERAL_START", "standoff");
	}

	internal void MusicStandoffBroke()
	{
		if (_music == "DUEL_GENERAL_START")
		{
			Music("DUEL_GENERAL_DRAW", "the standoff broke");
		}
	}

	internal void MusicStandoffOver()
	{
		if (_music != null && _music.StartsWith("DUEL_GENERAL"))
		{
			Music("DUEL_GENERAL_STOP", "he backed down");
		}
	}

	private void UpdateMusic(Ped player)
	{
		if (!Config.GsMusic)
		{
			return;
		}
		if (MISC.GET_MISSION_FLAG() || player.IsDead)
		{
			if (_music != null)
			{
				Music("MC_MUSIC_STOP", "mission / death");
			}
			return;
		}
		if (_musicStopAt >= 0 && Game.GameTime >= _musicStopAt)
		{
			Music("MC_MUSIC_STOP", "cue over");
			return;
		}
		if (_music != null && _music.StartsWith("DUEL_GENERAL") && _enc == null && _musicStopAt < 0)
		{
			Music("DUEL_GENERAL_END_OS", "the encounter is over");
			return;
		}
		Vector3 pos = player.Position;
		LiveCamp liveCamp = (from lc in _liveCamps.Values
			where lc.Boss != null && lc.Boss.CampKnown
			orderby SitePos(lc.Site).DistanceTo(pos)
			select lc).FirstOrDefault();
		float num = ((liveCamp != null) ? SitePos(liveCamp.Site).DistanceTo(pos) : 9999f);
		if (liveCamp != null && liveCamp.Engaged && liveCamp.Peds.Any((Ped p) => p.Exists() && !p.IsDead) && num < 200f)
		{
			Music("SP_HIDEOUTS_GENERAL_ACTION", liveCamp.Boss.Name + "'s camp is fighting");
		}
		else if (liveCamp != null && liveCamp.Cleared && _music != null && _music.StartsWith("SP_HIDEOUTS"))
		{
			MusicStopSoon(6000);
		}
		else if (liveCamp != null && !liveCamp.Engaged && num < 90f && (_music == null || _music.StartsWith("SP_HIDEOUTS")))
		{
			Music("SP_HIDEOUTS_GENERAL_IDLE", "creeping up on " + liveCamp.Boss.Name + "'s camp");
		}
		else if (_music != null && _music.StartsWith("SP_HIDEOUTS") && num > 160f)
		{
			MusicStopSoon(6000);
		}
	}

