	private void NoDeed(int h, string why)
	{
		if (_reDeeds.TryGetValue(h, out var value) && !value.Done)
		{
			value.Done = true;
			GrudgeLog("DEED roadside " + WhoIs(h) + ": " + why + " - no deed");
		}
	}

	private bool PlayedOut(ReDeed rd, Ped p)
	{
		if (p.Position.DistanceTo(rd.MetPos) > 8f)
		{
			return true;
		}
		if (!rd.Owned)
		{
			return false;
		}
		try
		{
			return ScriptOf(p.Handle) == null;
		}
		catch
		{
			return false;
		}
	}

	private string DeedTown(Vector3 at)
	{
		string result = null;
		float num = float.MaxValue;
		foreach (string repTown in RepTowns)
		{
			if (TownCore(repTown, out var centre, out var radius))
			{
				float num2 = new Vector3(at.X - centre.X, at.Y - centre.Y, 0f).Length() - radius;
				if (num2 < num)
				{
					num = num2;
					result = repTown;
				}
			}
		}
		if (!(num <= 1500f))
		{
			return null;
		}
		return result;
	}

	internal (string town, float add) GoodDeed(Vector3 at, string what, float weight = 1f, string kind = null)
	{
		try
		{
			string text = DeedTown(at);
			if (text == null)
			{
				GrudgeLog("DEED " + what + ": no town near enough to hear of it");
				return (town: null, add: 0f);
			}
			int num = GameDayKey();
			string key = text + "|" + num;
			string text2 = ((kind == null) ? null : (text + "|" + kind + "|" + num));
			_deedsToday.TryGetValue(key, out var value);
			int value2 = 0;
			if (text2 != null)
			{
				_deedsToday.TryGetValue(text2, out value2);
			}
			if (value >= 6 || (text2 != null && value2 >= 2))
			{
				GrudgeLog("DEED " + text + ": " + what + " - the town has heard enough for today");
				return (town: null, add: 0f);
			}
			if (_deedsToday.Count > 200)
			{
				_deedsToday.Clear();
			}
			_deedsToday[key] = value + 1;
			if (text2 != null)
			{
				_deedsToday[text2] = value2 + 1;
			}
			Dictionary<string, TownTalk> dictionary = Chronicle.TownWord ?? (Chronicle.TownWord = new Dictionary<string, TownTalk>());
			if (!dictionary.TryGetValue(text, out var value3))
			{
				value3 = (dictionary[text] = new TownTalk());
			}
			float num2 = (TownCore(text, out var _, out var radius) ? Math.Max(1f, radius / 130f * (radius / 130f)) : 1f);
			float num3 = 5f * weight / (float)Math.Sqrt(num2);
			int num4 = TownReputation(text);
			value3.Good = Math.Min(30f, value3.Good + num3);
			_townRepCache.Remove(text);
			SaveWorld();
			int num5 = TownReputation(text);
			ShowNotification("Word gets around " + text + " - " + what + ".");
			GrudgeLog($"DEED {text}: {what} (+{num3:0.0} good word, now {value3.Good:0.0}; reputation {num4:+0;-0;0} -> {num5:+0;-0;0})");
			Feed($"GOOD WORD {text}: {what} - reputation {num4:+0;-0;0} -> {num5:+0;-0;0}", Theme.Good);
			string key2 = text + "|" + what;
			long num6 = GameMinutesNow();
			bool num7 = _deedLineAt.TryGetValue(key2, out var value4) && num6 >= value4 && num6 - value4 < 120;
			_deedLineAt[key2] = num6;
			if (num7)
			{
				GrudgeLog("DEED " + text + ": " + what + " - the same fight, one World tab line");
			}
			else
			{
				try
				{
					ChronicleDeed("good", char.ToUpperInvariant(what[0]) + what.Substring(1), "word got around " + text, at, null);
				}
				catch
				{
				}
			}
			return (town: text, add: num3);
		}
		catch (Exception ex)
		{
			GrudgeLog("DEED failed: " + ex.Message);
			return (town: null, add: 0f);
		}
	}

	private static bool HandleKey(string key, out int handle)
	{
		handle = 0;
		if (key != null && key.Length > 1 && key[0] == 'h')
		{
			return int.TryParse(key.Substring(1), out handle);
		}
		return false;
	}

	internal void NoteMercyDeed(string key, Gang g, int notorietyTaken, (string town, float add) d)
	{
		if (key == null || (notorietyTaken <= 0 && (d.town == null || d.add <= 0f)))
		{
			return;
		}
		long now = GameMinutesNow();
		foreach (string item in (from kv in MercyNotes
			where now - kv.Value.At > 1440 || now < kv.Value.At
			select kv.Key).ToList())
		{
			MercyNotes.Remove(item);
		}
		MercyNote mercyNote = new MercyNote
		{
			Gang = g?.Id,
			Notoriety = Math.Max(0, notorietyTaken)
		};
		object town;
		if (d.add > 0f)
		{
			(town, _) = d;
		}
		else
		{
			town = null;
		}
		mercyNote.Town = (string)town;
		mercyNote.Good = Math.Max(0f, d.add);
		mercyNote.At = now;
		MercyNote mercyNote2 = mercyNote;
		if (HandleKey(key, out var handle))
		{
			try
			{
				mercyNote2.Model = ENTITY.GET_ENTITY_MODEL(handle);
			}
			catch
			{
			}
			_mercyHandleNotes[key] = mercyNote2;
		}
		else
		{
			MercyNotes[key] = mercyNote2;
			SaveWorld();
		}
	}

	internal void MercyTakenBack(string key)
	{
		if (key == null)
		{
			return;
		}
		MercyNote value;
		if (HandleKey(key, out var handle))
		{
			if (!_mercyHandleNotes.TryGetValue(key, out value))
			{
				return;
			}
			_mercyHandleNotes.Remove(key);
			uint num = 0u;
			try
			{
				num = ENTITY.GET_ENTITY_MODEL(handle);
			}
			catch
			{
			}
			if (value.Model != 0 && num != 0 && num != value.Model)
			{
				return;
			}
		}
		else
		{
			if (!MercyNotes.TryGetValue(key, out value))
			{
				return;
			}
			MercyNotes.Remove(key);
			SaveWorld();
		}
		long num2 = GameMinutesNow();
		if (num2 - value.At > 1440 || num2 < value.At)
		{
			return;
		}
		if (value.Notoriety > 0)
		{
			Gang gang = Gangs.ById(value.Gang);
			if (gang != null)
			{
				int num3 = NotorietyOf(gang);
				int num4 = num3 + value.Notoriety;
				Config.Notoriety[gang.Id] = num4;
				Config.Save();
				GrudgeLog($"NOTORIETY {gang.Id} {num3} -> {num4} (you killed a man you'd let go - the mercy is taken back)");
				Feed($"NOTORIETY {gang.Name} {num3} -> {num4} (killed a man you'd spared)", Theme.Warn);
			}
		}
		if (value.Town != null && value.Good > 0f && Chronicle.TownWord != null && Chronicle.TownWord.TryGetValue(value.Town, out var value2))
		{
			value2.Good = Math.Max(0f, value2.Good - value.Good);
			_townRepCache.Remove(value.Town);
			GrudgeLog($"DEED {value.Town}: you killed a man you'd spared - the good word is taken back (-{value.Good:0.0}, now {value2.Good:0.0})");
		}
	}

	private void TrackRoadsideDeeds(Ped player, int target)
	{
		Vector3 position = player.Position;
		int num = -1;
		try
		{
			num = MONEY._MONEY_GET_CASH_BALANCE();
		}
		catch
		{
		}
		bool flag = _deedCash >= 0 && num >= 0 && num < _deedCash && _deedCash - num <= 5000;
		_deedCash = num;
		if (_reDeeds.Count == 0)
		{
			return;
		}
		List<Ped> list = null;
		foreach (KeyValuePair<int, ReDeed> item in _reDeeds.ToList())
		{
			int key = item.Key;
			ReDeed value = item.Value;
			if (value.Done)
			{
				continue;
			}
			if (!ENTITY.DOES_ENTITY_EXIST(key) || ENTITY.IS_ENTITY_DEAD(key))
			{
				value.Done = true;
				continue;
			}
			Ped ped = new Ped(key);
			float num2 = ped.Position.DistanceTo(position);
			if (PED.IS_PED_IN_COMBAT(key, player.Handle))
			{
				value.Done = true;
				GrudgeLog("DEED roadside " + WhoIs(key) + ": turned on you - no deed");
				continue;
			}
			if (ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(key, player.Handle, p2: true, p3: true))
			{
				NoDeed(key, "you hurt them");
				continue;
			}
			if (target == key && num2 < 8f)
			{
				value.TalkMs += 1000;
			}
			if (value.Kind == "rescue" && num2 < 60f)
			{
				list = list ?? PedsAround(player);
				foreach (Ped item2 in list)
				{
					if (!(item2 == null) && item2.Exists() && item2.IsDead && item2.Handle != key && !_deedKillsSeen.Contains(item2.Handle) && !(item2.Position.DistanceTo(ped.Position) > 35f) && PED.GET_PED_SOURCE_OF_DEATH(item2.Handle) == player.Handle)
					{
						_deedKillsSeen.Add(item2.Handle);
						value.Kills++;
					}
				}
			}
			string text = (Woman(ped) ? "woman" : "man");
			string text2 = null;
			bool flag2 = value.TalkMs >= 2000 && num2 < 60f && Game.GameTime - value.MetAt > 10000 && PlayedOut(value, ped);
			if ((value.Kind == "help") & flag2)
			{
				text2 = "you helped a " + text + " in trouble (" + value.Note + ")";
			}
			else if (value.Kind == "rescue" && ((value.Kills > 0) | flag2) && Game.GameTime - value.MetAt > 4000)
			{
				if (value.Note.StartsWith("kidnapped"))
				{
					text2 = "you saved a kidnapped " + text;
				}
				else
				{
					text2 = (value.Note.StartsWith("held hostage") ? "you freed a hostage" : ("you came to the aid of a " + text + " (" + value.Note + ")"));
				}
			}
			else if (value.Kind == "escort" && value.TalkMs >= 2000 && Game.GameTime - value.MetAt > 90000 && num2 < 40f)
			{
				text2 = "you saw a " + text + " safely on " + ((text == "woman") ? "her" : "his") + " way";
			}
			else if (((value.Kind == "charity") & flag) && num2 < 4f)
			{
				text2 = "you gave a " + text + " some money";
			}
			if (text2 == null)
			{
				if ((value.Kind == "help" || value.Kind == "rescue") && num2 > 60f)
				{
					NoDeed(key, "you left before it played out");
				}
				else if (Game.GameTime - value.MetAt > 600000 || num2 > 300f)
				{
					value.Done = true;
				}
			}
			else
			{
				value.Done = true;
				GoodDeed(ped.Position, text2, value.Weight, (value.Kind == "charity") ? "charity" : null);
			}
		}
		if (_reDeeds.Count > 60)
		{
			foreach (int item3 in (from x in _reDeeds
				where x.Value.Done
				select x.Key).ToList())
			{
				_reDeeds.Remove(item3);
			}
		}
		if (_deedKillsSeen.Count > 400)
		{
			_deedKillsSeen.Clear();
		}
	}

	private void WatchRoadsideDeed(int h, string modelLower, string note)
	{
		if (_reDeeds.ContainsKey(h))
		{
			return;
		}
		string text;
		if (ReHelpTokens.Any(modelLower.Contains))
		{
			text = "help";
		}
		else if (ReRescueTokens.Any(modelLower.Contains))
		{
			text = "rescue";
		}
		else if (modelLower.Contains("escort"))
		{
			text = "escort";
		}
		else
		{
			text = (ReCharityTokens.Any(modelLower.Contains) ? "charity" : null);
		}
		if (text != null)
		{
			bool owned = false;
			try
			{
				owned = ScriptOf(h) != null;
			}
			catch
			{
			}
			_reDeeds[h] = new ReDeed
			{
				Kind = text,
				Note = (note ?? "in trouble"),
				MetAt = Game.GameTime,
				Weight = ((text == "charity") ? 0.6f : 1f),
				MetPos = new Ped(h).Position,
				Owned = owned
			};
			GrudgeLog("DEED roadside: watching " + WhoIs(h) + " (" + text + ": " + note + ")");
		}
	}

	private void NoteTownDefence(Gang g, Vector3 where)
	{
		if (g != null && !g.OrdersNotFeelings && !g.StoryOnly && InsideAnyTown(where))
		{
			int num;
			try
			{
				num = BountyDollars;
			}
			catch
			{
				num = 1;
			}
			if (num <= 0 && PLAYER.GET_PLAYER_WANTED_LEVEL(Game.Player.Handle) <= 0 && _combatants.Values.Any((int t) => Game.GameTime - t < 15000))
			{
				GoodDeed(where, "you saw off the " + ShortOutfit(g) + " in town", 0.6f, "defence");
			}
		}
	}

	internal int LowerNotoriety(Gang g, int amount, string why, string kind = null, int cap = 0, bool byWire = false)
	{
		if (g == null || amount <= 0 || g.StoryOnly)
		{
			return 0;
		}
		if (!byWire)
		{
			try
			{
				if (PlayerMasked(Game.Player.Character))
				{
					GrudgeLog("NOTORIETY " + g.Id + ": " + why + " - masked, they don't know it was you");
					return 0;
				}
			}
			catch
			{
			}
		}
		int num = NotorietyOf(g);
		if (num <= 0)
		{
			return 0;
		}
		if (kind != null && cap > 0)
		{
			string key = $"{g.Id}|{kind}|{GameDayKey()}";
			_goodwillToday.TryGetValue(key, out var value);
			amount = Math.Min(amount, cap - value);
			if (amount <= 0)
			{
				GrudgeLog("NOTORIETY " + g.Id + ": " + why + " - no more " + kind + " counts today");
				return 0;
			}
			_goodwillToday[key] = value + amount;
		}
		int num2 = Math.Max(0, num - amount);
		Config.Notoriety[g.Id] = num2;
		Config.Save();
		GrudgeLog($"NOTORIETY {g.Id} {num} -> {num2} ({why})");
		Feed($"NOTORIETY {g.Name} {num} -> {num2} ({why})", Theme.Good);
		return num - num2;
	}

	internal void NoteMercy(Gang g, string who, string id = null)
	{
		if (g != null && !g.StoryOnly)
		{
			string key = id ?? who ?? "?";
			int num = GameDayKey();
			if (!_mercyDay.TryGetValue(key, out var value) || value != num)
			{
				_mercyDay[key] = num;
				int notorietyTaken = LowerNotoriety(g, 2, "you let " + (who ?? "one of their men") + " go", "mercy", 6);
				NoteMercyDeed(key, g, notorietyTaken, GoodDeed(Game.Player.Character.Position, "you showed mercy to one of the " + ShortOutfit(g), 0.6f, "mercy"));
			}
		}
	}

	private void NoteEnemyHurt(Gang victim, int rank)
	{
		if (victim == null || victim.StoryOnly)
		{
			return;
		}
		float num = ((rank >= 4) ? 1f : 0.25f);
		foreach (Gang item in Gangs.All.Where((Gang x) => x != victim && !x.StoryOnly && !IsDestroyed(x) && NotorietyOf(x) > 0))
		{
			if (Relation(item.Id, victim.Id) <= Config.ClashLine)
			{
				_enemyGoodwill.TryGetValue(item.Id, out var value);
				value += num;
				int num2 = (int)value;
				_enemyGoodwill[item.Id] = value - (float)num2;
				if (num2 > 0)
				{
					LowerNotoriety(item, num2, "you've been killing men of the " + victim.Name, "enemies", 5);
				}
			}
		}
	}

	internal void NoteGreetScene(int handle)
	{
		if (_greetScenes.ContainsKey(handle) || !ENTITY.DOES_ENTITY_EXIST(handle) || ENTITY.IS_ENTITY_DEAD(handle) || IsOurs(handle))
		{
			return;
		}
		Ped ped = new Ped(handle);
		if (!ped.IsHuman || ped.IsPlayer)
		{
			return;
		}
		bool flag = PED.IS_PED_USING_ANY_SCENARIO(handle);
		int num = 0;
		if (flag)
		{
			try
			{
				num = TASK._GET_SCENARIO_POINT_PED_IS_USING(handle, p1: true);
			}
			catch
			{
			}
		}
		string text = ((_named.TryGetValue(handle, out var value) && !string.IsNullOrEmpty(value.Name)) ? value.Name : $"ped {handle}");
		string text2 = null;
		try
		{
			text2 = ScriptOf(handle);
		}
		catch
		{
		}
		bool flag2 = AtTableGame(handle);
		bool flag3 = !flag && ENTITY.GET_ENTITY_SPEED(handle) < 0.3f;
		_greetScenes[handle] = new GreetScene
		{
			Name = text,
			Female = !PED.IS_PED_MALE(handle),
			Busy = flag,
			Point = num,
			Start = Game.GameTime,
			At = ped.Position,
			Still = flag3,
			Script = text2,
			Table = flag2
		};
		string text3 = ((text2 != null) ? (" - run by the game's script '" + text2 + "'" + (flag2 ? ", a table game" : "")) : " - no game script runs him");
		if (flag)
		{
			GrudgeLog(Pron.Her("GREETSCENE " + text + ": greeted " + ((num != 0) ? "in an activity on a spot" : "in an activity where he stood") + text3 + " [" + BusyNote(handle) + "]", !PED.IS_PED_MALE(handle)));
		}
		else if (flag3)
		{
			GrudgeLog(Pron.Her("GREETSCENE " + text + ": greeted standing still or seated, NOT in an activity" + text3 + " - watching 8 s", !PED.IS_PED_MALE(handle)));
		}
	}

	private void UpdateGreetScenes(Ped player)
	{
		if (_greetScenes.Count == 0 || Game.GameTime < _nextGreetScenes)
		{
			return;
		}
		_nextGreetScenes = Game.GameTime + 500;
		foreach (KeyValuePair<int, GreetScene> item in _greetScenes.ToList())
		{
			int key = item.Key;
			GreetScene value = item.Value;
			int num = Game.GameTime - value.Start;
			if (!ENTITY.DOES_ENTITY_EXIST(key) || ENTITY.IS_ENTITY_DEAD(key) || num > 75000)
			{
				_greetScenes.Remove(key);
				continue;
			}
			Ped ped = new Ped(key);
			if (!value.Busy)
			{
				if (!value.Still)
				{
					_greetScenes.Remove(key);
					continue;
				}
				Vector3 position = ped.Position;
				float num2 = position.Z - value.At.Z;
				float num3 = new Vector3(position.X - value.At.X, position.Y - value.At.Y, 0f).Length();
				if (num2 > 0.25f || num3 > 1f)
				{
					GrudgeLog(Pron.Her(string.Format("GREETSCENE {0}: got up {1:0.0} s after the greeting (rose {2:0.00} m, {3:0.0} m from his place{4}{5}{6})", value.Name, (double)num / 1000.0, num2, num3, (value.Script != null) ? (", script '" + value.Script + "'") : "", PED.IS_PED_FLEEING(key) ? ", fleeing" : "", PED.IS_PED_USING_ANY_SCENARIO(key) ? ", into an activity" : ""), value.Female));
					_greetScenes.Remove(key);
				}
				else if (num > 8000)
				{
					GrudgeLog(Pron.Her("GREETSCENE " + value.Name + ": stayed put 8 s on (not in an activity)", value.Female));
					_greetScenes.Remove(key);
				}
				continue;
			}
			bool flag = PED.IS_PED_USING_ANY_SCENARIO(key);
			if (!value.Left)
			{
				if (!flag)
				{
					value.Left = true;
					value.RestoreAt = Game.GameTime + 15000;
					GrudgeLog(Pron.Her($"GREETSCENE {value.Name}: left his activity {(double)num / 1000.0:0.0} s after the greeting", value.Female));
					continue;
				}
				if (!value.Checked && num >= 3000)
				{
					value.Checked = true;
					GrudgeLog(Pron.Her("GREETSCENE " + value.Name + ": still in his activity 3 s on", value.Female));
				}
				if (num > 8000)
				{
					_greetScenes.Remove(key);
				}
			}
			else if (!value.Restored)
			{
				if (Game.GameTime < value.RestoreAt)
				{
					continue;
				}
				string text;
				if (flag)
				{
					text = "went back to it by himself";
				}
				else if (Config.TownsfolkReactions)
				{
					if (value.Table || AtTableGame(key))
					{
						text = "a card player - the table's script has him";
					}
					else if (PED.IS_PED_FLEEING(key))
					{
						text = "he's fleeing";
					}
					else if (PED.IS_PED_IN_COMBAT(key, 0))
					{
						text = "he's fighting";
					}
					else if (ped.IsInVehicle || ped.IsOnMount)
					{
						text = "he's riding";
					}
					else if (ENTITY.GET_ENTITY_SPEED(key) > 2.2f)
					{
						text = "he's running";
					}
					else if (ped.Position.DistanceTo(value.At) > 15f)
					{
						text = "he's gone on his way";
					}
					else
					{
						text = (IsOurs(key) ? "the mod has him now" : null);
					}
				}
				else
				{
					text = "townsfolk reactions are off";
				}
				if (text != null)
				{
					GrudgeLog(Pron.Her("GREETSCENE " + value.Name + ": not put back - " + text, value.Female));
					_greetScenes.Remove(key);
					continue;
				}
				if (Function.Call<bool>(7006499128492128287uL, new InputArgument[1] { key }))
				{
					if (num > 60000)
					{
						GrudgeLog(Pron.Her("GREETSCENE " + value.Name + ": not put back - always in your sight", value.Female));
						_greetScenes.Remove(key);
					}
					continue;
				}
				Crumbs.Native("greet scene: back to it");
				NoteSeatTask();
				if (value.Point != 0)
				{
					TASK.TASK_USE_SCENARIO_POINT(key, value.Point, "", -1, p4: true, p5: false, 0u, p7: false, -1f, p9: true);
				}
				else
				{
					TASK.TASK_USE_NEAREST_SCENARIO_TO_COORD_WARP(key, value.At.X, value.At.Y, value.At.Z, 2f, -1, p6: true, p7: false, p8: false, p9: false);
				}
				value.Restored = true;
				value.RestoreAt = Game.GameTime + 8000;
				GrudgeLog(Pron.Her(string.Format("GREETSCENE {0}: put back {1} ({2:0.0} m from it)", value.Name, (value.Point != 0) ? "on his spot" : "into the nearest activity where he was", ped.Position.DistanceTo(value.At)), value.Female));
			}
			else if (flag || Game.GameTime >= value.RestoreAt)
			{
				GrudgeLog(Pron.Her("GREETSCENE " + value.Name + ": " + (flag ? "back in his activity" : "didn't take - left as he is"), value.Female));
				_greetScenes.Remove(key);
			}
		}
	}

	internal List<Ped> GroupOf(Ped target, bool allowDead = false)
	{
		List<Ped> list = new List<Ped>();
		if (target == null || !target.Exists() || (target.IsDead && !allowDead) || !target.IsHuman)
		{
			return list;
		}
		bool flag = !target.IsDead && PED.IS_PED_USING_ANY_SCENARIO(target.Handle);
		Ped character = Game.Player.Character;
		Vector3 tp = target.Position;
		Vector3 vector = ENTITY.GET_ENTITY_VELOCITY(target.Handle, 0);
		bool flag2 = IsLawman(target);
		int num = (PED.IS_PED_IN_GROUP(target.Handle) ? PED.GET_PED_GROUP_INDEX(target.Handle) : (-1));
		_ = target.Heading;
		List<(Ped p, Vector3 pos)> list2 = PedSnapshot(character);
		bool flag3 = Enumerable.Count(list2, ((Ped p, Vector3 pos) s) => s.p != null && s.p.Handle != target.Handle && (s.pos - tp).Length() < 6f) >= 5;
		_togetherAt.TryGetValue(target.Handle, out var value);
		foreach (var (ped, vector2) in list2)
		{
			if (ped == null || ped.Handle == target.Handle || (vector2 - tp).Length() > 6f || !ped.Exists() || ped.IsPlayer || !ped.IsHuman || ped.IsDead)
			{
				continue;
			}
			float num2 = ped.Position.DistanceTo(tp);
			if (num2 > 5f || Kids.IsChild(ped) || IsStoryPed(ped) || IsPlaced(ped.Handle) || GameOwned(ped) || IsLawman(ped) != flag2 || OppositeSides(target, ped))
			{
				continue;
			}
			bool flag4 = num != -1 && PED.IS_PED_IN_GROUP(ped.Handle) && PED.GET_PED_GROUP_INDEX(ped.Handle) == num;
			if (!flag4 && num2 < 3f && PED.IS_PED_USING_ANY_SCENARIO(ped.Handle) && (flag || target.IsDead))
			{
				flag4 = true;
			}
			if (!flag4 && target.IsDead)
			{
				flag4 = num2 < 2.2f && ENTITY.GET_ENTITY_VELOCITY(ped.Handle, 0).Length() < 1.5f;
			}
			if (!flag4)
			{
				Vector3 vector3 = ENTITY.GET_ENTITY_VELOCITY(ped.Handle, 0);
				float num3 = vector.Length();
				float num4 = vector3.Length();
				bool flag5 = value?.ContainsKey(ped.Handle) ?? false;
				if (num3 < 0.5f && num4 < 0.5f && num2 < 3.2f)
				{
					flag4 = ((!flag3) ? (num2 < 1.8f || Facing(ped, tp) || Facing(target, ped.Position)) : ((Facing(ped, tp) && Facing(target, ped.Position)) || (flag5 && num2 < 2.5f)));
				}
				else if (num3 > 0.5f && num4 > 0.5f && num2 < 4f)
				{
					flag4 = (vector - vector3).Length() < (flag3 ? 0.4f : 0.8f) && ((!flag3 | flag5) || num2 < 2f);
				}
			}
			if (flag4)
			{
				list.Add(ped);
				if (list.Count >= 4)
				{
					break;
				}
			}
		}
		_groupCache[target.Handle] = (Game.GameTime, list.Select((Ped x) => x.Handle).ToList());
		return list;
	}

	internal static bool OppositeSides(Ped a, Ped b)
	{
		try
		{
			Gang gang = Gangs.ForModel((uint)a.Model.Hash);
			Gang gang2 = Gangs.ForModel((uint)b.Model.Hash);
			if (gang != gang2)
			{
				return true;
			}
			if (PED.GET_RELATIONSHIP_BETWEEN_PEDS(a.Handle, b.Handle) >= 4 || PED.GET_RELATIONSHIP_BETWEEN_PEDS(b.Handle, a.Handle) >= 4)
			{
				return true;
			}
			if (!a.IsDead && !b.IsDead && (PED.IS_PED_IN_COMBAT(a.Handle, b.Handle) || PED.IS_PED_IN_COMBAT(b.Handle, a.Handle)))
			{
				return true;
			}
		}
		catch
		{
		}
		return false;
	}

	private static bool Facing(Ped who, Vector3 at)
	{
		Vector3 forwardVector = who.ForwardVector;
		Vector3 vector = at - who.Position;
		vector.Z = 0f;
		float num = vector.Length();
		if (num > 0.01f)
		{
			return (forwardVector.X * vector.X + forwardVector.Y * vector.Y) / num > 0.5f;
		}
		return false;
	}

	private string CircleKey(int handle)
	{
		NemesisRecord nemesisRecord = RecordAt(handle);
		if (nemesisRecord != null)
		{
			if (nemesisRecord.Id == null)
			{
				return null;
			}
			return "n:" + nemesisRecord.Id;
		}
		if (!_acqOf.TryGetValue(handle, out var value))
		{
			return null;
		}
		return value.Id;
	}

	private List<string> CircleOf(string key)
	{
		if (key == null)
		{
			return null;
		}
		if (key.StartsWith("n:"))
		{
			NemesisRecord nemesisRecord = FindRecord(key.Substring(2));
			object obj;
			if (nemesisRecord != null)
			{
				obj = nemesisRecord.CircleAcq;
				if (obj == null)
				{
					return nemesisRecord.CircleAcq = new List<string>();
				}
			}
			else
			{
				obj = null;
			}
			return (List<string>)obj;
		}
		Acquaintance acquaintance = People.FirstOrDefault((Acquaintance x) => x.Id == key);
		if (acquaintance != null)
		{
			return acquaintance.Circle ?? (acquaintance.Circle = new List<string>());
		}
		NemesisRecord nemesisRecord2 = Roster.FirstOrDefault((NemesisRecord x) => x.FormerAcqId == key);
		object obj2;
		if (nemesisRecord2 != null)
		{
			obj2 = nemesisRecord2.CircleAcq;
			if (obj2 == null)
			{
				return nemesisRecord2.CircleAcq = new List<string>();
			}
		}
		else
		{
			obj2 = null;
		}
		return (List<string>)obj2;
	}

	private (Acquaintance a, NemesisRecord r) ResolveCircle(string key)
	{
		if (key == null)
		{
			return (a: null, r: null);
		}
		if (key.StartsWith("n:"))
		{
			return (a: null, r: FindRecord(key.Substring(2)));
		}
		Acquaintance acquaintance = People.FirstOrDefault((Acquaintance x) => x.Id == key);
		if (acquaintance != null)
		{
			return (a: acquaintance, r: null);
		}
		return (a: null, r: Roster.FirstOrDefault((NemesisRecord x) => x.FormerAcqId == key));
	}

	private void LinkGroup(Ped target, List<Ped> mates, bool met)
	{
		List<Ped> list = new List<Ped> { target };
		list.AddRange(mates);
		foreach (Ped item in list)
		{
			if (RecordAt(item.Handle) != null)
			{
				continue;
			}
			if (!_named.ContainsKey(item.Handle))
			{
				if (!LookReadable(item))
				{
					continue;
				}
				_named[item.Handle] = NameByLook(item);
				_namesGiven++;
			}
			RememberPerson(item.Handle, met && item == target);
		}
		List<string> list2 = (from p in list
			select CircleKey(p.Handle) into k
			where k != null
			select k).Distinct().ToList();
		bool flag = false;
		foreach (string item2 in list2)
		{
			List<string> list3 = CircleOf(item2);
			if (list3 == null)
			{
				continue;
			}
			foreach (string item3 in list2)
			{
				if (item3 != item2 && !list3.Contains(item3))
				{
					list3.Add(item3);
					flag = true;
					if (list3.Count > 6)
					{
						list3.RemoveAt(0);
					}
				}
			}
		}
		List<NemesisRecord> list4 = (from p in list
			select RecordAt(p.Handle) into r
			where r?.IsAlive ?? false
			select r).Distinct().ToList();
		for (int num = 0; num < list4.Count; num++)
		{
			for (int num2 = num + 1; num2 < list4.Count; num2++)
			{
				MakeFriends(list4[num], list4[num2], "found together");
			}
		}
		if (flag)
		{
			GroupsLinked++;
			_peopleDirty = true;
			SaveRoster();
			GrudgeLog("GROUP " + string.Join(", ", list.Select((Ped p) =>
			{
				string text;
				if (!_named.TryGetValue(p.Handle, out var value))
				{
					text = RecordAt(p.Handle)?.Name;
					if (text == null)
					{
						return "?";
					}
				}
				else
				{
					text = value.Name;
				}
				return text;
			})) + " are together");
		}
		foreach (Ped item4 in list)
		{
			_groupLinked.Add(item4.Handle);
		}
	}

	private void MakeFriends(NemesisRecord a, NemesisRecord b, string why)
	{
		if (a != b && a.Id != null && b.Id != null && !(a.KinId == b.Id) && !(b.KinId == a.Id))
		{
			a.FriendIds = a.FriendIds ?? new List<string>();
			b.FriendIds = b.FriendIds ?? new List<string>();
			if (!a.FriendIds.Contains(b.Id) && a.FriendIds.Count < 3 && b.FriendIds.Count < 3)
			{
				a.FriendIds.Add(b.Id);
				b.FriendIds.Add(a.Id);
				GrudgeLog("FRIENDS " + a.Name + " <-> " + b.Name + " (" + why + ")");
				SaveRoster();
			}
		}
	}

	private void LinkGroupOnce(int handle)
	{
		if (_groupLinked.Contains(handle))
		{
			return;
		}
		_groupLinked.Add(handle);
		Ped ped = Entity.FromHandle(handle) as Ped;
		if (!(ped == null) && ped.Exists() && !ped.IsDead)
		{
			List<Ped> list = GroupOf(ped);
			if (list.Count > 0)
			{
				LinkGroup(ped, list, met: false);
			}
		}
	}

	private void GroupGreet(int target)
	{
		Ped ped = Entity.FromHandle(target) as Ped;
		if (ped == null || !ped.Exists() || ped.IsDead)
		{
			return;
		}
		List<Ped> list = GroupOf(ped);
		_groupLinked.Add(target);
		if (list.Count == 0)
		{
			return;
		}
		List<Ped> list2 = list.Where((Ped m) => RecordAt(m.Handle) == null && (!_named.TryGetValue(m.Handle, out var value3) || !value3.Met)).ToList();
		LinkGroup(ped, list, met: true);
		int num = 0;
		foreach (Ped item in list)
		{
			if (RecordAt(item.Handle) != null)
			{
				continue;
			}
			Introduce(item.Handle);
			try
			{
				Liking(item.Handle, GrudgeAction.EmoteGreet);
			}
			catch
			{
			}
			if (Config.GsBody)
			{
				NemesisRecord nemesisRecord = ShadowOf(item);
				Personality personality = nemesisRecord?.Personality ?? Personality.Cold;
				int num2;
				if (!((_acqOf.TryGetValue(item.Handle, out var value) ? ((float)value.Fear) : 0f) >= 30f))
				{
					if (nemesisRecord == null || !nemesisRecord.TraitsRolled || nemesisRecord.Disposition != Disposition.Surly)
					{
						switch (personality)
						{
						default:
							num2 = ((_rng.Next(2) == 0) ? (-1457020913) : 901097731);
							break;
						case Personality.Cold:
							num2 = -822629770;
							break;
						case Personality.Hothead:
						case Personality.Proud:
							num2 = 1879954891;
							break;
						}
					}
					else
					{
						num2 = 0;
					}
				}
				else
				{
					num2 = -1312563584;
				}
				uint num3 = (uint)num2;
				if (num3 != 0)
				{
					_reactions.Add((Game.GameTime + 1300 + num * 650, item, "greet:" + num3));
				}
			}
			num++;
		}
		if (list2.Count == 0 || !_named.TryGetValue(target, out var value2))
		{
			return;
		}
		GroupIntros++;
		string tLast = LastName(value2.Name);
		List<string> list3 = list2.Select((Ped m) =>
		{
			string text3 = (_named.TryGetValue(m.Handle, out var value3) ? value3.Name : "a friend");
			string text4 = text3.Split(' ')[0];
			bool num4 = tLast != null && LastName(text3) == tLast;
			bool flag = !PED.IS_PED_MALE(m.Handle);
			if (!num4)
			{
				return text3;
			}
			return (!flag) ? ("my brother " + text4) : ("my sister " + text4);
		}).ToList();
		string text = ((list3.Count == 1) ? list3[0] : (string.Join(", ", list3.Take(list3.Count - 1)) + " and " + list3.Last()));
		string text2;
		if (list3.Count != 1)
		{
			text2 = "them";
		}
		else
		{
			text2 = (PED.IS_PED_MALE(list2[0].Handle) ? "him" : "her");
		}
		string[] array = new string[7]
		{
			"This here's " + text + ".",
			"Meet " + text + ".",
			Cap(text) + " - we ride together.",
			"You'll know " + text + ", then.",
			"Don't mind " + text2 + ". " + Cap(text) + ".",
			Cap(text) + ". Friends of mine.",
			"And this is " + text + "."
		};
		ShowSubtitle(value2.Name + ": \"" + array[_rng.Next(array.Length)] + "\"");
		Feed("GROUP met " + string.Join(", ", list2.Select((Ped m) => (!_named.TryGetValue(m.Handle, out var value3)) ? "?" : value3.Name)) + " (with " + value2.Name + ")", Theme.Good);
	}

	private static string Cap(string s)
	{
		if (!string.IsNullOrEmpty(s))
		{
			return char.ToUpperInvariant(s[0]) + s.Substring(1);
		}
		return s;
	}

	private static string LastName(string full)
	{
		string[] array = (full ?? "").Split(' ');
		if (array.Length <= 1)
		{
			return null;
		}
		return array[array.Length - 1];
	}

	private void GroupInsulted(int target)
	{
		Ped ped = Entity.FromHandle(target) as Ped;
		if (ped == null || !ped.Exists())
		{
			return;
		}
		List<Ped> list = GroupOf(ped);
		if (list.Count == 0)
		{
			return;
		}
		LinkGroup(ped, list, met: false);
		Ped character = Game.Player.Character;
		foreach (Ped item in list)
		{
			if (RecordAt(item.Handle) != null)
			{
				continue;
			}
			Provocation provocation = RememberStranger(item.Handle);
			if (provocation != null && provocation.Record == null)
			{
				Grudge(item.Handle, provocation, GrudgeAction.FriendInsulted);
				if (Config.TownsfolkReactions)
				{
					TASK.TASK_TURN_PED_TO_FACE_ENTITY(item.Handle, character.Handle, 2500, 0f, 0f, 0f);
					TASK.TASK_LOOK_AT_ENTITY(item.Handle, character.Handle, 4000, 0, 51, 0);
				}
			}
		}
	}

	private void UpdateGroupWatch(Ped player)
	{
		if (Game.GameTime < _nextGroupWatch)
		{
			return;
		}
		_nextGroupWatch = Game.GameTime + 500;
		Vector3 me = player.Position;
		List<(Ped, Vector3)> list = (from x in PedSnapshot(player)
			where x.p != null && (x.pos - me).Length() <= 30f
			select x).ToList();
		if (list.Count == 0)
		{
			return;
		}
		int num = 0;
		for (int num2 = 0; num2 < list.Count; num2++)
		{
			if (num >= 6)
			{
				break;
			}
			Ped item = list[(_groupWatchNext + num2) % list.Count].Item1;
			if (!item.Exists() || item.IsDead || item.IsPlayer || !item.IsHuman || IsPlaced(item.Handle) || Kids.IsChild(item) || IsStoryPed(item))
			{
				continue;
			}
			num++;
			List<Ped> list2 = GroupOf(item);
			if (list2.Count == 0)
			{
				continue;
			}
			if (!_togetherAt.TryGetValue(item.Handle, out var value))
			{
				value = (_togetherAt[item.Handle] = new Dictionary<int, int>());
			}
			foreach (Ped item2 in list2)
			{
				value[item2.Handle] = Game.GameTime;
			}
		}
		_groupWatchNext = (_groupWatchNext + 6) % Math.Max(1, list.Count);
		if (Game.GameTime < _nextTogetherPrune)
		{
			return;
		}
		_nextTogetherPrune = Game.GameTime + 2000;
		foreach (int item3 in _togetherAt.Keys.ToList())
		{
			Dictionary<int, int> dictionary2 = _togetherAt[item3];
			foreach (int item4 in (from kv in dictionary2
				where Game.GameTime - kv.Value > 90000
				select kv.Key).ToList())
			{
				dictionary2.Remove(item4);
			}
			if (dictionary2.Count == 0 || !ENTITY.DOES_ENTITY_EXIST(item3))
			{
				_togetherAt.Remove(item3);
			}
		}
	}

	private List<Ped> RecentMates(int handle)
	{
		List<Ped> list = new List<Ped>();
		if (_togetherAt.TryGetValue(handle, out var value))
		{
			foreach (KeyValuePair<int, int> item in value)
			{
				Ped ped = Entity.FromHandle(item.Key) as Ped;
				if (ped != null && ped.Exists())
				{
					list.Add(ped);
				}
			}
		}
		foreach (KeyValuePair<int, Dictionary<int, int>> item2 in _togetherAt)
		{
			if (item2.Value.ContainsKey(handle))
			{
				Ped ped2 = Entity.FromHandle(item2.Key) as Ped;
				if (ped2 != null && ped2.Exists() && !list.Contains(ped2))
				{
					list.Add(ped2);
				}
			}
		}
		return list;
	}

	internal bool IsCircleMate(int mate, int victim)
	{
		if (_togetherAt.TryGetValue(victim, out var value) && value.ContainsKey(mate))
		{
			return true;
		}
		if (_togetherAt.TryGetValue(mate, out var value2) && value2.ContainsKey(victim))
		{
			return true;
		}
		if (_groupCache.TryGetValue(victim, out (int, List<int>) value3) && Game.GameTime - value3.Item1 < 120000 && value3.Item2.Contains(mate))
		{
			return true;
		}
		string text = CircleKey(victim);
		string text2 = CircleKey(mate);
		if (text != null && text2 != null)
		{
			List<string> list = CircleOf(text);
			if (list != null && list.Contains(text2))
			{
				return true;
			}
		}
		NemesisRecord nemesisRecord = RecordAt(victim);
		NemesisRecord nemesisRecord2 = RecordAt(mate);
		if (nemesisRecord != null && nemesisRecord2 != null)
		{
			return nemesisRecord.FriendIds?.Contains(nemesisRecord2.Id) ?? false;
		}
		return false;
	}

	private void QueuePeopleNews(string deadName, string deadTown, List<string> circle, Vector3 body, NemesisRecord deadRec = null)
	{
		if (circle == null || circle.Count == 0)
		{
			return;
		}
		long num = GameMinutesNow();
		List<DeathNews> list = Chronicle.PeopleNews ?? (Chronicle.PeopleNews = new List<DeathNews>());
		HashSet<object> hashSet = new HashSet<object>();
		foreach (string item2 in circle.ToList())
		{
			var (a, r) = ResolveCircle(item2);
			if ((a == null && r == null) || !hashSet.Add(((object)r) ?? ((object)a)) || (a != null && a.Dead) || (r != null && !r.IsAlive))
			{
				continue;
			}
			if (r != null && deadRec != null)
			{
				List<string> friendIds = deadRec.FriendIds;
				if ((friendIds != null && friendIds.Contains(r.Id)) || r.KinId == deadRec.Id || deadRec.KinId == r.Id)
				{
					continue;
				}
			}
			bool num2 = _acqOf.Any((KeyValuePair<int, Acquaintance> kv) => kv.Value == a && a != null && ENTITY.DOES_ENTITY_EXIST(kv.Key) && new Ped(kv.Key).Position.DistanceTo(body) < 60f) || _worldNemeses.Any((KeyValuePair<int, NemesisRecord> kv) => kv.Value == r && r != null && ENTITY.DOES_ENTITY_EXIST(kv.Key) && new Ped(kv.Key).Position.DistanceTo(body) < 60f) || (r != null && r == ActiveRecord && _activeNemesisPed != null && _activeNemesisPed.Exists() && _activeNemesisPed.Position.DistanceTo(body) < 60f);
			string text = a?.Town ?? r?.KillLocation;
			int num3 = ((!num2) ? ((text != null && text == deadTown) ? (3 + _rng.Next(10)) : (12 + _rng.Next(37))) : 0);
			DeathNews item = new DeathNews
			{
				DeadName = deadName,
				KinId = item2,
				ByYou = true,
				At = num,
				DueAt = num + num3 * 60 + _rng.Next(60)
			};
			if (!num2)
			{
				list.Add(item);
				GrudgeLog(Pron.Her($"NEWS {a?.Name ?? r?.Name} will hear you killed his friend {deadName} in {num3} h", Models.Female(a?.Model ?? r?.ModelHash ?? 0)));
			}
		}
		SaveWorld();
	}

	private void DeliverPeopleNews(DeathNews n)
	{
		(Acquaintance, NemesisRecord) tuple = ResolveCircle(n.KinId);
		Acquaintance a = tuple.Item1;
		NemesisRecord item = tuple.Item2;
		string text = Pron.Her("heard you killed his friend " + n.DeadName, Models.Female(a?.Model ?? item?.ModelHash ?? 0));
		if (item != null)
		{
			if (item.IsAlive)
			{
				int hate = item.Hate;
				item.AddHate(12);
				Remember(item, "Grief", 60, "you killed his friend, " + n.DeadName);
				History(item, "HEARD you killed his friend " + n.DeadName, Theme.Blood);
				item.Touch();
				Feed("FRIEND " + item.Name + " " + text + ": hate " + Delta(hate, item.Hate), Theme.Blood, item);
			}
		}
		else
		{
			if (a == null || a.Dead)
			{
				return;
			}
			Personality personality = (Enum.TryParse<Personality>(a.Temper ?? "", out var result) ? result : Personality.Cold);
			float num;
			switch (personality)
			{
			default:
				num = 1f;
				break;
			case Personality.Coward:
				num = 0.5f;
				break;
			case Personality.Drifter:
				num = 0.6f;
				break;
			case Personality.Cold:
				num = 0.7f;
				break;
			case Personality.Hothead:
			case Personality.Proud:
			case Personality.Loyal:
				num = 1.3f;
				break;
			}
			float num2 = num;
			int grudge = a.Grudge;
			int fear = a.Fear;
			a.Grudge = Math.Min(100, a.Grudge + (int)Math.Round(45f * num2));
			a.Fear = Math.Min(100, a.Fear + ((personality == Personality.Coward) ? 18 : 6));
			a.Like = Math.Max(0, a.Like - 25);
			a.GrudgeSettled = false;
			(a.Witnessed ?? (a.Witnessed = new List<string>())).Add(text + " - " + GameDateShort());
			TrimWitnessed(a);
			_peopleDirty = true;
			foreach (KeyValuePair<int, Acquaintance> item2 in _acqOf.Where((KeyValuePair<int, Acquaintance> kv) => kv.Value == a).ToList())
			{
				RestoreGrudge(item2.Key, a);
			}
			GrudgeLog($"NEWS {a.Name} {text} ({(float)(GameMinutesNow() - n.At) / 60f:0.#} h after): grudge {grudge} -> {a.Grudge}, fear {fear} -> {a.Fear}");
			Feed($"FRIEND {a.Name} ({personality.ToString().ToLowerInvariant()}) {text}: grudge {grudge} to {a.Grudge}, fear {fear} to {a.Fear}", Theme.Blood);
		}
	}

	private void UpdatePeopleNews()
	{
		List<DeathNews> peopleNews = Chronicle.PeopleNews;
		if (peopleNews == null || peopleNews.Count == 0)
		{
			return;
		}
		long now = GameMinutesNow();
		List<DeathNews> list = (from n in peopleNews
			where n.DueAt <= now
			orderby n.DueAt
			select n).ToList();
		if (list.Count == 0)
		{
			return;
		}
		foreach (DeathNews item in list)
		{
			peopleNews.Remove(item);
			try
			{
				DeliverPeopleNews(item);
			}
			catch (Exception ex)
			{
				GrudgeLog("NEWS failed: " + ex.Message);
			}
		}
		SaveWorld();
	}

