					case 8:
						OnSocial(num6, GrudgeAction.DrawOn);
						break;
					case 7:
					case 20:
						OnRobAttempt(num6);
						break;
					case 19:
						OnRobAttempt(num6, calm: true);
						break;
					}
				}
				break;
			}
			case 1376140891u:
				*ptr = (ptr[1] = (ptr[2] = 0uL));
				if (SCRIPTS.GET_EVENT_DATA(0, i, ptr, 3) && (int)(*ptr) == player.Handle)
				{
					_lootedAt = Game.GameTime;
