				Ped ped = Entity.FromHandle(victim) as Ped;
				if (ped != null && ped.Exists() && ped.IsHuman && ped.IsDead && !LooksKnockedOut(ped) && !Kids.IsChild(ped) && _countedDeaths.Add(victim))
