						GrudgeLog("WITNESS failed: " + ex.Message);
					}
				}
				bool flag = GunMelee.IsGunMeleeHit(player, victim, (uint)ptr[2]);
				bool flag2 = (num2 == 2685387236u) | flag;
				if (!flag2)
				{
					GunMelee.MarkWounded(victim);
				}
				if (OnHorseHurt(victim))
				{
