				}
				else if (flag2)
				{
					OnInterrogationHit(victim);
					OnPlayerPunched(victim);
				}
				else if (num2 == 3566412244u)
				{
					OnInterrogationHit(victim, 1);
					Mark(victim, (Provocation p) =>
					{
						if (!p.Slashed)
						{
							Grudge(victim, p, GrudgeAction.Slashed);
						}
						p.Slashed = true;
					});
				}
				else
				{
					OnInterrogationHit(victim, 2);
					OnPlayerWounded(victim);
				}
				break;
			}
			}
		}
	}

	private void OnProvoked(int target, bool insult)
	{
		if (target == 0)
		{
			return;
		}
		if (PanelButtonsHeld)
		{
			GrudgeLog(string.Format("PROVOKE {0} on ped {1} ignored - the questioning panel's buttons", insult ? "antagonize" : "greet", target));
			return;
		}
		if (!_named.ContainsKey(target) && ChildPed(target, out var p))
		{
			if (Config.NamingEnabled)
			{
				MeetKid(target, KidFor(p));
			}
			return;
		}
		if (insult)
		{
			NoteAntagonized(target);
		}
		Introduce(target, insult);
		try
		{
			if (insult)
			{
				GroupInsulted(target);
			}
			else
			{
				GroupGreet(target);
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("GROUP failed: " + ex.Message);
		}
		if ((!insult && GreetNemesis(target, GrudgeAction.Greet)) || TownProvoked(target, insult))
		{
			return;
		}
		if (_activeNemesisPed != null && ActiveRecord != null && target == _activeNemesisPed.Handle)
		{
			NemesisProvoked(insult);
			return;
		}
		Provocation provocation = RememberStranger(target);
		if (provocation != null)
		{
			Grudge(target, provocation, insult ? GrudgeAction.Insult : GrudgeAction.Greet);
			ReactByTemper(target, insult);
		}
	}

	private bool GreetNemesis(int target, GrudgeAction a)
	{
		if (_activeNemesisPed != null && target == _activeNemesisPed.Handle)
		{
			return false;
		}
		if (GreetHidden(target))
		{
			return true;
		}
		NemesisRecord nemesisRecord = RecordAt(target);
		if (nemesisRecord == null || !nemesisRecord.IsAlive)
		{
			return false;
		}
		TownMan townMan = TownManFor(target);
		if (townMan != null && townMan.Engaged)
		{
			return false;
		}
		if (Entity.FromHandle(target) is Ped ped && ped.Exists() && PED.IS_PED_IN_COMBAT(ped.Handle, Game.Player.Character.Handle))
		{
			return false;
		}
		_lastGreetDrop = 0;
		ApplyToRecord(nemesisRecord, a);
		if (a == GrudgeAction.Greet)
		{
			string text;
			if (_lastGreetDrop >= 5)
			{
				text = "...Alright. Evenin'.";
			}
			else if (_lastGreetDrop >= 2)
			{
				text = "Hm. Evenin'.";
			}
			else
			{
				text = ((_lastGreetDrop >= 1) ? "Don't push it." : Taunts.GreetReply(_rng));
			}
			ShowSubtitle(nemesisRecord.Name + ": \"" + text + "\"");
		}
		return true;
	}

	private void OnSocial(int target, GrudgeAction a)
	{
		if (target == 0)
		{
			return;
		}
		Introduce(target, a == GrudgeAction.Taunt || a == GrudgeAction.Intimidate || a == GrudgeAction.DrawOn);
		if (a == GrudgeAction.EmoteGreet)
		{
			try
			{
				GroupGreet(target);
			}
			catch (Exception ex)
			{
				GrudgeLog("GROUP failed: " + ex.Message);
			}
		}
		NemesisRecord nemesisRecord = ((_activeNemesisPed != null && ActiveRecord != null && target == _activeNemesisPed.Handle) ? ActiveRecord : null);
		if (nemesisRecord != null)
		{
			ApplyToRecord(nemesisRecord, a);
		}
		else if ((a != GrudgeAction.EmoteGreet && a != GrudgeAction.Defuse) || !GreetNemesis(target, a))
		{
			Provocation provocation = RememberStranger(target);
			if (provocation != null && Game.GameTime - provocation.LastSocialAt >= 1500)
			{
				provocation.LastSocialAt = Game.GameTime;
				Grudge(target, provocation, a);
			}
		}
	}

	private void OnRobAttempt(int target, bool calm = false)
	{
		if (target == 0)
		{
			return;
		}
		NoDeed(target, "you stuck them up");
		Introduce(target, hostile: true);
		GrudgeAction a = (calm ? GrudgeAction.StickUpCalm : GrudgeAction.StickUp);
		if (_activeNemesisPed != null && ActiveRecord != null && target == _activeNemesisPed.Handle)
		{
			ApplyToRecord(ActiveRecord, a);
			return;
		}
		Provocation provocation = RememberStranger(target);
		if (provocation != null && Game.GameTime - provocation.LastRobAttempt >= 1500)
		{
			provocation.LastRobAttempt = Game.GameTime;
			Grudge(target, provocation, a);
		}
	}

	private void OnRobbed(int victim, string how)
	{
		OnInterrogationLoot(victim);
		NoDeed(victim, "you robbed them");
		if (Entity.FromHandle(victim) is Ped ped && ped.Exists() && !ped.IsDead)
		{
			Introduce(victim, hostile: true);
		}
		Provocation provocation = RememberStranger(victim);
		try
		{
			if (Entity.FromHandle(victim) is Ped ped2 && ped2.Exists() && !ped2.IsDead)
			{
				PurseRobbed(victim);
			}
		}
		catch
		{
		}
		NemesisMod nemesisMod = this;
		object arg = victim;
		string arg2 = how;
		string arg3;
		if (provocation == null)
		{
			arg3 = "ignored (dead, friend or not a person)";
		}
		else
		{
			arg3 = ((provocation.Record != null) ? ("existing nemesis " + provocation.Record.Name) : "stranger, grudge pending");
		}
		nemesisMod.GrudgeLog($"ROBBED ped={arg} via {arg2} -> {arg3}");
		NemesisRecord nemesisRecord;
		if (provocation == null)
		{
			nemesisRecord = RecordAt(victim);
			if (nemesisRecord == null || (_robbedAt.TryGetValue(victim, out var value) && Game.GameTime - value < 10000))
			{
				return;
			}
			_robbedAt[victim] = Game.GameTime;
		}
		else
		{
			if (Game.GameTime - provocation.LastRobbedTime < 10000)
			{
				return;
			}
			provocation.LastRobbedTime = Game.GameTime;
			bool flag = provocation.Record == null;
			if (flag)
			{
				Grudge(victim, provocation, GrudgeAction.Robbed);
			}
			else
			{
				CrimeSeen(victim, CrimeOf(GrudgeAction.Robbed));
			}
			provocation.Robbed = true;
			nemesisRecord = provocation.Record;
			if (nemesisRecord == null)
			{
				return;
			}
			if (flag && Roster.Contains(nemesisRecord))
			{
				nemesisRecord.TimesRobbed++;
				if (!provocation.RolledFor.HasValue || provocation.RolledFor.Value < GrudgeOrigin.Robbed)
				{
					provocation.RolledFor = GrudgeOrigin.Robbed;
				}
				WorldPart worldPart = PartFor(nemesisRecord, "ROBBED", "and swore to get it back");
				worldPart.Effects.Add($"hate {nemesisRecord.Hate} ({nemesisRecord.HateTier})");
				Vector3 position = Game.Player.Character.Position;
				ChronicleDeed("rob", "You robbed " + nemesisRecord.Name, "near " + GetZoneName(position), position, nemesisRecord.Gang, worldPart);
				SaveRoster();
				return;
			}
			if (!provocation.RolledFor.HasValue || provocation.RolledFor.Value < GrudgeOrigin.Robbed)
			{
				provocation.RolledFor = GrudgeOrigin.Robbed;
			}
		}
		int hate = nemesisRecord.Hate;
		HiddenSlip(nemesisRecord, "rob");
		nemesisRecord.TimesRobbed++;
		Remember(nemesisRecord, (Mind.F(nemesisRecord, "Greed") >= 60) ? "Anger" : "Shame", 45 + Math.Min(30, nemesisRecord.TimesRobbed * 8), (nemesisRecord.TimesRobbed > 1) ? $"you robbed him - {nemesisRecord.TimesRobbed} times now" : "you robbed him");
		int fear = nemesisRecord.Fear;
		int val = Balance.RobbedHateGain + ((nemesisRecord.Personality == Personality.Greedy) ? Balance.RobbedGreedyExtra : 0) + ((nemesisRecord.TraitsRolled && nemesisRecord.Wealth == Wealth.Poor) ? 5 : ((nemesisRecord.TraitsRolled && nemesisRecord.Wealth == Wealth.Rich) ? (-4) : 0)) + Math.Min(12, 4 * (nemesisRecord.TimesRobbed - 1));
		nemesisRecord.AddHate(Math.Max(3, val));
		nemesisRecord.AddFear(Balance.FearPerRobbery);
		nemesisRecord.AddYourNotoriety(5);
		Feed($"ROBBED {nemesisRecord.Name}: hate {Delta(hate, nemesisRecord.Hate)}  fear {Delta(fear, nemesisRecord.Fear)}  (robbed {nemesisRecord.TimesRobbed}x)", Theme.Warn, nemesisRecord);
		WorldPart worldPart2 = PartFor(nemesisRecord, "ROBBED", (nemesisRecord.TimesRobbed > 1) ? $"robbed {nemesisRecord.TimesRobbed} times now" : nemesisRecord.Title);
		worldPart2.Effects.Add($"hate {hate} -> {nemesisRecord.Hate}");
		worldPart2.Effects.Add($"fear {fear} -> {nemesisRecord.Fear}");
		Vector3 position2 = Game.Player.Character.Position;
		ChronicleDeed("rob", "You robbed " + nemesisRecord.Name, "near " + GetZoneName(position2), position2, nemesisRecord.Gang, worldPart2);
		SaveRoster();
		GrudgeNotice((Hate.TierOf(nemesisRecord.Hate) > Hate.TierOf(hate)) ? ("You robbed " + nemesisRecord.FullName + ". He's " + nemesisRecord.HateTier.ToString().ToLowerInvariant() + " now.") : ("You robbed " + nemesisRecord.FullName + " again. He won't forget it."));
	}

	internal void PayPlayer(int cents)
	{
		if (cents > 0)
		{
			try
			{
				MONEY._MONEY_INCREMENT_CASH_BALANCE(cents, MISC.GET_HASH_KEY("ADD_REASON_DEFAULT"));
			}
			catch
			{
				return;
			}
			_paidPending += cents;
			_paidAt = Game.GameTime;
		}
	}

	private unsafe void DetectRobberyByCash(Ped player)
	{
		int num = 0;
		if (((PLAYER.GET_ENTITY_PLAYER_IS_FREE_AIMING_AT(Game.Player.Handle, &num) && num != 0) || (PLAYER.GET_PLAYER_TARGET_ENTITY(Game.Player.Handle, &num) && num != 0)) && Entity.FromHandle(num) is Ped { IsHuman: not false, IsPlayer: false, IsDead: false })
		{
			_robTarget = num;
			_robTargetTime = Game.GameTime;
			if (WEAPON.IS_PED_ARMED(player.Handle, 4))
			{
				_gunOnAt[num] = Game.GameTime;
			}
		}
		int num2 = MONEY._MONEY_GET_CASH_BALANCE();
		if (_lastCash == int.MinValue)
		{
			_lastCash = num2;
			return;
		}
		int num3 = num2 - _lastCash;
		_lastCash = num2;
		if (_paidPending > 0 && Game.GameTime - _paidAt > 5000)
		{
			_paidPending = 0;
		}
		if (num3 > 0 && (_paidPending <= 0 || num3 > _paidPending))
		{
			_cashRoseAt = Game.GameTime;
			ArrestOnPayout(player);
		}
		if (num3 > 0 && _paidPending > 0)
		{
			int num4 = Math.Min(num3, _paidPending);
			num3 -= num4;
			_paidPending -= num4;
			if (num3 <= 0)
			{
				GrudgeLog($"CASH +{num4} paid by the mod - not a robbery");
			}
		}
		if (num3 > 0)
		{
			Ped ped2 = ((_robTarget != 0 && Game.GameTime - _robTargetTime < 6000) ? (Entity.FromHandle(_robTarget) as Ped) : null);
			bool flag = ped2 != null && ped2.Exists() && !ped2.IsDead && !ped2.IsHogtied && !ENTITY.IS_ENTITY_ATTACHED(ped2.Handle) && ped2.Position.DistanceTo(player.Position) < 8f;
			string text = null;
			if (flag && (!PLAYER.IS_PLAYER_CONTROL_ON(Game.Player.Handle) || Game.GameTime - _quietEndedAt < 3000))
			{
				text = "the game was paying out (no control)";
			}
			else if (flag && Game.GameTime - _lootedAt < 2000)
			{
				text = "you were looting (a body / a satchel)";
			}
			else if (flag && GameEventPed(ped2))
			{
				text = WhoIs(ped2.Handle) + " is part of a game event (a bet / a reward)";
			}
			GrudgeLog(string.Format("CASH +{0} recentTarget={1} {2}{3}", num3, _robTarget, flag ? "near and alive" : "none near", (text != null) ? (" - not a robbery: " + text) : ""));
			if (flag && text == null)
			{
				OnRobbed(_robTarget, $"cash +{num3}");
			}
		}
	}

	internal void MenuLog(string line)
	{
		GrudgeLog(line);
	}

	private bool FleeingYou(Ped ped, Ped player)
	{
		float num = ped.Position.DistanceTo(player.Position);
		if (num < 15f)
		{
			return true;
		}
		if (num < 50f && (WEAPON.IS_PED_ARMED(player.Handle, 4) || WEAPON.IS_PED_ARMED(player.Handle, 1)))
		{
			return true;
		}
		if (ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(ped.Handle, player.Handle, p2: true, p3: true))
		{
			return true;
		}
		if (_combatants.TryGetValue(ped.Handle, out var value))
		{
			return Game.GameTime - value < 10000;
		}
		return false;
	}

	internal void GrudgeLog(string line)
	{
		if (line == null)
		{
			return;
		}
		bool flag = line.StartsWith("FEED ASKED", StringComparison.Ordinal) || line.StartsWith("FEED INTEL", StringComparison.Ordinal) || line.StartsWith("FEED BRIBED", StringComparison.Ordinal) || line.StartsWith("FEED THREATENED", StringComparison.Ordinal) || line.StartsWith("FEED LET GO", StringComparison.Ordinal);
		if (Config != null && !Config.Verbose && !flag)
		{
			string[] chattyPrefixes = ChattyPrefixes;
			foreach (string value in chattyPrefixes)
			{
				if (line.StartsWith(value, StringComparison.Ordinal))
				{
					return;
				}
			}
		}
		line = UiDraw.TheFix(line);
		_logBuf.Append('[').Append(DateTime.Now.ToString("HH:mm:ss")).Append("] ")
			.Append(line)
			.Append("\r\n");
		if (_logBuf.Length > 16000)
		{
			FlushGrudgeLog(force: false, later: true);
		}
	}

	private void FlushGrudgeLog(bool force = false, bool later = false)
	{
		if (_logBuf.Length == 0 || (!force && _logBuf.Length < 16000 && Environment.TickCount < _nextLogFlush))
		{
			return;
		}
		_nextLogFlush = Environment.TickCount + 1000;
		string path = Path.Combine(_saveDir, "grudges.log");
		string text = _logBuf.ToString();
		_logBuf.Clear();
		if (later)
		{
			SafeFile.AppendLater(path, text);
			return;
		}
		SafeFile.WaitWrites(500);
		try
		{
			SafeFile.Append(path, text);
		}
		catch
		{
		}
	}

	private bool Bumped(Ped player)
	{
		if (PED.IS_PED_IN_MELEE_COMBAT(player.Handle))
		{
			return false;
		}
		if (!PED.IS_PED_ON_MOUNT(player.Handle))
		{
			return ENTITY.GET_ENTITY_SPEED(player.Handle) > 2.6f;
		}
		return true;
	}

	private void OnPlayerBumped(int victim)
	{
		Provocation provocation = RememberStranger(victim);
		if (provocation != null && Game.GameTime - provocation.LastBumpTime >= 3000)
		{
			provocation.LastBumpTime = Game.GameTime;
			if (provocation.Record != null)
			{
				int hate = provocation.Record.Hate;
				provocation.Record.AddHate(3);
				CapScuffle(provocation.Record, hate);
				provocation.Record.Touch();
				SaveRoster();
				Feed("BUMPED " + provocation.Record.Name + " - knocked him over: hate " + Delta(hate, provocation.Record.Hate), Theme.Dim, provocation.Record);
			}
			else
			{
				Grudge(victim, provocation, GrudgeAction.Bumped);
			}
		}
	}

	private void OnPlayerPunched(int victim)
	{
		Provocation provocation = RememberStranger(victim);
		if (provocation != null && Game.GameTime - provocation.LastHitTime >= 250)
		{
			provocation.LastHitTime = Game.GameTime;
			_lastPunchAt = Game.GameTime;
			provocation.Hits++;
			if (provocation.Record != null)
			{
				Feed($"PUNCHED {provocation.Record.Name} ({provocation.Hits} hits)", null, provocation.Record);
				CrimeSeen(victim, CrimeOf(GrudgeAction.Punch));
			}
			else
			{
				Grudge(victim, provocation, GrudgeAction.Punch);
			}
		}
	}

	private void UpdateBumps(Ped player)
	{
		if (Game.GameTime < _nextBumpScan)
		{
			return;
		}
		_nextBumpScan = Game.GameTime + 200;
		bool flag = PED.IS_PED_ON_MOUNT(player.Handle);
		bool flag2 = flag || ENTITY.GET_ENTITY_SPEED(player.Handle) > 2.6f;
		float num = (flag ? 4f : 2.5f);
		Vector3 position = player.Position;
		foreach (var item in PedSnapshot(player))
		{
			var (ped, _) = item;
			if (ped == null || !ped.Exists() || ped.IsDead || ped.Handle == player.Handle || !ped.IsHuman)
			{
				continue;
			}
			int handle = ped.Handle;
			if (!ped.IsRagdoll)
			{
				_downSeen.Remove(handle);
			}
			else if (!_downSeen.Contains(handle))
			{
				_downSeen.Add(handle);
				if (flag2 && !((item.pos - position).Length() > num) && !PED.IS_PED_IN_MELEE_COMBAT(player.Handle) && !PED.IS_PED_IN_COMBAT(handle, player.Handle) && (!IsOurs(handle) || RecordAt(handle) != null) && !Kids.IsChild(ped) && !IsStoryPed(ped) && !GameOwned(ped) && !IsCompanion(handle))
				{
					GrudgeLog(string.Format("BUMP you knocked {0} over ({1}, {2:0.0} m)", NameOf(handle), flag ? "riding" : $"{ENTITY.GET_ENTITY_SPEED(player.Handle):0.0} m/s", (item.pos - position).Length()));
					OnPlayerBumped(handle);
				}
			}
		}
		if (_downSeen.Count > 200)
		{
			_downSeen.Clear();
		}
	}

	private void UpdateCombatGrudges(Ped player)
	{
		try
		{
			UpdateBumps(player);
		}
		catch (Exception ex)
		{
			GrudgeLog("BUMP failed: " + ex.Message);
		}
		UpdateNerve(player);
		bool flag = PED.IS_PED_SHOOTING(player.Handle);
		if (flag && !_wasShootingAny && _combatants.Count > 0)
		{
			var (cam, dir) = AimRay();
			foreach (int item in _combatants.Keys.ToList())
			{
				Ped ped = Entity.FromHandle(item) as Ped;
				if (!(ped == null) && ped.Exists() && !ped.IsDead && (!_shotAtAt.TryGetValue(item, out var value) || Game.GameTime - value >= 3000) && (!_hitByYouAt.TryGetValue(item, out var value2) || Game.GameTime - value2 >= 1200) && ShotPasses(cam, dir, ped, 2.5f))
				{
					_shotAtAt[item] = Game.GameTime;
					NerveNearMiss(item);
					Provocation provocation = RememberStranger(item);
					if (provocation != null && provocation.Record == null)
					{
						Grudge(item, provocation, GrudgeAction.ShotAt);
					}
				}
			}
		}
		_wasShootingAny = flag;
		if (Game.GameTime < _nextCombatScan)
		{
			return;
		}
		_nextCombatScan = Game.GameTime + 500;
		foreach (Ped item2 in PedsAround(Game.Player.Character))
		{
			if (item2 == null || !item2.Exists() || item2.IsPlayer || item2.Position.DistanceTo(player.Position) > 80f || !item2.IsHuman || Kids.IsChild(item2))
			{
				continue;
			}
			int handle = item2.Handle;
			if (item2.IsDead)
			{
				if (LooksKnockedOut(item2))
				{
					_aliveNow.Add(handle);
					continue;
				}
				if (_aliveLastScan.Contains(handle) && PED.GET_PED_SOURCE_OF_DEATH(handle) == player.Handle && _countedDeaths.Add(handle))
				{
					WitnessKill(item2);
				}
				if (!_combatants.ContainsKey(handle) || !_countedDeaths.Contains(handle) || LooksKnockedOut(item2) || PED.GET_PED_SOURCE_OF_DEATH(handle) != player.Handle || !_comradeScored.Add(handle))
				{
					continue;
				}
				foreach (int item3 in _combatants.Keys.ToList())
				{
					if (item3 == handle)
					{
						continue;
					}
					Ped ped2 = Entity.FromHandle(item3) as Ped;
					if (!(ped2 == null) && ped2.Exists() && !ped2.IsDead && !(ped2.Position.DistanceTo(item2.Position) > 40f))
					{
						Provocation provocation2 = RememberStranger(item3);
						if (provocation2 != null && provocation2.Record == null)
						{
							Grudge(item3, provocation2, GrudgeAction.ComradeKilled);
						}
					}
				}
				continue;
			}
			_aliveNow.Add(handle);
			if (!PED.IS_PED_IN_COMBAT(handle, player.Handle))
			{
				continue;
			}
			bool flag2 = !_combatants.ContainsKey(handle);
			if (flag2)
			{
				try
				{
					uint key = ModGroupOf(handle);
					bool flag3 = _cameAtYouGroup.TryGetValue(key, out var value3) && Game.GameTime - value3 < 60000 && !ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(handle, player.Handle, p2: true, p3: true);
					if (!IsLawman(item2) && (flag3 || !YouStartedIt(handle, player, out var _)))
					{
						if (_cameAtYou.Count > 300)
						{
							_cameAtYou.Clear();
						}
						_cameAtYou.Add(handle);
						_cameAtYouGroup[key] = Game.GameTime;
					}
				}
				catch
				{
				}
			}
			_combatants[handle] = Game.GameTime;
			if (flag2)
			{
				RememberStranger(handle);
			}
			if (flag2)
			{
				try
				{
					NoteFirstBlow(item2, player);
				}
				catch (Exception ex2)
				{
					GrudgeLog("PEACE first blow failed: " + ex2.Message);
				}
			}
		}
		try
		{
			UpdatePeace(player);
		}
		catch (Exception ex3)
		{
			GrudgeLog("PEACE update failed: " + ex3.Message);
		}
		HashSet<int> aliveNow = _aliveNow;
		HashSet<int> aliveLastScan = _aliveLastScan;
		_aliveLastScan = aliveNow;
		_aliveNow = aliveLastScan;
		_aliveNow.Clear();
		foreach (int item4 in (from kv in _combatants
			where Game.GameTime - kv.Value > 60000
			select kv.Key).ToList())
		{
			_combatants.Remove(item4);
			_shotAtAt.Remove(item4);
		}
		if (_countedDeaths.Count > 200)
		{
			_countedDeaths.Clear();
			_comradeScored.Clear();
		}
	}

	internal void NoteKill(Ped dead, string gang = null)
	{
		if (!(dead == null) && dead.Exists() && _killNoted.Add(dead.Handle))
		{
			_tensionKills++;
			if (IsOurs(dead.Handle))
			{
				_tensionKillsOurs++;
			}
			RecentKills.Add((Game.GameTime, dead.Position, gang ?? RecordAt(dead.Handle)?.Gang ?? Gangs.ForModel((uint)dead.Model.Hash)?.Id));
			RecentKills.RemoveAll(((int at, Vector3 pos, string gang) k) => Game.GameTime - k.at > 600000);
		}
	}

	private void WitnessKill(Ped dead)
	{
		Ped character = Game.Player.Character;
		NoteKill(dead);
		string text = null;
		try
		{
			text = GoreOf(dead);
		}
		catch
		{
		}
		NemesisRecord nemesisRecord = RecordAt(dead.Handle);
		try
		{
			NerveAllyKilled(dead, nemesisRecord != null && (nemesisRecord == ActiveRecord || nemesisRecord.Rank >= 3), text);
		}
		catch (Exception ex)
		{
			GrudgeLog("NERVE failed: " + ex.Message);
		}
		if (text != null)
		{
			GrudgeLog("GORE you " + text + " (" + WhoIs(dead.Handle) + ")");
		}
		try
		{
			WitnessSilenced(dead);
			Witness((text != null) ? "gore" : "kill", dead.Handle, dead.Position, (text != null) ? ("saw you " + text) : null);
		}
		catch (Exception ex2)
		{
			GrudgeLog("WITNESS failed: " + ex2.Message);
		}
		try
		{
			AffiliateWronged(dead.Handle, (text != null) ? "gore" : "kill");
		}
		catch
		{
		}
		CountYourCrime("kill");
		if (text != null)
		{
			CountYourCrime("gore");
		}
		try
		{
			RememberMaskedKill(dead, character);
		}
		catch (Exception ex3)
		{
			GrudgeLog("MASKED KILL failed: " + ex3.Message);
		}
		NemesisRecord nemesisRecord2 = RecordAt(dead.Handle);
		string text2 = WhoIs(dead.Handle);
		bool flag = _followerOf.ContainsKey(dead.Handle) || (_activeNemesisPed != null && dead.Handle == _activeNemesisPed.Handle);
		foreach (Ped item in PedsAround(Game.Player.Character))
		{
			if (item == null || !item.Exists() || item.IsDead || item.IsPlayer || item.Handle == dead.Handle)
			{
				continue;
			}
			float num = item.Position.DistanceTo(dead.Position);
			if (num > 40f)
			{
				continue;
			}
			Interrogation interrogation = InterroFor(item.Handle);
			if (interrogation != null)
			{
				Terrify(interrogation, (text != null) ? GoreAt(num, Balance.TerrorComradeKilled) : Balance.TerrorComradeKilled, (text != null) ? ("SAW YOU " + text.ToUpperInvariant()) : "SAW YOU KILL");
			}
			NemesisRecord nemesisRecord3 = interrogation?.Rec ?? RecordAt(item.Handle);
			if (nemesisRecord3 != null && interrogation != _interro && (!_fighters.TryGetValue(item.Handle, out var value) || value.Done))
			{
				bool flag2 = flag || (nemesisRecord2 != null && (nemesisRecord2.Gang == nemesisRecord3.Gang || FriendsOf(nemesisRecord3).Contains(nemesisRecord2)));
				int fear = nemesisRecord3.Fear;
				int num2 = (flag2 ? (Balance.FearPerComradeKilled * 2) : Balance.FearPerComradeKilled);
				nemesisRecord3.AddFear((text != null) ? GoreAt(num, num2) : num2);
				if (nemesisRecord3.Fear != fear)
				{
					nemesisRecord3.Touch();
					Feed("SAW YOU KILL " + text2 + ": " + nemesisRecord3.Name + " fear " + Delta(fear, nemesisRecord3.Fear) + (flag2 ? "  (one of his own)" : ""), (150, 170, 210), nemesisRecord3);
				}
			}
		}
	}

	private void OnPlayerWounded(int victim)
	{
		Provocation provocation = RememberStranger(victim);
		if (provocation != null && !provocation.Wounded)
		{
			if (provocation.Record == null)
			{
				Grudge(victim, provocation, GrudgeAction.Wounded);
			}
			else
			{
				Feed("SHOT " + provocation.Record.Name, Theme.Warn, provocation.Record);
				CrimeSeen(victim, CrimeOf(GrudgeAction.Wounded));
			}
		}
		else if (provocation != null && provocation.Record == null && provocation.ShotAgainCount < 2 && Game.GameTime - provocation.LastWoundAt > 1500)
		{
			provocation.ShotAgainCount++;
			Grudge(victim, provocation, GrudgeAction.Wounded);
		}
		if (provocation != null)
		{
			provocation.Wounded = true;
			provocation.LastWoundAt = Game.GameTime;
		}
	}

	internal static bool LooksKnockedOut(Ped ped)
	{
		if (ped == null || !ped.Exists())
		{
			return false;
		}
		if (Downed.IsFinished(ped.Handle))
		{
			return false;
		}
		if (ped.IsIncapacitated)
		{
			return true;
		}
		if (!ped.IsDead)
		{
			return false;
		}
		if (GunMelee.KnockedOutByGunButt(ped))
		{
			return true;
		}
		uint num = PED.GET_PED_CAUSE_OF_DEATH(ped.Handle);
		if (num == 0)
		{
			return false;
		}
		uint num2 = WEAPON.GET_WEAPONTYPE_GROUP(num);
		if (num2 != 2685387236u)
		{
			return num2 == 308416707;
		}
		return true;
	}

	private static bool ReallyDead(Ped ped)
	{
		if (ped.IsDead)
		{
			return !LooksKnockedOut(ped);
		}
		return false;
	}

	private static bool Executed(int handle)
	{
		if (Downed.IsFinished(handle))
		{
			return !Downed.WasKicked(handle);
		}
		return false;
	}

	internal bool KoByYou(Ped ped, Ped player)
	{
		if (ped == null || player == null || !ped.Exists() || !player.Exists())
		{
			return false;
		}
		if (LawTook(ped.Handle))
		{
			return false;
		}
		if (ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(ped.Handle, player.Handle, p2: true, p3: true))
		{
			return true;
		}
		if (_hitByYouAt.TryGetValue(ped.Handle, out var value) && Game.GameTime - value < 10000)
		{
			return true;
		}
		return GrappledBy(ped, player);
	}

	private void Mark(int handle, Action<Provocation> what)
	{
		Provocation provocation = RememberStranger(handle);
		if (provocation != null)
		{
			what(provocation);
		}
	}

	private bool OnHorseHurt(int handle)
	{
		Ped horse = Entity.FromHandle(handle) as Ped;
		if (horse == null || !horse.Exists() || horse.IsHuman || !horse.Model.IsHorse)
		{
			return false;
		}
		int num = PED._GET_RIDER_OF_MOUNT(handle, p1: true);
		if (num == 0)
		{
			num = (from p in PedsAround(Game.Player.Character)
				where p.Position.DistanceTo(horse.Position) < 25f
				select p).FirstOrDefault((Ped p) => p.IsHuman && !p.IsPlayer && PED._GET_LAST_MOUNT(p.Handle) == handle)?.Handle ?? 0;
		}
		if (num != 0 && num != Game.Player.Character.Handle)
		{
			_horseRiders[handle] = num;
			_horseHurtAt[handle] = Game.GameTime;
		}
		return true;
	}

	private void UpdateHorses()
	{
		foreach (int item in _horseRiders.Keys.ToList())
		{
			Ped ped = Entity.FromHandle(item) as Ped;
			if (ped == null || !ped.Exists())
			{
				_horseRiders.Remove(item);
			}
			else
			{
				if (!ped.IsDead)
				{
					continue;
				}
				int rider = _horseRiders[item];
				bool num = PED.GET_PED_SOURCE_OF_DEATH(item) == Game.Player.Character.Handle || (_horseHurtAt.TryGetValue(item, out var value) && Game.GameTime - value < 60000);
				_horseHurtAt.Remove(item);
				if (!num)
				{
					_horseRiders.Remove(item);
					continue;
				}
				Mark(rider, (Provocation p) =>
				{
					if (!p.HorseKilled)
					{
						Grudge(rider, p, GrudgeAction.HorseKilled);
					}
					p.HorseKilled = true;
				});
				_horseRiders.Remove(item);
			}
		}
	}

	private Provocation RememberStranger(int handle)
	{
		if (handle == 0)
		{
			return null;
		}
		if (_activeNemesisPed != null && handle == _activeNemesisPed.Handle)
		{
			return null;
		}
		Ped ped = Entity.FromHandle(handle) as Ped;
		if (ped == null || ped.IsPlayer || !ped.IsHuman || ReallyDead(ped) || Kids.IsChild(ped) || IsStoryPed(ped))
		{
			return null;
		}
		if (GameOwned(ped) && !MissionMemoryOk(ped))
		{
			return null;
		}
		if (IsLawman(ped) && RecordAt(handle) == null)
		{
			return null;
		}
		if (!_provoked.TryGetValue(handle, out var value))
		{
			NoteModel(ped);
			NemesisRecord nemesisRecord = RecordAt(handle);
			if (nemesisRecord == null)
			{
				eRelationshipType relationshipWithPed = ped.GetRelationshipWithPed(Game.Player.Character);
				if (relationshipWithPed == (eRelationshipType)2 || relationshipWithPed == (eRelationshipType)1)
				{
					return null;
				}
			}
			if (!_named.ContainsKey(handle) && Config.NamingEnabled && LookReadable(ped))
			{
				_named[handle] = NameByLook(ped);
				_namesGiven++;
			}
			if (_provoked.TryGetValue(handle, out var value2))
			{
				value = value2;
			}
			else
			{
				NemesisRecord nemesisRecord2 = ShadowFor(ped);
				Personality temper = KnownTemper(ped) ?? nemesisRecord2.Personality ?? Personalities.Pick(_rng, nemesisRecord2.Gang != null);
				value = (_provoked[handle] = new Provocation
				{
					Temper = temper,
					Shadow = nemesisRecord2,
					ModelHash = (uint)ped.Model.Hash,
					Zone = GetZoneName(ped.Position),
					Pos = ped.Position,
					Record = nemesisRecord
				});
				if (nemesisRecord == null)
				{
					RememberPerson(handle, met: false);
				}
			}
		}
		if (value.Shadow != null && value.Shadow.Personality != value.Temper)
		{
			value.Shadow.Personality = value.Temper;
			string arg = (_named.TryGetValue(handle, out var value3) ? value3.Name : handle.ToString());
			Traits.Roll(value.Shadow, Seeds.For(new NemesisRecord
			{
				Id = $"stranger:{arg}|{value.ModelHash:X8}"
			}, "traits"), null);
		}
		value.LastTime = Game.GameTime;
		bool flag = PlayerMasked(Game.Player.Character);
		float num = ((_combatants.ContainsKey(handle) || PED.IS_PED_IN_COMBAT(handle, Game.Player.Character.Handle)) ? 60f : 25f);
		if (flag)
		{
			value.SeenMasked = true;
		}
		else if (ped.Position.DistanceTo(Game.Player.Character.Position) < num)
		{
			value.SawFace = true;
		}
		MarkNamed(handle, 3);
		return value;
	}

	private static GrudgeOrigin? Qualifies(Provocation p, NemesisSettings cfg)
	{
		if (p.Wounded)
		{
			return GrudgeOrigin.Wounded;
		}
		if (p.Slashed)
		{
			return GrudgeOrigin.Slashed;
		}
		if (p.HorseKilled)
		{
			return GrudgeOrigin.HorseKilled;
		}
		if (p.HorseStolen)
		{
			return GrudgeOrigin.HorseStolen;
		}
		if (p.WagonStolen)
		{
			return GrudgeOrigin.WagonStolen;
		}
		if (p.FriendKilled)
		{
			return GrudgeOrigin.FriendKilled;
		}
		if (p.Robbed)
		{
			return GrudgeOrigin.Robbed;
		}
		if (p.KnockedOut)
		{
			return GrudgeOrigin.KnockedOut;
		}
		if (p.Kidnapped)
		{
			return GrudgeOrigin.Kidnapped;
		}
		if (p.Hits >= cfg.BeatingHits)
		{
			return GrudgeOrigin.Beaten;
		}
		if (p.Threatened)
		{
			return GrudgeOrigin.Threatened;
		}
		if (p.Insulted)
		{
			return GrudgeOrigin.Insulted;
		}
		return null;
	}

	private void UpdateGrudges(Ped player)
	{
		UpdateHorses();
		UpdateCombatGrudges(player);
		foreach (int handle in _provoked.Keys.ToList())
		{
			Provocation provocation = _provoked[handle];
			Ped ped = Entity.FromHandle(handle) as Ped;
			if ((ped != null && ped.Exists() && ped.Model.Hash != (int)provocation.ModelHash) || (provocation.Record != null && !Roster.Contains(provocation.Record)))
			{
				_provoked.Remove(handle);
				continue;
			}
			bool flag = ped != null && ped.Exists() && ReallyDead(ped);
			if (provocation.HeldForMission && !flag && ped != null && ped.Exists() && !MissionHeld(ped) && !provocation.Settled && provocation.Record == null)
			{
				provocation.HeldForMission = false;
				GrudgeLog($"SETTLE ped={handle} {WhoIs(handle)}: the mission is over - deciding now");
				SettleGrudge(handle, provocation, ped);
				if (provocation.Record == null)
				{
					_provoked.Remove(handle);
					continue;
				}
			}
			if ((!provocation.HeldForMission || !(ped != null) || !ped.Exists() || flag || !MissionHeld(ped) || !(ped.Position.DistanceTo(player.Position) < 600f)) && (((ped == null || !ped.Exists()) | flag) || ped.Position.DistanceTo(player.Position) > 150f))
			{
				if (!flag && provocation.Record == null && provocation.Score > 0f && !provocation.Settled)
				{
					SettleGrudge(handle, provocation, null);
				}
				_provoked.Remove(handle);
				continue;
			}
			if (!provocation.FoughtBack && PED.IS_PED_IN_COMBAT(handle, player.Handle))
			{
				provocation.FoughtBack = true;
			}
			if (!provocation.Fled && !provocation.FoughtBack && !ped.IsDead && PED.IS_PED_FLEEING(handle) && !ToldToFlee(handle) && !_townMen.Any((TownMan m) => m.Leaving && m.Ped != null && m.Ped.Handle == handle) && FleeingYou(ped, player))
			{
				provocation.Fled = true;
			}
			if (provocation.Fled && !provocation.FledScored)
			{
				provocation.FledScored = true;
				if (provocation.Record != null)
				{
					int hate = provocation.Record.Hate;
					int fear = provocation.Record.Fear;
					provocation.Record.Hate = Math.Max(Math.Min(provocation.Record.Hate, 10), provocation.Record.Hate - Balance.FledHateCut / 2);
					provocation.Record.AddFear(Balance.FearPerFlee);
					SaveRoster();
					Feed("FLED " + provocation.Record.Name + ": hate " + Delta(hate, provocation.Record.Hate) + "  fear " + Delta(fear, provocation.Record.Fear), Theme.Good, provocation.Record);
				}
				else
				{
					Feed(Pron.Her($"FLED {WhoIs(handle)}: ran from you - if it sticks, he'll be afraid of you (hate -{Balance.FledHateCut}, fear +{Balance.FearPerFlee})", Pron.FemaleAt(handle)), Theme.Good);
				}
			}
			Downed.Saw(ped, LooksKnockedOut(ped));
			bool flag2 = TASK.IS_PED_IN_WRITHE(handle) || (_bulletImpact.LatestWound(handle) != null && !GunMelee.KnockedOutByGunButt(ped));
			if (ped.IsDead && !provocation.KnockedOut && (provocation.Hits > 0 || KoByYou(ped, player)) && LooksKnockedOut(ped) && !flag2 && !LawTook(handle))
			{
				provocation.KnockedOut = true;
			}
			if (provocation.Hits > 0 && !provocation.KnockedOut && !LawTook(handle))
			{
				if ((!ped.IsIncapacitated && !ped.IsRagdoll) || Game.GameTime - provocation.LastHitTime >= 10000 || flag2)
				{
					provocation.DownSince = -1;
				}
				else if (provocation.DownSince < 0)
				{
					provocation.DownSince = Game.GameTime;
				}
				else if (Game.GameTime - provocation.DownSince >= 1500)
				{
					provocation.KnockedOut = true;
				}
			}
			if (provocation.KnockedOut && !provocation.KoScored)
			{
				provocation.KoScored = true;
				if (provocation.Record == null)
				{
					Grudge(handle, provocation, GrudgeAction.KnockOut);
				}
				else
				{
					CrimeSeen(handle, CrimeOf(GrudgeAction.KnockOut));
				}
			}
			if (provocation.FoughtBack && !provocation.FoughtScored)
			{
				provocation.FoughtScored = true;
				if (provocation.Record == null)
				{
					Grudge(handle, provocation, GrudgeAction.FoughtBack);
				}
			}
			if (provocation.Record != null)
			{
				GrudgeOrigin? rolledFor = Qualifies(provocation, Config);
				if (rolledFor.HasValue && (!provocation.RolledFor.HasValue || rolledFor.Value > provocation.RolledFor.Value))
				{
					provocation.RolledFor = rolledFor;
					DeepenGrudge(provocation.Record, rolledFor.Value, rolledFor.Value != GrudgeOrigin.KnockedOut);
				}
			}
			else if (!provocation.Settled && !(provocation.Score <= 0f) && (provocation.Score >= (float)Balance.GsThreshold || Game.GameTime - provocation.LastActionAt >= Balance.GsSettleSeconds * 1000))
			{
				SettleGrudge(handle, provocation, ped);
			}
		}
	}

	private void SettleGrudge(int handle, Provocation p, Ped ped)
	{
		Ped ped2 = ped ?? (Entity.FromHandle(handle) as Ped);
		if (ped2 != null && ped2.Exists() && !ReallyDead(ped2) && MissionHeld(ped2))
		{
			if (!p.HeldForMission)
			{
				p.HeldForMission = true;
				GrudgeLog($"SETTLE ped={handle} {WhoIs(handle)} score={p.Score:0}: a mission still has him - he decides when it's over");
			}
			return;
		}
		p.Settled = true;
		p.SettledScore = p.Score;
		if (_acqOf.TryGetValue(handle, out var value))
		{
			value.GrudgeSettled = true;
			value.SawFace = p.SawFace;
			value.Grudge = (int)p.Score;
			_peopleDirty = true;
		}
		GrudgeOrigin grudgeOrigin = (GrudgeOrigin)(((int?)Qualifies(p, Config)) ?? ((p.FoughtBack || _combatants.ContainsKey(handle)) ? 4 : 2));
		if (!p.SawFace)
		{
			GrudgeLog(string.Format("SETTLE ped={0} {1} score={2:0} -> {3}, no nemesis", handle, grudgeOrigin, p.Score, p.SeenMasked ? "DISGUISED" : "never got a look at you (too far)"));
			DisguiseSaves++;
			Feed(string.Format("GRUDGE {0} ({1:0}): never saw your face ({2}) -> no nemesis", WhoIs(handle), p.Score, p.SeenMasked ? "masked" : "too far off"), Theme.Good);
			return;
		}
		int num = SettleChance(p);
		int num2 = _rng.Next(100);
		bool flag = num2 < num;
		GrudgeLog(string.Format("SETTLE ped={0} {1} score={2:0} chance={3}% roll={4} -> {5}", handle, grudgeOrigin, p.Score, num, num2, flag ? "NEMESIS" : "lets it go"));
		Feed(string.Format("GRUDGE {0}: score {1:0} = {2}%{3} -> {4}", WhoIs(handle), p.Score, num, (num >= 100) ? "" : $", rolled {num2}", flag ? ("NEMESIS (" + grudgeOrigin.ToString() + ")") : "lets it go"), flag ? Theme.Blood : Theme.Dim);
		if (!flag || !MakeRoom())
		{
			return;
		}
		p.Record = CreateGrudgeNemesis(p, grudgeOrigin, handle);
		if (_followerOf.TryGetValue(handle, out var value2) && p.Record != null)
		{
			if (value2.Gang != null)
			{
				NemesisRecord record = p.Record;
				record.Gang = value2.Gang;
				record.Rank = 1;
				record.BossId = value2.Id;
				record.Hate = Math.Max(record.Hate, Hate.Initial(grudgeOrigin));
				if (record.KinId != null && FindRecord(record.KinId)?.Gang != record.Gang)
				{
					record.KinId = null;
					record.KinRelation = null;
				}
				History(record, "JOINED the " + Gangs.ById(record.Gang)?.Name + " under " + value2.Name + " - a hired gun with a grudge of his own", (170, 150, 210));
			}
			_followerOf.Remove(handle);
		}
		p.RolledFor = Qualifies(p, Config);
		if (p.Record != null)
		{
			if (p.Robbed && p.Record.TimesRobbed == 0)
			{
				p.Record.TimesRobbed = 1;
				WorldPart worldPart = PartFor(p.Record, "ROBBED", "and swore to get it back");
				Vector3 position = Game.Player.Character.Position;
				try
				{
					ChronicleDeed("rob", "You robbed " + p.Record.Name, "near " + GetZoneName(position), position, p.Record.Gang, worldPart);
				}
				catch
				{
				}
			}
			if (p.KnockedOut && p.Record.TimesKnockedOutByPlayer == 0)
			{
				p.Record.TimesKnockedOutByPlayer = 1;
			}
			if (p.Kidnapped && p.Record.TimesHogtied == 0)
			{
				p.Record.TimesHogtied = 1;
			}
		}
		if (ped != null && ped.Exists())
		{
			_worldNemeses[handle] = p.Record;
		}
		if (ped != null && ped.Exists() && ped.IsDead)
		{
			_knockedOutWorld.Add(handle);
		}
	}

	private bool MakeRoom()
	{
		List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.IsAlive && !n.PresumedDead && n.Origin != GrudgeOrigin.GangMember).ToList();
		if (list.Count < Config.MaxLivingNemeses)
		{
			return true;
		}
		NemesisRecord nemesisRecord = (from n in list
			where n.TimesAmbushed == 0 && n.TimesKilledPlayer == 0 && n.Scars.Count == 0 && n.Rank <= 1 && !_worldNemeses.ContainsValue(n) && n != ActiveRecord
			orderby n.Hate, n.KilledPlayerAt
			select n).FirstOrDefault();
		if (nemesisRecord == null)
		{
			GrudgeNotice("Too many men already want you dead - this one lets it go. (You can raise the limit in the settings - " + KeyCombo.SettingsText + ".)");
			return false;
		}
		RemoveRecord(nemesisRecord, "MakeRoom: the roster was full - least invested man dropped");
		GrudgeNotice(nemesisRecord.Name + " forgot about you (the roster was full).");
		return true;
	}

	private void DeepenGrudge(NemesisRecord rec, GrudgeOrigin origin, bool bump = true)
	{
		HiddenSlip(rec, (origin == GrudgeOrigin.Robbed) ? "rob" : "violence");
		rec.Touch();
		int hate = rec.Hate;
		if (bump)
		{
			int val = ((rec.Gang != null || !rec.Personality.HasValue) ? Hate.Initial(origin) : Personalities.StartingHate(rec.Personality.Value, origin));
			rec.Hate = Math.Max(rec.Hate, val);
			rec.AddHate(5);
			if (FistOrigin(origin))
			{
				CapScuffle(rec, hate);
			}
		}
		if (rec.Origin == GrudgeOrigin.GangMember || (rec.Origin != GrudgeOrigin.Killed && origin > rec.Origin))
		{
			if (rec.Origin == GrudgeOrigin.GangMember || string.IsNullOrEmpty(rec.KillLocation))
			{
				rec.KillLocation = GetZoneName(Game.Player.Character.Position);
			}
			rec.Origin = origin;
		}
		SaveRoster();
		Feed($"{origin.ToString().ToUpperInvariant()} {rec.Name}: hate {Delta(hate, rec.Hate)} ({rec.HateTier})", Theme.Warn, rec);
		if (Hate.TierOf(rec.Hate) > Hate.TierOf(hate))
		{
			GrudgeNotice(rec.FullName + "'s hatred deepens. He's " + rec.HateTier.ToString().ToLowerInvariant() + " now.");
		}
	}

	internal static bool FistOrigin(GrudgeOrigin o)
	{
		if (o != GrudgeOrigin.Greeted && o != GrudgeOrigin.Insulted && o != GrudgeOrigin.Threatened && o != GrudgeOrigin.Beaten)
		{
			return o == GrudgeOrigin.KnockedOut;
		}
		return true;
	}

	internal static int FistCap(NemesisRecord r)
	{
		bool flag = r.Personality == Personality.Hothead || r.Personality == Personality.Proud;
		if (flag && r.Aggression >= 75)
		{
			return Balance.FistCapRage;
		}
		if (flag && r.Aggression >= 60)
		{
			return Balance.FistCapViolent;
		}
		if (flag || r.Aggression >= 70)
		{
			return Balance.FistCapHot;
		}
		return Balance.FistCap;
	}

	internal static void CapScuffle(NemesisRecord r, int before)
	{
		if (!Gangs.Orders(r))
		{
			r.Hate = Math.Min(r.Hate, Math.Max(before, FistCap(r)));
		}
	}

	internal static int TraitSpread(NemesisRecord r)
	{
		return (r.Aggression - 50) / 3 + ((r.Disposition == Disposition.Surly) ? 8 : ((r.Disposition == Disposition.Friendly) ? (-8) : 0)) + ((r.Devotion == Devotion.Devout) ? (-4) : 0);
	}

	internal void KnockoutReaction(NemesisRecord rec)
	{
		int hate = rec.Hate;
		bool flag = rec.Id != null && _lastKoAt.TryGetValue(rec.Id, out var value) && Game.GameTime - value < 300000;
		if (rec.Id != null)
		{
			_lastKoAt[rec.Id] = Game.GameTime;
		}
		bool num = rec.Personality == Personality.Coward || rec.Personality == Personality.Cold || EffectiveFear(rec) * 2 >= rec.Hate;
		bool num2 = rec.Personality == Personality.Cold || EffectiveFear(rec) * 2 >= rec.Hate;
		int num3 = Balance.KoHate;
		if (flag)
		{
			num3 /= 2;
		}
		if (num2)
		{
			num3 /= 2;
		}
		rec.AddHate(num3);
		rec.AddFear(Balance.FearPerKnockout);
		if (num)
		{
			rec.Fear = Math.Min(100, rec.Fear + 5);
		}
		CapScuffle(rec, hate);
		Remember(rec, "Shame", flag ? 70 : 55, flag ? "you knocked him cold - again" : "you knocked him out cold");
		if (rec.Needs != null)
		{
			rec.Needs["Violence"] = Math.Max(0, Mind.N(rec, "Violence") - 30);
		}
	}

	internal void FitKinToLife(NemesisRecord rec)
	{
		if (rec.KinId == null)
		{
			return;
		}
		NemesisRecord nemesisRecord = FindRecord(rec.KinId);
		if (nemesisRecord != null)
		{
			string text = Backstory.RelationForAge(rec, nemesisRecord);
			if (text == null)
			{
				GrudgeLog($"HISTORY {rec.Name}: no kin tie to {nemesisRecord.Name} (born {rec.BornYear} / {nemesisRecord.BornYear})");
				rec.KinId = null;
				rec.KinRelation = null;
			}
			else if (text != rec.KinRelation)
			{
				GrudgeLog($"HISTORY {rec.Name}: {rec.KinRelation} -> {text} of {nemesisRecord.Name} (born {rec.BornYear} / {nemesisRecord.BornYear})");
				rec.KinRelation = text;
			}
		}
	}

	private NemesisRecord CreateGrudgeNemesis(Provocation p, GrudgeOrigin origin, int handle = 0)
	{
		NemesisRecord nemesisRecord = NewRecord(p.ModelHash, p.Zone);
		nemesisRecord.Touch();
		if (handle != 0 && Entity.FromHandle(handle) is Ped ped && ped.Exists())
		{
			KeepOutfit(ped, nemesisRecord);
		}
		StartRest(nemesisRecord);
		if (handle != 0 && _named.TryGetValue(handle, out var value))
		{
			GrudgeLog("NAMING new nemesis keeps the name " + value.Name);
			if (nemesisRecord.KinId != null && nemesisRecord.Name.LastIndexOf(' ') > 0 && value.Name.LastIndexOf(' ') > 0 && nemesisRecord.Name.Substring(nemesisRecord.Name.LastIndexOf(' ')) != value.Name.Substring(value.Name.LastIndexOf(' ')))
			{
				GrudgeLog("NAMING " + value.Name + ": no kin tie to " + FindRecord(nemesisRecord.KinId)?.Name + " (a different family name)");
				nemesisRecord.KinId = null;
				nemesisRecord.KinRelation = null;
			}
			nemesisRecord.Name = value.Name;
			if (value.Title != null)
			{
				nemesisRecord.Title = value.Title;
			}
			_named.Remove(handle);
		}
		nemesisRecord.TimesKilledPlayer = 0;
		nemesisRecord.Origin = origin;
		nemesisRecord.HasOrigin = true;
		nemesisRecord.OriginX = p.Pos.X;
		nemesisRecord.OriginY = p.Pos.Y;
		nemesisRecord.OriginZ = p.Pos.Z;
		nemesisRecord.TimesAntagonized = p.Insults;
		nemesisRecord.TimesGreeted = p.Greetings;
		nemesisRecord.Personality = p.Temper;
		CopyTraits(p.Shadow, nemesisRecord);
		FitKinToLife(nemesisRecord);
		nemesisRecord.Hate = ((nemesisRecord.Gang != null) ? Hate.Initial(origin) : Personalities.InitialHate(p.Temper, origin, _rng));
		nemesisRecord.Hate = Math.Min(100, nemesisRecord.Hate + (int)Math.Max(0f, (p.Score - (float)Balance.GsThreshold) / 3f));
		if (nemesisRecord.Gang == null && nemesisRecord.TraitsRolled)
		{
			nemesisRecord.Hate = Math.Max(5, Math.Min(100, nemesisRecord.Hate + TraitSpread(nemesisRecord)));
		}
		if (nemesisRecord.Gang == null && nemesisRecord.TraitsRolled && MoneyOrigin(origin))
		{
			nemesisRecord.Hate = Math.Max(5, Math.Min(100, nemesisRecord.Hate + ((nemesisRecord.Wealth == Wealth.Poor) ? Balance.RobbedPoorShift : ((nemesisRecord.Wealth == Wealth.Rich) ? (-Balance.RobbedRichShift) : 0))));
		}
		if (FistOrigin(origin))
		{
			nemesisRecord.Hate = Math.Min(nemesisRecord.Hate, FistCap(nemesisRecord));
		}
		if (p.Fled && !p.FoughtBack)
		{
			nemesisRecord.Hate = Math.Max(Math.Min(nemesisRecord.Hate, 10), nemesisRecord.Hate - Balance.FledHateCut);
			nemesisRecord.AddFear(Balance.FearPerFlee);
		}
		if (p.Ledger.Count > 0)
		{
			History(nemesisRecord, "as a stranger: " + string.Join(", ", p.Ledger), Theme.Dim);
		}
		History(nemesisRecord, string.Format("BECAME YOUR NEMESIS ({0}): grudge {1:0}  ->  hate {2}, fear {3}{4}", origin, p.Score, nemesisRecord.Hate, nemesisRecord.Fear, p.Fled ? "  (he ran)" : ""), Theme.Blood);
		Roster.Add(nemesisRecord);
		_bulletImpact.TagVictim(handle, nemesisRecord.Id, nemesisRecord.FullName ?? "");
		ForgetPerson(handle, nemesisRecord.Name);
		WorldPart worldPart = PartFor(nemesisRecord, "NEMESIS", nemesisRecord.GrudgeSummary);
		worldPart.Effects.Add($"hate {nemesisRecord.Hate} ({nemesisRecord.HateTier})");
		if (nemesisRecord.Fear > 0)
		{
			worldPart.Effects.Add($"fear {nemesisRecord.Fear}");
		}
		ChronicleDeed("nemesis", nemesisRecord.Name + " swore vengeance on you", (nemesisRecord.KillLocation != null) ? ("in " + nemesisRecord.KillLocation) : "", p.Pos, nemesisRecord.Gang, worldPart);
		SaveRoster();
		GrudgeNotice("A nemesis rises: " + nemesisRecord.FullName + ". " + origin switch
		{
			GrudgeOrigin.Beaten => "He'll remember that beating.", 
			GrudgeOrigin.KnockedOut => "He'll remember waking up in the dirt.", 
			GrudgeOrigin.WagonStolen => "You took his wagon - and his living with it.", 
			GrudgeOrigin.HorseStolen => "You rode off on his horse. He'll walk a long way to find you.", 
			GrudgeOrigin.Robbed => "He'll want back what you took, and then some.", 
			GrudgeOrigin.Kidnapped => "He'll remember the rope.", 
			GrudgeOrigin.HorseKilled => "You killed his horse. He won't let that go.", 
			GrudgeOrigin.Slashed => "He'll remember the feel of your blade.", 
			GrudgeOrigin.Wounded => "He'll remember who put that hole in him.", 
			_ => "He won't forget those words.", 
		});
		return nemesisRecord;
	}

	private void UpdateWorldNemeses(Ped player)
	{
		PollFactionKills();
		foreach (int item in _worldNemeses.Keys.ToList())
		{
			NemesisRecord nemesisRecord = _worldNemeses[item];
			Ped ped = Entity.FromHandle(item) as Ped;
			if (!Roster.Contains(nemesisRecord) || !nemesisRecord.IsAlive || ped == null || !ped.Exists() || (ped.Position.DistanceTo(player.Position) > 300f && !ENTITY.IS_ENTITY_A_MISSION_ENTITY(item)))
			{
				_worldNemeses.Remove(item);
				_knockedOutWorld.Remove(item);
				continue;
			}
			Downed.Saw(ped, LooksKnockedOut(ped));
			NoteHeld(ped);
			if (ReallyDead(ped))
			{
				_worldNemeses.Remove(item);
				_knockedOutWorld.Remove(item);
				if (!nemesisRecord.PresumedDead)
				{
					ResolveNemesisDeath(ped, nemesisRecord, Executed(item));
				}
			}
			else if (!ped.IsDead)
			{
				_knockedOutWorld.Remove(item);
			}
			else if (!_knockedOutWorld.Contains(item) && !KoByYou(ped, player))
			{
				_knockedOutWorld.Add(item);
			}
			else if (_knockedOutWorld.Add(item))
			{
				int hate = nemesisRecord.Hate;
				int fear = nemesisRecord.Fear;
				nemesisRecord.TimesKnockedOutByPlayer++;
				nemesisRecord.Touch();
				nemesisRecord.AddYourNotoriety(10);
				KnockoutReaction(nemesisRecord);
				Feed("KNOCKED OUT " + nemesisRecord.Name + ": hate " + Delta(hate, nemesisRecord.Hate) + "  fear " + Delta(fear, nemesisRecord.Fear), Theme.Warn, nemesisRecord);
				SaveRoster();
				GrudgeNotice("You knocked " + nemesisRecord.Name + " out cold. He'll wake up angrier.");
				WorldPart worldPart = PartFor(nemesisRecord, "KNOCKED OUT", nemesisRecord.Title);
				worldPart.Effects.Add($"hate {hate} -> {nemesisRecord.Hate}");
				worldPart.Effects.Add($"fear {fear} -> {nemesisRecord.Fear}");
				ChronicleDeed("ko", "You knocked out " + nemesisRecord.Name, "near " + GetZoneName(ped.Position), ped.Position, nemesisRecord.Gang, worldPart);
			}
		}
	}

	internal static bool MoneyOrigin(GrudgeOrigin o)
	{
		if (o != GrudgeOrigin.Robbed && o != GrudgeOrigin.HorseStolen)
		{
			return o == GrudgeOrigin.WagonStolen;
		}
		return true;
	}

	private GrudgeOrigin OriginForKiller(Provocation p)
	{
		if (p == null)
		{
			return GrudgeOrigin.Killed;
		}
		GrudgeOrigin? grudgeOrigin = Qualifies(p, Config);
		if (!grudgeOrigin.HasValue)
		{
			if (p.Insults <= 0 && !p.Escalated)
			{
				return GrudgeOrigin.Killed;
			}
			return GrudgeOrigin.Insulted;
		}
		return grudgeOrigin.GetValueOrDefault();
	}

	private void PruneProvocations()
	{
		if (Game.GameTime < _nextPruneTime)
		{
			return;
		}
		_nextPruneTime = Game.GameTime + 10000;
		Downed.Prune();
		foreach (int item in _nemesisBodies.Keys.ToList())
		{
			if (!(Entity.FromHandle(item) is Ped ped) || !ped.Exists())
			{
				_nemesisBodies.Remove(item);
			}
		}
		foreach (int item2 in (from kv in _provoked
			where (kv.Value.Record == null && Game.GameTime - kv.Value.LastTime > 600000) || !ENTITY.DOES_ENTITY_EXIST(kv.Key)
			select kv.Key).ToList())
		{
			_provoked.Remove(item2);
		}
		foreach (int item3 in _knockedOutWorld.Where(Gone).ToList())
		{
			_knockedOutWorld.Remove(item3);
		}
		foreach (int item4 in _restrainedAt.Keys.Where((int h) => Gone(h) || Game.GameTime - _restrainedAt[h] > 60000).ToList())
		{
			_restrainedAt.Remove(item4);
		}
		foreach (int item5 in _robbedAt.Keys.Where((int h) => Gone(h) || Game.GameTime - _robbedAt[h] > 60000).ToList())
		{
			_robbedAt.Remove(item5);
		}
		foreach (string item6 in _lastKoAt.Keys.Where((string k) => Game.GameTime - _lastKoAt[k] > 300000).ToList())
		{
			_lastKoAt.Remove(item6);
		}
		foreach (int item7 in _combatants.Keys.Where(Gone).ToList())
		{
			_combatants.Remove(item7);
			_shotAtAt.Remove(item7);
		}
		if (_errorLoggedAt.Count > 200)
		{
			_errorLoggedAt.Clear();
		}
		static bool Gone(int h)
		{
			return !ENTITY.DOES_ENTITY_EXIST(h);
		}
	}

	private void NemesisProvoked(bool insult)
	{
		if (Game.GameTime - _lastNemesisProvokeTime < 1500)
		{
			return;
		}
		_lastNemesisProvokeTime = Game.GameTime;
		NemesisRecord activeRecord = ActiveRecord;
		int hate = activeRecord.Hate;
		if (!insult && StandoffGreeted(activeRecord))
		{
			return;
		}
		if (insult && _enc != null && _enc.StandoffUntil > 0)
		{
			_enc.StandoffUntil = -1;
		}
		if (insult && _enc != null && !_enc.Engaged && !_enc.Surrendered && _activeNemesisPed != null && _enc.EngageAt == 0)
		{
			_enc.Spotted = true;
			_enc.EngageAt = Game.GameTime + 2200;
			GrudgeLog("ENCOUNTER " + activeRecord.Name + " antagonized - words first, the fight in 2 s");
		}
		if (insult)
		{
			activeRecord.TimesAntagonized++;
			activeRecord.Fury++;
			activeRecord.AddHate(5);
			CapScuffle(activeRecord, hate);
			if (activeRecord.Fury >= 3)
			{
				activeRecord.Fury = 0;
				activeRecord.AddHate(5);
				CapScuffle(activeRecord, hate);
				ShowSubtitle(activeRecord.Name + " (enraged): \"That's it. No more talkin'.\"");
			}
			else
			{
				ShowSubtitle(activeRecord.Name + ": \"" + Taunts.AntagonizeReply(_rng) + "\"");
			}
			SaveRoster();
			Feed(insult ? string.Format("ANTAGONIZE {0} (fighting you): hate {1}  fury {2}/{3}{4}", activeRecord.Name, Delta(hate, activeRecord.Hate), activeRecord.Fury, 3, (activeRecord.Fury == 0) ? "  -> ENRAGED" : "") : $"GREET {activeRecord.Name} (fighting you): hate {Delta(hate, activeRecord.Hate)}  fury {activeRecord.Fury}/{3}", insult ? Theme.Warn : Theme.Good, activeRecord);
		}
		else
		{
			activeRecord.TimesGreeted++;
			activeRecord.Fury = Math.Max(0, activeRecord.Fury - 1);
			ApplyToRecord(activeRecord, GrudgeAction.Greet);
			ShowSubtitle(activeRecord.Name + ": \"" + Taunts.GreetReply(_rng) + "\"");
		}
	}

	private unsafe void DetectAntagonizeFallback()
	{
		if (_enc == null || _enc.Engaged)
		{
			return;
		}
		int num = 0;
		bool num2 = PLAYER.GET_PLAYER_INTERACTION_TARGET_ENTITY(Game.Player.Handle, &num, p2: false, p3: false) && num == _activeNemesisPed.Handle;
		bool flag = PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(Game.Player.Handle, _activeNemesisPed.Handle);
		if (!num2 && !flag)
		{
			return;
		}
		if (PanelButtonsHeld)
		{
			if (JustPressed((eInputType)648122183u) || JustPressed((eInputType)4131002361u))
			{
				GrudgeLog("PROVOKE a press on him ignored - the questioning panel's buttons");
			}
		}
		else if (JustPressed((eInputType)648122183u))
		{
			NemesisProvoked(insult: true);
		}
		else if (JustPressed((eInputType)4131002361u))
		{
			NemesisProvoked(insult: false);
		}
	}

	private static bool JustPressed(eInputType input)
	{
		if (!Game.IsControlJustPressed(input))
		{
			return Game.IsDisabledControlJustPressed(input);
		}
		return true;
	}

	internal static float WeightOf(GrudgeAction a)
	{
		return a switch
		{
			GrudgeAction.Greet => Balance.GsGreet, 
			GrudgeAction.EmoteGreet => Balance.GsGreet * 0.66f, 
			GrudgeAction.Defuse => Balance.GsDefuse, 
			GrudgeAction.Insult => Balance.GsInsult, 
			GrudgeAction.Taunt => Balance.GsInsult * 0.55f, 
			GrudgeAction.DrawOn => Balance.GsDrawOn, 
			GrudgeAction.Intimidate => Balance.GsIntimidate, 
			GrudgeAction.StickUp => Balance.GsStickUp, 
			GrudgeAction.StickUpCalm => Balance.GsStickUp * 0.7f, 
			GrudgeAction.Punch => Balance.GsPunch, 
			GrudgeAction.KnockOut => Balance.GsKnockOut, 
			GrudgeAction.Hogtie => Balance.GsHogtie, 
			GrudgeAction.Robbed => Balance.GsRobbed, 
			GrudgeAction.HorseStolen => Balance.GsHorseStolen, 
			GrudgeAction.WagonStolen => Balance.GsHorseStolen * 0.875f, 
			GrudgeAction.Slashed => Balance.GsSlashed, 
			GrudgeAction.HorseKilled => Balance.GsSlashed, 
			GrudgeAction.Wounded => Balance.GsWounded, 
			GrudgeAction.FoughtBack => Balance.GsFoughtBack, 
			GrudgeAction.ShotAt => Balance.GsShotAt, 
			GrudgeAction.ComradeKilled => Balance.GsComradeKilled, 
			GrudgeAction.FriendInsulted => 5f, 
			GrudgeAction.FriendHurt => 22f, 
			GrudgeAction.FriendKilled => 65f, 
			GrudgeAction.FriendThreatened => 12f, 
			GrudgeAction.Bumped => 10f, 
			_ => 0f, 
		};
	}

	private static bool Social(GrudgeAction a)
	{
		return a <= GrudgeAction.StickUpCalm;
	}

	private static (float mult, string why) FriendMult(Provocation p)
	{
		string item = p.Temper.ToString().ToLowerInvariant();
		float num;
		switch (p.Temper)
		{
		case Personality.Loyal:
			num = 1.4f;
			break;
		case Personality.Hothead:
			num = 1.3f;
			break;
		case Personality.Proud:
			num = 1.2f;
			break;
		case Personality.Greedy:
			num = 0.9f;
			break;
		case Personality.Cold:
		case Personality.Drifter:
			num = 0.8f;
			break;
		case Personality.Coward:
			num = 0.6f;
			break;
		default:
			num = 1f;
			break;
		}
		if (p.Shadow != null && p.Shadow.TraitsRolled)
		{
			num *= 0.9f + (float)p.Shadow.Aggression / 500f;
		}
		return (mult: num, why: item);
	}

	internal static float TemperMult(Personality t, GrudgeAction a)
	{
		bool flag = a == GrudgeAction.Insult || a == GrudgeAction.Taunt;
		bool flag2 = a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet || a == GrudgeAction.Defuse;
		bool flag3 = flag || a == GrudgeAction.KnockOut || a == GrudgeAction.Hogtie || a == GrudgeAction.Punch;
		bool flag4 = a == GrudgeAction.Robbed || a == GrudgeAction.StickUp || a == GrudgeAction.StickUpCalm || a == GrudgeAction.HorseStolen || a == GrudgeAction.WagonStolen;
		switch (t)
		{
		case Personality.Proud:
			if (!flag3)
			{
				if (!flag2)
				{
					return 1f;
				}
				return 0.7f;
			}
			return 1.5f;
		case Personality.Hothead:
			if (!flag2)
			{
				return 1.3f;
			}
			return 0.5f;
		case Personality.Greedy:
			if (!flag4)
			{
				if (!flag2)
				{
					return 0.85f;
				}
				return 1f;
			}
			return 1.6f;
		case Personality.Coward:
			if (!flag2)
			{
				if (!flag)
				{
					return 0.8f;
				}
				return 0.6f;
			}
			return 1.5f;
		case Personality.Drifter:
			if (!flag2)
			{
				return 0.7f;
			}
			return 1.5f;
		case Personality.Cold:
			if (!flag2)
			{
				return 0.9f;
			}
			return 0.8f;
		default:
			return 1f;
		}
	}

	internal void CrimeSeen(int handle, string crime)
	{
		if (crime == null)
		{
			return;
		}
		Ped ped = Entity.FromHandle(handle) as Ped;
		try
		{
			Witness(crime, handle, (ped != null && ped.Exists()) ? ped.Position : Game.Player.Character.Position);
		}
		catch (Exception ex)
		{
			GrudgeLog("WITNESS failed: " + ex.Message);
		}
		bool flag = false;
		try
		{
			flag = PlayerMasked(Game.Player.Character);
		}
		catch
		{
		}
		if (flag)
		{
			return;
		}
		try
		{
			AffiliateWronged(handle, crime);
		}
		catch
		{
		}
		if (crime == "punch")
		{
			long num = GameMinutesNow();
			if (_beatCounted.TryGetValue(handle, out var value) && num >= value && num - value < 5)
			{
				_beatCounted[handle] = num;
				return;
			}
			_beatCounted[handle] = num;
		}
		CountYourCrime(crime);
	}

	private void Grudge(int handle, Provocation p, GrudgeAction a)
	{
		if (p == null)
		{
			return;
		}
		if (p.Record == null)
		{
			try
			{
				Liking(handle, a);
			}
			catch
			{
			}
		}
		if (p.Record == null && !Social(a) && a < GrudgeAction.FriendInsulted)
		{
			try
			{
				LinkGroupOnce(handle);
			}
			catch
			{
			}
		}
		if (a == GrudgeAction.FriendKilled)
		{
			p.FriendKilled = true;
		}
		if (a > GrudgeAction.Defuse && a < GrudgeAction.FriendInsulted)
		{
			NoDeed(handle, $"you dealt with them badly ({a})");
		}
		CrimeSeen(handle, CrimeOf(a));
		if (a < GrudgeAction.FriendInsulted || a == GrudgeAction.Bumped)
		{
			NoteDealt(handle);
		}
		if (p.Record != null)
		{
			p.LastActionAt = Game.GameTime;
			ApplyToRecord(p.Record, a);
			return;
		}
		float score = p.Score;
		float num;
		string text;
		if (p.Shadow != null)
		{
			(num, text) = ReactionMult(p.Shadow, a);
		}
		else
		{
			float num2 = TemperMult(p.Temper, a);
			string text2 = p.Temper.ToString().ToLowerInvariant();
			text = text2;
			num = num2;
		}
		if (a == GrudgeAction.FriendKilled || a == GrudgeAction.FriendHurt || a == GrudgeAction.FriendThreatened)
		{
			(num, text) = FriendMult(p);
		}
		float num3 = (float)Math.Round(((a == GrudgeAction.Wounded && p.Wounded) ? Balance.GsShotAgain : WeightOf(a)) * num);
		bool flag = a == GrudgeAction.Wounded || a == GrudgeAction.Slashed || a == GrudgeAction.HorseKilled || a == GrudgeAction.KnockOut || a == GrudgeAction.Robbed || a == GrudgeAction.FriendKilled;
		if (num3 > 0f && !flag)
		{
			Ped ped = Entity.FromHandle(handle) as Ped;
			float num4 = ((ped != null && ped.Exists()) ? RepAt(ped.Position) : 0f);
			if (num4 >= 1f)
			{
				float num5 = RepGrudgeMult(num4, p.Temper.ToString());
				num3 = (float)Math.Round(num3 * num5);
				text += $", infamy x{num5:0.00}";
			}
			string town = ((ped != null && ped.Exists()) ? (_currentTown ?? TownAt(ped.Position)) : null);
			float num6 = GoodRepGrudgeMult(town);
			if (num6 < 0.999f)
			{
				num3 = (float)Math.Round(num3 * num6);
				text += $", good name x{num6:0.00}";
			}
		}
		p.Score = Math.Max(0f, Math.Min(100f, p.Score + num3));
		bool flag2 = p.Wounded || p.Slashed || p.KnockedOut || p.Robbed || p.Kidnapped || p.HorseKilled || p.HorseStolen || p.WagonStolen || p.FriendKilled || p.Hits > 0;
		bool flag3 = a == GrudgeAction.ShotAt || a == GrudgeAction.ComradeKilled || a == GrudgeAction.FoughtBack;
		if (flag3 && !flag2 && p.Score > Balance.GsUnhitCap)
		{
			p.Score = Math.Max(score, Balance.GsUnhitCap);
			text += ", never hit - capped";
		}
		bool flag4 = p.Slashed || p.KnockedOut || p.Robbed || p.Kidnapped || p.HorseKilled || p.HorseStolen || p.WagonStolen || p.FriendKilled || p.Hits > 0;
		if ((p.Wounded || a == GrudgeAction.Wounded) && p.ShotAgainCount == 0 && !flag4 && ((a == GrudgeAction.Wounded) | flag3) && p.Score > Balance.GsWoundCap)
		{
			p.Score = Math.Max(score, Balance.GsWoundCap);
			text += ", one wound - a roll";
		}
		p.LastActionAt = Game.GameTime;
		if (num3 > 0f && !Social(a))
		{
			p.LastHarmAt = Game.GameTime;
		}
		if (num3 > 0f && (!p.Settled || p.Score - p.SettledScore >= Balance.GsReopen))
		{
			p.Settled = false;
		}
		if (a == GrudgeAction.Insult || a == GrudgeAction.Taunt)
		{
			p.Insults++;
			p.InsultStreak++;
			p.Insulted = true;
			if (p.InsultStreak == 3 && !p.InsultLimitReached)
			{
				p.Score = Math.Min(100f, p.Score + 4f);
			}
			else if (p.InsultStreak >= 4)
			{
				p.InsultLimitReached = true;
			}
		}
		if (a == GrudgeAction.StickUp || a == GrudgeAction.StickUpCalm || a == GrudgeAction.Intimidate || a == GrudgeAction.DrawOn)
		{
			p.Threatened = true;
		}
		if (a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet)
		{
			p.Greetings++;
			p.InsultStreak = 0;
		}
		p.Ledger.Add(string.Format("{0}{1:0} {2}", (num3 >= 0f) ? "+" : "", num3, ActionName(a)));
		if (p.Ledger.Count > 6)
		{
			p.Ledger.RemoveAt(0);
		}
		NemesisMod nemesisMod = this;
		string text3 = Pron.Her(string.Format("{0} {1}: grudge {2:0} -> {3:0}  (x{4:0.00} {5}){6}", ActionName(a).ToUpperInvariant(), WhoIs(handle), score, p.Score, num, text, (p.Score >= (float)Balance.GsThreshold) ? "  NEMESIS LINE" : ""), Pron.FemaleAt(handle));
		(int r, int g, int b) value;
		if (num3 < 0f)
		{
			value = Theme.Good;
		}
		else
		{
			value = ((p.Score >= (float)Balance.GsThreshold) ? Theme.Blood : Theme.Warn);
		}
		nemesisMod.Feed(text3, value);
	}

	private (int n, float bonus, string note) GreetStreak(NemesisRecord rec, GrudgeAction a)
	{
		if (rec.Id == null || (a != GrudgeAction.Greet && a != GrudgeAction.EmoteGreet && a != GrudgeAction.Defuse))
		{
			return (n: 0, bonus: 0f, note: null);
		}
		DateTime now = DateTime.Now;
		_greetStreak.TryGetValue(rec.Id, out (int, DateTime) value);
		if (value.Item1 > 0 && (now - value.Item2).TotalSeconds < 1.5)
		{
			return (n: -1, bonus: 0f, note: null);
		}
		int num = ((value.Item1 <= 0 || !((now - value.Item2).TotalMinutes < (double)Balance.GreetStreakMinutes)) ? 1 : (value.Item1 + 1));
		_greetStreak[rec.Id] = (num, now);
		if (num == 3)
		{
			return (n: num, bonus: Balance.GreetStreakBonus, note: "3rd greet - warming to you");
		}
		if (num > 6)
		{
			return (n: num, bonus: 0f, note: "greeted to death - nothing more");
		}
		if (num > 3)
		{
			return (n: num, bonus: 0f, note: $"greet {num} - worth less now");
		}
		return (n: num, bonus: 0f, note: (num == 2) ? "2nd greet" : null);
	}

	private void ApplyToRecord(NemesisRecord rec, GrudgeAction a)
	{
		switch (a)
		{
		case GrudgeAction.Insult:
		case GrudgeAction.Taunt:
			HiddenSlip(rec, "antagonize");
			break;
		case GrudgeAction.DrawOn:
		case GrudgeAction.StickUp:
		case GrudgeAction.StickUpCalm:
			HiddenSlip(rec, "violence");
			break;
		}
		if (!Social(a))
		{
			return;
		}
		(int, float, string) tuple = GreetStreak(rec, a);
		if (tuple.Item1 < 0)
		{
			return;
		}
		rec.Touch();
		int hate = rec.Hate;
		int fear = rec.Fear;
		float num = 0f;
		float num2;
		switch (a)
		{
		case GrudgeAction.Greet:
			if (tuple.Item1 > 6)
			{
				num2 = 0f;
			}
			else
			{
				num2 = ((tuple.Item1 > 3) ? (-1f) : (-2f - tuple.Item2));
			}
			break;
		case GrudgeAction.EmoteGreet:
			if (tuple.Item1 > 6)
			{
				num2 = 0f;
			}
			else
			{
				num2 = ((tuple.Item1 > 3) ? (-1f) : (-1.5f - tuple.Item2));
			}
			break;
		case GrudgeAction.Defuse:
			if (tuple.Item1 > 6)
			{
				num2 = 0f;
			}
			else
			{
				num2 = ((tuple.Item1 > 3) ? (-1.5f) : (-5f));
			}
			break;
		case GrudgeAction.Insult:
			num2 = 5f;
			rec.TimesAntagonized++;
			break;
		case GrudgeAction.Taunt:
			num2 = 3f;
			break;
		case GrudgeAction.DrawOn:
			num2 = 3f;
			num = 2f;
			break;
		case GrudgeAction.Intimidate:
			num2 = 4f;
			num = 3f;
			break;
		case GrudgeAction.FriendThreatened:
			num2 = 4f;
			break;
		default:
			num2 = 6f;
			num = 2f;
			break;
		}
		var (num3, text) = ReactionMult(rec, a);
		if (rec.Gang != null && Gangs.Orders(rec) && num2 < 0f)
		{
			num2 = 0f;
		}
		if (num2 < 0f)
		{
			num3 = Math.Max(0.5f, Math.Min(1.4f, num3));
		}
		int num4 = (int)Math.Round(num2 * num3 * ((num2 > 0f) ? Balance.HateGainScale : 1f));
		if (num4 == 0)
		{
			num4 = Math.Sign(num2);
		}
		int num5 = ((num4 < 0) ? SocialFloor(rec) : 0);
		if (num4 < 0 && rec.Hate + num4 < num5)
		{
			num4 = Math.Min(0, num5 - rec.Hate);
			if (num4 == 0)
			{
				tuple.Item3 = $"words won't move him below {num5} ({FloorWhy(rec)})";
			}
		}
		rec.Hate = Math.Max(0, Math.Min(100, rec.Hate + num4));
		if (num4 > 0)
		{
			CapScuffle(rec, hate);
		}
		if (num > 0f)
		{
			rec.AddFear((int)Math.Round(num));
		}
		SaveRoster();
		Feed(string.Format("{0} {1}: hate {2}{3}  (x{4:0.00} {5}){6}", ActionName(a).ToUpperInvariant(), rec.Name, Delta(hate, rec.Hate), (rec.Fear != fear) ? ("  fear " + Delta(fear, rec.Fear)) : "", num3, text, (tuple.Item3 != null) ? ("  - " + tuple.Item3) : ""), (rec.Hate < hate) ? Theme.Good : Theme.Warn, rec);
		_lastGreetDrop = hate - rec.Hate;
	}

	internal static int SocialFloor(NemesisRecord r)
	{
		int val = Hate.Initial(r.Origin) / 2;
		if (r.TimesKilledPlayer > 0 || r.Origin == GrudgeOrigin.Killed)
		{
			val = Math.Max(val, Hate.VengefulAt);
		}
		if (r.ScarredByYou)
		{
			val = Math.Max(val, Hate.VengefulAt - 10);
		}
		if (r.TimesRobbed > 0)
		{
			val = Math.Max(val, 25);
		}
		return Math.Min(val, Hate.MurderousAt - 5);
	}

	internal static void SoftenHate(NemesisRecord r, int cut)
	{
		if (r != null && cut > 0)
		{
			Gang gang = ((r.Gang == null) ? null : Gangs.ById(r.Gang));
			if (gang == null || !gang.OrdersNotFeelings)
			{
				int feltHate = r.FeltHate;
				r.Hate = Math.Max(Math.Min(feltHate, SocialFloor(r)), feltHate - cut);
			}
		}
	}

	internal static string FloorWhy(NemesisRecord r)
	{
		if (r.TimesKilledPlayer <= 0 && r.Origin != GrudgeOrigin.Killed)
		{
			if (!r.ScarredByYou)
			{
				if (r.TimesRobbed <= 0)
				{
					return r.Origin.ToString().ToLowerInvariant() + " grudge";
				}
				return "you robbed him";
			}
			return "you scarred him";
		}
		return "he killed you";
	}

	private static (float mult, string why) ReactionMult(NemesisRecord r, GrudgeAction a)
	{
		List<string> why = new List<string>();
		float m = 1f;
		Personality t = r.Personality ?? Personality.Cold;
		Mul(TemperMult(t, a), t.ToString().ToLowerInvariant());
		if (r.TraitsRolled)
		{
			bool num = a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet || a == GrudgeAction.Defuse;
			bool flag = a == GrudgeAction.StickUp || a == GrudgeAction.StickUpCalm;
			if (num)
			{
				float f;
				if (r.Disposition != Disposition.Friendly)
				{
					f = ((r.Disposition == Disposition.Surly) ? 0.5f : 1f);
				}
				else
				{
					f = 1.5f;
				}
				Mul(f, r.Disposition.ToString().ToLowerInvariant());
				float f2;
				if (r.Devotion != Devotion.Devout)
				{
					f2 = ((r.Devotion == Devotion.Godless) ? 0.8f : 1f);
				}
				else
				{
					f2 = 1.3f;
				}
				Mul(f2, r.Devotion.ToString().ToLowerInvariant());
				if (a != GrudgeAction.Defuse)
				{
					Mul((r.Sociability == Sociability.Outgoing) ? 1.2f : 1f, "outgoing");
				}
				if (a == GrudgeAction.Defuse)
				{
					Mul((r.Smarts == Smarts.Sharp) ? 1.1f : 1f, "sharp");
				}
			}
			else
			{
				float f3;
				if (r.Disposition == Disposition.Surly)
				{
					f3 = 1.3f;
				}
				else
				{
					f3 = ((r.Disposition == Disposition.Friendly) ? 0.8f : 1f);
				}
				Mul(f3, r.Disposition.ToString().ToLowerInvariant());
				Mul(0.8f + (float)r.Aggression / 250f, Traits.Aggr(r.Aggression).ToLowerInvariant());
				if (flag)
				{
					float f4;
					if (r.Wealth != Wealth.Poor)
					{
						f4 = ((r.Wealth == Wealth.Rich) ? 0.8f : 1f);
					}
					else
					{
						f4 = 1.3f;
					}
					Mul(f4, r.Wealth.ToString().ToLowerInvariant());
				}
			}
		}
		return (mult: m, why: (why.Count == 0) ? "no modifiers" : string.Join(", ", why));
		void Mul(float num2, string w)
		{
			if (Math.Abs(num2 - 1f) > 0.01f)
			{
				m *= num2;
				why.Add(w);
			}
		}
	}

	internal static string ActionName(GrudgeAction a)
	{
		return a switch
		{
			GrudgeAction.EmoteGreet => "greet (emote)", 
			GrudgeAction.Insult => "antagonize", 
			GrudgeAction.DrawOn => "draw on", 
			GrudgeAction.StickUp => "stick-up", 
			GrudgeAction.StickUpCalm => "stick-up (calm)", 
			GrudgeAction.KnockOut => "knocked out", 
			GrudgeAction.Hogtie => "hogtied", 
			GrudgeAction.HorseStolen => "horse stolen", 
			GrudgeAction.WagonStolen => "wagon stolen", 
			GrudgeAction.Slashed => "cut", 
			GrudgeAction.HorseKilled => "horse killed", 
			GrudgeAction.Wounded => "shot", 
			GrudgeAction.FoughtBack => "fought back", 
			GrudgeAction.ShotAt => "shot at", 
			GrudgeAction.ComradeKilled => "saw you kill a man beside him", 
			GrudgeAction.FriendInsulted => "you insulted his friend", 
			GrudgeAction.FriendHurt => "you hurt his friend", 
			GrudgeAction.FriendKilled => "you killed his friend", 
			GrudgeAction.FriendThreatened => "you held a gun on his friend", 
			_ => a.ToString().ToLowerInvariant(), 
		};
	}

	private NemesisRecord ShadowFor(Ped ped, bool mind = true)
	{
		Gang gang = Gangs.ForModel((uint)ped.Model.Hash) ?? (RallyModel((uint)ped.Model.Hash) ? Gangs.Klan : null);
		NemesisRecord nemesisRecord = new NemesisRecord
		{
			Name = "",
			ModelHash = (uint)ped.Model.Hash,
			Gang = gang?.Id
		};
		if (_named.TryGetValue(ped.Handle, out var n) && !string.IsNullOrEmpty(n.Name))
		{
			nemesisRecord.Id = $"stranger:{n.Name}|{(uint)ped.Model.Hash:X8}";
		}
		Acquaintance acquaintance = ((n != null && !string.IsNullOrEmpty(n.Name)) ? People.FirstOrDefault((Acquaintance a) => a.Name == n.Name && a.Model == (uint)ped.Model.Hash) : null);
		RollNewLife(nemesisRecord, null, mind, (acquaintance != null && acquaintance.LifeRules < 2) ? 1 : 2);
		nemesisRecord.Id = null;
		return nemesisRecord;
	}

	private Personality? KnownTemper(Ped ped)
	{
		string text = null;
		if (_acqOf.TryGetValue(ped.Handle, out var value))
		{
			text = value.Temper;
		}
		if (text == null && _named.TryGetValue(ped.Handle, out var n))
		{
			text = People.FirstOrDefault((Acquaintance x) => x.Name == n.Name && x.Model == (uint)ped.Model.Hash)?.Temper;
		}
		if (text == null && _fpOf.TryGetValue(ped.Handle, out var value2) && value2 != "" && Prints.TryGetValue(value2, out var value3))
		{
			text = value3.Temper;
		}
		if (text == null || !Enum.TryParse<Personality>(text, out var result))
		{
			return null;
		}
		return result;
	}

	private static void CopyTraits(NemesisRecord from, NemesisRecord to)
	{
		if (from == null || !from.TraitsRolled)
		{
			return;
		}
		to.Aggression = from.Aggression;
		to.Sociability = from.Sociability;
		to.Disposition = from.Disposition;
		to.Smarts = from.Smarts;
		to.Wealth = from.Wealth;
		to.Trade = from.Trade;
		to.Faith = from.Faith;
		to.Devotion = from.Devotion;
		to.Family = from.Family;
		to.Children = from.Children;
		to.Pet = from.Pet;
		to.TraitsRolled = true;
		to.LifeRules = from.LifeRules;
		to.LifeFx = from.LifeFx?.ToList();
		if (from.PastRolled)
		{
			to.Past = from.Past.Select((PastEntry e) => new PastEntry
			{
				Year = e.Year,
				Month = e.Month,
				Text = e.Text,
				Kind = e.Kind,
				Public = e.Public,
				Known = e.Known,
				MirrorKind = e.MirrorKind,
				MirrorTitle = e.MirrorTitle,
				MirrorPlace = e.MirrorPlace,
				MirrorHeard = e.MirrorHeard
			}).ToList();
			to.BornYear = from.BornYear;
			to.Birthplace = from.Birthplace;
			to.PastRolled = true;
			to.Woven = false;
			to.Fear = Math.Max(to.Fear, from.Fear);
		}
		if (from.MindRolled)
		{
			to.Facets = new Dictionary<string, int>(from.Facets);
			to.Values = new Dictionary<string, int>(from.Values);
			to.Needs = new Dictionary<string, int>(from.Needs);
			to.Stress = from.Stress;
			to.Memories = from.Memories.ToList();
			to.Ties = new List<Tie>();
			to.Goals = from.Goals.ToList();
			to.MindRolled = true;
		}
	}

	private static int SettleChance(Provocation p)
	{
		if (!(p.Score >= (float)Balance.GsThreshold))
		{
			return Math.Max(0, (int)(p.Score - (float)Balance.GsFloor));
		}
		return 100;
	}

