	private HisPeopleHold FindHisPeople(Ped him)
	{
		int h = him.Handle;
		HisPeopleHold hisPeopleHold = new HisPeopleHold
		{
			Him = h
		};
		if (_enc != null && _activeNemesisPed != null && (h == _activeNemesisPed.Handle || _followers.Any((Ped f) => f != null && f.Exists() && f.Handle == h)))
		{
			if (_enc.Engaged)
			{
				return null;
			}
			hisPeopleHold.Crew = true;
			hisPeopleHold.Men.AddRange(from p in new Ped[1] { _activeNemesisPed }.Concat(_followers)
				where p != null && p.Exists() && !p.IsDead && p.Handle != h
				select p);
			hisPeopleHold.What = (IsMourner(him) ? "the mourners with " : "the crew of ") + (ActiveRecord?.Name ?? "his leader");
		}
		else
		{
			Raid raid = _raids.FirstOrDefault((Raid x) => x.Men.Any((Ped m) => m.Exists() && m.Handle == h));
			if (raid != null)
			{
				if (raid.Hostile)
				{
					return null;
				}
				hisPeopleHold.Patrol = raid;
				hisPeopleHold.Men.AddRange(raid.Men.Where((Ped m) => m.Exists() && !m.IsDead && m.Handle != h));
				hisPeopleHold.What = raid.Gang.Name + " patrol";
			}
			else
			{
				Band band = BandOf(h);
				if (band != null)
				{
					if (band.Turned)
					{
						return null;
					}
					hisPeopleHold.Men.AddRange(band.Men.Where((Ped m) => m.Exists() && !m.IsDead && m.Handle != h && m.Position.DistanceTo(him.Position) < 40f));
					hisPeopleHold.What = band.What;
				}
				else if (!IsOurs(h))
				{
					hisPeopleHold.Men.AddRange(GroupOf(him));
					hisPeopleHold.What = "the people with him";
				}
			}
		}
		if (hisPeopleHold.Men.Count <= 0)
		{
			return null;
		}
		return hisPeopleHold;
	}

	private void HoldHisPeople(Ped him)
	{
		ReleaseHisPeople(wentForYou: false, quietly: true);
		_hisPeople = ((him != null && him.Exists()) ? FindHisPeople(him) : null);
		if (_hisPeople != null)
		{
			GrudgeLog(string.Format("INTERRO his people: {0}, {1} {2} - held while you question him", _hisPeople.What, _hisPeople.Men.Count, (_hisPeople.Men.Count == 1) ? "man" : "men"));
		}
	}

	private string HisPeopleStance(HisPeopleHold hp, Ped m, Ped player)
	{
		if (StoryBansWeapons(player.Position) != null)
		{
			return "stare";
		}
		NemesisRecord nemesisRecord = RecordAt(m.Handle);
		if (!hp.Crew && hp.Patrol == null && (nemesisRecord == null || nemesisRecord.Gang == null) && Gangs.ForModel((uint)m.Model.Hash) == null)
		{
			return "game";
		}
		Personality? personality = nemesisRecord?.Personality;
		if (!personality.HasValue && Enum.TryParse<Personality>(TemperOf(m), out var result))
		{
			personality = result;
		}
		if (personality != Personality.Coward)
		{
			return "aim";
		}
		return "back";
	}

	private void HoldHisPeopleTick(Ped player)
	{
		HisPeopleHold hp = _hisPeople;
		if (hp == null || Game.GameTime < hp.NextAt)
		{
			return;
		}
		hp.NextAt = Game.GameTime + 500;
		Ped ped = Entity.FromHandle(hp.Him) as Ped;
		bool flag = StoryBansWeapons(player.Position) != null;
		if (!hp.GunOn && ped != null && ped.Exists() && PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(Game.Player.Handle, ped.Handle) && WEAPON.IS_PED_ARMED(player.Handle, 6))
		{
			hp.GunOn = true;
			foreach (Ped item in hp.Men.Where((Ped m) => m != null && m.Exists() && !m.IsDead))
			{
				hp.Stance[item.Handle] = HisPeopleStance(hp, item, player);
			}
			GrudgeLog(string.Format("INTERRO his people ({0}): a gun on their man - {1} draw on you, {2} back off, {3} stare, {4} left to the game", hp.What, Count("aim"), Count("back"), Count("stare"), Count("game")));
		}
		if (hp.GunOn && !flag)
		{
			bool flag2 = PED.IS_PED_SHOOTING(player.Handle);
			if (flag2 || hp.Men.Any((Ped m) => m != null && m.Exists() && !m.IsDead && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(m.Handle, player.Handle, p2: true, p3: true)))
			{
				GrudgeLog("INTERRO his people (" + hp.What + "): " + (flag2 ? "you fired" : "you hurt one of them") + " with them covering you - it's a fight");
				ReleaseHisPeople(wentForYou: true);
				return;
			}
		}
		bool flag3 = Game.GameTime >= hp.LookAt;
		if (flag3)
		{
			hp.LookAt = Game.GameTime + 4000;
		}
		foreach (Ped man in hp.Men)
		{
			if (man == null || !man.Exists() || man.IsDead || PED.IS_PED_IN_COMBAT(man.Handle, 0))
			{
				continue;
			}
			int handle = man.Handle;
			if (!hp.Stance.TryGetValue(handle, out var value))
			{
				string text;
				if (!hp.GunOn)
				{
					text = "stare";
				}
				else
				{
					string text2 = (hp.Stance[handle] = HisPeopleStance(hp, man, player));
					text = text2;
				}
				value = text;
			}
			if (hp.GunOn && hp.Grudged.Add(handle))
			{
				GunOnHisFriend(man);
			}
			if (value == "game")
			{
				continue;
			}
			man.BlockPermanentEvents = true;
			hp.Blocked.Add(handle);
			if (flag3)
			{
				TASK.TASK_LOOK_AT_ENTITY(handle, player.Handle, 5000, 0, 51, 0);
			}
			if (hp.GunOn && value == "aim")
			{
				CoverYou(hp, man, player);
				continue;
			}
			bool flag4 = false;
			if (hp.GunOn && value == "back")
			{
				if (!hp.BackedAt.TryGetValue(handle, out var value2))
				{
					hp.BackedAt[handle] = Game.GameTime;
					Flee(handle, player.Handle, 7f, 2500, 1.2f);
					continue;
				}
				if (Game.GameTime - value2 < 2600)
				{
					continue;
				}
				flag4 = true;
			}
			if ((!hp.Crew | flag4) && !hp.Turned.Contains(handle) && !PED.IS_PED_USING_ANY_SCENARIO(handle))
			{
				hp.Turned.Add(handle);
				TASK.TASK_TURN_PED_TO_FACE_ENTITY(handle, player.Handle, -1, 0f, 0f, 0f);
			}
		}
		int Count(string s)
		{
			return Enumerable.Count(hp.Stance.Values, (string v) => v == s);
		}
	}

	private void CoverYou(HisPeopleHold hp, Ped m, Ped player)
	{
		int handle = m.Handle;
		if (PED.IS_PED_USING_ANY_SCENARIO(handle))
		{
			TASK.CLEAR_PED_TASKS(handle, p1: false, p2: false);
		}
		else
		{
			if (hp.AimAt.TryGetValue(handle, out var value) && Game.GameTime < value)
			{
				return;
			}
			if (!hp.AimAt.ContainsKey(handle))
			{
				uint num = 0u;
				try
				{
					num = Function.Call<uint>(9548732433391192802uL, new InputArgument[3] { handle, false, false });
				}
				catch
				{
				}
				if (num == 0 || !GunMelee.IsGun(num))
				{
					hp.AimAt[handle] = int.MaxValue;
					hp.Turned.Add(handle);
					TASK.TASK_TURN_PED_TO_FACE_ENTITY(handle, player.Handle, -1, 0f, 0f, 0f);
					return;
				}
				try
				{
					WEAPON.SET_CURRENT_PED_WEAPON(handle, num, p2: true, 0, p4: false, p5: false);
				}
				catch
				{
				}
			}
			hp.AimAt[handle] = Game.GameTime + 2500;
			TASK.TASK_AIM_GUN_AT_ENTITY(handle, player.Handle, 3000, p3: false, 0);
		}
	}

	private void GunOnHisFriend(Ped m)
	{
		NemesisRecord nemesisRecord = RecordAt(m.Handle);
		if (nemesisRecord != null)
		{
			ApplyToRecord(nemesisRecord, GrudgeAction.FriendThreatened);
			return;
		}
		Provocation provocation = RememberStranger(m.Handle);
		if (provocation != null)
		{
			Grudge(m.Handle, provocation, GrudgeAction.FriendThreatened);
		}
	}

	private void ReleaseHisPeople(bool wentForYou, bool quietly = false)
	{
		HisPeopleHold hisPeople = _hisPeople;
		_hisPeople = null;
		if (hisPeople == null)
		{
			return;
		}
		Ped character = Game.Player.Character;
		int num = 0;
		foreach (Ped man in hisPeople.Men)
		{
			if (man == null || !man.Exists() || man.IsDead)
			{
				continue;
			}
			num++;
			int handle = man.Handle;
			TASK.TASK_CLEAR_LOOK_AT(handle);
			if (PED.IS_PED_IN_COMBAT(handle, 0))
			{
				continue;
			}
			hisPeople.Stance.TryGetValue(handle, out var value);
			bool flag = hisPeople.AimAt.TryGetValue(handle, out var value2) && value2 != int.MaxValue;
			if (wentForYou && hisPeople.GunOn && (value == "aim" || value == "back"))
			{
				man.BlockPermanentEvents = true;
				TASK.TASK_COMBAT_PED(handle, character.Handle, 0, 16);
				continue;
			}
			if (!wentForYou & flag)
			{
				TASK.TASK_AIM_GUN_AT_ENTITY(handle, character.Handle, 2000, p3: false, 0);
				_lowerGuns.Add((handle, Game.GameTime + 2000, hisPeople.Patrol));
				continue;
			}
			if (hisPeople.Turned.Contains(handle) || hisPeople.BackedAt.ContainsKey(handle))
			{
				TASK.CLEAR_PED_TASKS(handle, p1: false, p2: false);
			}
			if ((wentForYou || !IsMourner(man) || (!hisPeople.Turned.Contains(handle) && !hisPeople.BackedAt.ContainsKey(handle)) || !BackToGrave(man)) && (value != "game" || hisPeople.Blocked.Contains(handle)))
			{
				man.BlockPermanentEvents = !_patrolOpen.Contains(handle) && StaysBlocked(man);
			}
		}
		if (hisPeople.Patrol != null && _raids.Contains(hisPeople.Patrol))
		{
			if (wentForYou && !hisPeople.Patrol.Hostile)
			{
				hisPeople.Patrol.Hostile = true;
				hisPeople.Patrol.WatchYouUntil = 0;
				hisPeople.Patrol.Watch = false;
				SetPatrolRelations(character);
				foreach (Ped item in hisPeople.Patrol.Men.Where((Ped m) => m.Exists() && !m.IsDead))
				{
					if (_patrolOpen.Remove(item.Handle))
					{
						item.BlockPermanentEvents = true;
					}
					TASK.TASK_COMBAT_PED(item.Handle, character.Handle, 0, 16);
				}
			}
			else if (!wentForYou)
			{
				hisPeople.Patrol.NextOrder = Game.GameTime + (hisPeople.GunOn ? 2200 : 0);
			}
		}
		if (!quietly)
		{
			NemesisMod nemesisMod = this;
			string what = hisPeople.What;
			object arg = num;
			string arg2;
			if (wentForYou)
			{
				arg2 = "they back him";
			}
			else
			{
				arg2 = (hisPeople.GunOn ? "they keep you covered a moment, then go back to what they were doing" : "back to what they were doing");
			}
			nemesisMod.GrudgeLog($"INTERRO his people ({what}, {arg}): {arg2}");
		}
	}

	private void HisPeopleAfterTick(Ped player)
	{
		if (_lowerGuns.Count == 0)
		{
			return;
		}
		for (int num = _lowerGuns.Count - 1; num >= 0; num--)
		{
			var (num2, num3, raid) = _lowerGuns[num];
			if (Game.GameTime >= num3)
			{
				_lowerGuns.RemoveAt(num);
				Ped ped = Entity.FromHandle(num2) as Ped;
				if (!(ped == null) && ped.Exists() && !ped.IsDead && !PED.IS_PED_IN_COMBAT(num2, 0))
				{
					try
					{
						WEAPON.SET_CURRENT_PED_WEAPON(num2, 2725352035u, p2: true, 0, p4: false, p5: false);
					}
					catch
					{
					}
					TASK.CLEAR_PED_TASKS(num2, p1: false, p2: false);
					if (!IsMourner(ped) || !BackToGrave(ped))
					{
						ped.BlockPermanentEvents = !_patrolOpen.Contains(num2) && StaysBlocked(ped);
						if (raid != null && _raids.Contains(raid) && !raid.Hostile)
						{
							raid.NextOrder = 0;
						}
					}
				}
			}
		}
	}

	private bool BackToHisPatrol(int h)
	{
		Raid raid = _raids.FirstOrDefault((Raid x) => x.Men.Any((Ped m) => m.Exists() && m.Handle == h));
		if (raid == null || raid.Hostile)
		{
			return false;
		}
		TASK.CLEAR_PED_TASKS(h, p1: false, p2: false);
		raid.NextOrder = 0;
		return true;
	}

	internal static bool PastShown(PastEntry e)
	{
		if (e == null || e.Year <= 0)
		{
			return true;
		}
		int num = GameYear();
		int num2 = GameMonth();
		if (e.Year >= num)
		{
			if (e.Year == num)
			{
				return e.Month <= num2;
			}
			return false;
		}
		return true;
	}

	internal static int GameYear()
	{
		int num;
		try
		{
			num = CLOCK.GET_CLOCK_YEAR();
			if (num < 1850 || num > 1950)
			{
				num = 1899;
			}
		}
		catch
		{
			num = 1899;
		}
		if (Gangs.Era < 1907 || num >= 1907)
		{
			return num;
		}
		return 1907;
	}

	internal static int GameMonth()
	{
		try
		{
			return Math.Max(1, Math.Min(12, CLOCK.GET_CLOCK_MONTH() + 1));
		}
		catch
		{
			return 6;
		}
	}

	private void FixWomensTrades()
	{
		WorldState chronicle = Chronicle;
		if (chronicle.WomenTradesFixed)
		{
			return;
		}
		int num = 0;
		foreach (NemesisRecord item in Roster.Where((NemesisRecord x) => x.Gang == null && !x.Story && x.Trade != null && Backstory.Woman(x) && !Traits.IsWomansTrade(x.Trade)).ToList())
		{
			try
			{
				string trade = item.Trade;
				Random rng = Seeds.For(item, "woman");
				item.Trade = null;
				Traits.SetBackground(item, rng);
				if (item.PastRolled)
				{
					Backstory.Roll(item, rng, GameYear(), GameMonth(), derive: false);
					item.Woven = false;
				}
				num++;
				GrudgeLog("HISTORY " + item.Name + ": a woman's trade - " + item.Trade + " (was " + trade + "), her life written again");
			}
			catch (Exception ex)
			{
				GrudgeLog("HISTORY " + item.Name + ": the woman's-trade fix failed - " + ex.Message);
			}
		}
		chronicle.WomenTradesFixed = true;
		GrudgeLog($"HISTORY women's trades checked: {num} given a woman's trade");
		if (num > 0)
		{
			SaveRoster();
		}
		SaveWorld();
	}

	private void RollNewLife(NemesisRecord r, IList<NemesisRecord> roster, bool mind = true, int rules = 2)
	{
		Random rng = ((r.Id != null) ? Seeds.For(r, "life") : _rng);
		r.LifeRules = ((rules >= 2) ? 2 : 0);
		Traits.SetBackground(r, rng);
		BackstoryResult backstoryResult = Backstory.Roll(r, rng, GameYear(), GameMonth(), derive: true);
		r.Personality = Backstory.PickTemper(backstoryResult, r.Gang != null, rng);
		Traits.Roll(r, rng, roster);
		if (r.KinId != null)
		{
			NemesisRecord nemesisRecord = roster?.FirstOrDefault((NemesisRecord n) => n.Id == r.KinId);
			if (Backstory.FitKinAge(r, nemesisRecord, rng, GameYear()))
			{
				backstoryResult = Backstory.Roll(r, rng, GameYear(), GameMonth(), derive: true, keepBorn: true);
				GrudgeLog($"HISTORY {r.Name}: {r.KinRelation} of {nemesisRecord?.Name} - born {r.BornYear} (his {nemesisRecord?.BornYear}), life rewritten");
				if (rules >= 2)
				{
					Personality? personality = r.Personality;
					r.Personality = Backstory.PickTemper(backstoryResult, r.Gang != null, rng);
					if (r.Personality != personality)
					{
						r.Aggression = Math.Max(0, Math.Min(100, r.Aggression + Traits.AggressionBase(r.Personality) - Traits.AggressionBase(personality)));
						GrudgeLog($"HISTORY {r.Name}: his rewritten life makes him {r.Personality} (was {personality})");
					}
				}
			}
		}
		Backstory.Apply(r, backstoryResult);
		if (rules >= 2)
		{
			r.LifeFx = backstoryResult.Fx.Concat(from kv in backstoryResult.Tilt
				where kv.Value != 0
				select $"t:{kv.Key.ToString().ToLowerInvariant()}:{kv.Value}").ToList();
		}
		if (mind)
		{
			Mind.Roll(r, rng, GameMinutesNow());
		}
	}

	private void EnsurePast(NemesisRecord r)
	{
		if (r.PastRolled)
		{
			return;
		}
		try
		{
			Backstory.Roll(r, (r.Id != null) ? Seeds.For(r, "life") : _rng, GameYear(), GameMonth(), derive: false);
		}
		catch (Exception ex)
		{
			GrudgeLog("HISTORY life failed for " + r.Name + ": " + ex.Message);
		}
	}

	private void UpdateHistory()
	{
		if (Game.GameTime < _nextHistoryCheck)
		{
			return;
		}
		_nextHistoryCheck = Game.GameTime + 15000;
		if (!Chronicle.HistorySeeded)
		{
			EnsureWorldHistory();
			return;
		}
		int num = 0;
		foreach (NemesisRecord item in Roster.Where((NemesisRecord r) => r.PastRolled && !r.Woven).Take(25).ToList())
		{
			Weave(item);
			num++;
		}
		int year = GameYear();
		int month = GameMonth();
		Gang[] all = Gangs.All;
		foreach (Gang g in all)
		{
			if (Roster.Any((NemesisRecord n) => n.Gang == g.Id && n.IsAlive && n.PastRolled) && Enumerable.Count(Chronicle.Past, (WorldEvent e) => e.Gangs.Contains(g.Id) && (e.Kind == "RAID" || e.Kind == "CLASH" || e.Kind == "DUTY") && e.People.Any((WorldPart p) => Roster.Any((NemesisRecord x) => x.Id == p.Id && x.IsAlive))) < 2)
			{
				num += GangPast(g, 2, year, month);
			}
		}
		SyncTies();
		if (num > 0)
		{
			SaveRoster();
			SaveWorld();
		}
	}

	private void EnsureWorldHistory()
	{
		WorldState chronicle = Chronicle;
		if (chronicle.HistorySeeded || !Roster.Any((NemesisRecord n) => n.Gang != null && n.IsAlive))
		{
			return;
		}
		int num = GameYear();
		int month = GameMonth();
		chronicle.Past = new List<WorldEvent>();
		foreach (NemesisRecord item in Roster)
		{
			if (item.Past == null)
			{
				continue;
			}
			item.Past.RemoveAll((PastEntry e) => e.Kind == "world" || e.Kind == "kin" || e.Kind == "friend" || e.Kind == "weave");
			foreach (PastEntry item2 in item.Past)
			{
				item2.WorldId = null;
			}
			item.Woven = false;
			EnsurePast(item);
		}
		Lore(num, month);
		if (Gangs.Era >= 1907)
		{
			EraLore(fresh: true);
			Apply1907Seats(GameMinutesNow(), _rng, transition: false);
		}
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			NemesisMod nemesisMod = this;
			Gang g = gang;
			int count;
			if (gang.Id == "odriscoll")
			{
				count = 5;
			}
			else if (gang.Id == "lemoyneraiders" || gang.Id == "delobo")
			{
				count = 4;
			}
			else
			{
				count = ((gang.Id == "army" || gang.Id == "wapiti" || gang.Id == "laramie") ? 3 : 2);
			}
			nemesisMod.GangPast(g, count, num, month);
		}
		RankYears(num);
		chronicle.HistorySeeded = true;
		chronicle.HistoryYear = num;
		GrudgeLog($"HISTORY seeded for {num}: {chronicle.Past.Count} past events, {Enumerable.Count(Roster, (NemesisRecord r) => r.PastRolled)} lives");
		Feed($"HISTORY the years before {num}: {chronicle.Past.Count} things the world remembers", Theme.Gold);
		SaveWorld();
		SaveRoster();
	}

	private WorldEvent PastEvent(string kind, int year, int month, string title, string place, bool heard, params string[] gangs)
	{
		int num = GameYear();
		int num2 = GameMonth();
		if (year > num)
		{
			year = num;
		}
		if (month < 1 || month > 12)
		{
			month = 1 + _rng.Next(12);
		}
		if (year == num && month > num2)
		{
			month = num2;
		}
		int maxValue = 27;
		if (year == num && month == num2)
		{
			int cLOCK_DAY_OF_MONTH = CLOCK.GET_CLOCK_DAY_OF_MONTH();
			if (cLOCK_DAY_OF_MONTH <= 1)
			{
				if (month > 1)
				{
					month--;
				}
				else
				{
					year--;
					month = 12;
				}
			}
			else
			{
				maxValue = Math.Min(27, cLOCK_DAY_OF_MONTH - 1);
			}
		}
		DateTime d = new DateTime(year, month, 1 + _rng.Next(maxValue), 6 + _rng.Next(16), _rng.Next(60), 0);
		WorldEvent worldEvent = new WorldEvent
		{
			Id = NewId(10),
			Kind = kind,
			GameMin = GameDate.ToMinutes(d),
			Day = GameDate.DayKey(d),
			When = $"{Months[d.Month - 1]} {d.Year}",
			Title = title,
			Place = place,
			Heard = heard,
			IsPast = true
		};
		worldEvent.Gangs.AddRange(gangs.Where((string g) => g != null));
		Chronicle.Past.Add(worldEvent);
		return worldEvent;
	}

	private void Lore(int year, int month)
	{
		int num = year - 6;
		foreach (LoreRow loreRow in LoreRows)
		{
			int num2 = ((loreRow.Year != 0) ? loreRow.Year : (year - loreRow.YearsAgo));
			if (num2 >= num - 1 && num2 <= year && !string.IsNullOrEmpty(loreRow.Title))
			{
				WorldEvent worldEvent = PastEvent("LORE", num2, loreRow.Month, loreRow.Title, loreRow.Place ?? "", true, loreRow.Gang);
				worldEvent.Lines.AddRange(loreRow.Lines ?? new List<string>());
				if (!string.IsNullOrEmpty(loreRow.When))
				{
					worldEvent.When = loreRow.When;
				}
			}
		}
	}

	private int JoinYearOf(NemesisRecord r)
	{
		int val = (r.Past?.FirstOrDefault((PastEntry p) => p.Kind == "gang"))?.Year ?? ((r.BornYear > 0) ? (r.BornYear + 18) : (GameYear() - 2));
		if (r.BornYear > 0)
		{
			val = Math.Max(val, r.BornYear + 15);
		}
		return Math.Min(val, GameYear());
	}

	private int GangPast(Gang g, int count, int year, int month)
	{
		if (!GangTales.TryGetValue(g.Id, out (string, string, string[], string, int, string)[] value) || value == null || value.Length == 0)
		{
			return 0;
		}
		List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.Gang == g.Id && n.IsAlive && n.PastRolled).ToList();
		if (list.Count == 0)
		{
			return 0;
		}
		HashSet<int> hashSet = new HashSet<int>();
		for (int num = 0; num < count; num++)
		{
			int num2 = _rng.Next(value.Length);
			for (int num3 = 0; num3 < 4; num3++)
			{
				if (!hashSet.Contains(num2))
				{
					break;
				}
				num2 = _rng.Next(value.Length);
			}
			hashSet.Add(num2);
			(string, string, string[], string, int, string) tuple = value[num2];
			List<NemesisRecord> list2 = list.Where((NemesisRecord n) => n.Rank >= 2).ToList();
			NemesisRecord lead = ((list2.Count > 0) ? list2 : list)[_rng.Next(((list2.Count > 0) ? list2 : list).Count)];
			int ey = Math.Max(year - 6, JoinYearOf(lead)) + _rng.Next(Math.Max(1, year - Math.Max(year - 6, JoinYearOf(lead)) + 1));
			ey = Math.Min(year, ey);
			List<NemesisRecord> list3 = (from _ in list
				where _ != lead && _.BossId == lead.Id && JoinYearOf(_) <= ey
				orderby _rng.Next()
				select _).Take(1 + _rng.Next(3)).ToList();
			if (list3.Count == 0)
			{
				list3 = (from _ in list
					where _ != lead && JoinYearOf(_) <= ey
					orderby _rng.Next()
					select _).Take(_rng.Next(3)).ToList();
			}
			string text = tuple.Item3[_rng.Next(tuple.Item3.Length)];
			WorldEvent worldEvent = PastEvent(tuple.Item1, ey, 1 + _rng.Next(12), tuple.Item2.Replace("{place}", text), text, _rng.Next(100) < tuple.Item5, g.Id, tuple.Item4);
			worldEvent.Lines.Add(tuple.Item6);
			foreach (NemesisRecord item in new NemesisRecord[1] { lead }.Concat(list3))
			{
				RideIn(worldEvent, item, tuple.Item1);
			}
			Gang foe = ((tuple.Item4 != null) ? Gangs.ById(tuple.Item4) : null);
			if (foe != null)
			{
				foreach (NemesisRecord item2 in (from _ in Roster
					where _.Gang == foe.Id && _.IsAlive && _.PastRolled && JoinYearOf(_) <= ey
					orderby _rng.Next()
					select _).Take(_rng.Next(3)))
				{
					RideIn(worldEvent, item2, tuple.Item1);
				}
			}
			if (tuple.Item1 == "CLASH" || tuple.Item1 == "RAID")
			{
				int num4 = _rng.Next(4);
				if (num4 > 0)
				{
					worldEvent.UnnamedDead[g.Id] = num4;
				}
				if (foe != null && _rng.Next(2) == 0)
				{
					worldEvent.UnnamedDead[foe.Id] = 1 + _rng.Next(3);
				}
			}
		}
		GrudgeLog($"HISTORY {g.Name}: {count} tales from the years before");
		return count;
	}

	private void RideIn(WorldEvent ev, NemesisRecord r, string kind)
	{
		if (ev.People.Any((WorldPart p) => p.Id == r.Id))
		{
			return;
		}
		int num = _rng.Next(100);
		string text;
		if (!(kind == "CLASH") && !(kind == "RAID"))
		{
			text = "UNHURT";
		}
		else if (num < 20)
		{
			text = "WOUNDED";
		}
		else if (num < 38)
		{
			text = "DISTINGUISHED";
		}
		else
		{
			text = ((num < 46 && r.Personality == Personality.Coward) ? "FLED" : "UNHURT");
		}
		WorldPart worldPart = new WorldPart
		{
			Id = r.Id,
			Name = r.Name,
			Gang = r.Gang,
			Outcome = text
		};
		string text2 = text switch
		{
			"FLED" => "Ran when the shooting started: " + ev.Title, 
			"DISTINGUISHED" => "Made his name: " + ev.Title, 
			"WOUNDED" => "Took a bullet: " + ev.Title, 
			_ => "Rode in it: " + ev.Title, 
		};
		bool flag = !r.TemperKnown;
		if (text == "WOUNDED")
		{
			worldPart.Effects.Add("old wound");
			if (flag)
			{
				r.Aggression = Math.Min(100, r.Aggression + 3);
			}
		}
		if (text == "DISTINGUISHED")
		{
			worldPart.Effects.Add("made his name");
		}
		if (text == "FLED")
		{
			worldPart.Effects.Add("ran");
			if (flag)
			{
				r.Fear = Math.Min(30, r.Fear + 3);
			}
		}
		ev.People.Add(worldPart);
		int month = Array.IndexOf(Months, (ev.When ?? "").Split(' ')[0]) + 1;
		r.Past.Add(new PastEntry
		{
			Year = ev.Day / 10000,
			Month = month,
			Text = text2,
			Kind = "world",
			WorldId = ev.Id,
			Public = ev.Heard
		});
		r.Past = (from e in r.Past
			orderby e.Year, e.Month
			select e).ToList();
	}

	private void RankYears(int year)
	{
		Gang[] all = Gangs.All;
		foreach (Gang g in all)
		{
			foreach (IGrouping<int, (NemesisRecord, PastEntry)> item in from x in Roster.Where((NemesisRecord n) => n.Gang == g.Id && n.Past != null).SelectMany((NemesisRecord n) => from e in n.Past
					where e.Kind == "rank" && e.Year >= year - 6
					select (n: n, e: e)).ToList()
				group x by x.e.Year into x
				orderby x.Key
				select x)
			{
				WorldEvent worldEvent = PastEvent("RANKS", item.Key, 12, $"{g.Name}: promotions, {item.Key}", "", false, g.Id);
				if (item.Key == year)
				{
					worldEvent.When = $"{item.Key} so far";
				}
				foreach (var (nemesisRecord, pastEntry) in item)
				{
					worldEvent.People.Add(new WorldPart
					{
						Id = nemesisRecord.Id,
						Name = nemesisRecord.Name,
						Gang = g.Id,
						Outcome = "PROMOTED",
						Note = pastEntry.Text
					});
					pastEntry.WorldId = worldEvent.Id;
				}
			}
		}
	}

	private void Weave(NemesisRecord r)
	{
		try
		{
			int year = GameYear();
			GameMonth();
			Gang gang = Gangs.ById(r.Gang);
			r.Past = r.Past ?? new List<PastEntry>();
			NemesisRecord nemesisRecord = ((r.BossId != null) ? Roster.FirstOrDefault((NemesisRecord b) => b.Id == r.BossId) : null);
			if (nemesisRecord != null && gang != null && !r.Past.Any((PastEntry e) => e.Kind == "weave"))
			{
				int year2 = JoinYearOf(r);
				int month = r.Past.FirstOrDefault((PastEntry e) => e.Kind == "gang")?.Month ?? 0;
				string text;
				if (r.Gang == "army")
				{
					text = "Served under " + nemesisRecord.Name + " from the start";
				}
				else
				{
					text = ((r.Gang == "wapiti") ? ("Learned the warrior's road from " + nemesisRecord.Name) : ("Brought into the " + gang.Name + " by " + nemesisRecord.Name));
				}
				r.Past.Add(new PastEntry
				{
					Year = year2,
					Month = month,
					Text = text,
					Kind = "weave"
				});
				if (nemesisRecord.Past != null && !nemesisRecord.Past.Any((PastEntry e) => e.Kind == "weave" && e.Text.Contains(r.Name)))
				{
					nemesisRecord.Past.Add(new PastEntry
					{
						Year = year2,
						Month = month,
						Text = ((r.Gang == "army") ? ("Took " + r.Name + " into his command") : ((r.Gang == "wapiti") ? ("Taught " + r.Name + " the warrior's road") : ("Brought " + r.Name + " into the " + gang.Name))),
						Kind = "weave"
					});
				}
			}
			NemesisRecord kin = ((r.KinId != null) ? Roster.FirstOrDefault((NemesisRecord k) => k.Id == r.KinId) : null);
			if (kin != null && !r.Past.Any((PastEntry e) => e.Kind == "kin" && e.Text.Contains(kin.Name)))
			{
				string text2 = r.KinRelation ?? "kin";
				string text3 = Traits.Inverse(text2);
				int year3 = Math.Min(year, Math.Max(r.BornYear, kin.BornYear) + 16 + _rng.Next(4));
				r.Past.Add(new PastEntry
				{
					Year = year3,
					Month = 0,
					Text = ((r.Gang != null && r.Gang == kin.Gang) ? ("Rides with his " + text3 + ", " + kin.Name) : ("Keeps in touch with his " + text3 + ", " + kin.Name)),
					Kind = "kin"
				});
				kin.Past?.Add(new PastEntry
				{
					Year = year3,
					Month = 0,
					Text = "Looks out for his " + text2 + ", " + r.Name,
					Kind = "kin"
				});
			}
			foreach (string fid in r.FriendIds ?? new List<string>())
			{
				NemesisRecord f = Roster.FirstOrDefault((NemesisRecord x) => x.Id == fid);
				if (f == null || f.Past == null || r.Past.Any((PastEntry e) => e.Kind == "friend" && e.Text.Contains(f.Name)))
				{
					continue;
				}
				PastEntry shared = r.Past.Where((PastEntry e) => e.WorldId != null && e.Kind == "world").FirstOrDefault((PastEntry e) => f.Past.Any((PastEntry x) => x.WorldId == e.WorldId));
				WorldEvent worldEvent = ((shared != null) ? Chronicle.Past.FirstOrDefault((WorldEvent x) => x.Id == shared.WorldId) : null);
				int num = shared?.Year ?? Math.Min(year, Math.Max(JoinYearOf(r), JoinYearOf(f)));
				string text4 = ((worldEvent != null) ? ("Friends with " + f.Name + " since " + Lower(worldEvent.Title)) : $"Friends with {{0}} since {num}");
				r.Past.Add(new PastEntry
				{
					Year = num,
					Month = (shared?.Month ?? 0),
					Text = text4.Replace("{0}", f.Name),
					Kind = "friend"
				});
				f.Past.Add(new PastEntry
				{
					Year = num,
					Month = (shared?.Month ?? 0),
					Text = ((worldEvent != null) ? ("Friends with " + r.Name + " since " + Lower(worldEvent.Title)) : $"Friends with {r.Name} since {num}"),
					Kind = "friend"
				});
			}
			foreach (PastEntry item in r.Past.Where((PastEntry e) => e.MirrorKind != null && e.WorldId == null && e.Year >= year - 6).ToList())
			{
				WorldEvent worldEvent2 = PastEvent(item.MirrorKind, item.Year, item.Month, (item.MirrorTitle ?? "").Replace("{name}", r.Name), item.MirrorPlace ?? "", item.MirrorHeard, r.Gang ?? "");
				worldEvent2.People.Add(new WorldPart
				{
					Id = r.Id,
					Name = r.Name,
					Gang = r.Gang,
					Outcome = ((item.MirrorKind == "BRAWL") ? "WON" : "INVOLVED"),
					Note = item.Text
				});
				item.WorldId = worldEvent2.Id;
				item.Public |= worldEvent2.Heard;
			}
			if (gang != null && !r.Past.Any((PastEntry e) => e.Kind == "world") && _rng.Next(100) < 45)
			{
				WorldEvent worldEvent3 = (from _ in Chronicle.Past
					where _.Gangs.Contains(gang.Id) && (_.Kind == "RAID" || _.Kind == "CLASH" || _.Kind == "DUTY") && _.Day / 10000 >= JoinYearOf(r) && _.People.Count < 7
					orderby _rng.Next()
					select _).FirstOrDefault();
				if (worldEvent3 != null)
				{
					RideIn(worldEvent3, r, worldEvent3.Kind);
				}
			}
			if (gang == null && _rng.Next(100) < 30)
			{
				string home = (r.Birthplace ?? "").Split(',')[0];
				WorldEvent worldEvent4 = Chronicle.Past.FirstOrDefault((WorldEvent x) => x.Kind == "LORE" && !string.IsNullOrEmpty(x.Place) && (x.Place == home || x.Place == r.KillLocation) && (r.BornYear <= 0 || x.Day / 10000 >= r.BornYear + 14));
				if (worldEvent4 != null && !worldEvent4.People.Any((WorldPart p) => p.Id == r.Id))
				{
					worldEvent4.People.Add(new WorldPart
					{
						Id = r.Id,
						Name = r.Name,
						Gang = null,
						Outcome = "WITNESS",
						Note = "was there"
					});
					int month2 = Array.IndexOf(Months, (worldEvent4.When ?? "").Split(' ')[0]) + 1;
					r.Past.Add(new PastEntry
					{
						Year = worldEvent4.Day / 10000,
						Month = month2,
						Text = "Was in " + worldEvent4.Place + " for it: " + worldEvent4.Title,
						Kind = "world",
						WorldId = worldEvent4.Id,
						Public = true
					});
				}
			}
			r.Past = (from e in r.Past
				orderby e.Year, e.Month
				select e).ToList();
			r.Woven = true;
		}
		catch (Exception ex)
		{
			r.Woven = true;
			GrudgeLog("HISTORY weave failed for " + r.Name + ": " + ex.Message);
		}
	}

	private static string Lower(string s)
	{
		if (!string.IsNullOrEmpty(s))
		{
			return char.ToLowerInvariant(s[0]) + s.Substring(1);
		}
		return s;
	}

	private void RevealPast(NemesisRecord r, string what, params string[] kinds)
	{
		if (r?.Past == null)
		{
			return;
		}
		List<PastEntry> list = r.Past.Where((PastEntry e) => !e.Known && !e.Public && kinds.Contains(e.Kind)).ToList();
		foreach (PastEntry item in list)
		{
			item.Known = true;
		}
		if (list.Count > 0)
		{
			Feed("PAST " + r.Name + " told you about " + what + ": " + string.Join("; ", from e in list.Take(3)
				select e.WhenText + " " + Lower(e.Text)) + ((list.Count > 3) ? $" (+{list.Count - 3})" : ""), Backstory.KindColor(list[0].Kind), r);
		}
	}

	internal bool PastShown(NemesisRecord n, PastEntry e)
	{
		if (!_debugOn && !e.Known)
		{
			if (e.Public)
			{
				return n.TemperKnown;
			}
			return false;
		}
		return true;
	}

	internal string HistoryDebugLine()
	{
		WorldState chronicle = Chronicle;
		return string.Format("history: {0} - {1} past events, {2} lives ({3} woven)", chronicle.HistorySeeded ? $"seeded for {chronicle.HistoryYear}" : "not seeded yet", chronicle.Past?.Count ?? 0, Enumerable.Count(Roster, (NemesisRecord r) => r.PastRolled), Enumerable.Count(Roster, (NemesisRecord r) => r.Woven));
	}

	private void HoldingsPass()
	{
		List<HoldingsEvent> ev = Hold.Pass(out var changed);
		ApplyHoldings(ev);
		if (changed)
		{
			SaveWorld();
		}
	}

	private void ApplyHoldings(List<HoldingsEvent> ev)
	{
		bool flag = false;
		bool flag2 = false;
		foreach (HoldingsEvent item in ev)
		{
			switch (item.Act)
			{
			case HoldingsAct.Log:
				GrudgeLog(item.Text);
				break;
			case HoldingsAct.RedoCampBlip:
				RedoCampBlip(item.SiteId);
				break;
			case HoldingsAct.StashBlips:
				flag = true;
				break;
			case HoldingsAct.CacheBlips:
				flag2 = true;
				break;
			case HoldingsAct.RevealCamp:
				if (item.Who != null)
				{
					RevealCamp(item.Who, found: false);
				}
				break;
			case HoldingsAct.Notice:
				ReplyNotice(item.Text);
				break;
			case HoldingsAct.WorldNews:
				GrudgeLog("HOLDINGS news" + (item.Big ? " (big)" : "") + ": " + item.Text);
				if (Config.WorldNews >= (item.Big ? 2 : 3))
				{
					ShowNotification(item.Text);
				}
				break;
			case HoldingsAct.PurseTaken:
				AddPurse(item.From, -item.Amount, "the " + item.To.Name + " took their " + (item.Stash ? "stash" : "treasury") + " at " + item.Place);
				AddPurse(item.To, item.Amount, "they took the " + OutfitPoss(item.From) + " " + (item.Stash ? "stash" : "treasury") + " at " + item.Place);
				break;
			}
		}
		if (flag)
		{
			RefreshStashBlips();
		}
		if (flag2)
		{
			RefreshCacheBlips();
		}
	}

