	internal void KeeperLeft(NemesisRecord r, string how)
	{
		Gang gang = Gangs.Of(r);
		if (r == null || gang == null)
		{
			return;
		}
		bool flag = Hold.SupplyRaidedRecently(gang) && Hold.SupplyCampHitSite.TryGetValue(gang.Id, out var value) && Hold.SupplyCampOf(gang)?.Id == value && (value == r.CampId || Hold.SupplyKeeper(gang) == r);
		bool flag2 = Hold.TreasuryRobbedNow(gang) && Hold.TreasuryRobbedSite.TryGetValue(gang.Id, out var value2) && Hold.TreasuryOf(gang)?.Id == value2 && (value2 == r.CampId || (Hold.IsStash(gang) && Hold.StashKeeper(gang) == r));
		if (flag || flag2)
		{
			if (flag)
			{
				Hold.MarkKeeperGone(gang, treasury: false);
			}
			if (flag2)
			{
				Hold.MarkKeeperGone(gang, treasury: true);
			}
			SaveWorld();
			GrudgeLog("HOLDINGS " + r.Name + " " + how + " - he kept the " + OutfitPoss(gang) + " " + ((flag & flag2) ? "supplies and money" : (flag ? "supplies" : "money")) + " you hit: they leave once you've gone");
		}
	}

