		else if (ped8 == null && _lastPromptPed != null && Game.GameTime - _lastPromptAt >= ((_lastPromptMode == "aim") ? 1200 : 700))
		{
			GrudgeLog($"INTERRO prompt target: none (was ped {_lastPromptPed.Handle}, {_lastPromptMode})");
