			_lastPromptMode = "none";
		}
		if (ped8 != null)
		{
			_dpadOursAt = Game.GameTime;
		}
		if (ped8 != null)
		{
			bool flag2 = Game.GameTime - _interroPromptSeenAt < 250;
			if ((XPad.Connected && XPad.Pressed(1)) & flag2)
			{
				_rbHeldSince = Game.GameTime;
