	private static bool GrappledBy(Ped p, Ped player)
	{
		if (p != null && p.Exists() && PED.GET_PED_IS_BEING_GRAPPLED(p.Handle))
		{
			return PED._GET_PED_GRAPPLER(p.Handle) == player.Handle;
		}
		return false;
	}

