		}
		if (!HUD._UI_PROMPT_HAS_HOLD_MODE_COMPLETED(p) && !HUD._UI_PROMPT_HAS_STANDARD_MODE_COMPLETED(p, 0))
		{
			return false;
		}
		_lastPromptFire = Game.GameTime;
		return true;
	}

