	private void Terrify(Interrogation it, int amount, string what)
	{
		if (amount <= 0)
		{
			return;
		}
		float num = Traits.FearGain(it.Rec ?? it.Shown) * Balance.FearGainScale;
		int cLOCK_HOURS = CLOCK.GET_CLOCK_HOURS();
		if (Quirks.Has(it.Rec, "superstitious") && (cLOCK_HOURS >= 21 || cLOCK_HOURS < 5))
		{
			num *= 1.3f;
		}
		if (Quirks.Has(it.Rec, "sadist"))
		{
			switch (what)
			{
			case "HIT":
			case "STABBED":
			case "SHOT":
				num *= 0.7f;
				break;
			}
		}
		try
		{
			if (PlayerMasked(Game.Player.Character))
			{
				num *= 1.25f;
			}
		}
		catch
		{
		}
		Interrogation interrogation = it;
		string label;
		if (what == "SHOT NEAR")
		{
			label = "SHOT NEAR HIM";
		}
		else
		{
			label = ((what == "SAW YOU KILL") ? "SAW A KILL" : what);
		}
		interrogation.Act(label);
		float terror = it.Terror;
		bool flag = it.Terror >= 99.5f;
		it.Terror = Math.Min(100f, it.Terror + (float)amount * num);
		if (what != "THREATENED")
		{
			it.ScaredSinceThreat = true;
		}
		bool flag2 = false;
		if (it.CampLockAt >= 0f && it.Terror >= it.CampLockAt)
		{
			it.CampLockAt = -1f;
			it.CampTries = Balance.InterroTriesPerScare - 1;
			flag2 = true;
		}
		if (it.KinLockAt >= 0f && it.Terror >= it.KinLockAt)
		{
			it.KinLockAt = -1f;
			it.KinTries = Balance.InterroTriesPerScare - 1;
			flag2 = true;
		}
		int count = it.Locks.Count;
		ReopenQuestions(it, flag && amount > 0);
		if (it.Locks.Count < count)
		{
			flag2 = true;
		}
		if (flag2)
		{
			Feed($"INTERROGATION {Speaker(it)}: scared enough to ask again (fear {it.Terror:0})", Theme.Good, it.Rec);
		}
		int lastChance = it.LastChance;
		it.LastChance = ChanceToTalk(it, Game.Player.Character);
		Feed($"{what} {Speaker(it)}: fear {terror:0} -> {it.Terror:0} (x{num:0.00})  camp {lastChance}% -> {it.LastChance}%  family {it.FamilyChance}%", (it.Terror > terror) ? Theme.Warn : Theme.Dim, it.Rec);
		if (_convo != null && _convo.It == it)
		{
			Personality personality = it.Temper ?? Personality.Cold;
			bool flag3 = it.Terror >= 60f;
			string text = what switch
			{
				"SHOT NEAR" => "near", 
				"STABBED" => "cut", 
				"SHOT" => "shot", 
				_ => "hit", 
			};
			if (flag3 || (personality == Personality.Coward && text == "hit"))
			{
				text += "_scared";
			}
			_convo.Line = InterroLines.Pick(text, it.Gang, personality, _rng, null, null, LeaderOut(it.Gang, it.Rec)) ?? ((!(what == "SHOT")) ? "...Ugh." : (flag3 ? "AAH! Stop! Stop, I'll talk!" : "Gah! You son of a..."));
			BuildOptions(_convo);
		}
	}

	private string ConfessCamp(Interrogation it)
	{
		NemesisRecord nemesisRecord = IntelTarget(it);
		it.CampDone = true;
		if (nemesisRecord != null && CampOf(nemesisRecord) == null)
		{
			return Nothing(it, nemesisRecord.Name + "? He's on the move - no camp I know of. That's the truth!");
		}
		if (nemesisRecord != null && it.Rec != null)
		{
			it.Rec.GaveCamp = true;
			it.Rec.AddHate(10);
		}
		if (nemesisRecord == null)
		{
			if (it.Rec == null || it.Rec.Rank < 4)
			{
				if (BossOf(it.Rec) == null || !BossOf(it.Rec).CampKnown)
				{
					return "I don't know nothin' about the camps! I just ride where I'm told!";
				}
				return "You already know where " + BossOf(it.Rec).Name + " is! That's all I got!";
			}
			if (!IsLeader(it.Gang, it.Rec))
			{
				if (!LeaderOut(it.Gang, it.Rec))
				{
					return (it.Gang?.LeaderName ?? "The boss") + "? Nobody knows where he lays his head. Not even me. That's the truth!";
				}
				return "Nobody's at the top right now. There's no camp to give you.";
			}
			return "Where I sleep? You'll not get that out of me. Nobody gets that.";
		}
		CampSite campSite = CampOf(nemesisRecord);
		string text = ((it.Rec?.BossId == nemesisRecord.Id) ? ("our " + TierWord(nemesisRecord, plural: false)) : ("one of the " + TierWord(nemesisRecord, plural: true)));
		string text2 = (campSite.Hideout ? ("holed up at " + campSite.Name) : ("camped out in " + GetZoneName(SitePos(campSite))));
		nemesisRecord.AddHate(5);
		RevealPast(it.Rec, "his years in the gang", "gang", "rank", "weave", "world", "crime", "war");
		History(nemesisRecord, "GIVEN UP: " + Speaker(it) + " told you where to find him (" + campSite.Label + ")", Theme.Warn);
		RevealCamp(nemesisRecord, found: false);
		ReplyNotice("INTEL: " + OfficerTitle(nemesisRecord) + " " + nemesisRecord.FullName + " - " + campSite.Label + ". Marked on your map.");
		Feed("INTEL from " + Speaker(it) + ": " + nemesisRecord.FullName + " (" + text + ") - " + campSite.Label, Theme.Good, it.Rec);
		WorldPart worldPart = ((it.Rec != null) ? PartFor(it.Rec, "TALKED", "under questioning") : new WorldPart
		{
			Name = Speaker(it),
			Outcome = "TALKED",
			Note = "under questioning"
		});
		if (it.Rec != null)
		{
			worldPart.Effects.Add("hate +10 (a rat now)");
		}
		WorldPart worldPart2 = PartFor(nemesisRecord, "GIVEN UP", campSite.Label);
		worldPart2.Effects.Add("camp marked on your map");
		ChronicleDeed("intel", Speaker(it) + " gave up " + nemesisRecord.Name + "'s " + (campSite.Hideout ? "hideout" : "camp"), campSite.Label, null, nemesisRecord.Gang, worldPart, worldPart2);
		return "Alright, alright! " + nemesisRecord.FullName + " - " + text + " - he's " + text2 + "! Now let me be!";
	}

	private NemesisRecord StandInFor(Ped ped, Interrogation it)
	{
		_named.TryGetValue(ped.Handle, out var value);
		NemesisRecord nemesisRecord = ((_provoked.TryGetValue(ped.Handle, out var value2) && value2.Shadow != null && value2.Shadow.PastRolled) ? value2.Shadow : null);
		if (nemesisRecord == null)
		{
			try
			{
				nemesisRecord = ShadowFor(ped);
			}
			catch
			{
				nemesisRecord = new NemesisRecord();
			}
		}
		nemesisRecord.Id = $"tmp:{ped.Handle}";
		nemesisRecord.Name = value?.Name ?? ((it.Gang?.Name != null) ? (it.Gang.Name + " man") : "Stranger");
		nemesisRecord.Title = value?.Title ?? "";
		nemesisRecord.Gang = it.Gang?.Id;
		nemesisRecord.ModelHash = (uint)ped.Model.Hash;
		nemesisRecord.Personality = it.Temper;
		nemesisRecord.Hate = 30;
		nemesisRecord.Rank = 1;
		NemesisRecord nemesisRecord2 = (_followerOf.TryGetValue(ped.Handle, out var value3) ? value3 : null);
		if (nemesisRecord2 == null)
		{
			nemesisRecord2 = _liveCamps.Values.FirstOrDefault((LiveCamp lc) => lc.Peds.Any((Ped p) => p != null && p.Handle == ped.Handle))?.Boss;
		}
		nemesisRecord.BossId = nemesisRecord2?.Id;
		GrudgeLog("INTERRO " + nemesisRecord.Name + ": no record - a stand-in with his own life" + ((nemesisRecord2 != null) ? (", answers to " + nemesisRecord2.Name) : ""));
		return nemesisRecord;
	}

	private string ConfessKin(Interrogation it)
	{
		it.KinDone = true;
		it.AskedKin = true;
		NemesisRecord who = it.Who;
		if (who == null)
		{
			return Nothing(it, "Family? Ain't got none worth telling you about.");
		}
		List<(NemesisRecord, string)> list = KinOf(who);
		if (list.Count > 0 && it.Rec != null)
		{
			it.Rec.GaveKin = true;
		}
		RevealKin(who, list);
		List<Goal> goals = who.Goals;
		if (goals != null && goals.Count > 0 && !who.WantsKnown)
		{
			who.WantsKnown = true;
			Feed("WANTS " + who.Name + ": " + string.Join("; ", who.Goals.Select((Goal g) => g.Text)), Theme.Gold, who);
		}
		RevealPast(who, "his family and where he came from", "born", "youth", "family", "loss", "kin", "friend", "faith");
		who.AddHate(5);
		if (list.Count == 0)
		{
			return Nothing(it, (who.Family == "married") ? ("Got a wife" + ((who.Children > 0) ? " and young'uns" : "") + " - and you leave them out of this!") : "Ain't got nobody. Nobody rides with me.");
		}
		(NemesisRecord, string) tuple = list[0];
		if (tuple.Item2 == "friend" && list.All(((NemesisRecord who, string rel) x) => x.rel == "friend"))
		{
			if (!tuple.Item1.IsAlive)
			{
				return tuple.Item1.Name + " was my friend. You killed him.";
			}
			return tuple.Item1.Name + "... we ride together. " + (Gangs.ById(tuple.Item1.Gang)?.Name ?? "He's his own man") + "." + ((list.Count > 1) ? (" And " + list[1].Item1.Name + ".") : "") + " Leave 'em out of this.";
		}
		string text = ((list.Count > 1) ? (" And " + list[1].Item1.Name + ((list[1].Item2 == "friend") ? ", a friend" : (", my " + list[1].Item2)) + ".") : "");
		if (!tuple.Item1.IsAlive)
		{
			return "My " + tuple.Item2 + ", " + tuple.Item1.Name + ". You killed him, you son of a bitch." + text;
		}
		return "My " + tuple.Item2 + "... " + tuple.Item1.Name + ". He rides with " + (Gangs.ById(tuple.Item1.Gang)?.Name ?? "nobody") + "." + text + " Leave him be!";
	}

	private List<(NemesisRecord who, string rel)> KinOf(NemesisRecord rec)
	{
		List<(NemesisRecord, string)> list = new List<(NemesisRecord, string)>();
		if (rec == null)
		{
			return list;
		}
		NemesisRecord nemesisRecord = ((rec.KinId != null) ? Roster.FirstOrDefault((NemesisRecord r) => r.Id == rec.KinId) : null);
		if (nemesisRecord != null)
		{
			list.Add((nemesisRecord, Traits.Inverse(rec.KinRelation)));
		}
		foreach (NemesisRecord item in Roster.Where((NemesisRecord r) => r.KinId == rec.Id))
		{
			list.Add((item, item.KinRelation));
		}
		foreach (NemesisRecord item2 in FriendsOf(rec))
		{
			list.Add((item2, "friend"));
		}
		return list;
	}

	private void RevealKin(NemesisRecord rec, List<(NemesisRecord who, string rel)> kin)
	{
		string text;
		if (rec.TraitsRolled)
		{
			text = ((rec.Family == "single") ? "single" : (((rec.Family == "married") ? "married" : "a widower") + ((rec.Children > 0) ? string.Format(", {0} {1}", rec.Children, (rec.Children == 1) ? "child" : "children") : "")));
		}
		else
		{
			text = "";
		}
		if (kin.Count == 0)
		{
			Feed("KIN " + rec.Name + ": no kin or friends on your roster" + ((text != "") ? (" - " + text) : ""), Theme.Dim, rec);
			return;
		}
		Feed("KIN " + rec.Name + " gave up his family and friends: " + string.Join(";  ", kin.Select(((NemesisRecord who, string rel) k) => k.rel + " " + k.who.Name + " (" + Where(k.who) + ")")) + ((text != "") ? ("  - " + text) : ""), (210, 190, 140), rec);
		ChronicleDeed("intel", rec.Name + " gave up his family and friends", "", null, rec.Gang, new WorldPart[1] { PartFor(rec, "TALKED", "under questioning") }.Concat(kin.Select(((NemesisRecord who, string rel) k2) => PartFor(k2.who, "GIVEN UP", "his " + k2.rel))).ToArray());
		foreach (var item in kin)
		{
			History(item.who, ((item.rel == "friend") ? "FRIEND" : "KIN") + ": his " + Traits.Inverse(item.rel) + " " + rec.Name + " told you about him under questioning", (210, 190, 140));
		}
		static string Where(NemesisRecord k)
		{
			if (!k.IsAlive)
			{
				return "dead";
			}
			Gang gang = Gangs.ById(k.Gang);
			if (gang != null)
			{
				return $"{gang.Name}, rank {k.Rank}";
			}
			return "rides alone";
		}
	}

	private NemesisRecord IntelTarget(Interrogation it)
	{
		NemesisRecord rec = it.Rec;
		if (rec != null)
		{
			NemesisRecord nemesisRecord = BossOf(rec);
			if (!Unknown(nemesisRecord))
			{
				return null;
			}
			return nemesisRecord;
		}
		if (it.Gang == null)
		{
			return null;
		}
		List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.Gang == it.Gang.Id && n.Rank >= 2 && n.Rank < 4 && Unknown(n)).ToList();
		if (list.Count != 0)
		{
			return list[_rng.Next(list.Count)];
		}
		return null;
		static bool Unknown(NemesisRecord o)
		{
			if (o != null && o.CampId != null && !o.CampKnown && o.CanHunt && !o.PresumedDead)
			{
				return IsOfficer(o);
			}
			return false;
		}
	}

	private void BuildInterroOptions(Convo c)
	{
		BuildQuestionOptions(c);
	}

	private void ChooseInterro(Convo c, ConvoOption o)
	{
		FaceSeenInQuestioning(c.Ped, Game.Player.Character);
		Interrogation it = c.It;
		Ped character = Game.Player.Character;
		NemesisRecord rec = it.Rec;
		Personality personality = it.Temper ?? Personality.Cold;
		string text = Speaker(it);
		int before = rec?.Hate ?? 0;
		int before2 = rec?.Fear ?? 0;
		_ = it.LastChance;
		int num = _rng.Next(100);
		if (o.Odds < 0)
		{
			_ = 1;
		}
		else
			_ = num < o.Odds;
		_ = InterroNote;
		if (o.Key.StartsWith("cat:"))
		{
			ToggleCategory(c, o.Key.Substring(4));
			return;
		}
		if (o.Key.StartsWith("q:"))
		{
			AskQuestion(c, o);
			return;
		}
		switch (o.Key)
		{
		case "ibribe":
		{
			int num2 = BribeCost(it);
			if (CashDollars < num2)
			{
				break;
			}
			c.PayAmount = num2;
			MONEY._MONEY_DECREMENT_CASH_BALANCE(c.PayAmount * 100);
			if (!it.Ped.IsHogtied && !PED.IS_PED_RAGDOLL(it.Ped.Handle))
			{
				GesturePay(it.Ped, youPay: true);
			}
			it.Bribed = true;
			bool flag = personality == Personality.Greedy || (rec != null && Mind.N(rec, "Money") >= 60);
			bool flag2 = rec != null && rec.Wealth == Wealth.Poor;
			string situation;
			if (personality == Personality.Loyal)
			{
				it.BribeBonus = -10;
				if (rec != null)
				{
					int hate = rec.Hate;
					rec.AddHate(5);
					CapScuffle(rec, hate);
				}
				situation = "bribe_loyal";
			}
			else if (rec != null && rec.Wealth == Wealth.Rich)
			{
				it.BribeBonus = 0;
				situation = "bribe_rich";
			}
			else if (flag)
			{
				it.BribeBonus = 30;
				situation = "bribe_greedy";
			}
			else if (flag2)
			{
				it.BribeBonus = 15;
				situation = "bribe_poor";
			}
			else
			{
				it.BribeBonus = 8;
				situation = "bribe";
			}
			c.Line = InterroLines.Pick(situation, it.Gang, personality, _rng, null, null, LeaderOut(it.Gang, it.Rec)) ?? "Money don't buy everything. But it helps.";
			it.Act("PAID");
			Feed(string.Format("BRIBED {0}: ${1} - talk {2:+0;-0;0}%{3}", text, num2, it.BribeBonus, flag ? ", lies less" : ""), (it.BribeBonus > 0) ? Theme.Good : Theme.Warn, rec);
			break;
		}
		case "ithreat":
		{
			it.Threats++;
			it.ThreatsUsed++;
			it.ScaredSinceThreat = false;
			Terrify(it, Balance.TerrorThreat, "THREATENED");
			SayAny(character, "threaten", ArthurThreats, it.Ped);
			int item = Personalities.Interrogation(it.Temper).threat;
			bool flag3 = Unscared(it);
			ref string line = ref c.Line;
			string situation2;
			if ((item < 0) | flag3)
			{
				situation2 = "threat_defy";
			}
			else if (personality == Personality.Coward || it.Terror >= 60f)
			{
				situation2 = "threat_scared";
			}
			else
			{
				situation2 = ((_rng.Next(2) == 0) ? "threat_defy" : "threat");
			}
			line = InterroLines.Pick(situation2, it.Gang, personality, _rng, null, null, LeaderOut(it.Gang, it.Rec)) ?? (((item < 0) | flag3) ? "Go on then. Do it." : "...You wouldn't.");
			if (flag3)
			{
				if ((personality == Personality.Hothead || personality == Personality.Proud) && _rng.Next(2) == 0)
				{
					OutOfPatience(c, it, "called your bluff");
					return;
				}
				if (Strain(c, it, 2f, "an empty threat"))
				{
					return;
				}
			}
			break;
		}
		case "idone":
			SayAny(character, "done talking", ArthurDone, it.Ped);
			Feed("DONE " + text + ": you left it there (not scared of you - nothing spared)", Theme.Dim, rec);
			c.Line = ThatsAllLine(personality, IsMourner(it.Ped));
			EndConvoSoon(c, "that's all");
			return;
		case "irelease":
			LetGoAccounting(it);
			Say(character, "WITNESS_DISMISS", it.Ped);
			Feed("LET GO " + text + " after questioning" + ((rec != null) ? (": hate " + Delta(before, rec.Hate) + "  fear " + Delta(before2, rec.Fear)) : ""), Theme.Dim, rec);
			c.Line = InterroLines.Pick((it.Terror >= 55f) ? "letgo_scared" : "letgo", it.Gang, personality, _rng, null, null, LeaderOut(it.Gang, rec), it.Ped != null && it.Ped.Exists() && Models.Female((uint)it.Ped.Model.Hash)) ?? "...";
			EndConvoSoon(c, "release");
			return;
		}
		it.LastChance = ChanceToTalk(it, character);
		if (rec != null)
		{
			SaveRoster();
		}
		BuildOptions(c);
	}

	private void EndInterrogation(bool released, bool quiet = true)
	{
		if (_interro?.Rec != null)
		{
			Interrogation x = _interro;
			List<string> list = x.AnsweredNow.Where((string a) => !x.Reported.Contains(a)).ToList();
			List<string> list2 = x.ActOrder.Select((string a) => (x.ActCount[a] <= 1) ? a.ToLowerInvariant() : $"{a.ToLowerInvariant()} x{x.ActCount[a]}").ToList();
			if (x.Reported.Count == 0 || list.Count > 0)
			{
				string text = ((list.Count > 0) ? ("answered " + string.Join(", ", list.Select((string id) => Questions.All.FirstOrDefault((QuestionRow q) => q.Id == id)?.Answer ?? id))) : "told you nothing");
				History(x.Rec, string.Format("QUESTIONED{0}: {1} - fear {2:0} -> {3:0}{4}", (x.Reported.Count > 0) ? " (again)" : "", text, x.StartTerror, x.Terror, (list2.Count > 0) ? (" - " + string.Join(", ", list2)) : ""), Theme.Gold);
			}
			foreach (string item in list)
			{
				x.Reported.Add(item);
			}
			if (x.Reported.Count == 0)
			{
				x.Reported.Add("-");
			}
		}
		if (_interro != null && _interro.Rec != null && _interro.Ped.Exists() && !DeadNow(_interro.Ped))
		{
			NemesisRecord rec = _interro.Rec;
			int num = (int)Math.Round((_interro.Terror - _interro.StartTerror) / 2f);
			if (_interro.Terror >= 40f && !_interro.FearRemembered)
			{
				_interro.FearRemembered = true;
				Remember(rec, "Fear", (int)Math.Min(90f, _interro.Terror), "you questioned him");
			}
			if (_interro.CampDone && rec.GaveCamp && !_interro.ShameRemembered)
			{
				_interro.ShameRemembered = true;
				Remember(rec, "Shame", 60, "he talked - gave up his own");
			}
			if (num > 0)
			{
				int fear = rec.Fear;
				rec.Fear = Math.Min(100, rec.Fear + num);
				Feed($"FEAR {rec.Name}: questioning left its mark - fear {Delta(fear, rec.Fear)}  (interrogation fear {_interro.StartTerror:0} -> {_interro.Terror:0})", (150, 170, 210), rec);
				_interro.StartTerror = _interro.Terror;
				SaveRoster();
			}
		}
		HidePrompts();
		HideLockPrompt();
		Interrogation interro = _interro;
		_interro = null;
		_interroCandidate = null;
		ReleaseHisPeople(released && interro != null && interro.GoNow && CanGoForYou(interro.Ped, Game.Player.Character));
		if (interro?.Ped != null && interro.Ped.Exists())
		{
			ENTITY.FREEZE_ENTITY_POSITION(interro.Ped.Handle, p1: false);
		}
		if (interro?.Ped != null && interro.Ped.Exists())
		{
			interro.Ped.BlockPermanentEvents = StaysBlocked(interro.Ped);
			TASK.TASK_CLEAR_LOOK_AT(interro.Ped.Handle);
		}
		if (released && interro != null && (interro.LetGo || interro.BargainStruck) && interro.Ped != null && interro.Ped.Exists() && !DeadNow(interro.Ped))
		{
			if (_surrenderGroup == 0)
			{
				_surrenderGroup = World.AddRelationshipGroup("NEMESIS_SURRENDERED");
			}
			interro.Ped.RelationshipGroup = _surrenderGroup;
			World.SetRelationshipBetweenGroups((eRelationshipType)3, _surrenderGroup, Game.Player.Character.RelationshipGroup);
			if (!interro.HeldByUs)
			{
				interro.Ped.BlockPermanentEvents = true;
				_sparedBound[interro.Ped.Handle] = Game.GameTime;
				GrudgeLog(string.Format("INTERRO {0}: ped {1} {2} - he runs once he's free", interro.BargainStruck ? "bargain struck" : "let go", interro.Ped.Handle, interro.Ped.IsHogtied ? "hogtied" : "down / held"));
			}
		}
		if (interro?.Ped == null || !interro.Ped.Exists() || DeadNow(interro.Ped))
		{
			return;
		}
		if (released && interro.GoNow)
		{
			interro.GoNow = false;
			if (CanGoForYou(interro.Ped, Game.Player.Character))
			{
				GoesForYou(interro, Game.Player.Character);
				return;
			}
		}
		if ((released & quiet) && !interro.GotAway)
		{
			TalkEndedQuietly(interro.Ped, interro.LetGo || interro.BargainStruck);
		}
		if (interro.HeldByUs)
		{
			TASK.CLEAR_PED_TASKS(interro.Ped.Handle, p1: true, p2: true);
			if (released)
			{
				AfterQuestioning(interro, Game.Player.Character);
			}
		}
	}

	private void AfterQuestioning(Interrogation it, Ped player)
	{
		int handle = it.Ped.Handle;
		AfterTalk afterTalk = InterroPatience.After(it.Terror, it.Temper, it.Calm, it.LetGo || it.BargainStruck, it.Warned);
		bool flag = afterTalk != AfterTalk.Run && !it.LetGo && !it.BargainStruck && BackToGrave(it.Ped);
		bool flag2 = !flag && afterTalk != AfterTalk.Run && !it.LetGo && !it.BargainStruck && BackToHisPatrol(handle);
		if (flag | flag2)
		{
			switch (afterTalk)
			{
			case AfterTalk.StareDown:
				ShowSubtitle(Speaker(it) + ": \"" + PickLine(StareLines) + "\"");
				break;
			case AfterTalk.Mutter:
				Say(it.Ped, DefiantLines[_rng.Next(DefiantLines.Length)], player);
				ShowSubtitle(Speaker(it) + ": \"" + PickLine(MutterLines) + "\"");
				break;
			}
		}
		else
		{
			switch (afterTalk)
			{
			case AfterTalk.Run:
				StartRunning(handle, player);
				_recentFoes[handle] = Game.GameTime;
				_runnerRolled.Remove(handle);
				_letGoRunners.Add(handle);
				break;
			case AfterTalk.WalkOff:
				WalkOff(handle, player);
				break;
			case AfterTalk.Business:
				TASK.TASK_WANDER_STANDARD(handle, 10f, 10);
				break;
			case AfterTalk.StareDown:
				TASK.TASK_TURN_PED_TO_FACE_ENTITY(handle, player.Handle, 3000, 0f, 0f, 0f);
				_walkOffs[handle] = new Walker
				{
					Since = Game.GameTime,
					Until = Game.GameTime + 3000
				};
				ShowSubtitle(Speaker(it) + ": \"" + PickLine(StareLines) + "\"");
				break;
			case AfterTalk.Mutter:
				WalkOff(handle, player);
				Say(it.Ped, DefiantLines[_rng.Next(DefiantLines.Length)], player);
				ShowSubtitle(Speaker(it) + ": \"" + PickLine(MutterLines) + "\"");
				break;
			}
		}
		GrudgeLog(string.Format("INTERRO closed on {0} (fear {1:0}{2}{3}): {4}{5}", Speaker(it), it.Terror, it.Calm ? $", patience {it.Patience:0}/{it.PatienceMax:0}" : ", from a fight", (it.LetGo || it.BargainStruck) ? ", let go" : "", afterTalk, flag ? " - back to his place at the grave" : (flag2 ? " - back to his patrol" : "")));
	}

	private static bool Unscared(Interrogation it)
	{
		if (it.Calm)
		{
			return it.Terror < (float)it.CampNeed;
		}
		return false;
	}

	private string FoughtYouWhy(int h)
	{
		if (!_fighters.ContainsKey(h))
		{
			if (!_cameAtYou.Contains(h))
			{
				if (!_selfDefence.Contains(h))
				{
					if (!_combatants.TryGetValue(h, out var value) || Game.GameTime - value >= 180000)
					{
						if (!_recentFoes.TryGetValue(h, out var value2) || Game.GameTime - value2 >= 180000)
						{
							if (!_hitByYouAt.TryGetValue(h, out var value3) || Game.GameTime - value3 >= 180000)
							{
								return null;
							}
							return $"you hit him {(Game.GameTime - value3) / 1000} s ago";
						}
						return $"fought or fled you {(Game.GameTime - value2) / 1000} s ago";
					}
					return $"in a fight with you {(Game.GameTime - value) / 1000} s ago";
				}
				return "went for you";
			}
			return "came at you";
		}
		return "fought you";
	}

	private bool Strain(Convo c, Interrogation it, float cost, string why)
	{
		float patience = it.Patience;
		it.Patience = Math.Max(0f, it.Patience - cost);
		if (it.Patience <= 0f)
		{
			OutOfPatience(c, it, why);
			return true;
		}
		if (it.Patience <= 1f && !it.Warned)
		{
			it.Warned = true;
			c.Line = (c.Line + " " + WarnLine(it.Temper ?? Personality.Cold)).Trim();
			Feed($"INTERROGATION {Speaker(it)}: his patience is about gone ({it.Patience:0} left) - one more and he's done", Theme.Warn, it.Rec);
		}
		GrudgeLog($"INTERRO {Speaker(it)} patience {patience:0} -> {it.Patience:0} ({why}, fear {it.Terror:0} under his line {it.CampNeed})");
		return false;
	}

	private static void FaceYouDown(Ped p, Ped player)
	{
		TASK.TASK_TURN_PED_TO_FACE_ENTITY(p.Handle, player.Handle, -1, 0f, 0f, 0f);
		TASK.TASK_LOOK_AT_ENTITY(p.Handle, player.Handle, -1, 0, 51, 0);
	}

	private bool CanGoForYou(Ped p, Ped player)
	{
		if (p != null && p.Exists() && !DeadNow(p) && !p.IsIncapacitated && !GrappledBy(p, player) && !p.IsHogtied && !p.IsRagdoll && !TASK.IS_PED_IN_WRITHE(p.Handle) && !CantWalk(p.Handle))
		{
			return !ENTITY.IS_ENTITY_ATTACHED(p.Handle);
		}
		return false;
	}

	private void OutOfPatience(Convo c, Interrogation it, string why)
	{
		it.Patience = 0f;
		Ped character = Game.Player.Character;
		Personality t = it.Temper ?? Personality.Cold;
		if (it.Rec != null)
		{
			SaveRoster();
		}
		string text = StoryBansWeapons(character.Position);
		if (!CanGoForYou(it.Ped, character) || text != null)
		{
			c.Line = ((text != null) ? PickLine(SafeTownDoneLines) : DoneLine(t));
			Feed("INTERROGATION " + Speaker(it) + ": out of patience (" + why + ") - he won't say another word", Theme.Warn, it.Rec);
			GrudgeLog("INTERRO " + Speaker(it) + " out of patience (" + why + ") - " + ((text != null) ? ("not here (" + text + ")") : "he can't go for you") + ": done talking");
			EndConvoSoon(c, "out of patience");
		}
		else
		{
			ShowSubtitle(Speaker(it) + ": \"" + SnapLine(t) + "\"");
			Say(it.Ped, DefiantLines[_rng.Next(DefiantLines.Length)], character);
			GrudgeLog($"INTERRO {Speaker(it)} SNAPPED ({why}; fear {it.Terror:0} under his line {it.CampNeed}) - he goes for you");
			if (it.Rec != null)
			{
				History(it.Rec, "WENT FOR YOU when you questioned him", Theme.Warn);
			}
			it.GoNow = true;
			EndConvo("he snapped");
		}
	}

	internal bool WentForYouQuestioned(int h)
	{
		if (_wentForYouAt.TryGetValue(h, out var value))
		{
			return Game.GameTime - value < 60000;
		}
		return false;
	}

	private void GoesForYou(Interrogation it, Ped player)
	{
		Ped ped = it.Ped;
		int handle = ped.Handle;
		Crumbs.Native("Interrogation snap");
		TASK.CLEAR_PED_TASKS(handle, p1: true, p2: true);
		_wentForYouAt[handle] = Game.GameTime;
		if (_cameAtYou.Count > 300)
		{
			_cameAtYou.Clear();
		}
		_cameAtYou.Add(handle);
		_selfDefence.Add(handle);
		ped.RelationshipGroup = NemesisGroup();
		World.SetRelationshipBetweenGroups((eRelationshipType)6, NemesisGroup(), player.RelationshipGroup);
		PED.SET_PED_COMBAT_ATTRIBUTES(handle, 5, p2: true);
		PED.SET_PED_COMBAT_ATTRIBUTES(handle, 46, p2: true);
		uint num = Function.Call<uint>(9548732433391192802uL, new InputArgument[3] { handle, false, false });
		uint num2 = ((num != 0) ? WEAPON.GET_WEAPONTYPE_GROUP(num) : 0u);
		bool flag = num != 0 && num2 != 2685387236u && num2 != 308416707;
		if (flag)
		{
			try
			{
				WEAPON.SET_CURRENT_PED_WEAPON(handle, num, p2: true, 0, p4: false, p5: false);
			}
			catch
			{
			}
		}
		TASK.TASK_COMBAT_PED(handle, player.Handle, 0, 16);
		string text = ((!flag) ? "his fists" : (num2 switch
		{
			1548507267u => "something to throw", 
			3566412244u => "a knife", 
			_ => "his gun", 
		}));
		Feed("SNAPPED " + Speaker(it) + ": out of patience - he goes for you with " + text, Theme.Warn, it.Rec);
	}

	private string PickLine(string[] l)
	{
		return l[_rng.Next(l.Length)];
	}

	private string WarnLine(Personality t)
	{
		return PickLine(t switch
		{
			Personality.Coward => new string[2] { "Please, mister... leave me be. I'm warning you.", "Don't you push me. I mean it." }, 
			Personality.Greedy => new string[2] { "Time's money, friend. And you're about out of both.", "You ain't paying for this conversation. It's about over." }, 
			Personality.Loyal => new string[2] { "I've got nothing for you. Ask again and see what happens.", "I won't tell you twice." }, 
			Personality.Cold => new string[2] { "You're wasting my time. You won't waste much more of it.", "Careful now." }, 
			Personality.Proud => new string[2] { "I've answered to you long enough.", "Nobody talks to me like this for long." }, 
			Personality.Hothead => new string[2] { "One more question. Go on. Ask me one more.", "You're pushin' me, mister. You're pushin' real hard." }, 
			_ => new string[2] { "Last question, mister. Then I'm done with you.", "That's about enough of that." }, 
		});
	}

	private string SnapLine(Personality t)
	{
		return PickLine(t switch
		{
			Personality.Cold => new string[2] { "Enough.", "You should've let it be." }, 
			Personality.Proud => new string[2] { "Nobody talks to me like that!", "I'll not be spoken to like a dog!" }, 
			Personality.Hothead => new string[2] { "That's it! To hell with you!", "I've had enough of you!" }, 
			_ => new string[2] { "I'm done talking!", "Enough of this!" }, 
		});
	}

	private string DoneLine(Personality t)
	{
		return PickLine(t switch
		{
			Personality.Cold => new string[2] { "We're finished, you and me.", "That's all the talk you'll get." }, 
			Personality.Hothead => new string[2] { "I'm done talking to you! You hear me? Done!", "Cut me loose and ask me that again. I dare you." }, 
			_ => new string[2] { "I'm done talking to you.", "Not another word. Not one." }, 
		});
	}

	private string ThatsAllLine(Personality t, bool mourner)
	{
		return PickLine((!mourner) ? (t switch
		{
			Personality.Coward => new string[2] { "...Alright. Alright, mister.", "Yes sir. Good day, sir." }, 
			Personality.Greedy => new string[2] { "Cost me nothin'. Cost you your time.", "Then we're square. For now." }, 
			Personality.Loyal => new string[2] { "Good. Go on, then.", "Then leave us be." }, 
			Personality.Cold => new string[2] { "Then go.", "We're done." }, 
			Personality.Proud => new string[2] { "Then get out of my sight.", "Don't come at me like that again." }, 
			Personality.Hothead => new string[2] { "About damn time.", "Then quit wavin' that thing at me." }, 
			_ => new string[2] { "Suits me.", "Fine by me." }, 
		}) : new string[2] { "Then leave us to bury our own.", "Then let us grieve in peace." });
	}

	private static bool NoTowns(NemesisRecord n)
	{
		return Gangs.ById(n?.Gang)?.NoTowns ?? false;
	}

	private uint PlainModelOf(NemesisRecord rec)
	{
		string[] array = Gangs.ById(rec.Gang)?.TownModels;
		if (array == null || array.Length == 0)
		{
			return 0u;
		}
		if (string.IsNullOrEmpty(rec.PlainModel) || !array.Contains(rec.PlainModel))
		{
			rec.PlainModel = array[Seeds.For(rec, "plain").Next(array.Length)];
		}
		return MISC.GET_HASH_KEY(rec.PlainModel);
	}

	private TownMan HiddenTownMan(int handle)
	{
		return _townMen.FirstOrDefault((TownMan t) => t.Disguised && !t.Rec.CoverBlown && t.Ped != null && t.Ped.Handle == handle);
	}

	private void TryHiddenInTown(string town, Ped player)
	{
		foreach (Gang g in Gangs.All.Where((Gang x) => x.NoTowns && x.TownModels != null))
		{
			if ((g.OnlyDistricts != null && !g.OnlyDistricts.Contains(_regionDistrict)) || _townMen.Any((TownMan t) => t.Rec.Gang == g.Id))
			{
				continue;
			}
			if (_townMen.Count + _townArrivals.Count >= Balance.TownMaxMen)
			{
				GrudgeLog($"KLAN town {town} already has its {Balance.TownMaxMen} men");
				break;
			}
			if ((float)_rng.Next(100) >= (float)g.TownChancePercent * NightTownMult())
			{
				GrudgeLog("KLAN none of the " + g.Name + " in " + town + " this time");
				continue;
			}
			List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.Gang == g.Id && n.IsAlive && !n.PresumedDead && n.CanHunt && !Resting(n) && !_worldNemeses.ContainsValue(n) && n != ActiveRecord).ToList();
			if (list.Count != 0)
			{
				NemesisRecord nemesisRecord = list[_rng.Next(list.Count)];
				GrudgeLog("KLAN " + nemesisRecord.FullName + " is in " + town + " out of his robe" + (nemesisRecord.CoverBlown ? " (you know him)" : ""));
				SpawnTownPresence(nemesisRecord, town, player);
			}
		}
	}

	private bool GreetHidden(int target)
	{
		TownMan townMan = HiddenTownMan(target);
		if (townMan == null)
		{
			return false;
		}
		NemesisRecord rec = townMan.Rec;
		rec.PlainGreets++;
		rec.Touch();
		if (rec.PlainGreets >= 3)
		{
			Unmask(townMan, "greet");
			return true;
		}
		string[] array = ((rec.PlainGreets != 1) ? new string[4] { "You again. Folks round here keep to their own, you know.", "Twice in a day. You keep good company?", "We like things the way they are in this county.", "Mind how you go. It gets dark out there." } : new string[4] { "Afternoon, friend.", "Fine day for it.", "Evenin'. Haven't seen you round here.", "Mister." });
		ShowSubtitle(rec.Name + ": \"" + array[_rng.Next(array.Length)] + "\"");
		Feed($"GREETED {rec.FullName} - a townsman ({rec.PlainGreets}/3)", Theme.Dim);
		SaveRoster();
		return true;
	}

	private void HiddenSlip(NemesisRecord rec, string how)
	{
		if (rec == null || rec.CoverBlown)
		{
			return;
		}
		TownMan townMan = _townMen.FirstOrDefault((TownMan t) => t.Rec == rec && t.Disguised);
		if (townMan == null)
		{
			return;
		}
		if (how == "antagonize")
		{
			int num;
			if (rec.Personality == Personality.Hothead)
			{
				num = 80;
			}
			else
			{
				num = ((rec.Personality == Personality.Proud) ? 65 : 35);
			}
			if (_rng.Next(100) >= num)
			{
				GrudgeLog($"KLAN {rec.Name} held his tongue ({num}%)");
				return;
			}
		}
		Unmask(townMan, how);
	}

	private void Unmask(TownMan tm, string how)
	{
		NemesisRecord rec = tm.Rec;
		Gang gang = Gangs.ById(rec.Gang);
		rec.CoverBlown = true;
		tm.Disguised = false;
		string text = how switch
		{
			"greet" => (rec.Personality == Personality.Hothead) ? "Keep sniffin' round me, the night riders'll come callin' for you." : "Folks like you don't last long in this county. Ask around - after dark.", 
			"antagonize" => "You'll learn your place when the fires come, boy.", 
			"rob" => null, 
			"questioned" => "Alright! Alright... I ride with 'em. Everybody here does, near enough.", 
			_ => "Get your hands off me! You don't know who you're dealin' with!", 
		};
		if (text != null)
		{
			ShowSubtitle(rec.Name + ": \"" + text + "\"");
		}
		string text2 = how switch
		{
			"questioned" => "what he told you", 
			"greet" => "what he let slip", 
			"rob" => "a white hood folded in his coat", 
			_ => "a white hood falling out of his coat", 
		};
		if (tm.Blip == null || !tm.Blip.Exists())
		{
			Crumbs.Native("KlanCover blip add (V2)");
			tm.Blip = tm.Ped.AddBlip((BlipType)2545348716u);
			if (tm.Blip != null)
			{
				Function.Call(11290983183885202434uL, tm.Blip.Handle, new InputArgument(UiDraw.ForeverVarString(rec.FullName + " (" + (gang?.Name ?? "Klan") + ", out of his robe)")));
			}
		}
		Remember(rec, (rec.Personality == Personality.Coward) ? "Fear" : "Anger", 45, "you found him out in town");
		History(rec, "FOUND OUT in " + tm.Town + ": one of " + (gang?.Name ?? "them") + ", living as a townsman (" + text2 + ")", Theme.Warn);
		Feed("UNMASKED " + rec.FullName + " rides with " + (gang?.Name ?? "the Klan") + " - " + text2, Theme.Warn, rec);
		GrudgeNotice(rec.FullName + " is one of " + (gang?.Name ?? "the Klan") + " - " + text2 + ".");
		GrudgeLog("KLAN " + rec.FullName + " unmasked in " + tm.Town + " by " + how);
		SaveRoster();
	}

	private void KlanHonorTick()
	{
		if (Game.GameTime < _nextKlanHonor)
		{
			return;
		}
		_nextKlanHonor = Game.GameTime + 500;
		if (_honorDecor < 0)
		{
			AskHonorDecor();
		}
		if (_honorDecor == 0)
		{
			return;
		}
		foreach (int item in OurHandles())
		{
			if (!_honorMarked.Contains(item) && ENTITY.DOES_ENTITY_EXIST(item) && KlanMan(item))
			{
				MarkHonor(item);
			}
		}
		if (_honorMarked.Count > 256)
		{
			_honorMarked.RemoveWhere((int h) => !ENTITY.DOES_ENTITY_EXIST(h));
		}
		if (_klanBodies.Count > 64)
		{
			_klanBodies.RemoveWhere((int h) => !ENTITY.DOES_ENTITY_EXIST(h));
		}
	}

	private void MarkHonor(int h)
	{
		if (_honorDecor < 0)
		{
			AskHonorDecor();
		}
		if (_honorDecor == 1 && _honorMarked.Add(h))
		{
			Crumbs.Native("klan honor decor");
			bool flag = Function.Call<bool>(16757697947711703311uL, new InputArgument[3]
			{
				h,
				new InputArgument(UiDraw.CString("honor_override")),
				0
			});
			if (_klanHonorSet++ == 0)
			{
				GrudgeLog(string.Format("KLANHONOR first Klansman marked (ped {0}{1}): {2}", h, ENTITY.IS_ENTITY_DEAD(h) ? ", a body" : "", flag ? "set" : "the game refused it"));
			}
		}
	}

	internal void KlanBody(Ped body, string gangId)
	{
		if (!(body == null) && body.Exists() && !(gangId != Gangs.Klan.Id))
		{
			_klanBodies.Add(body.Handle);
			MarkHonor(body.Handle);
		}
	}

	private void AskHonorDecor()
	{
		List<int> list = new List<int>();
		for (int i = 1; i <= 7; i++)
		{
			if (Function.Call<bool>(8229574572667171442uL, new InputArgument[2]
			{
				new InputArgument(UiDraw.CString("honor_override")),
				i
			}))
			{
				list.Add(i);
			}
		}
		_honorDecor = (list.Contains(3) ? 1 : 0);
		NemesisMod nemesisMod = this;
		string line;
		if (_honorDecor == 1)
		{
			line = "KLANHONOR the game knows \"honor_override\" (an int decorator) - every Klansman of ours is marked: killing him costs no honor";
		}
		else
		{
			line = ((list.Count > 0) ? ("KLANHONOR \"honor_override\" is a decorator of type " + string.Join(", ", list) + ", not an int - Klansmen aren't marked") : "KLANHONOR the game has no \"honor_override\" decorator - Klansmen aren't marked (killing one may still cost honor)");
		}
		nemesisMod.GrudgeLog(line);
	}

	private IEnumerable<int> OurHandles()
	{
		foreach (var item2 in OurPeds())
		{
			Ped item = item2.p;
			if (item != null)
			{
				yield return item.Handle;
			}
		}
		foreach (int item3 in _followerOf.Keys.ToList())
		{
			yield return item3;
		}
		foreach (int item4 in _worldNemeses.Keys.ToList())
		{
			yield return item4;
		}
		foreach (int item5 in _nemesisBodies.Keys.ToList())
		{
			yield return item5;
		}
		foreach (int item6 in _klanBodies.ToList())
		{
			yield return item6;
		}
	}

	private bool KlanMan(int h)
	{
		uint value = ENTITY.GET_ENTITY_MODEL(h);
		if (KlanRallyModels.Contains(value))
		{
			return true;
		}
		if (_klanBodies.Contains(h))
		{
			return true;
		}
		if (_nemesisBodies.TryGetValue(h, out var value2) && value2?.Gang == Gangs.Klan.Id)
		{
			return true;
		}
		if (_worldNemeses.TryGetValue(h, out var value3) && value3?.Gang == Gangs.Klan.Id)
		{
			return true;
		}
		if (_followerOf.TryGetValue(h, out var value4) && value4?.Gang == Gangs.Klan.Id)
		{
			return true;
		}
		if (_activeNemesisPed != null && _activeNemesisPed.Handle == h && ActiveRecord?.Gang == Gangs.Klan.Id)
		{
			return true;
		}
		if (_townMen.Any((TownMan t) => t.Ped != null && t.Ped.Handle == h && t.Rec?.Gang == Gangs.Klan.Id))
		{
			return true;
		}
		return _liveCamps.Values.Any((LiveCamp c) => c.Boss?.Gang == Gangs.Klan.Id && c.Peds.Any((Ped p) => p != null && p.Handle == h));
	}

	private void DebugLawTest(Ped player)
	{
		LawTestEnd("a new test");
		Gang gang = Gangs.ById("lemoyneraiders");
		if (gang == null || !FactionModels.TryGetValue(gang.Id, out var value) || value.Length == 0)
		{
			SpawnerSays("law test: no Raider models.");
			return;
		}
		if (_lawTestHateGroup == 0)
		{
			_lawTestHateGroup = World.AddRelationshipGroup("NEMESIS_LAWTEST_HATE");
		}
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _lawTestHateGroup, player.RelationshipGroup);
		(string, uint)[] array = new (string, uint)[4]
		{
			("the mod's own group (as now)", GroupFor(gang)),
			("the game's Raiders group", MISC.GET_HASH_KEY("rel_gang_lemoyne_raiders")),
			("the mod's group, hostile to you", _lawTestHateGroup),
			("the game's criminals group", MISC.GET_HASH_KEY("rel_criminals"))
		};
		float heading = player.Heading;
		double num = (double)heading * Math.PI / 180.0;
		Vector3 vector = new Vector3(0f - (float)Math.Sin(num), (float)Math.Cos(num), 0f);
		Vector3 vector2 = new Vector3((float)Math.Cos(num), (float)Math.Sin(num), 0f);
		Vector3 vector3 = player.Position + vector * 8f;
		for (int i = 0; i < array.Length; i++)
		{
			Vector3 pos = Ground(vector3 + vector2 * (((float)i - 1.5f) * 2.5f));
			Ped ped = SpawnPed(value[_rng.Next(value.Length)], pos, heading + 180f);
			if (ped == null)
			{
				GrudgeLog($"LAWTEST {i + 1}: the model didn't load - not made");
				continue;
			}
			MakeOurs(ped.Handle);
			ApplyFactionStyle(ped, gang.Id);
			WEAPON.REMOVE_ALL_PED_WEAPONS(ped.Handle, p1: true, p2: true);
			ped.RelationshipGroup = array[i].Item2;
			ped.BlockPermanentEvents = true;
			TASK.TASK_STAND_STILL(ped.Handle, -1);
			LawTestMan lawTestMan = new LawTestMan
			{
				P = ped,
				N = i + 1,
				What = array[i].Item1
			};
			try
			{
				lawTestMan.Blip = ped.AddBlip((BlipType)2545348716u);
				if (lawTestMan.Blip != null)
				{
					Function.Call(11290983183885202434uL, lawTestMan.Blip.Handle, new InputArgument(UiDraw.ForeverVarString($"Law test {i + 1} - {array[i].Item1}")));
				}
			}
			catch
			{
			}
			_lawTest.Add(lawTestMan);
		}
		_lawTestUntil = Game.GameTime + 300000;
		_fairUntil = 0;
		try
		{
			_lawTestBounty = LAW.GET_BOUNTY(Game.Player.Handle);
			_lawTestWanted = PLAYER.GET_PLAYER_WANTED_LEVEL(Game.Player.Handle) > 0;
		}
		catch
		{
		}
		GrudgeLog(string.Format("LAWTEST started: {0} Raiders, left to right - {1} - bounty ${2}, wanted {3}; fair game off for 5 minutes", _lawTest.Count, string.Join("; ", _lawTest.Select((LawTestMan m) => $"{m.N} {m.What}")), _lawTestBounty / 100, _lawTestWanted));
		SpawnerSays("law test: left to right - 1 the mod's group, 2 the game's Raiders, 3 the mod's group (hostile), 4 the game's criminals. Kill one, wait 30 s for its LAWTEST line, then the next - 1 last.");
	}

	private void LawTestTick(Ped player)
	{
		if (_lawTest.Count == 0 || Game.GameTime < _nextLawTest)
		{
			return;
		}
		_nextLawTest = Game.GameTime + 500;
		int handle = Game.Player.Handle;
		int num = _lawTestBounty;
		bool flag = _lawTestWanted;
		try
		{
			num = LAW.GET_BOUNTY(handle);
			flag = PLAYER.GET_PLAYER_WANTED_LEVEL(handle) > 0;
		}
		catch
		{
		}
		foreach (LawTestMan item in _lawTest)
		{
			if (item.KilledAt == 0 && item.P != null && item.P.Exists() && item.P.IsDead)
			{
				item.KilledAt = Game.GameTime;
				item.BountyBefore = _lawTestBounty;
				item.WantedBefore = _lawTestWanted;
				bool flag2 = PED.GET_PED_SOURCE_OF_DEATH(item.P.Handle) == player.Handle;
				GrudgeLog(string.Format("LAWTEST {0} ({1}) killed{2} - bounty before ${3}, wanted {4}", item.N, item.What, flag2 ? " by you" : " - not by you", item.BountyBefore / 100, item.WantedBefore));
				if (item.Blip != null && item.Blip.Exists())
				{
					item.Blip.Delete();
				}
			}
			if (item.KilledAt == 0)
			{
				continue;
			}
			int[] array = new int[3] { 3000, 10000, 30000 };
			while (item.Said < array.Length && Game.GameTime - item.KilledAt >= array[item.Said])
			{
				bool flag3 = false;
				bool flag4 = false;
				bool flag5 = false;
				try
				{
					flag3 = Function.Call<bool>(7629521592523355275uL, new InputArgument[1] { handle });
					flag4 = Function.Call<bool>(844106609231005222uL, new InputArgument[1] { handle });
					flag5 = LAW.IS_LAW_INCIDENT_ACTIVE(handle);
				}
				catch
				{
				}
				GrudgeLog(string.Format("LAWTEST {0} ({1}) +{2} s: bounty ${3} -> ${4}, wanted {5}, witnesses {6}{7}, law incident {8}", item.N, item.What, array[item.Said] / 1000, item.BountyBefore / 100, num / 100, flag, flag3 ? "active" : "none active", flag4 ? " / pending" : "", flag5 ? "on" : "off"));
				item.Said++;
			}
		}
		if (_lawTest.All((LawTestMan m) => m.KilledAt == 0 || m.Said >= 3))
		{
			_lawTestBounty = num;
			_lawTestWanted = flag;
		}
		if (_lawTest.All((LawTestMan m) => m.KilledAt > 0 && m.Said >= 3))
		{
			LawTestEnd("all four done");
		}
		else if (!LawTestOn)
		{
			LawTestEnd("5 minutes up");
		}
	}

	private void LawTestEnd(string why)
	{
		if (_lawTest.Count == 0)
		{
			return;
		}
		foreach (LawTestMan item in _lawTest)
		{
			if (item.Blip != null && item.Blip.Exists())
			{
				item.Blip.Delete();
			}
			if (item.P != null && item.P.Exists() && !item.P.IsDead)
			{
				item.P.Delete();
			}
		}
		_lawTest.Clear();
		_lawTestUntil = 0;
		GrudgeLog("LAWTEST over (" + why + ") - fair game back to normal");
	}

	internal static string LeaderCopyId(Gang g)
	{
		if (g != null)
		{
			return "lore_leader_" + g.Id;
		}
		return null;
	}

	internal static bool IsLeaderCopy(NemesisRecord r)
	{
		if (r != null && r.Id != null)
		{
			return r.Id.StartsWith("lore_leader_");
		}
		return false;
	}

	internal static string FamilyNameOf(NemesisRecord r)
	{
		if (r != null && r.Name != null)
		{
			if (!IsLeaderCopy(r))
			{
				return NameBank.Surname(r.Name);
			}
			return r.Name.Substring(r.Name.LastIndexOf(' ') + 1);
		}
		return "";
	}

	private bool LeaderCopyFits(Gang g, bool making = false)
	{
		if (g != null && !g.StoryOnly && g != Gangs.Army && !g.OrdersNotFeelings && !IsDestroyed(g) && !string.IsNullOrEmpty(g.LoreLeader ?? g.LeaderName))
		{
			if (making)
			{
				return Roster.Any((NemesisRecord n) => n.Gang == g.Id && n.IsAlive && !IsLeaderCopy(n));
			}
			return true;
		}
		return false;
	}

	private void SyncLeaderCopies()
	{
		bool flag = false;
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			string id = LeaderCopyId(gang);
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == id);
			if (nemesisRecord != null && RepairLeaderCopy(gang, nemesisRecord))
			{
				flag = true;
			}
			LeaderSeat leaderSeat = SeatOf(gang);
			bool flag2 = leaderSeat == null || leaderSeat.Fallen == null;
			if (nemesisRecord != null && (!nemesisRecord.IsAlive || nemesisRecord.PresumedDead))
			{
				if (nemesisRecord.PresumedDead)
				{
					nemesisRecord.IsAlive = false;
					nemesisRecord.PresumedDead = false;
				}
				if (flag2 && leaderSeat != null && leaderSeat.Successor == nemesisRecord.Id)
				{
					string text = ((nemesisRecord.Fate == "Arrested") ? "arrested" : "killed");
					if (nemesisRecord.SeatFell)
					{
						Seats[gang.Id] = new LeaderSeat
						{
							Fallen = text,
							OldName = nemesisRecord.FullName,
							At = GameMinutesNow()
						};
						GrudgeLog("LEADER " + gang.Name + ": " + nemesisRecord.FullName + "'s fall was already counted (the world file missed it) - the seat is open again, quietly");
					}
					else
					{
						nemesisRecord.SeatFell = true;
						Fall(gang, nemesisRecord.FullName, text, nemesisRecord.KilledByPlayer, nemesisRecord);
					}
					flag = true;
				}
			}
			else if (nemesisRecord != null)
			{
				string text2;
				if (flag2)
				{
					if (Config.FindLeaders)
					{
						text2 = ((!LeaderCopyFits(gang)) ? "his outfit's out of the picture" : null);
					}
					else
					{
						text2 = "lore leaders locked";
					}
				}
				else
				{
					text2 = "his seat fell (" + leaderSeat.Fallen + ")";
				}
				if (text2 != null)
				{
					if (OffStage(nemesisRecord))
					{
						BenchLeaderCopy(nemesisRecord, text2);
						flag = true;
					}
					continue;
				}
				if (leaderSeat == null)
				{
					leaderSeat = (Seats[gang.Id] = new LeaderSeat());
				}
				if (leaderSeat.Successor != nemesisRecord.Id)
				{
					leaderSeat.Successor = nemesisRecord.Id;
					flag = true;
				}
			}
			else if ((Config.FindLeaders & flag2) && LeaderCopyFits(gang, making: true))
			{
				if (MakeLeaderCopy(gang))
				{
					flag = true;
				}
			}
			else if (leaderSeat != null && leaderSeat.Fallen == null && leaderSeat.Successor != null && leaderSeat.Successor.StartsWith("lore_leader_"))
			{
				leaderSeat.Successor = null;
				flag = true;
			}
		}
		if (flag)
		{
			ApplyLeaders();
			SaveRoster();
			SaveWorld();
		}
	}

	private uint LeaderFace(Gang g)
	{
		foreach (string item in from x in (g.LeaderModel ?? "").Split('|')
			select x.Trim() into x
			where x.Length > 0
			select x)
		{
			uint num = MISC.GET_HASH_KEY(item);
			if (STREAMING.IS_MODEL_IN_CDIMAGE(num))
			{
				return num;
			}
		}
		if (g.Seed != null)
		{
			foreach (var item2 in g.Seed.OrderByDescending(((int Rank, int Count, PedHash[] Models) s) => s.Rank))
			{
				PedHash[] array = item2.Models ?? new PedHash[0];
				foreach (PedHash pedHash in array)
				{
					if (!BountyModel(Models.Name((uint)pedHash)))
					{
						return (uint)pedHash;
					}
				}
			}
		}
		if (g.TroopModels == null || g.TroopModels.Length == 0)
		{
			return 424175505u;
		}
		return (uint)g.TroopModels[0];
	}

	private bool MakeLeaderCopy(Gang g)
	{
		string id = LeaderCopyId(g);
		string text = g.LoreLeader ?? g.LeaderName;
		if (Roster.Any((NemesisRecord n) => n.Id == id))
		{
			return false;
		}
		NemesisRecord nemesisRecord = BenchedLeaders.FirstOrDefault((NemesisRecord b) => b?.Id == id);
		if (nemesisRecord != null)
		{
			BenchedLeaders.Remove(nemesisRecord);
			GrudgeLog("LEADER " + text + ": back on the roster (lore leaders unlocked)");
		}
		else
		{
			nemesisRecord = JsonConvert.DeserializeObject<NemesisRecord>(JsonConvert.SerializeObject(LorePage(g)));
			nemesisRecord.Id = id;
			nemesisRecord.Name = text;
			nemesisRecord.Title = "";
			nemesisRecord.Origin = GrudgeOrigin.GangMember;
			nemesisRecord.SeedMember = true;
			nemesisRecord.CardLife = true;
			nemesisRecord.ModelHash = LeaderFace(g);
			nemesisRecord.OutfitHash = 0u;
			nemesisRecord.KinId = null;
			nemesisRecord.KinRelation = null;
			nemesisRecord.PersonalityKnown = true;
			nemesisRecord.Hate = (g.SeedHate.HasValue ? ((g.SeedHate.Value.min + g.SeedHate.Value.max) / 2) : 75);
			GrudgeLog($"LEADER {text}: out in the world (lore leaders unlocked) - {Models.Name(nemesisRecord.ModelHash)}, rank {nemesisRecord.Rank}");
		}
		nemesisRecord.IsAlive = true;
		nemesisRecord.PresumedDead = false;
		nemesisRecord.Rank = 5;
		nemesisRecord.Gang = g.Id;
		nemesisRecord.BossId = null;
		nemesisRecord.CampId = null;
		nemesisRecord.CampKnown = false;
		nemesisRecord.CampUnsure = false;
		Roster.Add(nemesisRecord);
		LeaderSeat leaderSeat = SeatOf(g);
		if (leaderSeat == null)
		{
			leaderSeat = (Seats[g.Id] = new LeaderSeat());
		}
		leaderSeat.Successor = nemesisRecord.Id;
		_nextCampAssign = 0;
		return true;
	}

	private bool RepairLeaderCopy(Gang g, NemesisRecord copy)
	{
		bool result = false;
		if (!copy.CardLife)
		{
			NemesisRecord nemesisRecord = LorePage(g);
			if (nemesisRecord != null)
			{
				copy.Past = ((nemesisRecord.Past == null) ? null : JsonConvert.DeserializeObject<List<PastEntry>>(JsonConvert.SerializeObject(nemesisRecord.Past)));
				copy.PastRolled = nemesisRecord.PastRolled;
				copy.BornYear = nemesisRecord.BornYear;
				copy.Birthplace = nemesisRecord.Birthplace;
				copy.LifeRules = nemesisRecord.LifeRules;
				copy.Personality = nemesisRecord.Personality;
				copy.PersonalityKnown = true;
				copy.KinId = null;
				copy.KinRelation = null;
				copy.CardLife = true;
				result = true;
				GrudgeLog($"LEADER {copy.Name}: his card's life (born {copy.BornYear}, {copy.Personality})");
			}
		}
		uint num = LeaderFace(g);
		if (copy.ModelHash != num && (!copy.IsAlive || OffStage(copy)))
		{
			GrudgeLog("LEADER " + copy.Name + ": his face " + Models.Name(copy.ModelHash) + " -> " + Models.Name(num));
			copy.ModelHash = num;
			copy.OutfitHash = 0u;
			result = true;
		}
		return result;
	}

	private void BenchLeaderCopy(NemesisRecord copy, string why)
	{
		BenchedLeaders.RemoveAll((NemesisRecord b) => b?.Id == copy.Id);
		BenchedLeaders.Add(copy);
		RemoveRecord(copy, "the leader benched - " + why);
		GrudgeLog("LEADER " + copy.Name + ": off the roster (" + why + ") - kept in world.json");
	}

	private void BenchLeaderCopies(string why)
	{
		foreach (NemesisRecord item in Roster.Where((NemesisRecord n) => IsLeaderCopy(n) && n.IsAlive).ToList())
		{
			BenchLeaderCopy(item, why);
		}
	}

	internal NemesisRecord LeaderPageOf(Gang g)
	{
		if (g == null || g.StoryOnly)
		{
			return null;
		}
		LeaderSeat seat = SeatOf(g);
		if (seat?.Fallen != null)
		{
			if (seat.Successor == null)
			{
				return null;
			}
			return Roster.FirstOrDefault((NemesisRecord n) => n.Id == seat.Successor);
		}
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == LeaderCopyId(g) && n.IsAlive);
		if (nemesisRecord != null)
		{
			return nemesisRecord;
		}
		return LorePage(g);
	}

	internal NemesisRecord LorePage(Gang g)
	{
		if (g == null)
		{
			return null;
		}
		if (_leaderPages.TryGetValue(g.Id, out var value))
		{
			return value;
		}
		string name = g.LoreLeader ?? g.LeaderName;
		NemesisRecord nemesisRecord = new NemesisRecord();
		nemesisRecord.Id = "leader_" + g.Id;
		nemesisRecord.Name = name;
		nemesisRecord.Gang = g.Id;
		nemesisRecord.Rank = 5;
		nemesisRecord.IsAlive = true;
		nemesisRecord.LeaderPage = true;
		nemesisRecord.Origin = GrudgeOrigin.GangMember;
		nemesisRecord.SeedMember = true;
		nemesisRecord.ModelHash = ((!string.IsNullOrEmpty(g.LeaderModel)) ? MISC.GET_HASH_KEY(g.LeaderModel.Split('|')[0]) : 0u);
		value = nemesisRecord;
		GiveLeaderLife(value, g);
		value.Name = name;
		value.Title = "Leader of the " + g.Name;
		value.KinId = null;
		value.KinRelation = null;
		value.PersonalityKnown = true;
		_leaderPages[g.Id] = value;
		return value;
	}

	internal List<(string label, string value)> LeaderFacts(NemesisRecord r)
	{
		Gang g = Gangs.ById(r.Gang);
		List<(string, string)> list = new List<(string, string)>();
		if (g == null)
		{
			return list;
		}
		if (r.BornYear > 0)
		{
			list.Add(("AGE", string.Format("{0} (born {1}{2})", GameYear() - r.BornYear, r.BornYear, string.IsNullOrEmpty(r.Birthplace) ? "" : (", " + r.Birthplace))));
		}
		if (!string.IsNullOrEmpty(g.HomeTown))
		{
			list.Add(("HOLDS", g.HomeTown));
		}
		string text = AgendaText(g);
		if (!string.IsNullOrEmpty(text))
		{
			list.Add(("AIM", char.ToUpperInvariant(text[0]) + text.Substring(1)));
		}
		if (HasPurse(g))
		{
			list.Add(("PURSE", $"${PurseOf(g)}  -  {PurseWord(PurseOf(g))}"));
		}
		list.Add(("MEN", $"{MenOf(g)}  -  {StrengthWord(Strength(g))}"));
		list.Add(("SUPPLIES", $"{SuppliesOf(g)} / 100  -  {SupplyState(SuppliesOf(g))} ({SupplyWord(g)})"));
		List<WarRecord> list2 = Wars.Where((WarRecord w) => w.Result == null && (w.A == g.Id || w.B == g.Id)).ToList();
		list.Add(("WARS", (list2.Count == 0) ? "none" : string.Join(",  ", list2.Select((WarRecord w) => WarName(w) + " (the " + Gangs.ById((w.A == g.Id) ? w.B : w.A)?.Name + ")"))));
		int num = NotorietyOf(g);
		list.Add(("YOU", g.OrdersNotFeelings ? (Notoriety.LevelNames[Notoriety.Level(num)] + " to his men - orders, not feelings") : $"{Notoriety.LevelNames[Notoriety.Level(num)]} to his outfit ({num} / 100)"));
		return list;
	}

	internal void ForgetTiedLeaders()
	{
		_leaderTied.Clear();
	}

	internal void ReapplyLeaders(IEnumerable<NemesisRecord> removed = null)
	{
		if (removed != null)
		{
			foreach (LeaderSeat s in Seats.Values)
			{
				if (s.Successor != null && removed.Any((NemesisRecord r) => r.Id == s.Successor))
				{
					s.Successor = null;
				}
			}
		}
		_leadersApplied = false;
		_leaderTied.Clear();
	}

	internal LeaderSeat SeatOf(Gang g)
	{
		if (g == null || !Seats.TryGetValue(g.Id, out var value))
		{
			return null;
		}
		return value;
	}

	internal bool LeaderVacant(Gang g)
	{
		LeaderSeat leaderSeat = SeatOf(g);
		if (leaderSeat != null && leaderSeat.Fallen != null)
		{
			return leaderSeat.Successor == null;
		}
		return false;
	}

	internal string SuccessorId(Gang g)
	{
		return SeatOf(g)?.Successor;
	}

	internal (string name, string blurb, bool vacant) LeaderCard(Gang g)
	{
		LeaderSeat s = SeatOf(g);
		if (s?.Fallen == null)
		{
			return (name: g.LoreLeader ?? g.LeaderName, blurb: g.LoreBlurb ?? g.LeaderBlurb, vacant: false);
		}
		if (s.Successor != null)
		{
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == s.Successor);
			if (nemesisRecord != null)
			{
				return (name: nemesisRecord.FullName, blurb: "Took over after " + s.OldName + " was " + s.Fallen + ".", vacant: false);
			}
		}
		return (name: "Vacant", blurb: s.OldName + " was " + s.Fallen + ". The seat is open until the next shake-up.", vacant: true);
	}

	internal string LeaderAsSaidBy(Gang g, NemesisRecord speaker)
	{
		if (g == null)
		{
			return null;
		}
		if (speaker != null && speaker.Id != null && SuccessorId(g) == speaker.Id)
		{
			return null;
		}
		if (!LeaderCard(g).vacant)
		{
			return g.LeaderName;
		}
		return null;
	}

	internal bool LeaderOut(Gang g, NemesisRecord speaker)
	{
		if (g != null)
		{
			return LeaderAsSaidBy(g, speaker) == null;
		}
		return false;
	}

	internal bool IsLeader(Gang g, NemesisRecord r)
	{
		if (g != null && r != null && r.Id != null)
		{
			return SuccessorId(g) == r.Id;
		}
		return false;
	}

	private void ApplyLeaders()
	{
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			if (gang.LoreLeader == null)
			{
				gang.LoreLeader = gang.LeaderName;
				gang.LoreBlurb = gang.LeaderBlurb;
			}
			(string name, string blurb, bool vacant) tuple = LeaderCard(gang);
			string item = tuple.name;
			string item2 = tuple.blurb;
			bool item3 = tuple.vacant;
			gang.LeaderName = (item3 ? (SeatOf(gang)?.OldName ?? gang.LoreLeader) : item);
			gang.LeaderBlurb = item2;
		}
		_leadersApplied = true;
	}

	private void CleanLeaderCardDupes()
	{
		if (_leaderDupesCleaned)
		{
			return;
		}
		_leaderDupesCleaned = true;
		int num = 0;
		foreach (IGrouping<string, NemesisRecord> item in (from n in Roster
			where n.Id != null && n.Id.StartsWith("fallen_")
			group n by n.Id).ToList())
		{
			NemesisRecord nemesisRecord = item.First();
			foreach (NemesisRecord item2 in item.Skip(1).ToList())
			{
				Roster.Remove(item2);
				num++;
			}
			Gang gang = Gangs.ById(nemesisRecord.Gang);
			LeaderSeat leaderSeat = ((gang != null) ? SeatOf(gang) : null);
			if (leaderSeat != null && leaderSeat.OldName != null && nemesisRecord.Name != leaderSeat.OldName && nemesisRecord.Id == $"fallen_{gang.Id}_{leaderSeat.At}")
			{
				GrudgeLog("LEADER card " + nemesisRecord.Id + ": named " + nemesisRecord.Name + " by mistake - back to " + leaderSeat.OldName);
				nemesisRecord.Name = leaderSeat.OldName;
				nemesisRecord.KinId = null;
				nemesisRecord.KinRelation = null;
			}
		}
		if (num > 0)
		{
			GrudgeLog($"LEADER {num} duplicate fallen leader cards removed");
			SaveRoster();
		}
	}

	private void BackfillFallenLeaders()
	{
		CleanLeaderCardDupes();
		Gang[] all = Gangs.All;
		foreach (Gang g in all)
		{
			LeaderSeat s = SeatOf(g);
			if (s?.Fallen == null || string.IsNullOrEmpty(s.OldName) || s.OldName != (g.LoreLeader ?? s.OldName))
			{
				continue;
			}
			string cardId = $"fallen_{g.Id}_{s.At}";
			if (!Roster.Any((NemesisRecord n) => !n.IsAlive && n.Gang == g.Id && (n.Name == s.OldName || n.Id == cardId)))
			{
				NemesisRecord nemesisRecord = new NemesisRecord();
				nemesisRecord.Id = $"fallen_{g.Id}_{s.At}";
				nemesisRecord.Name = s.OldName;
				nemesisRecord.Title = "";
				nemesisRecord.Gang = g.Id;
				nemesisRecord.Rank = 5;
				nemesisRecord.IsAlive = false;
				nemesisRecord.Origin = GrudgeOrigin.GangMember;
				nemesisRecord.SeedMember = true;
				nemesisRecord.KilledByPlayer = s.Fallen.Contains("by you");
				nemesisRecord.ModelHash = ((!string.IsNullOrEmpty(g.LeaderModel)) ? MISC.GET_HASH_KEY(g.LeaderModel.Split('|')[0]) : 0u);
				NemesisRecord nemesisRecord2 = nemesisRecord;
				if (s.Fallen == "arrested" || s.Fallen.StartsWith("turned in"))
				{
					nemesisRecord2.Fate = "Arrested";
				}
				string text = LeftFate(s.Fallen);
				if (text != null)
				{
					nemesisRecord2.Fate = text;
				}
				if (nemesisRecord2.Fate != null || (Gangs.Era >= 1907 && Chronicle.EraTurnAt > 0 && s.At <= Chronicle.EraTurnAt) || s.Fallen.Contains("on his bounty"))
				{
					nemesisRecord2.Buried = true;
				}
				GiveLeaderLife(nemesisRecord2, g);
				History(nemesisRecord2, FallLabel(s.Fallen) + " - the leader of " + g.Name + ", " + s.Fallen, Theme.Blood);
				Roster.Add(nemesisRecord2);
				SaveRoster();
				GrudgeLog("LEADER " + s.OldName + ": added to the " + g.Name + " fallen row (he fell before the card existed)");
			}
		}
	}

	private void UpdateLeaders(Ped player)
	{
		if (!_leadersApplied)
		{
			FixLeaderNames();
			EnsureLoreMen();
			BountyModelsStayInTheirMissions();
			try
			{
				RetireMistakenNemeses();
			}
			catch (Exception ex)
			{
				GrudgeLog("ROSTER retire failed: " + ex.Message);
			}
			ApplyLeaders();
			try
			{
				FixEraFunerals();
				FixWofford1907();
				BronteRideAgain();
				FixWomensTrades();
			}
			catch (Exception ex2)
			{
				GrudgeLog("FUNERAL era fix failed: " + ex2.Message);
			}
			BackfillFallenLeaders();
			NoteLoreModels();
			RepairLeaderLives();
			try
			{
				RepairPlansOffMap();
			}
			catch (Exception ex3)
			{
				GrudgeLog("PLAN repair failed: " + ex3.Message);
			}
		}
		if (Game.GameTime < _nextLeaderScan)
		{
			return;
		}
		_nextLeaderScan = Game.GameTime + 1000;
		try
		{
			SyncLeaderCopies();
		}
		catch (Exception ex4)
		{
			GrudgeLog("LEADER copies failed: " + ex4.Message);
		}
		BackfillFallenLeaders();
		LoreMenSeen(player);
		TrackNamedPeds();
		try
		{
			LogMissionPeds(player);
		}
		catch
		{
		}
		Gang[] all = Gangs.All;
		foreach (Gang g in all)
		{
			LeaderSeat seat = SeatOf(g);
			if (seat?.Fallen != null && seat.Successor == null && LeaderVacant(g) && !IsDestroyed(g) && SeatDue(g) && !WorldBusy(player))
			{
				List<NemesisRecord> living = Roster.Where((NemesisRecord n) => n.Gang == g.Id && n.IsAlive && !n.PresumedDead).ToList();
				(string, NemesisRecord)? tuple = FillLeaderSeat(g, living);
				if (tuple.HasValue)
				{
					Feed("LEADER " + tuple.Value.Item1, Theme.Gold);
					GrudgeNotice(tuple.Value.Item1);
					_nextCampAssign = 0;
				}
				else
				{
					seat.FillAt = GameMinutesNow() + 720;
				}
				continue;
			}
			if (seat?.Successor != null)
			{
				NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == seat.Successor);
				if (nemesisRecord == null || !nemesisRecord.IsAlive || nemesisRecord.PresumedDead)
				{
					Fall(g, nemesisRecord?.FullName ?? "the man who took over", "killed", nemesisRecord?.KilledByPlayer ?? false, nemesisRecord);
					continue;
				}
			}
			if (seat?.Fallen != null || string.IsNullOrEmpty(g.LeaderModel))
			{
				continue;
			}
			HashSet<uint> models = new HashSet<uint>(from x in g.LeaderModel.Split('|')
				where x.Trim().Length > 0
				select MISC.GET_HASH_KEY(x.Trim()));
			Ped ped = PedsAround(player).FirstOrDefault((Ped p) => p != null && p.Exists() && models.Contains((uint)p.Model.Hash) && AtLeaderSpot(g, p.Position) && !(LeaderCopyAt?.Invoke(p.Handle) ?? false));
			if (ped == null && _leaderTied.TryGetValue(g.Id, out (int, int, Vector3) value) && Entity.FromHandle(value.Item1) is Ped ped2 && ped2.Exists() && models.Contains((uint)ped2.Model.Hash))
			{
				ped = ped2;
			}
			LeaderWatch(g, ped, player);
			if (g.LoreLeader == null)
			{
				_ = g.LeaderName;
			}
			if (Game.GameTime - _cashRoseAt < 20000 && TryArrest(g, player))
			{
				continue;
			}
			if (ped != null)
			{
				(int, int, Vector3) value2;
				if (ped.IsDead && !LooksKnockedOut(ped))
				{
					int num = PED.GET_PED_SOURCE_OF_DEATH(ped.Handle);
					bool byYou = num == player.Handle || (num == 0 && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(ped.Handle, player.Handle, p2: true, p3: true)) || IsCompanionKiller(num);
					Fall(g, g.LoreLeader ?? g.LeaderName, "killed", byYou, null, g.LeaderModel);
				}
				else if (ped.IsHogtied || ENTITY.IS_ENTITY_ATTACHED_TO_ENTITY(ped.Handle, player.Handle) || ENTITY.IS_ENTITY_ATTACHED(ped.Handle))
				{
					_leaderTied[g.Id] = (ped.Handle, Game.GameTime, ped.Position);
				}
				else if (_leaderTied.TryGetValue(g.Id, out value2) && value2.Item1 == ped.Handle)
				{
					_leaderTied[g.Id] = (value2.Item1, value2.Item2, ped.Position);
				}
			}
			else
			{
				if (!_leaderTied.TryGetValue(g.Id, out (int, int, Vector3) value3))
				{
					continue;
				}
				Entity entity = Entity.FromHandle(value3.Item1);
				if (Game.GameTime - value3.Item2 > 300000)
				{
					_leaderTied.Remove(g.Id);
				}
				else if (entity == null || !entity.Exists())
				{
					_leaderTied.Remove(g.Id);
					bool flag = player.Position.DistanceTo(value3.Item3) < 60f;
					bool flag2 = Game.GameTime - _cashRoseAt < 90000;
					if (flag & flag2)
					{
						Fall(g, g.LoreLeader ?? g.LeaderName, "arrested", byYou: true, null, g.LeaderModel);
						continue;
					}
					GrudgeLog("LEADER " + (g.LoreLeader ?? g.LeaderName) + " was tied up and is gone (" + (flag ? "no bounty paid" : $"{player.Position.DistanceTo(value3.Item3):0} m from where you left him") + ") - not turned in");
				}
			}
		}
	}

	private void GiveLeaderLife(NemesisRecord r, Gang g)
	{
		if (r == null || g == null || (r.Past != null && r.Past.Count > 0))
		{
			return;
		}
		if (LeaderLore.TryGetValue(g.Id, out (Personality, int, string, (int, string, string)[]) value) && r.Name == (g.LoreLeader ?? g.LeaderName))
		{
			try
			{
				RollNewLife(r, Roster, mind: true, 1);
			}
			catch
			{
			}
			r.KinId = null;
			r.KinRelation = null;
			r.Personality = value.Item1;
			r.BornYear = value.Item2;
			r.Birthplace = value.Item3;
			r.Past = new List<PastEntry>
			{
				new PastEntry
				{
					Year = value.Item2,
					Kind = "born",
					Text = "Born in " + value.Item3,
					Public = true,
					Known = true
				}
			};
			(int, string, string)[] item = value.Item4;
			for (int i = 0; i < item.Length; i++)
			{
				(int, string, string) tuple = item[i];
				r.Past.Add(new PastEntry
				{
					Year = tuple.Item1,
					Kind = tuple.Item2,
					Text = tuple.Item3,
					Public = true,
					Known = true
				});
			}
			r.PastRolled = true;
			r.PersonalityKnown = true;
			GrudgeLog($"LEADER {r.Name}: his life written from the lore ({r.Past.Count} lines, {value.Item1})");
		}
		else
		{
			string name = r.Name;
			string title = r.Title;
			try
			{
				RollNewLife(r, Roster, mind: true, 1);
			}
			catch (Exception ex)
			{
				GrudgeLog("LEADER life roll failed: " + ex.Message);
			}
			r.Name = name;
			r.Title = title;
			r.KinId = null;
			r.KinRelation = null;
			if (r.Past != null)
			{
				foreach (PastEntry item2 in r.Past)
				{
					item2.Public = true;
					item2.Known = true;
				}
			}
			r.PersonalityKnown = true;
			GrudgeLog($"LEADER {r.Name}: a life rolled for him ({r.Past?.Count ?? 0} lines, {r.Personality})");
		}
		r.Rank = 5;
	}

	private void RepairLeaderLives()
	{
		bool flag = false;
		foreach (NemesisRecord item in Roster.Where((NemesisRecord n) => n.Id != null && n.Id.StartsWith("fallen_") && (n.Past == null || n.Past.Count == 0)).ToList())
		{
			Gang gang = Gangs.ById(item.Gang);
			if (gang != null)
			{
				GiveLeaderLife(item, gang);
				if (item.History == null || item.History.Count == 0)
				{
					History(item, ((item.Fate == "Arrested") ? "ARRESTED" : "DIED") + " - the leader of " + gang.Name, Theme.Blood);
				}
				flag = true;
			}
		}
		if (flag)
		{
			SaveRoster();
		}
	}

	internal void ArrestOnPayout(Ped player)
	{
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			if (SeatOf(gang)?.Fallen == null && _leaderTied.ContainsKey(gang.Id))
			{
				try
				{
					TryArrest(gang, player);
				}
				catch (Exception ex)
				{
					GrudgeLog("LEADER arrest check failed: " + ex.Message);
				}
			}
		}
	}

	private bool TryArrest(Gang g, Ped player)
	{
		if (!_leaderTied.TryGetValue(g.Id, out (int, int, Vector3) value) || Game.GameTime - value.Item2 > 1800000)
		{
			return false;
		}
		Ped ped = Entity.FromHandle(value.Item1) as Ped;
		bool flag = ped != null && ped.Exists();
		if (flag && ped.IsDead && !LooksKnockedOut(ped))
		{
			return false;
		}
		if ((!flag || !(ped.Position.DistanceTo(player.Position) < 300f)) && !(value.Item3.DistanceTo(player.Position) < 150f) && flag)
		{
			GrudgeLog("LEADER " + (g.LoreLeader ?? g.LeaderName) + ": money came in but he's " + (flag ? $"{ped.Position.DistanceTo(player.Position):0} m" : "?") + " away - not counted");
			return false;
		}
		_leaderTied.Remove(g.Id);
		string text = g.LoreLeader ?? g.LeaderName;
		GrudgeLog("LEADER " + text + ": the bounty paid out with him in your hands (" + (flag ? $"{ped.Position.DistanceTo(player.Position):0} m" : "taken away") + ") - ARRESTED");
		Fall(g, text, "arrested", byYou: true, null, g.LeaderModel);
		return true;
	}

	internal static bool AtLeaderSpot(Gang g, Vector3 p)
	{
		if (g.LeaderSpot != null && g.LeaderSpot.Length >= 3)
		{
			return new Vector3(p.X - g.LeaderSpot[0], p.Y - g.LeaderSpot[1], 0f).Length() < g.LeaderSpot[2];
		}
		return true;
	}

	internal string LoreNameAt(string modelLower, Vector3 at)
	{
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			if (!string.IsNullOrEmpty(gang.LeaderModel) && gang.LeaderModel.ToLowerInvariant().Split('|').Contains(modelLower) && AtLeaderSpot(gang, at))
			{
				return gang.LoreLeader ?? gang.LeaderName;
			}
		}
		return Roster.FirstOrDefault((NemesisRecord n) => n.LoreModel != null && n.LoreModel.ToLowerInvariant() == modelLower)?.FullName;
	}

	private void NoteLoreModels()
	{
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			if (string.IsNullOrEmpty(gang.LeaderModel))
			{
				continue;
			}
			string[] array = gang.LeaderModel.ToLowerInvariant().Split('|');
			foreach (string text in array)
			{
				if (text.StartsWith("u_"))
				{
					LoreModels.Add(text.Trim());
				}
			}
		}
		foreach (NemesisRecord item in Roster)
		{
			if (item.LoreModel != null)
			{
				LoreModels.Add(item.LoreModel.ToLowerInvariant());
			}
		}
	}

	private void LeaderWatch(Gang g, Ped him, Ped player)
	{
		string text;
		if (him == null)
		{
			text = "not around";
		}
		else if (him.IsDead)
		{
			text = (LooksKnockedOut(him) ? "knocked out" : "dead");
		}
		else if (ENTITY.IS_ENTITY_ATTACHED_TO_ENTITY(him.Handle, player.Handle))
		{
			text = "carried by you";
		}
		else if (ENTITY.IS_ENTITY_ATTACHED(him.Handle))
		{
			text = "on a horse / carried";
		}
		else
		{
			text = ((!him.IsHogtied) ? "free" : "hogtied");
		}
		_leaderState.TryGetValue(g.Id, out var value);
		if (!(text == value))
		{
			_leaderState[g.Id] = text;
			if (value != null || !(text == "not around"))
			{
				string text2 = ((him != null) ? $" - {him.Position.DistanceTo(player.Position):0} m from you, model {Models.Name((uint)him.Model.Hash)}, ped {him.Handle}" : "");
				GrudgeLog("LEADER " + (g.LoreLeader ?? g.LeaderName) + " (" + g.Name + "): " + (value ?? "first seen") + " -> " + text + text2 + (MISC.GET_MISSION_FLAG() ? " [mission running]" : ""));
			}
		}
	}

	private void LogMissionPeds(Ped player)
	{
		if (Game.GameTime < _nextMissionPedScan)
		{
			return;
		}
		_nextMissionPedScan = Game.GameTime + 2000;
		if (!MISC.GET_MISSION_FLAG())
		{
			if (_missionPedsLogged.Count > 0)
			{
				_missionPedsLogged.Clear();
			}
		}
		else
		{
			if (_missionPedsLogged.Count > 60)
			{
				return;
			}
			foreach (Ped item in PedsAround(player))
			{
				if (!(item == null) && item.Exists() && !item.IsPlayer && item.IsHuman && !_missionPedsLogged.Contains(item.Handle) && ENTITY.IS_ENTITY_A_MISSION_ENTITY(item.Handle) && !BelongsToUs(item.Handle))
				{
					float num = item.Position.DistanceTo(player.Position);
					if (!(num > 80f))
					{
						_missionPedsLogged.Add(item.Handle);
						GrudgeLog(string.Format("MISSION ped {0} (ped {1}) {2:0} m - {3}", Models.Name((uint)item.Model.Hash), item.Handle, num, item.IsDead ? "dead" : (item.IsHogtied ? "hogtied" : "alive")));
					}
				}
			}
		}
	}

	private void EnsureLoreMen()
	{
		Gang raiders = Gangs.LemoyneRaiders;
		if (Roster.Any((NemesisRecord n) => n.Gang == raiders.Id) && !Roster.Any((NemesisRecord n) => n.Id == "lore_millemont"))
		{
			NemesisRecord nemesisRecord = NewRecord(3939581308u, "Scarlett Meadows", raiders, 4);
			nemesisRecord.Id = "lore_millemont";
			nemesisRecord.Name = "Camille de Millemont";
			nemesisRecord.Title = "";
			nemesisRecord.LoreModel = "u_m_m_uniexconfedsbounty_01";
			nemesisRecord.Gang = raiders.Id;
			nemesisRecord.Rank = 4;
			nemesisRecord.Origin = GrudgeOrigin.GangMember;
			nemesisRecord.SeedMember = true;
			nemesisRecord.Personality = Personality.Proud;
			nemesisRecord.Hate = 72;
			nemesisRecord.KillLocation = "Rhodes";
			nemesisRecord.Past = nemesisRecord.Past ?? new List<PastEntry>();
			nemesisRecord.Past.Add(new PastEntry
			{
				Year = 1898,
				Month = 0,
				Kind = "crime",
				Text = "Robbed the mail and killed a postal carrier - he calls it rebellion",
				Public = true,
				Known = true
			});
			nemesisRecord.Past.Add(new PastEntry
			{
				Year = 1899,
				Month = 0,
				Kind = "crime",
				Text = "Wanted in Rhodes: $55, dead or alive - theft of state property, crimes against officers of the state",
				Public = true,
				Known = true
			});
			Roster.Add(nemesisRecord);
			SaveRoster();
			GrudgeLog("LEADER added Camille de Millemont (lore) to the Lemoyne Raiders as a captain");
		}
	}

	private void RetireMistakenNemeses()
	{
		foreach (NemesisRecord item in Roster.Where((NemesisRecord x) => x.IsAlive && x.Id != null && MistakenNemeses.Contains(x.Id)).ToList())
		{
			GrudgeLog("ROSTER " + item.Name + ": made a nemesis by mistake - he quits the life");
			QuitTheLife(item, GameMinutesNow());
		}
	}

	internal static bool BountyModel(string m)
	{
		if (!string.IsNullOrEmpty(m))
		{
			if (!m.Contains("_bht_"))
			{
				if (m.Contains("bounty"))
				{
					return !m.Contains("bountyhunter");
				}
				return false;
			}
			return true;
		}
		return false;
	}

	private void BountyModelsStayInTheirMissions()
	{
		int num = 0;
		try
		{
			foreach (NemesisRecord r in Roster.Where((NemesisRecord x) => x.IsAlive && x.Gang != null && (x.SeedMember || (x.Id ?? "").StartsWith("lore_")) && !IsLeaderCopy(x) && BountyModel(Models.Name(x.ModelHash))).ToList())
			{
				Gang gang = Gangs.ById(r.Gang);
				uint num2 = 0u;
				if (gang?.Seed != null)
				{
					foreach (var item in gang.Seed.OrderBy(((int Rank, int Count, PedHash[] Models) s) => Math.Abs(s.Rank - r.Rank)))
					{
						PedHash[] array = item.Models ?? new PedHash[0];
						foreach (PedHash pedHash in array)
						{
							if (!BountyModel(Models.Name((uint)pedHash)))
							{
								num2 = (uint)pedHash;
								break;
							}
						}
						if (num2 != 0)
						{
							break;
						}
					}
				}
				if (num2 == 0 && gang?.TroopModels != null && gang.TroopModels.Length != 0)
				{
					num2 = (uint)gang.TroopModels[0];
				}
				if (num2 != 0)
				{
					GrudgeLog("MODEL " + r.Name + ": " + Models.Name(r.ModelHash) + " is a bounty mission's - now " + Models.Name(num2) + ", new clothes");
					r.ModelHash = num2;
					r.OutfitHash = 0u;
					num++;
				}
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("MODEL bounty-model check failed: " + ex.Message);
		}
		if (num > 0)
		{
			SaveRoster();
		}
	}

	private void LoreMenSeen(Ped player)
	{
		if (!Chronicle.MillemontFix)
		{
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == "lore_millemont");
			if (nemesisRecord != null && !nemesisRecord.IsAlive && nemesisRecord.History != null && nemesisRecord.History.Any((HistoryEntry h) => h.Text != null && h.Text.Contains("bounty on him was settled")) && nemesisRecord.TimesCheatedDeath > 0)
			{
				Chronicle.MillemontFix = true;
				nemesisRecord.IsAlive = true;
				nemesisRecord.PresumedDead = true;
				nemesisRecord.History.RemoveAll((HistoryEntry h) => h.Text != null && h.Text.Contains("bounty on him was settled"));
				GrudgeLog("LEADER Camille de Millemont brought back - his ped from a mod skirmish isn't the game's bounty man (presumed dead, as his roll said)");
				SaveRoster();
				SaveWorld();
				goto IL_0103;
			}
		}
		if (!Chronicle.MillemontFix)
		{
			Chronicle.MillemontFix = true;
		}
		goto IL_0103;
		IL_0103:
		if (Game.GameTime < _nextLoreScan)
		{
			return;
		}
		_nextLoreScan = Game.GameTime + 1000;
		foreach (NemesisRecord item in Roster.Where((NemesisRecord n) => n.LoreModel != null && n.IsAlive))
		{
			uint model = MISC.GET_HASH_KEY(item.LoreModel);
			Ped ped = PedsAround(player).FirstOrDefault((Ped p) => p != null && p.Exists() && p.Model.Hash == (int)model && !IsOurs(p.Handle) && !WasOurs.Contains(p.Handle) && !KnownBody(p.Handle, model) && !Gangs.All.Any((Gang g) => g.LeaderSpot != null && AtLeaderSpot(g, p.Position)));
			if (!(ped == null) && ped.IsDead && !LooksKnockedOut(ped))
			{
				item.IsAlive = false;
				item.KilledByPlayer = ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(ped.Handle, player.Handle, p2: true, p3: true);
				History(item, "DIED - the game's own bounty on him was settled", Theme.Blood);
				Feed("LEADER " + item.FullName + " is dead (the Rhodes bounty)", Theme.Blood, item);
				DeathNotice(item.FullName + " is dead.");
				GrudgeLog("LEADER " + item.FullName + " (lore man) died - seen as the game's " + item.LoreModel);
				SaveRoster();
			}
		}
	}

	private void TrackNamedPeds()
	{
		foreach (KeyValuePair<int, Provocation> item in _provoked.ToList())
		{
			NemesisRecord nemesisRecord = item.Value?.Record;
			if (nemesisRecord != null && nemesisRecord.IsAlive && !_worldNemeses.ContainsKey(item.Key) && Roster.Contains(nemesisRecord) && (!(_activeNemesisPed != null) || item.Key != _activeNemesisPed.Handle) && ENTITY.DOES_ENTITY_EXIST(item.Key) && ENTITY.IS_ENTITY_A_PED(item.Key) && !_worldNemeses.ContainsValue(nemesisRecord))
			{
				_worldNemeses[item.Key] = nemesisRecord;
				GrudgeLog($"TRACK ped {item.Key} is {nemesisRecord.FullName} now - his death counts as his");
			}
		}
		if (_interro?.Ped != null && _interro.Rec != null && Roster.Contains(_interro.Rec) && _interro.Rec.IsAlive && !_worldNemeses.ContainsKey(_interro.Ped.Handle) && !_worldNemeses.ContainsValue(_interro.Rec) && _interro.Ped.Exists() && (_activeNemesisPed == null || _interro.Ped.Handle != _activeNemesisPed.Handle))
		{
			_worldNemeses[_interro.Ped.Handle] = _interro.Rec;
			GrudgeLog($"TRACK questioned ped {_interro.Ped.Handle} is {_interro.Rec.FullName} - his death counts as his");
		}
	}

	private void Fall(Gang g, string who, string how, bool byYou = false, NemesisRecord record = null, string model = null)
	{
		if (record == null && !Roster.Any((NemesisRecord n) => !n.IsAlive && n.Gang == g.Id && n.Name == who))
		{
			NemesisRecord nemesisRecord = new NemesisRecord();
			nemesisRecord.Id = $"fallen_{g.Id}_{GameMinutesNow()}";
			nemesisRecord.Name = who;
			nemesisRecord.Title = "";
			nemesisRecord.Gang = g.Id;
			nemesisRecord.Rank = 5;
			nemesisRecord.IsAlive = false;
			nemesisRecord.Origin = GrudgeOrigin.GangMember;
			nemesisRecord.SeedMember = true;
			nemesisRecord.KilledByPlayer = byYou;
			nemesisRecord.ModelHash = ((model != null) ? MISC.GET_HASH_KEY(model.Split('|')[0]) : 0u);
			nemesisRecord.KillLocation = GetZoneName(Game.Player.Character.Position);
			NemesisRecord nemesisRecord2 = nemesisRecord;
			if (how == "arrested")
			{
				nemesisRecord2.Fate = "Arrested";
			}
			GiveLeaderLife(nemesisRecord2, g);
			History(nemesisRecord2, FallLabel(how) + " - the leader of " + g.Name + ", " + how + (byYou ? " (by you)" : ""), Theme.Blood);
			Roster.Add(nemesisRecord2);
			SaveRoster();
			GrudgeLog("LEADER " + who + ": on the " + g.Name + " fallen row");
		}
		if (byYou)
		{
			AddNotoriety(g, 40, (how.StartsWith("killed") ? "killed" : "brought down") + " their leader, " + who);
		}
		Seats[g.Id] = new LeaderSeat
		{
			Fallen = how,
			OldName = who,
			At = GameMinutesNow()
		};
		ApplyLeaders();
		SaveWorld();
		try
		{
			_nextRosterSave = 0;
			FlushRosterSave();
			SaveWorldNow(background: true);
			_nextWorldSave = Game.GameTime + 60000;
		}
		catch (Exception ex)
		{
			GrudgeLog("SAVE after a leader's fall failed: " + ex.Message);
		}
		GrudgeLog("LEADER " + g.Name + ": " + who + " " + how + " - the seat is open");
		Feed("LEADER " + who + " of " + g.Name + " " + how + " - the seat is open", g.Accent);
		DeathNotice(who + " was " + how + ". " + g.Name + " have no leader - for now.");
		Vector3 position = Game.Player.Character.Position;
		if (byYou)
		{
			ChronicleDeed("leader", who + " of " + g.Name + " was " + how, "near " + GetZoneName(position), position, g.Id, new WorldPart
			{
				Name = who,
				Gang = g.Id,
				Outcome = ((FallLabel(how) == "ARRESTED") ? "JAILED" : "KILLED"),
				Note = "the leader"
			});
		}
	}

	private static string FallLabel(string how)
	{
		if (how == null || (!how.StartsWith("arrested") && !how.StartsWith("turned in")))
		{
			if (LeftFate(how) == null)
			{
				return "DIED";
			}
			return "GONE";
		}
		return "ARRESTED";
	}

	private static string LeftFate(string how)
	{
		if (how != null)
		{
			if (!how.StartsWith("left"))
			{
				if (!how.StartsWith("went north"))
				{
					if (!(how == "broke up"))
					{
						if (!how.StartsWith("taken in on his bounty"))
						{
							return null;
						}
						return "Gone";
					}
					return "Gone";
				}
				return "Went to Canada";
			}
			return "Left";
		}
		return null;
	}

