	private string StoryFateLocked(Gang g, params string[] cards)
	{
		LeaderSeat leaderSeat = SeatOf(g);
		if (leaderSeat == null || leaderSeat.Fallen == null)
		{
			return null;
		}
		if (leaderSeat.Successor != null)
		{
			return "The " + g.Name + " already have a new leader - this can't be changed now.";
		}
		if (!cards.Contains(leaderSeat.Fallen))
		{
			return (leaderSeat.OldName ?? "He") + " fell in your game (" + leaderSeat.Fallen + ") - this can't be changed here.";
		}
		return null;
	}

	private void SetLeaderFate(Gang g, string fallen, string oldName)
	{
		LeaderSeat s = SeatOf(g);
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == LeaderCopyId(g) && n.IsAlive);
		if (nemesisRecord != null)
		{
			BenchLeaderCopy(nemesisRecord, "the setup card");
		}
		Roster.RemoveAll((NemesisRecord n) => !n.IsAlive && n.Gang == g.Id && ((n.Id.StartsWith("fallen_" + g.Id + "_") && s != null && n.Id == $"fallen_{g.Id}_{s.At}") || n.Id == LeaderCopyId(g)));
		if (fallen == null)
		{
			Seats.Remove(g.Id);
		}
		else
		{
			Seats[g.Id] = new LeaderSeat
			{
				Fallen = fallen,
				OldName = oldName,
				At = GameMinutesNow()
			};
		}
		ApplyLeaders();
		BackfillFallenLeaders();
		if (fallen != null)
		{
			NemesisRecord nemesisRecord2 = Roster.FirstOrDefault((NemesisRecord n) => n.Id == $"fallen_{g.Id}_{SeatOf(g)?.At}");
			if (nemesisRecord2 != null)
			{
				nemesisRecord2.Buried = true;
			}
		}
		SaveRoster();
		SaveWorld();
	}

	private void FixWofford1907()
	{
		WorldState chronicle = Chronicle;
		if (chronicle.WoffordFixed || Gangs.Era < 1907)
		{
			return;
		}
		chronicle.WoffordFixed = true;
		Gang lemoyneRaiders = Gangs.LemoyneRaiders;
		if (SeatOf(lemoyneRaiders)?.Fallen == null)
		{
			if (chronicle.EraTurnAt <= 0)
			{
				chronicle.EraTurnAt = ((chronicle.StoryChapterAt > 0) ? chronicle.StoryChapterAt : GameMinutesNow());
			}
			Seats[lemoyneRaiders.Id] = new LeaderSeat
			{
				Fallen = "taken in on his bounty years ago - dead or in Sisika, nobody's sure",
				OldName = (lemoyneRaiders.LoreLeader ?? "Lindsey Wofford"),
				At = chronicle.EraTurnAt,
				FillAt = GameMinutesNow()
			};
			ApplyLeaders();
			SaveWorld();
			GrudgeLog("LEADER Lindsey Wofford: gone by 1907 (one-time) - the Raiders pick a new head");
		}
	}

	private void FixEraFunerals()
	{
		WorldState chronicle = Chronicle;
		if (chronicle.EraFuneralsFixed || Gangs.Era < 1907)
		{
			return;
		}
		chronicle.EraFuneralsFixed = true;
		if (chronicle.EraTurnAt <= 0)
		{
			chronicle.EraTurnAt = ((chronicle.StoryChapterAt > 0) ? chronicle.StoryChapterAt : GameMinutesNow());
		}
		HashSet<string> ids = new HashSet<string>();
		foreach (KeyValuePair<string, LeaderSeat> kv in Seats)
		{
			LeaderSeat s = kv.Value;
			if (s?.Fallen == null || s.At > chronicle.EraTurnAt + 1440)
			{
				continue;
			}
			foreach (NemesisRecord item in Roster.Where((NemesisRecord n) => !n.IsAlive && n.Gang == kv.Key && (n.Id.StartsWith("fallen_" + kv.Key + "_") || n.Name == s.OldName)))
			{
				string text = LeftFate(s.Fallen);
				if (text != null && item.Fate == null)
				{
					item.Fate = text;
					foreach (HistoryEntry item2 in item.History ?? new List<HistoryEntry>())
					{
						if (item2.Text != null && item2.Text.StartsWith("DIED - the leader"))
						{
							item2.Text = "GONE" + item2.Text.Substring(4);
						}
					}
				}
				item.Buried = true;
				ids.Add(item.Id);
			}
		}
		int num = Plans.RemoveAll((Plan p) => p.Kind == "funeral" && !p.Done && (FuneralDead(p).Any(ids.Contains) || p.Gang == "nightfolk"));
		SaveRoster();
		SaveWorld();
		try
		{
			RefreshPlanBlips();
		}
		catch
		{
		}
		GrudgeLog($"FUNERAL one-time: {ids.Count} leader(s) gone since the turn to 1907 set as long buried / gone - {num} funeral(s) called off");
	}

	private long SeatFillAt(Gang g, LeaderSeat seat)
	{
		if (seat.FillAt > 0)
		{
			return seat.FillAt;
		}
		int top = ((g.Tiers != null && g.Tiers.Length != 0) ? g.Tiers[0].MinRank : 4);
		List<int> list = (from n in Roster
			where n.Gang == g.Id && n.IsAlive && !n.PresumedDead && n.Rank >= top && !n.Paralyzed
			select Standing(n).score into s
			orderby s descending
			select s).ToList();
		double num;
		if (list.Count >= 2 && list[0] - list[1] >= 25)
		{
			num = 0.35;
		}
		else if (list.Count == 1)
		{
			num = 0.5;
		}
		else
		{
			num = ((list.Count == 0) ? 0.9 : 0.65);
		}
		double num2 = 1.0 + 3.0 * Math.Min(1.0, Math.Max(0.0, num + (_rng.NextDouble() - 0.5) * 0.6));
		long num3 = Math.Max(seat.At, GameMinutesNow() - 5760);
		seat.FillAt = num3 + (long)(num2 * 24.0 * 60.0) + _rng.Next(60);
		SaveWorld();
		GrudgeLog($"LEADER {g.Name}: the seat will be filled in about {(seat.FillAt - GameMinutesNow()) / 60} game hours ({list.Count} officers)");
		return seat.FillAt;
	}

	private bool SeatDue(Gang g)
	{
		LeaderSeat leaderSeat = SeatOf(g);
		if (leaderSeat != null)
		{
			return GameMinutesNow() >= SeatFillAt(g, leaderSeat);
		}
		return false;
	}

	private (string line, NemesisRecord heir)? FillLeaderSeat(Gang g, List<NemesisRecord> living)
	{
		if (!LeaderVacant(g) || g.Tiers == null || g.Tiers.Length == 0)
		{
			return null;
		}
		if (!SeatDue(g))
		{
			return null;
		}
		NemesisRecord nemesisRecord = (from n in living
			where n.Rank >= g.Tiers[0].MinRank && !n.Paralyzed
			orderby Standing(n).score descending, n.Id
			select n).FirstOrDefault() ?? (from n in living
			where !n.Paralyzed
			orderby n.Rank descending, Standing(n).score descending
			select n).FirstOrDefault();
		if (nemesisRecord == null)
		{
			return null;
		}
		LeaderSeat leaderSeat = Seats[g.Id];
		leaderSeat.Successor = nemesisRecord.Id;
		nemesisRecord.Rank = 5;
		nemesisRecord.BossId = null;
		History(nemesisRecord, "TOOK THE LEAD of " + g.Name + " after " + leaderSeat.OldName + " was " + leaderSeat.Fallen, Theme.Gold);
		Remember(nemesisRecord, "Pride", 70, "he leads " + g.Name + " now");
		ApplyLeaders();
		SaveWorld();
		GrudgeLog("LEADER " + g.Name + ": " + nemesisRecord.FullName + " takes the seat (" + Standing(nemesisRecord).why + ")");
		if (g == Gangs.Army && Chronicle.FortCleared)
		{
			Chronicle.FortCleared = false;
			Chronicle.FortKnown = false;
			SaveWorld();
			GrudgeLog("ARMY fort: a new commander holds Fort Wallace - its ways unknown again");
			Feed("HIDEOUT " + nemesisRecord.Name + " holds Fort Wallace now - an officer could tell you his ways", Theme.Warn);
			ReplyNotice("A new commander holds Fort Wallace: " + nemesisRecord.Name + ". His ways will have to be learned again.");
		}
		if (g == Gangs.Army)
		{
			RefreshFortBlip();
		}
		return (nemesisRecord.Name + " takes the lead of " + g.Name + "  -  " + leaderSeat.OldName + " is gone", nemesisRecord);
	}

	private void FixDuplicateNames()
	{
		int num = 0;
		foreach (IGrouping<string, NemesisRecord> item in (from n in Roster
			where n.IsAlive && !n.Story && n.Name != null && n.Name.Contains(' ')
			group n by n.Name into g
			where g.Count() > 1
			select g).ToList())
		{
			foreach (NemesisRecord r in (from n in item
				orderby (!Keeps(n)) ? 1 : 0, n.KilledPlayerAt
				select n).Skip(1).ToList())
			{
				Gang gang = Gangs.Of(r);
				if (Keeps(r) || (gang != null && !gang.FamilyNames) || (gang != null && gang.RankInName))
				{
					continue;
				}
				string text = NameBank.Surname(r.Name);
				string name = r.Name;
				string[] array = (Models.Female(r.ModelHash) ? FemaleFirstFor(gang?.FirstNames ?? NameBank.AmericanFirst) : (gang?.FirstNames ?? NameBank.AmericanFirst));
				for (int num2 = 0; num2 < 30; num2++)
				{
					if (!Roster.Any((NemesisRecord n) => n != r && n.Name == r.Name))
					{
						break;
					}
					r.Name = array[_rng.Next(array.Length)] + " " + text;
				}
				if (Roster.Any((NemesisRecord n) => n != r && n.Name == r.Name))
				{
					r.Name = name;
				}
				if (r.Name != name)
				{
					num++;
					GrudgeLog("NAMING two men were " + name + " - the one you never met is " + r.Name + " now");
				}
			}
		}
		if (num > 0)
		{
			SaveRoster();
		}
		bool Keeps(NemesisRecord n)
		{
			if (n.TimesAmbushed + n.TimesInterrogated + n.TimesKilledPlayer <= 0 && !n.PersonalityKnown && n.LoreModel == null && !n.Id.StartsWith("lore_"))
			{
				return Seats.Values.Any((LeaderSeat s) => s.Successor == n.Id);
			}
			return true;
		}
	}

	private void FixLeaderNames()
	{
		try
		{
			FixDuplicateNames();
		}
		catch (Exception ex)
		{
			GrudgeLog("NAMING duplicate fix failed: " + ex.Message);
		}
		int n = 0;
		foreach (NemesisRecord item3 in Roster)
		{
			if (item3.History != null)
			{
				foreach (HistoryEntry item4 in item3.History)
				{
					item4.Text = Fix(item4.Text);
				}
			}
			if (item3.Past == null)
			{
				continue;
			}
			foreach (PastEntry item5 in item3.Past)
			{
				item5.Text = Fix(item5.Text);
			}
		}
		foreach (WorldEvent item6 in Chronicle.Events.Concat(Chronicle.Past ?? new List<WorldEvent>()))
		{
			item6.Title = Fix(item6.Title);
			for (int i = 0; i < item6.Lines.Count; i++)
			{
				item6.Lines[i] = Fix(item6.Lines[i]);
			}
		}
		if (n > 0)
		{
			GrudgeLog($"LEADER renamed the old made-up leaders in {n} saved texts (Wofford / Favours)");
			SaveRoster();
			SaveWorld();
		}
		string Fix(string s)
		{
			if (string.IsNullOrEmpty(s))
			{
				return s;
			}
			string text = s;
			(string, string)[] leaderRenames = LeaderRenames;
			for (int j = 0; j < leaderRenames.Length; j++)
			{
				(string, string) tuple = leaderRenames[j];
				string item = tuple.Item1;
				string item2 = tuple.Item2;
				s = s.Replace(item, item2);
			}
			if (s != text)
			{
				n++;
			}
			return s;
		}
	}

	internal int MenStart(Gang g)
	{
		if (g != null)
		{
			if (!StartMen.TryGetValue(g.Id, out var value))
			{
				return 60;
			}
			return value;
		}
		return 1;
	}

	internal int MenOf(Gang g)
	{
		if (g == null || g.StoryOnly)
		{
			return 0;
		}
		if (!Chronicle.MenRescaled)
		{
			RescaleMen();
		}
		if (!Chronicle.MenRescaled2)
		{
			RescaleMen2();
		}
		if (!MenMap.TryGetValue(g.Id, out var value))
		{
			value = MenStart(g);
			MenMap[g.Id] = value;
		}
		return value;
	}

	private void RescaleMen()
	{
		Chronicle.MenRescaled = true;
		foreach (KeyValuePair<string, int> oldStartMan in OldStartMen)
		{
			if (MenMap.TryGetValue(oldStartMan.Key, out var value))
			{
				int num = MidStartMen[oldStartMan.Key];
				int num2 = Math.Max((int)Math.Round((double)value * (double)num / (double)oldStartMan.Value), (int)((double)num * 0.4));
				MenMap[oldStartMan.Key] = num2;
				GrudgeLog($"MEN {Gangs.ById(oldStartMan.Key)?.Name ?? oldStartMan.Key}: {value} -> {num2} (the bigger starting numbers - {oldStartMan.Value} -> {num})");
			}
		}
		SaveWorld();
	}

	private void RescaleMen2()
	{
		Chronicle.MenRescaled2 = true;
		foreach (KeyValuePair<string, int> midStartMan in MidStartMen)
		{
			if (MenMap.TryGetValue(midStartMan.Key, out var value))
			{
				int num = StartMen[midStartMan.Key];
				int num2 = (int)Math.Round((double)value * (double)num / (double)midStartMan.Value);
				MenMap[midStartMan.Key] = num2;
				GrudgeLog($"MEN {Gangs.ById(midStartMan.Key)?.Name ?? midStartMan.Key}: {value} -> {num2} (hundreds and thousands - {midStartMan.Value} -> {num})");
			}
		}
		SaveWorld();
	}

	internal static int NamedWorth(int rank)
	{
		if (rank > 0)
		{
			return Math.Min(10, 5 + (int)Math.Round((double)(rank - 1) * 1.25));
		}
		return 1;
	}

	private bool DeclaredWar(string a, string b)
	{
		if (a != null && b != null && a != b)
		{
			return Wars.Any((WarRecord w) => w.Result == null && ((w.A == a && w.B == b) || (w.A == b && w.B == a)));
		}
		return false;
	}

	private int WorldLoss(Gang g, int rolled, long atMin, double mult = 1.0, int fightMen = -1)
	{
		if (g == null || rolled <= 0)
		{
			return 0;
		}
		int num = MenOf(g);
		int num2 = ((fightMen > 0) ? Math.Min(num, fightMen) : num);
		int num3 = (int)Math.Round((double)rolled * mult * Math.Max(1.0, (double)num2 / 60.0));
		double num4 = 0.02 + _rng.NextDouble() * 0.05;
		int num5 = Math.Max(1, (int)Math.Ceiling((double)num * num4));
		if (num3 > num5)
		{
			GrudgeLog($"MEN {g.Name}: a fight's losses {num3} -> {num5} (at most {num4 * 100.0:0.#}% of {num} this time)");
			num3 = num5;
		}
		long num6 = ((atMin > 0) ? atMin : GameMinutesNow()) / 1440;
		if (!_worldLost.TryGetValue(g.Id, out (long, int, int, bool) value) || value.Item1 != num6)
		{
			value = (num6, num, 0, false);
		}
		int num7 = Math.Max(0, Math.Max(1, (int)Math.Ceiling((double)value.Item2 * 0.08)) - value.Item3);
		if (num3 > num7)
		{
			if (num7 == 0 && !value.Item4)
			{
				GrudgeLog($"MEN {g.Name}: that day's losses are at the cap ({value.Item3}, 8% of {value.Item2})");
				value.Item4 = true;
			}
			num3 = num7;
		}
		_worldLost[g.Id] = (value.Item1, value.Item2, value.Item3 + num3, value.Item4);
		return num3;
	}

	internal int FieldCap(Gang g)
	{
		if (g != null && !g.OrdersNotFeelings)
		{
			return Math.Max(0, (int)((long)MenOf(g) * 200L / (3L * (long)Math.Max(1, MenStart(g)))));
		}
		return 999;
	}

	internal double TargetWeight(Gang g)
	{
		if (g == null || g.OrdersNotFeelings)
		{
			return 1.0;
		}
		double num = MenShare(g);
		if (!(num < 0.1))
		{
			if (!(num < 0.25))
			{
				return 1.0;
			}
			return 0.5;
		}
		return 0.15;
	}

	internal double MenShare(Gang g)
	{
		if (g != null)
		{
			if (!IsDestroyed(g))
			{
				return (double)MenOf(g) / (double)Math.Max(1, MenStart(g));
			}
			return 0.0;
		}
		return 1.0;
	}

	internal float MenPower(Gang g)
	{
		double num = MenShare(g);
		return (float)((num < 0.2) ? (0.2 + 2.0 * num) : (0.6 + 0.4 * Math.Min(1.25, num)));
	}

	internal void LoseMen(Gang g, int n, string why)
	{
		if (g == null || g.StoryOnly || n <= 0 || IsDestroyed(g))
		{
			return;
		}
		int num = MenOf(g);
		int num2 = Math.Max(0, num - n);
		if (num2 != num)
		{
			MenMap[g.Id] = num2;
			GrudgeLog($"MEN {g.Name}: {num} -> {num2} ({why})");
			SaveWorld();
			try
			{
				SuppliesForLosses(g, num - num2);
			}
			catch
			{
			}
			if ((double)num >= (double)MenStart(g) * 0.4 && (double)num2 < (double)MenStart(g) * 0.4)
			{
				Feed($"MEN the {g.Name} are down to {num2} men - their crews ride short", Theme.Warn);
			}
		}
	}

	private void DailyHiring(int days)
	{
		foreach (Gang item in Gangs.All.Where((Gang x) => !x.StoryOnly && !IsDestroyed(x)))
		{
			int num = MenOf(item);
			int num2 = MenStart(item);
			int num3 = num2 * 3 / 2;
			if (num >= num2)
			{
				continue;
			}
			int num4 = Math.Min(days, 30);
			int val = Math.Min(num2 - num, num3 - num);
			int num5;
			if (item.OrdersNotFeelings)
			{
				num5 = Math.Min(val, (int)Math.Round((double)num2 * 0.015 * (double)num4));
			}
			else
			{
				int num6 = (((double)num < (double)num2 * 0.9) ? Math.Min(val, (int)Math.Round((double)num2 * 0.01 * (double)num4)) : 0);
				if (_rng.NextDouble() > RecruitChance(item))
				{
					if (num6 <= 0)
					{
						GrudgeLog($"MEN {item.Name}: nobody signs on today (recruits {RecruitChance(item) * 100.0:0}%)");
						continue;
					}
					MenMap[item.Id] = num + num6;
					GrudgeLog($"MEN {item.Name}: {num} -> {num + num6} ({num6} local men throw in - the outfit's down to {num * 100 / Math.Max(1, num2)}% of its strength)");
					continue;
				}
				num5 = Math.Min(val, (int)Math.Round((double)num2 * 0.025 * (0.33 + 0.67 * Math.Min(1.2, TerritoryShare(item))) * (double)num4));
				int num7 = (HasPurse(item) ? (PurseOf(item) - 150) : 0);
				int num8 = ((!HasPurse(item)) ? num5 : ((num7 > 0) ? (((PurseOf(item) >= 600) ? num7 : (num7 / 2)) / 2) : 0));
				bool flag = LowSupplies(item);
				if (flag)
				{
					GrudgeLog($"MEN {item.Name}: no new hands - no supplies to feed or arm them ({SuppliesOf(item)}); locals only");
					num8 = 0;
				}
				int num9 = 0;
				if ((HasPurse(item) | flag) && num8 < num5)
				{
					num9 = Math.Min(num5 - num8, (int)Math.Round((double)num2 * 0.004 * (1.0 + _rng.NextDouble()) * (double)num4));
				}
				num5 = Math.Min(num5, num8);
				if (num5 + num9 < num6)
				{
					num9 = num6 - num5;
				}
				if (num5 > 0 && HasPurse(item))
				{
					AddPurse(item, -2 * num5, $"{num5} new hands hired");
				}
				if (num9 > 0)
				{
					GrudgeLog($"MEN {item.Name}: {num9} local men throw in for a share - no wages (purse ${PurseOf(item)})");
					num5 += num9;
				}
			}
			if (num5 > 0)
			{
				MenMap[item.Id] = num + num5;
				GrudgeLog($"MEN {item.Name}: {num} -> {num + num5} (hired over {num4} day(s))");
			}
		}
		SaveWorld();
	}

	internal int Strength(Gang g)
	{
		if (g == null || g.StoryOnly)
		{
			return 0;
		}
		if (IsDestroyed(g))
		{
			return 0;
		}
		var (num, num2, num3, num4) = StrengthParts(g);
		return (int)Math.Round(100.0 * (0.3 * num + 0.3 * num2 + 0.2 * num3 + 0.2 * num4));
	}

	internal (double ground, double men, double money, double supplies) StrengthParts(Gang g)
	{
		double item = Math.Min(1.25, TerritoryShare(g)) / 1.25;
		double item2 = Math.Min(1.25, MenShare(g)) / 1.25;
		double item3 = (HasPurse(g) ? Math.Min(1.0, (double)PurseOf(g) / (g.OrdersNotFeelings ? 6000.0 : 1200.0)) : 1.0);
		return (ground: item, men: item2, money: item3, supplies: (double)SuppliesOf(g) / 100.0);
	}

	internal static string StrengthWord(int s)
	{
		if (s < 75)
		{
			if (s < 50)
			{
				if (s < 30)
				{
					if (s < 15)
					{
						return "Breaking";
					}
					return "Weak";
				}
				return "Stretched";
			}
			return "Holding";
		}
		return "Strong";
	}

	private void LoseMenInEvent(WorldEvent ev)
	{
		if (ev == null)
		{
			return;
		}
		Dictionary<string, int> dictionary = new Dictionary<string, int>();
		foreach (WorldPart p in ev.People.Where((WorldPart worldPart) => worldPart.Outcome == "KILLED" && worldPart.Gang != null))
		{
			dictionary[p.Gang] = (dictionary.TryGetValue(p.Gang, out var value) ? value : 0) + NamedWorth(Roster.FirstOrDefault((NemesisRecord n) => n.Id == p.Id)?.Rank ?? 1);
		}
		bool flag = ev.Gangs != null && ev.Gangs.Count >= 2 && DeclaredWar(ev.Gangs[0], ev.Gangs[1]);
		int fightMen = ((ev.Gangs == null || ev.Gangs.Count == 0) ? (-1) : (from id in ev.Gangs
			select Gangs.ById(id) into x
			where x != null && !x.StoryOnly
			select MenOf(x)).DefaultIfEmpty(-1).Min());
		foreach (KeyValuePair<string, int> item in ev.UnnamedDead)
		{
			dictionary[item.Key] = (dictionary.TryGetValue(item.Key, out var value2) ? value2 : 0) + WorldLoss(Gangs.ById(item.Key), item.Value, ev.GameMin, flag ? 1.0 : 0.5, fightMen);
		}
		foreach (KeyValuePair<string, int> item2 in dictionary)
		{
			LoseMen(Gangs.ById(item2.Key), item2.Value, ev.Title ?? ev.Kind);
		}
	}

	internal string MenLine()
	{
		return "men: " + string.Join(", ", from g in Gangs.All
			where !g.StoryOnly && !IsDestroyed(g)
			select $"{g.Id} {MenOf(g)}/{MenStart(g)} (strength {Strength(g)})");
	}

	private void DebugIcons(IconKind k)
	{
		if (_iconBlips.ContainsKey(k))
		{
			HideIcons(k);
			SpawnerSays("map icons: " + IconKindNames[(int)k] + " off.");
		}
		else
		{
			var (num, num2) = ShowIcons(k);
			SpawnerSays(string.Format("map icons: {0} {1}{2}. Again to hide.", num, IconKindNames[(int)k], (num2 > 0) ? $" ({num2} more left out - the map's limit; the nearest are shown)" : ""));
		}
	}

	private void DebugIconsAll()
	{
		if (_iconBlips.Count > 0)
		{
			HideMapIcons();
			SpawnerSays("map icons: all off.");
			return;
		}
		int num = 0;
		int num2 = 0;
		foreach (IconKind value in Enum.GetValues(typeof(IconKind)))
		{
			(int, int) tuple = ShowIcons(value);
			num += tuple.Item1;
			num2 += tuple.Item2;
		}
		SpawnerSays(string.Format("map icons: {0} on the map{1}. Again to hide them all.", num, (num2 > 0) ? $" ({num2} more left out - the map's limit; the nearest are shown)" : ""));
	}

	private (int shown, int left) ShowIcons(IconKind k, bool quiet = false)
	{
		HideIcons(k);
		Vector3 me = Game.Player.Character.Position;
		List<MapIcon> list = (from i in IconsOf(k)
			where i.At != Vector3.Zero
			orderby i.At.DistanceTo2D(me)
			select i).ToList();
		int num = Math.Max(0, 250 - _iconBlips.Values.Sum((List<int> v) => v.Count));
		List<int> list2 = new List<int>();
		foreach (MapIcon item in list.Take(num))
		{
			int num2 = AddMapIcon(item);
			if (num2 != 0)
			{
				list2.Add(num2);
			}
		}
		_iconBlips[k] = list2;
		if (k == IconKind.People)
		{
			_nextPeopleIcons = Game.GameTime + 3000;
		}
		if (!quiet)
		{
			GrudgeLog($"MAPICONS {IconKindNames[(int)k]}: {list2.Count} shown of {list.Count}");
		}
		return (shown: list2.Count, left: Math.Max(0, list.Count - num));
	}

	private unsafe void HideIcons(IconKind k)
	{
		if (!_iconBlips.TryGetValue(k, out var value))
		{
			return;
		}
		foreach (int item in value)
		{
			int current = item;
			if (MAP.DOES_BLIP_EXIST(current))
			{
				MAP.REMOVE_BLIP(&current);
			}
		}
		_iconBlips.Remove(k);
	}

	internal void HideMapIcons()
	{
		foreach (IconKind item in _iconBlips.Keys.ToList())
		{
			HideIcons(item);
		}
	}

	private int AddMapIcon(MapIcon ic)
	{
		Crumbs.Native("map icon");
		int num = ((ic.Radius > 0f) ? Function.Call<int>(5039874870525413504uL, new InputArgument[5]
		{
			Joaat.Of("BLIP_STYLE_AREA"),
			ic.At.X,
			ic.At.Y,
			ic.At.Z,
			ic.Radius
		}) : MAP.BLIP_ADD_FOR_COORDS(2545348716u, ic.At.X, ic.At.Y, ic.At.Z));
		if (num == 0)
		{
			return 0;
		}
		if (ic.Sprite != null)
		{
			MAP.SET_BLIP_SPRITE(num, MISC.GET_HASH_KEY(ic.Sprite), p2: true);
		}
		if (ic.Tint != null)
		{
			try
			{
				Function.Call<bool>(7362600660482055727uL, new InputArgument[2]
				{
					num,
					MISC.GET_HASH_KEY(ic.Tint)
				});
			}
			catch
			{
			}
		}
		Function.Call(11290983183885202434uL, num, new InputArgument(UiDraw.ForeverVarString(ic.Name)));
		return num;
	}

	private void MapIconsTick()
	{
		if (_iconBlips.ContainsKey(IconKind.People) && Game.GameTime >= _nextPeopleIcons)
		{
			ShowIcons(IconKind.People, quiet: true);
		}
	}

	private static MapIcon Icon(Vector3 at, string sprite, string name, string tint = null, float radius = 0f)
	{
		return new MapIcon
		{
			At = at,
			Sprite = sprite,
			Name = name,
			Tint = tint,
			Radius = radius
		};
	}

	private IEnumerable<MapIcon> IconsOf(IconKind k)
	{
		switch (k)
		{
		case IconKind.Camps:
		{
			foreach (CampSite allSite in Camps.AllSites)
			{
				bool flag = allSite.Id.StartsWith("placed_");
				bool flag2 = !flag && Camps.Extra.Contains(allSite);
				string text = Gangs.ById(SiteOwner(allSite))?.Name ?? "nobody holds it";
				Vector3 at = SitePos(allSite);
				string sprite = (allSite.Hideout ? "blip_region_hideout" : "blip_camp_tent");
				string name = "Camp " + (allSite.Hideout ? "hideout" : "site") + ": " + text + " - " + allSite.Region + " (" + (flag ? "placed" : (flag2 ? "learned" : "the game's")) + ")";
				string tint;
				if (flag)
				{
					tint = "BLIP_MODIFIER_DEBUG_BLUE";
				}
				else
				{
					tint = (flag2 ? "BLIP_MODIFIER_DEBUG_GREEN" : null);
				}
				yield return Icon(at, sprite, name, tint);
			}
			CampSite[] retired = Camps.Retired;
			foreach (CampSite campSite2 in retired)
			{
				yield return Icon(new Vector3(campSite2.X, campSite2.Y, campSite2.Z), "blip_region_hideout", "Retired camp: " + campSite2.Name + " - nobody camps here", "BLIP_MODIFIER_DEBUG_RED");
			}
			break;
		}
		case IconKind.Supplies:
			foreach (Gang item3 in Gangs.All.Where(HoldsCamps))
			{
				CampSite campSite3 = SupplyCampOf(item3);
				if (campSite3 != null)
				{
					yield return Icon(SitePos(campSite3), "blip_chest", "Supplies: the " + item3.Name + "'s supply camp - " + campSite3.Region, "BLIP_MODIFIER_DEBUG_YELLOW");
				}
			}
			foreach (StashSpot stashSpot in StashSpots)
			{
				yield return Icon(new Vector3(stashSpot.X, stashSpot.Y, stashSpot.Z), "blip_chest", "Stash spot: " + stashSpot.Town + (stashSpot.BuiltIn ? " (built in)" : " (placed)"));
			}
			break;
		case IconKind.Funerals:
			foreach (var item4 in AllCemeteries())
			{
				yield return Icon(item4.at, "blip_ambient_death", "Funerals: " + CemeteryLabel(item4.at));
			}
			foreach (Vector3 plot in Plots)
			{
				yield return Icon(plot, "blip_deadeye_cross", "Funeral plot (marked)");
			}
			break;
		case IconKind.Treasuries:
			foreach (Gang item5 in Gangs.All.Where(HoldsCamps))
			{
				CampSite campSite = TreasuryOf(item5);
				if (campSite != null)
				{
					yield return Icon(SitePos(campSite), "blip_gang_savings", "Treasury: the " + item5.Name + "'s - " + campSite.Region + (TreasuryKnownList.Contains(item5.Id) ? " (you know it)" : ""));
				}
			}
			break;
		case IconKind.LaidUp:
			foreach (KeyValuePair<string, (Vector3?, Vector3?)> townSpot in TownSpots)
			{
				Vector3? item = townSpot.Value.Item1;
				if (item.HasValue)
				{
					Vector3 valueOrDefault2 = item.GetValueOrDefault();
					if (OpenDoctors.Contains(townSpot.Key))
					{
						yield return Icon(valueOrDefault2, "blip_shop_doctor", "Laid-up men: the " + townSpot.Key + " doctor's");
					}
				}
			}
			foreach (var hotel in Hotels)
			{
				yield return Icon(hotel.at, "blip_hotel_bed", "Laid-up men: a hotel bed in " + hotel.town + " (marked)");
			}
			break;
		case IconKind.Bars:
			foreach (KeyValuePair<string, (Vector3?, Vector3?)> townSpot2 in TownSpots)
			{
				Vector3? item = townSpot2.Value.Item2;
				if (item.HasValue)
				{
					Vector3 valueOrDefault = item.GetValueOrDefault();
					yield return Icon(valueOrDefault, "blip_saloon", "Saloon: " + townSpot2.Key);
				}
			}
			foreach (Bar b in Bars)
			{
				if (!TownSpots.Any((KeyValuePair<string, (Vector3? Doctor, Vector3? Saloon)> t) =>
				{
					Vector3? item2 = t.Value.Saloon;
					return item2.HasValue && item2.GetValueOrDefault().DistanceTo(b.At) < 5f;
				}))
				{
					yield return Icon(b.At, "blip_saloon", "Saloon fight bar: " + b.Town, "BLIP_MODIFIER_DEBUG_YELLOW");
				}
			}
			break;
		case IconKind.Habits:
			foreach (NemesisRecord r in Roster.Where((NemesisRecord n) => n.IsAlive && !n.PresumedDead && n.Habits != null))
			{
				foreach (Habit habit in r.Habits)
				{
					if (habit.X != 0f || habit.Y != 0f)
					{
						yield return Icon(new Vector3(habit.X, habit.Y, habit.Z), "blip_ambient_gang_leader", "Habit: " + r.Name + " " + HabitText(habit) + (habit.Known ? " (you know it)" : ""));
					}
				}
			}
			break;
		case IconKind.Plans:
			foreach (Plan item6 in Plans.Where((Plan x) => !x.Done))
			{
				Vector3 at2 = ((item6.Kind == "funeral" && item6.PlotSet) ? new Vector3(item6.PlotX, item6.PlotY, item6.PlotZ) : new Vector3(item6.X, item6.Y, item6.Z));
				string text2 = Gangs.ById(item6.Gang)?.Name;
				yield return Icon(at2, "blip_attention", "Plan (" + item6.Kind + (item6.Lie ? ", a lie" : "") + ((text2 != null) ? (", " + text2) : "") + "): " + item6.Title + " - " + WhenText(item6.DueAt) + (item6.Known ? " (known)" : ""));
			}
			break;
		case IconKind.People:
		{
			List<KeyValuePair<int, NemesisRecord>> list = _worldNemeses.ToList();
			if (_activeNemesisPed != null && ActiveRecord != null && !_worldNemeses.ContainsKey(_activeNemesisPed.Handle))
			{
				list.Add(new KeyValuePair<int, NemesisRecord>(_activeNemesisPed.Handle, ActiveRecord));
			}
			foreach (KeyValuePair<int, NemesisRecord> item7 in list)
			{
				if (item7.Value != null && ENTITY.DOES_ENTITY_EXIST(item7.Key) && !ENTITY.IS_ENTITY_DEAD(item7.Key))
				{
					yield return Icon(ENTITY.GET_ENTITY_COORDS(item7.Key, p1: true, p2: true), "blip_ambient_npc", string.Format("{0} ({1}, rank {2})", item7.Value.Name, Gangs.ById(item7.Value.Gang)?.Name ?? "no outfit", item7.Value.Rank));
				}
			}
			break;
		}
		case IconKind.Calm:
		{
			CampSite[] retired = Camps.Retired;
			foreach (CampSite s in retired)
			{
				Vector3 c = new Vector3(s.X, s.Y, s.Z);
				yield return Icon(c, null, $"Calm zone: {s.Name} - no fights within {300f:0} m", null, 300f);
				yield return Icon(c, "blip_region_hideout", "Calm zone: " + s.Name + " (its middle)", "BLIP_MODIFIER_DEBUG_GREEN");
			}
			break;
		}
		}
	}

	private void RememberMaskedKill(Ped dead, Ped player)
	{
		if (dead == null || !dead.Exists() || !dead.IsHuman || Kids.IsChild(dead) || RecordAt(dead.Handle) != null || MISC.GET_MISSION_FLAG() || IsStoryPed(dead) || GameOwned(dead) || IsCompanion(dead.Handle) || !PlayerMasked(player))
		{
			return;
		}
		uint hash = (uint)dead.Model.Hash;
		Vector3 position = dead.Position;
		string zoneName = GetZoneName(position);
		NemesisRecord nemesisRecord = NewRecord(hash, zoneName);
		if (!_named.TryGetValue(dead.Handle, out var value))
		{
			try
			{
				value = NameByLook(dead);
			}
			catch
			{
				value = null;
			}
		}
		if (value != null && !string.IsNullOrEmpty(value.Name))
		{
			nemesisRecord.Name = value.Name;
			nemesisRecord.Title = value.Title ?? "";
		}
		if (_provoked.TryGetValue(dead.Handle, out var value2) && value2.Record == null)
		{
			nemesisRecord.Personality = value2.Temper;
			if (value2.Shadow != null)
			{
				CopyTraits(value2.Shadow, nemesisRecord);
			}
		}
		nemesisRecord.Origin = ((nemesisRecord.Gang != null) ? GrudgeOrigin.GangMember : GrudgeOrigin.Gunfight);
		nemesisRecord.HasOrigin = true;
		nemesisRecord.OriginX = position.X;
		nemesisRecord.OriginY = position.Y;
		nemesisRecord.OriginZ = position.Z;
		nemesisRecord.KinId = null;
		nemesisRecord.KinRelation = null;
		nemesisRecord.Hate = 0;
		nemesisRecord.IsAlive = false;
		nemesisRecord.PresumedDead = false;
		nemesisRecord.KilledByPlayer = true;
		nemesisRecord.TimesKilledPlayer = 0;
		nemesisRecord.Touch();
		try
		{
			KeepOutfit(dead, nemesisRecord);
		}
		catch
		{
		}
		History(nemesisRecord, "KILLED BY YOU near " + zoneName + " - you wore a mask; he never saw your face", Theme.Blood);
		Roster.Add(nemesisRecord);
		_bulletImpact.TagVictim(dead.Handle, nemesisRecord.Id, nemesisRecord.FullName);
		ForgetPerson(dead.Handle, nemesisRecord.Name);
		_named.Remove(dead.Handle);
		WorldPart worldPart = new WorldPart
		{
			Id = nemesisRecord.Id,
			Name = nemesisRecord.Name,
			Gang = nemesisRecord.Gang,
			Outcome = "KILLED",
			Note = "you were masked"
		};
		ChronicleDeed("kill", "You killed " + nemesisRecord.Name, "near " + zoneName, position, nemesisRecord.Gang, worldPart);
		SaveRoster();
		GrudgeLog("MASKED KILL " + nemesisRecord.FullName + " (" + ((nemesisRecord.Gang == null) ? "unaffiliated" : Gangs.ById(nemesisRecord.Gang)?.Name) + ") remembered - near " + zoneName);
		DeathNotice(nemesisRecord.FullName + " is dead.");
	}

	private void EnsureMind(NemesisRecord r)
	{
		if (r == null)
		{
			return;
		}
		if (!r.MindRolled)
		{
			try
			{
				Mind.Roll(r, (r.Id != null) ? Seeds.For(r, "mind") : _rng, GameMinutesNow());
			}
			catch (Exception ex)
			{
				GrudgeLog("MIND roll failed for " + r.Name + ": " + ex.Message);
			}
		}
		if (!r.QuirksRolled && r.MindRolled)
		{
			Quirks.Roll(r, (r.Id != null) ? Seeds.For(r, "quirks") : _rng);
			if (r.Quirks.Count > 0)
			{
				GrudgeLog("QUIRKS " + r.Name + ": " + string.Join(", ", r.Quirks));
			}
		}
	}

	internal void CheckSkills(NemesisRecord r, string band)
	{
		if (r == null || !r.IsAlive)
		{
			return;
		}
		bool flag = !r.SkillsV2;
		int num = r.Skills?.Count ?? 0;
		List<string> list = Quirks.EarnSkills(r, band);
		if (flag)
		{
			if (num > 0 || (r.Skills?.Count ?? 0) > 0)
			{
				GrudgeLog(string.Format("SKILL {0}: rules v2 - now {1} (rank {2}, had {3})", r.Name, string.Join(", ", r.Skills), r.Rank, num));
			}
			SaveRoster();
			return;
		}
		foreach (string item in list)
		{
			History(r, "LEARNED: " + Quirks.SkillText(item), Theme.Gold);
			Feed("SKILL " + r.Name + ": " + Quirks.SkillText(item), Theme.Gold);
			GrudgeLog("SKILL " + r.Name + ": " + item);
			SaveRoster();
		}
	}

	internal void Remember(NemesisRecord r, string emotion, int intensity, string text, string cause = "you")
	{
		if (r == null)
		{
			return;
		}
		EnsureMind(r);
		Dictionary<string, int> before = ((r.Facets != null) ? new Dictionary<string, int>(r.Facets) : null);
		_ = r.Goals?.Count;
		string text2 = string.Join(",", r.Goals?.Select((Goal g) => g.Type) ?? new string[0]);
		if (!Mind.Remember(r, emotion, intensity, text, cause, GameMinutesNow(), _rng))
		{
			return;
		}
		List<string> list = ((before == null) ? new List<string>() : (from kv in r.Facets
			where before.TryGetValue(kv.Key, out var value) && value != kv.Value
			select $"{kv.Key.ToLowerInvariant()} {before[kv.Key]} -> {kv.Value}").ToList());
		string text3;
		if (string.Join(",", r.Goals?.Select((Goal g) => g.Type) ?? new string[0]) != text2)
		{
			List<Goal> goals = r.Goals;
			if (goals != null && goals.Count > 0)
			{
				text3 = "; now wants: " + r.Goals[0].Text;
				goto IL_0163;
			}
		}
		text3 = "";
		goto IL_0163;
		IL_0163:
		string text4 = text3;
		Feed(string.Format("MIND {0} will never forget: {1} ({2} {3}){4}{5}", r.Name, text, Mind.Felt(emotion), intensity, (list.Count > 0) ? (" - " + string.Join(", ", list)) : "", text4), Mind.EmotionColor(emotion), r);
		GrudgeLog(string.Format("MIND {0} long-term {1} {2}: {3} | {4}{5}", r.Name, emotion, intensity, text, string.Join(", ", list), text4));
	}

	private static string EmotionOfMood(string mood)
	{
		switch (mood)
		{
		case "Grieving":
		case "Homesick":
			return "Grief";
		case "Shaken":
		case "Sick":
		case "Hurting":
			return "Fear";
		case "Bitter":
			return "Anger";
		case "Jailed":
		case "Humiliated":
			return "Shame";
		case "Proud":
			return "Pride";
		case "Joyful":
		case "Steady":
		case "Flush":
			return "Joy";
		default:
			return null;
		}
	}

	private void UpdateMinds()
	{
		long num = GameMinutesNow();
		if (num <= 0)
		{
			return;
		}
		long num2 = num / 60;
		long num3 = num / 1440;
		if (_lastMindHour < 0)
		{
			_lastMindHour = num2;
			_lastMindDay = num3;
			return;
		}
		if (num2 <= _lastMindHour)
		{
			if (num2 < _lastMindHour - 2)
			{
				_lastMindHour = num2;
				_lastMindDay = num3;
			}
			return;
		}
		int num4 = (int)Math.Min(48L, num2 - _lastMindHour);
		_lastMindHour = num2;
		List<NemesisRecord> list = Roster.Where((NemesisRecord r) => r.IsAlive && !r.PresumedDead).ToList();
		foreach (NemesisRecord item in list)
		{
			EnsureMind(item);
			CheckSkills(item, null);
		}
		for (int num5 = 0; num5 < num4; num5++)
		{
			foreach (NemesisRecord item2 in list)
			{
				if (Roster.Contains(item2))
				{
					HourOf(item2, num - (long)(num4 - 1 - num5) * 60L);
				}
			}
		}
		if (num3 > _lastMindDay)
		{
			int num6 = (int)Math.Min(7L, num3 - _lastMindDay);
			_lastMindDay = num3;
			for (int num7 = 0; num7 < num6; num7++)
			{
				foreach (NemesisRecord item3 in list)
				{
					if (Roster.Contains(item3) && item3.IsAlive)
					{
						DayOf(item3, num);
					}
				}
			}
		}
		SaveRoster();
	}

	private void HourOf(NemesisRecord r, long now)
	{
		if (r.Needs == null)
		{
			return;
		}
		List<PastEntry> past = r.Past;
		bool flag = (past != null && past.Any((PastEntry e) => e.Text != null && e.Text.Contains("drinking"))) || (Mind.F(r, "Anger") > 65 && Mind.F(r, "Piety") < 30);
		Rise("Drink", (!flag) ? 1 : 3);
		Rise("Company", (!r.TraitsRolled || r.Sociability != Sociability.Outgoing) ? 1 : 2);
		DateTime dateTime = GameDate.FromMinutes(now);
		int hour = dateTime.Hour;
		float num = Mind.F(r, "Piety");
		float num2 = Mind.F(r, "Greed");
		if ((num >= 65f && hour % 6 == 0) || (num >= 45f && num < 65f && hour % 12 == 0))
		{
			Rise("Faith", 1);
		}
		if (num2 >= 60f || hour % 3 == 0)
		{
			Rise("Money", 1);
		}
		if (dateTime.DayOfWeek == DayOfWeek.Sunday && hour == 10 && num >= 45f)
		{
			MeetN("Faith", 60);
		}
		if (r.Gang != null && dateTime.DayOfWeek == DayOfWeek.Saturday && hour == 20)
		{
			MeetN("Money", 50);
		}
		if (r.Gang == null && hour == 18 && (uint)Seeds.Stable($"work/{r.Id}/{now / 1440}") % 3u == 0)
		{
			MeetN("Money", 35);
		}
		Rise("Violence", (Mind.F(r, "Cruelty") >= 60 || Mind.F(r, "Anger") >= 70) ? 2 : 0);
		if (r.Gang != null && (r.CampId != null || r.BossId != null))
		{
			Rise("Company", -3);
			if (_rng.Next(3) == 0)
			{
				Rise("Drink", -4);
			}
		}
		int num3 = Mind.NeedNames.Count((string n) => Mind.N(r, n) >= 70);
		int num4 = r.Memories?.Where((Memory m) => !m.LongTerm && Mind.Bad.Contains(m.Emotion)).Sum((Memory m) => m.Intensity) ?? 0;
		int num5 = num3 + ((num4 >= 150) ? 1 : 0) - 2;
		r.Stress = Math.Max(0, Math.Min(100, r.Stress + num5));
		if (r.Stress >= 85 && _rng.Next(100) < 2 && OffStage(r) && (!_snappedAt.TryGetValue(r.Id ?? "", out var value) || value > now || now - value >= 4320))
		{
			_snappedAt[r.Id ?? ""] = now;
			Snap(r, now);
		}
		void MeetN(string n, int d)
		{
			r.Needs[n] = Math.Max(0, Mind.N(r, n) - d);
		}
		void Rise(string n, int d)
		{
			r.Needs[n] = Math.Max(0, Math.Min(100, Mind.N(r, n) + d));
		}
	}

	private void DayOf(NemesisRecord r, long now)
	{
		Mind.Fade(r);
		if (r.Goals != null)
		{
			Gang gang = Gangs.Of(r);
			r.Goals.RemoveAll((Goal g) =>
			{
				if (g.Type == "Protect")
				{
					NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord x) => x.Id == g.Target);
					if (nemesisRecord == null)
					{
						return true;
					}
					return !nemesisRecord.IsAlive;
				}
				return false;
			});
			if (gang != null && r.Goals.Any((Goal g) => g.Type == "Rise") && r.Rank >= gang.Tiers[0].MinRank)
			{
				r.Goals.RemoveAll((Goal g) => g.Type == "Rise");
			}
		}
		if (Mind.Has(r, "Settle") && (EffectiveFear(r) >= 40 || r.Stress >= 60) && r.TimesKilledPlayer == 0 && OffStage(r) && _rng.Next(100) < 4 && !LoreProtected(r) && (r.Gang == null || SuccessorId(Gangs.ById(r.Gang)) != r.Id))
		{
			QuitTheLife(r, now);
		}
	}

	private void Snap(NemesisRecord r, long now)
	{
		MindSnaps++;
		Gang gang = Gangs.Of(r);
		NemesisRecord nemesisRecord = ((gang != null) ? (from _ in Roster
			where _ != r && _.Gang == r.Gang && _.IsAlive && !_.PresumedDead && OffStage(_)
			orderby _rng.Next()
			select _).FirstOrDefault() : null);
		string text = ((nemesisRecord != null) ? (r.Name + " snapped and went for " + nemesisRecord.Name) : (r.Name + " snapped - a bottle through a window, a fight with a stranger"));
		WorldEvent worldEvent = NewEvent("LIFE", now);
		worldEvent.Gangs.Add(r.Gang ?? "");
		worldEvent.Title = text;
		worldEvent.Place = ((gang != null) ? ("(" + gang.Name + ")") : "(rides alone)");
		worldEvent.Lines.Add($"Stress {r.Stress} - he'd had enough.");
		WorldPart worldPart = new WorldPart
		{
			Id = r.Id,
			Name = r.Name,
			Gang = r.Gang,
			Outcome = "SNAPPED",
			Note = "at the end of his rope"
		};
		worldEvent.People.Add(worldPart);
		if (nemesisRecord != null)
		{
			worldEvent.People.Add(new WorldPart
			{
				Id = nemesisRecord.Id,
				Name = nemesisRecord.Name,
				Gang = nemesisRecord.Gang,
				Outcome = "HIT",
				Note = "on the wrong end of it"
			});
			Mind.SetTie(r, nemesisRecord.Id, "enemy", Math.Min(Mind.TieTo(r, nemesisRecord.Id)?.Strength ?? 0, 0) - 40, "the night he snapped");
			Mind.SetTie(nemesisRecord, r.Id, "enemy", Math.Min(Mind.TieTo(nemesisRecord, r.Id)?.Strength ?? 0, 0) - 50, "the night he snapped");
			AddThought(nemesisRecord, "Bitter", r.Name + " went for him for no reason", -2, 72, now);
		}
		r.Stress = Math.Max(0, r.Stress - 40);
		if (r.Needs != null)
		{
			r.Needs["Violence"] = 0;
		}
		AddThought(r, "Humiliated", "lost control in front of everyone", -2, 48, now, worldPart);
		History(r, (nemesisRecord != null) ? ("SNAPPED and went for " + nemesisRecord.Name) : "SNAPPED - lost control in front of everyone", Theme.Warn);
		worldEvent.Heard = true;
		Chronicle.Events.Add(worldEvent);
		SaveWorld();
		LastMindNote = text;
		GrudgeLog($"MIND {text} (stress -> {r.Stress})");
	}

	private void QuitTheLife(NemesisRecord r, long now)
	{
		MindQuits++;
		string text = (new string[6] { "a farm outside Strawberry", "his brother's place back East", "a homestead near Emerald Ranch", "the railroad in New Austin", "his wife's people in Lemoyne", "a mining claim in the Grizzlies" })[_rng.Next(6)];
		WorldEvent worldEvent = NewEvent("LIFE", now);
		worldEvent.Gangs.Add(r.Gang ?? "");
		worldEvent.Title = r.Name + " quit the life";
		worldEvent.Place = "for " + text;
		worldEvent.Lines.Add((r.Gang != null) ? ("He walked away from the " + Gangs.Of(r)?.Name + ". Nobody stopped him.") : "He sold his horse and left the territory.");
		worldEvent.People.Add(new WorldPart
		{
			Id = r.Id,
			Name = r.Name,
			Gang = r.Gang,
			Outcome = "LEFT",
			Note = $"fear {EffectiveFear(r)}, stress {r.Stress}"
		});
		worldEvent.Heard = true;
		Chronicle.Events.Add(worldEvent);
		foreach (NemesisRecord item in Roster.Where((NemesisRecord x) => x != r && Mind.TieTo(x, r.Id) != null))
		{
			AddThought(item, "Homesick", r.Name + " quit the life", -1, 48, now);
		}
		RemoveRecord(r, "quit the life");
		SaveWorld();
		LastMindNote = r.Name + " quit the life";
		Feed($"MIND {r.Name} quit the life (fear {EffectiveFear(r)}, stress {r.Stress}) - gone {text}", Theme.Dim);
		GrudgeLog("MIND " + r.Name + " quit the life - " + text);
		GrudgeNotice("Word is " + r.FullName + " quit the life. Gone to " + text + ".");
	}

	private static int KinStrength(string rel)
	{
		switch (rel)
		{
		default:
			return 40;
		case "cousin":
			return 50;
		case "uncle":
		case "nephew":
			return 60;
		case "brother":
		case "son":
		case "father":
			return 80;
		}
	}

	private void SyncTies()
	{
		if (Game.GameTime < _nextTieSync)
		{
			return;
		}
		_nextTieSync = Game.GameTime + 15000;
		foreach (NemesisRecord r in Roster)
		{
			if (!r.MindRolled)
			{
				continue;
			}
			r.Ties = r.Ties ?? new List<Tie>();
			if (!r.GoalsSet)
			{
				Mind.InitGoals(r, Seeds.For(r, "goals"), GameMinutesNow());
			}
			if (r.KinId != null && Roster.Any((NemesisRecord k) => k.Id == r.KinId))
			{
				if (Mind.TieTo(r, r.KinId) == null)
				{
					Mind.SetTie(r, r.KinId, "kin", KinStrength(r.KinRelation), Traits.Inverse(r.KinRelation));
				}
				NemesisRecord nemesisRecord = Roster.First((NemesisRecord x) => x.Id == r.KinId);
				if (nemesisRecord.MindRolled && Mind.TieTo(nemesisRecord, r.Id) == null)
				{
					Mind.SetTie(nemesisRecord, r.Id, "kin", KinStrength(r.KinRelation), r.KinRelation);
				}
			}
			foreach (string item in r.FriendIds ?? new List<string>())
			{
				if (Mind.TieTo(r, item) == null)
				{
					Mind.SetTie(r, item, "friend", 50 + _rng.Next(25));
				}
			}
			foreach (Tie item2 in r.Ties.Where((Tie t) => t.Type == "friend" && !(r.FriendIds ?? new List<string>()).Contains(t.Id)).ToList())
			{
				item2.Type = "enemy";
				item2.Strength = Math.Min(item2.Strength, -20);
			}
			NemesisRecord nemesisRecord2 = ((r.BossId != null) ? Roster.FirstOrDefault((NemesisRecord b) => b.Id == r.BossId) : null);
			if (nemesisRecord2 != null && nemesisRecord2.MindRolled && Mind.TieTo(r, nemesisRecord2.Id) == null)
			{
				Mind.SetTie(r, nemesisRecord2.Id, "mentor", 20 + Mind.F(r, "Loyalty") / 3, "his boss");
				if (Mind.TieTo(nemesisRecord2, r.Id) == null)
				{
					Mind.SetTie(nemesisRecord2, r.Id, "protege", 15 + Mind.F(nemesisRecord2, "Loyalty") / 4, "one of his men");
				}
			}
			r.Ties.RemoveAll((Tie t) => !Roster.Any((NemesisRecord x) => x.Id == t.Id));
		}
	}

	private void MeetNeeds(NemesisRecord r, string text)
	{
		if (r?.Needs != null && text != null)
		{
			string text2 = text.ToLowerInvariant();
			if (text2.Contains("drink") || text2.Contains("whiskey") || text2.Contains("saloon") || text2.Contains("bottle") || text2.Contains("drunk"))
			{
				Meet("Drink", 45);
			}
			if (text2.Contains("church") || text2.Contains("pray") || text2.Contains("god") || text2.Contains("preacher") || text2.Contains("hymn"))
			{
				Meet("Faith", 50);
			}
			if (text2.Contains("pay") || text2.Contains("won") || text2.Contains("score") || text2.Contains("stole") || text2.Contains("money") || text2.Contains("cards"))
			{
				Meet("Money", 40);
			}
			if (text2.Contains("fight") || text2.Contains("brawl") || text2.Contains("duel") || text2.Contains("knife") || text2.Contains("blows") || text2.Contains("shot"))
			{
				Meet("Violence", 50);
			}
			if (text2.Contains("friend") || text2.Contains("wedding") || text2.Contains("sang") || text2.Contains("letter") || text2.Contains("visit") || text2.Contains("together"))
			{
				Meet("Company", 40);
			}
		}
		void Meet(string n, int d)
		{
			r.Needs[n] = Math.Max(0, Mind.N(r, n) - d);
		}
	}

	internal string MindDebugLine()
	{
		List<NemesisRecord> list = Roster.Where((NemesisRecord r) => r.IsAlive && r.MindRolled).ToList();
		if (list.Count == 0)
		{
			return "minds: -";
		}
		IEnumerable<string> values = from g in list.SelectMany((NemesisRecord r) => r.Goals ?? new List<Goal>())
			group g by g.Type into g
			orderby g.Count() descending
			select $"{g.Key.ToLowerInvariant()} {g.Count()}";
		return $"minds: {list.Count} - stress avg {list.Average((NemesisRecord r) => r.Stress):0}, {Enumerable.Count(list, (NemesisRecord r) => r.Stress >= 70)} on edge, {Enumerable.Count(list, (NemesisRecord r) => Mind.NeedNames.Any((string n) => Mind.N(r, n) >= 70))} with unmet needs" + string.Format("  -  wants: {0}  -  {1} lasting memories, {2} snapped, {3} quit", string.Join(", ", values), list.Sum((NemesisRecord r) =>
		{
			List<Memory> memories = r.Memories;
			return (memories != null) ? Enumerable.Count(memories, (Memory m) => m.LongTerm) : 0;
		}), MindSnaps, MindQuits) + ((LastMindNote != "") ? ("  -  last: " + LastMindNote) : "");
	}

	internal string MindShort(NemesisRecord r)
	{
		if (r == null || !r.MindRolled)
		{
			return "";
		}
		Goal goal = r.Goals?.FirstOrDefault();
		Memory memory = Mind.Strongest(r);
		return string.Format("stress {0}{1}{2}", r.Stress, (goal != null) ? (", wants to " + goal.Type.ToLowerInvariant() + ((goal.Target == "you") ? " (you)" : "")) : "", (memory != null) ? (", " + Mind.Felt(memory.Emotion) + ": " + memory.Text) : "");
	}

	private static string[] FemaleFirstFor(string[] maleBank)
	{
		if (maleBank != NameBank.IrishFirst)
		{
			if (maleBank != NameBank.SouthernFirst)
			{
				return NameBank.AmericanFemaleFirst;
			}
			return NameBank.SouthernFemaleFirst;
		}
		return NameBank.IrishFemaleFirst;
	}

	private (string, string) FreshName(uint model, bool female = false)
	{
		Gang gang = Gangs.ForModel(model);
		if (gang != null && gang.RankInName && !female)
		{
			return (SoldierName(gang), "");
		}
		bool flag = South && _rng.Next(100) < 60;
		string[] array = gang?.FirstNames ?? (flag ? NameBank.SouthernFirst : NameBank.AmericanFirst);
		string[] array2 = gang?.LastNames ?? (flag ? NameBank.SouthernLast : NameBank.AmericanLast);
		string[] array3 = gang?.Titles ?? NameBank.AmericanTitles;
		if (female && array != NameBank.WapitiFirst)
		{
			array = FemaleFirstFor(array);
			array3 = NameBank.FemaleTitles;
		}
		Dictionary<string, int> firstUse = new Dictionary<string, int>();
		Dictionary<string, int> lastUse = new Dictionary<string, int>();
		foreach (Named value5 in _named.Values)
		{
			Count(value5.Name);
		}
		foreach (NemesisRecord item in Roster)
		{
			if (item.IsAlive)
			{
				Count(item.Name);
			}
		}
		if (_keptNames != null)
		{
			foreach (string keptName in _keptNames)
			{
				Count(keptName);
			}
		}
		string text = null;
		string text2 = null;
		int num = int.MaxValue;
		for (int i = 0; i < 24; i++)
		{
			string text3 = array[_rng.Next(array.Length)];
			string text4 = array2[_rng.Next(array2.Length)];
			string name = text3 + " " + text4;
			text2 = text2 ?? name;
			if ((gang?.ExcludedNames != null && gang.ExcludedNames.Contains(name)) || Roster.Any((NemesisRecord r) => r.Name == name) || _named.Values.Any((Named n) => n.Name == name) || NameKept(name) || NameRetired(name))
			{
				continue;
			}
			int num2 = (firstUse.TryGetValue(text3, out var value) ? value : 0) * 2 + (lastUse.TryGetValue(text4, out var value2) ? value2 : 0) * 2;
			if (num2 < num)
			{
				text = name;
				num = num2;
				if (num2 == 0)
				{
					break;
				}
			}
		}
		return (text ?? text2, HasNickname(text ?? text2, gang != null) ? array3[_rng.Next(array3.Length)] : "");
		void Count(string full)
		{
			if (!string.IsNullOrEmpty(full))
			{
				int num3 = full.IndexOf(' ');
				if (num3 > 0)
				{
					string key = full.Substring(0, num3);
					string key2 = full.Substring(num3 + 1);
					firstUse[key] = ((!firstUse.TryGetValue(key, out var value3)) ? 1 : (value3 + 1));
					lastUse[key2] = ((!lastUse.TryGetValue(key2, out var value4)) ? 1 : (value4 + 1));
				}
			}
		}
	}

	private string SoldierName(Gang g)
	{
		string[] array = g.LastNames ?? NameBank.AmericanLast;
		string text = null;
		for (int i = 0; i < 30; i++)
		{
			if (text != null)
			{
				break;
			}
			string text2 = array[_rng.Next(array.Length)];
			if (!Taken(text2))
			{
				text = text2;
			}
		}
		return "Pvt. " + (text ?? array[_rng.Next(array.Length)]);
		bool Taken(string sur)
		{
			string end = " " + sur;
			if (!Roster.Any((NemesisRecord r) => r.Gang == g.Id && r.Name != null && r.Name.EndsWith(end)) && !_named.Values.Any((Named n) => n.Name != null && n.Name.EndsWith(end) && Prefixes.Any((string p) => n.Name.StartsWith(p))) && !NameKept("Pvt." + end))
			{
				return NameRetired("Pvt." + end);
			}
			return true;
		}
	}

	private void FixSoldierNames()
	{
		Dictionary<string, string> map = new Dictionary<string, string>();
		int num = 0;
		int num2 = 0;
		foreach (Acquaintance person in People)
		{
			string text = Fix(person.Name, person.Model);
			if (text != person.Name)
			{
				person.Name = text;
				person.Title = "";
				num++;
			}
		}
		foreach (Print value2 in Prints.Values)
		{
			uint result = 0u;
			if (value2.Fp != null && value2.Fp.Length >= 8)
			{
				uint.TryParse(value2.Fp.Substring(0, 8), NumberStyles.HexNumber, null, out result);
			}
			string text2 = Fix(value2.Name, result);
			if (text2 != value2.Name)
			{
				value2.Name = text2;
				value2.Title = "";
				num2++;
			}
		}
		int num3 = _bulletImpact?.RenameVictims((string name, uint model) => Fix(name, model)) ?? 0;
		if (_keptNames != null)
		{
			foreach (KeyValuePair<string, string> item in map)
			{
				if (_keptNames.Remove(item.Key))
				{
					_keptNames.Add(item.Value);
				}
			}
		}
		if (num > 0)
		{
			_peopleDirty = true;
		}
		if (num2 > 0)
		{
			_printsDirty = true;
			_nextPrintsSave = 0;
		}
		if (map.Count > 0)
		{
			GrudgeLog($"NAMING soldier names fixed: {num} people you know, {num2} looks, {num3} X-ray entries");
		}
		string Fix(string full, uint model)
		{
			if (!string.IsNullOrEmpty(full))
			{
				Gang gang = Gangs.ForModel(model);
				if (gang != null && gang.RankInName)
				{
					if (Prefixes.Any((string p) => full.StartsWith(p)) || !full.Contains(' '))
					{
						return full;
					}
					if (map.TryGetValue(full, out var value))
					{
						return value;
					}
					string text3 = "Pvt. " + full.Substring(full.LastIndexOf(' ') + 1);
					map[full] = text3;
					GrudgeLog("NAMING soldier rename " + full + " -> " + text3);
					return text3;
				}
			}
			return full;
		}
	}

	private bool NameRetired(string name)
	{
		if (_deadNames == null || Game.GameTime - _deadNamesAt > 10000)
		{
			_deadNamesAt = Game.GameTime;
			IEnumerable<string> first = (from a in People
				where a.Name != null
				select a.Name).Concat(from p in Prints.Values
				where p.Dead && p.Name != null
				select p.Name);
			IEnumerable<string> retiredNames = Chronicle.RetiredNames;
			_deadNames = new HashSet<string>(first.Concat(retiredNames ?? Enumerable.Empty<string>()));
		}
		return _deadNames.Contains(name);
	}

	private void RetireDeadNames()
	{
		List<string> list = Chronicle.RetiredNames ?? (Chronicle.RetiredNames = new List<string>());
		bool flag = false;
		foreach (KeyValuePair<int, Named> item in _named)
		{
			Named value = item.Value;
			if (!value.Story && !string.IsNullOrEmpty(value.Name) && ENTITY.DOES_ENTITY_EXIST(item.Key) && ENTITY.IS_ENTITY_DEAD(item.Key) && !LooksKnockedOut(new Ped(item.Key)) && !list.Contains(value.Name))
			{
				list.Add(value.Name);
				_deadNames?.Add(value.Name);
				flag = true;
				GrudgeLog("NAMING " + value.Name + " died - the name is retired");
			}
		}
		if (flag)
		{
			if (list.Count > 3000)
			{
				list.RemoveRange(0, list.Count - 3000);
			}
			SaveWorld();
		}
	}

	private bool HasNickname(string name, bool gang)
	{
		if (!string.IsNullOrEmpty(name))
		{
			return (uint)Seeds.Stable("nick/" + name) % 100u < (uint)(gang ? Config.NicknameGangPercent : Config.NicknameLonerPercent);
		}
		return false;
	}

	private void ThinNicknames()
	{
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		foreach (NemesisRecord item in Roster)
		{
			if (!string.IsNullOrEmpty(item.Title) && !HasNickname(item.Name, item.Gang != null))
			{
				item.Title = "";
				num++;
			}
		}
		foreach (Acquaintance person in People)
		{
			if (!string.IsNullOrEmpty(person.Title) && !HasNickname(person.Name, Gangs.ForModel(person.Model) != null))
			{
				person.Title = "";
				num2++;
			}
		}
		foreach (Print value in Prints.Values)
		{
			uint result = 0u;
			if (value.Fp != null && value.Fp.Length >= 8)
			{
				uint.TryParse(value.Fp.Substring(0, 8), NumberStyles.HexNumber, null, out result);
			}
			if (!string.IsNullOrEmpty(value.Title) && !HasNickname(value.Name, Gangs.ForModel(result) != null))
			{
				value.Title = "";
				num3++;
			}
		}
		if (num > 0)
		{
			SaveRoster();
		}
		if (num2 > 0)
		{
			_peopleDirty = true;
		}
		if (num3 > 0)
		{
			_printsDirty = true;
			_nextPrintsSave = 0;
		}
		GrudgeLog($"NAMING nicknames thinned to {Config.NicknameGangPercent}% gang / {Config.NicknameLonerPercent}% others: dropped {num} on the roster, {num2} people you know, {num3} looks");
	}

	private static string ModelName(uint model)
	{
		return Models.Name(model);
	}

	private void MoveLaramieModels()
	{
		uint num = 440831189u;
		uint modelHash = 3204687205u;
		int num2 = 0;
		foreach (NemesisRecord item in Roster)
		{
			if (!(item.Gang != Gangs.LaramieGang.Id) && item.ModelHash == num && item.IsAlive && item.TimesAmbushed <= 0 && item.TimesAntagonized <= 0 && item.TimesInterrogated <= 0 && item.TimesKnockedOutByPlayer <= 0 && !item.LastInteraction.HasValue && item.LastCameAt <= 0 && !item.PersonalityKnown)
			{
				item.ModelHash = modelHash;
				item.OutfitHash = 0u;
				num2++;
			}
		}
		if (num2 != 0)
		{
			SaveRoster();
			GrudgeLog($"NAMING {num2} Laramie men moved to the gang's own model (g_m_m_uniranchers_01) - the ones you've faced keep their face");
		}
	}

	private void FixKinSurnames()
	{
		foreach (NemesisRecord r in Roster)
		{
			if (r.KinId == null || r.Name == null || !r.Name.Contains(' '))
			{
				continue;
			}
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord k) => k.Id == r.KinId);
			if (nemesisRecord == null || nemesisRecord.Gang != r.Gang)
			{
				continue;
			}
			Gang gang = Gangs.ById(r.Gang);
			if (gang != null && !gang.FamilyNames)
			{
				continue;
			}
			string text = FamilyNameOf(nemesisRecord);
			string text2 = NameBank.Surname(r.Name);
			bool flag = text.EndsWith(" " + text2);
			bool flag2 = IsLeaderCopy(nemesisRecord) && text2.EndsWith(" " + text);
			if (!(text == text2) && (flag || flag2))
			{
				string name = r.Name;
				string now = r.Name.Split(' ')[0] + " " + text;
				if (!Roster.Any((NemesisRecord n) => n != r && n.Name == now))
				{
					r.Name = now;
					GrudgeLog("NAMING " + name + " -> " + r.Name + " (" + (flag2 ? "the family name" : "the whole family name") + " of his " + (r.KinRelation ?? "kin") + " " + nemesisRecord.Name + ")");
					SaveRoster();
				}
			}
		}
	}

	private void RenameMobOnce()
	{
		int n = 0;
		foreach (WorldEvent item in Chronicle.Events.Concat(Chronicle.Past ?? new List<WorldEvent>()))
		{
			item.Title = R(item.Title);
			item.Place = R(item.Place);
			for (int i = 0; i < item.Lines.Count; i++)
			{
				item.Lines[i] = R(item.Lines[i]);
			}
			foreach (WorldPart person in item.People)
			{
				person.Note = R(person.Note);
				for (int j = 0; j < person.Effects.Count; j++)
				{
					person.Effects[j] = R(person.Effects[j]);
				}
			}
		}
		foreach (NemesisRecord item2 in Roster)
		{
			if (item2.History != null)
			{
				foreach (HistoryEntry item3 in item2.History)
				{
					item3.Text = R(item3.Text);
				}
			}
			if (item2.Past != null)
			{
				foreach (PastEntry item4 in item2.Past)
				{
					item4.Text = R(item4.Text);
				}
			}
			if (item2.Thoughts != null)
			{
				foreach (Thought thought in item2.Thoughts)
				{
					thought.Text = R(thought.Text);
				}
			}
			if (item2.Memories == null)
			{
				continue;
			}
			foreach (Memory memory in item2.Memories)
			{
				memory.Text = R(memory.Text);
			}
		}
		if (n > 0)
		{
			SaveWorld();
			SaveRoster();
			GrudgeLog($"NAMING the Saint Denis Mob is the Bronte Family now - {n} old lines renamed");
		}
		string R(string t)
		{
			if (t != null && t.Contains("Saint Denis Mob"))
			{
				n++;
				return t.Replace("Saint Denis Mob", "Bronte Family");
			}
			return t;
		}
	}

