	private void FixFemaleNames()
	{
		HashSet<string> male = new HashSet<string>(NameBank.AmericanFirst.Concat(NameBank.SouthernFirst).Concat(NameBank.IrishFirst));
		HashSet<string> femaleAll = new HashSet<string>(NameBank.AmericanFemaleFirst.Concat(NameBank.SouthernFemaleFirst).Concat(NameBank.IrishFemaleFirst));
		Dictionary<string, string> map = new Dictionary<string, string>();
		HashSet<string> taken = new HashSet<string>(from x in Roster.Select((NemesisRecord r) => r.Name).Concat(People.Select((Acquaintance a) => a.Name)).Concat(Prints.Values.Select((Print x) => x.Name))
			where x != null
			select x);
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		foreach (NemesisRecord item in Roster)
		{
			string text = Fix(item.Name, ModelName(item.ModelHash), item.ModelHash);
			if (text != item.Name)
			{
				item.Name = text;
				num++;
			}
		}
		foreach (Acquaintance person in People)
		{
			string text2 = Fix(person.Name, ModelName(person.Model), person.Model);
			if (text2 != person.Name)
			{
				person.Name = text2;
				person.Title = (HasNickname(text2, gang: false) ? FemaleTitle() : "");
				num2++;
			}
		}
		foreach (Print value2 in Prints.Values)
		{
			uint result = 0u;
			if (value2.Fp != null && value2.Fp.Length >= 8)
			{
				uint.TryParse(value2.Fp.Substring(0, 8), NumberStyles.HexNumber, null, out result);
			}
			string text3 = Fix(value2.Name, value2.Model, result);
			if (text3 != value2.Name)
			{
				value2.Name = text3;
				value2.Title = (HasNickname(text3, gang: false) ? FemaleTitle() : "");
				num3++;
			}
		}
		if (map.Count == 0)
		{
			return;
		}
		foreach (NemesisRecord item2 in Roster)
		{
			if (item2.History == null)
			{
				continue;
			}
			foreach (HistoryEntry item3 in item2.History)
			{
				if (item3.Text == null)
				{
					continue;
				}
				foreach (KeyValuePair<string, string> item4 in map)
				{
					if (item3.Text.Contains(item4.Key))
					{
						item3.Text = item3.Text.Replace(item4.Key, item4.Value);
					}
				}
			}
		}
		if (_keptNames != null)
		{
			foreach (KeyValuePair<string, string> item5 in map)
			{
				if (_keptNames.Remove(item5.Key))
				{
					_keptNames.Add(item5.Value);
				}
			}
		}
		if (num > 0)
		{
			SaveRoster();
		}
		if (num2 > 0)
		{
			_peopleDirty = true;
		}
		if (num3 > 0)
		{
			_printsDirty = true;
			_nextPrintsSave = 0;
		}
		GrudgeLog($"NAMING female names fixed: {num} on the roster, {num2} people you know, {num3} looks ({map.Count} names)");
		string FemaleTitle()
		{
			return NameBank.FemaleTitles[_rng.Next(NameBank.FemaleTitles.Length)];
		}
		string Fix(string full, string modelName, uint modelHash)
		{
			if (string.IsNullOrEmpty(full) || modelName == null || !modelName.Contains("_f_"))
			{
				return full;
			}
			if (map.TryGetValue(full, out var value))
			{
				return value;
			}
			int num4 = full.IndexOf(' ');
			if (num4 <= 0)
			{
				return full;
			}
			string text4 = full.Substring(0, num4);
			string text5 = full.Substring(num4 + 1);
			if (!male.Contains(text4) || femaleAll.Contains(text4))
			{
				return full;
			}
			string[] array;
			if (Gangs.ForModel(modelHash)?.FirstNames == NameBank.IrishFirst)
			{
				array = NameBank.IrishFemaleFirst;
			}
			else
			{
				array = ((NameBank.SouthernFirst.Contains(text4) && !NameBank.AmericanFirst.Contains(text4)) ? NameBank.SouthernFemaleFirst : NameBank.AmericanFemaleFirst);
			}
			string text6 = null;
			for (int i = 0; i < 30; i++)
			{
				if (text6 != null)
				{
					break;
				}
				string text7 = array[_rng.Next(array.Length)] + " " + text5;
				if (!taken.Contains(text7))
				{
					text6 = text7;
				}
			}
			text6 = text6 ?? (array[_rng.Next(array.Length)] + " " + text5);
			taken.Add(text6);
			map[full] = text6;
			GrudgeLog("NAMING female rename " + full + " -> " + text6 + " (" + modelName + ")");
			return text6;
		}
	}

	internal static bool IsStoryPed(Ped p)
	{
		if (p == null || !p.Exists())
		{
			return false;
		}
		if (!GameNamed(Models.Name(p)))
		{
			return false;
		}
		if (LeaderCopyAt != null)
		{
			return !LeaderCopyAt(p.Handle);
		}
		return true;
	}

	internal static bool GameNamed(string ml)
	{
		if (string.IsNullOrEmpty(ml))
		{
			return false;
		}
		if (ml.StartsWith("cs_"))
		{
			return true;
		}
		if (!ml.StartsWith("u_"))
		{
			return false;
		}
		if (!StoryCast.TryGet(ml, out var _) && TownCast.NameFor(ml) == null)
		{
			return LoreModels.Contains(ml);
		}
		return true;
	}

	private static bool UniqueModel(int ped)
	{
		return Models.Name(ENTITY.GET_ENTITY_MODEL(ped)).StartsWith("u_");
	}

	private void UpdateNaming(Ped player)
	{
		if (!Config.NamingEnabled)
		{
			return;
		}
		UpdateUnease(player);
		Vector3 pos;
		if (Game.GameTime >= _nextNameScan)
		{
			_nextNameScan = Game.GameTime + 1000;
			pos = player.Position;
			List<Ped> list = PedsAround(player);
			int num = 0;
			int num2 = 0;
			foreach (Ped item in list)
			{
				if (item == null || !item.Exists() || item.IsPlayer || !item.IsHuman || item.IsDead || item.Position.DistanceTo(pos) > Config.NamingRadius)
				{
					continue;
				}
				num++;
				if (_named.TryGetValue(item.Handle, out var value))
				{
					value.SeenAt = Game.GameTime;
				}
				else
				{
					if (_worldNemeses.ContainsKey(item.Handle) || (_activeNemesisPed != null && item.Handle == _activeNemesisPed.Handle))
					{
						continue;
					}
					string text = Models.Raw((uint)item.Model.Hash).ToLowerInvariant();
					if (Kids.IsChild(item) && (!text.StartsWith("cs_") || !StoryCast.TryGet(text, out var _)))
					{
						if (!IsStoryPed(item))
						{
							KidFor(item);
						}
						continue;
					}
					if (text.StartsWith("u_") && !GameNamed(text) && _loggedUnique.Add(text))
					{
						GrudgeLog("NAMING unique " + text + ": no name known - named like anyone else");
					}
					if (GameNamed(text))
					{
						string text2 = null;
						string storyTemper = null;
						string storyNote = null;
						if (StoryCast.TryGet(text, out var p2))
						{
							text2 = p2.Name;
							storyTemper = p2.Temper;
							storyNote = p2.Note;
						}
						else if (LoreModels.Contains(text))
						{
							text2 = LoreNameAt(text, item.Position);
							storyNote = "wanted";
						}
						else
						{
							text2 = TownCast.NameFor(text);
							if (text.Contains("_bht_") || text.Contains("bounty"))
							{
								storyNote = "wanted - a bounty";
							}
						}
						if (_loggedUnique.Add(text))
						{
							GrudgeLog("NAMING unique " + text + ": " + (text2 ?? "no name known"));
						}
						if (text2 != null)
						{
							_named[item.Handle] = new Named
							{
								Name = text2,
								Title = "",
								SeenAt = Game.GameTime,
								NamedAt = Game.GameTime,
								Met = true,
								Importance = 3,
								Story = true,
								StoryTemper = storyTemper,
								StoryNote = storyNote
							};
							_namesGiven++;
						}
					}
					else if (num2 < 12 && (!Config.LinkLooks || LookReadable(item)))
					{
						num2++;
						_named[item.Handle] = NameByLook(item);
						_namesGiven++;
					}
				}
			}
			LookSync(player);
			UpdateRoadside(player);
			UpdateWitnessRecognition(player);
			UpdateWitnessReports(player);
			NamingScanNote = $"scan: {list.Count} peds around, {_nearbyCache.Count} from the near list, {num} within {Config.NamingRadius:0} m";
			ForgetKids();
			foreach (KeyValuePair<int, Named> item2 in _named.ToList())
			{
				Named value2 = item2.Value;
				bool flag = !ENTITY.DOES_ENTITY_EXIST(item2.Key) || ENTITY.IS_ENTITY_DEAD(item2.Key);
				if (!flag && ENTITY.DOES_ENTITY_EXIST(item2.Key) && new Ped(item2.Key).Position.DistanceTo(pos) <= 45f)
				{
					value2.SeenAt = Game.GameTime;
				}
				int num3;
				if (value2.Met)
				{
					num3 = 1800000;
				}
				else if (value2.Importance >= 3)
				{
					num3 = 600000;
				}
				else
				{
					num3 = ((value2.Importance >= 1) ? 180000 : 15000);
				}
				if (!flag && value2.Met && ENTITY.IS_ENTITY_A_PED(item2.Key) && new Ped(item2.Key).Position.DistanceTo(pos) < 60f && !value2.Story)
				{
					SetPromptName(item2.Key, value2.Name);
				}
				if (!ENTITY.DOES_ENTITY_EXIST(item2.Key) || (flag && value2.Importance == 0) || Game.GameTime - value2.SeenAt > num3)
				{
					_named.Remove(item2.Key);
					_namesDropped++;
				}
			}
			if (_named.Count > Config.NamingCap)
			{
				foreach (int item3 in (from t in (from kv in _named
						select (Key: kv.Key, Importance: kv.Value.Importance, Met: kv.Value.Met, d: Dist(kv.Key)) into t
						where !t.Met && t.d > 15f
						orderby t.Importance, t.d descending
						select t).Take(_named.Count - Config.NamingCap)
					select t.Key).ToList())
				{
					_named.Remove(item3);
					_namesDropped++;
				}
			}
		}
		if (Game.GameTime >= _nextNemesisNames)
		{
			_nextNemesisNames = Game.GameTime + 1000;
			Vector3 position = player.Position;
			foreach (KeyValuePair<int, NemesisRecord> worldNemese in _worldNemeses)
			{
				if (ENTITY.DOES_ENTITY_EXIST(worldNemese.Key) && ENTITY.IS_ENTITY_A_PED(worldNemese.Key) && !ENTITY.IS_ENTITY_DEAD(worldNemese.Key) && new Ped(worldNemese.Key).Position.DistanceTo(position) < 60f)
				{
					SetPromptName(worldNemese.Key, worldNemese.Value.Name);
				}
			}
			if (_activeNemesisPed != null && _activeNemesisPed.Exists() && ActiveRecord != null)
			{
				SetPromptName(_activeNemesisPed.Handle, ActiveRecord.Name);
			}
		}
		DrawNameplate(player);
		float Dist(int h)
		{
			if (!ENTITY.DOES_ENTITY_EXIST(h))
			{
				return 9999f;
			}
			return new Ped(h).Position.DistanceTo(pos);
		}
	}

	internal static List<Ped> PedsAround(Ped player)
	{
		if (Game.GameTime - _aroundAt < 250)
		{
			return _aroundCache;
		}
		_aroundAt = Game.GameTime;
		HashSet<int> hashSet = new HashSet<int>();
		List<Ped> list = new List<Ped>();
		foreach (Ped item in World.GetAllPeds().Concat(NearbyPeds(player)))
		{
			if (item != null && hashSet.Add(item.Handle))
			{
				list.Add(item);
			}
		}
		_aroundCache = list;
		_snapAt = -100000;
		return list;
	}

	internal static List<(Ped p, Vector3 pos)> PedSnapshot(Ped player)
	{
		List<Ped> list = PedsAround(player);
		if (_snapAt >= 0 && Game.GameTime - _snapAt < 250)
		{
			return _snap;
		}
		_snapAt = Game.GameTime;
		List<(Ped, Vector3)> list2 = new List<(Ped, Vector3)>(list.Count);
		foreach (Ped item in list)
		{
			if (item != null && ENTITY.DOES_ENTITY_EXIST(item.Handle))
			{
				list2.Add((item, ENTITY.GET_ENTITY_COORDS(item.Handle, p1: true, p2: true)));
			}
		}
		_snap = list2;
		return list2;
	}

	private unsafe static List<Ped> NearbyPeds(Ped player)
	{
		if (Game.GameTime - _nearbyAt < 500)
		{
			return _nearbyCache;
		}
		_nearbyAt = Game.GameTime;
		List<Ped> list = new List<Ped>();
		ulong* ptr = stackalloc ulong[129];
		for (int i = 0; i < 129; i++)
		{
			ptr[i] = 0uL;
		}
		*ptr = 48uL;
		Crumbs.Native("Naming nearby peds");
		int num = PED.GET_PED_NEARBY_PEDS(player.Handle, ptr, -1, 0);
		for (int j = 0; j < num && j < 48; j++)
		{
			int num2 = (int)(ptr[j + 1] & 0xFFFFFFFFu);
			if (num2 != 0 && num2 != player.Handle && ENTITY.DOES_ENTITY_EXIST(num2) && ENTITY.IS_ENTITY_A_PED(num2))
			{
				list.Add(new Ped(num2));
			}
		}
		_nearbyCache = list;
		return list;
	}

	private static void SetPromptName(int ped, string name)
	{
		if (!UniqueModel(ped))
