		_settleFrom[ped.Handle] = spot;
		_settling.Add((ped, Game.GameTime + 1500, (allowWander && _rng.Next(100) < 50) ? null : IdleInPlace[_rng.Next(IdleInPlace.Length)], -1f));
		NaturalNote = "using a scenario point";
