	private static float PaperAdHeight(string ad, float w)
	{
		string[] array = (ad ?? "").Split('|');
		int num = Math.Min(4, PaperWrap((array.Length > 1) ? array[1] : "", 0.19f, w - 0.016f, title: false).Count);
		return 0.04f + (float)num * 0.0178f + 0.01f;
	}

	private static void PaperAd(string ad, float x, float y, float w)
	{
		if (!string.IsNullOrEmpty(ad))
		{
			string[] array = ad.Split('|');
			List<string> list = PaperWrap((array.Length > 1) ? array[1] : "", 0.19f, w - 0.016f, title: false);
			int num = Math.Min(4, list.Count);
			float num2 = 0.04f + (float)num * 0.0178f + 0.01f;
			UiDraw.Outline(x + 0.002f, y, w - 0.004f, num2, Ink.r, Ink.g, Ink.b, 255);
			UiDraw.Outline(x + 0.005f, y + 0.005f, w - 0.01f, num2 - 0.01f, Faded.r, Faded.g, Faded.b, 255);
			float num3 = PaperHead(array[0], x + 0.008f, y + 0.01f, w - 0.016f, 0.22f, 1);
			for (int i = 0; i < num; i++)
			{
				float x2 = x + (w - Theme.MixedWidth(list[i], 0.19f, 0.0222f)) / 2f;
				UiDraw.TextFont(list[i], UiDraw.BodyFont, x2, num3 + 0.004f + (float)i * 0.0178f, 0.19f, Ink.r, Ink.g, Ink.b);
			}
		}
	}

	private WarRecord WarNearYou(Vector3 me, float reach = 1800f)
	{
		District here = CurrentDistrict;
		return (from w in Wars
			where w.Result == null && !w.Paused && !TruceBetween(w.A, w.B)
			select (w: w, d: DistrictByKey(w.District)) into t
			where t.d != null && (t.d == here || new Vector3(t.d.X - me.X, t.d.Y - me.Y, 0f).Length() < reach)
			orderby t.d == here descending, new Vector3(t.d.X - me.X, t.d.Y - me.Y, 0f).Length()
			select t.w).FirstOrDefault();
	}

	private void QueueVolley(Vector3 pos, Ped owner, string what)
	{
		if (_rng.Next(100) < 45)
		{
			int num = ((_rng.Next(100) >= 40) ? 1 : 2);
			int num2 = Game.GameTime;
			for (int i = 0; i < num; i++)
			{
				num2 += 1000 + _rng.Next(2001);
				_followBooms.Add((num2, pos, owner, what));
			}
		}
	}

	private void UpdateVolleys(Ped player)
	{
		for (int num = _followBooms.Count - 1; num >= 0; num--)
		{
			(int, Vector3, Ped, string) tuple = _followBooms[num];
			if (Game.GameTime >= tuple.Item1)
			{
				_followBooms.RemoveAt(num);
				if (!MISC.GET_MISSION_FLAG() && !WorldBusy(player))
				{
					double num2 = _rng.NextDouble() * Math.PI * 2.0;
					float num3 = 8f + (float)_rng.NextDouble() * 17f;
					Vector3 vector = Ground(tuple.Item2 + new Vector3((float)Math.Cos(num2) * num3, (float)Math.Sin(num2) * num3, 0f));
					if (!(vector == Vector3.Zero) && !(player.Position.DistanceTo(vector) < 100f) && ModExplosion(vector, 0f, (tuple.Item3 != null && tuple.Item3.Exists() && !tuple.Item3.IsDead) ? tuple.Item3 : null, tuple.Item4 + " (volley)"))
					{
						GrudgeLog($"BOOM volley: another {tuple.Item4} {player.Position.DistanceTo(vector):0} m off");
					}
				}
			}
		}
	}

	private void UpdateNightShelling(Ped player)
	{
		UpdateVolleys(player);
		if (_nightEcho > 0 && Game.GameTime >= _nightEcho)
		{
			_nightEcho = 0;
			if (!MISC.GET_MISSION_FLAG() && !WorldBusy(player))
			{
				NightBlast(player, Ground(_nightEchoNear + new Vector3((float)(_rng.NextDouble() * 30.0 - 15.0), (float)(_rng.NextDouble() * 30.0 - 15.0), 0f)), "the second");
			}
		}
		if (Game.GameTime < _nextNightBlastRoll)
		{
			return;
		}
		_nextNightBlastRoll = Game.GameTime + 20000;
		if (!WarNight || !Config.DistantBattles || Game.GameTime < _nightBlastAllowed || SkirmishDistant || WorldBusy(player) || MISC.GET_MISSION_FLAG() || !MapSettled())
		{
			return;
		}
		WarRecord warRecord = WarNearYou(player.Position);
		if (warRecord == null)
		{
			return;
		}
		InitHeat(warRecord);
		double num = (double)warRecord.Heat * 0.4;
		if (_rng.NextDouble() * 100.0 >= num)
		{
			return;
		}
		Vector3 vector = DistantSpot(player);
		if (!(vector == Vector3.Zero))
		{
			NightBlast(player, vector, $"{WarName(warRecord)}, heat {warRecord.Heat} ({num:0}%)");
			_nightBlastAllowed = Game.GameTime + 25000;
			if (warRecord.Heat >= 60 && _rng.Next(100) < 35)
			{
				_nightEcho = Game.GameTime + 2000 + _rng.Next(4000);
				_nightEchoNear = vector;
			}
		}
	}

	private void NightBlast(Ped player, Vector3 at, string why)
	{
		if (!(player.Position.DistanceTo(at) < 120f) && ModExplosion(at, 0f, null, "night blast"))
		{
			GrudgeLog("WAR night blast " + Away(player.Position, at) + " - " + why);
			if (why != "the second")
			{
				QueueVolley(at, null, "night blast");
			}
		}
	}

	private bool ModExplosion(Vector3 pos, float shake, Ped owner, string what)
	{
		if (owner != null && owner.Exists() && !owner.IsDead)
		{
			Crumbs.Native(what + " (owned)");
			FIRE.ADD_OWNED_EXPLOSION(owner.Handle, pos.X, pos.Y, pos.Z, DistantExplosionTag, 1f, p6: true, p7: false, shake);
		}
		else
		{
			bool flag = false;
			try
			{
				flag = PedsAround(Game.Player.Character).Any((Ped p) => p != null && p.Exists() && !p.IsDead && !p.IsPlayer && p.Position.DistanceTo(pos) < 20f);
			}
			catch
			{
				flag = true;
			}
			if (flag)
			{
				GrudgeLog("BOOM " + what + ": someone within 20 m and no fighter to own it - not set off");
				return false;
			}
			Crumbs.Native(what);
			FIRE.ADD_EXPLOSION(pos.X, pos.Y, pos.Z, DistantExplosionTag, 1f, p5: true, p6: false, shake);
		}
		_modBoomAt = Game.GameTime;
		_modBoomPos = pos;
		return true;
	}

	private Ped BoomOwner(IEnumerable<Ped> men, Vector3 pos)
	{
		return men?.Where((Ped p) => p != null && p.Exists() && !p.IsDead && !p.IsInVehicle).OrderByDescending((Ped p) => p.Position.DistanceTo(pos)).FirstOrDefault();
	}

	private void DebugWarHeat(Ped player, int by)
	{
		WarRecord warRecord = WarNearYou(player.Position, 1E+09f) ?? Wars.FirstOrDefault((WarRecord x) => x.Result == null);
		if (warRecord == null)
		{
			SpawnerSays("no war going on - use 'Start a war here' first.");
			return;
		}
		InitHeat(warRecord);
		int heat = warRecord.Heat;
		warRecord.Heat = Math.Max(0, Math.Min(100, warRecord.Heat + by));
		SaveWorld();
		GrudgeLog($"WAR heat (spawner) {WarName(warRecord)}: {heat} -> {warRecord.Heat}");
		SpawnerSays(string.Format("{0}: heat {1} -> {2}{3}.", WarName(warRecord), heat, warRecord.Heat, warRecord.Paused ? " (a truce has it paused)" : ""));
	}

	private IEnumerable<(Ped p, OurRole role)> OurPeds()
	{
		if (_activeNemesisPed != null)
		{
			yield return (p: _activeNemesisPed, role: OurRole.Active);
		}
		bool missionOn = false;
		try
		{
			missionOn = MISC.GET_MISSION_FLAG();
		}
		catch
		{
		}
		foreach (Ped item in CompanionPeds())
		{
			if (!missionOn || !(item != null) || !IsCompanionReal(item.Handle))
			{
				yield return (p: item, role: OurRole.Companion);
			}
		}
		foreach (Ped follower in _followers)
		{
			yield return (p: follower, role: OurRole.Crew);
		}
		foreach (TownMan townMan in _townMen)
		{
			if (townMan.Ped != null)
			{
				yield return (p: townMan.Ped, role: OurRole.Town);
			}
		}
		foreach (Ped regular in _regulars)
		{
			yield return (p: regular, role: OurRole.Regular);
		}
		foreach (LiveCamp value in _liveCamps.Values)
		{
			foreach (Ped ped in value.Peds)
			{
				yield return (p: ped, role: OurRole.Camp);
			}
		}
		foreach (Raid raid in _raids)
		{
			foreach (Ped man in raid.Men)
			{
				yield return (p: man, role: OurRole.Patrol);
			}
		}
		foreach (Ped checkpointMan in CheckpointMen)
		{
			yield return (p: checkpointMan, role: OurRole.Patrol);
		}
		foreach (Ped supplyWagonMan in SupplyWagonMen)
		{
			yield return (p: supplyWagonMan, role: OurRole.Patrol);
		}
		foreach (Ped item2 in _skirmish)
		{
			yield return (p: item2, role: OurRole.Skirmish);
		}
		foreach (Ped saloonPed in SaloonPeds)
		{
			yield return (p: saloonPed, role: OurRole.Skirmish);
		}
		foreach (Ped survivor in _survivors)
		{
			yield return (p: survivor, role: OurRole.Survivor);
		}
		foreach (Ped hunter in _hunters)
		{
			yield return (p: hunter, role: OurRole.Hunter);
		}
		if (_general != null)
		{
			yield return (p: _general, role: OurRole.General);
		}
		foreach (Ped item3 in _genEscort)
		{
			yield return (p: item3, role: OurRole.General);
		}
		if (_rival != null)
		{
			if (_rival.Ped != null)
			{
				yield return (p: _rival.Ped, role: OurRole.Rival);
			}
			foreach (Ped man2 in _rival.Men)
			{
				yield return (p: man2, role: OurRole.Rival);
			}
		}
		if (_sightingPed != null)
		{
			yield return (p: _sightingPed, role: OurRole.Sighting);
		}
		foreach (Ped aftermathPed in _aftermathPeds)
		{
			yield return (p: aftermathPed, role: OurRole.Aftermath);
		}
	}

	internal OurRole RoleOf(int handle)
	{
		if (_roleFrame != Game.FrameCount)
		{
			_roleFrame = Game.FrameCount;
			_roleOf.Clear();
			foreach (var (ped, value) in OurPeds())
			{
				if (ped != null && !_roleOf.ContainsKey(ped.Handle))
				{
					_roleOf[ped.Handle] = value;
				}
			}
			foreach (int key in _followerOf.Keys)
			{
				if (!_roleOf.ContainsKey(key))
				{
					_roleOf[key] = OurRole.HiredGun;
				}
			}
			foreach (int key2 in _worldNemeses.Keys)
			{
				if (!_roleOf.ContainsKey(key2))
				{
					_roleOf[key2] = OurRole.WorldNemesis;
				}
			}
		}
		if (!_roleOf.TryGetValue(handle, out var value2))
		{
			return OurRole.None;
		}
		return value2;
	}

	internal bool IsOurs(int handle)
	{
		return RoleOf(handle) != OurRole.None;
	}

	internal bool OutfitFighter(int handle)
	{
		OurRole ourRole = RoleOf(handle);
		if (ourRole != OurRole.Patrol && ourRole != OurRole.Camp && ourRole != OurRole.Skirmish && ourRole != OurRole.Survivor && ourRole != OurRole.Aftermath && ourRole != OurRole.HiredGun)
		{
			return ourRole == OurRole.Hunter;
		}
		return true;
	}

	internal unsafe void DeleteOrRelease(Ped p)
	{
		if (!(p == null) && p.Exists())
		{
			if (SafeToDelete(p))
			{
				p.Delete();
				return;
			}
			int handle = p.Handle;
			ReleaseIfOurs(&handle);
		}
	}

	internal static void MakeOurs(int h)
	{
		if (h != 0 && ENTITY.DOES_ENTITY_EXIST(h))
		{
			ENTITY.SET_ENTITY_AS_MISSION_ENTITY(h, p1: true, p2: true);
			_ownSpawned[h] = ENTITY.GET_ENTITY_MODEL(h);
