	internal static Ped SpawnPed(PedHash model, Vector3 pos, float heading)
	{
		bool flag = false;
		if (!STREAMING.HAS_MODEL_LOADED((uint)model))
		{
			Model m = new Model((int)model);
			if (!m.IsValid || !m.IsPed)
			{
				return null;
			}
			RequestModel(m, 1500);
			flag = true;
			if (!m.IsLoaded)
			{
				return null;
			}
			if (MISC.GET_MISSION_FLAG() || CAM.IS_SCREEN_FADED_OUT() || CAM.IS_SCREEN_FADING_OUT())
			{
				STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)model);
				return null;
			}
		}
		Ped ped = World.CreatePed(model, pos, heading);
		if (flag)
		{
			STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)model);
		}
		if (ped != null && ped.Exists())
		{
			_ownSpawned[ped.Handle] = (uint)ped.Model.Hash;
			Land(ped, pos);
			try
			{
				GiveVoiceHook?.Invoke(ped);
			}
			catch
			{
			}
			VaryOutfit(ped);
		}
		return ped;
	}

	private static void VaryOutfit(Ped p)
	{
		try
		{
			uint m = (uint)p.Model.Hash;
			if (!_varyModel.TryGetValue(m, out var value))
			{
				value = (_varyModel[m] = Gangs.All.Any((Gang g) => g.TroopModels != null && g.TroopModels.Length == 1 && g.TroopModels[0] == (PedHash)m));
			}
			if (value)
			{
				int num = PED.GET_NUM_META_PED_OUTFITS(p.Handle);
				if (num > 1)
				{
					PED._EQUIP_META_PED_OUTFIT_PRESET(p.Handle, _outfitRng.Next(num), p2: false);
					Function.Call(14739335899491263887uL, p.Handle, false, true, true, true, false);
				}
			}
		}
		catch
		{
		}
	}

	private static void Land(Ped p, Vector3 at)
	{
		STREAMING.REQUEST_COLLISION_AT_COORD(at.X, at.Y, at.Z);
		if (p.IsHuman)
		{
			Landing landing = new Landing
			{
				P = p,
				At = at,
				Born = Game.GameTime,
				FreedAt = Game.GameTime
			};
			if (!ENTITY.HAS_COLLISION_LOADED_AROUND_ENTITY(p.Handle))
			{
				ENTITY.FREEZE_ENTITY_POSITION(p.Handle, p1: true);
				landing.Frozen = true;
			}
			_landing.Add(landing);
		}
	}

	internal static void ClearLanding()
	{
		foreach (Landing item in _landing)
		{
			try
			{
				if (item.Frozen && item.P != null && item.P.Exists())
				{
					ENTITY.FREEZE_ENTITY_POSITION(item.P.Handle, p1: false);
				}
			}
			catch
			{
			}
		}
		_landing.Clear();
	}

	internal static void TickLanding()
	{
		for (int num = _landing.Count - 1; num >= 0; num--)
		{
			Landing landing = _landing[num];
			if (landing.P == null || !landing.P.Exists() || landing.P.IsDead)
			{
				_landing.RemoveAt(num);
			}
			else
			{
				int handle = landing.P.Handle;
				if (landing.Frozen)
				{
					bool flag = ENTITY.HAS_COLLISION_LOADED_AROUND_ENTITY(handle);
					int num2 = INTERIOR.GET_INTERIOR_AT_COORDS(landing.At.X, landing.At.Y, landing.At.Z);
					if (num2 != 0 && !INTERIOR.IS_INTERIOR_READY(num2))
					{
						flag = false;
					}
					if (!flag)
					{
						STREAMING.REQUEST_COLLISION_AT_COORD(landing.At.X, landing.At.Y, landing.At.Z);
					}
					if (flag || landing.P.IsOnMount || PED.IS_PED_IN_ANY_VEHICLE(handle, p1: false) || Game.GameTime - landing.Born > 30000)
					{
						ENTITY.FREEZE_ENTITY_POSITION(handle, p1: false);
						landing.Frozen = false;
						landing.FreedAt = Game.GameTime;
						if (!flag)
						{
							LandingLog?.Invoke($"LANDING ped {handle}: no ground loaded at {landing.At.X:0},{landing.At.Y:0} after 30 s - let go anyway");
						}
					}
				}
				else if (Game.GameTime - landing.FreedAt > 15000)
				{
					_landing.RemoveAt(num);
				}
				else if (!landing.P.IsOnMount && !PED.IS_PED_IN_ANY_VEHICLE(handle, p1: false) && !ENTITY.IS_ENTITY_ATTACHED(handle))
				{
					Vector3 position = landing.P.Position;
					if (!(ENTITY.GET_ENTITY_VELOCITY(handle, 0).Z > -7f) && !(position.Z > landing.At.Z - 4f) && landing.Saves < 2)
					{
						landing.Saves++;
						Vector3 safeCoordForPed = World.GetSafeCoordForPed(landing.At);
						Vector3 at = (((safeCoordForPed.X != 0f || safeCoordForPed.Y != 0f) && new Vector3(safeCoordForPed.X - landing.At.X, safeCoordForPed.Y - landing.At.Y, 0f).Length() < 15f) ? safeCoordForPed : landing.At);
						ENTITY.SET_ENTITY_COORDS(handle, at.X, at.Y, at.Z + 0.3f, p4: false, p5: false, p6: false, p7: false);
						ENTITY.SET_ENTITY_VELOCITY(handle, 0f, 0f, 0f);
						STREAMING.REQUEST_COLLISION_AT_COORD(at.X, at.Y, at.Z);
						ENTITY.FREEZE_ENTITY_POSITION(handle, p1: true);
						landing.Frozen = true;
						landing.At = at;
						LandingLog?.Invoke($"LANDING ped {handle} ({Models.Name((uint)landing.P.Model.Hash)}): fell through the ground at {position.X:0},{position.Y:0},{position.Z:0} - put back at {at.X:0},{at.Y:0},{at.Z:0}");
					}
				}
			}
		}
	}

	internal static Vehicle SpawnVehicle(VehicleHash model, Vector3 pos, float heading)
	{
		Stopwatch stopwatch = (STREAMING.HAS_MODEL_LOADED((uint)model) ? null : Stopwatch.StartNew());
		Vehicle vehicle = World.CreateVehicle(model, pos, heading);
		if (stopwatch != null)
		{
			ModelWaitMs += stopwatch.Elapsed.TotalMilliseconds;
		}
		if (vehicle != null && vehicle.Exists())
		{
			_ownSpawned[vehicle.Handle] = (uint)vehicle.Model.Hash;
		}
		return vehicle;
	}

	private static bool Registered(int h)
	{
		if (_ownSpawned.TryGetValue(h, out var value))
		{
			return value == ENTITY.GET_ENTITY_MODEL(h);
		}
		return false;
	}

	internal static void PruneOwn()
	{
		_ownGone.Clear();
		foreach (int key in _ownSpawned.Keys)
		{
			if (!ENTITY.DOES_ENTITY_EXIST(key))
			{
				_ownGone.Add(key);
			}
		}
		foreach (int item in _ownGone)
		{
			_ownSpawned.Remove(item);
		}
	}

	internal static bool BelongsToUs(int h)
	{
		if (h == 0 || !ENTITY.DOES_ENTITY_EXIST(h))
		{
			return false;
		}
		if (!ENTITY.IS_ENTITY_A_MISSION_ENTITY(h))
		{
			return false;
		}
		if (OwnCheckState > 0)
		{
			try
			{
				return Function.Call<bool>(7073775680682537778uL, new InputArgument[2] { h, false });
			}
			catch
			{
			}
		}
		return Registered(h);
	}

	internal unsafe static void ReleaseIfOurs(int* h)
	{
		if (h == null || *h == 0 || !ENTITY.DOES_ENTITY_EXIST(*h) || !BelongsToUs(*h))
		{
			return;
		}
		int num = *h;
		Crumbs.Native("Ours release entity");
		ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(h);
		_ownSpawned.Remove(num);
		if (WasOurs.Count > 4000)
		{
			WasOurs.Clear();
		}
		WasOurs.Add(num);
		if (ENTITY.IS_ENTITY_A_PED(num) && !ENTITY.IS_ENTITY_DEAD(num))
		{
			if (ReleasedAt.Count > 300)
			{
				ReleasedAt.Clear();
			}
			ReleasedAt[num] = Game.GameTime;
		}
	}

	private void CalibrateOwnCheck()
	{
		if (OwnCheckState != 0)
		{
			return;
		}
		foreach (var (ped, ourRole) in OurPeds())
		{
			if (!(ped == null) && ped.Exists() && ourRole != OurRole.Companion && ENTITY.IS_ENTITY_A_MISSION_ENTITY(ped.Handle) && Registered(ped.Handle))
			{
				bool flag;
				try
				{
					flag = Function.Call<bool>(7073775680682537778uL, new InputArgument[2] { ped.Handle, false });
				}
				catch
				{
					flag = false;
				}
				if (flag)
				{
					_ownYes++;
				}
				else
				{
					_ownNo++;
				}
				if (_ownYes > 0)
				{
					OwnCheckState = 1;
					GrudgeLog($"ENTITY ownership check works ({_ownYes} of ours read as ours, {_ownNo} not)");
					break;
				}
				if (_ownNo >= 6)
				{
					OwnCheckState = -1;
					GrudgeLog("ENTITY ownership check reads FALSE for our own peds - using the mod's own spawn registry instead");
					break;
				}
			}
		}
	}

	internal bool XRayHandsOff(int h)
	{
		if (MISC.GET_MISSION_FLAG())
		{
			return true;
		}
		if (IsCompanion(h) || IsCompanionReal(h))
		{
			return true;
		}
		Ped ped = Entity.FromHandle(h) as Ped;
		if (ped == null || !ped.Exists())
		{
			return true;
		}
		if (!IsStoryPed(ped))
		{
			return GameOwned(ped);
		}
		return true;
	}

	internal string XRayAnimalHandsOff(int h)
	{
		if (XRayHandsOff(h))
		{
			return "a mission's";
		}
		int handle = Game.Player.Character.Handle;
		if (h == PED.GET_MOUNT(handle) || h == PED._GET_LAST_MOUNT(handle) || h == PLAYER._GET_SADDLE_HORSE_FOR_PLAYER(Game.Player.Handle))
		{
			return "your horse";
		}
		Ped ped = Entity.FromHandle(h) as Ped;
		if (ped == null || !ped.Exists())
		{
			return "gone";
		}
		string text = Models.Name(ped);
		if (text.Contains("legendary"))
		{
			return "a legendary animal";
		}
		string text2 = null;
		try
		{
			text2 = ScriptOf(h);
		}
		catch
		{
		}
		if (text2 != null && text2.IndexOf("legend", StringComparison.OrdinalIgnoreCase) >= 0)
		{
			return "a legendary animal";
		}
		if (text2 != null && _animalScriptSaid.Add(h))
		{
			GrudgeLog($"XRAY animal {text} (ped {h}) belongs to the game script '{text2}' - its X-ray verdict comes true all the same");
		}
		return null;
	}

	internal bool GameOwned(Ped p)
	{
		if (p == null || !p.Exists())
		{
			return false;
		}
		int handle = p.Handle;
		if (IsOurs(handle))
		{
			return false;
		}
		string text = Models.Name(p);
		if (text.StartsWith("msp_") || text.StartsWith("mes_") || text.StartsWith("rcsp_") || text.StartsWith("rces_"))
		{
			return true;
		}
		if (!MISC.GET_MISSION_FLAG() && !InStoryScene(p.Position))
		{
			return false;
		}
		if (ENTITY.IS_ENTITY_A_MISSION_ENTITY(handle))
		{
			return !BelongsToUs(handle);
		}
		return false;
	}

	internal bool MissionHeld(Ped p)
	{
		if (p == null || !p.Exists() || IsOurs(p.Handle) || !MISC.GET_MISSION_FLAG())
		{
			return false;
		}
		if (ENTITY.IS_ENTITY_A_MISSION_ENTITY(p.Handle))
		{
			return !BelongsToUs(p.Handle);
		}
		return false;
	}

	internal bool MissionMemoryOk(Ped p)
	{
		if (!MissionHeld(p) || IsStoryPed(p) || GameEventPed(p))
		{
			return false;
		}
		string text = Models.Name(p);
		if (text.StartsWith("msp_") || text.StartsWith("mes_") || text.StartsWith("rcsp_") || text.StartsWith("rces_"))
		{
			return false;
		}
		return Gangs.ForModel((uint)p.Model.Hash) != null;
	}

	internal static bool RallyModel(uint m)
	{
		return Models.Name(m).StartsWith("re_rally");
	}

	internal static bool RallyManFree(Ped p)
	{
		if (p != null && p.Exists() && RallyModel((uint)p.Model.Hash))
		{
			return !ENTITY.IS_ENTITY_A_MISSION_ENTITY(p.Handle);
		}
		return false;
	}

	internal static bool GameEventPed(Ped p)
	{
		if (p != null && p.Exists() && Models.Name(p).StartsWith("re_"))
		{
			return !Registered(p.Handle);
		}
		return false;
	}

	internal static bool RequestModel(Model m, int ms)
	{
		Stopwatch stopwatch = Stopwatch.StartNew();
		try
		{
			return m.Request(ms);
		}
		finally
		{
			ModelWaitMs += stopwatch.Elapsed.TotalMilliseconds;
		}
	}

	internal bool LoadModelSafe(Model m, int ms)
	{
		if (!m.IsValid)
		{
			return false;
		}
		if (!m.IsLoaded)
		{
			RequestModel(m, ms);
		}
		if (!m.IsLoaded)
		{
			return false;
		}
		_nextBusyCheck = 0;
		Ped character = Game.Player.Character;
		if (character == null || !character.Exists() || WorldBusy(character) || MISC.GET_MISSION_FLAG())
		{
			GrudgeLog($"SPAWN skipped - the world went busy while model 0x{(uint)m.Hash:X8} loaded");
			return false;
		}
		return true;
	}

	internal bool IsOurs(Ped p)
	{
		if (p != null)
		{
			return RoleOf(p.Handle) != OurRole.None;
		}
		return false;
	}

	internal bool IsPlaced(int handle)
	{
		OurRole ourRole = RoleOf(handle);
		if (ourRole != OurRole.None)
		{
			return ourRole != OurRole.Regular;
		}
		return false;
	}

	private void EnsureGameOutlawGroups()
	{
		if (_gameOutlawGroups == null)
		{
			_gameOutlawGroups = new Dictionary<uint, string>();
			string[] gameOutlawGroupNames = GameOutlawGroupNames;
			foreach (string text in gameOutlawGroupNames)
			{
				_gameOutlawGroups[MISC.GET_HASH_KEY(text)] = text;
			}
			_relCriminals = MISC.GET_HASH_KEY("rel_criminals");
		}
	}

	private static string RelName(int r)
	{
		return r switch
		{
			7 => "dead", 
			6 => "hate", 
			5 => "wanted", 
			4 => "dislike", 
			3 => "ignore", 
			2 => "like", 
			1 => "respect", 
			0 => "none", 
			_ => r.ToString(), 
		};
	}

	private static int RelBetween(uint a, uint b)
	{
		try
		{
			return Function.Call<int>(11415340851948334684uL, new InputArgument[2] { a, b });
		}
		catch
		{
			return -1;
		}
	}

	private string GroupName(uint g)
	{
		if (_gameOutlawGroups == null || !_gameOutlawGroups.TryGetValue(g, out var value))
		{
			return $"0x{g:X8}";
		}
		return value;
	}

	internal void ForgetSwitch(int h)
	{
		_outlawSwitched.Remove(h);
	}

	internal uint ModGroupOf(int h)
	{
		uint num = PED.GET_PED_RELATIONSHIP_GROUP_HASH(h);
		if (!_outlawSwitched.TryGetValue(h, out (uint, uint, int) value) || value.Item1 == 0 || num != value.Item2)
		{
			return num;
		}
		return value.Item1;
	}

	internal bool OutlawMan(int h)
	{
		if (!ENTITY.DOES_ENTITY_EXIST(h) || (RoleOf(h) == OurRole.None && RecordAt(h) == null && !Registered(h) && BandOf(h) == null) || RoleOf(h) == OurRole.Companion)
		{
			return false;
		}
		return FairOutfit(Gangs.ById(RecordAt(h)?.Gang) ?? Gangs.ForModel(ENTITY.GET_ENTITY_MODEL(h)));
	}

	private bool DrewOnYouNow(int h)
	{
		if (!_combatants.TryGetValue(h, out var value) || Game.GameTime - value > 3000)
		{
			return false;
		}
		OurRole ourRole = RoleOf(h);
		if (ourRole == OurRole.Companion || (ourRole == OurRole.None && RecordAt(h) == null && !_provoked.ContainsKey(h)))
		{
			return false;
		}
		if ((Gangs.ById(RecordAt(h)?.Gang) ?? Gangs.ForModel(ENTITY.GET_ENTITY_MODEL(h))) != null)
		{
			return false;
		}
		if (IsLawman(new Ped(h)) || XRayHandsOff(h) || !CameAtYou(h))
		{
			return false;
		}
		if (!DrewOnYou(h))
		{
			return false;
		}
		_drewOnYouAt[h] = Game.GameTime;
		return true;
	}

	private uint GameGroupOf(int h, Gang g)
	{
		EnsureGameOutlawGroups();
		uint num = 0u;
		try
		{
			num = PED.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH(h);
		}
		catch
		{
		}
		bool flag = _gameOutlawGroups.ContainsKey(num);
		uint result = (flag ? num : _relCriminals);
		if (_lawGroupSaid.Add(g.Id))
		{
			GrudgeLog("LAWGROUP " + g.Name + ": yours to kill, their men go in the game's " + (flag ? (GroupName(num) + " (their model's own)") : $"rel_criminals (their model's own, 0x{num:X8}, isn't one of the game's outlaw groups)"));
		}
		return result;
	}

	private IEnumerable<uint> ModGroups()
	{
		uint[] array = new uint[14]
		{
			_nemesisGroup, _campGroup, _checkpointGroup, _beatenGroup, _surrenderGroup, _rivalGroup, _saloonGrpA, _saloonGrpB, _survivorGroup, _townRelGroup,
			_townFightGroup, _huntersGroup, _generalGroup, _lawTestHateGroup
		};
		foreach (uint num in array)
		{
			if (num != 0)
			{
				yield return num;
			}
		}
		if (_sideA != 0)
		{
			yield return _sideA;
		}
		if (_sideB != 0)
		{
			yield return _sideB;
		}
		foreach (uint value in _factionCampGroups.Values)
		{
			if (value != 0)
			{
				yield return value;
			}
		}
		foreach (uint value2 in _patrolGroups.Values)
		{
			if (value2 != 0)
			{
				yield return value2;
			}
		}
	}

	private void CarryHostility(uint mod, uint game)
	{
		if (mod == 0 || mod == game)
		{
			return;
		}
		bool flag = _outlawSwitched.Values.Any(((uint mod, uint game, int last) s) => s.game == game && s.mod != 0 && s.mod != mod);
		if (!flag)
		{
			World.SetRelationshipBetweenGroups((eRelationshipType)1, game, mod);
			World.SetRelationshipBetweenGroups((eRelationshipType)1, mod, game);
		}
		foreach (uint item in ModGroups().Distinct())
		{
			if (item != mod && item != game)
			{
				int num = RelBetween(mod, item);
				int num2 = RelBetween(item, mod);
				bool flag2 = num == 4 || num == 6;
				bool flag3 = num2 == 4 || num2 == 6;
				if (!flag | flag2)
				{
					World.SetRelationshipBetweenGroups((num >= 1 && num <= 6) ? ((eRelationshipType)num) : ((eRelationshipType)3), game, item);
				}
				if (!flag | flag3)
				{
					World.SetRelationshipBetweenGroups((num2 >= 1 && num2 <= 6) ? ((eRelationshipType)num2) : ((eRelationshipType)3), item, game);
				}
			}
		}
	}

	private void SwitchOutlaw(int h, string why, int now)
	{
		if (h == 0 || !ENTITY.DOES_ENTITY_EXIST(h) || !ENTITY.IS_ENTITY_A_PED(h) || !PED.IS_PED_HUMAN(h))
		{
			return;
		}
		Ped ped = new Ped(h);
		if (ped.IsDead && !LooksKnockedOut(ped))
		{
			return;
		}
		bool flag = OutlawMan(h);
		if (!flag && !DrewOnYouNow(h))
		{
			return;
		}
		Gang g = (flag ? (Gangs.ById(RecordAt(h)?.Gang) ?? Gangs.ForModel((uint)ped.Model.Hash)) : null);
		uint num = PED.GET_PED_RELATIONSHIP_GROUP_HASH(h);
		bool flag2 = _outlawSwitched.TryGetValue(h, out (uint, uint, int) value);
		EnsureGameOutlawGroups();
		uint num2;
		if (flag2)
		{
			num2 = value.Item2;
		}
		else
		{
			num2 = (flag ? GameGroupOf(h, g) : _relCriminals);
		}
		uint num3 = (flag2 ? value.Item1 : 0u);
		if (num != num2)
		{
			num3 = num;
			CarryHostility(num3, num2);
			PED.SET_PED_RELATIONSHIP_GROUP_HASH(h, num2);
			if (!flag2 && _outlawSwitchLogs++ < 60)
			{
				GrudgeLog("LAWGROUP " + AttackerLabel(h) + " (" + (flag ? ShortOutfit(g) : "no outfit") + ") into the game's " + GroupName(num2) + " - " + (flag ? why : "he drew on you"));
			}
		}
		_outlawSwitched[h] = (num3, num2, now);
	}

	private void ProbeGameOutlawGroups(Ped player)
	{
		if (!_lawGroupsProbed)
		{
			_lawGroupsProbed = true;
			EnsureGameOutlawGroups();
			uint me = PED.GET_PED_RELATIONSHIP_GROUP_HASH(player.Handle);
			GrudgeLog("LAWGROUP the game's outlaw groups toward you: " + string.Join(", ", _gameOutlawGroups.Select((KeyValuePair<uint, string> kv) => kv.Value + " " + RelName(RelBetween(kv.Key, me)))));
		}
	}

	private unsafe void UpdateOutlawGroups(Ped player)
	{
		if (MISC.GET_MISSION_FLAG())
		{
			return;
		}
		int now = Game.GameTime;
		int handle = Game.Player.Handle;
		int num = 0;
		if (PLAYER.GET_ENTITY_PLAYER_IS_FREE_AIMING_AT(handle, &num) && num != 0 && ENTITY.IS_ENTITY_A_PED(num))
		{
			_inSightsAt[num] = now;
		}
		num = 0;
		if (PLAYER.GET_PLAYER_TARGET_ENTITY(handle, &num) && num != 0 && ENTITY.IS_ENTITY_A_PED(num))
		{
			_inSightsAt[num] = now;
		}
		num = 0;
		if (PLAYER.GET_PLAYER_INTERACTION_TARGET_ENTITY(handle, &num, p2: false, p3: false) && num != 0 && ENTITY.IS_ENTITY_A_PED(num))
		{
			_inSightsAt[num] = now;
		}
		if (_inSightsAt.Count > 0 && AttackInputs.Any(Game.IsControlPressed))
		{
			int num2 = 1000;
			try
			{
				if (Function.Call<bool>(12781818049324475888uL, new InputArgument[1] { handle }))
				{
					num2 = 6000;
				}
			}
			catch
			{
			}
			foreach (KeyValuePair<int, int> item in _inSightsAt.ToList())
			{
				if (now - item.Value < num2)
				{
					SwitchOutlaw(item.Key, "you went for him", now);
				}
			}
		}
		if (Game.GameTime < _nextOutlawGroups)
		{
			return;
		}
		_nextOutlawGroups = Game.GameTime + 250;
		ProbeGameOutlawGroups(player);
		if (_inSightsAt.Count > 32)
		{
			foreach (int item2 in (from kv in _inSightsAt
				where now - kv.Value > 6000
				select kv.Key).ToList())
			{
				_inSightsAt.Remove(item2);
			}
		}
		Dictionary<int, string> why = new Dictionary<int, string>();
		foreach (KeyValuePair<int, int> combatant in _combatants)
		{
			if (now - combatant.Value < 3000)
			{
				Add(combatant.Key, "he's fighting you");
			}
		}
		foreach (KeyValuePair<int, int> item3 in _hitByYouAt)
		{
			if (now - item3.Value < 10000)
			{
				Add(item3.Key, "you hurt him");
			}
		}
		foreach (KeyValuePair<int, Fighter> fighter in _fighters)
		{
			if (fighter.Value != null && fighter.Value.Broke && !fighter.Value.Done)
			{
				Add(fighter.Key, "he gave up");
			}
		}
		if (_interro?.Ped != null)
		{
			Add(_interro.Ped.Handle, "you're questioning him");
		}
		Vector3 position = player.Position;
		foreach (var (ped, vector) in PedSnapshot(player))
		{
			if (ped == null || vector.DistanceTo(position) > 40f || why.ContainsKey(ped.Handle) || (RoleOf(ped.Handle) == OurRole.None && RecordAt(ped.Handle) == null && !Registered(ped.Handle) && BandOf(ped.Handle) == null))
			{
				continue;
			}
			if (ped.IsHogtied || TASK.IS_PED_IN_WRITHE(ped.Handle) || (ped.IsDead && LooksKnockedOut(ped)))
			{
				Add(ped.Handle, "he's down");
			}
			else
			{
				if (ped.IsDead || !PED.IS_PED_IN_COMBAT(ped.Handle, player.Handle) || !OutlawMan(ped.Handle))
				{
					continue;
				}
				Add(ped.Handle, "he's squaring up to you");
				Gang g = Gangs.ById(RecordAt(ped.Handle)?.Gang) ?? Gangs.ForModel((uint)ped.Model.Hash);
				if (FairOutfit(g))
				{
					try
					{
						FairNow(g, AttackerLabel(ped.Handle));
					}
					catch
					{
					}
				}
			}
		}
		foreach (KeyValuePair<int, string> item4 in why)
		{
			SwitchOutlaw(item4.Key, item4.Value, now);
		}
		foreach (int item5 in _outlawSwitched.Keys.ToList())
		{
			if (why.ContainsKey(item5))
			{
				continue;
			}
			(uint, uint, int) tuple2 = _outlawSwitched[item5];
			if (!ENTITY.DOES_ENTITY_EXIST(item5))
			{
				_outlawSwitched.Remove(item5);
			}
			else if (!ENTITY.IS_ENTITY_DEAD(item5) && now - tuple2.Item3 >= 8000)
			{
				if (PED.GET_PED_RELATIONSHIP_GROUP_HASH(item5) == tuple2.Item2 && tuple2.Item1 != 0)
				{
					PED.SET_PED_RELATIONSHIP_GROUP_HASH(item5, tuple2.Item1);
				}
				_outlawSwitched.Remove(item5);
				if (_outlawSwitchLogs++ < 60)
				{
					GrudgeLog($"LAWGROUP {AttackerLabel(item5)} back in the mod's group (nothing for {8} s)");
				}
			}
		}
		void Add(int h, string w)
