			if (h != 0 && !why.ContainsKey(h))
			{
				why[h] = w;
			}
		}
	}

	private int NextRetarget(int h)
	{
		if (!_retargetAt.TryGetValue(h, out var value))
		{
			return 0;
		}
		return value;
