	private unsafe void EndRaid(Raid r)
	{
		_scenes.Remove(r);
		_nextSideCheck.Remove(r);
		try
		{
			ChronicleRaid(r);
		}
		catch (Exception ex)
		{
			GrudgeLog("WORLD raid chronicle failed: " + ex.Message);
		}
		if (r.Dot != null && r.Dot.Exists())
		{
			r.Dot.Delete();
		}
		foreach (Ped man in r.Men)
		{
			if (!(man == null) && man.Exists())
			{
				int handle = man.Handle;
				if (!man.IsDead && SafeToDelete(man) && man.Position.DistanceTo(Game.Player.Character.Position) > 200f)
				{
					_worldNemeses.Remove(handle);
					man.Delete();
				}
				else
				{
					ReleaseIfOurs(&handle);
				}
			}
		}
		foreach (Ped horse in r.Horses)
		{
			if (!(horse == null) && horse.Exists())
			{
				int handle2 = horse.Handle;
				ReleaseIfOurs(&handle2);
			}
		}
		_raids.Remove(r);
		GrudgeLog("PATROL " + r.Gang?.Id + " " + (r.CampId ?? "on the road") + " over");
	}

	private bool UpdatePatrolScene(Raid r, Ped lead, Ped player)
	{
		_scenes.TryGetValue(r, out var value);
		bool flag = r.Hostile || AfterYou(r.Gang);
		if (value != null && (flag || r.AlertAt != value.AlertSeen || lead == null))
		{
			foreach (var value5 in value.Lookers.Values)
			{
				if (value5.man.Exists() && !value5.man.IsDead && !PED.IS_PED_IN_COMBAT(value5.man.Handle, 0))
				{
					TASK.CLEAR_PED_TASKS(value5.man.Handle, p1: false, p2: false);
				}
			}
			_scenes.Remove(r);
			GrudgeLog("PATROL " + r.Gang.Id + ": done looking the scene over - " + (flag ? "it turned ugly" : "more shooting"));
			return false;
		}
		if (value == null)
		{
			if (((r.RidingOff || r.Watch) | flag) || lead == null)
			{
				return false;
			}
			if ((r.CampId != null || r.Responding || r.AlertAt <= r.SpawnedAt || !(lead.Position.DistanceTo(r.Alert) < 80f) || (r.QuietFrom == 0 && !r.SidedWithYou)) && (!r.Arrived || (r.CampId == null && !r.Responding)))
			{
				return false;
			}
			if (r.CampId != null && r.QuietFrom == 0 && Game.GameTime - r.ArrivedAt < 60000)
			{
				return false;
			}
			if (r.Men.Any((Ped m) => m.Exists() && !m.IsDead && PED.IS_PED_IN_COMBAT(m.Handle, 0)))
			{
				r.QuietFrom = Game.GameTime;
				return false;
			}
			if (Game.GameTime - Math.Max(r.AlertAt, r.QuietFrom) < 15000 || Game.GameTime < r.WatchYouUntil)
			{
				return false;
			}
			value = StartPatrolScene(r, lead, player, _rng.Next(100) < 30);
			_scenes[r] = value;
		}
		bool calm = Game.GameTime - r.AlertAt > 10000 && Game.GameTime >= r.WatchYouUntil;
		foreach (Ped item in r.Men.Where((Ped m) => m.Exists() && !m.IsDead))
		{
			PatrolTalkable(r, item, player, calm);
		}
		if (value.MountAt == 0 && Game.GameTime >= value.EndsAt)
		{
			value.MountAt = Game.GameTime;
			foreach (Ped item2 in r.Men.Where((Ped m) => m.Exists() && !m.IsDead && !m.IsOnMount))
			{
				TASK.CLEAR_PED_TASKS(item2.Handle, p1: false, p2: false);
				if (r.HorseOf.TryGetValue(item2.Handle, out var value2) && value2 != null && value2.Exists() && !value2.IsDead)
				{
					TASK.TASK_MOUNT_ANIMAL(item2.Handle, value2.Handle, 20000, -1, 1f, 1, 0uL, 0uL);
				}
			}
			GrudgeLog("PATROL " + r.Gang.Id + ": done looking the scene over - mounting up");
			return true;
		}
		if (value.MountAt != 0)
		{
			bool flag2 = !r.Mounted || r.Men.All((Ped m) => !m.Exists() || m.IsDead || m.IsOnMount);
			if (!flag2)
			{
				long num = Game.GameTime - value.MountAt;
				bool flag3 = Game.GameTime >= value.RemountAt;
				if (flag3)
				{
					value.RemountAt = Game.GameTime + 4000;
				}
				foreach (Ped item3 in r.Men.Where((Ped m) => m.Exists() && !m.IsDead && !m.IsOnMount))
				{
					if (r.HorseOf.TryGetValue(item3.Handle, out var value3) && !(value3 == null) && value3.Exists() && !value3.IsDead)
					{
						if (num > 25000 || (num > 12000 && HiddenFromView(player, item3.Position)))
						{
							Crumbs.Native("Patrols onto mount");
							PED.SET_PED_ONTO_MOUNT(item3.Handle, value3.Handle, -1, p3: true);
						}
						else if (flag3 && item3.Position.DistanceTo(value3.Position) > 2.5f)
						{
							TASK.TASK_MOUNT_ANIMAL(item3.Handle, value3.Handle, 20000, -1, 1f, 1, 0uL, 0uL);
						}
					}
				}
				flag2 = r.Men.All((Ped m) => !m.Exists() || m.IsDead || m.IsOnMount || !r.HorseOf.TryGetValue(m.Handle, out var value4) || value4 == null || !value4.Exists() || value4.IsDead);
			}
			if (!flag2)
			{
				return true;
			}
			_scenes.Remove(r);
			Vector3 vector = lead.Position - player.Position;
			vector.Z = 0f;
			if (vector.Length() < 1f)
			{
				vector = new Vector3(1f, 0f, 0f);
			}
			vector.Normalize();
			r.Responding = false;
			r.Arrived = true;
			r.RidingOff = true;
			r.FollowAt.Clear();
			r.AlertAt = Math.Min(r.AlertAt, Game.GameTime - 45001);
			r.Target = PatrolPoint(lead.Position + vector * 300f);
			r.Hurry = true;
			r.MovingTo = Vector3.Zero;
			r.MoveOrderAt = -100000;
			r.NextOrder = 0;
			GrudgeLog($"PATROL {r.Gang.Id}: riding off together after the fight ({Enumerable.Count(r.Men, (Ped m) => m.Exists() && !m.IsDead)} men, {lead.Position.DistanceTo(player.Position):0} m from you)");
			return false;
		}
		foreach (int item4 in value.Lookers.Keys.ToList())
		{
			var (ped, ped2, num2) = value.Lookers[item4];
			if (!ped.Exists() || ped.IsDead || PED.IS_PED_IN_COMBAT(ped.Handle, 0))
			{
				continue;
			}
			if (num2 == 0)
			{
				if (ped.IsOnMount)
				{
					continue;
				}
				num2 = 1;
				Vector3 vector2 = BodySide(ped2);
				TASK.TASK_FOLLOW_NAV_MESH_TO_COORD(ped.Handle, vector2.X, vector2.Y, vector2.Z, 1f, -1, 0.6f, 0, 0f);
			}
			else if (num2 == 1 && !ped2.Exists())
			{
				num2 = 2;
				TASK.TASK_START_SCENARIO_IN_PLACE_HASH(ped.Handle, MISC.GET_HASH_KEY("WORLD_HUMAN_GUARD_SCOUT"), -1, p3: true, 0u, -1f, p6: false);
			}
			else if (num2 == 1 && ped.Position.DistanceTo(ped2.Position) < 1.8f)
			{
				num2 = 2;
				ENTITY.SET_ENTITY_HEADING(ped.Handle, HeadingTo(ped.Position, ped2.Position));
				TASK.TASK_START_SCENARIO_IN_PLACE_HASH(ped.Handle, MISC.GET_HASH_KEY("WORLD_HUMAN_CROUCH_INSPECT"), -1, p3: true, 0u, -1f, p6: false);
			}
			else if (num2 == 1 && Stuck(ped))
			{
				Vector3 vector3 = BodySide(ped2);
				TASK.TASK_GO_TO_COORD_ANY_MEANS(ped.Handle, vector3.X, vector3.Y, vector3.Z, 1f, 0, p6: false, 786603, 0f);
			}
			value.Lookers[item4] = (ped, ped2, num2);
		}
		return true;
	}

	private PatrolScene StartPatrolScene(Raid r, Ped lead, Ped player, bool look = true)
	{
		Vector3 centre;
		if (r.Alert != Vector3.Zero)
		{
			centre = r.Alert;
		}
		else
		{
			centre = ((r.CampId != null) ? r.Target : lead.Position);
		}
		PatrolScene sc = new PatrolScene
		{
			StartedAt = Game.GameTime,
			EndsAt = Game.GameTime + 35000 + _rng.Next(10000),
			AlertSeen = r.AlertAt,
			Center = centre
		};
		if (r.SidedWithYou && !AfterYou(r.Gang) && lead.Position.DistanceTo(player.Position) < 45f && !HiddenFromView(player, lead.Position + new Vector3(0f, 0f, 1f)))
		{
			TASK.TASK_TURN_PED_TO_FACE_ENTITY(lead.Handle, player.Handle, 2500, 0f, 0f, 0f);
			TrySay(lead, "GREET_GENERAL_STRANGER", player);
			GrudgeNotice("The " + r.Gang.Name + " ride on.");
		}
		HashSet<int> ours = new HashSet<int>(from m in r.Men
			where m.Exists()
			select m.Handle);
		List<Ped> bodies = new List<Ped>();
		try
		{
			bodies = (from p in PedsAround(player)
				where p != null && p.Exists() && p.IsDead && p.IsHuman && !p.IsPlayer && !ours.Contains(p.Handle) && p.Position.DistanceTo(centre) < 45f
				group p by p.Handle into g
				select g.First() into p
				orderby p.Position.DistanceTo(lead.Position)
				select p).ToList();
		}
		catch (Exception ex)
		{
			GrudgeLog("PATROL scene: the dead couldn't be found - " + ex.Message);
		}
		List<Ped> list = (from m in r.Men
			where m.Exists() && !m.IsDead && m != lead && !PED.IS_PED_IN_COMBAT(m.Handle, 0) && !NerveOut(m.Handle)
			orderby (bodies.Count <= 0) ? 0f : m.Position.DistanceTo(bodies[0].Position)
			select m).ToList();
		for (int num = 0; num < Math.Min((!look) ? 1 : 2, Math.Min(list.Count, bodies.Count)); num++)
		{
			Ped ped = list[num];
			if (_patrolOpen.Remove(ped.Handle))
			{
				ped.BlockPermanentEvents = true;
			}
			if (ped.IsOnMount)
			{
				TASK.TASK_DISMOUNT_ANIMAL(ped.Handle, 0, 0uL, 0uL, 0uL, 0);
			}
			sc.Lookers[ped.Handle] = (ped, bodies[num], 0);
		}
		if (bodies.Count > 0)
		{
			sc.Center = bodies[0].Position;
		}
		foreach (Ped item in r.Men.Where((Ped m) => m.Exists() && !m.IsDead && !sc.Lookers.ContainsKey(m.Handle) && !PED.IS_PED_IN_COMBAT(m.Handle, 0)))
		{
			Function.Call(8044667063384373619uL, item.Handle, sc.Center.X, sc.Center.Y, sc.Center.Z, 4000, 0, 51, 0);
			Function.Call(16164602603745899285uL, item.Handle, sc.Center.X, sc.Center.Y, sc.Center.Z, 14f, 2f, 5f, 0);
		}
		sc.EndsAt = Game.GameTime + ((look && bodies.Count > 0) ? (25000 + _rng.Next(10000)) : (15000 + _rng.Next(10000)));
		GrudgeLog(string.Format("PATROL {0}: quiet 15 s - looking the place over, moving about: {1} to {2} dead, {3} s, {4:0} m from you{5}", r.Gang.Id, sc.Lookers.Count, bodies.Count, (sc.EndsAt - Game.GameTime) / 1000, lead.Position.DistanceTo(player.Position), r.SidedWithYou ? ", they took your side" : ""));
		return sc;
	}

	private void RideOffTogether(Raid r, Ped m, Ped lead, bool march)
	{
		if (lead == null || m == lead)
		{
			if (march || Stuck(m))
			{
				MoveTo(r, m, r.Target, fast: false);
			}
			return;
		}
		int num = r.Men.Where((Ped x) => x != lead).ToList().IndexOf(m);
		float num2 = 3.5f * (float)(num / 2 + 1);
		float num3 = ((num % 2 == 0) ? 2f : (-2f));
		bool flag = m.Position.DistanceTo(lead.Position) > (float)Math.Sqrt(num2 * num2 + num3 * num3) + 5f;
		if (!r.FollowAt.TryGetValue(m.Handle, out var value) || (flag && Game.GameTime - value > 6000))
		{
			r.FollowAt[m.Handle] = Game.GameTime;
			TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(m.Handle, lead.Handle, num3, 0f - num2, 0f, 3f, -1, 2.5f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
		}
	}

	private Vector3 BodySide(Ped body)
	{
		double num = _rng.NextDouble() * Math.PI * 2.0;
		return GroundOnSpot(body.Position + new Vector3((float)Math.Cos(num) * 0.9f, (float)Math.Sin(num) * 0.9f, 0f));
	}

	private bool AtWar(Gang a, Gang b)
	{
		if (a == null || b == null || a == b)
		{
			return false;
		}
		if (IsDestroyed(a) || IsDestroyed(b) || TruceBetween(a.Id, b.Id))
		{
			return false;
		}
		if ((a != Gangs.Army || (b != Gangs.LemoyneRaiders && b != Gangs.ODriscolls)) && (b != Gangs.Army || (a != Gangs.LemoyneRaiders && a != Gangs.ODriscolls)))
		{
			return AtWarNow(a.Id, b.Id);
		}
		return true;
	}

	private Gang FactionOfPed(Ped p)
	{
		NemesisRecord nemesisRecord = RecordAt(p.Handle);
		if (nemesisRecord != null && nemesisRecord.Gang != null)
		{
			return Gangs.ById(nemesisRecord.Gang);
		}
		return Gangs.ForModel((uint)p.Model.Hash);
	}

	private static bool CivilGroup(uint g)
	{
		if (_relCivMale == 0)
		{
			_relCivMale = Joaat.Of("REL_CIVMALE");
			_relCivFemale = Joaat.Of("REL_CIVFEMALE");
			_relPlayer = Joaat.Of("PLAYER");
		}
		if (g != _relCivMale && g != _relCivFemale)
		{
			return g == _relPlayer;
		}
		return true;
	}

	private bool SharedModGroup(uint g)
	{
		if (g != 0)
		{
			if (g != _nemesisGroup && g != _townFightGroup && g != _townRelGroup && g != _rivalGroup && g != _survivorGroup && g != _huntersGroup && g != _surrenderGroup && g != _generalGroup && g != _sideA)
			{
				return g == _sideB;
			}
			return true;
		}
		return false;
	}

	private void JudgeTheFight(Raid r, Ped lead, Ped player)
	{
		if (r.Hostile || lead == null || !lead.Exists() || (_nextSideCheck.TryGetValue(r, out var value) && Game.GameTime < value))
		{
			return;
		}
		_nextSideCheck[r] = Game.GameTime + 1000;
		if (lead.Position.DistanceTo(player.Position) > 150f)
		{
			return;
		}
		Vector3 position = player.Position;
		string text = null;
		List<(Gang, uint)> list = new List<(Gang, uint)>();
		List<(Gang, Ped)> list2 = new List<(Gang, Ped)>();
		foreach (Ped item in PedsAround(player))
		{
			if (item == null || !item.Exists() || item.IsPlayer || !item.IsHuman || r.Men.Contains(item) || item.Position.DistanceTo(position) > 120f || !(item.IsDead ? (PED.GET_PED_SOURCE_OF_DEATH(item.Handle) == player.Handle) : PED.IS_PED_IN_COMBAT(item.Handle, player.Handle)))
			{
				continue;
			}
			Gang gang = FactionOfPed(item);
			if (gang == null)
			{
				continue;
			}
			if (gang == r.Gang)
			{
				text = (item.IsDead ? ("you killed one of their own (" + gang.Name + ")") : ("you're fighting their own (" + gang.Name + ")"));
				break;
			}
			if (AtWar(r.Gang, gang) && !item.IsDead)
			{
				uint num = ModGroupOf(item.Handle);
				if (SharedModGroup(num) || CivilGroup(num))
				{
					list2.Add((gang, item));
				}
				else
				{
					list.Add((gang, num));
				}
			}
		}
		if (text != null)
		{
			r.Hostile = true;
			r.WatchYouUntil = 0;
			r.Watch = false;
			SetPatrolRelations(player);
			GrudgeLog("PATROL " + r.Gang.Id + " sides: " + text + " - they're after you");
			Feed("PATROL " + r.Gang.Name + ": " + text + " - they're after you", Theme.Blood);
			return;
		}
		uint num2 = GroupFor(r.Gang);
		foreach (var (gang2, ped) in list2)
		{
			if (!_sidedPeds.Add(ped.Handle))
			{
				continue;
			}
			foreach (Ped man in r.Men)
			{
				if (man != null && man.Exists() && !man.IsDead && man.Position.DistanceTo(ped.Position) < 120f)
				{
					TASK.TASK_COMBAT_PED(man.Handle, ped.Handle, 0, 16);
				}
			}
			r.WatchYouUntil = 0;
			r.SidedWithYou = true;
			GrudgeLog($"PATROL {r.Gang.Id} sides: you're fighting the {gang2.Name} - they take on ped {ped.Handle}");
			Feed("PATROL " + r.Gang.Name + " rides in against the " + gang2.Name, r.Gang.Accent);
		}
		foreach (var (gang3, num3) in list.Distinct())
		{
			if (num3 != 0 && num3 != player.RelationshipGroup && _sidedAgainst.Add((r.Gang.Id, num3)))
			{
				World.SetRelationshipBetweenGroups((eRelationshipType)6, num2, num3);
				World.SetRelationshipBetweenGroups((eRelationshipType)6, num3, num2);
				r.WatchYouUntil = 0;
				r.SidedWithYou = true;
				GrudgeLog("PATROL " + r.Gang.Id + " sides: you're fighting the " + gang3.Name + " - they take them on");
				Feed("PATROL " + r.Gang.Name + " rides in against the " + gang3.Name, r.Gang.Accent);
			}
		}
	}

	private bool GetDownToFight(Raid r, Ped m, Ped player)
	{
		if (!r.Hostile || !m.IsOnMount || _gotDown.Contains(m.Handle))
		{
			return false;
		}
		if (m.Position.DistanceTo(player.Position) > 45f)
		{
			return false;
		}
		_gotDown.Add(m.Handle);
		if ((uint)m.Handle % 10u >= 7)
		{
			return false;
		}
		TASK.TASK_DISMOUNT_ANIMAL(m.Handle, 0, 0uL, 0uL, 0uL, 0);
		GrudgeLog($"PATROL {r.Gang.Id}: a rider gets down to fight ({m.Position.DistanceTo(player.Position):0} m from you)");
		return true;
	}

	private bool FightingNear(Raid r, Ped player)
	{
		if (!r.Hostile && Game.GameTime >= r.WatchYouUntil)
		{
			return r.Men.Any((Ped m) => m.Exists() && !m.IsDead && PED.IS_PED_IN_COMBAT(m.Handle, 0) && m.Position.DistanceTo(player.Position) < 120f);
		}
		return true;
	}

	private void CapOurPeds()
	{
		if (Game.GameTime < _pedCapAt)
		{
			return;
		}
		_pedCapAt = Game.GameTime + 5000;
		Ped character = Game.Player.Character;
		if (character == null || !character.Exists())
		{
			return;
		}
		Vector3 position = character.Position;
		int num = 0;
		HashSet<int> hashSet = new HashSet<int>();
		foreach (var (ped, ourRole) in OurPeds())
		{
			if (ped != null && hashSet.Add(ped.Handle) && ped.Exists() && !ped.IsDead && ourRole != OurRole.Companion)
			{
				num++;
			}
		}
		int num2 = Enumerable.Count(_aftermathPeds, (Ped ped2) => ped2 != null && ped2.Exists());
		int num3 = num + num2 / 2 - 30;
		if (num3 <= 0)
		{
			return;
		}
		List<(Ped, int, float, TownMan)> list = new List<(Ped, int, float, TownMan)>();
		foreach (Ped aftermathPed in _aftermathPeds)
		{
			if (aftermathPed != null && aftermathPed.Exists())
			{
				list.Add((aftermathPed, 0, aftermathPed.Position.DistanceTo(position), null));
			}
		}
		foreach (Ped regular in _regulars)
		{
			if (regular != null && regular.Exists() && !regular.IsDead)
			{
				list.Add((regular, 1, regular.Position.DistanceTo(position), null));
			}
		}
		foreach (Ped survivor in _survivors)
		{
			if (survivor != null && survivor.Exists() && !survivor.IsDead && !_worldNemeses.ContainsKey(survivor.Handle))
			{
				list.Add((survivor, 2, survivor.Position.DistanceTo(position), null));
			}
		}
		foreach (TownMan townMan in _townMen)
		{
			if (townMan.Ped != null && townMan.Ped.Exists() && !townMan.Ped.IsDead && !townMan.Engaged && !townMan.Leaving)
			{
				list.Add((townMan.Ped, 3, townMan.Ped.Position.DistanceTo(position), townMan));
			}
		}
		int num4 = 0;
		foreach (var item in list.Where(((Ped p, int tier, float d, TownMan tm) c) => c.d > 80f).OrderBy(((Ped p, int tier, float d, TownMan tm) c) => c.tier).ThenByDescending(((Ped p, int tier, float d, TownMan tm) c) => c.d))
		{
			if (num4 >= num3)
			{
				break;
			}
			if (SafeToDelete(item.Item1) && HiddenFromView(character, item.Item1.Position + new Vector3(0f, 0f, 1f)) && !PED.IS_PED_IN_COMBAT(item.Item1.Handle, 0))
			{
				if (item.Item4 != null)
				{
					ClearTownMan(item.Item4, delete: true);
				}
				else
				{
					var (p, _, _, _) = item;
					DeleteOrRelease(p);
				}
				num4++;
			}
		}
		if (num4 > 0)
		{
			GrudgeLog($"PEDCAP {num} living + {num2} bodies of ours (cap {30}) - let {num4} far-off, out-of-sight people go");
		}
	}

	private static string PenKey(Telegram t)
	{
		return (t.ToNemesis ? "n:" : "p:") + t.ToId;
	}

	private static int TemperPen(Personality? p)
	{
		if (p != Personality.Loyal)
		{
			if (p != Personality.Drifter)
			{
				if (p != Personality.Cold)
				{
					if (p != Personality.Coward && p != Personality.Hothead && p != Personality.Proud)
					{
						return 0;
					}
					return -5;
				}
				return -20;
			}
			return 5;
		}
		return 15;
	}

	private static int TemperPenCost(Personality? p)
	{
		if (p != Personality.Cold)
		{
			if (p != Personality.Proud && p != Personality.Hothead)
			{
				if (p != Personality.Greedy && p != Personality.Drifter)
				{
					if (p != Personality.Coward)
					{
						if (p != Personality.Loyal)
						{
							return 12;
						}
						return 8;
					}
					return 10;
				}
				return 14;
			}
			return 16;
		}
		return 22;
	}

	private static Personality? TemperOfAcq(Acquaintance a)
	{
		if (!Enum.TryParse<Personality>(a?.Temper ?? "", out var result))
		{
			return null;
		}
		return result;
	}

	private PenPal PenOf(Telegram t, NemesisRecord r, Acquaintance a)
	{
		long num = GameMinutesNow();
		if (!Pens.TryGetValue(PenKey(t), out var value))
		{
			int v;
			if (r != null)
			{
				v = 25 - (r.Hate - 50) / 2 + EffectiveFear(r) / 4 + TemperPen(r.Personality);
			}
			else
			{
				v = ((a != null) ? (40 + a.Like / 2 - a.Fear / 3 - a.Grudge / 2 + TemperPen(TemperOfAcq(a))) : 30);
			}
			value = new PenPal
			{
				Interest = Clamp(v, 0, 100),
				LastAt = num
			};
			Pens[PenKey(t)] = value;
			GrudgeLog($"PENPAL {t.ToName}: interest in your letters starts at {value.Interest}");
		}
		long num2 = Math.Max(0L, (num - value.LastAt) / 1440);
		if (num2 > 0)
		{
			int num3 = ((a != null && a.Like >= 20) ? 5 : 2);
			value.Interest = Math.Min(100, value.Interest + (int)Math.Min(100L, num2 * num3));
			value.LastAt += num2 * 1440;
			if (value.Stopped && value.Interest >= 30)
			{
				value.Stopped = false;
				GrudgeLog($"PENPAL {t.ToName} would answer you again ({value.Interest})");
			}
		}
		if (a != null && a.Like < 10 && a.Grudge > 40)
		{
			value.Interest = 0;
		}
		return value;
	}

	private bool PenAnswers(Telegram t, NemesisRecord r, Acquaintance a)
	{
		PenPal penPal = PenOf(t, r, a);
		if (penPal.Interest > 0 && !penPal.Stopped)
		{
			return true;
		}
		penPal.Stopped = true;
		t.NoAnswer = true;
		t.Reply = "NO REPLY CAME.";
		t.Effect = $"no answer - interest {penPal.Interest}";
		bool female = ((r != null) ? Models.Female(r.ModelHash) : (a != null && Models.Female(a.Model)));
		t.Result = Pron.Her("He didn't write back. He's had enough of your wires for now.", female);
		GrudgeLog($"PENPAL {t.ToName}: no answer - he's stopped writing back (interest {penPal.Interest})");
		return false;
	}

	private void PenSpent(Telegram t, NemesisRecord r, Acquaintance a)
	{
		PenPal penPal = PenOf(t, r, a);
		int num;
		if (r != null)
		{
			num = TemperPenCost(r.Personality) + ((r.HateTier == HateTier.Murderous) ? 6 : 0);
		}
		else
		{
			num = Math.Max(4, TemperPenCost(TemperOfAcq(a)) - (a?.Like ?? 0) / 10);
			if (t.Message == "warn")
			{
				num += 15;
			}
		}
		int interest = penPal.Interest;
		penPal.Interest = Math.Max(0, penPal.Interest - num);
		penPal.Letters++;
		penPal.LastAt = GameMinutesNow();
		if (penPal.Interest == 0)
		{
			penPal.Stopped = true;
		}
		GrudgeLog(string.Format("PENPAL {0}: interest {1} -> {2} ({3} letters){4}", t.ToName, interest, penPal.Interest, penPal.Letters, penPal.Stopped ? " - he'll stop answering" : ""));
	}

	private float PenWorth(Telegram t)
	{
		long since = GameMinutesNow() - 10080;
		return Enumerable.Count(Telegrams, (Telegram x) => x != t && x.ToId == t.ToId && !x.ToNemesis && x.Arrived && !x.NoAnswer && x.ArriveAt >= since && FriendlyKeys.Contains(x.Message ?? "")) switch
		{
			2 => 0.35f, 
			1 => 0.6f, 
			0 => 1f, 
			_ => 0.2f, 
		};
	}

	internal bool IsPenPal(Acquaintance a)
	{
		if (a != null && a.Like >= 40 && Pens.TryGetValue("p:" + a.Id, out var value) && value.Letters >= 2 && !value.Stopped)
		{
			return value.Interest > 0;
		}
		return false;
	}

	private (string text, (int r, int g, int b) c)? PenStatus(Telegram t)
	{
		if (!Pens.TryGetValue(PenKey(t), out var value))
		{
			return null;
		}
		bool female;
		string s;
		(int, int, int) item;
		if (t.ToNemesis)
		{
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord x) => x.Id == t.ToId);
			female = nemesisRecord != null && Models.Female(nemesisRecord.ModelHash);
			if (value.Stopped || value.Interest <= 0)
			{
				s = "He's stopped answering your wires.";
				item = Theme.Warn;
			}
			else
			{
				if (value.Interest >= 25)
				{
					return null;
				}
				s = "He's tiring of your wires - he may not answer many more.";
				item = Theme.Warn;
			}
		}
		else
		{
			Acquaintance acquaintance = People.FirstOrDefault((Acquaintance x) => x.Id == t.ToId);
			female = acquaintance != null && Models.Female(acquaintance.Model);
			if (value.Stopped || value.Interest <= 0)
			{
				s = "He's stopped answering your letters for now.";
				item = Theme.Warn;
			}
			else if (value.Interest < 25)
			{
				s = "He's tiring of your letters - give it a few days.";
				item = Theme.Warn;
			}
			else if (IsPenPal(acquaintance))
			{
				s = $"Pen pals - he's written to you {value.Letters} times and is glad to hear from you.";
				item = Theme.Good;
			}
			else
			{
				if (value.Interest < 60)
				{
					return null;
				}
				s = "He's glad to hear from you.";
				item = Theme.Good;
			}
		}
		return (Pron.Her(s, female), item);
	}

	private string PenLetterLine(Acquaintance a)
	{
		string text = PenLife[_rng.Next(PenLife.Length)];
		if (_rng.Next(100) < 35)
		{
			string text2 = TownNewsFor(a.Town);
			if (!text2.StartsWith("QUIET"))
			{
				text = text + "  " + text2;
			}
		}
		return text;
	}

	private Telegram PenPalLetter(long now)
	{
		Acquaintance acquaintance = (from _ in People
			where !_.Dead && _.Id != null && IsPenPal(_) && !Telegrams.Any((Telegram t) => t.ToId == _.Id && t.Spontaneous && now - t.ArriveAt < 4320) && !Telegrams.Any((Telegram t) => t.ToId == _.Id && !t.Arrived)
			orderby _rng.Next()
			select _).FirstOrDefault();
		if (acquaintance == null)
		{
			return null;
		}
		string text = (new string[4] { "HOPE THIS FINDS YOU WELL.", "THOUGHT I WOULD WRITE.", "BEEN A WHILE. HOW ARE YOU KEEPING.", "NO NEWS. WRITING ANYWAY." })[_rng.Next(4)];
		GrudgeLog("PENPAL " + acquaintance.FullName + " wrote to you first");
		return new Telegram
		{
			Id = NewId(8),
			ToId = acquaintance.Id,
			ToNemesis = false,
			ToName = acquaintance.FullName,
			Message = "in_letter",
			SentAt = now,
			ArriveAt = now,
			Arrived = true,
			Spontaneous = true,
			Reply = text + "  " + PenLetterLine(acquaintance) + "  WRITE WHEN YOU CAN.",
			Effect = ""
		};
	}

	private static string SpontLabel(string kind)
	{
		return kind switch
		{
			"in_threat" => "A threat", 
			"in_gloat" => "A gloating letter", 
			"in_plea" => "A plea for mercy", 
			"in_tip" => "A warning", 
			"in_treasury" => "A tip-off", 
			"in_regards" => "A friendly note", 
			"in_letter" => "A letter", 
			_ => "A letter", 
		};
	}

	private static string AnswerTo(string key)
	{
		switch (key)
		{
		case "peace":
			return "peace offer";
		case "sorry":
		case "pcondole":
			if (!(key == "sorry"))
			{
				return "condolences";
			}
			return "apology";
		case "money":
			return "money";
		case "payoff":
			return "offer to pay him off";
		case "threat":
		case "family":
			return "threat";
		case "coming":
			return "warning that you're coming";
		case "taunt":
		case "kin":
			return "taunt";
		case "boss":
			return "question about his boss";
		case "distrust":
			return "word about his boss";
		case "wish":
			return "good wishes";
		case "condole":
			return "condolences";
		case "pgift":
		case "gift":
			return "gift";
		case "regards":
			return "regards";
		case "news":
			return "question about the news";
		case "asking":
			return "question";
		case "thanks":
			return "thanks";
		case "drink":
			return "drink";
		case "loan":
			return "request for a loan";
		case "lookout":
			return "request";
		case "warn":
			return "warning";
		case "letter":
		case "checkin":
			return "letter";
		default:
			return "wire";
		}
	}

	private static string InboxNote(Telegram t)
	{
		string text;
		if (t.NoAnswer)
		{
			text = "No reply came";
		}
		else
		{
			text = (t.Spontaneous ? SpontLabel(t.Message) : ("Reply to your " + AnswerTo(t.Message)));
		}
		if (t.Money > 0 && !t.Read)
		{
			text += $"  -  ${t.Money} enclosed";
		}
		return text;
	}

	private string TelegramContext(Telegram t, bool fem)
	{
		string text = $"{GameDate.FromMinutes(t.Spontaneous ? t.ArriveAt : t.SentAt):MMM d}";
		string s;
		if (t.NoAnswer)
		{
			s = "You wired him from " + (t.From ?? "a station") + " on " + text + ". Western Union could not raise an answer.";
		}
		else
		{
			s = (t.Spontaneous ? (SpontLabel(t.Message) + " he sent you on " + text + ".") : ("His answer to your " + AnswerTo(t.Message) + ", wired from " + (t.From ?? "a station") + " on " + text + "."));
		}
		return Pron.Her(s, fem);
	}

	internal List<Acquaintance> PeopleForList()
	{
		if (_peopleListCache != null && UiDraw.RealMs - _peopleListAt < 250)
		{
			return _peopleListCache;
		}
		_peopleListAt = UiDraw.RealMs;
		return _peopleListCache = PeopleForListNow();
	}

	private List<Acquaintance> PeopleForListNow()
	{
		HashSet<string> onRoster = new HashSet<string>(Roster.Select((NemesisRecord r) => r.Name));
		List<Acquaintance> list = People.Where((Acquaintance a) => a != null && !string.IsNullOrEmpty(a.Name) && !onRoster.Contains(a.Name) && (a.Met || a.Grudge > 0 || a.Fear > 0 || a.Like > 0 || a.Favours > 0 || a.LastDealt > DateTime.MinValue || (a.Witnessed != null && a.Witnessed.Count > 0))).ToList();
		HashSet<string> hashSet = new HashSet<string>(list.Select((Acquaintance a) => a.Name));
		foreach (KeyValuePair<int, Named> item in _named)
		{
			Named value = item.Value;
			if (!value.Story && !string.IsNullOrEmpty(value.Name) && !hashSet.Contains(value.Name) && !onRoster.Contains(value.Name) && RecordAt(item.Key) == null && _provoked.TryGetValue(item.Key, out var value2) && !value2.Settled)
			{
				Acquaintance acquaintance = new Acquaintance
				{
					LifeRules = 2,
					Model = (ENTITY.DOES_ENTITY_EXIST(item.Key) ? ENTITY.GET_ENTITY_MODEL(item.Key) : 0u),
					Name = value.Name,
					Title = value.Title,
					Met = value.Met,
					Town = _currentTown,
					LastSeen = DateTime.Now,
					LastGameMin = GameMinutesNow(),
					TimesSeen = 1
				};
				if (_provoked.TryGetValue(item.Key, out var value3) && !value3.Settled)
				{
					acquaintance.Grudge = (int)value3.Score;
					acquaintance.Temper = value3.Temper.ToString();
				}
				hashSet.Add(value.Name);
				list.Add(acquaintance);
			}
		}
		return list;
	}

	private void SavePeople(bool force = false, bool later = false)
	{
		if ((_peopleDirty || !_peopleSoft || (!force && Game.GameTime - _peopleSoftSavedAt < 60000)) && (!_peopleDirty || (!force && Game.GameTime < _nextPeopleSave)))
		{
			return;
		}
		_nextPeopleSave = Game.GameTime + 5000;
		try
		{
			string text = JsonConvert.SerializeObject(People);
			if (force && !later && SafeFile.WaitWrites())
			{
				SafeFile.Write(PeoplePath, text, keepBak: true);
			}
			else
			{
				SafeFile.WriteLater(PeoplePath, text, keepBak: true, (Exception err) =>
				{
					if (err != null)
					{
						_peopleDirty = true;
					}
				});
			}
			_peopleDirty = false;
			_peopleSoft = false;
			_peopleSoftSavedAt = Game.GameTime;
		}
		catch (Exception ex)
		{
			GrudgeLog("PEOPLE save failed: " + ex.Message);
		}
	}

	internal NemesisRecord PersonRecord(Acquaintance a)
	{
		if (a == null)
		{
			return null;
		}
		string key = (a.Id ?? a.Name) + "|" + a.Model;
		if (!_personPages.TryGetValue(key, out var value))
		{
			Gang gang = Gangs.ForModel(a.Model);
			value = new NemesisRecord
			{
				Name = "",
				ModelHash = a.Model,
				Gang = gang?.Id
			};
			value.Id = $"stranger:{a.Name}|{a.Model:X8}";
			RollNewLife(value, null, mind: true, (a.LifeRules < 2) ? 1 : 2);
			if (a.LifeRules >= 2 && !string.IsNullOrEmpty(a.Temper) && Enum.TryParse<Personality>(a.Temper, out var result) && value.Personality != result)
			{
				Personality? personality = value.Personality;
				value.Personality = result;
				BackstoryResult backstoryResult = Backstory.Roll(value, Seeds.For(value, "life-fit"), GameYear(), GameMonth(), derive: false, keepBorn: true);
				value.LifeFx = (from kv in backstoryResult.Tilt
					where kv.Value != 0
					select $"t:{kv.Key.ToString().ToLowerInvariant()}:{kv.Value}").ToList();
				Mind.Roll(value, Seeds.For(value, "mind"), GameMinutesNow());
				value.Quirks = new List<string>();
				value.QuirksRolled = false;
				GrudgeLog($"HISTORY {a.Name}: known as {result} (the roll said {personality}) - his life written to fit");
			}
			value.Id = "person:" + (a.Id ?? a.Name);
			value.KinId = null;
			value.FriendIds = new List<string>();
			_personPages[key] = value;
		}
		value.Name = a.Name;
		value.Title = a.Title ?? "";
		value.Person = true;
		value.PersonAcq = a;
		if (!string.IsNullOrEmpty(a.Temper) && Enum.TryParse<Personality>(a.Temper, out var result2))
		{
			value.Personality = result2;
		}
		value.PersonalityKnown = a.Met || a.Grudge > 0;
		if (value.Past != null)
		{
			foreach (PastEntry item in value.Past)
			{
				item.Known = a.Met;
			}
		}
		value.KillLocation = a.Town;
		return value;
	}

	internal void NoteDealt(int handle)
	{
		if (handle != 0 && _acqOf.TryGetValue(handle, out var value))
		{
			value.LastDealt = DateTime.Now;
			_peopleDirty = true;
		}
	}

	internal void RememberPerson(int handle, bool met)
	{
		if (!Config.RememberPeople || handle == 0 || RecordAt(handle) != null || OutfitFighter(handle) || !_named.TryGetValue(handle, out var n) || n.Story)
		{
			return;
		}
		Ped ped = Entity.FromHandle(handle) as Ped;
		if (ped == null || !ped.Exists() || ped.IsDead || !ped.IsHuman || Kids.IsChild(ped))
		{
			return;
		}
		if (!_acqOf.TryGetValue(handle, out var a))
		{
			a = People.FirstOrDefault((Acquaintance x) => x.Name == n.Name && x.Model == (uint)ped.Model.Hash);
			if (a == null)
			{
				a = new Acquaintance
				{
					LifeRules = 2,
					Id = Guid.NewGuid().ToString("N").Substring(0, 10),
					Name = n.Name,
					Title = n.Title,
					Model = (uint)ped.Model.Hash,
					Town = (_currentTown ?? TownAt(ped.Position) ?? GetZoneName(ped.Position)),
					FirstSeen = DateTime.Now,
					LastSeen = DateTime.Now,
					LastGameMin = GameMinutesNow(),
					Met = (met || n.Met),
					Affil = n.Affil
				};
				People.Add(a);
				WaryFromWord(a, TemperOf(ped), ped);
				try
				{
					int num = ((a.Town != null) ? TownReputation(a.Town) : 0);
					if (num >= 20 && !IsLawman(ped))
					{
						a.Like = Math.Max(a.Like, Math.Min(12, num / 6));
						GrudgeLog($"PEOPLE {a.Name} has heard good things about you in {a.Town} (reputation {num:+0}) - likes you {a.Like}");
					}
				}
				catch
				{
				}
				if (a.Fear > 0 && IsLawman(ped))
				{
					a.Fear = Math.Min(5, a.Fear / 4);
				}
				GrudgeLog("PEOPLE remembered " + a.Name + " (" + a.Town + ")" + ((a.Fear > 0) ? $" - wary already, fear {a.Fear} (the town talks)" : ""));
				while (People.Count > Config.PeopleCap)
				{
					Acquaintance acquaintance = (from x in People
						where x != a && !_acqOf.ContainsValue(x)
						orderby x.Met, x.Grudge > 0, x.Fear > 0 || x.Like > 0 || x.Favours > 0 || (x.Witnessed != null && x.Witnessed.Count > 0), x.Fear + x.Like, x.LastSeen
						select x).FirstOrDefault();
					if (acquaintance == null)
					{
						break;
					}
					People.Remove(acquaintance);
				}
			}
			_acqOf[handle] = a;
		}
		a.Met |= met || n.Met;
		if (met)
		{
			a.LastDealt = DateTime.Now;
		}
		if (string.IsNullOrEmpty(a.Temper))
		{
			try
			{
				a.Temper = TemperOf(ped);
			}
			catch
			{
			}
		}
		a.LastSeen = DateTime.Now;
		a.LastGameMin = GameMinutesNow();
		_peopleDirty = true;
	}

	internal void ForgetPerson(int handle, string name)
	{
		Acquaintance acquaintance;
		if (_acqOf.TryGetValue(handle, out var value))
		{
			acquaintance = value;
		}
		else
		{
			acquaintance = ((name != null) ? People.FirstOrDefault((Acquaintance x) => x.Name == name) : null);
		}
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord r) => r.Name == name);
		string text = acquaintance?.Affil ?? (_named.TryGetValue(handle, out var value2) ? value2.Affil : null);
		if (nemesisRecord != null && text != null && nemesisRecord.Affiliation == null && nemesisRecord.Gang == null)
		{
			nemesisRecord.Affiliation = text;
			History(nemesisRecord, "secretly runs with the " + (Gangs.ById(text)?.Name ?? text), Theme.Dim);
		}
		if (acquaintance != null && nemesisRecord != null)
		{
			nemesisRecord.FormerAcqId = acquaintance.Id;
			if (acquaintance.Circle != null && acquaintance.Circle.Count > 0)
			{
				nemesisRecord.CircleAcq = acquaintance.Circle.ToList();
				foreach (string item2 in acquaintance.Circle)
				{
					NemesisRecord item = ResolveCircle(item2).r;
					if (item != null && item.IsAlive)
					{
						MakeFriends(nemesisRecord, item, "they rode together before");
					}
				}
			}
		}
		if (acquaintance != null && nemesisRecord != null && (acquaintance.Like > 0 || acquaintance.Favours > 0))
		{
			int feltHate = nemesisRecord.FeltHate;
			int num = Math.Min(10, acquaintance.Like / 8 + acquaintance.Favours * 3);
			if (num > 0)
			{
				Gang gang = Gangs.ById(nemesisRecord.Gang ?? "");
				if (gang == null || !gang.OrdersNotFeelings)
				{
					nemesisRecord.Hate = Math.Max(5, feltHate - num);
				}
			}
			History(nemesisRecord, Pron.Her(string.Format("he used to like you (like {0}{1}) - hate {2} to {3}", acquaintance.Like, (acquaintance.Favours > 0) ? $", {acquaintance.Favours} favours" : "", feltHate, nemesisRecord.Hate), Pron.FemaleAt(handle)), Theme.Dim);
		}
		if (acquaintance != null && nemesisRecord != null && acquaintance.Fear > nemesisRecord.Fear)
		{
			GrudgeLog(Pron.Her(string.Format("PEOPLE {0} {1} - keeps his fear of you {2} -> {3}", name, nemesisRecord.IsAlive ? "becomes a nemesis" : "goes on the roster as a dead man", nemesisRecord.Fear, acquaintance.Fear), Pron.FemaleAt(handle)));
			nemesisRecord.Fear = acquaintance.Fear;
		}
		if (_acqOf.TryGetValue(handle, out var value3))
		{
			People.Remove(value3);
			_acqOf.Remove(handle);
			_peopleDirty = true;
			return;
		}
		uint fm = (ENTITY.DOES_ENTITY_EXIST(handle) ? ENTITY.GET_ENTITY_MODEL(handle) : 0u);
		if (name != null && People.RemoveAll((Acquaintance x) => x.Name == name && (fm == 0 || x.Model == fm)) > 0)
		{
			_peopleDirty = true;
		}
	}

	private void UpdatePeople(Ped player)
	{
		if (Game.GameTime >= _nextPeopleSync)
		{
			_nextPeopleSync = Game.GameTime + 2000;
			try
			{
				FadeWitnessFear();
			}
			catch
			{
			}
			try
			{
				RetireDeadNames();
			}
			catch
			{
			}
			foreach (KeyValuePair<int, Acquaintance> item in _acqOf.ToList())
			{
				Acquaintance value = item.Value;
				if (!ENTITY.DOES_ENTITY_EXIST(item.Key))
				{
					_acqOf.Remove(item.Key);
					continue;
				}
				if (_provoked.TryGetValue(item.Key, out var value2) && value2.Record == null && (value.Grudge != (int)value2.Score || string.IsNullOrEmpty(value.Temper) || value.GrudgeSettled != value2.Settled || value.SawFace != value2.SawFace))
				{
					value.Grudge = (int)value2.Score;
					if (string.IsNullOrEmpty(value.Temper))
					{
						value.Temper = value2.Temper.ToString();
					}
					value.GrudgeSettled = value2.Settled;
					value.SawFace = value2.SawFace;
					_peopleDirty = true;
				}
				Ped ped = new Ped(item.Key);
				if (!ped.IsDead || LooksKnockedOut(ped))
				{
					continue;
				}
				value.Dead = true;
				_acqOf.Remove(item.Key);
				_peopleDirty = true;
				GrudgeLog("PEOPLE " + value.Name + " died");
				int num = PED.GET_PED_SOURCE_OF_DEATH(ped.Handle);
				if (num == player.Handle || IsCompanionKiller(num) || (num == 0 && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(ped.Handle, player.Handle, p2: true, p3: true)))
				{
					try
					{
						QueuePeopleNews(value.Name, value.Town, value.Circle, ped.Position);
					}
					catch (Exception ex)
					{
						GrudgeLog("NEWS failed: " + ex.Message);
					}
				}
			}
			for (int num2 = _regulars.Count - 1; num2 >= 0; num2--)
			{
				Ped ped2 = _regulars[num2];
				if (ped2 == null || !ped2.Exists())
				{
					_regulars.RemoveAt(num2);
				}
				else if (ped2.Position.DistanceTo(player.Position) > 220f && SafeToDelete(ped2) && !_worldNemeses.ContainsKey(ped2.Handle))
				{
					_acqOf.Remove(ped2.Handle);
					_named.Remove(ped2.Handle);
					ped2.Delete();
					_regulars.RemoveAt(num2);
				}
			}
		}
		SavePeople();
	}

	private unsafe bool TrySpawnRegular(Ped player, string town, bool force = false)
	{
		if (!Config.RememberPeople || town == null || Enumerable.Count(_regulars, (Ped r) => r.Exists()) >= Config.RegularsMax)
		{
			return false;
		}
		List<Acquaintance> here = _acqOf.Values.ToList();
		List<Acquaintance> list = People.Where((Acquaintance a) => !a.Dead && a.Town == town && !here.Contains(a) && (force || (DateTime.Now - a.LastSpawned).TotalMinutes > 20.0)).ToList();
		if (list.Count == 0)
		{
			return false;
		}
		Acquaintance acquaintance = list[_rng.Next(list.Count)];
		Model m = new Model(acquaintance.Model);
		if (!m.IsValid || !m.IsPed)
		{
			acquaintance.Dead = true;
			_peopleDirty = true;
			return false;
		}
		if (!LoadModelSafe(m, 2000))
		{
			return false;
		}
		(Vector3, float, int)? tuple = FindTownSeat(player, town);
		Vector3 vector = (tuple.HasValue ? StandIn(tuple.Value.Item1, tuple.Value.Item2) : NaturalTownSpot(player, town).pos);
		if (vector == Vector3.Zero)
		{
			STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)m.Hash);
			return false;
		}
		GrudgeLog("PEOPLE spot for " + acquaintance.Name + ": " + SpotNote(vector, town, player));
		Ped ped = SpawnPed((PedHash)m.Hash, vector, tuple.HasValue ? tuple.Value.Item2 : ((float)_rng.Next(360)));
		STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)m.Hash);
		if (ped == null)
		{
			return false;
		}
		MakeOurs(ped.Handle);
		if (tuple.HasValue)
		{
			SitAt(ped, tuple.Value.Item3, tuple.Value.Item1, tuple.Value.Item2);
		}
		else
		{
			PlaceNaturally(ped, vector);
		}
		MakeSociable(ped);
		if (Config.RegularsAmbient)
		{
			int handle = ped.Handle;
			ReleaseIfOurs(&handle);
		}
		_named[ped.Handle] = new Named
		{
			Name = acquaintance.Name,
			Title = acquaintance.Title,
			Met = acquaintance.Met,
			Importance = 3,
			SeenAt = Game.GameTime,
			NamedAt = Game.GameTime
		};
		_acqOf[ped.Handle] = acquaintance;
		if (acquaintance.Grudge > 0)
		{
			RestoreGrudge(ped.Handle, acquaintance);
		}
		acquaintance.LastSpawned = DateTime.Now;
		acquaintance.TimesSeen++;
		_peopleDirty = true;
		_regulars.Add(ped);
		GrudgeLog(string.Format("PEOPLE {0} turns up in {1} ({2}, grudge {3})", acquaintance.Name, town, tuple.HasValue ? "on a seat" : "in the street", acquaintance.Grudge));
		TownHappening(acquaintance.Name + " turned up in " + town);
		Feed("TOWN " + acquaintance.Name + " is around " + town + (acquaintance.Met ? "" : " (you never got his name)") + ((acquaintance.Grudge > 0) ? $" - still sore: grudge {acquaintance.Grudge}" : ""), Theme.Dim);
		return true;
	}

	internal float TownSpread(string town)
	{
		if (town == null || !TownCore(town, out var _, out var radius))
		{
			return Balance.TownSpreadMeters;
		}
		return Balance.TownSpreadMeters * Math.Max(1f, radius / 130f);
	}

	internal (Vector3 pos, float heading, int point)? FindTownSeat(Ped player, string town, float minD = 12f)
	{
		if (town == null || !TownCore(town, out var centre, out var radius))
		{
			return FindSeat(player, minD, 110f, town);
		}
		float spread = TownSpread(town);
		Vector3? townToward = TownToward;
		if (townToward.HasValue)
		{
			Vector3 valueOrDefault = townToward.GetValueOrDefault();
			if (new Vector3(valueOrDefault.X - centre.X, valueOrDefault.Y - centre.Y, 0f).Length() < radius)
			{
				(Vector3, float, int)? result = FindSeat(player, minD, 220f, town, centre, radius, valueOrDefault, 70f, spread);
				if (result.HasValue)
				{
					return result;
				}
			}
		}
		if (radius > 150f)
		{
			Vector3 position = player.Position;
			for (int i = 0; i < 3; i++)
			{
				Vector3 vector = Vector3.Zero;
				for (int j = 0; j < 10; j++)
				{
					if (!(vector == Vector3.Zero))
					{
						break;
					}
					double num = _rng.NextDouble() * Math.PI * 2.0;
					double num2 = (double)radius * 0.75 * Math.Sqrt(_rng.NextDouble());
					Vector3 vector2 = centre + new Vector3((float)(Math.Cos(num) * num2), (float)(Math.Sin(num) * num2), 0f);
					if (vector2.DistanceTo2D(position) < 200f)
					{
						vector = vector2;
					}
				}
				if (vector == Vector3.Zero)
				{
					break;
				}
				(Vector3, float, int)? result2 = FindSeat(player, minD, 220f, town, centre, radius, vector, 90f, spread);
				if (result2.HasValue)
				{
					return result2;
				}
			}
		}
		return FindSeat(player, minD, 220f, town, centre, radius, null, 0f, spread);
	}

	internal unsafe (Vector3 pos, float heading, int point)? FindSeat(Ped player, float minD, float maxD, string town = null, Vector3? centre = null, float coreRadius = 0f, Vector3? searchAt = null, float searchRadius = 0f, float spread = 0f)
	{
		ulong* ptr = stackalloc ulong[272];
		for (int i = 0; i < 272; i++)
		{
			ptr[i] = 0uL;
		}
		*ptr = 256uL;
		Vector3 position = player.Position;
		Vector3 vector = searchAt ?? centre ?? position;
		Crumbs.Native("People scenario points");
		float x = vector.X;
		float y = vector.Y;
		float z = vector.Z;
		float p;
		if (searchRadius > 0f)
		{
			p = searchRadius;
		}
		else
		{
			p = (centre.HasValue ? coreRadius : maxD);
		}
		int num = TASK.GET_SCENARIO_POINTS_IN_AREA(x, y, z, p, ptr, 256);
		int num2 = INTERIOR.GET_INTERIOR_FROM_ENTITY(player.Handle);
		List<(Vector3, float, int)> list = new List<(Vector3, float, int)>();
		HashSet<int> hashSet = new HashSet<int>();
		int num3 = 0;
		int num4 = 0;
		int num5 = 0;
		int num6 = 0;
		int num7 = 0;
		int num8 = 0;
		int num9 = (centre.HasValue ? 999 : 6);
		int saloonInterior = 0;
		if (centre.HasValue && town != null && TownSpots.TryGetValue(town, out (Vector3?, Vector3?) value))
		{
			Vector3? item = value.Item2;
			if (item.HasValue)
			{
				Vector3 valueOrDefault = item.GetValueOrDefault();
				if (valueOrDefault.DistanceTo(position) < 110f)
				{
					saloonInterior = INTERIOR.GET_INTERIOR_AT_COORDS(valueOrDefault.X, valueOrDefault.Y, valueOrDefault.Z);
				}
			}
		}
		for (int j = 1; j <= Math.Min(num + 1, 256); j++)
		{
			if (list.Count >= num9)
			{
				break;
			}
			int num10 = (int)(ptr[j] & 0xFFFFFFFFu);
			if (num10 == 0 || !hashSet.Add(num10) || !TASK.DOES_SCENARIO_POINT_EXIST(num10))
			{
				continue;
			}
			num3++;
			if (TASK._GET_PED_USING_SCENARIO_POINT(num10) != 0)
			{
				num4++;
				continue;
			}
			Vector3 vector2 = TASK._GET_SCENARIO_POINT_COORDS(num10, p1: true);
			float num11 = vector2.DistanceTo(position);
			if (num11 < minD || num11 > maxD)
			{
				num8++;
				continue;
			}
			if (_seatTaken.TryGetValue(num10, out var value2) && Game.GameTime - value2 < 120000)
			{
				num4++;
				continue;
			}
			if (centre.HasValue && vector2.DistanceTo2D(centre.Value) > coreRadius)
			{
				num7++;
				continue;
			}
			if (town != null && TownAt(vector2) != town)
			{
				num7++;
				continue;
			}
			int num12 = INTERIOR.GET_INTERIOR_AT_COORDS(vector2.X, vector2.Y, vector2.Z);
			if (num12 != 0 && num12 != num2 && num12 != saloonInterior)
			{
				num5++;
				continue;
			}
			bool flag = saloonInterior != 0 && num12 == saloonInterior;
			NemesisMod nemesisMod = this;
			Vector3 c = vector2;
			float r;
			if (centre.HasValue)
			{
				if (flag)
				{
					r = 3f;
				}
				else
				{
					r = ((spread > 0f) ? spread : Balance.TownSpreadMeters);
				}
			}
			else
			{
				r = 6f;
			}
			if (nemesisMod.OurPeopleNear(c, r))
			{
				num4++;
			}
			else if (centre.HasValue)
			{
				list.Add((vector2, TASK._GET_SCENARIO_POINT_HEADING(num10, p1: true), num10));
			}
			else if (!HiddenFromView(player, vector2))
			{
				num6++;
			}
			else
			{
				list.Add((vector2, TASK._GET_SCENARIO_POINT_HEADING(num10, p1: true), num10));
			}
		}
		string text = "";
		List<Vector3> folk;
		if (centre.HasValue)
		{
			folk = (from ped in PedsAround(player)
				where ped != null && ped.Exists() && !ped.IsDead && ped.Handle != player.Handle && PED.IS_PED_HUMAN(ped.Handle) && !IsOurs(ped.Handle) && ped.Position.DistanceTo2D(centre.Value) < coreRadius * 1.2f
				select ped.Position).ToList();
			List<((Vector3, float, int), double, int, bool)> list2 = list.Select(((Vector3, float, int) f) =>
			{
				double item2 = Weight(f, out var near, out var saloon);
				return (f: f, w: item2, nr: near, sl: saloon);
			}).ToList();
			int count = list2.Count;
			int num13 = Enumerable.Count(list2, (((Vector3, float, int) f, double w, int nr, bool sl) tuple3) => tuple3.nr > 0);
			int num14 = Enumerable.Count(list2, (((Vector3, float, int) f, double w, int nr, bool sl) tuple3) => tuple3.sl);
			int num15 = 0;
			int num16 = 0;
			list = new List<(Vector3, float, int)>();
			for (int num17 = 0; num17 < 20; num17++)
			{
				if (list2.Count <= 0)
				{
					break;
				}
				double num18 = _rng.NextDouble() * list2.Sum((((Vector3, float, int) f, double w, int nr, bool sl) tuple3) => tuple3.w);
				int num19;
				for (num19 = 0; num19 < list2.Count - 1; num19++)
				{
					num18 -= list2[num19].Item2;
					if (num18 <= 0.0)
					{
						break;
					}
				}
				((Vector3, float, int), double, int, bool) tuple = list2[num19];
				list2.RemoveAt(num19);
				if (tuple.Item3 == 0 && !tuple.Item4 && num13 >= 1)
				{
					continue;
				}
				float num20 = tuple.Item1.Item1.DistanceTo2D(centre.Value) / coreRadius;
				if (!tuple.Item4 && (num20 > 0.9f || (num20 > 0.75f && tuple.Item3 < 2)))
				{
					num15++;
					continue;
				}
				if (!HiddenFromView(player, tuple.Item1.Item1))
				{
					num6++;
					continue;
				}
				if (!tuple.Item4 && !Walkable(tuple.Item1.Item1))
				{
					num16++;
					continue;
				}
				list.Add(tuple.Item1);
				text = string.Format(" | picked: {0} townsfolk within 20 m{1}, weight {2:0.0}", tuple.Item3, tuple.Item4 ? ", IN THE SALOON" : "", tuple.Item2);
				break;
			}
			SeatNoteExtra = $", {count} candidates in the core ({num13} near townsfolk, {num14} in the saloon; {folk.Count} townsfolk about; {num15} at the edge skipped, {num16} off the walkways)";
		}
		else
		{
			SeatNoteExtra = "";
		}
		SeatNote = string.Format("{0}{1} returned, {2} points, {3} too near/far, {4} in use, {5} outside town, {6} in other buildings, {7} in view, {8} usable{9}", searchAt.HasValue ? $"district {searchAt.Value.X:0},{searchAt.Value.Y:0} ({searchRadius:0} m), spread {spread:0} m - " : "", num, num3, num8, num4, num7, num5, num6, list.Count, SeatNoteExtra);
		if (list.Count == 0)
		{
			return null;
		}
		(Vector3, float, int) tuple2 = list[_rng.Next(list.Count)];
		_seatTaken[tuple2.Item3] = Game.GameTime;
		foreach (int item3 in (from kv in _seatTaken
			where Game.GameTime - kv.Value > 300000
			select kv.Key).ToList())
		{
			_seatTaken.Remove(item3);
		}
		GrudgeLog(string.Format("SEAT {0} at {1:0},{2:0} ({3:0} m from you{4}) - {5}{6}", tuple2.Item3, tuple2.Item1.X, tuple2.Item1.Y, tuple2.Item1.DistanceTo(position), centre.HasValue ? $", {tuple2.Item1.DistanceTo2D(centre.Value):0}/{coreRadius:0} m from {town} centre" : ((town != null) ? (", zone " + town) : ", wild"), SeatNote, text));
		return (tuple2.Item1, tuple2.Item2, tuple2.Item3);
		double Weight((Vector3, float, int) f, out int near, out bool saloon)
		{
			Vector3 c2 = f.Item1;
			near = Enumerable.Count(folk, (Vector3 q) => q.DistanceTo(c2) < 20f);
			saloon = saloonInterior != 0 && INTERIOR.GET_INTERIOR_AT_COORDS(c2.X, c2.Y, c2.Z) == saloonInterior;
			double num21 = ((near == 0) ? 0.05 : Math.Pow(Math.Min(near, 8), 1.5));
			if (saloon)
			{
				num21 += 10.0;
			}
			float num22 = c2.DistanceTo2D(centre.Value);
			return num21 * ((num22 < coreRadius * 0.5f) ? 1.0 : ((num22 < coreRadius * 0.75f) ? 0.45 : 0.12));
		}
	}

	private bool OurPeopleNear(Vector3 c, float r)
	{
		foreach (var item in OurPeds())
		{
			var (ped, _) = item;
			if (item.role != OurRole.Aftermath && ped != null && ped.Exists() && !ped.IsDead && ped.Position.DistanceTo(c) < r)
			{
				return true;
			}
		}
		return false;
	}

	private bool CardOccluded(Vector3 point)
	{
		Crumbs.Native("NameCards occlusion ray");
		return Ray.Blocked(CAM.GET_FINAL_RENDERED_CAM_COORD(), point, 17, Game.Player.Character.Handle);
	}

	internal static bool Walkable(Vector3 c)
	{
		try
		{
			Vector3 safeCoordForPed = World.GetSafeCoordForPed(c);
			if (safeCoordForPed == Vector3.Zero)
			{
				return false;
			}
			return safeCoordForPed.DistanceTo2D(c) < 2.5f && Math.Abs(safeCoordForPed.Z - c.Z) < 1.5f;
		}
		catch
		{
			return true;
		}
	}

	internal bool HiddenFromView(Ped player, Vector3 spot)
	{
		Vector3 vector = spot + new Vector3(0f, 0f, 1.2f);
		if (!Projection.ToScreen(vector, out var x, out var y) || x < -0.02f || x > 1.02f || y < -0.02f || y > 1.02f)
		{
			return true;
		}
		return Ray.Blocked(CAM.GET_FINAL_RENDERED_CAM_COORD(), vector, 1, player.Handle);
	}

	internal unsafe Vector3 StandIn(Vector3 seat, float heading)
	{
		double num = (double)heading * Math.PI / 180.0;
		Vector3 vector = seat + new Vector3((0f - (float)Math.Sin(num)) * 1.1f, (float)Math.Cos(num) * 1.1f, 0f);
		Vector3 vector2 = new Vector3(0f, 0f, 0.6f);
		if (Ray.Blocked(seat + vector2, vector + vector2, 17, 0))
		{
			return seat;
		}
		float num2 = default;
		if (MISC.GET_GROUND_Z_FOR_3D_COORD(vector.X, vector.Y, seat.Z + 1.2f, &num2, p4: false) && Math.Abs(num2 - seat.Z) < 0.8f)
		{
			vector.Z = num2;
			return vector;
		}
		return seat;
	}

	private void SitAt(Ped ped, int point, Vector3 seat, float heading)
	{
		SeatTried++;
		Crumbs.Native("seat task: SitAt point");
		NoteSeatTask();
		TASK.TASK_USE_SCENARIO_POINT(ped.Handle, point, "", -1, p4: true, p5: false, 0u, p7: false, -1f, p9: true);
		_seating.Add(new Seating
		{
			Ped = ped,
			Point = point,
			Seat = seat,
			Stand = ped.Position,
			Heading = heading,
			Stage = 0,
			CheckAt = Game.GameTime + 1500
		});
		NaturalNote = "on one of the town's seats";
	}

	private void UpdateSeating()
	{
		for (int num = _seating.Count - 1; num >= 0; num--)
		{
			Seating seating = _seating[num];
			Ped ped = seating.Ped;
			if (ped == null || !ped.Exists() || ped.IsDead || PED.IS_PED_IN_COMBAT(ped.Handle, Game.Player.Character.Handle))
			{
				_seating.RemoveAt(num);
			}
			else
			{
				string text;
				if (_named.TryGetValue(ped.Handle, out var value))
				{
					text = value.Name;
				}
				else
				{
					text = (_worldNemeses.TryGetValue(ped.Handle, out var value2) ? value2.Name : $"ped {ped.Handle}");
				}
				if (PED.IS_PED_USING_ANY_SCENARIO(ped.Handle))
				{
					string text2;
					if (seating.Stage != 0)
					{
						text2 = ((seating.Stage == 1) ? "took the nearest seat (2.5 m)" : "took a seat within 10 m");
					}
					else
					{
						text2 = "sat on the point";
					}
					if (seating.Stage == 0)
					{
						SeatOnPoint++;
					}
					else if (seating.Stage == 1)
					{
						SeatNear++;
					}
					else
					{
						SeatWide++;
					}
					GrudgeLog($"SEAT {text}: {text2} at {ped.Position.X:0},{ped.Position.Y:0},{ped.Position.Z:0}");
					_seating.RemoveAt(num);
				}
				else if (Game.GameTime >= seating.CheckAt)
				{
					if (seating.Stage == 0)
					{
						Crumbs.Native("seat task: seating nearest 2.5 m");
						NoteSeatTask();
						TASK.TASK_USE_NEAREST_SCENARIO_TO_COORD_WARP(ped.Handle, seating.Seat.X, seating.Seat.Y, seating.Seat.Z, 2.5f, -1, p6: true, p7: false, p8: false, p9: false);
						seating.Stage = 1;
						seating.CheckAt = Game.GameTime + 1200;
					}
					else if (seating.Stage == 1)
					{
						Crumbs.Native("seat task: seating nearest 10 m");
						NoteSeatTask();
						TASK.TASK_USE_NEAREST_SCENARIO_TO_COORD_WARP(ped.Handle, seating.Seat.X, seating.Seat.Y, seating.Seat.Z, 10f, -1, p6: true, p7: false, p8: false, p9: false);
						seating.Stage = 2;
						seating.CheckAt = Game.GameTime + 1200;
					}
					else
					{
						SeatFailed++;
						if (ped.Position.DistanceTo(seating.Stand) > 0.8f || Math.Abs(ped.Position.Z - seating.Stand.Z) > 0.5f)
						{
							ENTITY.SET_ENTITY_COORDS(ped.Handle, seating.Stand.X, seating.Stand.Y, seating.Stand.Z, p4: false, p5: false, p6: false, p7: false);
						}
						string text3 = TownIdle[_rng.Next(TownIdle.Length)];
						Vector3 vector = OpenSpot(seating.Stand, seating.Heading, ped.Handle, out var face, out var note);
						if (vector.DistanceTo(ped.Position) > 0.3f)
						{
							ENTITY.SET_ENTITY_COORDS(ped.Handle, vector.X, vector.Y, vector.Z, p4: false, p5: false, p6: false, p7: false);
						}
						ENTITY.SET_ENTITY_HEADING(ped.Handle, face);
						GrudgeLog("SEAT " + text + ": standing - " + note);
						TASK.TASK_START_SCENARIO_IN_PLACE_HASH(ped.Handle, MISC.GET_HASH_KEY(text3), -1, p3: true, 0u, face, p6: false);
						GrudgeLog(string.Format("SEAT {0}: no seat took (point {1}) - standing in front of it, {2}", text, seating.Point, text3.Replace("WORLD_HUMAN_", "").ToLowerInvariant()));
						_seating.RemoveAt(num);
					}
				}
			}
		}
	}

	private unsafe Vector3 OpenSpot(Vector3 at, float preferred, int self, out float face, out string note)
	{
		float num = preferred;
		float num2 = -1f;
		for (int i = 0; i < 8; i++)
		{
			float num3 = preferred + 45f * (float)i;
			float num4 = Room(at, num3);
			if (num4 > num2 + 0.2f)
			{
				num = num3;
				num2 = num4;
			}
		}
		Vector3 vector = at;
		note = $"room {num2:0.0} m";
		if (num2 < 2.5f)
		{
			double num5 = (double)num * Math.PI / 180.0;
			Vector3 vector2 = new Vector3(0f - (float)Math.Sin(num5), (float)Math.Cos(num5), 0f) * Math.Min(1.2f, Math.Max(0.3f, num2 - 0.6f));
			Vector3 vector3 = at + vector2;
			float num6 = default;
			if (MISC.GET_GROUND_Z_FOR_3D_COORD(vector3.X, vector3.Y, at.Z + 1.2f, &num6, p4: false) && Math.Abs(num6 - at.Z) < 1f)
			{
				vector3.Z = num6;
				vector = vector3;
				note += $", cramped - stepped {vector2.Length():0.0} m out";
			}
		}
		if (Room(vector, preferred) >= 3f)
		{
			face = preferred;
			note += ", faces the seat's way";
			return vector;
		}
		face = num;
		float num7 = -1f;
		for (int j = 0; j < 8; j++)
		{
			float num8 = preferred + 45f * (float)j;
			float num9 = Room(vector, num8);
			if (num9 > num7 + 0.2f)
			{
				face = num8;
				num7 = num9;
			}
		}
		note += $", faces the open side ({num7:0.0} m)";
		return vector;
		float Room(Vector3 from0, float h)
		{
			double num10 = (double)h * Math.PI / 180.0;
			Vector3 vector4 = new Vector3(0f - (float)Math.Sin(num10), (float)Math.Cos(num10), 0f);
			Vector3 vector5 = from0 + new Vector3(0f, 0f, 1f) + vector4 * 0.3f;
			if (!Ray.Hit(vector5, vector5 + vector4 * 4f, 17, self, out var at2))
			{
				return 4.3f;
			}
			return at2.DistanceTo(vector5) + 0.3f;
		}
	}

	internal string SeatingDebugLine()
	{
		if (SeatTried != 0)
		{
			return string.Format("seating: {0}/{1} sat ({2} on the point, {3} nearest, {4} within 10 m), {5} standing in front{6}", SeatOnPoint + SeatNear + SeatWide, SeatTried, SeatOnPoint, SeatNear, SeatWide, SeatFailed, (_seating.Count > 0) ? $", {_seating.Count} still going" : "");
