			bool flag = now >= p.DueAt && now <= num6;
			if (p.Known)
			{
				num4++;
			}
			if (flag && num5 < ((p.Kind == "funeral") ? 50f : 150f))
			{
				bool num7;
				if (!(p.Kind == "funeral"))
				{
