			}
			if (((p.Kind == "funeral") & flag) && !p.Live && num5 < 220f)
			{
				NoteGraveSight(p, player);
			}
			if (flag && !p.Live && num5 < 220f && p.Kind != "empty")
			{
				string text = NoSpawnReason(player);
				if (p.Kind == "funeral" && text != null && text == StoryBansWeapons(player.Position))
