	private bool PlayPlan(Plan p, Ped player)
	{
		Vector3 vector = Vector3.Zero;
		bool flag = p.Kind == "habit" || p.Kind == "funeral";
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == p.LeaderId && n.CanHunt && !n.PresumedDead && OffStage(n)) ?? (flag ? null : (from n in Roster
			where n.Gang == p.Gang && n.CanHunt && !n.PresumedDead && n.Rank >= 2 && OffStage(n)
			orderby n.Rank descending
			select n).FirstOrDefault());
		if (nemesisRecord == null)
		{
			if (!flag || _routineNobodySaid.Add(p.Id))
			{
				GrudgeLog("PLAN " + p.Kind + " " + p.Title + ": nobody free to do it right now");
			}
			return false;
		}
		Vector3 vector2 = ((flag && (p.Kind == "funeral" || HabitOf(p).h?.Kind != "ride")) ? Ground(new Vector3(p.X, p.Y, p.Z)) : SnapToRoad(new Vector3(p.X, p.Y, p.Z), 150f));
		if (p.Kind == "funeral")
		{
			Vector3 cem = new Vector3(p.X, p.Y, p.Z);
			if (p.PlotSet && !OnAMark(cem, new Vector3(p.PlotX, p.PlotY, p.PlotZ)))
			{
				p.PlotSet = false;
				GrudgeLog("FUNERAL " + p.Title + ": its plot wasn't on a marked one - picked again");
			}
			if (!p.PlotSet)
			{
				bool flag2 = Plots.Any((Vector3 q) => q.DistanceTo2D(cem) < 200f);
				if (player.Position.DistanceTo2D(cem) > (flag2 ? 220f : 160f))
				{
					return false;
				}
				Vector3 vector3 = FuneralPlot(cem);
				p.PlotX = vector3.X;
				p.PlotY = vector3.Y;
				p.PlotZ = vector3.Z;
				p.PlotSet = true;
				SaveWorld();
			}
			vector2 = new Vector3(p.PlotX, p.PlotY, p.PlotZ);
			float num = player.Position.DistanceTo(vector2);
			NoteGraveSight(p, player);
			bool flag3 = _funeralSeenAt.TryGetValue(p.Id, out var value) && Game.GameTime - value < 20000;
			if (num < 120f && ((num < 60f) | flag3))
			{
				vector = RideInStart(vector2, player, onFoot: true, far: true);
				if (vector == Vector3.Zero)
				{
					return false;
				}
			}
		}
		if (flag && p.Kind == "habit" && HabitOf(p).h?.Kind == "drink")
		{
			vector2 = new Vector3(p.X, p.Y, p.Z);
		}
		bool onFoot = flag && p.Kind == "habit" && HabitOf(p).h?.Kind == "drink";
		Vector3 vector4 = ((p.Kind != "trap" && p.Kind != "funeral") ? RideInStart(vector2, player, onFoot) : vector);
		if (p.Kind != "funeral" && vector4 == Vector3.Zero && !HiddenFromView(player, vector2))
		{
			return false;
		}
		EncounterCard encounterCard = (flag ? RoutineCard(p) : new EncounterCard
		{
			Id = "plan-" + p.Kind,
			Stage = "idle",
			Title = p.Title,
			Standoff = ((p.Kind == "trap") ? new bool?(false) : ((bool?)null)),
			SightRange = ((p.Kind == "trap") ? 70f : 0f),
			Activity = ((p.Kind == "ride" || (p.Gang == "army" && p.Kind == "job")) ? "patrol" : null),
			Cast = new CardCast
			{
				Crew = new List<int> { p.Crew, p.Crew }
			},
			Taunts = ((p.Kind == "trap") ? new List<string> { "Told you he'd come. Now!", "Right where we wanted you.", "Walked right into it, didn't you?" } : null),
			History = ((p.Kind == "trap") ? "SPRANG A TRAP on you at {place}" : ((p.Kind == "alone") ? "CAUGHT WITHOUT HIS MEN at {place}" : "CAUGHT AT A JOB ({kind}) at {place}"))
		});
		string scenario = ((encounterCard.Activity == "patrol") ? null : encounterCard.Activity);
		bool patrol = encounterCard.Activity == "patrol";
		if (vector4 != Vector3.Zero)
		{
			encounterCard.Activity = "patrol";
		}
		_spawnAt = ((vector4 != Vector3.Zero) ? vector4 : vector2);
		try
		{
			SpawnEncounter(nemesisRecord, EncounterKind.Idle, player, encounterCard);
		}
		finally
		{
			_spawnAt = null;
		}
		if (ActiveRecord != nemesisRecord)
		{
			GrudgeLog("PLAN " + p.Kind + " " + p.Title + ": spawn failed - tried again later");
			return false;
		}
		p.Live = true;
		if (p.Kind == "trap")
		{
			p.Engaged = true;
		}
		p.ScarsAt = nemesisRecord.Scars.Count;
		if (vector4 != Vector3.Zero && p.Kind != "funeral")
		{
			try
			{
				BeginRideIn(p, vector2, onFoot, patrol, scenario);
			}
			catch (Exception ex)
			{
				GrudgeLog("RIDEIN failed: " + ex.Message);
			}
		}
		if (flag)
		{
			_wildCameAt = Game.GameTime;
		}
		if (p.Kind == "funeral")
		{
			FuneralStarted(p, player, vector2, (vector4 != Vector3.Zero) ? vector4.DistanceTo(vector2) : 0f);
		}
		GrudgeLog($"PLAN {p.Kind} {p.Title} is happening at {vector2.X:0},{vector2.Y:0} - {nemesisRecord.Name} + {p.Crew}");
		Feed("PLAN " + (p.Lie ? "TRAP" : p.Kind.ToUpperInvariant()) + ": " + p.Title + " - " + p.Place, (p.Kind == "trap") ? Theme.Blood : Theme.Gold, nemesisRecord);
		if (p.Kind == "trap")
		{
			GrudgeNotice("It's a trap.");
		}
		if (p.Known && p.Kind != "trap" && vector4 == Vector3.Zero)
		{
			GrudgeNotice("There they are: " + p.Title + ".");
		}
		if (p.Lie && p.Kind == "trap")
		{
			ExposeLiar(p, "it was a trap");
		}
		return true;
	}

	private unsafe Vector3 SnapToRoad(Vector3 target, float within)
	{
		ulong* ptr = stackalloc ulong[3];
		try
		{
			if (PATHFIND.GET_CLOSEST_VEHICLE_NODE(target.X, target.Y, target.Z, (Vector3*)ptr, 0, 3f, 0f))
			{
				Vector3 p = new Vector3(*(float*)ptr, *(float*)(ptr + 1), *(float*)(ptr + 2));
				if (p.DistanceTo2D(target) < within)
				{
					return Ground(p);
				}
			}
		}
		catch
		{
		}
		return Ground(target);
	}

	private void ResolvePlan(Plan p, Ped player)
	{
		_historyAt = Math.Min(p.DueAt, GameMinutesNow());
		try
		{
			ResolvePlanAt(p, player);
		}
		finally
		{
			_historyAt = null;
		}
	}

	private string JobFailure(Gang g)
	{
		string[] array;
		if (g?.Id == "wapiti")
		{
			array = new string[3] { "the herd had moved on", "soldiers found them first", "the hunt came back empty" };
		}
		else if (g?.Id == "laramie")
		{
			array = new string[5] { "the rancher's hands were sitting up with the herd", "a stock detective was waiting", "the herd stampeded the wrong way", "the cattlemen's association had men on the road", "a storm scattered the stock" };
		}
		else if (g?.Id == "delobo")
		{
			array = new string[5] { "the Army was on the river that night", "the rurales were waiting on the other side", "the train carried soldiers, not money", "the marshal from Armadillo rode them down", "a horse went lame in the canyon" };
		}
		else if (g?.Id == "nightfolk")
		{
			array = new string[6] { "the moon was too bright", "a lantern was seen and the road emptied", "the dogs in Lagras woke the whole town", "the Raiders were on that road that night", "the water was wrong, the elder said", "nobody would go past the old church" };
		}
		else
		{
			array = ((g != null && g.OrdersNotFeelings) ? new string[3] { "the men they were sent for were long gone", "the column came back empty-handed", "bad orders and worse luck" } : new string[6] { "the law was waiting", "a posse rode them down", "the mark had hired guns", "somebody talked", "they were seen coming", "it fell apart at the last minute" });
		}
		return array[_rng.Next(array.Length)];
	}

	private void ResolvePlanAt(Plan p, Ped player)
	{
		p.Done = true;
		Gang gang = Gangs.ById(p.Gang);
		if (ResolveRoutine(p, player))
		{
			return;
		}
		if (IsDestroyed(gang))
		{
			GrudgeLog("PLAN " + p.Title + ": the " + gang.Name + " are finished - it never happened");
			return;
		}
		if (p.Lie)
		{
			if (p.Visited && !p.Live)
			{
				CaughtLying(p);
			}
			p.Outcome = (p.Visited ? "a lie" : "never checked");
			return;
		}
		if (p.Live)
		{
			p.Outcome = "you were there";
			if (p.Kind == "job")
			{
				PurseForJob(gang, ok: false, youThere: true);
			}
			return;
		}
		if (p.Kind == "job" && gang != null && !gang.OrdersNotFeelings && MenOf(gang) == 0)
		{
			p.Outcome = "never happened";
			GrudgeLog("PLAN " + p.Title + ": the " + gang.Name + " have no men left to do it");
			return;
		}
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == p.LeaderId);
		WorldEvent worldEvent = NewEvent("JOB", p.DueAt);
		worldEvent.Gangs.Add(p.Gang ?? "");
		worldEvent.Place = p.Place;
		worldEvent.HasPos = true;
		worldEvent.X = p.X;
		worldEvent.Y = p.Y;
		worldEvent.Z = p.Z;
		bool flag = _rng.Next(100) < ((p.Kind == "alone") ? 100 : (p.Desperate ? 55 : 70));
		bool flag2 = nemesisRecord != null && nemesisRecord.IsAlive && !nemesisRecord.PresumedDead;
		string text = (flag2 ? nemesisRecord.Name : ("the " + (gang?.Name ?? "outfit")));
		if (p.Kind == "job")
		{
			WorldEvent worldEvent2 = worldEvent;
			string title;
			if (gang?.Id == "nightfolk")
			{
				title = (flag ? ("In the night, " + (flag2 ? (text + "'s folk") : "the Night Folk") + " went out to " + p.Title + ". By morning it was done, and nobody saw a thing") : ((flag2 ? (text + "'s folk") : "The Night Folk") + " went out to " + p.Title + " and came back with nothing - " + JobFailure(gang)));
			}
			else if (flag)
			{
				title = (flag2 ? (text + " and his men did it: " + p.Title) : (Cap(text) + " did it: " + p.Title));
			}
			else
			{
				title = (flag2 ? (text + "'s men tried to " + p.Title + " - " + JobFailure(gang)) : (Cap(text) + " tried to " + p.Title + " - " + JobFailure(gang)));
			}
			worldEvent2.Title = title;
			if (nemesisRecord != null && nemesisRecord.IsAlive && !nemesisRecord.PresumedDead && OffStage(nemesisRecord))
			{
				WorldPart worldPart = PartFor(nemesisRecord, flag ? "PULLED IT OFF" : "WENT WRONG", p.Title);
				worldEvent.People.Add(worldPart);
				if (flag)
				{
					AddThought(nemesisRecord, "Flush", "the job that paid", 2, 48, p.DueAt, worldPart);
					GainRankXp(nemesisRecord, 1, "a job that paid");
				}
				else if (_rng.Next(100) < 25 * Config.WorldLethality / 100)
				{
					OffscreenDeath(nemesisRecord, worldEvent, worldPart, "the law", gun: true);
				}
				else
				{
					AddThought(nemesisRecord, "Bitter", "the job that went wrong", -2, 48, p.DueAt, worldPart);
				}
			}
			if (!flag)
			{
				worldEvent.UnnamedDead[gang?.Id ?? "outlaws"] = 1 + _rng.Next(2);
			}
		}
		else
		{
			worldEvent.Title = ((p.Kind == "ride") ? (text + "'s crew rode " + p.Place) : (text + " went about alone " + p.Place));
		}
		worldEvent.Heard = p.Known || WordReachesYou(worldEvent, player);
		Chronicle.Events.Add(worldEvent);
		p.Outcome = (flag ? "done" : "went wrong");
		if (p.Kind == "job")
		{
			PurseForJob(gang, flag, youThere: false, p.Desperate);
		}
		GrudgeLog("PLAN " + p.Kind + " resolved off screen: " + worldEvent.Title);
		if (p.Known)
		{
			GrudgeNotice(worldEvent.Title + ".");
		}
		SaveWorld();
		SaveRoster();
	}

	private void CaughtLying(Plan p)
	{
		p.Done = true;
		p.Outcome = "a lie";
		ExposeLiar(p, (p.Kind == "empty") ? "nobody was there" : "it was a trap");
		string text = Roster.FirstOrDefault((NemesisRecord n) => n.Id == p.ToldBy)?.Name ?? "He";
		GrudgeNotice((p.Kind == "trap") ? (text + " sent you into a trap.") : ("Nobody here. " + text + " lied to you."));
		SaveWorld();
	}

	private void ExposeLiar(Plan p, string how)
	{
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == p.ToldBy);
		if (nemesisRecord != null)
		{
			nemesisRecord.LiedToYou++;
			History(nemesisRecord, "LIED TO YOU about " + (p.ToldAbout ?? "his outfit") + " - " + how, Theme.Warn);
			Feed("LIED " + nemesisRecord.Name + ": about " + (p.ToldAbout ?? "his outfit") + " - " + how, Theme.Warn);
			Remember(nemesisRecord, "Pride", 40, "fooled you");
			SaveRoster();
		}
	}

	private unsafe void RefreshPlanBlips()
	{
		if (!MapSettled())
		{
			_mapPending.Add(RefreshPlanBlips);
			return;
		}
		if (_mapHidden)
		{
			ClearPlanBlips();
			return;
		}
		Dictionary<string, Plan> want = (from plan in Plans
			where plan.Known && !plan.Done && !plan.Visited && plan.Id != null
			group plan by plan.Id).ToDictionary((IGrouping<string, Plan> g) => g.Key, (IGrouping<string, Plan> g) => g.First());
		foreach (string item in _planBlips.Keys.Where((string k) => !want.ContainsKey(k)).ToList())
		{
			int p = _planBlips[item];
			Crumbs.Native("Plans blip remove");
			if (MAP.DOES_BLIP_EXIST(p))
			{
				MAP.REMOVE_BLIP(&p);
			}
			_planBlips.Remove(item);
			_planBlipAt.Remove(item);
		}
		foreach (Plan value5 in want.Values)
		{
			if (_planBlips.TryGetValue(value5.Id, out var value) && !MAP.DOES_BLIP_EXIST(value))
			{
				_planBlips.Remove(value5.Id);
			}
			Vector3 vector = PlanMarkAt(value5);
			if (_planBlips.TryGetValue(value5.Id, out var value2) && _planBlipAt.TryGetValue(value5.Id, out var value3) && value3.DistanceTo2D(vector) > 3f)
			{
				Crumbs.Native("Plans blip remove");
				if (MAP.DOES_BLIP_EXIST(value2))
				{
					MAP.REMOVE_BLIP(&value2);
				}
				_planBlips.Remove(value5.Id);
			}
			if (!_planBlips.ContainsKey(value5.Id))
			{
				_planBlipAt[value5.Id] = vector;
				float x = vector.X;
				float y = vector.Y;
				float z = vector.Z;
				Gang gang = Gangs.ById(value5.Gang);
				NemesisMod nemesisMod = this;
				float x2 = x;
				float y2 = y;
				float z2 = z;
				string text;
				if (gang != null)
				{
					text = gang.Name + ": ";
				}
				else
				{
					text = ((value5.Kind == "funeral") ? "" : "Outlaws: ");
				}
				int value4 = nemesisMod.AddMarkerBlip(x2, y2, z2, text + value5.Title + " - " + WhenText(value5.DueAt));
				_planBlips[value5.Id] = value4;
			}
		}
	}

	private unsafe void ClearPlanBlips()
	{
		Crumbs.Native("Plans blip remove");
		foreach (string item in _planBlips.Keys.ToList())
		{
			int p = _planBlips[item];
			if (MAP.DOES_BLIP_EXIST(p))
			{
				MAP.REMOVE_BLIP(&p);
			}
		}
		_planBlips.Clear();
		_planBlipAt.Clear();
	}

	private Vector3 PlanMarkAt(Plan p)
	{
		Vector3 spot = new Vector3(p.X, p.Y, p.Z);
		if (p.Kind != "funeral")
		{
			return spot;
		}
		if (!p.PlotSet && Plots.Any((Vector3 q) => q.DistanceTo2D(spot) < 200f))
		{
			Vector3 vector = FuneralPlot(spot);
			p.PlotX = vector.X;
			p.PlotY = vector.Y;
			p.PlotZ = vector.Z;
			p.PlotSet = true;
			SaveWorld();
		}
		if (!p.PlotSet)
		{
			return spot;
		}
		return new Vector3(p.PlotX, p.PlotY, p.PlotZ);
	}

	private void BeginProcession(Plan p, Vector3 grave, string scenario)
	{
		List<Ped> men = EncounterMen();
		if (men.Count == 0)
		{
			return;
		}
		_settling.RemoveAll(((Ped ped, int checkAt, string fallback, float heading) s) => s.ped != null && men.Any((Ped m) => m.Handle == s.ped.Handle));
		Procession procession = new Procession
		{
			Plan = p,
			Grave = grave,
			Scenario = (scenario ?? "WORLD_HUMAN_GUARD_LAZY"),
			StartedAt = Game.GameTime,
			StageAt = Game.GameTime
		};
		procession.Road = SnapToRoad(grave, 60f);
		if (procession.Road == Vector3.Zero || procession.Road.DistanceTo2D(grave) > 60f)
		{
			procession.Road = grave;
		}
		procession.BodyAt = GroundOnSpot(grave + new Vector3(0.9f, -1f, 0f));
		foreach (Ped item in men)
		{
			_settleFrom.Remove(item.Handle);
			ClaimBack(item);
			item.BlockPermanentEvents = true;
			TASK.CLEAR_PED_TASKS(item.Handle, p1: false, p2: false);
			if (!item.IsOnMount)
			{
				MountOnHorse(item);
			}
		}
		procession.Carrier = ((men.Count >= 2) ? men.Last() : men[0]);
		int num = PED.GET_MOUNT(procession.Carrier.Handle);
		procession.Horse = ((num != 0) ? new Ped(num) : null);
		NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == p.Dead);
		Model model = ((nemesisRecord != null) ? new Model((int)nemesisRecord.ModelHash) : ((Model)null));
		if (model == null || !model.IsValid || !model.IsPed)
		{
			model = procession.Carrier.Model;
		}
		Vector3 pos = GroundOnSpot(procession.Carrier.Position - procession.Carrier.ForwardVector * 2.5f + new Vector3(1.5f, 0f, 0f));
		Ped ped = SpawnPed((PedHash)model.Hash, pos, procession.Carrier.Heading);
		if (ped != null)
		{
			MakeOurs(ped.Handle);
			if (nemesisRecord != null)
			{
				try
				{
					ApplyScars(ped, nemesisRecord);
				}
				catch
				{
				}
			}
			KlanBody(ped, nemesisRecord?.Gang ?? p.Gang);
			ENTITY.SET_ENTITY_HEALTH(ped.Handle, 0, 0);
			procession.Body = ped;
			procession.LoadAt = Game.GameTime + 1200;
			if (procession.Horse != null)
			{
				ENTITY.SET_ENTITY_NO_COLLISION_ENTITY(ped.Handle, procession.Horse.Handle, p2: false);
				ENTITY.SET_ENTITY_NO_COLLISION_ENTITY(ped.Handle, procession.Carrier.Handle, p2: false);
			}
		}
		_proc = procession;
		ProcessionOrders(force: true);
		GrudgeLog(string.Format("PROCESSION {0}: {1} riding in at a walk from {2:0} m out ({3:0} m from you), the road point {4:0} m from the grave (z {5:0.0}){6}", p.Title, men.Count, men[0].Position.DistanceTo(grave), men[0].Position.DistanceTo(Game.Player.Character.Position), procession.Road.DistanceTo2D(grave), grave.Z, (ped == null) ? " - the body couldn't be made" : ""));
	}

	private void ProcessionOrders(bool force = false)
	{
		Procession proc = _proc;
		if (proc == null || proc.Stage != 0 || (!force && Game.GameTime < proc.NextOrder))
		{
			return;
		}
		proc.NextOrder = Game.GameTime + 3000;
		Ped activeNemesisPed = _activeNemesisPed;
		if (activeNemesisPed == null || !activeNemesisPed.Exists())
		{
			return;
		}
		Vector3 road = proc.Road;
		bool flag = ENTITY.GET_ENTITY_SPEED(activeNemesisPed.Handle) < 0.5f;
		if (force | flag)
		{
			if (!force)
			{
				proc.Standing++;
			}
			TASK.TASK_GO_TO_COORD_ANY_MEANS(activeNemesisPed.Handle, road.X, road.Y, road.Z, 2.2f, 0, p6: false, 786603, 0f);
			if (proc.Standing == 3)
			{
				GrudgeLog($"PROCESSION {proc.Plan?.Title}: the leader keeps stopping ({activeNemesisPed.Position.DistanceTo2D(road):0} m to go) - told again");
			}
		}
		int num = 0;
		foreach (Ped item in _followers.Where((Ped f) => f != null && f.Exists() && !f.IsDead))
		{
			if (force || ENTITY.GET_ENTITY_SPEED(item.Handle) < 0.5f)
			{
				TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(item.Handle, activeNemesisPed.Handle, (num % 2 == 0) ? 1.2f : (-1.2f), -4f - 3.5f * (float)(num / 2), 0f, 2.2f, -1, 2.5f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
			}
			num++;
		}
	}

	private void ProcessionTick()
	{
		Procession proc = _proc;
		if (proc == null)
		{
			return;
		}
		Ped activeNemesisPed = _activeNemesisPed;
		List<Ped> list = EncounterMen();
		if (_enc == null || activeNemesisPed == null || !activeNemesisPed.Exists() || activeNemesisPed.IsDead || _enc.Engaged || _enc.StandoffUntil > 0)
		{
			if (proc.Body != null && proc.Body.Exists() && (proc.ByHand || proc.Shouldered))
			{
				ENTITY.DETACH_ENTITY(proc.Body.Handle, p1: true, p2: true);
			}
			foreach (Ped item in list)
			{
				item.BlockPermanentEvents = false;
			}
			GrudgeLog($"PROCESSION {proc.Plan?.Title}: interrupted at stage {proc.Stage} - the encounter's rules now");
			_proc = null;
			return;
		}
		LoadBodyOnHorse(proc);
		switch (proc.Stage)
		{
		case 0:
			RideInStage(proc, activeNemesisPed, list);
			break;
		case 1:
			if (!list.Any((Ped m) => m.IsOnMount) || Game.GameTime - proc.StageAt >= 6000)
			{
				StartWalkIn(proc, list);
			}
			break;
		case 2:
			WalkInStage(proc, list);
			break;
		}
	}

	private void LoadBodyOnHorse(Procession pr)
	{
		if (pr.Body == null || !pr.Body.Exists() || pr.Stage != 0 || pr.OnHorse || pr.ByHand || Game.GameTime < pr.LoadAt)
		{
			return;
		}
		if (pr.Horse == null || !pr.Horse.Exists())
		{
			pr.LoadAt = int.MaxValue;
			return;
		}
		if (!pr.LoadTried)
		{
			pr.LoadTried = true;
			pr.CheckAt = Game.GameTime + 1500;
			uint p = 0u;
			try
			{
				p = Function.Call<uint>(3814558401569769835uL, new InputArgument[2]
				{
					pr.Body.Handle,
					0
				});
			}
			catch
			{
			}
			try
			{
				TASK.TASK_CARRIABLE(pr.Body.Handle, p, pr.Horse.Handle, 24, 512);
				return;
			}
			catch (Exception ex)
			{
				GrudgeLog("PROCESSION body onto the horse (game's carry) failed: " + ex.Message);
				return;
			}
		}
		if (Game.GameTime < pr.CheckAt)
		{
			return;
		}
		if (PED._GET_CARRIER_AS_MOUNT(pr.Body.Handle) == pr.Horse.Handle || ENTITY.IS_ENTITY_ATTACHED_TO_ENTITY(pr.Body.Handle, pr.Horse.Handle))
		{
			pr.OnHorse = true;
			GrudgeLog("PROCESSION body: across the horse's back (the game's carry)");
			return;
		}
		int num = ENTITY.GET_ENTITY_BONE_INDEX_BY_NAME(pr.Horse.Handle, "SKEL_Spine3");
		if (num < 0)
		{
			num = 0;
		}
		ENTITY.ATTACH_ENTITY_TO_ENTITY(pr.Body.Handle, pr.Horse.Handle, num, 0f, (num == 0) ? (-0.45f) : 0f, (num == 0) ? 0.75f : 0.35f, 0f, 0f, 90f, p9: false, p10: false, p11: false, p12: false, 2, p14: true, p15: false, p16: false);
		pr.ByHand = true;
		GrudgeLog($"PROCESSION body: the game's carry onto the horse didn't take (carriable {TASK.GET_IS_CARRIABLE_ENTITY(pr.Body.Handle)}) - tied across its back by hand (bone {num})");
	}

	private void RideInStage(Procession pr, Ped lead, List<Ped> men)
	{
		Vector3 position = lead.Position;
		bool flag = position.DistanceTo2D(pr.Road) < 10f || position.DistanceTo2D(pr.Grave) < 25f;
		bool flag2 = Game.GameTime - pr.StartedAt > 200000;
		if (!flag && !flag2)
		{
			if (Game.GameTime >= pr.NextCheck)
			{
				pr.NextCheck = Game.GameTime + 20000;
				float num = position.DistanceTo2D(pr.Road);
				bool flag3 = pr.LastLeft > 0f && pr.LastLeft - num < 5f && Game.GameTime - pr.StartedAt > 15000;
				GrudgeLog(string.Format("PROCESSION {0}: {1:0} m to go, {2:0} m from you, {3:0.0} m/s{4}", pr.Plan?.Title, num, position.DistanceTo(Game.Player.Character.Position), ENTITY.GET_ENTITY_SPEED(lead.Handle), flag3 ? " - stuck" : ""));
				if (flag3 && HiddenFromView(Game.Player.Character, position + new Vector3(0f, 0f, 1.5f)))
				{
					Vector3 vector = pr.Road - position;
					vector.Z = 0f;
					float num2 = vector.Length();
					if (num2 > 1f)
					{
						vector *= 1f / num2;
					}
					Vector3 vector2 = SnapToRoad(position + vector * Math.Min(25f, Math.Max(0f, num2 - 10f)), 20f);
					if (vector2 != Vector3.Zero && HiddenFromView(Game.Player.Character, vector2 + new Vector3(0f, 0f, 1.5f)))
					{
						int num3 = 0;
						foreach (Ped man in men)
						{
							int num4 = PED.GET_MOUNT(man.Handle);
							Vector3 vector3 = vector2 - vector * (4f * (float)num3);
							num3++;
							ENTITY.SET_ENTITY_COORDS((num4 != 0) ? num4 : man.Handle, vector3.X, vector3.Y, vector3.Z + 0.3f, p4: false, p5: false, p6: false, p7: false);
						}
						GrudgeLog($"PROCESSION {pr.Plan?.Title}: moved along {vector2.DistanceTo(position):0} m (out of your sight)");
						ProcessionOrders(force: true);
					}
				}
				pr.LastLeft = num;
			}
			ProcessionOrders();
			return;
		}
		pr.Stage = 1;
		pr.StageAt = Game.GameTime;
		foreach (Ped man2 in men)
		{
			if (man2.IsOnMount)
			{
				TASK.TASK_DISMOUNT_ANIMAL(man2.Handle, 0, 0uL, 0uL, 0uL, 0);
			}
		}
		GrudgeLog(string.Format("PROCESSION {0}: {1} after {2} s, {3:0} m from the grave", pr.Plan?.Title, flag ? "there" : "out of time - they get down here", (Game.GameTime - pr.StartedAt) / 1000, position.DistanceTo2D(pr.Grave)));
		if (pr.Plan != null && pr.Plan.Known && Game.Player.Character.Position.DistanceTo(pr.Grave) < 200f)
		{
			GrudgeNotice("There they are: " + pr.Plan.Title + ".");
		}
	}

	private void StartWalkIn(Procession pr, List<Ped> men)
	{
		pr.Stage = 2;
		pr.StageAt = Game.GameTime;
		pr.PickAt = Game.GameTime;
		double num = _rng.NextDouble() * Math.PI * 2.0;
		for (int i = 0; i < men.Count; i++)
		{
			double num2 = num + (double)i * (Math.PI * 2.0 / (double)Math.Max(3, men.Count));
			Vector3 vector = GroundOnSpot(pr.BodyAt + new Vector3((float)Math.Cos(num2) * 2.6f, (float)Math.Sin(num2) * 2.6f, 0f));
			pr.Ring[men[i].Handle] = vector;
			if (men[i] != pr.Carrier || pr.Body == null)
			{
				WalkTo(men[i], vector, straight: false);
			}
		}
		if (pr.Body == null || !pr.Body.Exists())
		{
			pr.BodyDown = true;
			return;
		}
		if (pr.ByHand)
		{
			ENTITY.DETACH_ENTITY(pr.Body.Handle, p1: true, p2: true);
		}
		TASK.CLEAR_PED_TASKS(pr.Carrier.Handle, p1: false, p2: false);
		TASK.TASK_PICKUP_CARRIABLE_ENTITY(pr.Carrier.Handle, pr.Body.Handle);
		GrudgeLog(string.Format("PROCESSION {0}: off their horses - {1} takes the body down ({2}), {3} walk in", pr.Plan?.Title, WhoIs(pr.Carrier.Handle), pr.OnHorse ? "from the horse" : (pr.ByHand ? "untied" : "off the ground"), men.Count - 1));
	}

	private static void WalkTo(Ped m, Vector3 p, bool straight)
	{
		if (straight)
		{
			TASK.TASK_GO_STRAIGHT_TO_COORD(m.Handle, p.X, p.Y, p.Z, 1f, -1, 40000f, 0.3f, 0);
		}
		else
		{
			TASK.TASK_FOLLOW_NAV_MESH_TO_COORD(m.Handle, p.X, p.Y, p.Z, 1f, -1, 0.6f, 0, 0f);
		}
	}

	private bool CarrierHolds(Procession pr)
	{
		if (!pr.Shouldered && !PED.IS_PED_CARRYING_SOMETHING(pr.Carrier.Handle))
		{
			return PED._GET_CARRIER_AS_PED(pr.Body.Handle) == pr.Carrier.Handle;
		}
		return true;
	}

	private void WalkInStage(Procession pr, List<Ped> men)
	{
		bool flag = Game.GameTime >= pr.NextOrder;
		if (flag)
		{
			pr.NextOrder = Game.GameTime + 3000;
			pr.Standing++;
		}
		bool straight = pr.Standing % 2 == 0;
		Ped carrier = pr.Carrier;
		if (!pr.BodyDown && carrier != null && carrier.Exists() && !carrier.IsDead && pr.Body != null && pr.Body.Exists())
		{
			bool flag2 = CarrierHolds(pr);
			if (!pr.Picked)
			{
				int num = Game.GameTime - pr.PickAt;
				if (flag2)
				{
					pr.Picked = true;
					WalkTo(carrier, pr.BodyAt, straight: false);
					GrudgeLog($"PROCESSION body: taken up (the game's carry) after {num} ms - carried in");
				}
				else if (!pr.PickRetried && num > 3500)
				{
					pr.PickRetried = true;
					TASK.CLEAR_PED_TASKS(carrier.Handle, p1: false, p2: false);
					TASK.TASK_PICKUP_CARRIABLE_ENTITY(carrier.Handle, pr.Body.Handle);
				}
				else if (num > 7000)
				{
					int num2 = ENTITY.GET_ENTITY_BONE_INDEX_BY_NAME(carrier.Handle, "SKEL_R_Clavicle");
					ENTITY.ATTACH_ENTITY_TO_ENTITY(pr.Body.Handle, carrier.Handle, Math.Max(0, num2), 0.15f, 0.05f, 0f, 0f, 90f, 90f, p9: false, p10: false, p11: false, p12: false, 2, p14: true, p15: false, p16: false);
					pr.Shouldered = true;
					pr.Picked = true;
					TASK.CLEAR_PED_TASKS(carrier.Handle, p1: false, p2: false);
					WalkTo(carrier, pr.BodyAt, straight: false);
					GrudgeLog($"PROCESSION body: the game's pick-up didn't take - over his shoulder by hand (bone {num2})");
				}
			}
			else if (!pr.Placing)
			{
				if (carrier.Position.DistanceTo2D(pr.BodyAt) < 1.8f)
				{
					pr.Placing = true;
					pr.PlaceAt = Game.GameTime;
					if (!pr.Shouldered & flag2)
					{
						TASK.TASK_PLACE_CARRIED_ENTITY_AT_COORD(carrier.Handle, pr.Body.Handle, pr.BodyAt.X, pr.BodyAt.Y, pr.BodyAt.Z, 1f, 0);
					}
					else
					{
						LayBodyAt(pr, "off his shoulder");
					}
				}
				else if (flag && ENTITY.GET_ENTITY_SPEED(carrier.Handle) < 0.3f)
				{
					WalkTo(carrier, pr.BodyAt, straight);
				}
				if (!flag2 && !pr.Placing)
				{
					pr.Picked = false;
					pr.PickRetried = false;
					pr.PickAt = Game.GameTime;
					TASK.TASK_PICKUP_CARRIABLE_ENTITY(carrier.Handle, pr.Body.Handle);
					GrudgeLog("PROCESSION body: dropped on the way - taken up again");
				}
			}
			else if (!flag2)
			{
				pr.BodyDown = true;
				GrudgeLog("PROCESSION body: laid down by the grave (the carrier set him down)");
				WalkTo(carrier, pr.Ring.TryGetValue(carrier.Handle, out var value) ? value : pr.BodyAt, straight: false);
			}
			else if (Game.GameTime - pr.PlaceAt > 6000)
			{
				LayBodyAt(pr, "the setting down didn't finish");
			}
		}
		else if (!pr.BodyDown)
		{
			LayBodyAt(pr, "the carrier was gone");
		}
		bool flag3 = true;
		foreach (Ped man in men)
		{
			Vector3 value2;
			if (man == carrier && !pr.BodyDown)
			{
				flag3 = false;
			}
			else if (pr.Ring.TryGetValue(man.Handle, out value2) && !(man.Position.DistanceTo2D(value2) < 1.3f))
			{
				flag3 = false;
				if (flag && ENTITY.GET_ENTITY_SPEED(man.Handle) < 0.3f)
				{
					WalkTo(man, value2, straight);
				}
			}
		}
		int num3 = Game.GameTime - pr.StageAt;
		if ((pr.BodyDown & flag3) || num3 > 45000)
		{
			Gather(pr, men, flag3 ? "all there" : $"{num3 / 1000} s on");
		}
	}

	private void LayBodyAt(Procession pr, string how)
	{
		pr.BodyDown = true;
		if (!(pr.Body == null) && pr.Body.Exists())
		{
			if (pr.Carrier != null && pr.Carrier.Exists() && PED.IS_PED_CARRYING_SOMETHING(pr.Carrier.Handle))
			{
				PED.DETACH_CARRIABLE_ENTITY(pr.Body.Handle, p1: true, p2: true);
			}
			ENTITY.DETACH_ENTITY(pr.Body.Handle, p1: true, p2: true);
			pr.Shouldered = false;
			ENTITY.SET_ENTITY_COORDS(pr.Body.Handle, pr.BodyAt.X, pr.BodyAt.Y, pr.BodyAt.Z + 0.1f, p4: false, p5: false, p6: false, p7: false);
			if (pr.Carrier != null && pr.Carrier.Exists())
			{
				WalkTo(pr.Carrier, pr.Ring.TryGetValue(pr.Carrier.Handle, out var value) ? value : pr.BodyAt, straight: false);
			}
			GrudgeLog($"PROCESSION body: laid down by the grave ({how}) at z {pr.BodyAt.Z:0.0}");
		}
	}

	private void Gather(Procession pr, List<Ped> men, string why)
	{
		if (!pr.BodyDown)
		{
			LayBodyAt(pr, "it was time");
		}
		foreach (Ped man in men)
		{
			float num = HeadingTo(man.Position, pr.BodyAt);
			ENTITY.SET_ENTITY_HEADING(man.Handle, num);
			TASK.TASK_START_SCENARIO_IN_PLACE_HASH(man.Handle, MISC.GET_HASH_KEY(pr.Scenario), -1, p3: true, 0u, num, p6: false);
			man.BlockPermanentEvents = false;
		}
		pr.Stage = 3;
		GrudgeLog("PROCESSION " + pr.Plan?.Title + ": gathered round the body (" + why + ") - " + pr.Scenario);
		_proc = null;
	}

	private bool QuestionFits(Interrogation it, QuestionRow q)
	{
		string[] array = (q.Requires ?? "").Split(new char[1] { '&' }, StringSplitOptions.RemoveEmptyEntries);
		for (int i = 0; i < array.Length; i++)
		{
			switch (array[i].Trim())
			{
			case "gang":
				if (it.Gang == null)
				{
					return false;
				}
				break;
			case "named":
				if (it.Who == null)
				{
					return false;
				}
				break;
			case "boss":
				if (it.Who == null || BossOf(it.Who) == null)
				{
					return false;
				}
				break;
			case "officer":
				if (it.Who == null || !IsOfficer(it.Who))
				{
					return false;
				}
				break;
			case "top":
				if (it.Who == null || it.Gang?.Tiers == null || it.Gang.Tiers.Length == 0 || it.Who.Rank < it.Gang.Tiers[0].MinRank)
				{
					return false;
				}
				break;
			case "camps":
				if (it.Gang == null || Camps.ForGang(it.Gang.Id).Length == 0)
				{
					return false;
				}
				break;
			case "kin":
				if (it.Who == null || KinOf(it.Who).Count == 0)
				{
					return false;
				}
				break;
			case "funeral":
				if (FuneralToTell(it.Gang) == null)
				{
					return false;
				}
				break;
			case "news":
				if (FuneralToTell(it.Gang) == null && !Roster.Any((NemesisRecord n) => n.Gang == it.Gang?.Id && n.IsAlive && !n.PresumedDead && n != it.Who && n.Rank >= 1 && n.Rank < 4))
				{
					return false;
				}
				break;
			}
		}
		return true;
	}

	private static bool IsBigIntel(QuestionRow q)
	{
		if (q != null)
		{
			return BigIntel.Contains(q.Answer);
		}
		return false;
	}

	private int IntelCap(Interrogation it)
	{
		Personality personality = it.Temper ?? Personality.Cold;
		if (personality == Personality.Coward || personality == Personality.Greedy || personality == Personality.Drifter || (it.Rec != null && Quirks.Has(it.Rec, "traitor")))
		{
			return 2;
		}
		if (personality == Personality.Loyal || personality == Personality.Proud || personality == Personality.Cold)
		{
			return 1;
		}
		return (int)(1 + (uint)Seeds.Stable("intel/" + (it.Rec?.Name ?? it.Ped?.Handle.ToString() ?? "")) % 2u);
	}

	private int IntelSoFar(Interrogation it)
	{
		return Math.Max(it.IntelGiven, it.Rec?.IntelGiven ?? 0);
	}

	private bool IntelSpent(Interrogation it)
	{
		return IntelSoFar(it) >= IntelCap(it);
	}

	private bool Answered(Interrogation it, QuestionRow q)
	{
		if (!it.AnsweredNow.Contains(q.Id))
		{
			if (q.Once && it.Rec?.Asked != null)
			{
				if (!it.Rec.Asked.Contains(q.Id))
				{
					return it.Rec.Asked.Any((string a) => Questions.Merged.TryGetValue(a, out var value) && value == q.Id);
				}
				return true;
			}
			return false;
		}
		return true;
	}

	private int QuestionNeed(Interrogation it, QuestionRow q)
	{
		return Math.Max(0, Math.Min(95, it.CampNeed + q.Need));
	}

	private int QuestionChance(Interrogation it, QuestionRow q)
	{
		int num = QuestionNeed(it, q);
		if (it.Terror < (float)num)
		{
			return 0;
		}
		int num2 = (int)Math.Round((it.Terror - (float)num) * it.Tw);
		return Math.Max(3, Math.Min(90, it.Common + num2 + q.Odds + it.BribeBonus));
	}

	private int GateState(Interrogation it)
	{
		int num = (it.ScaredSinceThreat ? 1 : 0) + ((Game.GameTime < it.NextAskAt) ? 2 : 0);
		QuestionRow[] all = Questions.All;
		foreach (QuestionRow questionRow in all)
		{
			it.Locks.TryGetValue(questionRow.Id, out var value);
			num = num * 31 + ((it.Terror >= (float)QuestionNeed(it, questionRow)) ? 1 : 0) * 2 + ((value > 0f && it.Terror < value) ? 1 : 0) + (TooScaredToLie(it) ? 4 : 0);
		}
		return num;
	}

	private bool TooScaredToLie(Interrogation it)
	{
		return it.Terror >= (float)(it.CampNeed + 50);
	}

	private int LieChance(Interrogation it, QuestionRow q, out string why)
	{
		why = "";
		if (!q.Lies)
		{
			return 0;
		}
		if (TooScaredToLie(it))
		{
			why = "too scared to lie";
			return 0;
		}
		NemesisRecord rec = it.Rec;
		if (rec == null)
		{
			why = "a nobody, 15";
			return 15;
		}
		if (Quirks.Has(rec, "honest"))
		{
			why = "honest to a fault";
			return 0;
		}
		List<string> parts = new List<string>();
		int c = 10;
		Add((50 - Mind.F(rec, "Honesty")) / 2, "honesty");
		if (it.Temper == Personality.Loyal)
		{
			Add(15, "loyal");
		}
		if (it.Temper == Personality.Coward)
		{
			Add(-10, "coward");
		}
		Add((rec.Hate - 50) / 6, "hate");
		Add(-(int)((it.Terror - (float)QuestionNeed(it, q)) / 2f), "fear");
		if (it.Bribed && (it.Temper == Personality.Greedy || Mind.N(rec, "Money") >= 60))
		{
			Add(-20, "paid");
		}
		if (Quirks.Has(rec, "braggart"))
		{
			Add(10, "braggart");
		}
		if (Quirks.Has(rec, "traitor"))
		{
			Add(-15, "traitor");
		}
		Add(-10 * Math.Min(3, rec.LiedToYou), "caught before");
		c = Math.Max(0, Math.Min(75, c));
		why = string.Join(", ", parts);
		return c;
		void Add(int v, string w)
		{
			if (v != 0)
			{
				c += v;
				parts.Add($"{w} {v:+0;-0}");
			}
		}
	}

	private void BuildQuestionOptions(Convo c)
	{
		Interrogation it = c.It;
		string[] cats = Questions.Cats;
		foreach (string cat in cats)
		{
			List<QuestionRow> list = Questions.All.Where((QuestionRow q) => q.Cat == cat && QuestionFits(it, q)).ToList();
			if (list.Count == 0)
			{
				continue;
			}
			bool flag = it.OpenCat == cat;
			bool spent = IntelSpent(it);
			int num = Enumerable.Count(list, (QuestionRow q) => !Answered(it, q) && (!spent || !IsBigIntel(q)));
			list = list.Where((QuestionRow q) => !Answered(it, q) && (!spent || !IsBigIntel(q))).ToList();
			c.Options.Add(new ConvoOption
			{
				Key = "cat:" + cat,
				Text = cat + "...",
				Cat = true,
				Open = flag,
				Enabled = true,
				Note = ((num > 0) ? null : (spent ? "he won't say another word" : "nothing more he'd tell"))
			});
			if (!flag)
			{
				continue;
			}
			foreach (QuestionRow item in list)
			{
				int num2 = QuestionNeed(it, item);
				int num3 = RollOdds(it, item);
				it.Locks.TryGetValue(item.Id, out var value);
				string text;
				if (Answered(it, item))
				{
					text = "answered";
				}
				else if (spent && IsBigIntel(item))
				{
					text = "he won't say another word";
				}
				else if (it.Terror < (float)num2 && !Unscared(it))
				{
					text = "not scared enough";
				}
				else
				{
					text = ((value > 0f && it.Terror < value) ? "scare him more" : null);
				}
				bool num4 = text == "answered" || text == "he won't say another word";
				if (text == null && Game.GameTime < it.NextAskAt)
				{
					text = "he's answering";
				}
				bool flag2 = text == "scare him more" || text == "he's answering";
				if (!num4 && !flag2 && it.Terror >= 85f)
				{
					text = null;
				}
				c.Options.Add(new ConvoOption
				{
					Key = "q:" + item.Id,
					Text = item.Text,
					Indent = 1,
					Odds = ((text == null) ? num3 : (-1)),
					Enabled = (text == null),
					Note = text
				});
			}
		}
		if (!it.Bribed && it.Rec != null)
		{
			int num5 = BribeCost(it);
			bool female = it.Ped != null && it.Ped.Exists() && !PED.IS_PED_MALE(it.Ped.Handle);
			bool flag3 = Unscared(it);
			c.Options.Add(new ConvoOption
			{
				Key = "ibribe",
				Text = Pron.Her($"[Pay him ${num5}]", female),
				Enabled = (!flag3 && CashDollars >= num5),
				Note = (flag3 ? "not scared of you" : ((CashDollars >= num5) ? null : "not enough money"))
			});
		}
		string text2;
		if (it.ThreatsUsed >= 3)
		{
			text2 = "used up";
		}
		else
		{
			text2 = ((!it.ScaredSinceThreat) ? "scare him first" : null);
		}
		c.Options.Add(new ConvoOption
		{
			Key = "ithreat",
			Text = (_debugOn ? $"[Threaten]  {it.ThreatsUsed}/3" : "[Threaten]"),
			Enabled = (text2 == null),
			Note = text2
		});
		c.Options.Add(Unscared(it) ? new ConvoOption
		{
			Key = "idone",
			Text = "That's all."
		} : new ConvoOption
		{
			Key = "irelease",
			Text = "Let him go."
		});
	}

	private int BribeCost(Interrogation it)
	{
		return 10 + 5 * Math.Max(1, it.Rec?.Rank ?? 1);
	}

	private bool ToggleCategory(Convo c, string cat, bool? open = null)
	{
		Interrogation it = c.It;
		bool flag = open ?? (it.OpenCat != cat);
		it.OpenCat = (flag ? cat : null);
		string key = "cat:" + cat;
		BuildOptions(c);
		c.Sel = Math.Max(0, c.Options.FindIndex((ConvoOption o) => o.Key == key) + (flag ? 1 : 0));
		if (c.Sel >= c.Options.Count)
		{
			c.Sel = c.Options.Count - 1;
		}
		return true;
	}

	private int RollOdds(Interrogation it, QuestionRow q)
	{
		if (q == null)
		{
			return 0;
		}
		if (Unscared(it))
		{
			return 0;
		}
		int num = (it.AskedAny ? QuestionChance(it, q) : FirstAskOdds(it, q, QuestionChance(it, q)));
		if (it.Terror >= 85f)
		{
			num = Math.Max(num, (int)Math.Round(40f + (it.Terror - 85f) * 3f));
		}
		return num;
	}

	private int FirstAskOdds(Interrogation it, QuestionRow q, int odds)
	{
		float num = (it.Temper ?? Personality.Cold) switch
		{
			Personality.Loyal => -0.2f, 
			Personality.Hothead => 0f, 
			Personality.Greedy => 0.15f, 
			Personality.Drifter => 0.2f, 
			Personality.Coward => 0.35f, 
			_ => -0.1f, 
		};
		float num2 = Math.Max(0f, it.Terror - (float)QuestionNeed(it, q)) / 100f;
		float num3 = Math.Max(0.15f, Math.Min(1f, 0.35f + num + num2));
		return Math.Max(0, (int)Math.Round((float)odds * num3));
	}

	private static bool MaxFear(Interrogation it)
	{
		return it.Terror >= 99.5f;
	}

	private string ReasonHeWontSay(Interrogation it, QuestionRow q)
	{
		Personality personality = it.Temper ?? Personality.Cold;
		string text = LeaderAsSaidBy(it.Gang, it.Rec) ?? ((it.Gang != null && IsLeader(it.Gang, it.Rec)) ? "my own men" : "the boss");
		if (Answered(it, q))
		{
			string[] array = new string[3] { "I already told you that. Nothing's changed since.", "I said it once. Saying it twice won't make it truer.", "You heard me the first time." };
			return array[_rng.Next(array.Length)];
		}
		string[] array2 = personality switch
		{
			Personality.Drifter => new string[2] { "That's the whole of what I know. I just ride with 'em, I don't run 'em.", "Nobody tells a man like me more than that." }, 
			Personality.Hothead => new string[2] { "I'm done talking! You hear me? Done!", "That's it! That's all of it, damn you!" }, 
			Personality.Greedy => new string[2] { "That's all I know that's worth anything - and you got it for free.", "There's nothing else to sell, mister. You cleaned me out." }, 
			Personality.Proud => new string[2] { "You've had all you're getting. Shoot me if you like.", "I've shamed myself enough for one day. No more." }, 
			Personality.Loyal => new string[2]
			{
				"I've said more than I should have. The rest dies with me.",
				"I gave you what I gave you. I won't sell out " + text + " any further."
			}, 
			Personality.Coward => new string[2]
			{
				"I can't - I told you too much already. " + text + " finds out, I'm a dead man either way.",
				"Please - that's all I had. I swear on my mother, there's nothing more."
			}, 
			_ => new string[2]
			{
				"That's everything they ever told me. They don't tell men like me the rest.",
				"Any more than that and " + text + " would know it came from me."
			}, 
		};
		return array2[_rng.Next(array2.Length)];
	}

	private void AskQuestion(Convo c, ConvoOption o)
	{
		Interrogation it = c.It;
		QuestionRow questionRow = Questions.All.FirstOrDefault((QuestionRow x) => "q:" + x.Id == o.Key);
		if (questionRow == null)
		{
			return;
		}
		NemesisRecord rec = it.Rec;
		Personality personality = it.Temper ?? Personality.Cold;
		Ped character = Game.Player.Character;
		if (Game.GameTime < it.NextAskAt)
		{
			return;
		}
		it.NextAskAt = Game.GameTime + 2500;
		if (Answered(it, questionRow) || (IntelSpent(it) && IsBigIntel(questionRow)))
		{
			c.Line = ReasonHeWontSay(it, questionRow);
			Feed("ASKED " + Speaker(it) + " (" + questionRow.Cat.ToLowerInvariant() + ": " + questionRow.Answer + "): he's done with that - \"" + c.Line + "\"", Theme.Dim, rec);
			if (!Unscared(it) || !Strain(c, it, 1f, "too many questions"))
			{
				BuildOptions(c);
			}
			return;
		}
		int num = _rng.Next(100);
		bool flag = !it.AskedAny;
		it.AskedAny = true;
		bool flag2 = num < o.Odds;
		bool flag3 = !flag2 && questionRow.Lies && (personality == Personality.Cold || personality == Personality.Loyal) && !TooScaredToLie(it) && it.Rec != null && !Unscared(it) && !Quirks.Has(it.Rec, "honest") && _rng.Next(100) < 45;
		if (flag3)
		{
			flag2 = true;
		}
		if (flag2)
		{
			int num2 = LieChance(it, questionRow, out var why);
			bool flag4 = flag3 || (num2 > 0 && _rng.Next(100) < num2);
			if (flag3)
			{
				why = ((why == "") ? "" : (why + ", ")) + "lied instead of refusing";
			}
			Say(it.Ped, it.Ped.IsHogtied ? "PLEAD_HOGTIED" : "PLEAD", character);
			it.AnsweredNow.Add(questionRow.Id);
			it.Empty = false;
			c.Line = Answer(it, questionRow, flag4);
			if (questionRow.Once && rec != null && !it.Empty && !rec.Asked.Contains(questionRow.Id))
			{
				rec.Asked.Add(questionRow.Id);
			}
			if (!it.Empty && !flag4 && IsBigIntel(questionRow))
			{
				it.IntelGiven = IntelSoFar(it) + 1;
				if (rec != null)
				{
					rec.IntelGiven = it.IntelGiven;
				}
				if (IntelSpent(it))
				{
					string text = InterroLines.Pick("lock", it.Gang, personality, _rng, null, null, LeaderOut(it.Gang, it.Rec)) ?? "That's all you're getting. I won't say another word.";
					c.Line = c.Line + " " + text;
					Feed($"INTEL {Speaker(it)} has given up all he will ({IntelSoFar(it)} of {IntelCap(it)}) - he won't say another word about his outfit", Theme.Dim, rec);
				}
			}
			if (c.Line != null && c.Line.Length < 70 && _rng.Next(100) < 55)
			{
				string text2 = InterroLines.Pick((it.Terror >= 60f) ? "lead_scared" : "lead", it.Gang, personality, _rng, null, null, LeaderOut(it.Gang, it.Rec));
				if (text2 != null)
				{
					c.Line = text2 + " " + c.Line;
				}
			}
			Feed(string.Format("ASKED {0} ({1}: {2}): {3}%, rolled {4} -> TALKS{5}", Speaker(it), questionRow.Cat.ToLowerInvariant(), questionRow.Answer, o.Odds, num, questionRow.Lies ? string.Format(" - lie {0}%{1}{2}", num2, (why != "") ? (" (" + why + ")") : "", flag4 ? " LIED" : "") : ""), (flag4 && _debugOn) ? Theme.Warn : Theme.Good, rec);
			if (questionRow.Answer == "bargain" && it.BargainStruck)
			{
				EndConvoSoon(c, "bargain");
				return;
			}
		}
		else
		{
			it.Round++;
			if (rec != null)
			{
				int hate = rec.Hate;
				rec.AddHate(2);
				CapScuffle(rec, hate);
			}
			c.Line = InterroLines.Pick((it.Terror >= 55f) ? "refuse_scared" : "refuse", it.Gang, personality, _rng, BossOf(rec)?.Name, null, LeaderOut(it.Gang, it.Rec)) ?? Defiance[_rng.Next(Defiance.Length)];
			Say(it.Ped, DefiantLines[_rng.Next(DefiantLines.Length)], character);
			it.Tries.TryGetValue(questionRow.Id, out var value);
			value++;
			it.Tries[questionRow.Id] = value;
			if (value >= Balance.InterroTriesPerScare)
			{
				it.Locks[questionRow.Id] = it.Terror + (float)Balance.InterroScareToRetry;
				if (!Unscared(it))
				{
					c.Line = c.Line + " " + (InterroLines.Pick("lock", it.Gang, personality, _rng, null, null, LeaderOut(it.Gang, it.Rec)) ?? "...I ain't saying another word about that.");
				}
			}
			Feed(string.Format("ASKED {0} ({1}: {2}): {3}%, {4} -> refuses{5}", Speaker(it), questionRow.Cat.ToLowerInvariant(), questionRow.Answer, o.Odds, flag ? $"first question, rolled {num}" : $"rolled {num}", Unscared(it) ? " (not scared of you)" : ""), Theme.Dim, rec);
			if (Unscared(it) && Strain(c, it, 1f, "too many questions"))
			{
				return;
			}
		}
		it.LastChance = ChanceToTalk(it, character);
		if (rec != null)
		{
			SaveRoster();
		}
		BuildOptions(c);
	}

	private void EndConvoSoon(Convo c, string why)
	{
		if (c.It?.Rec != null)
		{
			SaveRoster();
		}
		c.EndAt = Game.GameTime + 3500;
		c.Options.Clear();
		GrudgeLog("INTERRO ends soon (" + why + ")");
	}

	private void ReopenQuestions(Interrogation it, bool atCap = false)
	{
		foreach (string item in (from kv in it.Locks
			where it.Terror >= kv.Value || (atCap && kv.Value > 100f)
			select kv.Key).ToList())
		{
			it.Locks.Remove(item);
			it.Tries[item] = Balance.InterroTriesPerScare - 1;
		}
	}

	private string Answer(Interrogation it, QuestionRow q, bool lying)
	{
		NemesisRecord rec = it.Who;
		Gang g = it.Gang;
		float num = it.Terror - (float)QuestionNeed(it, q);
		switch (q.Answer)
		{
		case "catch":
		{
			string[] array2;
			if (!(num >= 30f) && !(it.Terror >= 85f))
			{
				array2 = ((!(num >= 12f)) ? new string[3] { "ride", "habit", "alone" } : new string[3] { "habit", "alone", "ride" });
			}
			else
			{
				array2 = new string[3] { "alone", "habit", "ride" };
			}
			string result = null;
			for (int num2 = 0; num2 < array2.Length; num2++)
			{
				result = Try(array2[num2], lying && num2 == 0);
				if (!it.Empty | lying)
				{
					break;
				}
			}
			GrudgeLog(string.Format("INTERROGATION catch your boss: {0} (fear {1:+0;-0} past the line - tried {2})", it.Empty ? "nothing" : "told", num, string.Join(" / ", array2)));
			return result;
		}
		case "news":
		{
			Plan plan2 = FuneralToTell(g);
			string[] array4 = ((plan2 == null || plan2.DueAt - GameMinutesNow() >= 2880) ? new string[2] { "shakeup", "funeral" } : new string[2] { "funeral", "shakeup" });
			foreach (string key in array4)
			{
				string result3 = Try(key, lie: false);
				if (!it.Empty)
				{
					return result3;
				}
			}
			return Nothing(it, "Nothing. Same as always.");
		}
		case "holedup":
			it.AskedCamp = true;
			if (lying)
			{
				return Try("camp", lie: true);
			}
			if (rec != null && IsOfficer(rec) && num >= 20f)
			{
				string text3 = Try("hideout", lie: false);
				if (!it.Empty)
				{
					if (num < 40f)
					{
						return text3;
					}
					string text4 = Try("camp", lie: false);
					bool empty = it.Empty;
					it.Empty = false;
					if (!empty)
					{
						return text3 + " " + text4;
					}
					return text3;
				}
			}
			return Try("camp", lie: false);
		case "stores":
		{
			string[] array3 = ((!(num >= 10f)) ? new string[2] { "supplies", "treasury" } : new string[2] { "treasury", "supplies" });
			string text7 = Try(array3[0], lie: false);
			bool empty2 = it.Empty;
			if (!empty2 && num < 25f)
			{
				return text7;
			}
			string text8 = Try(array3[1], lie: false);
			bool empty3 = it.Empty;
			if (empty2 & empty3)
			{
				it.Empty = true;
				return text7;
			}
			it.Empty = false;
			if (!empty2)
			{
				if (!empty3)
				{
					return text7 + " " + text8;
				}
				return text7;
			}
			return text8;
		}
		case "orders":
			return AnswerOrders(it, lying);
		case "wants":
		{
			List<Goal> goals = rec.Goals;
			if (goals != null && goals.Count > 0 && !rec.WantsKnown)
			{
				rec.WantsKnown = true;
				Feed("WANTS " + rec.Name + ": " + string.Join("; ", rec.Goals.Select((Goal x) => x.Text)), Theme.Gold, rec);
			}
			Goal goal = rec.Goals?.FirstOrDefault();
			if (goal != null)
			{
				if (!(goal.Type == "Avenge") || !(goal.Target == "you"))
				{
					if (!(goal.Type == "Settle"))
					{
						if (!(goal.Type == "Rise"))
						{
							if (!(goal.Type == "Rich"))
							{
								if (!(goal.Type == "Prove"))
								{
									return "I just want to " + goal.Text + ".";
								}
								return "To show 'em I ain't nobody. Starting with you.";
							}
							return "Money. Enough to stop running.";
						}
						return "To be more than a gun for hire. I'll run my own men one day.";
					}
					return "Out. I want out of all this. Somewhere nobody knows me.";
				}
				return "What do I want? You. In the ground.";
			}
			return "Get through the winter. Same as any man.";
