				});
				ChronicleDeed("intel", Speaker(it) + " gave up " + nemesisRecord6.Name + "'s hideout", CampOf(nemesisRecord6)?.Label ?? "", null, nemesisRecord6.Gang, worldPart4, PartFor(nemesisRecord6, "GIVEN UP", CampOf(nemesisRecord6)?.Label));
			}
