			}
			if (TreasuryRobbedNow(g))
			{
				return Nothing(it, "After what you did? It's not where it was. Nobody's told me where it went.");
			}
			RevealTreasury(g, Speaker(it));
			rec.AddHate(15);
			NemesisRecord nemesisRecord3 = HolderOf(campSite);
			if (nemesisRecord3 != null)
			{
				History(nemesisRecord3, (nemesisRecord3 == it.Rec) ? ("GAVE UP the money he keeps (" + campSite.Label + ")") : ("GIVEN UP: " + Speaker(it) + " told you where the money's kept (" + campSite.Label + ")"), Theme.Warn);
			}
			try
			{
				WorldPart worldPart = ((it.Rec != null) ? PartFor(it.Rec, "TALKED", "under questioning") : new WorldPart
				{
					Name = Speaker(it),
					Outcome = "TALKED",
					Note = "under questioning"
				});
				ChronicleDeed("intel", Speaker(it) + " gave up where the " + g.Name + " keep their money", campSite.Label, null, g.Id, worldPart);
			}
			catch
			{
			}
			if (nemesisRecord3 == null || nemesisRecord3 != it.Rec)
			{
				return "Strongboxes... " + campSite.Label + "." + ((nemesisRecord3 != null) ? (" " + nemesisRecord3.Name + " sits on them.") : "") + " They'll skin me for this.";
			}
			return "Strongboxes... " + campSite.Label + ". Mine to sit on - till you came along. They'll skin me for this.";
		}
		case "supplies":
		{
			if (!KnowsWhere(rec, g, "supplies"))
			{
				return Nothing(it, NotToldMe(rec, "the supplies"));
			}
			CampSite campSite2 = SupplyCampOf(g);
			if (campSite2 == null)
			{
				return Nothing(it, (g == Gangs.Army) ? "The Army's fed by the government. Wagons come in from the railheads." : "We ain't got stores to speak of. Not any more.");
			}
			NemesisRecord nemesisRecord4 = HolderOf(campSite2);
			if (nemesisRecord4 == null && IsSupplyCache(g))
			{
				if (SupplyCacheKnown(g))
				{
					return Nothing(it, "You know where. " + campSite2.Label + ". Nobody's camp now.");
				}
				RevealSupplyCache(g, campSite2, Speaker(it));
				rec.AddHate(10);
				ReplyNotice("INTEL: the " + g.Name + " supplies are still at " + campSite2.Label + ", with no camp round them. Marked on your map.");
				try
				{
					WorldPart worldPart2 = ((it.Rec != null) ? PartFor(it.Rec, "TALKED", "under questioning") : new WorldPart
					{
						Name = Speaker(it),
						Outcome = "TALKED",
						Note = "under questioning"
					});
					ChronicleDeed("intel", Speaker(it) + " gave up where the " + g.Name + " keep their supplies", campSite2.Label, null, g.Id, worldPart2);
				}
				catch
				{
				}
				NemesisRecord nemesisRecord5 = SupplyKeeper(g);
				NemesisRecord rec2 = it.Rec;
				if (rec2 != null && rec2.Gang == g.Id && rec2.CampId == null && rec2.IsAlive && !rec2.Paralyzed && (nemesisRecord5 == null || rec2.Rank > nemesisRecord5.Rank || (rec2.Rank == nemesisRecord5.Rank && string.CompareOrdinal(rec2.Id ?? "", nemesisRecord5.Id ?? "") < 0)))
				{
					nemesisRecord5 = rec2;
				}
				if (nemesisRecord5 == null || nemesisRecord5 != it.Rec)
				{
					return "Crates, feed, the guns... still at " + campSite2.Label + ". Nobody's camp now" + ((nemesisRecord5 != null) ? (" - " + nemesisRecord5.Name + " will be watching it") : " - nobody left to watch it") + ".";
				}
				return "Crates, feed, the guns... still at " + campSite2.Label + ". Nobody's camp now. They'll be wanting me to watch it.";
			}
			if (nemesisRecord4 == null)
			{
				return Nothing(it, "They moved it all. Don't know where.");
			}
			bool flag = nemesisRecord4 == it.Rec;
			if (nemesisRecord4.CampKnown)
			{
				return Nothing(it, flag ? ("You know the place. My camp - " + campSite2.Label + ".") : ("You know the place. " + nemesisRecord4.Name + "'s camp - " + campSite2.Label + "."));
			}
			RevealCamp(nemesisRecord4, found: false);
			Hold.KnowSupplies(g, campSite2);
			RedoCampBlip(campSite2.Id);
			rec.AddHate(10);
			History(nemesisRecord4, flag ? ("GAVE UP the supplies he keeps (" + campSite2.Label + ")") : ("GIVEN UP: " + Speaker(it) + " told you where the supplies are kept (" + campSite2.Label + ")"), Theme.Warn);
			ReplyNotice("INTEL: the " + g.Name + " keep their supplies at " + campSite2.Label + ". Marked on your map.");
			GrudgeLog("SUPPLY " + g.Name + ": you know the supply camp now - " + campSite2.Label + " (from " + Speaker(it) + ")");
			try
			{
				WorldPart worldPart3 = ((it.Rec != null) ? PartFor(it.Rec, "TALKED", "under questioning") : new WorldPart
				{
					Name = Speaker(it),
					Outcome = "TALKED",
					Note = "under questioning"
				});
				ChronicleDeed("intel", Speaker(it) + " gave up where the " + g.Name + " keep their supplies", campSite2.Label, null, g.Id, worldPart3);
			}
			catch
			{
			}
			if (!flag)
			{
				return "Crates, feed, the guns... it's all at " + campSite2.Label + ". " + nemesisRecord4.Name + " keeps it.";
			}
			return "Crates, feed, the guns... it's all at " + campSite2.Label + ". My camp. I keep it.";
		}
		case "people":
			return ConfessKin(it);
		case "past":
		{
			RevealPast(rec, "why he rides", "born", "youth", "work", "gang", "war", "crime", "loss");
			int hate = rec.Hate;
			SoftenHate(rec, 3);
			string result2;
			if (Mind.V(rec, "Money") < 2)
			{
				if (Mind.V(rec, "Gang") < 2)
				{
					if (Mind.V(rec, "Family") < 2)
					{
						PastEntry pastEntry = rec.Past?.LastOrDefault((PastEntry e) => e.Kind == "crime" || e.Kind == "war");
						result2 = ((pastEntry != null) ? ("After " + LowerFirst(pastEntry.Text).TrimEnd('.') + "... where else was I gonna go?") : "Ain't nothing else for a man like me.");
					}
					else
					{
						result2 = "I got people to feed. You think I'd be out here otherwise?";
					}
				}
				else
				{
					result2 = "They're all I got. They took me in when nobody would.";
				}
			}
			else
			{
				result2 = "Money. Same as you, don't lie.";
			}
			Feed("PAST " + rec.Name + ": why he rides - hate " + Delta(hate, rec.Hate), Theme.Gold, rec);
			return result2;
		}
		case "worstgrudge":
		{
			List<NemesisRecord> source = (from n in Roster
				where n.Gang == g.Id && n.IsAlive && !n.PresumedDead && n != rec
				orderby n.Hate descending
				select n).ToList();
			NemesisRecord man = source.FirstOrDefault();
			if (man != null && man.Paralyzed && _rng.Next(100) >= 25)
			{
				man = source.FirstOrDefault((NemesisRecord n) => !n.Paralyzed) ?? man;
			}
			if (man == null)
			{
				return Nothing(it, "Nobody. They're all dead, thanks to you.");
			}
			man.Touch();
			string text;
			if (man.TimesKilledPlayer > 0)
			{
				text = "he's killed you before and he'll do it again";
			}
			else if (man.KinId != null && Roster.Any((NemesisRecord k) => k.Id == man.KinId && !k.IsAlive))
			{
				text = "you killed his kin";
			}
			else if (man.ScarredByYou)
			{
				text = "you marked him";
			}
			else
			{
				text = ((man.Origin == GrudgeOrigin.GangMember) ? "you've crossed his outfit one time too many" : (Regex.Replace(man.Origin.ToString(), "(?<=[a-z])(?=[A-Z])", " ").ToLowerInvariant() + " - he don't forget"));
			}
			Intent intent = IntentOf(man);
			Feed(string.Format("INTEL {0}: hates you most in the {1} (hate {2}{3}) - {4}", man.Name, g.Name, man.Hate, (intent.ToString() != "None") ? $", {intent}" : "", text), Theme.Gold);
			History(man, "NAMED by " + Speaker(it) + " as the man who wants you dead most", Theme.Dim);
			ReplyNotice("INTEL: " + man.Name + " wants you dead more than any of them.");
			if (man.Paralyzed)
			{
				return man.Name + ". " + char.ToUpper(text[0]) + text.Substring(1) + ". Not that he'll ever walk again - but he'll pay someone who can.";
			}
			return man.Name + ". " + char.ToUpper(text[0]) + text.Substring(1) + ". He won't stop.";
		}
		case "bargain":
			return Bargain(it);
		default:
			return "...";
		}
		string Try(string answer, bool lie)
		{
			it.Empty = false;
			return Answer(it, new QuestionRow
			{
				Id = q.Id,
				Cat = q.Cat,
				Answer = answer,
				Lies = q.Lies,
				Need = q.Need
			}, lie);
		}
	}

	private int GrudgeScoreFloor(NemesisRecord r)
	{
		return SocialFloor(r);
	}

	private static string LowerFirst(string s)
	{
		if (!string.IsNullOrEmpty(s))
		{
			return char.ToLowerInvariant(s[0]) + s.Substring(1);
		}
		return s;
	}

	private static string Nothing(Interrogation it, string line)
	{
		it.Empty = true;
		return line;
	}

	private bool KnowsWhere(NemesisRecord rec, Gang g, string what)
	{
		if (rec == null || g == null)
		{
			return false;
		}
		bool flag = g.Tiers != null && g.Tiers.Length != 0 && rec.Rank >= g.Tiers[0].MinRank;
		bool flag2 = what == "money";
		int num;
		if (flag)
		{
			num = (flag2 ? 80 : 90);
		}
		else if (IsOfficer(rec))
		{
			num = (flag2 ? 15 : 40);
		}
		else
		{
			num = (flag2 ? 4 : 15);
		}
		int num2 = (int)((uint)Seeds.Stable("knows-" + what + "/" + rec.Name) % 100u);
		bool flag3 = num2 < num;
		GrudgeLog(string.Format("INTERROGATION {0} knows where the {1} {2} kept? {3}% ({4}), rolled {5} - {6}", rec.Name, what, (what == "money") ? "is" : "are", num, flag ? "under the leader" : (IsOfficer(rec) ? "an officer" : "low down"), num2, flag3 ? "yes" : "no"));
		return flag3;
	}

	private string NotToldMe(NemesisRecord rec, string what)
	{
		string[] array = new string[4]
		{
			"They don't tell men like me where " + what + "'s kept! I swear it!",
			char.ToUpper(what[0]) + what.Substring(1) + "? Only the boss's men know that. Not me.",
			"I don't know! Ask the ones up top - they never told me nothin'.",
			"You think they'd trust me with " + what + "? Look at me."
		};
		return array[(uint)Seeds.Stable("nottold/" + rec?.Name) % (uint)array.Length];
	}

	private string AnswerOrders(Interrogation it, bool lying)
	{
		Gang gang = it.Gang;
		NemesisRecord rec = it.Rec;
		if (lying)
		{
			(string, string, int)[] array = JobsOf(gang);
			string[] array2 = JobTownsOf(gang);
			if (array.Length == 0 || array2.Length == 0)
			{
				return Nothing(it, "Orders? We ride where we're told.");
			}
			(string, string, int) tuple = array[_rng.Next(array.Length)];
			string text = array2[_rng.Next(array2.Length)];
			Vector3 vector = JobSpot(text);
			if (vector == Vector3.Zero)
			{
				return Nothing(it, "Orders? We ride where we're told.");
			}
			Plan plan = MakeLie("their orders", rec, gang, vector, tuple.Item2.Replace("{t}", text), GameMinutesNow() + (long)(10 + _rng.Next(30)) * 60L, tuple.Item1.Replace("{t}", text));
			IntelNotice(plan);
			return "We're to " + plan.Title + ". " + char.ToUpper(WhenText(plan.DueAt)[0]) + WhenText(plan.DueAt).Substring(1) + ". That's the truth!";
		}
		Plan plan2 = FactionJob(gang);
		if (plan2 == null)
		{
			return Nothing(it, "Orders? We ride where we're told, when we're told.");
		}
		if (plan2.Known)
		{
			return Nothing(it, "You know already - " + plan2.Title + ". " + char.ToUpper(WhenText(plan2.DueAt)[0]) + WhenText(plan2.DueAt).Substring(1) + ".");
		}
		plan2.Known = true;
		plan2.ToldBy = rec?.Id;
		plan2.ToldAbout = "their orders";
		SaveWorld();
		IntelNotice(plan2);
		string text2 = AgendaText(gang);
		object obj;
		if (!IsLeader(gang, rec))
		{
			string text3 = LeaderAsSaidBy(gang, rec);
			obj = ((text3 != null) ? (text3 + " means") : null);
		}
		else
		{
			obj = "I mean";
		}
		string text4 = (string)obj;
		return "We're to " + plan2.Title + ". " + char.ToUpper(WhenText(plan2.DueAt)[0]) + WhenText(plan2.DueAt).Substring(1) + "." + ((text2 != null && text4 != null) ? (" " + text4 + " to " + text2 + ".") : "") + " Now let me be!";
	}

	private void IntelNotice(Plan p)
	{
		ReplyNotice("INTEL (unconfirmed): " + (Gangs.ById(p.Gang)?.Name ?? "they") + " - " + p.Title + ", " + p.Place + ", " + WhenText(p.DueAt) + ". Marked on your map.");
		Feed("INTEL ? " + p.Title + " - " + p.Place + " - " + WhenText(p.DueAt), Theme.Gold);
		RefreshPlanBlips();
	}

	private string DayText(int key)
	{
		_ = key / 10000;
		int val = key / 100 % 100;
		int num = key % 100;
		return $"{Months[Math.Max(0, Math.Min(11, val))]} {num}";
	}

	private string ConfessCampUnsure(Interrogation it)
	{
		NemesisRecord nemesisRecord = IntelTarget(it);
		bool flag = nemesisRecord?.CampKnown ?? true;
		string result = ConfessCamp(it);
		if (nemesisRecord != null && !flag && nemesisRecord.CampKnown)
		{
			nemesisRecord.CampUnsure = true;
			RedoCampBlip(nemesisRecord.CampId);
			return result;
		}
		it.Empty = true;
		return result;
	}

	private string LieAboutCamp(Interrogation it, NemesisRecord target, string about)
	{
		Gang gang = it.Gang;
		List<CampSite> list = (from s in Camps.ForGang(gang.Id)
			where !Roster.Any((NemesisRecord n) => n.CampId == s.Id && n.IsAlive) && !IsCleared(s) && !WetSite(s)
			select s).ToList();
		if (target == null || list.Count == 0)
		{
			return Nothing(it, "I don't know nothin' about the camps! I just ride where I'm told!");
		}
		CampSite campSite = list[_rng.Next(list.Count)];
		Plan plan = MakeLie(about, it.Rec, gang, SitePos(campSite), campSite.Label, GameMinutesNow(), target.Name + "'s " + (campSite.Hideout ? "hideout" : "camp"));
		plan.WindowMin = 4320;
		SaveWorld();
		if (it.Rec != null)
		{
			it.Rec.GaveCamp = true;
		}
		it.CampDone = true;
		IntelNotice(plan);
		return target.Name + "... he's at " + campSite.Label + ". Go see for yourself!";
	}

	private string Bargain(Interrogation it)
	{
		NemesisRecord r = it.Rec;
		Personality t = it.Temper ?? Personality.Cold;
		it.BargainStruck = true;
		bool she = it.Ped != null && it.Ped.Exists() && Models.Female((uint)it.Ped.Model.Hash);
		if (r == null)
		{
			return Line("bargain_plead", "I got a family! Please! I'll ride out of here tonight!");
		}
		long num = GameMinutesNow();
		try
		{
			KeeperLeft(r, "bought his life");
		}
		catch (Exception ex)
		{
			GrudgeLog("HOLDINGS keeper left failed: " + ex.Message);
		}
		if (r.BargainAt > 0 && num >= r.BargainAt && num - r.BargainAt < 10080)
		{
			it.BargainStruck = false;
			return Line("bargain_again", "I already bought my life off you. You want more, you'll have to kill me.");
		}
		r.BargainAt = num;
		bool flag = Quirks.Has(r, "traitor") || (t == Personality.Coward && it.Terror >= 60f) || Mind.F(r, "Loyalty") < 30;
		if ((t == Personality.Greedy || Mind.N(r, "Money") >= 60) && r.Wealth != Wealth.Poor)
		{
			int num2 = 5 + r.Rank * 5 + ((r.Wealth == Wealth.Rich) ? 25 : 5);
			PayPlayer(num2 * 100);
			if (it.Ped != null && it.Ped.Exists() && !it.Ped.IsHogtied)
			{
				GesturePay(it.Ped, youPay: false);
			}
			History(r, $"BOUGHT HIS LIFE from you: ${num2}", Theme.Warn);
			Feed($"BARGAIN {r.Name}: paid you ${num2} for his life", Theme.Gold, r);
			Remember(r, "Shame", 45, "paid for his life");
			return Line("bargain_pay", "Here - ${dollars}. All I got on me. Take it and we never met.").Replace("{dollars}", num2.ToString());
		}
		if (flag && r.Gang != null)
		{
			r.Informant = true;
			r.InformedDay = GameDayKey();
			History(r, "TURNED INFORMER for you - to save his skin", Theme.Warn);
			Feed("BARGAIN " + r.Name + ": he'll send you word of what the " + Gangs.ById(r.Gang)?.Name + " are planning", Theme.Gold, r);
			Remember(r, "Fear", 60, "turned informer");
			return Line("bargain_inform", "I'll tell you what they're planning. Every job, before they ride. Just let me live.");
		}
		if (t == Personality.Proud || t == Personality.Loyal || t == Personality.Hothead)
		{
			r.OwesYou = true;
			History(r, "OWES YOU HIS LIFE - he'll back down once", Theme.Warn);
			Feed("BARGAIN " + r.Name + ": he owes you his life (backs down the next time)", Theme.Gold, r);
			Remember(r, "Shame", 55, "owes you his life");
			return Line("bargain_owe", "Then I owe you. I pay my debts. Once. After that, we're square.");
		}
		r.Fear = Math.Max(r.Fear, 90);
		Mind.SetGoal(r, new Goal
		{
			Type = "Settle",
			Text = "get away from you - out of this life",
			Since = GameMinutesNow()
		});
		History(r, "SWORE TO LEAVE THE TERRITORY to save his life", Theme.Warn);
		Feed("BARGAIN " + r.Name + ": swore he'd leave the territory (fear 90, wants out)", Theme.Gold, r);
		return Line("bargain_leave", "I'll go. Tonight. You'll never see my face again, I swear on my mother.");
		string Line(string sit, string fallback)
		{
			return InterroLines.Pick(sit, it.Gang, t, _rng, null, null, LeaderOut(it.Gang, r), she) ?? fallback;
		}
	}

	private void UpdateInformants()
	{
		int num = GameDayKey();
		foreach (NemesisRecord item in Roster.Where((NemesisRecord n) => n.Informant && n.IsAlive && !n.PresumedDead).ToList())
		{
			if (DaysBetweenKeys(item.InformedDay, num) < 2)
			{
				continue;
			}
			item.InformedDay = num;
			if (OffStage(item) && _rng.Next(100) < 10)
			{
				item.Informant = false;
				WorldEvent worldEvent = NewEvent("FEUD", GameMinutesNow());
				worldEvent.Gangs.Add(item.Gang ?? "");
				worldEvent.Place = "in camp";
				worldEvent.Title = "The " + Gangs.ById(item.Gang)?.Name + " found out " + item.Name + " was talking to you";
				WorldPart worldPart = PartFor(item, "FOUND OUT", "an informer");
				worldEvent.People.Add(worldPart);
				OffscreenDeath(item, worldEvent, worldPart, "his own gang", gun: true);
				worldEvent.Heard = true;
				Chronicle.Events.Add(worldEvent);
				DeathNotice("The " + Gangs.ById(item.Gang)?.Name + " found out " + item.Name + " was your informer.");
				SaveWorld();
				SaveRoster();
				continue;
			}
			Plan plan = FactionJob(Gangs.ById(item.Gang));
			if (plan != null && !plan.Known)
			{
				plan.Known = true;
				plan.ToldBy = item.Id;
				plan.ToldAbout = "their orders (letter)";
				SaveWorld();
				ReplyNotice("A letter from " + item.Name + ": the " + Gangs.ById(item.Gang)?.Name + " mean to " + plan.Title + " - " + WhenText(plan.DueAt) + ".");
				Feed("INFORMER " + item.Name + ": " + plan.Title + " - " + WhenText(plan.DueAt), Theme.Gold, item);
				RefreshPlanBlips();
			}
		}
	}

	private static int DaysBetweenKeys(int a, int b)
	{
		if (a <= 0)
		{
			return 99;
		}
		return (int)(A(b) - A(a)).TotalDays;
		static DateTime A(int k)
		{
			try
			{
				return new DateTime(k / 10000, k / 100 % 100 + 1, Math.Max(1, k % 100));
			}
			catch
			{
				return DateTime.MinValue;
			}
		}
	}

	internal static int XpNeed(int rank)
	{
		return 2 * Math.Max(1, rank);
	}

	internal void GainRankXp(NemesisRecord r, int amount, string why)
	{
		if (r == null || !r.IsAlive || amount <= 0 || r.Rank >= 5)
		{
			return;
		}
		if (Mind.Has(r, "Settle"))
		{
			GrudgeLog("RANK " + r.Name + ": no xp for " + why + " - he wants out");
			return;
		}
		double num = 0.5 + (double)Mind.F(r, "Ambition") / 100.0;
		if (Mind.Has(r, "Rise"))
		{
			num *= 1.5;
		}
		int num2 = Math.Max(1, (int)Math.Round((double)amount * num));
		r.RankXp = Math.Min(r.RankXp + num2, XpNeed(r.Rank));
		GrudgeLog($"RANK {r.Name} +{num2} xp ({why}, x{num:0.00}) -> {r.RankXp}/{XpNeed(r.Rank)} at rank {r.Rank}");
		if (r.Gang == null)
		{
			TryRankUp(r, why);
		}
		SaveRoster();
	}

	private bool TryRankUp(NemesisRecord r, string why)
	{
		if (r.Rank >= 5 || r.RankXp < XpNeed(r.Rank) || Mind.Has(r, "Settle"))
		{
			return false;
		}
		if (r.PresumedDead)
		{
			return false;
		}
		r.RankXp -= XpNeed(r.Rank);
		int rank = r.Rank;
		r.Rank++;
		History(r, $"ROSE TO RANK {r.Rank} - {why}", Theme.Gold);
		Remember(r, "Pride", 45, $"made a name for himself - rank {r.Rank}", null);
		Feed($"RANK {r.Name}: {rank} -> {r.Rank} ({why})", Theme.Gold, r);
		if (r == ActiveRecord && _activeNemesisPed != null && _activeNemesisPed.Exists())
		{
			ApplyRankStats(_activeNemesisPed, r, fullHeal: false);
		}
		GrudgeNotice($"{r.FullName} is getting a name for himself: rank {r.Rank}.");
		return true;
	}

	private int PromoteWithinTiers(Gang gang, List<NemesisRecord> living, List<(string, (int r, int g, int b))> lines, List<WorldPart> rankParts)
	{
		int num = 0;
		for (int t = 0; t < gang.Tiers.Length; t++)
		{
			int max = ((t == 0) ? 5 : (gang.Tiers[t - 1].MinRank - 1));
			foreach (NemesisRecord item in living.Where((NemesisRecord n) => n.Rank >= gang.Tiers[t].MinRank && n.Rank <= max && n.Rank < max && n.RankXp >= XpNeed(n.Rank) && !Mind.Has(n, "Settle")).ToList())
			{
				int rank = item.Rank;
				item.RankXp -= XpNeed(item.Rank);
				item.Rank++;
				string text = Backstory.Singular(gang.Tiers[t].Label);
				History(item, $"RANK {rank} -> {item.Rank} as {text} in the {gang.Name} - earned it", gang.Accent);
				Remember(item, "Pride", 40, $"moved up to rank {item.Rank}", null);
				lines.Add(($"{item.Name} earns rank {item.Rank} ({text})", Theme.Text));
				WorldPart worldPart = PartFor(item, "PROMOTED", "earned it");
				worldPart.Effects.Add($"rank {rank} -> {item.Rank}");
				rankParts.Add(worldPart);
				GrudgeLog($"RANK {gang.Id} {item.Name} {rank} -> {item.Rank} within {text} (xp left {item.RankXp})");
				num++;
			}
		}
		return num;
	}

	private static string PairKey(string a, string b)
	{
		if (string.CompareOrdinal(a, b) >= 0)
		{
			return b + "|" + a;
		}
		return a + "|" + b;
	}

	private WarRecord LiveWar(string a, string b)
	{
		return Wars.FirstOrDefault((WarRecord w) => (w.A == a && w.B == b) || (w.A == b && w.B == a));
	}

	internal static int LoreRelation(string a, string b)
	{
		if (a == null || b == null || a == b)
		{
			return 100;
		}
		Gang gang = Gangs.ById(a);
		Gang gang2 = Gangs.ById(b);
		if (gang?.Relations != null && gang.Relations.TryGetValue(b, out var value))
		{
			return value;
		}
		if (gang2?.Relations != null && gang2.Relations.TryGetValue(a, out var value2))
		{
			return value2;
		}
		return 0;
	}

	internal int Relation(string a, string b)
	{
		if (a == null || b == null || a == b)
		{
			return 100;
		}
		if (!RelMap.TryGetValue(PairKey(a, b), out var value))
		{
			return LoreRelation(a, b);
		}
		return value;
	}

	internal string RelationCause(string a, string b)
	{
		if (!RelWhy.TryGetValue(PairKey(a, b), out var value))
		{
			return "old blood between them";
		}
		return value;
	}

	internal void ShiftRelation(string a, string b, int delta, string why, bool force = false)
	{
		if (a == null || b == null || a == b || delta == 0 || Gangs.ById(a) == null || Gangs.ById(b) == null)
		{
			return;
		}
		int num = Relation(a, b);
		if (force)
		{
			int num2 = Math.Max(-100, Math.Min(100, num + delta));
			RelMap[PairKey(a, b)] = num2;
			if (!string.IsNullOrEmpty(why))
			{
				RelWhy[PairKey(a, b)] = why;
			}
			SaveWorld();
			GrudgeLog($"RELATION {Gangs.ById(a).Name} / {Gangs.ById(b).Name}: {num} -> {num2} ({why}, forced)");
			return;
		}
		if (delta < 0 && num <= -80)
		{
			delta = Math.Min(-1, (int)Math.Round((double)delta / 3.0));
		}
		if (delta > 0 && num >= 80)
		{
			delta = Math.Max(1, (int)Math.Round((double)delta / 3.0));
		}
		string key = PairKey(a, b) + "|" + GameDayKey();
		_relSwing.TryGetValue(key, out var value);
		int num3 = Math.Max(-20, Math.Min(20, value + delta)) - value;
		if (num3 == 0)
		{
			GrudgeLog($"RELATION {Gangs.ById(a).Name} / {Gangs.ById(b).Name}: {why} - no more change today (moved {value:+0;-0} already)");
			return;
		}
		if (_relSwing.Count > 400)
		{
			_relSwing.Clear();
		}
		_relSwing[key] = value + num3;
		delta = num3;
		int num4 = Math.Max(-100, Math.Min(100, num + delta));
		if (num4 != num)
		{
			string key2 = PairKey(a, b);
			RelMap[key2] = num4;
			if (!string.IsNullOrEmpty(why))
			{
				RelWhy[key2] = why;
			}
			SaveWorld();
			GrudgeLog($"RELATION {Gangs.ById(a).Name} / {Gangs.ById(b).Name}: {num} -> {num4} ({why})");
			int warLine = Config.WarLine;
			if (num > warLine && num4 <= warLine)
			{
				Feed("BAD BLOOD the " + Gangs.ById(a).Name + " and the " + Gangs.ById(b).Name + " are ready to go to war (" + why + ")", Theme.Blood);
			}
			else if (num <= warLine && num4 > warLine)
			{
				Feed("COOLING the " + Gangs.ById(a).Name + " and the " + Gangs.ById(b).Name + " back off from war (" + why + ")", Theme.Dim);
			}
		}
	}

	internal static string RelationWord(int r)
	{
		if (r > -70)
		{
			if (r > -35)
			{
				if (r > -15)
				{
					if (r >= 15)
					{
						if (r >= 40)
						{
							return "friendly";
						}
						return "on terms";
					}
					return "wary";
				}
				return "hostile";
			}
			return "at war";
		}
		return "blood feud";
	}

	internal void DriftRelations(int days)
	{
		List<string> list = (from g in Gangs.All
			where !g.StoryOnly
			select g.Id).ToList();
		for (int num = 0; num < list.Count; num++)
		{
			for (int num2 = num + 1; num2 < list.Count; num2++)
			{
				string text = list[num];
				string text2 = list[num2];
				string key = PairKey(text, text2);
				if (!RelMap.TryGetValue(key, out var value))
				{
					continue;
				}
				int num3 = Math.Max(-100, LoreRelation(text, text2) - GrievanceOf(text, text2));
				int num4 = value;
				if (num4 <= -80)
				{
					num3 = Math.Max(num3, -70);
				}
				for (int num5 = 0; num5 < Math.Min(days, 30); num5++)
				{
					int num6 = (int)Math.Round((double)(num3 - num4) * 0.03);
					if (num6 == 0 && num4 != num3)
					{
						num6 = Math.Sign(num3 - num4);
					}
					if (Math.Abs(num3 - num4) >= 15 && Math.Abs(num6) < 2)
					{
						num6 = 2 * Math.Sign(num3 - num4);
					}
					num4 += num6;
				}
				if (num4 != value)
				{
					RelMap[key] = num4;
					GrudgeLog($"RELATION {text} / {text2}: {value} -> {num4} (time - toward the old {num3})");
				}
				if (num4 == LoreRelation(text, text2))
				{
					RelMap.Remove(key);
					RelWhy.Remove(key);
				}
			}
		}
		try
		{
			FadeGrievances(days);
			RollFlashpoint(days);
		}
		catch (Exception ex)
		{
			GrudgeLog("SPARK failed: " + ex.Message);
		}
		for (int num7 = 0; num7 < list.Count; num7++)
		{
			for (int num8 = num7 + 1; num8 < list.Count; num8++)
			{
				string a = list[num7];
				string b = list[num8];
				if (Relation(a, b) <= Config.WarLine)
				{
					continue;
				}
				Gang gang = Gangs.ById(a);
				if (gang != null && gang.OrdersNotFeelings)
				{
					continue;
				}
				Gang gang2 = Gangs.ById(b);
				if (gang2 == null || !gang2.OrdersNotFeelings)
				{
					int num9 = Math.Min(100, LoreRelation(a, b) + 15) - Relation(a, b);
					if (num9 > 0 && list.Any((string c) =>
					{
						if (c != a && c != b)
						{
							Gang gang3 = Gangs.ById(c);
							if ((gang3 == null || !gang3.OrdersNotFeelings) && AtWarNow(a, c))
							{
								return AtWarNow(b, c);
							}
						}
						return false;
					}))
					{
						ShiftRelation(a, b, Math.Min(num9, 2 * Math.Min(days, 5)), "a common enemy");
					}
				}
			}
		}
		SaveWorld();
	}

	internal string RelationsLine()
	{
		List<string> list = (from g in Gangs.All
			where !g.StoryOnly && !IsDestroyed(g)
			select g.Id).ToList();
		List<(string, int)> list2 = new List<(string, int)>();
		for (int num = 0; num < list.Count; num++)
		{
			for (int num2 = num + 1; num2 < list.Count; num2++)
			{
				int num3 = Relation(list[num], list[num2]);
				if (num3 <= -15 || RelMap.ContainsKey(PairKey(list[num], list[num2])))
				{
					list2.Add((string.Format("{0}/{1} {2}{3}", list[num], list[num2], num3, (num3 != LoreRelation(list[num], list[num2])) ? $" (lore {LoreRelation(list[num], list[num2])})" : ""), num3));
				}
			}
		}
		return "relations: " + ((list2.Count == 0) ? "all at peace" : string.Join(", ", list2.OrderBy(((string t, int r) x) => x.r).Take(10).Select(((string t, int r) x) => x.t)));
	}

	private int RecentClashes(string a, string b)
	{
		long num = GameMinutesNow() - 4320;
		int num2 = 0;
		int num3 = Chronicle.Events.Count - 1;
		while (num3 >= 0 && num2 < 10)
		{
			WorldEvent worldEvent = Chronicle.Events[num3];
			if (!worldEvent.IsPast && worldEvent.GameMin >= num && (worldEvent.Kind == "CLASH" || worldEvent.Kind == "CAMP OVERRUN" || worldEvent.Kind == "RAID") && worldEvent.Gangs.Contains(a) && worldEvent.Gangs.Contains(b))
			{
				num2++;
			}
			num3--;
		}
		return num2;
	}

	private (Gang a, Gang b, District d)? PickClashPair()
	{
		List<Gang> list = Gangs.All.Where((Gang g) => !g.StoryOnly && !IsDestroyed(g) && Roster.Any((NemesisRecord n) => n.Gang == g.Id && n.IsAlive && !n.PresumedDead)).ToList();
		List<(Gang, Gang, District, double)> list2 = new List<(Gang, Gang, District, double)>();
		foreach (Gang item in list)
		{
			foreach (Gang item2 in list)
			{
				if (string.CompareOrdinal(item.Id, item2.Id) >= 0)
				{
					continue;
				}
				int num = Relation(item.Id, item2.Id);
				if (num > Config.ClashLine || TruceBetween(item.Id, item2.Id))
				{
					continue;
				}
				District[] districts = Districts;
				foreach (District district in districts)
				{
					int num3 = HoldOf(district, item.Id);
					int num4 = HoldOf(district, item2.Id);
					if ((num3 >= 3 && num4 >= 3) || (item.OrdersNotFeelings && num4 >= 8) || (item2.OrdersNotFeelings && num3 >= 8))
					{
						double num5 = (((item.OrdersNotFeelings || item2.OrdersNotFeelings) && LiveWar(item.Id, item2.Id) == null) ? 0.4 : 1.0);
						list2.Add((item, item2, district, num5 * (double)(-num) * (double)Math.Max(3, Math.Min(Math.Max(num3, 3), Math.Max(num4, 3))) / (1.0 + 0.6 * (double)RecentClashes(item.Id, item2.Id)) * AgendaPairMult(item, item2, district) * Math.Min(TargetWeight(item), TargetWeight(item2))));
					}
				}
			}
		}
		if (list2.Count == 0)
		{
			return null;
		}
		double num6 = _rng.NextDouble() * list2.Sum(((Gang a, Gang b, District d, double w) c) => c.w);
		foreach (var item3 in list2)
		{
			if (!((num6 -= item3.Item4) > 0.0))
			{
				return (item3.Item1.OrdersNotFeelings || (!item3.Item2.OrdersNotFeelings && _rng.Next(100) < ((HoldOf(item3.Item3, item3.Item1.Id) >= HoldOf(item3.Item3, item3.Item2.Id)) ? 65 : 35))) ? (item3.Item1, item3.Item2, item3.Item3) : (item3.Item2, item3.Item1, item3.Item3);
			}
		}
		(Gang, Gang, District, double) tuple = list2.Last();
		return (tuple.Item1, tuple.Item2, tuple.Item3);
	}

	private (string place, Vector3 pos, CampSite site)? ClashPlace(Gang attacker, Gang defender, District d, Ped player)
	{
		CampSite campSite = WarGoalCamp(attacker, defender, d);
		if (campSite != null && _rng.Next(100) < 70 && (player == null || new Vector3(campSite.X, campSite.Y, campSite.Z).DistanceTo(player.Position) >= Config.WorldMinDistance))
		{
			return ("at " + campSite.Label, new Vector3(campSite.X, campSite.Y, campSite.Z), campSite);
		}
		if (defender.HasCamps && _rng.Next(100) < (attacker.OrdersNotFeelings ? 60 : 40))
		{
			HashSet<string> manned = new HashSet<string>(from n in Roster
				where n.Gang == defender.Id && n.CampId != null && OffStage(n)
				select n.CampId);
			CampSite campSite2 = (from s in SitesHeldBy(defender.Id)
				where !IsCleared(s) && !_liveCamps.ContainsKey(s.Id) && DistrictAt(new Vector3(s.X, s.Y, s.Z)) == d && (player == null || new Vector3(s.X, s.Y, s.Z).DistanceTo(player.Position) >= Config.WorldMinDistance)
				orderby manned.Contains(s.Id) descending
				select s).ThenBy((CampSite _) => _rng.Next()).FirstOrDefault();
			if (campSite2 != null)
			{
				return ("at " + campSite2.Label, new Vector3(campSite2.X, campSite2.Y, campSite2.Z), campSite2);
			}
		}
		if (_rng.Next(100) < 35)
		{
			foreach (string item in TownNames.OrderBy((string _) => _rng.Next()))
			{
				if (TownCore(item, out var centre, out var radius) && DistrictAt(centre) == d)
				{
					double num = _rng.NextDouble() * Math.PI * 2.0;
					float num2 = radius + 180f + (float)_rng.NextDouble() * 200f;
					Vector3 vector = new Vector3(centre.X + (float)Math.Cos(num) * num2, centre.Y + (float)Math.Sin(num) * num2, centre.Z);
					if ((!(player != null) || !(new Vector3(vector.X - player.Position.X, vector.Y - player.Position.Y, 0f).Length() < Config.WorldMinDistance)) && !InsideAnyTown(vector) && OnLand(vector))
					{
						return ("outside " + item, vector, null);
					}
				}
			}
		}
		for (int num3 = 0; num3 < 10; num3++)
		{
			double num4 = _rng.NextDouble() * Math.PI * 2.0;
			float num5 = 150f + (float)_rng.NextDouble() * 450f;
			Vector3 vector2 = new Vector3(d.X + (float)Math.Cos(num4) * num5, d.Y + (float)Math.Sin(num4) * num5, 100f);
			if ((!(player != null) || !(new Vector3(vector2.X - player.Position.X, vector2.Y - player.Position.Y, 0f).Length() < Config.WorldMinDistance)) && !InsideAnyTown(vector2) && OnLand(vector2))
			{
				return ("in " + d.Name, vector2, null);
			}
		}
		return null;
	}

	private void WarStarted(District d, Gang a, Gang b)
	{
		WarRecord warRecord = new WarRecord
		{
			District = d.Key,
			A = a.Id,
			B = b.Id,
			StartMin = GameMinutesNow(),
			HoldA0 = HoldOf(d, a.Id),
			HoldB0 = HoldOf(d, b.Id),
			MenA0 = Math.Max(1, MenOf(a)),
			MenB0 = Math.Max(1, MenOf(b)),
			LastReportDay = GameDayKey(),
			Cause = RelationCause(a.Id, b.Id)
		};
		Wars.RemoveAll((WarRecord x) => x.District == d.Key);
		try
		{
			PickWarGoal(warRecord, d, a, b);
		}
		catch (Exception ex)
		{
			GrudgeLog("WAR goal failed: " + ex.Message);
		}
		InitHeat(warRecord);
		if (warRecord.GoalText != null && warRecord.GoalLog.Count == 0)
		{
			warRecord.GoalLog.Add($"{GameDate.FromMinutes(GameMinutesNow()):MMM d}: {warRecord.GoalText}");
		}
		warRecord.Name = NameWar(warRecord, d, a, b, warRecord.Cause);
		Wars.Add(warRecord);
		WorldEvent worldEvent = NewEvent("WAR", GameMinutesNow());
		worldEvent.Gangs.Add(a.Id);
		worldEvent.Gangs.Add(b.Id);
		worldEvent.Title = "War breaks out in " + d.Name + ": the " + a.Name + " and the " + b.Name;
		worldEvent.Place = "in " + d.Name;
		worldEvent.HasPos = true;
		worldEvent.X = d.X;
		worldEvent.Y = d.Y;
		worldEvent.Z = 100f;
		worldEvent.Lines.Add("They're already calling it " + warRecord.Name + ".");
		worldEvent.Lines.Add("What started it: " + warRecord.Cause + ".");
		if (warRecord.GoalText != null)
		{
			worldEvent.Lines.Add("What the " + a.Name + " want: " + warRecord.GoalText + ".");
		}
		worldEvent.Lines.Add($"The {a.Name} hold {warRecord.HoldA0} of the district, the {b.Name} {warRecord.HoldB0}. They're {RelationWord(Relation(a.Id, b.Id))} ({Relation(a.Id, b.Id)}).");
		worldEvent.Lines.Add("Expect skirmishes on the roads there, raids on camps, and bodies by morning.");
		worldEvent.Heard = true;
		Chronicle.Events.Add(worldEvent);
		SaveWorld();
	}

	private void WarEnded(District d, string aId, string bId)
	{
		WarRecord warRecord = Wars.FirstOrDefault((WarRecord x) => x.District == d.Key);
		Gang gang = Gangs.ById(aId);
		Gang gang2 = Gangs.ById(bId);
		if (gang == null || gang2 == null)
		{
			Wars.Remove(warRecord);
			return;
		}
		int num = HoldOf(d, aId);
		int num2 = HoldOf(d, bId);
		int num3 = Relation(aId, bId);
		string text = WarResultText(warRecord, gang, gang2) ?? (TruceBetween(aId, bId) ? "they called a truce" : ((IsDestroyed(gang) || IsDestroyed(gang2)) ? "one side is finished" : ((num3 > Config.WarLine) ? "the bad blood cooled" : ((Math.Min(num, num2) < 8) ? ("the " + ((num < num2) ? gang.Name : gang2.Name) + " were driven out") : "one side won the ground"))));
		Gang gang3 = ((num >= num2) ? gang : gang2);
		WorldEvent worldEvent = NewEvent("WAR", GameMinutesNow());
		worldEvent.Gangs.Add(aId);
		worldEvent.Gangs.Add(bId);
		worldEvent.Title = ((warRecord != null) ? (WarName(warRecord) + " is over - the " + gang3.Name + " hold " + d.Name) : ("The war in " + d.Name + " is over - the " + gang3.Name + " hold it"));
		Gang gang4;
		if ((warRecord?.Goal == "drive" && warRecord.Result == "met") || warRecord?.Result == "broken")
		{
			gang4 = gang2;
		}
		else
		{
			gang4 = ((warRecord?.Result == "defended" || warRecord?.Result == "spent") ? gang : null);
		}
		if (warRecord?.Result == "broken" || warRecord?.Result == "spent")
		{
			Gang g = ((warRecord.Result == "broken") ? gang : gang2);
			Gang gang5 = ((warRecord.Result == "broken") ? gang2 : gang);
			int num4 = Math.Min(10, HoldOf(d, gang5.Id));
			if (num4 > 0)
			{
				ShiftControl(d, gang5, -num4, "ran out of men");
				ShiftControl(d, g, num4, "the " + gang5.Name + " ran out of men");
			}
		}
		if (gang4 != null)
		{
			(Chronicle.Beaten ?? (Chronicle.Beaten = new Dictionary<string, long>()))[d.Key + "|" + gang4.Id] = GameMinutesNow() + 10080;
			worldEvent.Title = ((gang4 == gang2) ? ("The " + gang.Name + " drove the " + gang2.Name + " out of " + d.Name) : ("The " + gang2.Name + " drove the " + gang.Name + " off in " + d.Name));
			GrudgeLog("WAR " + d.Name + ": the " + gang4.Name + " were beaten - their ground there stays down for 7 days");
		}
		worldEvent.Place = "in " + d.Name;
		worldEvent.HasPos = true;
		worldEvent.X = d.X;
		worldEvent.Y = d.Y;
		worldEvent.Z = 100f;
		worldEvent.Lines.Add("How it ended: " + text + ".");
		if (warRecord != null)
		{
			long num5 = Math.Max(0L, (GameMinutesNow() - warRecord.StartMin) / 1440);
			if (num5 > 120)
			{
				num5 = 0L;
			}
			worldEvent.Lines.Add(string.Format("It lasted {0} day{1}: {2} fights that word got out about, {3} named men dead.", num5, (num5 == 1) ? "" : "s", warRecord.Clashes, warRecord.Dead));
			worldEvent.Lines.Add($"Ground: the {gang.Name} {warRecord.HoldA0} -> {num}, the {gang2.Name} {warRecord.HoldB0} -> {num2}.");
		}
		if (gang4 != null)
		{
			worldEvent.Lines.Add("The " + gang4.Name + " will be a while getting their ground back in " + d.Name + ".");
		}
		worldEvent.Heard = true;
		Chronicle.Events.Add(worldEvent);
		if (warRecord != null)
		{
			warRecord.EndMin = GameMinutesNow();
			warRecord.EndTitle = worldEvent.Title;
			warRecord.EndHow = text;
			try
			{
				Gang gang6 = Gangs.ById(warRecord.A) ?? gang;
				Gang gang7 = Gangs.ById(warRecord.B) ?? gang2;
				warRecord.EndPurseA = WarPurse(gang6);
				warRecord.EndPurseB = WarPurse(gang7);
				warRecord.EndMenA = $"{MenOf(gang6)} of {MenStart(gang6)}  -  {StrengthWord(Strength(gang6))}";
				warRecord.EndMenB = $"{MenOf(gang7)} of {MenStart(gang7)}  -  {StrengthWord(Strength(gang7))}";
				warRecord.EndLeaderA = WarLeader(gang6);
				warRecord.EndLeaderB = WarLeader(gang7);
				warRecord.EndAimA = WarAim(gang6);
				warRecord.EndAimB = WarAim(gang7);
				warRecord.EndHoldA = HoldOf(d, gang6.Id);
				warRecord.EndHoldB = HoldOf(d, gang7.Id);
			}
			catch (Exception ex)
			{
				GrudgeLog("WAR end snapshot failed: " + ex.Message);
			}
			List<WarRecord> list = Chronicle.PastWars ?? (Chronicle.PastWars = new List<WarRecord>());
			list.Add(warRecord);
			while (list.Count > 12)
			{
				list.RemoveAt(0);
			}
		}
		Wars.Remove(warRecord);
		SaveWorld();
	}

	internal long WarDay(WarRecord w)
	{
		if (w != null)
		{
			return Math.Max(0L, GameMinutesNow() - w.StartMin) / 1440 + 1;
		}
		return 0L;
	}

	internal static string WarSince(WarRecord w)
	{
		return GameDate.FromMinutes(w.StartMin).ToString("MMM d");
	}

	private void WarReport(District d, WarRecord w)
	{
		Gang gang = Gangs.ById(w.A);
		Gang gang2 = Gangs.ById(w.B);
		if (gang == null || gang2 == null)
		{
			return;
		}
		if (w.StartMin > GameMinutesNow() || GameMinutesNow() - w.StartMin > 172800)
		{
			GrudgeLog($"WAR {d.Name}: start time {w.StartMin} doesn't fit this save - counted from today");
			w.StartMin = GameMinutesNow();
		}
		int num = HoldOf(d, w.A);
		int num2 = HoldOf(d, w.B);
		long num3 = Math.Max(1L, (GameMinutesNow() - w.StartMin) / 1440);
		WorldEvent worldEvent = NewEvent("WAR", GameMinutesNow());
		worldEvent.Gangs.Add(w.A);
		worldEvent.Gangs.Add(w.B);
		Gang gang3;
		if (num == num2)
		{
			gang3 = null;
		}
		else
		{
			gang3 = ((num > num2) ? gang : gang2);
		}
		long num4 = WarDay(w);
		GrudgeLog($"WAR {d.Name} day {num4}: ground {gang.Name} {num} (from {w.HoldA0}), {gang2.Name} {num2} (from {w.HoldB0}) - men {MenOf(gang)} of {w.MenA0}, {MenOf(gang2)} of {w.MenB0} - heat {w.Heat}");
		worldEvent.Title = ((gang3 == null) ? $"Day {num4} of {WarName(w)}: dead even" : $"Day {num4} of {WarName(w)}: the {gang3.Name} are winning");
		worldEvent.Place = "in " + d.Name;
		worldEvent.HasPos = true;
		worldEvent.X = d.X;
		worldEvent.Y = d.Y;
		worldEvent.Z = 100f;
		worldEvent.Lines.Add("At war since " + WarSince(w) + ".");
		worldEvent.Lines.Add($"Ground now: the {gang.Name} {num} ({num - w.HoldA0:+0;-0}), the {gang2.Name} {num2} ({num2 - w.HoldB0:+0;-0}).");
		worldEvent.Lines.Add($"{w.Clashes} fights so far, {w.Dead} named men dead. They're {RelationWord(Relation(w.A, w.B))} ({Relation(w.A, w.B)}).");
		try
		{
			DailyWarTurn(w, d, worldEvent, num3);
		}
		catch (Exception ex)
		{
			GrudgeLog("WAR daily turn failed: " + ex.Message);
		}
		int num5 = Math.Max(0, w.Dead - w.DeadAtReport);
		w.DeadAtReport = w.Dead;
		int num6 = ((num3 >= 5) ? 1 : 0) + num5;
		if (w.GoalText != null)
		{
			worldEvent.Lines.Add("The " + gang.Name + ": " + w.GoalText + ".");
		}
		worldEvent.Lines.Add($"Strength: the {gang.Name} {StrengthWord(Strength(gang)).ToLowerInvariant()} ({MenOf(gang)} men), the {gang2.Name} {StrengthWord(Strength(gang2)).ToLowerInvariant()} ({MenOf(gang2)} men).");
		if (TruceBetween(w.A, w.B))
		{
			w.Paused = true;
			worldEvent.Title = $"Day {num4} of {WarName(w)}: a truce holds";
			worldEvent.Lines.Add("Neither side moves while the truce holds. When it runs out they'll fight again - unless they've cooled.");
		}
		else
		{
			if (w.Paused)
			{
				w.Paused = false;
				worldEvent.Lines.Add("The truce is over. The fighting starts again.");
				GrudgeLog("WAR " + d.Name + ": the truce ran out - the war goes on");
			}
			bool flag = false;
			try
			{
				flag = LeadersSueForPeace(w, d, worldEvent, num3);
			}
			catch (Exception ex2)
			{
				GrudgeLog("WAR peace roll failed: " + ex2.Message);
			}
			if (!flag)
			{
				if (num6 > 0)
				{
					ShiftRelation(w.A, w.B, num6, string.Format("war-weary (day {0}{1})", num3, (num5 > 0) ? $", {num5} named dead" : ""));
				}
				if (num3 >= 10)
				{
					worldEvent.Lines.Add((num3 >= 25) ? "Both sides are bleeding men - there's talk of calling it off." : "The fighting is wearing on both sides.");
				}
			}
		}
		worldEvent.Heard = true;
		Chronicle.Events.Add(worldEvent);
		SaveWorld();
	}

	private void NoteClashForWars(WorldEvent ev)
	{
		try
		{
			LoseMenInEvent(ev);
		}
		catch (Exception ex)
		{
			GrudgeLog("MEN event note failed: " + ex.Message);
		}
		if (ev != null && ev.Gangs != null && ev.Gangs.Count >= 2 && (ev.Kind == "CLASH" || ev.Kind == "CAMP OVERRUN" || ev.Kind == "RAID"))
		{
			NoteClash(ev.Gangs[0], ev.Gangs[1], Enumerable.Count(ev.People, (WorldPart p) => p.Outcome == "KILLED"), ev.Kind == "CAMP OVERRUN", ev.Place, ev.HasPos ? new Vector3?(new Vector3(ev.X, ev.Y, ev.Z)) : ((Vector3?)null));
		}
	}

	internal void NoteLiveClash(string a, string b, int namedKilled, string place, Vector3 pos)
	{
		if (a == null || b == null || a == b)
		{
			return;
		}
		try
		{
			NoteClash(a, b, namedKilled, overrun: false, place, pos);
		}
		catch (Exception ex)
		{
			GrudgeLog("RELATION live clash note failed: " + ex.Message);
		}
	}

	internal WarRecord WarOfFight(string a, string b, District d, long when, bool liveOnly)
	{
		List<WarRecord> source = (liveOnly ? Wars.Where(Pair).ToList() : (from x in Wars.Concat(Chronicle.PastWars ?? new List<WarRecord>())
			where Pair(x) && when >= x.StartMin - 5 && (x.EndMin <= 0 || when <= x.EndMin + 60)
			orderby x.StartMin
			select x).ToList());
		return ((d == null) ? null : source.FirstOrDefault((WarRecord x) => x.District == d.Key)) ?? source.FirstOrDefault((WarRecord x) => !liveOnly || x.Result == null);
		bool Pair(WarRecord x)
		{
			if (x != null)
			{
				if (!(x.A == a) || !(x.B == b))
				{
					if (x.A == b)
					{
						return x.B == a;
					}
					return false;
				}
				return true;
			}
			return false;
		}
	}

	private void NoteClash(string a, string b, int killed, bool overrun, string place, Vector3? at)
	{
		if (killed > 0)
		{
			AddGrievance(a, b, 3 * killed, $"{killed} named men killed {place}");
		}
		if (overrun)
		{
			AddGrievance(a, b, 10, "overran a camp");
		}
		WarRecord warRecord = WarOfFight(a, b, at.HasValue ? DistrictAt(at.Value) : null, GameMinutesNow(), liveOnly: true);
		bool flag = warRecord != null && GameMinutesNow() - warRecord.StartMin > 4320;
		ShiftRelation(a, b, flag ? (-2) : (-6), overrun ? ("the " + Gangs.ById(a)?.Name + " overran a camp") : ("a fight " + place));
		if (warRecord != null)
		{
			warRecord.Clashes++;
			warRecord.Dead += killed;
			NemesisMod nemesisMod = this;
			WarRecord w = warRecord;
			int n = 4 + 2 * Math.Min(killed, 4) + (overrun ? 8 : 0);
			string why;
			if (overrun)
			{
				why = "a camp overrun";
			}
			else
			{
				why = ((killed > 0) ? $"{killed} named men killed" : "a fight");
			}
			nemesisMod.AddHeat(w, n, why);
		}
	}

	private void RefreshWarMarkers()
	{
		if (_mapHidden)
		{
			ClearWarMarkers();
		}
		else
		{
			if (!MapSettled() || _worldCatchingUp)
			{
				return;
			}
			HashSet<string> hashSet = new HashSet<string>();
			if (Config.WarMarkers)
			{
				District[] districts = Districts;
				foreach (District district in districts)
				{
					(Gang, Gang)? tuple = WarIn(district);
					if (!tuple.HasValue)
					{
						continue;
					}
					hashSet.Add(district.Key);
					if (_warMarkers.ContainsKey(district.Key) || string.IsNullOrEmpty(district.Region))
					{
						continue;
					}
					uint num = Joaat.Of(district.Region);
					uint num2 = Joaat.Of(Config.WarRegionStyle);
					Crumbs.Mark("war shading " + district.Region);
					FlushGrudgeLog(force: true);
					int num3;
					try
					{
						num3 = Function.Call<int>(6214909650283936023uL, new InputArgument[2] { num, num2 });
					}
					catch (Exception ex)
					{
						GrudgeLog("WAR shading " + district.Region + " failed: " + ex.Message);
						continue;
					}
					_warMarkers[district.Key] = (int)num;
					string text = "War: the " + tuple.Value.Item1.Name + " vs the " + tuple.Value.Item2.Name;
					if (num3 != 0)
					{
						try
						{
							Crumbs.Native("war shading name");
							Function.Call(11290983183885202434uL, num3, new InputArgument(UiDraw.ForeverVarString(text)));
						}
						catch
						{
						}
					}
					if (Config.Verbose)
					{
						GrudgeLog("WAR " + district.Name + " shaded on the map (" + district.Region + ", " + Config.WarRegionStyle + ")");
					}
				}
			}
			foreach (string item in _warMarkers.Keys.ToList())
			{
				if (!hashSet.Contains(item))
				{
					RemoveWarMarker(item);
				}
			}
			try
			{
				RefreshWarDistrictBlips(hashSet);
			}
			catch (Exception ex2)
			{
				GrudgeLog("WAR district marker failed: " + ex2.Message);
			}
			District currentDistrict = CurrentDistrict;
			(Gang, Gang)? tuple2 = WarIn(currentDistrict);
			if (tuple2.HasValue && currentDistrict.Key != _warNoticeDistrict)
			{
				_warNoticeDistrict = currentDistrict.Key;
				GrudgeNotice("You ride into " + currentDistrict.Name + " - the " + tuple2.Value.Item1.Name + " and the " + tuple2.Value.Item2.Name + " are at war here.");
				Feed("WAR you rode into " + currentDistrict.Name + ": the " + tuple2.Value.Item1.Name + " vs the " + tuple2.Value.Item2.Name, Theme.Warn);
			}
			else if (!tuple2.HasValue)
			{
				_warNoticeDistrict = null;
			}
		}
	}

	internal static string ShortOutfit(Gang g)
	{
		if (g == null)
		{
			return "?";
		}
		switch (g.Id)
		{
		case "odriscoll":
			return "O'Driscolls";
		case "lemoyneraiders":
			return "Raiders";
		case "army":
			return "Army";
		case "klan":
			return "Klan";
		case "wapiti":
			return "Wapiti";
		case "bronte":
			return "Brontes";
		case "murfree":
			return "Murfrees";
		case "skinners":
			return "Skinners";
		default:
		{
			string text = g.Name ?? "?";
			if (!text.StartsWith("The "))
			{
				return text;
			}
			return text.Substring(4);
		}
		}
	}

	private unsafe void RefreshWarDistrictBlips(HashSet<string> live)
	{
		foreach (string item in _warDistrictBlips.Keys.ToList())
		{
			(int, string) tuple = _warDistrictBlips[item];
			if (live.Contains(item) && MAP.DOES_BLIP_EXIST(tuple.Item1))
			{
				continue;
			}
			var (p, _) = tuple;
			Crumbs.Native("war district blip remove");
			try
			{
				if (MAP.DOES_BLIP_EXIST(p))
				{
					MAP.REMOVE_BLIP(&p);
				}
			}
			catch
			{
			}
			_warDistrictBlips.Remove(item);
		}
		if (!Config.WarMarkers)
		{
			return;
		}
		foreach (string key in live)
		{
			District district = Districts.FirstOrDefault((District x) => x.Key == key);
			WarRecord warRecord = Wars.FirstOrDefault((WarRecord x) => x.Result == null && x.District == key);
			if (district == null || warRecord == null || (district.X == 0f && district.Y == 0f))
			{
				continue;
			}
			Gang g = Gangs.ById(warRecord.A);
			Gang g2 = Gangs.ById(warRecord.B);
			string text = UiDraw.TheFix(WarName(warRecord).Replace("The ", "") + ": " + ShortOutfit(g) + " v " + ShortOutfit(g2) + ", " + (warRecord.Paused ? "truce" : $"Day {WarDay(warRecord)}"));
			if (_warDistrictBlips.TryGetValue(key, out (int, string) value))
			{
				if (value.Item2 != text)
				{
					Function.Call(11290983183885202434uL, value.Item1, new InputArgument(UiDraw.ForeverVarString(text)));
					_warDistrictBlips[key] = (value.Item1, text);
				}
				continue;
			}
			Crumbs.Native("war district blip add");
			int num = MAP.BLIP_ADD_FOR_COORDS(3911271093u, district.X, district.Y, 0f);
			try
			{
				MAP.SET_BLIP_SPRITE(num, MISC.GET_HASH_KEY("blip_town"), p2: true);
			}
			catch
			{
			}
			Function.Call(11290983183885202434uL, num, new InputArgument(UiDraw.ForeverVarString(text)));
			_warDistrictBlips[key] = (num, text);
			GrudgeLog($"WAR map marker: {text} ({district.X:0},{district.Y:0})");
		}
	}

	private void RemoveWarMarker(string key)
	{
		if (!_warMarkers.TryGetValue(key, out var value))
		{
			return;
		}
		bool flag = false;
		try
		{
			flag = CAM.IS_SCREEN_FADED_OUT() || CAM.IS_SCREEN_FADING_OUT();
		}
		catch
		{
		}
		if (!flag)
		{
			Crumbs.Mark("war shading off " + key);
			try
			{
				Function.Call(7459886982293971635uL, (uint)value);
			}
			catch
			{
			}
		}
		_warMarkers.Remove(key);
	}

	internal void ClearWarMarkers()
	{
		foreach (string item in _warMarkers.Keys.ToList())
		{
			RemoveWarMarker(item);
		}
		try
		{
			RefreshWarDistrictBlips(new HashSet<string>());
		}
		catch
		{
		}
	}

	internal static string OutfitWord(Gang g)
	{
		string text = g?.Name ?? "";
		if (text.StartsWith("The "))
		{
			text = text.Substring(4);
		}
		string[] array = new string[4] { " Boys", " Brothers", " Family", " Brood" };
		foreach (string text2 in array)
		{
			if (text.EndsWith(text2))
			{
				return text.Substring(0, text.Length - text2.Length);
			}
		}
		if (text.EndsWith("s") && !text.EndsWith("ss"))
		{
			text = text.Substring(0, text.Length - 1);
		}
		return text;
	}

	private WorldEvent Incident(List<Gang> outfits, long now)
	{
		List<(Gang, Gang, District)> list = new List<(Gang, Gang, District)>();
		District[] districts = Districts;
		foreach (District district in districts)
		{
			foreach (Gang outfit in outfits)
			{
				foreach (Gang outfit2 in outfits)
				{
					if (string.CompareOrdinal(outfit.Id, outfit2.Id) < 0 && HoldOf(district, outfit.Id) >= 5 && HoldOf(district, outfit2.Id) >= 5)
					{
						list.Add((outfit, outfit2, district));
					}
				}
			}
		}
		if (list.Count == 0)
		{
			return null;
		}
		var (gang, gang2, district2) = list[_rng.Next(list.Count)];
		if (_rng.Next(2) == 0)
		{
			Gang gang3 = gang2;
			gang2 = gang;
			gang = gang3;
		}
		int num = Relation(gang.Id, gang2.Id);
		bool flag = gang.OrdersNotFeelings || gang2.OrdersNotFeelings || _rng.Next(100) < ((num <= Config.WarLine) ? 80 : ((num < 0) ? 65 : 45));
		string[] array = (flag ? BadBlood : Deals);
		string name = district2.Name;
		string input = array[_rng.Next(array.Length)].Replace("{aw}", OutfitWord(gang)).Replace("{bw}", OutfitWord(gang2)).Replace("{a}", gang.Name)
			.Replace("{b}", gang2.Name)
			.Replace("{p}", name)
			.Replace("{d}", district2.Name);
		input = Regex.Replace(input, "(^|\\s)([aA]) (?=[AEIOaeio])", "$1$2n ");
		input = char.ToUpperInvariant(input[0]) + input.Substring(1);
		int delta = (flag ? (-(10 + _rng.Next(13))) : (8 + _rng.Next(11)));
		int num2 = num;
		ShiftRelation(gang.Id, gang2.Id, delta, char.ToLowerInvariant(input[0]) + input.Substring(1));
		WorldEvent worldEvent = NewEvent("TURMOIL", now);
		worldEvent.Gangs.Add(gang.Id);
		worldEvent.Gangs.Add(gang2.Id);
		worldEvent.Title = input;
		worldEvent.Place = "in " + district2.Name;
		worldEvent.HasPos = true;
		worldEvent.X = district2.X;
		worldEvent.Y = district2.Y;
		worldEvent.Z = 100f;
		int num3 = Relation(gang.Id, gang2.Id);
		worldEvent.Lines.Add(flag ? $"Bad blood: the {gang.Name} and the {gang2.Name} go from {RelationWord(num2)} to {RelationWord(num3)} ({num2} -> {num3})." : $"Cooler heads: the {gang.Name} and the {gang2.Name} go from {RelationWord(num2)} to {RelationWord(num3)} ({num2} -> {num3}).");
		if (flag && num3 <= Config.WarLine && num2 > Config.WarLine)
		{
			worldEvent.Lines.Add("There's talk of war in " + district2.Name + ".");
		}
		return worldEvent;
	}

	private NemesisRecord ShadowOf(Ped p)
	{
		if (_provoked.TryGetValue(p.Handle, out var value) && value.Shadow != null)
		{
			return value.Shadow;
		}
		if (!_witnessShadow.TryGetValue(p.Handle, out var value2))
		{
			value2 = ShadowFor(p, mind: false);
			Personality? personality = KnownTemper(p);
			if (personality.HasValue)
			{
				value2.Personality = personality;
			}
			_witnessShadow[p.Handle] = value2;
		}
		return value2;
	}

	private float RepAt(Vector3 at)
	{
		return TownWord(_currentTown ?? TownAt(at));
	}

	private static int StartFear(float rep, string temper)
	{
		if (!(rep < 20f))
		{
			return (int)Math.Min(30f, rep / 5f * TemperFearGain(temper));
		}
		return 0;
	}

	internal static int HeardChance(float rep)
	{
		if (!(rep < 15f))
		{
			return (int)Math.Round(75.0 * Math.Pow(Math.Min(1.0, (double)(rep - 15f) / 85.0), 1.2));
		}
		return 0;
	}

	private static float RepUneaseMult(float rep)
	{
		return 1f + rep / 200f;
	}

	private static float RepGrudgeMult(float rep, string temper)
	{
		return Math.Max(0.5f, 1f - rep / 100f * 0.35f * Math.Min(1.5f, TemperFearGain(temper)));
	}

	private static float RepLikeMult(float rep)
	{
		return Math.Max(0.5f, 1f - rep / 100f * 0.4f);
	}

	private static float LikeGain(NemesisRecord sh)
	{
		if (sh == null)
		{
			return 1f;
		}
		return ((sh.Disposition == Disposition.Friendly) ? 1.5f : ((sh.Disposition == Disposition.Surly) ? 0.5f : 1f)) * ((sh.Sociability == Sociability.Outgoing) ? 1.3f : 0.8f) * Tempers.Of(sh.Personality).LikeGain;
	}

	private int LikeDelta(int handle, int baseDelta)
	{
		if (baseDelta <= 0)
		{
			return baseDelta;
		}
		Ped ped = Entity.FromHandle(handle) as Ped;
		if (ped == null || !ped.Exists())
		{
			return baseDelta;
		}
		float num = LikeGain(ShadowOf(ped)) * RepLikeMult(RepAt(ped.Position));
		return Math.Max(1, (int)Math.Round((float)baseDelta * num));
	}

	private void NervousGreet(int handle)
	{
		if (!_acqOf.TryGetValue(handle, out var value) || !_named.TryGetValue(handle, out var value2))
		{
			return;
		}
		Ped ped = Entity.FromHandle(handle) as Ped;
		if (!(ped == null) && ped.Exists())
		{
			float num = RepAt(ped.Position);
			if ((value.Fear >= 15 || !(num < 40f)) && _rng.Next(100) < 70)
			{
				string text = value.Temper ?? "";
				string[] array = (NervousLines.TryGetValue(text, out var value3) ? value3 : NervousLines[""]);
				ShowSubtitle(value2.Name + ": \"" + array[_rng.Next(array.Length)] + "\"");
				RepNote(string.Format("NERVOUS {0} ({1}, fear {2}, infamy {3:0}) greeted you back", value2.Name, (text == "") ? "?" : text.ToLowerInvariant(), value.Fear, num));
			}
		}
	}

	internal void RepNote(string text)
	{
		_repNotes.Add((UiDraw.RealMs, text));
		if (_repNotes.Count > 30)
		{
			_repNotes.RemoveAt(0);
		}
	}

	internal IEnumerable<string> ReputationLines()
	{
		List<Acquaintance> alive = People.Where((Acquaintance a) => !a.Dead).ToList();
		int afraid = Enumerable.Count(alive, (Acquaintance a) => a.Fear > 0);
		int terrified = Enumerable.Count(alive, (Acquaintance a) => a.Fear >= 50);
		int liked = Enumerable.Count(alive, (Acquaintance a) => a.Like > 0);
		string noto = string.Join(", ", Gangs.All.Select((Gang g) => $"{g.Name} {NotorietyOf(g)} ({Notoriety.LevelName(NotorietyOf(g))})"));
		int num = OverallReputation();
		yield return string.Format("REPUTATION {0:+0;-0;0} ({1}) - bounty ${2} (law part {3}){4}", num, RepWord(num), BountyDollars, LawPart(), LAW.IS_LAW_INCIDENT_ACTIVE(Game.Player.Handle) ? " - the law is after you" : "");
		foreach (var item in (from t in RepTowns
			select (t: t, p: TownRep(t)) into x
			where x.p.Known > 0 || x.p.Illwill > 0
			orderby x.p.Known descending
			select x).Take(6))
		{
			yield return "  " + TownRepLine(item.t);
		}
		yield return "notoriety: " + noto;
		IEnumerable<string> first = (from a in alive
			where a.Town != null && (a.Fear > 0 || a.Like > 0)
			select a.Town).Distinct();
		IEnumerable<string> enumerable = Chronicle.TownWord?.Keys;
		List<(string, float, int, int)> list = (from t in first.Concat(enumerable ?? Enumerable.Empty<string>()).Distinct()
			select (t: t, w: TownWord(t), af: Enumerable.Count(alive, (Acquaintance a) => a.Town == t && a.Fear > 0), lk: Enumerable.Count(alive, (Acquaintance a) => a.Town == t && a.Like > 0)) into x
			orderby x.w descending
			select x).Take(6).ToList();
		yield return "infamy (fear talk): " + ((list.Count == 0) ? "nobody talks about you" : string.Join(";  ", list.Select(((string t, float w, int af, int lk) x) => $"{x.t} {x.w:0} ({x.af} afraid, {x.lk} like you)")));
		yield return $"people who know you: {alive.Count} - {afraid} afraid (avg {((afraid > 0) ? alive.Where((Acquaintance a) => a.Fear > 0).Average((Acquaintance a) => a.Fear) : 0.0):0}), {terrified} at 50+, {liked} like you, " + $"{Enumerable.Count(People, (Acquaintance a) => a.Reported)} told the law, {Enumerable.Count(People, (Acquaintance a) => a.KeptQuiet)} kept quiet, {Enumerable.Count(People, (Acquaintance a) => a.Dead)} dead";
		List<NemesisRecord> list2 = Roster.Where((NemesisRecord r) => r.IsAlive && !r.PresumedDead).ToList();
		yield return $"nemeses: {list2.Count} alive - {Enumerable.Count(list2, (NemesisRecord r) => r.HateTier == HateTier.Murderous)} murderous, {Enumerable.Count(list2, (NemesisRecord r) => r.HateTier == HateTier.Vengeful)} vengeful, " + $"{Enumerable.Count(list2, (NemesisRecord r) => r.HateTier == HateTier.Resentful)} resentful ({Enumerable.Count(list2, (NemesisRecord r) => r.Gang == null)} loners)";
	}

	internal IEnumerable<string> PeopleNearLines(Ped player)
	{
		Vector3 me = player.Position;
		List<(int, Named, float)> list = (from kv in _named
			where !kv.Value.Story && ENTITY.DOES_ENTITY_EXIST(kv.Key) && !ENTITY.IS_ENTITY_DEAD(kv.Key)
			select (h: kv.Key, n: kv.Value, d: new Ped(kv.Key).Position.DistanceTo(me)) into t
			where t.d < 40f
			orderby t.d
			select t).Take(12).ToList();
		if (list.Count == 0)
		{
			yield return "nobody named near you";
			yield break;
		}
		foreach (var item4 in list)
		{
			int item = item4.Item1;
			Named item2 = item4.Item2;
			float item3 = item4.Item3;
			NemesisRecord nemesisRecord = RecordAt(item);
			if (nemesisRecord != null)
			{
				yield return $"{nemesisRecord.Name} {item3:0}m - NEMESIS {nemesisRecord.Personality}, hate {nemesisRecord.Hate}, fear {EffectiveFear(nemesisRecord)}";
				continue;
			}
			_acqOf.TryGetValue(item, out var value);
			_provoked.TryGetValue(item, out var value2);
			float num = UneaseOf(item);
			string text = ((value2 != null) ? value2.Temper.ToString() : (value?.Temper ?? "?"));
			string text2 = string.Format("fear {0}{1}, likes {2}, grudge {3:0}", value?.Fear ?? 0, (num >= 1f) ? $" | uneasy {num:0}" : "", value?.Like ?? 0, value2?.Score ?? ((float)(value?.Grudge ?? 0)));
			string text3 = value?.Witnessed?.LastOrDefault();
			yield return string.Format("{0}{1} {2:0}m - {3}, {4}{5}", item2.Met ? "*" : "", item2.Name, item3, text, text2, (text3 != null) ? (" - " + text3) : "");
		}
	}

	internal IEnumerable<string> RecentRepLines()
	{
		if (_repNotes.Count == 0)
		{
			yield return "nothing yet this session";
			yield break;
		}
		foreach (var item3 in Enumerable.Reverse(_repNotes).Take(14))
		{
			int item = item3.at;
			string item2 = item3.text;
			int num = Math.Max(0, (UiDraw.RealMs - item) / 1000);
			yield return ((num < 60) ? (num + "s") : (num / 60 + "m")) + "  " + item2;
		}
	}

	internal long GameMinutesNow()
	{
		if (_gmFrame == Game.FrameCount)
		{
			return _gmCache;
		}
		_gmFrame = Game.FrameCount;
		return _gmCache = GameMinutesRaw();
	}

	private long GameMinutesRaw()
	{
		try
		{
			return GameDate.ToMinutes(DayOf(GameDayKey())) + CLOCK.GET_CLOCK_HOURS() * 60 + CLOCK.GET_CLOCK_MINUTES();
		}
		catch
		{
			return 0L;
		}
	}

	internal void StartRest(NemesisRecord rec)
	{
		if (rec != null && Balance.NewNemesisRestHours > 0)
		{
			rec.RestUntil = GameMinutesNow() + (long)Balance.NewNemesisRestHours * 60L;
		}
	}

	internal bool Resting(NemesisRecord rec)
	{
		if (rec != null && rec.RestUntil > 0)
		{
			return GameMinutesNow() < rec.RestUntil;
		}
		return false;
	}

	private unsafe void Wipe(Ped p)
	{
		if (p == null || !p.Exists())
		{
			return;
		}
		int handle = p.Handle;
		bool flag = _modelOf.TryGetValue(handle, out var value) && value != (uint)p.Model.Hash;
		if (flag || !BelongsToUs(handle) || IsCompanionReal(handle))
		{
			_worldNemeses.Remove(handle);
			_followerOf.Remove(handle);
			_knockedOutWorld.Remove(handle);
			GrudgeLog(string.Format("WIPE ped {0} left alone ({1})", handle, flag ? "his handle belongs to someone else now" : "not ours any more"));
			return;
		}
		NemesisRecord nemesisRecord = (_worldNemeses.TryGetValue(p.Handle, out var value2) ? value2 : (((_activeNemesisPed != null && p.Handle == _activeNemesisPed.Handle) ? ActiveRecord : null) ?? RecordAt(p.Handle)));
		_worldNemeses.Remove(p.Handle);
		_followerOf.Remove(p.Handle);
		_knockedOutWorld.Remove(p.Handle);
		int handle2 = p.Handle;
		Ped character = Game.Player.Character;
		if ((ENTITY.IS_ENTITY_ATTACHED(handle2) && !PED.IS_PED_ON_MOUNT(handle2) && !PED.IS_PED_IN_ANY_VEHICLE(handle2, p1: false)) || p.IsHogtied || (character != null && character.Exists() && PED.GET_MOUNT(character.Handle) == handle2) || (character != null && character.Exists() && ENTITY.IS_ENTITY_ATTACHED_TO_ENTITY(handle2, character.Handle)))
		{
			if (nemesisRecord != null)
			{
				_worldNemeses[handle2] = nemesisRecord;
				_keptTied.Add((handle2, nemesisRecord));
			}
			int num = handle2;
			ReleaseIfOurs(&handle2);
			GrudgeLog(string.Format("WIPE ped {0} kept (tied up with you){1} - handed to the game", num, (nemesisRecord != null) ? (" - " + nemesisRecord.Name) : ""));
		}
		else
		{
			ENTITY.SET_ENTITY_AS_MISSION_ENTITY(handle2, p1: true, p2: true);
			p.Delete();
		}
	}

