	}

	private void FlushSaves()
	{
		Guard("saves", () =>
		{
			bool flag = HUD.IS_PAUSE_MENU_ACTIVE();
			if (flag && !_pauseFlushed)
			{
				_pauseFlushed = true;
				if (Environment.TickCount - _perfSince > 60000)
				{
					WritePerf(force: true);
				}
				FinishSlices("the pause menu");
				try
				{
					_nextRosterSave = 0;
					FlushRosterSave();
					if (_worldDirty)
					{
						SaveWorldNow(background: true);
					}
				}
				catch (Exception ex)
				{
					GrudgeLog("SAVE on pause failed: " + ex.Message);
				}
			}
			else if (!flag)
			{
				_pauseFlushed = false;
			}
			if ((flag || _menu.IsOpen || _bulletImpact.ViewerOpen || CAM.IS_SCREEN_FADED_OUT() || CAM.IS_SCREEN_FADING_OUT()) && Game.GameTime >= _nextHiddenSave)
			{
				_nextHiddenSave = Game.GameTime + 5000;
				try
				{
					if (_rosterDirty)
					{
						_nextRosterSave = 0;
						FlushRosterSave();
					}
					else if (_worldDirty)
					{
						SaveWorldNow(background: true);
						_nextWorldSave = Game.GameTime + 60000;
					}
				}
				catch (Exception ex2)
				{
					GrudgeLog("SAVE while hidden failed: " + ex2.Message);
				}
			}
			if (_rosterWriteError != null)
			{
				GrudgeLog("SAVE roster write failed (tried again on the next pass): " + _rosterWriteError);
				_rosterWriteError = null;
			}
			bool flag2 = _combatants.Values.Any((int t) => Game.GameTime - t < 3000) || (_enc != null && _enc.Engaged);
			if (!flag2)
			{
				_fightSaveHoldSince = -1;
			}
			else if (_fightSaveHoldSince < 0)
			{
				_fightSaveHoldSince = Game.GameTime;
			}
			bool flag3 = flag2 && Game.GameTime - _fightSaveHoldSince < 25000;
			if (!flag3 & flag2)
			{
				_fightSaveHoldSince = Game.GameTime;
			}
			XRayLog.Hold = flag3;
			RunSlices(flag3 ? 1.0 : 2.0);
			foreach (var safe in Saves)
			{
				if (!flag3 || !(safe.name != "log"))
				{
					long elapsedTicks = _saveClock.ElapsedTicks;
					try
					{
						safe.flush();
					}
					catch (Exception ex3)
					{
						GrudgeLog("ERROR in save " + safe.name + ": " + ex3.Message);
					}
					double num = (double)(_saveClock.ElapsedTicks - elapsedTicks) * 1000.0 / (double)Stopwatch.Frequency;
					NoteSaveTime(safe.name, num);
					if (num >= 5.0 && safe.name != "log")
					{
						break;
					}
				}
			}
			if (XRayLog.SaveCount != _xraySavesSeen)
			{
				_xraySavesSeen = XRayLog.SaveCount;
				NoteSaveTime("xray log", XRayLog.LastSaveMs);
			}
		});
	}

	private void ForceSaves(bool later = false)
	{
		bool started = !later && SafeFile.BeginWaitBudget(2500);
		try
		{
			ForceSavesNow(later);
		}
		finally
		{
			SafeFile.EndWaitBudget(started);
		}
	}

	private void ForceSavesNow(bool later)
	{
		XRayLog.Hold = false;
		if (!later)
		{
			FinishSlices("a full save");
		}
		else if (Slicing("roster") || Slicing("world"))
		{
			FinishSlices("a save point");
		}
		foreach (var safe in Saves)
		{
			if (later && safe.name == "roster")
			{
				try
				{
					_nextRosterSave = 0;
					FlushRosterSave(force: false, sliced: true);
				}
				catch (Exception ex)
				{
					GrudgeLog("ABORT save roster failed: " + ex.Message);
				}
			}
			else if (later && safe.name == "world")
			{
				try
				{
					if (_worldDirty)
					{
						SaveWorldNow(background: true, sliced: true);
					}
				}
				catch (Exception ex2)
				{
					GrudgeLog("ABORT save world failed: " + ex2.Message);
				}
			}
			else if (later && safe.name == "people")
			{
				try
				{
					SavePeople(force: true, later: true);
				}
				catch (Exception ex3)
				{
					GrudgeLog("ABORT save people failed: " + ex3.Message);
				}
			}
			else if (later && safe.name == "looks")
			{
				try
				{
					SavePrints(later: true);
				}
				catch (Exception ex4)
				{
					GrudgeLog("ABORT save looks failed: " + ex4.Message);
				}
			}
			else
			{
				try
				{
					safe.force();
				}
				catch (Exception ex5)
				{
					GrudgeLog("ABORT save " + safe.name + " failed: " + ex5.Message);
				}
			}
		}
	}

	private bool Slicing(string name)
	{
		return _slices.Any((SliceJob j) => j.Name == name);
	}

	private void StartSlice(string name, string path, object root, int gen, Action<Exception> done)
	{
		_slices.Add(new SliceJob
		{
			Name = name,
			Path = path,
			Json = new SlicedJson(root),
			Gen = gen,
			Done = done
		});
	}

	private bool SliceStillGood(SliceJob j)
	{
		if (!(j.Name == "roster"))
		{
			if (j.Json.Root == _chron)
			{
				return j.Gen == _worldGen;
			}
			return false;
		}
		if (j.Json.Root == Roster)
		{
			return j.Gen == _rosterGen;
		}
		return false;
	}

	private void RunSlices(double budgetMs)
	{
		long t0;
		if (_slices.Count > 0)
		{
			t0 = _saveClock.ElapsedTicks;
			foreach (SliceJob item in _slices.ToList())
			{
				if (!SliceStillGood(item))
				{
					SetAside(item);
					continue;
				}
				double num = Spent();
				bool flag;
				try
				{
					do
					{
						flag = item.Json.Step();
					}
					while (!flag && Spent() < budgetMs);
				}
				catch (Exception ex)
				{
					SliceFailed(item, ex);
					continue;
				}
				double num2 = Spent() - num;
				item.Ms += num2;
				item.Frames++;
				if (num2 > item.MaxMs)
				{
					item.MaxMs = num2;
				}
				if (flag)
				{
					CompleteSlice(item);
				}
				if (!(Spent() >= budgetMs))
				{
					continue;
				}
				break;
			}
		}
		RunAfterSlices();
		double Spent()
		{
			return (double)(_saveClock.ElapsedTicks - t0) * 1000.0 / (double)Stopwatch.Frequency;
		}
	}

	private void CompleteSlice(SliceJob j)
	{
		_slices.Remove(j);
		if (!SliceStillGood(j))
		{
			SetAside(j);
			return;
		}
		SafeFile.WriteLater(j.Path, j.Json.Text, keepBak: true, j.Done);
		if (j.MaxMs >= 15.0)
		{
			GrudgeLog($"SAVETIME {j.Name} took {j.MaxMs:0} ms in one frame (in pieces: {j.Ms:0} ms over {j.Frames} frames)");
		}
	}

	private void SetAside(SliceJob j)
	{
		_slices.Remove(j);
		NemesisMod nemesisMod = this;
		string name = j.Name;
		string text;
		if (j.Name == "roster")
		{
			text = ((j.Json.Root == Roster) ? "saved whole meanwhile" : "the roster was put back / reset");
		}
		else
		{
			text = ((j.Json.Root == _chron) ? "saved whole meanwhile" : "the world was put back / reset");
		}
		nemesisMod.GrudgeLog("SAVE " + name + " in pieces set aside - " + text);
	}

	private void SliceFailed(SliceJob j, Exception ex)
	{
		_slices.Remove(j);
		if (j.Name == "roster")
		{
			_rosterDirty = true;
		}
		else
		{
			_worldDirty = true;
		}
		GrudgeLog("SAVE " + j.Name + " in pieces failed (" + ex.GetType().Name + ": " + ex.Message + ") - saved whole on the next pass");
	}

	private void FinishSlices(string why)
	{
		if (_slices.Count == 0)
		{
			RunAfterSlices();
			return;
		}
		foreach (SliceJob item in _slices.ToList())
		{
			if (!SliceStillGood(item))
			{
				SetAside(item);
				continue;
			}
			try
			{
				item.Json.Finish();
			}
			catch (Exception ex)
			{
				SliceFailed(item, ex);
				continue;
			}
			CompleteSlice(item);
		}
		RunAfterSlices();
	}

	private void AfterSlices(Action a)
	{
		if (_slices.Count == 0)
		{
			a();
		}
		else
		{
			_afterSlices.Add(a);
		}
	}

	private void RunAfterSlices()
	{
		if (_slices.Count > 0 || _afterSlices.Count == 0)
		{
			return;
		}
		List<Action> list = _afterSlices.ToList();
		_afterSlices.Clear();
		foreach (Action item in list)
		{
			try
			{
				item();
			}
			catch (Exception ex)
			{
				GrudgeLog("SAVE after the pieces failed: " + ex.Message);
			}
		}
	}

	private void NoteSaveTime(string name, double ms)
	{
		if (!(ms < 15.0))
		{
			bool flag = _combatants.Values.Any((int t) => Game.GameTime - t < 3000) || (_enc != null && _enc.Engaged);
			GrudgeLog(string.Format("SAVETIME {0} took {1:0} ms{2}", name, ms, flag ? " - IN A FIGHT" : ""));
		}
	}

	private void FlushPrints()
	{
		if (_printsDirty && Game.GameTime >= _nextPrintsSave)
		{
			_nextPrintsSave = Game.GameTime + 60000;
			SavePrints(later: true);
		}
	}

	private static int PadRowLen(int gy)
	{
		if (gy >= PadGridRows.Length)
		{
			return PadGridKeys.Length;
		}
		return PadGridRows[gy].Length;
	}

	private void OpenSearch(bool pad)
	{
		if (_menu.IsOpen || _bulletImpact.ViewerOpen)
		{
			_search = new SearchPanel
			{
				OverXRay = _bulletImpact.ViewerOpen,
				Pad = pad,
				OnKeys = pad
			};
			UiSound("MENU_ENTER");
			RunSearch();
		}
	}

	private void CloseSearch()
	{
		if (_search == null)
		{
			return;
		}
		if (_search.PadKb)
		{
			try
			{
				MISC.CANCEL_ONSCREEN_KEYBOARD();
			}
			catch
			{
			}
		}
		_search = null;
		UiSound("MENU_CLOSE");
	}

	private void StartPadKeyboard()
	{
		try
		{
			Crumbs.Native("search onscreen keyboard");
			MISC.DISPLAY_ONSCREEN_KEYBOARD(0, "", "", _search.Query ?? "", "", "", "", 40);
			_search.PadKb = true;
			_search.PadKbAt = Environment.TickCount;
		}
		catch (Exception ex)
		{
			GrudgeLog("SEARCH the game's keyboard failed: " + ex.Message);
			_search.PadKb = false;
		}
	}

	private void UpdateTabHold()
	{
		if (_tabDownAt == 0)
		{
			return;
		}
		if (!UiMouse.KeyDownNow(Keys.Tab))
		{
			bool flag = _tabDownAt != -1;
			_tabDownAt = 0;
			if (flag && _search == null && (_menu.IsOpen || _bulletImpact.ViewerOpen))
			{
				Dispatch(Keys.Tab);
			}
		}
		else if (_tabDownAt != -1 && Environment.TickCount - _tabDownAt > 600)
		{
			_tabDownAt = -1;
			if (_search == null)
			{
				OpenSearch(pad: false);
			}
		}
	}

	private void UpdateSearch()
	{
		if (_search == null)
		{
			return;
		}
		if (!_menu.IsOpen && !_bulletImpact.ViewerOpen)
		{
			_search = null;
			return;
		}
		Game.DisableAllControlsThisFrame();
		if (!_search.PadKb)
		{
			return;
		}
		eInputType[] padKeyboardInputs = PadKeyboardInputs;
		foreach (eInputType p in padKeyboardInputs)
		{
			PAD.ENABLE_CONTROL_ACTION(0, (uint)p, p2: true);
		}
		switch (MISC.UPDATE_ONSCREEN_KEYBOARD())
		{
		case 1:
		{
			string text = null;
			try
			{
				text = MISC.GET_ONSCREEN_KEYBOARD_RESULT();
			}
			catch
			{
			}
			_search.PadKb = false;
			_search.Query = (text ?? "").Trim();
			_search.Sel = 0;
			_search.Top = 0;
			RunSearch();
			GrudgeLog($"SEARCH pad keyboard: '{_search.Query}' - {_search.Hits.Count} found");
			break;
		}
		case 2:
			_search.PadKb = false;
			if (string.IsNullOrEmpty(_search.Query))
			{
				CloseSearch();
			}
			break;
		case 3:
			if (Environment.TickCount - _search.PadKbAt > 1500)
			{
				_search.PadKb = false;
				GrudgeLog("SEARCH the game's on-screen keyboard didn't come up - type with the keyboard");
				ShowNotification("enRAGE: the game's keyboard didn't open - type the name on the keyboard.");
			}
			break;
		}
	}

	private void PadSearchKey(Keys key)
	{
		SearchPanel s = _search;
		if (s == null)
		{
			return;
		}
		if (!s.Pad)
		{
			s.Pad = true;
			s.OnKeys = true;
		}
		if (!s.OnKeys)
		{
			if (key == Keys.Escape || key == Keys.Q || key == Keys.Tab || (key == Keys.Up && s.Sel == 0))
			{
				s.OnKeys = true;
				UiSound("NAV_UP");
			}
			else if (key == Keys.Up || key == Keys.Down || key == Keys.Return)
			{
				SearchKey(key, shift: false);
			}
			return;
		}
		int num = PadRowLen(s.GY);
		int num2 = PadGridRows.Length + 1;
		switch (key)
		{
		case Keys.Left:
			s.GX = (s.GX - 1 + num) % num;
			UiSound("NAV_LEFT");
			break;
		case Keys.Right:
			s.GX = (s.GX + 1) % num;
			UiSound("NAV_RIGHT");
			break;
		case Keys.Down:
			if (s.GY == num2 - 1 && s.Hits.Count > 0)
			{
				ToResults();
				break;
			}
			goto case Keys.Up;
		case Keys.Up:
		{
			int num3 = PadRowLen(s.GY);
			s.GY = (s.GY + ((key == Keys.Down) ? 1 : (num2 - 1))) % num2;
			int num4 = PadRowLen(s.GY);
			s.GX = Math.Min(num4 - 1, (int)Math.Round((float)(s.GX * (num4 - 1)) / (float)Math.Max(1, num3 - 1)));
			UiSound((key == Keys.Down) ? "NAV_DOWN" : "NAV_UP");
			break;
		}
		case Keys.Return:
			if (s.GY < PadGridRows.Length)
			{
				AddChar(PadGridRows[s.GY][s.GX]);
			}
			else if (s.GX == 0)
			{
				AddChar(' ');
			}
			else if (s.GX == 1)
			{
				Delete();
			}
			else
			{
				ToResults();
			}
			UiSound("SELECT");
			break;
		case Keys.Back:
			Delete();
			UiSound("BACK");
			break;
		case Keys.Space:
			if (s.Query.Length > 0 && !s.Query.EndsWith(" "))
			{
				AddChar(' ');
			}
			break;
		case Keys.Tab:
			ToResults();
			break;
		case Keys.Escape:
			CloseSearch();
			break;
		}
		void AddChar(char c)
		{
			if (s.Query.Length < 40)
			{
				bool flag = s.Query.Length == 0 || s.Query.EndsWith(" ");
				s.Query += (flag ? char.ToUpperInvariant(c) : char.ToLowerInvariant(c));
				s.Sel = 0;
				s.Top = 0;
				RunSearch();
			}
		}
		void Delete()
		{
			if (s.Query.Length > 0)
			{
				s.Query = s.Query.Substring(0, s.Query.Length - 1);
				s.Sel = 0;
				s.Top = 0;
				RunSearch();
			}
		}
		void ToResults()
		{
			if (s.Hits.Count > 0)
			{
				s.OnKeys = false;
				s.Sel = 0;
				s.Top = 0;
				UiSound("NAV_DOWN");
			}
		}
	}

	private bool SearchKey(Keys key, bool shift)
	{
		SearchPanel search = _search;
		if (search == null)
		{
			return false;
		}
		if (search.PadKb)
		{
			return true;
		}
		switch (key)
		{
		case Keys.Escape:
			CloseSearch();
			return true;
		case Keys.Back:
			if (search.Query.Length == 0)
			{
				CloseSearch();
				return true;
			}
			search.Query = search.Query.Substring(0, search.Query.Length - 1);
			search.Sel = 0;
			search.Top = 0;
			RunSearch();
			return true;
		case Keys.Up:
			if (search.Hits.Count > 0)
			{
				search.Sel = (search.Sel - 1 + search.Hits.Count) % search.Hits.Count;
				UiSound("NAV_UP");
			}
			return true;
		case Keys.Down:
			if (search.Hits.Count > 0)
			{
				search.Sel = (search.Sel + 1) % search.Hits.Count;
				UiSound("NAV_DOWN");
			}
			return true;
		case Keys.Return:
		{
			if (search.Hits.Count == 0)
			{
				return true;
			}
			SearchHit searchHit = search.Hits[Math.Max(0, Math.Min(search.Sel, search.Hits.Count - 1))];
			GrudgeLog("SEARCH '" + search.Query + "' -> " + searchHit.Kind + " " + searchHit.Label);
			_search = null;
			UiSound("SELECT");
			try
			{
				searchHit.Go();
			}
			catch (Exception ex)
			{
				GrudgeLog("SEARCH jump failed: " + ex.Message);
			}
			return true;
		}
		default:
		{
			char c = KeyChar(key, shift);
			if (c != '\0' && search.Query.Length < 40)
			{
				search.Query += c;
				search.Sel = 0;
				search.Top = 0;
				RunSearch();
			}
			return true;
		}
		}
	}

	private static char KeyChar(Keys k, bool shift)
	{
		if (k >= Keys.A && k <= Keys.Z)
		{
			return (char)((shift ? 65 : 97) + (k - 65));
		}
		if (k >= Keys.D0 && k <= Keys.D9 && !shift)
		{
			return (char)(48 + (k - 48));
		}
		if (k >= Keys.NumPad0 && k <= Keys.NumPad9)
		{
			return (char)(48 + (k - 96));
		}
		switch (k)
		{
		case Keys.Space:
			return ' ';
		case Keys.OemQuotes:
			return '\'';
		case Keys.Subtract:
		case Keys.OemMinus:
			return '-';
		case Keys.Decimal:
		case Keys.OemPeriod:
			return '.';
		default:
			return '\0';
		}
	}

	private static int MatchRank(string text, string q)
	{
		if (string.IsNullOrEmpty(text))
		{
			return -1;
		}
		int num = text.IndexOf(q, StringComparison.OrdinalIgnoreCase);
		if (num < 0)
		{
			return -1;
		}
		if (num == 0)
		{
			return 0;
		}
		if (text[num - 1] != ' ' && text[num - 1] != '\'' && text[num - 1] != '-')
		{
			return 2;
		}
		return 1;
	}

	private void RunSearch()
	{
		SearchPanel search = _search;
		search.Hits.Clear();
		string text = (search.Query ?? "").Trim();
		if (text.Length == 0)
		{
			return;
		}
		List<SearchHit> hits = new List<SearchHit>();
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			NemesisRecord nemesisRecord = LeaderPageOf(gang);
			if (nemesisRecord != null && nemesisRecord.LeaderPage)
			{
				hashSet.Add(nemesisRecord.Name);
				Gang gg = gang;
				Add("LEADER", nemesisRecord.Name, "Leader of the " + gang.Name, Theme.Gold, MatchRank(nemesisRecord.Name, text), 0, () =>
				{
					ShowRecordPage(LeaderPageOf(gg));
				});
			}
		}
		foreach (NemesisRecord item3 in Roster)
		{
			if (item3 == null || string.IsNullOrEmpty(item3.Name))
			{
				continue;
			}
			int num = Math.Max(MatchRank(item3.Name, text), (item3.Title != null && item3.Title.Length > 0) ? MatchRank(item3.FullName, text) : (-1));
			if (num >= 0)
			{
				hashSet.Add(item3.Name);
				Gang gang2 = Gangs.ById(item3.Gang);
				bool flag = !item3.IsAlive || (item3.PresumedDead && !NemesisRecord.ShowSecrets);
				string sub = ((gang2 != null) ? gang2.Name : "Loner") + "  -  " + RosterMenu.RankText(item3) + "  -  " + (flag ? item3.Status : item3.HateTier.ToString());
				NemesisRecord rr = item3;
				Add(flag ? "FALLEN" : "NEMESIS", item3.FullName, sub, flag ? Theme.Dim : UiDraw.HateColor(item3.HateTier), num, (!flag) ? 1 : 4, () =>
				{
					ShowRecordPage(rr);
				});
			}
		}
		foreach (NemesisRecord item4 in StoryRoster)
		{
			int num2 = MatchRank(item4.Name, text);
			if (num2 >= 0)
			{
				hashSet.Add(item4.Name);
				NemesisRecord rr2 = item4;
				Add("THE GANG", item4.Name, string.IsNullOrEmpty(item4.Title) ? "Van der Linde gang" : ("Van der Linde gang  -  " + item4.Title), VdlAccent, num2, 2, () =>
				{
					ShowRecordPage(rr2);
				});
			}
		}
		foreach (Acquaintance person in People)
		{
			if (person == null || string.IsNullOrEmpty(person.Name) || hashSet.Contains(person.Name))
			{
				continue;
			}
			int num3 = MatchRank(person.Name, text);
			if (num3 < 0)
			{
				continue;
			}
			Acquaintance aa = person;
			string text2;
			if (person.Dead)
			{
				text2 = "Dead";
			}
			else
			{
				text2 = (person.Met ? "Met" : "Seen");
			}
			string sub2 = text2 + (string.IsNullOrEmpty(person.Town) ? "" : ("  -  " + person.Town)) + (string.IsNullOrEmpty(person.Temper) ? "" : ("  -  " + person.Temper));
			Add("PERSON", person.FullName, sub2, (r: 170, g: 200, b: 150), num3, 3, () =>
			{
				NemesisRecord nemesisRecord2 = PersonRecord(aa);
				if (nemesisRecord2 != null)
				{
					ShowRecordPage(nemesisRecord2);
				}
			});
		}
		foreach (var item5 in WarList())
		{
			WarRecord item = item5.w;
			bool item2 = item5.live;
			string text3 = WarName(item);
			Gang gang3 = Gangs.ById(item.A);
			Gang gang4 = Gangs.ById(item.B);
			int num4 = Math.Max(MatchRank(text3, text), Math.Max(MatchRank(gang3?.Name, text), MatchRank(gang4?.Name, text)));
			if (num4 >= 0)
			{
				WarRecord ww = item;
				Add("WAR", text3, (DistrictByKey(item.District)?.Name ?? item.District) + "  -  " + gang3?.Name + " vs " + gang4?.Name + "  -  " + (item2 ? $"Day {WarDay(item)}" : "Over"), Theme.NativeRed, num4, 5, () =>
				{
					ShowWarPage(ww);
				});
			}
		}
		int num5 = 0;
		foreach (WorldEvent item6 in ChronicleFor(0))
		{
			if (num5 >= 25)
			{
				break;
			}
			int num6 = MatchRank(item6.Title, text);
			if (num6 < 0 && item6.People != null)
			{
				foreach (WorldPart person2 in item6.People)
				{
					num6 = Math.Max(num6, MatchRank(person2.Name, text));
				}
			}
			if (num6 >= 0)
			{
				num5++;
				WorldEvent ee = item6;
				Add("EVENT", item6.Title, (string.IsNullOrEmpty(item6.When) ? "" : (item6.When + "  -  ")) + KindLabel(item6.Kind) + (string.IsNullOrEmpty(item6.Place) ? "" : ("  -  " + item6.Place)), KindColor(item6.Kind), num6, 6, () =>
				{
					ShowEventPage(ee);
				});
			}
		}
		foreach (var item7 in _bulletImpact.SearchXRays())
		{
			int num7 = MatchRank(item7.victim, text);
			if (num7 >= 0)
			{
				var (id, _, _, _, _) = item7;
				Add("X-RAY", item7.victim, string.Format("{0} {1}{2}{3}", item7.shots, (item7.shots == 1) ? "wound" : "wounds", item7.animal ? "  -  animal" : "", item7.killed ? "  -  killed" : ""), (r: 120, g: 150, b: 210), num7, 7, () =>
				{
					ShowXRayOf(id);
				});
			}
		}
		search.Hits = (from h in hits
			orderby h.Rank, h.Label
			select h).Take(60).ToList();
		search.Sel = Math.Min(search.Sel, Math.Max(0, search.Hits.Count - 1));
		void Add(string kind, string label, string sub3, (int r, int g, int b) c, int rank, int kindOrder, Action go)
		{
			if (rank >= 0)
			{
				hits.Add(new SearchHit
				{
					Kind = kind,
					Label = label,
					Sub = sub3,
					Color = c,
					Rank = rank * 10 + kindOrder,
					Go = go
				});
			}
		}
	}

