	private void SpawnSighting(NemesisRecord rec, Vector3 spot)
	{
		Vector3 vector = World.GetSafeCoordForPed(spot);
		if (vector.DistanceTo(spot) > 6f || (vector.X == 0f && vector.Y == 0f))
		{
			vector = spot;
		}
		Model model = new Model(rec.ModelHash);
		if (!model.IsValid || !model.IsPed)
		{
			model = new Model((PedHash)424175505u);
		}
		Ped ped = SpawnPed((PedHash)model.Hash, vector + new Vector3(0f, 0f, 0.1f), _rng.Next(360));
		STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)model.Hash);
		if (!(ped == null))
		{
			MakeOurs(ped.Handle);
			WEAPON.REMOVE_ALL_PED_WEAPONS(ped.Handle, p1: true, p2: true);
			ped.BlockPermanentEvents = true;
			ApplyScars(ped, rec);
			_sightingCrippleAt = Game.GameTime + 2500;
			_sightingPed = ped;
			_sightingRec = rec;
			_sightingSpoke = false;
			Crumbs.Native("Sightings blip add (V2)");
			_sightingBlip = ped.AddBlip((BlipType)2545348716u);
			if (_sightingBlip != null)
			{
				Function.Call(11290983183885202434uL, _sightingBlip.Handle, new InputArgument(UiDraw.ForeverVarString(rec.FullName + " (crippled)")));
			}
		}
	}

	private void UpdateSightingPed(Ped player)
	{
		if (_sightingPed == null)
		{
			return;
		}
		NemesisRecord sightingRec = _sightingRec;
		if (!_sightingPed.Exists() || !Roster.Contains(sightingRec))
		{
			ClearSighting(delete: false);
		}
		else if (_sightingPed.IsDead)
		{
			int num = PED.GET_PED_SOURCE_OF_DEATH(_sightingPed.Handle);
			bool flag = ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(_sightingPed.Handle, player.Handle, p2: true, p3: true);
			bool flag2 = num == player.Handle || ((num == 0) & flag);
			if (!flag2 && !flag && (num == 0 || num == _sightingPed.Handle))
			{
				GrudgeLog("SIGHTING " + sightingRec.Name + " died with nobody's hand on it (a fall) - not counted, he's still laid up");
				ClearSighting(delete: true);
				return;
			}
			try
			{
				ResolveNemesisDeath(_sightingPed, sightingRec, executed: true);
			}
			catch (Exception ex)
			{
				GrudgeLog("SIGHTING death handling failed: " + ex.Message);
			}
			sightingRec.IsAlive = false;
			sightingRec.PresumedDead = false;
			SaveRoster();
			DeathNotice(flag2 ? ("You finished " + sightingRec.FullName + ". He never stood a chance.") : (sightingRec.FullName + " is dead - he never stood a chance."));
			ClearSighting(delete: false);
		}
		else
		{
			float num2 = _sightingPed.Position.DistanceTo(player.Position);
			if (!_sightingSpoke && num2 < 4f)
			{
				_sightingSpoke = true;
				ShowSubtitle(sightingRec.FullName + ": \"" + Taunts.Paralyzed(sightingRec, _rng) + "\"");
			}
			if (num2 > 150f)
			{
				ClearSighting(delete: true);
			}
		}
	}

	internal void ReviveFellMen()
	{
		string[] fellNotKilled = FellNotKilled;
		foreach (string id in fellNotKilled)
		{
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == id);
			if (nemesisRecord == null || nemesisRecord.IsAlive)
			{
				continue;
			}
			nemesisRecord.IsAlive = true;
			nemesisRecord.PresumedDead = false;
			nemesisRecord.KilledByPlayer = false;
			nemesisRecord.History?.RemoveAll((HistoryEntry h) => h.Text != null && h.Text.StartsWith("KILLED BY") && h.Text.Contains("Saint Denis"));
			Chronicle.DeathNews?.RemoveAll((DeathNews n) => n.DeadId == id);
			Chronicle.PeopleNews?.RemoveAll((DeathNews n) => n.DeadId == id);
			Chronicle.RetiredNames?.Remove(nemesisRecord.Name);
			foreach (WorldEvent item in Chronicle.Events.Where((WorldEvent e) => e.People != null && e.People.Any((WorldPart p) => p.Id == id && p.Outcome == "KILLED")).ToList())
			{
				item.People.RemoveAll((WorldPart p) => p.Id == id);
				if (item.People.Count == 0)
				{
					Chronicle.Events.Remove(item);
				}
			}
			SaveRoster();
			SaveWorld();
			GrudgeLog("SIGHTING repair: " + nemesisRecord.Name + " didn't die - he fell through the doctor's floor before it had loaded. He's back, still laid up.");
		}
	}

	private unsafe void ClearSighting(bool delete)
	{
		ClearPendingSighting();
		if (_sightingBlip != null && _sightingBlip.Exists())
		{
			_sightingBlip.Delete();
		}
		_sightingBlip = null;
		if (_sightingPed != null && _sightingPed.Exists())
		{
			if (delete && SafeToDelete(_sightingPed))
			{
				_sightingPed.Delete();
			}
			else
			{
				int handle = _sightingPed.Handle;
				ReleaseIfOurs(&handle);
			}
		}
		_sightingPed = null;
		_sightingRec = null;
	}

	private static SocialOption MoneyFor(NemesisRecord r, Personality t)
	{
		if (t == Personality.Proud || (r.Wealth == Wealth.Rich && t != Personality.Greedy))
		{
			return null;
		}
		return new SocialOption
		{
			Key = "money",
			Text = "Give Him a Few Dollars ($5)",
			Cost = 5,
			Hate = ((t == Personality.Proud) ? 3 : (-8)),
			Need = "Money",
			Reply = t switch
			{
				Personality.Greedy => "Five? ...Fine. It's a start.", 
				Personality.Proud => "I don't need your charity.", 
				_ => "...That's decent of you. Real decent.", 
			}
		};
	}

	private SocialOption SocialFor(NemesisRecord r)
	{
		if (r == null || Gangs.Orders(r))
		{
			return null;
		}
		Personality personality = r.Personality ?? Personality.Cold;
		SocialOption socialOption = MoneyFor(r, personality);
		if (socialOption != null)
		{
			return socialOption;
		}
		if (Quirks.Has(r, "drunk") || Mind.N(r, "Drink") >= 60)
		{
			return new SocialOption
			{
				Key = "drink",
				Text = "Buy Him a Drink ($2)",
				Cost = 2,
				Hate = -6,
				Need = "Drink",
				Reply = ((personality == Personality.Proud) ? "...I'll drink it. Don't mean we're friends." : "Well now. Don't mind if I do.")
			};
		}
		SocialOption socialOption2 = MoneyFor(r, personality);
		if (socialOption2 != null)
		{
			return socialOption2;
		}
		if (personality == Personality.Proud)
		{
			return new SocialOption
			{
				Key = "respect",
				Text = "Show Him Respect",
				Hate = -6,
				Reply = "...Hm. At least you know who you're talking to."
			};
		}
		if (r.TraitsRolled && r.Sociability == Sociability.Outgoing)
		{
			return new SocialOption
			{
				Key = "smoke",
				Text = "Share a Smoke",
				Hate = -4,
				Need = "Company",
				Reply = "Obliged. ...You're alright, for a son of a bitch."
			};
		}
		return new SocialOption
		{
			Key = "shake",
			Text = "Shake His Hand",
			Hate = -3,
			Reply = ((personality == Personality.Hothead) ? "...Fine. Don't make me regret it." : "Alright. We're square, for now.")
		};
	}

	private unsafe (Ped ped, NemesisRecord rec, Provocation p) SocialTarget(Ped player)
	{
		if (_convo != null || _interro != null || PLAYER.IS_PLAYER_FREE_AIMING(Game.Player.Handle))
		{
			return (ped: null, rec: null, p: null);
		}
		int num = 0;
		if (!PLAYER.GET_PLAYER_INTERACTION_TARGET_ENTITY(Game.Player.Handle, &num, p2: false, p3: false) || num == 0)
		{
			return (ped: null, rec: null, p: null);
		}
		Ped ped = Entity.FromHandle(num) as Ped;
		if (ped == null || !ped.Exists() || ped.IsDead || !ped.IsHuman || ped.IsPlayer || ped.IsHogtied || Kids.IsChild(ped))
		{
			return (ped: null, rec: null, p: null);
		}
		if (ped.Position.DistanceTo(player.Position) > 6f || PED.IS_PED_IN_COMBAT(ped.Handle, player.Handle))
		{
			return (ped: null, rec: null, p: null);
		}
		if (GameEventPed(ped) || IsStoryPed(ped) || GameOwned(ped))
		{
			return (ped: null, rec: null, p: null);
		}
		if (_lastPromptPed != null && _lastPromptPed.Handle == ped.Handle && Game.GameTime - _lastPromptAt < 800)
		{
			return (ped: null, rec: null, p: null);
		}
		NemesisRecord nemesisRecord = RecordAt(ped.Handle);
		if (nemesisRecord != null)
		{
			if (_enc != null && _enc.Engaged && ped == _activeNemesisPed)
			{
				return (ped: null, rec: null, p: null);
			}
			if (_townMen.Any((TownMan t) => t.Ped == ped && t.Engaged))
			{
				return (ped: null, rec: null, p: null);
			}
			return (ped: ped, rec: nemesisRecord, p: null);
		}
		if (_provoked.TryGetValue(ped.Handle, out var value) && value.Record == null && value.Score > 0f && !value.Settled)
		{
			return (ped: ped, rec: value.Shadow, p: value);
		}
		if (_named.TryGetValue(ped.Handle, out var value2) && value2.Met && !value2.Story && !IsOurs(ped.Handle) && !IsLawman(ped) && !GameOwned(ped))
		{
			return (ped: ped, rec: ShadowOf(ped), p: null);
		}
		return (ped: null, rec: null, p: null);
	}

