	private void Stage(Action run, Func<bool> still = null, Action done = null)
	{
		_staged.Enqueue(new StagedJob
		{
			Run = run,
			Still = still,
			Done = done
		});
	}

	private void RunStaged()
	{
		if (_staged.Count == 0)
		{
			return;
		}
		StagedJob stagedJob = _staged.Dequeue();
		try
		{
			if (stagedJob.Still == null || stagedJob.Still())
			{
				stagedJob.Run();
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("STAGED a job failed: " + ex.Message);
		}
		finally
		{
			try
			{
				stagedJob.Done?.Invoke();
			}
			catch
			{
			}
		}
	}

	private void ClearStaged()
	{
		while (_staged.Count > 0)
		{
			StagedJob stagedJob = _staged.Dequeue();
			try
			{
				stagedJob.Done?.Invoke();
			}
			catch
			{
			}
		}
	}

	private void WitnessQueueTick()
	{
		for (int i = 0; i < 2; i++)
		{
			if (_witnessBatches.Count <= 0)
			{
				break;
			}
			WitnessBatch witnessBatch = _witnessBatches.Peek();
			if (witnessBatch.Jobs.Count > 0)
			{
				var (p, d, fearHere) = witnessBatch.Jobs.Dequeue();
				try
				{
					WitnessOne(witnessBatch, p, d, fearHere);
				}
				catch (Exception ex)
				{
					GrudgeLog("WITNESS failed: " + ex.Message);
				}
			}
			if (witnessBatch.Jobs.Count == 0)
			{
				_witnessBatches.Dequeue();
				WitnessDone(witnessBatch);
			}
		}
	}

	private void TownSpotTick(Ped player)
	{
		string currentTown = _currentTown;
		if (currentTown == null || !NearTownCore(player, currentTown) || WorldBusy(player))
		{
			return;
		}
		if (!_townSpots.TryGetValue(currentTown, out var value))
		{
			value = (_townSpots[currentTown] = new TownSpotStock());
		}
		if (value.Tries >= 400 || (value.About.Count >= 16 && value.Street.Count >= 16))
		{
			return;
		}
		_townSpotAbout = !_townSpotAbout;
		Vector3 position = player.Position;
		if (_townSpotAbout && value.About.Count < 16 && TownSpots.TryGetValue(currentTown, out (Vector3?, Vector3?) value2))
		{
			List<Vector3> list = (from v in new Vector3?[2] { value2.Item2, value2.Item1 }
				where v.HasValue
				select v.Value).ToList();
			if (list.Count == 0)
			{
				return;
			}
			Vector3 vector = list[_rng.Next(list.Count)];
			double num = _rng.NextDouble() * Math.PI * 2.0;
			float num2 = 6f + (float)_rng.NextDouble() * 30f;
			Vector3 p = vector + new Vector3((float)Math.Cos(num) * num2, (float)Math.Sin(num) * num2, 0f);
			if (!(p.DistanceTo2D(position) > 180f))
			{
				value.Tries++;
				Vector3 p2 = GroundOnSpot(p);
				if (!UpHigh(p2) && Outdoors(p2) && !value.About.Any((Vector3 x) => x.DistanceTo(p2) < 4f))
				{
					value.About.Add(p2);
				}
			}
		}
		else
		{
			if (value.Street.Count >= 16 || !TownCore(currentTown, out var centre, out var radius))
			{
				return;
			}
			double num3 = _rng.NextDouble() * Math.PI * 2.0;
			float num4 = (float)Math.Sqrt(_rng.NextDouble()) * radius * 0.85f;
			Vector3 vector2 = centre + new Vector3((float)Math.Cos(num3) * num4, (float)Math.Sin(num3) * num4, 0f);
			if (!(vector2.DistanceTo2D(position) > 180f))
			{
				value.Tries++;
				Vector3 safeCoordForPed = World.GetSafeCoordForPed(vector2);
				Vector3 p3 = (((safeCoordForPed.X == 0f && safeCoordForPed.Y == 0f) || safeCoordForPed.DistanceTo2D(vector2) > 15f) ? GroundOnSpot(vector2) : safeCoordForPed);
				if (p3.DistanceTo2D(centre) <= radius && !UpHigh(p3) && Outdoors(p3) && !value.Street.Any((Vector3 x) => x.DistanceTo(p3) < 4f))
				{
					value.Street.Add(p3);
				}
			}
		}
	}

	private bool StockedSpotLow(Vector3 p, string town)
	{
		if (town == null || !TownCore(town, out var centre, out var _) || centre.Z == 0f)
		{
			return true;
		}
		if (p.Z > centre.Z + 6f)
		{
			return !(p.Z > Game.Player.Character.Position.Z + 6f);
		}
		return true;
	}

	private List<StashSpot> LoadStashSpots()
	{
		List<StashSpot> list = BuiltInStashSpots.Select((StashSpot stashSpot) =>
		{
			stashSpot.BuiltIn = true;
			return stashSpot;
		}).ToList();
		try
		{
			if (File.Exists(StashSpotsPath))
			{
				List<StashSpot> list2 = JsonConvert.DeserializeObject<List<StashSpot>>(File.ReadAllText(StashSpotsPath)) ?? new List<StashSpot>();
				foreach (StashSpot s in list2.Where((StashSpot stashSpot) => stashSpot?.Town != null))
				{
					if (!list.Any((StashSpot o) => o.Town == s.Town && o.Pos.DistanceTo(s.Pos) < 3f))
					{
						list.Add(s);
					}
				}
				GrudgeLog(string.Format("STASHSPOT {0} placed spot(s) loaded ({1})", list2.Count, string.Join(", ", from stashSpot in list
					group stashSpot by stashSpot.Town into gr
					select $"{gr.Key} {gr.Count()}")));
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("STASHSPOT stash_spots.json unreadable: " + ex.Message);
		}
		return list;
	}

	private void SaveStashSpots()
	{
		try
		{
			SafeFile.Write(StashSpotsPath, JsonConvert.SerializeObject(StashSpots.Where((StashSpot s) => !s.BuiltIn).ToList(), Formatting.Indented));
		}
		catch (Exception ex)
		{
			GrudgeLog("STASHSPOT save failed: " + ex.Message);
		}
	}

	internal void DebugPlaceStashSpot(Ped p)
	{
		Vector3 position = p.Position;
		string town = _currentTown ?? TownNear(position);
		if (town == null)
		{
			SpawnerSays("stand in a town to place a stash spot.");
			return;
		}
		Vector3 g = GroundOnSpot(position);
		if (g == Vector3.Zero)
		{
			g = position;
		}
		if (StashSpots.Any((StashSpot s) => s.Town == town && s.Pos.DistanceTo2D(g) < 3f))
		{
			SpawnerSays("there's a stash spot here already.");
			return;
		}
		StashSpot item = new StashSpot
		{
			Town = town,
			X = g.X,
			Y = g.Y,
			Z = g.Z,
			H = p.Heading
		};
		StashSpots.Add(item);
		SaveStashSpots();
		int num = Enumerable.Count(StashSpots, (StashSpot s) => s.Town == town);
		GrudgeLog($"STASHSPOT placed in {town} at {g.X:0.0},{g.Y:0.0},{g.Z:0.0} heading {p.Heading:0} ({num} in {town})");
		SpawnerSays($"stash spot placed - {num} in {town}. A stash piles up here, facing the way you face.");
		if (_iconBlips.ContainsKey(IconKind.Supplies))
		{
			ShowIcons(IconKind.Supplies);
		}
	}

	internal void DebugRemoveStashSpot(Ped p)
	{
		Vector3 pos = p.Position;
		StashSpot near = (from s in StashSpots
			where s.Pos.DistanceTo2D(pos) < 15f
			orderby s.Pos.DistanceTo2D(pos)
			select s).FirstOrDefault();
		if (near == null)
		{
			SpawnerSays("no stash spot within 15 m.");
			return;
		}
		if (near.BuiltIn)
		{
			SpawnerSays("that spot is built into the mod - it can't be removed here.");
			return;
		}
		StashSpots.Remove(near);
		SaveStashSpots();
		GrudgeLog($"STASHSPOT removed in {near.Town} at {near.X:0.0},{near.Y:0.0}");
		SpawnerSays($"stash spot removed - {Enumerable.Count(StashSpots, (StashSpot s) => s.Town == near.Town)} left in {near.Town}.");
		if (_iconBlips.ContainsKey(IconKind.Supplies))
		{
			ShowIcons(IconKind.Supplies);
		}
	}

	private void UpdateStoryProgress(Ped player)
	{
		if (Game.GameTime < _nextStoryCheck)
		{
			return;
		}
		_nextStoryCheck = Game.GameTime + 5000;
		Vector3 pos = player.Position;
		int num = 0;
		string text = null;
		if (Models.Name(player) == "player_three")
		{
			num = 7;
			text = "playing as John";
		}
		else if (pos.Y < -4000f)
		{
			num = 5;
			text = "Guarma";
		}
		else
		{
			if (_gangHashes == null)
			{
				_gangHashes = new HashSet<uint>(CampKeyOfModel.Keys);
			}
			List<Ped> list = (from ped in PedsAround(player)
				where ped != null && ped.Exists() && !ped.IsDead && !ped.IsPlayer && _gangHashes.Contains((uint)ped.Model.Hash) && !IsOurs(ped.Handle) && ped.Position.DistanceTo(pos) < 70f
				select ped).ToList();
			foreach (Ped p in list)
			{
				string key = CampPeople.FirstOrDefault((KeyValuePair<string, (string model, int willing)> kv) => MISC.GET_HASH_KEY(kv.Value.model) == (uint)p.Model.Hash).Key;
				if (key != null)
				{
					_storySeenAlive.Add(key);
				}
			}
			if (list.Count >= 3 && !InsideAnyTown(pos) && !MISC.GET_MISSION_FLAG())
			{
				((int, string, float, float), float) tuple = (from c in ChapterCamps
					select (c: c, d: new Vector3(pos.X - c.x, pos.Y - c.y, 0f).Length()) into t
					orderby t.d
					select t).First();
				if (tuple.Item2 < 400f)
				{
					num = tuple.Item1.Item1;
					text = tuple.Item1.Item2;
				}
				else if (_storyUnknownLogged++ < 3)
				{
					GrudgeLog($"STORY gang camp at {pos.X:0},{pos.Y:0} matches no chapter camp (nearest {tuple.Item1.Item2}, {tuple.Item2:0} m)");
				}
			}
		}
		if (num == 7 && Chronicle.Era < 1907 && !_holdTurn)
		{
			bool alreadyEpilogue = Chronicle.StoryChapter >= 7;
			try
			{
				EightYearsLater(text, debug: false, alreadyEpilogue);
				return;
			}
			catch (Exception ex)
			{
				GrudgeLog("EPILOGUE the turn failed: " + ex);
				return;
			}
		}
		bool flag = Config.StoryChapterSet > 0 && num != 7 && Chronicle.StoryChapter < 7;
		if (flag)
		{
			num = Config.StoryChapterSet;
		}
		if (num == 0 || num == Chronicle.StoryChapter)
		{
			return;
		}
		int storyChapter = Chronicle.StoryChapter;
		Dictionary<string, int> regBefore = ChapterRegard.Keys.ToDictionary((string k) => k, RegardOf);
		Chronicle.StoryChapter = num;
		Chronicle.StoryChapterAt = GameMinutesNow();
		SaveWorld();
		GrudgeLog(string.Format("STORY {0} -> chapter {1} (was {2})", flag ? "chapter set by you ([Calm] StoryChapter)" : $"camp seen at {pos.X:0},{pos.Y:0} ({text})", num, (storyChapter == 0) ? "unknown" : storyChapter.ToString()));
		ApplyStoryChapter(storyChapter != 0);
		if (num == 4 && Gangs.Era < 1907 && SeatOf(Gangs.SaintDenisMob)?.Fallen == null)
		{
			ShowNotification("enRAGE: Settings, Your story (O in the menu) is where you tell the mod what's become of the outfits' leaders in your story.");
			GrudgeLog("STORY chapter 4: told you where the setup card's Your story rows are (Angelo Bronte)");
		}
		List<(string, int, int)> list2 = (from k in ChapterRegard.Keys
			select (k: k, a: regBefore[k], b: RegardOf(k)) into t
			where t.a != t.b
			select t).ToList();
		if (list2.Count > 0)
		{
			GrudgeLog($"REGARD the story moved them (chapter {RegardChapter}): " + string.Join(", ", list2.Select(((string k, int a, int b) t) => $"{Nm(t.k)} {t.a} -> {t.b}")));
			IEnumerable<string> values = list2.OrderByDescending(((string k, int a, int b) t) => Math.Abs(t.b - t.a)).Take(3).Select(((string k, int a, int b) t) => $"{Nm(t.k)} {t.a} to {t.b}");
			Feed("REGARD the camp's feelings moved with the story: " + string.Join(", ", values) + ((list2.Count > 3) ? $" (+{list2.Count - 3} more)" : ""), Theme.Dim);
		}
		string Nm(string k)
		{
			return StoryRoster.FirstOrDefault((NemesisRecord r) => r.Id == "vdl_" + k)?.Name ?? k;
		}
	}

	internal void ApplyStoryChapter(bool announce)
	{
		int storyChapter = Chronicle.StoryChapter;
		if (storyChapter <= 0)
		{
			return;
		}
		int year = GameYear();
		int month = GameMonth();
		List<string> list = new List<string>();
		(string, int, bool, string)[] storyFates = StoryFates;
		for (int i = 0; i < storyFates.Length; i++)
		{
			(string key, int ch, bool dead, string how) f = storyFates[i];
			NemesisRecord nemesisRecord = StoryRoster.FirstOrDefault((NemesisRecord x) => x.Id == "vdl_" + f.key);
			if (nemesisRecord == null)
			{
				continue;
			}
			bool flag = storyChapter >= f.ch && (!f.dead || !_storySeenAlive.Contains(f.key) || storyChapter >= 7);
			if (flag && nemesisRecord.IsAlive)
			{
				nemesisRecord.IsAlive = false;
				ref string storyGone = ref nemesisRecord.StoryGone;
				string text;
				if (f.dead)
				{
					text = null;
				}
				else
				{
					text = (f.how.StartsWith("Left") ? "Left the gang" : "Gone");
				}
				storyGone = text;
				nemesisRecord.Past = nemesisRecord.Past ?? new List<PastEntry>();
				if (!nemesisRecord.Past.Any((PastEntry e) => e.Kind == "fate"))
				{
					nemesisRecord.Past.Add(new PastEntry
					{
						Year = year,
						Month = month,
						Kind = "fate",
						Text = f.how,
						Public = true,
						Known = true
					});
				}
				list.Add(f.dead ? (nemesisRecord.Name + " is dead") : (nemesisRecord.Name + ": " + f.how.ToLowerInvariant()));
			}
			else if (!flag && !nemesisRecord.IsAlive && nemesisRecord.Past != null && nemesisRecord.Past.Any((PastEntry e) => e.Kind == "fate"))
			{
				nemesisRecord.IsAlive = true;
				nemesisRecord.StoryGone = null;
				nemesisRecord.Past.RemoveAll((PastEntry e) => e.Kind == "fate");
			}
		}
		if (storyChapter >= 7 && SeatOf(Gangs.ODriscolls)?.Fallen == null)
		{
			Seats[Gangs.ODriscolls.Id] = new LeaderSeat
			{
				Fallen = "hanged by the law",
				OldName = (Gangs.ODriscolls.LoreLeader ?? "Colm O'Driscoll"),
				At = GameMinutesNow()
			};
			ApplyLeaders();
			list.Add("Colm O'Driscoll was hanged");
		}
		if (storyChapter >= 5 && SeatOf(Gangs.SaintDenisMob)?.Fallen == null)
		{
			Seats[Gangs.SaintDenisMob.Id] = new LeaderSeat
			{
				Fallen = "fed to an alligator by Dutch van der Linde",
				OldName = (Gangs.SaintDenisMob.LoreLeader ?? "Angelo Bronte"),
				At = GameMinutesNow()
			};
			ApplyLeaders();
			list.Add("Angelo Bronte is dead - Dutch fed him to an alligator");
		}
		if (list.Count == 0)
		{
			return;
		}
		GrudgeLog(string.Format("STORY chapter {0} ({1}): {2}", storyChapter, ChapterNames[Math.Min(storyChapter, 7)], string.Join("; ", list)));
		if (announce)
		{
			if (Config.WorldEvents)
			{
				WorldEvent worldEvent = NewEvent("VDL", GameMinutesNow());
				worldEvent.Gangs.Add("vdl");
				worldEvent.Heard = true;
				worldEvent.Title = storyChapter switch
				{
					7 => "The Van der Linde gang is finished", 
					5 => "The gang washed up on Guarma", 
					_ => "The gang made camp at " + ChapterNames[storyChapter], 
				};
				worldEvent.Place = ((storyChapter == 7) ? "years later" : ("at " + ChapterNames[Math.Min(storyChapter, 7)]));
				worldEvent.Lines.AddRange(list);
				Chronicle.Events.Add(worldEvent);
			}
			Feed("STORY " + ChapterNames[Math.Min(storyChapter, 7)] + ": " + string.Join("; ", list), Theme.Gold);
			SaveWorld();
		}
	}

	internal string StoryCompanionBlock(string key)
	{
		int storyChapter = Chronicle.StoryChapter;
		if (storyChapter == 5)
		{
			return "Guarma";
		}
		if (storyChapter >= 7)
		{
			return "the epilogue";
		}
		NemesisRecord nemesisRecord = StoryRoster.FirstOrDefault((NemesisRecord x) => x.Id == "vdl_" + key);
		if (nemesisRecord == null || nemesisRecord.IsAlive)
		{
			return null;
		}
		return "the story has taken him";
	}

	internal string StoryDebugLine()
	{
		return "story: chapter " + ((Chronicle.StoryChapter == 0) ? "unknown (visit the gang's camp)" : $"{Chronicle.StoryChapter} - {ChapterNames[Math.Min(Chronicle.StoryChapter, 7)]}") + $"  -  {Enumerable.Count(StoryRoster, (NemesisRecord r) => r.Story && r.IsAlive)} of the gang alive, {_storySeenAlive.Count} seen in camp";
	}

	private static int GameDayKey()
	{
		return GameDate.TodayKey();
	}

	private void UpdateSuccession()
	{
		if (!Config.Succession || Game.GameTime < _nextSuccessionCheck)
		{
			return;
		}
		_nextSuccessionCheck = Game.GameTime + 2000;
		long num = GameMinutesNow();
		if (_lastClockStamp >= 0 && num - _lastClockStamp > 120 && Game.GameTime - _lastJumpAt > 30000)
		{
			_lastSleepAt = num;
		}
		_lastClockStamp = num;
		int num2 = GameDayKey();
		if (Config.LastDecayDay != 0 && num2 != Config.LastDecayDay && DayOf(num2) < DayOf(Config.LastDecayDay))
		{
			Config.LastDecayDay = num2;
			Config.Save();
		}
		else if (Config.LastDecayDay != num2 && CLOCK.GET_CLOCK_HOURS() >= Config.SuccessionHour)
		{
			bool flag = Config.LastDecayDay == 0;
			int num3 = ((!flag) ? Math.Max(1, Math.Min(30, (int)(DayOf(num2) - DayOf(Config.LastDecayDay)).TotalDays)) : 0);
			Config.LastDecayDayBefore = Config.LastDecayDay;
			Config.LastDecayDay = num2;
			if (!flag)
			{
				try
				{
					DriftControl(num3);
				}
				catch (Exception ex)
				{
					GrudgeLog("CONTROL drift failed: " + ex.Message);
				}
			}
			if (!flag && Balance.NotorietyDecayPerDay > 0)
			{
				Gang[] all = Gangs.All;
				foreach (Gang gang in all)
				{
					int num4 = NotorietyOf(gang);
					if (num4 > 0)
					{
						int num5 = num3;
						if (Chronicle.NotorietyGainDay != null && Chronicle.NotorietyGainDay.TryGetValue(gang.Id, out var value) && Config.LastDecayDayBefore != 0 && DayOf(value) >= DayOf(Config.LastDecayDayBefore))
						{
							num5 = Math.Max(0, num3 - 1);
						}
						int num6 = num3 - num5;
						int num7 = Balance.NotorietyDecayPerDay * num5 + ((num6 > 0) ? (Math.Max(1, Balance.NotorietyDecayPerDay / 2) * num6) : 0);
						if (num7 <= 0)
						{
							GrudgeLog($"NOTORIETY {gang.Id} {num4} holds");
							continue;
						}
						Config.Notoriety[gang.Id] = Math.Max(0, num4 - num7);
						GrudgeLog($"NOTORIETY {gang.Id} {num4} -> {Config.Notoriety[gang.Id]} (a day passes)");
					}
				}
			}
			Config.Save();
		}
		Dictionary<string, int> dictionary = Chronicle.NextShakeUp ?? (Chronicle.NextShakeUp = new Dictionary<string, int>());
		Dictionary<string, int> dictionary3 = Chronicle.ShakeUpHour ?? (Chronicle.ShakeUpHour = new Dictionary<string, int>());
		int cLOCK_HOURS = CLOCK.GET_CLOCK_HOURS();
		List<(Gang, DateTime)> list = new List<(Gang, DateTime)>();
		foreach (Gang item2 in Gangs.All.Where((Gang gang2) => gang2.Seed != null && gang2.Tiers != null))
		{
			if (!dictionary.TryGetValue(item2.Id, out var value2) || value2 == 0)
			{
				ScheduleShakeUp(item2, num2, first: true);
				continue;
			}
			try
			{
				if ((DayOf(value2) - DayOf(num2)).TotalDays > (double)(Config.SuccessionMaxDays + 1))
				{
					ScheduleShakeUp(item2, num2, first: true);
					continue;
				}
				if (!dictionary3.ContainsKey(item2.Id))
				{
					dictionary3[item2.Id] = _rng.Next(24);
					SaveWorld();
				}
				int num8 = dictionary3[item2.Id];
				if (DayOf(num2) > DayOf(value2) || (DayOf(num2) == DayOf(value2) && cLOCK_HOURS >= num8))
				{
					list.Add((item2, DayOf(value2).AddHours(num8)));
				}
			}
			catch
			{
				ScheduleShakeUp(item2, num2, first: true);
			}
		}
		if (Game.GameTime >= _nextHollowCheck)
		{
			_nextHollowCheck = Game.GameTime + 30000;
			Gang[] all = Gangs.All;
			foreach (Gang g in all)
			{
				PullShakeUpIn(g, num2);
			}
		}
		Config.NextSuccessionDay = ((dictionary.Count > 0) ? dictionary.Values.OrderBy((int v) =>
		{
			try
			{
				return DayOf(v);
			}
			catch
			{
				return DateTime.MaxValue;
			}
		}).First() : 0);
		if (list.Count != 0 && Game.GameTime >= _nextShakeUpRun && !_menu.IsOpen && !_bulletImpact.ViewerOpen && !(_activeNemesisPed != null) && PLAYER.IS_PLAYER_CONTROL_ON(Game.Player.Handle))
		{
			Gang item = list.OrderBy(((Gang g, DateTime when) x) => x.when).First().Item1;
			Config.LastSuccessionDay = num2;
			ScheduleShakeUp(item, num2, first: false);
			_nextShakeUpRun = Game.GameTime + ((list.Count > 2) ? (15000 + _rng.Next(15000)) : (60000 + _rng.Next(120000)));
			GrudgeLog("SUCCESSION shake-up now for the " + item.Name + ((list.Count > 1) ? $" ({list.Count - 1} more due - one at a time)" : ""));
			RunSuccession(GameMinutesNow() - _lastSleepAt < 720, new List<Gang> { item });
			PullShakeUpIn(item, num2);
		}
	}

	private void ScheduleShakeUp(Gang g, int fromDay, bool first)
	{
		Dictionary<string, int> dictionary = Chronicle.NextShakeUp ?? (Chronicle.NextShakeUp = new Dictionary<string, int>());
		Dictionary<string, int> dictionary3 = Chronicle.ShakeUpHour ?? (Chronicle.ShakeUpHour = new Dictionary<string, int>());
		int num = 0;
		int key = fromDay;
		for (int i = 0; i < 4; i++)
		{
			num = (first ? _rng.Next(1, Config.SuccessionMaxDays + 1) : _rng.Next(Config.SuccessionMinDays, Config.SuccessionMaxDays + 1));
			try
			{
				key = GameDate.DayKey(DayOf(fromDay).AddDays(num));
			}
			catch
			{
				key = fromDay;
				break;
			}
			if (!dictionary.Any((KeyValuePair<string, int> kv) => kv.Key != g.Id && kv.Value == key))
			{
				break;
			}
		}
		dictionary[g.Id] = key;
		dictionary3[g.Id] = _rng.Next(24);
		SaveWorld();
		GrudgeLog($"SUCCESSION {g.Id}: next shake-up in {num} days ({dictionary[g.Id]}) at {dictionary3[g.Id]:00}:00");
	}

	internal double UpperShare(Gang g)
	{
		if (g?.Tiers == null || g.Tiers.Length < 2)
		{
			return 1.0;
		}
		int num = 0;
		for (int i = 0; i < g.Tiers.Length - 1; i++)
		{
			num += g.Tiers[i].Seats;
		}
		if (num <= 0)
		{
			return 1.0;
		}
		int lowest = g.Tiers[g.Tiers.Length - 2].MinRank;
		string succ = SuccessorId(g);
		int num2 = Enumerable.Count(Roster, (NemesisRecord n) => n.Gang == g.Id && n.IsAlive && !n.PresumedDead && n.Id != succ && n.Rank >= lowest);
		return Math.Min(1.0, (double)num2 / (double)num);
	}

	private bool ReadyToRise(NemesisRecord n)
	{
		if (n.RankXp < 2 * n.Rank)
		{
			return Standing(n).score >= 70;
		}
		return true;
	}

	private void PullShakeUpIn(Gang g, int today)
	{
		if (g == null || g.OrdersNotFeelings || g.Tiers == null || g.Seed == null || IsDestroyed(g))
		{
			return;
		}
		Dictionary<string, int> nextShakeUp = Chronicle.NextShakeUp;
		if (nextShakeUp == null || !nextShakeUp.TryGetValue(g.Id, out var value) || value == 0)
		{
			return;
		}
		double num = UpperShare(g);
		int num2 = ((num < 0.5) ? 1 : ((num < 0.75) ? 2 : int.MaxValue));
		if (num2 == int.MaxValue)
		{
			return;
		}
		try
		{
			DateTime dateTime = DayOf(today).AddDays(num2);
			if (!(DayOf(value) <= dateTime))
			{
				nextShakeUp[g.Id] = GameDate.DayKey(dateTime);
				SaveWorld();
				GrudgeLog(string.Format("SUCCESSION {0}: officer seats {1:0}% filled - the next shake-up comes sooner, within {2} day{3} ({4})", g.Id, num * 100.0, num2, (num2 == 1) ? "" : "s", nextShakeUp[g.Id]));
			}
		}
		catch
		{
		}
	}

	internal int ShakeUpDayOf(Gang g)
	{
		if (g == null || Chronicle.NextShakeUp == null || !Chronicle.NextShakeUp.TryGetValue(g.Id, out var value))
		{
			return Config.NextSuccessionDay;
		}
		return value;
	}

	private void ScheduleNextSuccession(int fromDay)
	{
		int num = _rng.Next(Config.SuccessionMinDays, Config.SuccessionMaxDays + 1);
		try
		{
			DateTime d = DayOf(fromDay).AddDays(num);
			Config.NextSuccessionDay = GameDate.DayKey(d);
		}
		catch
		{
			Config.NextSuccessionDay = fromDay;
		}
		Config.Save();
		GrudgeLog($"SUCCESSION next shake-up in {num} days ({Config.NextSuccessionDay})");
	}

	internal (int score, string why) Standing(NemesisRecord n)
	{
		int num = n.Hate + 30 * n.TimesKilledPlayer + 20 * n.TimesCheatedDeath + 12 * n.Scars.Count + 8 * n.TimesAmbushed + 6 * n.Rank + ((n.Origin != GrudgeOrigin.GangMember) ? 10 : 0) + n.Aggression / 10 - EffectiveFear(n) / 4 + Mind.StandingBonus(n).bonus;
		switch (n.Personality)
		{
		case Personality.Proud:
			num += 15;
			break;
		case Personality.Hothead:
			num += 10;
			break;
		case Personality.Loyal:
			num += 8;
			break;
		case Personality.Cold:
			num += 5;
			break;
		case Personality.Coward:
			num -= 20;
			break;
		}
		string item;
		if (n.TimesKilledPlayer > 0)
		{
			item = "killed you " + ((n.TimesKilledPlayer == 1) ? "once" : (n.TimesKilledPlayer + "x"));
		}
		else if (n.TimesCheatedDeath > 0)
		{
			item = "came back from the dead";
		}
		else if (n.ScarredByYou)
		{
			item = "carries your scar";
		}
		else if (n.Scars.Count > 0)
		{
			item = "a scarred veteran";
		}
		else if (n.TimesAmbushed > 0)
		{
			item = $"has come for you {n.TimesAmbushed}x";
		}
		else if (n.Origin != GrudgeOrigin.GangMember)
		{
			item = "has a score to settle";
		}
		else
		{
			item = ((n.Personality == Personality.Proud || n.Personality == Personality.Hothead) ? "ambitious" : "next in line");
		}
		return (score: num, why: item);
	}

	private void RunSuccession(bool slept, List<Gang> due)
	{
		try
		{
			TrimGangRosters();
		}
		catch (Exception ex)
		{
			GrudgeLog("ERROR shake-up roster trim: " + ex);
		}
		if (due.Any((Gang gang2) => gang2.Id == Gangs.LemoyneRaiders.Id))
		{
			RaiderInfighting();
		}
		List<(string, (int, int, int))> list = new List<(string, (int, int, int))>();
		int num = 0;
		foreach (Gang item4 in due)
		{
			Gang gang = item4;
			string succ = SuccessorId(gang);
			List<NemesisRecord> living = Roster.Where((NemesisRecord n) => n.Gang == gang.Id && n.IsAlive && !n.PresumedDead && n.Id != succ).ToList();
			if (living.Count == 0 && !Roster.Any((NemesisRecord n) => n.Gang == gang.Id))
			{
				continue;
			}
			List<(string, (int, int, int))> list2 = new List<(string, (int, int, int))>();
			(string, NemesisRecord)? tuple = FillLeaderSeat(gang, living);
			if (tuple.HasValue)
			{
				living.Remove(tuple.Value.Item2);
				list2.Add((tuple.Value.Item1, Theme.Gold));
				num++;
			}
			List<(NemesisRecord, string)> list3 = new List<(NemesisRecord, string)>();
			List<WorldPart> list4 = new List<WorldPart>();
			int num2 = HireBudget(gang);
			int num3 = 0;
			int num4 = 0;
			if (HasPurse(gang) && !gang.OrdersNotFeelings)
			{
				GrudgeLog($"SUCCESSION {gang.Id}: purse ${PurseOf(gang)} - ${num2} to spend on new men");
			}
			double num5 = UpperShare(gang);
			int num6 = 0;
			for (int num7 = 0; num7 < gang.Tiers.Length; num7++)
			{
				(string Label, int MinRank, int Seats) tuple2 = gang.Tiers[num7];
				int item = tuple2.MinRank;
				int item2 = tuple2.Seats;
				int count = In(num7).Count;
				int num8 = item2 - count;
				bool flag = !gang.OrdersNotFeelings && num7 < gang.Tiers.Length - 1;
				int num9 = num8;
				if (flag && num8 > 0)
				{
					num9 = Math.Max(0, (int)Math.Round((double)item2 * (0.7 + _rng.NextDouble() * 0.2)) - count);
				}
				for (int num10 = 0; num10 < num8; num10++)
				{
					NemesisRecord up = null;
					if (num7 + 1 < gang.Tiers.Length)
					{
						up = (from n in In(num7 + 1)
							where !n.Paralyzed
							orderby Standing(n).score descending, n.Id
							select n).FirstOrDefault();
					}
					if (flag && num10 >= num9 && (up == null || !ReadyToRise(up)))
					{
						int num11 = num8 - num10;
						GrudgeLog(string.Format("SUCCESSION {0} {1} {2} seat(s) left open - nobody ready{3}", gang.Id, num11, Seat(num7), (up != null) ? $" (best: {up.Name}, xp {up.RankXp}/{2 * up.Rank}, standing {Standing(up).score})" : ""));
						list2.Add((string.Format("{0} {1} seat{2} left open - nobody ready yet", num11, (num11 == 1) ? Seat(num7) : gang.Tiers[num7].Label.ToLowerInvariant(), (num11 == 1) ? "" : "s"), Theme.Dim));
						break;
					}
					if (up != null && item >= 2)
					{
						num6++;
					}
					if (up != null)
					{
						string item3 = Standing(up).why;
						int rank = up.Rank;
						up.Rank = item;
						up.BossId = null;
						if (item >= 2)
						{
							int hate = up.Hate;
							up.Hate = Math.Min(100, up.Hate + (int)Math.Round(10f * Tempers.Of(up.Personality).HateGain));
							int num12 = (gang.SeedHate.HasValue ? gang.SeedHate.Value.max : Hate.VengefulAt);
							if (up.Hate < num12)
							{
								up.Hate = num12 + _rng.Next(4);
							}
							if (up.Hate != hate)
							{
								GrudgeLog($"SUCCESSION {up.Name}: hate {hate} -> {up.Hate} with the promotion ({up.Personality})");
							}
						}
						if (up == ActiveRecord && _activeNemesisPed != null)
						{
							ApplyRankStats(_activeNemesisPed, up, fullHeal: false);
						}
						list2.Add((up.Name + " rises to " + Seat(num7) + "  -  " + item3, Theme.Text));
						WorldPart worldPart = PartFor(up, "PROMOTED", item3);
						worldPart.Effects.Add($"rank {rank} -> {up.Rank}");
						worldPart.Effects.Add(Seat(num7));
						list4.Add(worldPart);
						History(up, "ROSE TO " + Seat(num7).ToUpperInvariant() + " in the " + gang.Name + " (" + item3 + ")", gang.Accent);
						Remember(up, "Pride", Mind.Has(up, "Rise") ? 70 : 45, "made " + Seat(num7), null);
						if (Mind.Has(up, "Rise") && num7 == 0)
						{
							up.Goals.RemoveAll((Goal goal) => goal.Type == "Rise");
						}
						foreach (NemesisRecord item5 in (from o in In(num7 + 1)
							where o != up && o.IsAlive && Mind.Has(o, "Rise")
							select o).Take(2))
						{
							Mind.SetTie(item5, up.Id, "rival", Math.Min(Mind.TieTo(item5, up.Id)?.Strength ?? 0, 0) - 35, "made " + Seat(num7) + " over him");
							Remember(item5, "Shame", 40, "passed over - " + up.Name + " made " + Seat(num7), up.Id);
						}
						GrudgeLog($"SUCCESSION {gang.Id} {up.Name} rank {rank} -> {up.Rank} ({Seat(num7)}) score={Standing(up).score} {item3}");
						num++;
					}
					else
					{
						if (IsDestroyed(gang))
						{
							continue;
						}
						if (_rng.NextDouble() > RecruitChance(gang))
						{
							GrudgeLog($"SUCCESSION {gang.Id} {Seat(num7)} seat stays empty - recruits {RecruitChance(gang) * 100.0:0}% (ground {TerritoryShare(gang) * 100.0:0}%)");
							continue;
						}
						bool flag2 = num7 == gang.Tiers.Length - 1;
						int num13 = RecruitCost((!flag2) ? 1 : 0);
						bool flag3 = HasPurse(gang) && (PurseOf(gang) < num13 || num3 + num13 > num2);
						if (flag2 && !gang.OrdersNotFeelings && (flag3 || MenShare(gang) < 0.75))
						{
							NemesisRecord nemesisRecord = LocalRecruit(gang, num7);
							if (nemesisRecord != null)
							{
								int num14 = (HasPurse(gang) ? Math.Min(10, Math.Max(0, PurseOf(gang) - 60)) : 0);
								if (num14 > 0)
								{
									AddPurse(gang, -num14, "a local man as " + Seat(num7));
									num3 += num14;
								}
								living.Add(nemesisRecord);
								WorldPart worldPart2 = PartFor(nemesisRecord, "JOINED", "a local man");
								worldPart2.Effects.Add(Seat(num7));
								list4.Add(worldPart2);
								list2.Add((nemesisRecord.Name + " joins as " + Seat(num7) + "  -  a local man", Theme.Text));
								GrudgeLog(string.Format("SUCCESSION {0} local {1} takes the {2} seat (${3}; {4})", gang.Id, nemesisRecord.Name, Seat(num7), num14, flag3 ? "no money for a new man" : $"men {MenOf(gang)} of {MenStart(gang)}"));
								num++;
								continue;
							}
						}
						if (HasPurse(gang))
						{
							int num15 = num13;
							if (PurseOf(gang) < num15 || num3 + num15 > num2)
							{
								num4++;
								if (num4 == 1)
								{
									GrudgeLog($"SUCCESSION {gang.Id} {Seat(num7)} seat stays empty - can't pay a new man (spent ${num3} of ${num2}, purse ${PurseOf(gang)}) - and any more seats this shake-up");
								}
								continue;
							}
							num3 += num15;
							AddPurse(gang, -num15, "a new man as " + Seat(num7));
						}
						var (nemesisRecord2, text) = Recruit(gang, num7);
						living.Add(nemesisRecord2);
						list3.Add((nemesisRecord2, Seat(num7)));
						WorldPart worldPart3 = PartFor(nemesisRecord2, "JOINED", text ?? "a new man");
						worldPart3.Effects.Add(Seat(num7));
						list4.Add(worldPart3);
						if (text != null)
						{
							list2.Add((nemesisRecord2.Name + " joins as " + Seat(num7) + "  -  " + text, Theme.Warn));
						}
						GrudgeLog(string.Format("SUCCESSION {0} recruit {1} as {2} rank {3} hate {4}{5}", gang.Id, nemesisRecord2.Name, Seat(num7), nemesisRecord2.Rank, nemesisRecord2.Hate, (text != null) ? (" - " + text) : ""));
						num++;
					}
				}
			}
			num += PromoteWithinTiers(gang, living, list2, list4);
			if (Enumerable.Count(list3, ((NemesisRecord rec, string label) r) => r.rec.KinId == null) > 0)
			{
				IEnumerable<string> values = list3.Where(((NemesisRecord rec, string label) r) => r.rec.KinId == null).GroupBy(((NemesisRecord rec, string label) r) => r.label).Select((IGrouping<string, (NemesisRecord rec, string label)> grouping) => $"{grouping.Count()} new {((grouping.Count() == 1) ? grouping.Key : gang.Tiers.First(((string Label, int MinRank, int Seats) x) => Singular(x.Label) == grouping.Key).Label.ToLowerInvariant())}");
				list2.Add((string.Join(", ", values) + " brought in", Theme.Dim));
			}
			if (num4 > 0)
			{
				list2.Add((string.Format("No money for more men - {0} seat{1} left empty", num4, (num4 == 1) ? "" : "s"), Theme.Warn));
			}
			if (list2.Count != 0)
			{
				ChronicleRanks(gang, list4, (num5 < 0.5 && num6 >= 2) ? $"The {gang.Name} rebuild their ranks - {num6} new officers" : null);
				list.Add((gang.Name.ToUpperInvariant(), gang.Accent));
				list.AddRange(list2);
				Feed($"SUCCESSION {gang.Name}: {list2.Count} change(s)", gang.Accent);
			}
			List<NemesisRecord> In(int t)
			{
				return living.Where((NemesisRecord n) => n.Rank >= gang.Tiers[t].MinRank && n.Rank <= MaxOf(t)).ToList();
			}
			int MaxOf(int t)
			{
				if (t != 0)
				{
					return gang.Tiers[t - 1].MinRank - 1;
				}
				return 5;
			}
			string Seat(int t)
			{
				return Singular(gang.Tiers[t].Label);
			}
		}
		Gang[] all = Gangs.All;
		foreach (Gang g in all)
		{
			try
			{
				CheckCollapse(g);
			}
			catch (Exception ex2)
			{
				GrudgeLog("SANDBOX collapse check failed: " + ex2.Message);
			}
		}
		if (num != 0)
		{
			SaveRoster();
			AssignCamps();
			_successionTitle = (slept ? "WHILE YOU SLEPT" : "WORD ON THE TRAIL");
			_successionCard = list;
			_successionShownMs = -1;
		}
	}

	private NemesisRecord LocalRecruit(Gang gang, int tier)
	{
		List<NemesisRecord> source = Roster.Where((NemesisRecord n) => n.Gang == null && n.IsAlive && !n.PresumedDead && !n.Story && n.Id != null && n != ActiveRecord && !_worldNemeses.ContainsValue(n) && !IsArmy(n) && n.Affiliation != "army").ToList();
		NemesisRecord nemesisRecord = (from _ in source
			where _.Affiliation == gang.Id
			orderby _rng.Next()
			select _).FirstOrDefault() ?? (from n in source.Where(OnTheirGround)
			orderby n.Hate descending
			select n).ThenBy((NemesisRecord _) => _rng.Next()).FirstOrDefault();
		if (nemesisRecord == null)
		{
			return null;
		}
		nemesisRecord.Gang = gang.Id;
		nemesisRecord.Rank = gang.Tiers[tier].MinRank;
		nemesisRecord.BossId = null;
		nemesisRecord.CampId = null;
		nemesisRecord.CampKnown = false;
		if (nemesisRecord.Affiliation == gang.Id)
		{
			nemesisRecord.Affiliation = null;
		}
		History(nemesisRecord, "JOINED the " + gang.Name + " as " + Singular(gang.Tiers[tier].Label) + " - a local who threw in with them", gang.Accent);
		SaveRoster();
		return nemesisRecord;
		bool OnTheirGround(NemesisRecord n)
		{
			string killLocation = n.KillLocation;
			if (killLocation == null || !TownCore(killLocation, out var centre, out var _))
			{
				return false;
			}
			District district = DistrictAt(centre);
			if (district != null)
			{
				return HoldOf(district, gang.Id) >= 10;
			}
			return false;
		}
	}

	private (NemesisRecord rec, string note) Recruit(Gang gang, int tier)
	{
		(string, int, int) tuple = gang.Tiers[tier];
		int minRank = tuple.Item2;
		(int, int, PedHash[]) tuple2 = (from s in gang.Seed
			where s.Rank >= minRank
			orderby s.Rank
			select s).FirstOrDefault();
		if (tuple2.Item3 == null)
		{
			tuple2 = gang.Seed.Last();
		}
		PedHash[] item = tuple2.Item3;
		NemesisRecord nemesisRecord = NewRecord((uint)item[_rng.Next(item.Length)], "", gang, minRank);
		nemesisRecord.Gang = gang.Id;
		nemesisRecord.Rank = minRank;
		nemesisRecord.Origin = GrudgeOrigin.GangMember;
		nemesisRecord.SeedMember = true;
		nemesisRecord.TimesKilledPlayer = 0;
		nemesisRecord.KilledPlayerAt = DateTime.Now;
		NemesisRecord nemesisRecord2 = nemesisRecord;
		int hate;
		if (gang.SeedHate.HasValue)
		{
			hate = gang.SeedHate.Value.min + _rng.Next(Math.Max(1, gang.SeedHate.Value.max - gang.SeedHate.Value.min + 1));
		}
		else
		{
			hate = ((minRank >= 2) ? (Hate.MurderousAt + _rng.Next(10)) : SeedFootSoldierHate(gang, nemesisRecord));
		}
		nemesisRecord2.Hate = hate;
		nemesisRecord.AddHate(NotorietyOf(gang) / 5);
		GiveHomeTown(nemesisRecord, gang);
		string text = null;
		List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.Gang == gang.Id && !n.IsAlive && n.KilledByPlayer && n.Name != null && n.Name.Contains(' ') && !n.Id.StartsWith("fallen_") && !Roster.Any((NemesisRecord k) => k.IsAlive && k.KinId == n.Id)).ToList();
		if (list.Count > 0 && _rng.Next(100) < Config.SuccessionKinChance)
		{
			NemesisRecord nemesisRecord3 = list[_rng.Next(list.Count)];
			string last = FamilyNameOf(nemesisRecord3);
			string first = nemesisRecord.Name.Split(' ')[0];
			nemesisRecord.KinId = nemesisRecord3.Id;
			nemesisRecord.KinRelation = Traits.RollKin(_rng);
			if (gang.FamilyNames && Traits.SharesSurname(nemesisRecord.KinRelation, _rng) && !Roster.Any((NemesisRecord n) => n.Name == first + " " + last))
			{
				nemesisRecord.Name = first + " " + last;
			}
			if (Backstory.FitKinAge(nemesisRecord, nemesisRecord3, Seeds.For(nemesisRecord, "kin"), GameYear()))
			{
				Backstory.Roll(nemesisRecord, Seeds.For(nemesisRecord, "life"), GameYear(), GameMonth(), derive: false);
				GrudgeLog($"HISTORY recruit {nemesisRecord.Name}: {nemesisRecord.KinRelation} of the late {nemesisRecord3.Name} - born {nemesisRecord.BornYear} (his {nemesisRecord3.BornYear}), life rewritten");
			}
			nemesisRecord.AddHate(15);
			text = nemesisRecord.KinRelation + " of the late " + nemesisRecord3.Name;
		}
		History(nemesisRecord, "JOINED the " + gang.Name + " as " + Singular(gang.Tiers[tier].Label) + ((text != null) ? (" - " + text + ", come to settle it") : ""), gang.Accent);
		StartRest(nemesisRecord);
		Roster.Add(nemesisRecord);
		return (rec: nemesisRecord, note: text);
	}

	private static string Singular(string label)
	{
		string text = ((label.Length > 1 && label.EndsWith("S")) ? label.Substring(0, label.Length - 1) : label);
		if (text.Length != 0)
		{
			return text[0] + text.Substring(1).ToLowerInvariant();
		}
		return text;
	}

	private void DrawSuccessionCard()
	{
		if (_successionCard != null && !Config.GrudgeMessages)
		{
			_successionCard = null;
		}
		else
		{
			if (_successionCard == null || _menu.IsOpen || _bulletImpact.ViewerOpen)
			{
				return;
			}
			if (_successionShownMs < 0)
			{
				_successionShownMs = UiDraw.RealMs;
			}
			int num = UiDraw.RealMs - _successionShownMs;
			if (num > 14000)
			{
				_successionCard = null;
				return;
			}
			int num2;
			if (num < 800)
			{
				num2 = 255 * num / 800;
			}
			else
			{
				num2 = ((num > 13200) ? (255 * (14000 - num) / 800) : 255);
			}
			int num3 = Math.Min(_successionCard.Count, 16);
			float h = 0.06f + (float)num3 * 0.024f + 0.012f;
			Theme.Brush(0.665f, 0.3f, 0.315f, h, num2);
			UiDraw.Rect(0.665f, 0.3f, 0.315f, 0.0027777776f, Theme.Gold.r, Theme.Gold.g, Theme.Gold.b, num2);
			UiDraw.TextFont(_successionTitle, UiDraw.TitleFont, 0.67700005f, 0.31f, 0.42f, Theme.Title.r, Theme.Title.g, Theme.Title.b, num2);
			UiDraw.Text("The ranks have shifted.", 0.67700005f, 0.338f, 0.24f, Theme.Dim.r, Theme.Dim.g, Theme.Dim.b, num2);
			float num4 = 0.36200002f;
			for (int i = 0; i < num3; i++)
			{
				var (text, tuple2) = _successionCard[i];
				if (Gangs.All.Any((Gang g) => g.Name.ToUpperInvariant() == text))
				{
					UiDraw.Rect(0.67700005f, num4 + 0.005f, 0.0015625001f, 0.013f, tuple2.Item1, tuple2.Item2, tuple2.Item3, num2);
					UiDraw.TextFont(text, UiDraw.TitleFont, 0.684f, num4 + 0.001f, 0.26f, tuple2.Item1, tuple2.Item2, tuple2.Item3, num2);
				}
				else
				{
					UiDraw.Text((text.Length > 52) ? (text.Substring(0, 51) + ".") : text, 0.684f, num4 + 0.002f, 0.25f, tuple2.Item1, tuple2.Item2, tuple2.Item3, num2);
				}
				num4 += 0.024f;
			}
		}
	}

	internal static string OutfitPoss(Gang g)
	{
		if (g != null)
		{
			if (!g.Name.EndsWith("s"))
			{
				return g.Name + "'s";
			}
			return g.Name + "'";
		}
		return "";
	}

	internal int SuppliesOf(Gang g)
	{
		if (g == null || g.StoryOnly)
		{
			return 100;
		}
		if (!SupplyMap.TryGetValue(g.Id, out var value))
		{
			if (!g.OrdersNotFeelings)
			{
				return 70;
			}
			return 80;
		}
		return value;
	}

	internal void AddSupplies(Gang g, int delta, string why)
	{
		if (g != null && !g.StoryOnly && delta != 0)
		{
			int num = SuppliesOf(g);
			int num2 = Math.Max(0, Math.Min(100, num + delta));
			if (num2 != num)
			{
				SupplyMap[g.Id] = num2;
				GrudgeLog($"SUPPLIES {g.Name}: {num} -> {num2} ({why})");
				SaveWorld();
			}
		}
	}

	private void AddSuppliesFrac(Gang g, double delta, string why)
	{
		if (g != null && !g.StoryOnly)
		{
			_supplyFrac.TryGetValue(g.Id, out var value);
			value += delta;
			int num = (int)Math.Truncate(value);
			_supplyFrac[g.Id] = value - (double)num;
			if (num != 0)
			{
				AddSupplies(g, num, why);
			}
		}
	}

	internal static string SupplyState(int v)
	{
		if (v > 0)
		{
			if (v >= 25)
			{
				if (v >= 50)
				{
					if (v >= 80)
					{
						return "Plenty";
					}
					return "Stocked";
				}
				return "Short";
			}
			return "Low";
		}
		return "Out";
	}

	internal static (int r, int g, int b) SupplyColor(int v)
	{
		if (v >= 25)
		{
			if (v >= 50)
			{
				return Theme.Good;
			}
			return Theme.Warn;
		}
		return Theme.Blood;
	}

	internal static string SupplyWord(Gang g)
	{
		return g?.Id switch
		{
			"odriscoll" => "stolen goods", 
			"lemoyneraiders" => "the cause's stores", 
			"army" => "the depot", 
			"klan" => "the lodge's stores", 
			"wapiti" => "the herd and the hunt", 
			"bronte" => "the family's warehouses", 
			"murfree" => "what they've hoarded", 
			"skinners" => "hides and powder", 
			_ => "supplies", 
		};
	}

	internal bool ShortOfArms(Gang g)
	{
		if (g != null && !g.StoryOnly)
		{
			return SuppliesOf(g) < 50;
		}
		return false;
	}

	internal bool LowSupplies(Gang g)
	{
		if (g != null && !g.StoryOnly)
		{
			return SuppliesOf(g) < 25;
		}
		return false;
	}

	private void DailySupplies(int days)
	{
		int num = Math.Min(days, 30);
		foreach (Gang item in Gangs.All.Where((Gang x) => !x.StoryOnly && !IsDestroyed(x)))
		{
			double num2 = 2.0 + 6.0 * Math.Min(1.2, TerritoryShare(item));
			if (item.OrdersNotFeelings)
			{
				num2 += 5.0;
			}
			if (item == Gangs.Wapiti)
			{
				num2 += 3.0;
			}
			double num3 = 4.0 * Math.Min(1.5, MenShare(item)) + (double)(3 * WarsOf(item));
			if (SuppliesOf(item) < 10)
			{
				num3 = Math.Min(num3, num2 - 0.5);
			}
			_supplyFrac.TryGetValue("day:" + item.Id, out var value);
			double num4 = (num2 - num3) * (double)num + value;
			int num5 = (int)Math.Truncate(num4);
			_supplyFrac["day:" + item.Id] = num4 - (double)num5;
			int num6 = 0;
			if (HasPurse(item) && !item.OrdersNotFeelings && SuppliesOf(item) + num5 < 60 && PurseOf(item) > 600)
			{
				int num7 = Math.Min(num, Math.Min(3, (PurseOf(item) - 600) / 40));
				if (num7 > 0)
				{
					AddPurse(item, -40 * num7, $"bought supplies ({num7} day(s))");
					num6 = 8 * num7;
				}
			}
			AddSupplies(item, num5 + num6, string.Format("{0} day(s): +{1:0.#}/day from its ground, -{2:0.#}/day for its men{3}{4}", num, num2, num3, (WarsOf(item) > 0) ? " and wars" : "", (num6 > 0) ? $", bought {num6}" : ""));
		}
	}

	private void SuppliesForLosses(Gang g, int men)
	{
		if (men > 0)
		{
			AddSuppliesFrac(g, -100.0 * (double)men / (double)Math.Max(1, MenStart(g)), "fighting");
		}
	}

	private Gang TopHolderHere(Ped p)
	{
		District d = DistrictAt(p.Position);
		if (d == null)
		{
			return null;
		}
		return (from g in Gangs.All
			where !g.StoryOnly && !IsDestroyed(g) && HoldOf(d, g.Id) > 0
			orderby HoldOf(d, g.Id) descending
			select g).FirstOrDefault();
	}

	private void DebugSupplies(Ped p, int by)
	{
		Gang gang = TopHolderHere(p);
		if (gang == null)
		{
			SpawnerSays("no outfit holds ground here.");
			return;
		}
		int num = SuppliesOf(gang);
		AddSupplies(gang, by, "the spawner (debug)");
		SpawnerSays($"the {OutfitPoss(gang)} supplies: {num} -> {SuppliesOf(gang)} ({SupplyState(SuppliesOf(gang))}).");
	}

	internal string SupplyLine()
	{
		return "supplies: " + string.Join(", ", from g in Gangs.All
			where !g.StoryOnly && !IsDestroyed(g)
			select $"{g.Id} {SuppliesOf(g)}");
	}

	private void UpdateSupplyCaches(Ped player)
	{
		if (Game.GameTime < _nextCacheSpawn)
		{
			return;
		}
		_nextCacheSpawn = Game.GameTime + 1000;
		if (Game.GameTime >= _nextCacheBlips)
		{
			_nextCacheBlips = Game.GameTime + 15000;
			RefreshCacheBlips();
		}
		Vector3 position = player.Position;
		foreach (LiveSupply item in _liveSupplies.Values.ToList())
		{
			if (!item.Town && item.Gang != null)
			{
				CampSite campSite = Camps.ById(item.SiteId);
				if (campSite != null && !(position.DistanceTo(SitePos(campSite)) > 60f) && (!Hold.SupplyKnownAt.TryGetValue(item.Gang.Id, out var value) || !(value == campSite.Id)))
				{
					Hold.KnowSupplies(item.Gang, campSite);
					SaveWorld();
					GrudgeLog("SUPPLY " + item.Gang.Name + ": you found their supplies - " + campSite.Label);
					RedoCampBlip(campSite.Id);
					RefreshCacheBlips();
				}
			}
		}
		foreach (string item2 in _unguardedCaches.ToList())
		{
			CampSite campSite2 = Camps.ById(item2);
			if (campSite2 == null || position.DistanceTo(SitePos(campSite2)) > 260f || !IsSupplyCamp(campSite2))
			{
				DespawnUnguardedCache(item2, "you rode off");
			}
		}
		if (SupplyCaches.Count == 0 || player.IsDead || NoSpawnReason(player, place: true) != null)
		{
			return;
		}
		foreach (string item3 in SupplyCaches.Keys.ToList())
		{
			Gang gang = Gangs.ById(item3);
			CampSite campSite3 = SupplyCampOf(gang);
			if (campSite3 == null)
			{
				continue;
			}
			float num = position.DistanceTo(SitePos(campSite3));
			if (_liveSupplies.ContainsKey(campSite3.Id))
			{
				if (num < 60f && !SupplyCacheKnown(gang))
				{
					FoundSupplyCache(gang, campSite3);
				}
			}
			else if (!_liveCamps.ContainsKey(campSite3.Id) && !(num > Config.CampSpawnRange) && !(num < 60f) && HiddenFromView(player, SitePos(campSite3) + new Vector3(0f, 0f, 1.2f)) && TownSiteReady(campSite3))
			{
				NemesisRecord nemesisRecord = ((CacheGuardsDue(gang) && !IsCleared(campSite3)) ? SupplyKeeper(gang) : null);
				if (nemesisRecord != null)
				{
					GrudgeLog($"SUPPLY {gang.Name}: their cache at {campSite3.Label} ({num:0} m) - kept by {nemesisRecord.Name}");
					SpawnCamp(campSite3, nemesisRecord, player);
					break;
				}
				if (CacheGuardsDue(gang) && !IsCleared(campSite3) && _cacheNoKeeperSaid.Add(campSite3.Id))
				{
					GrudgeLog("SUPPLY " + gang.Name + ": none of theirs free to keep the cache at " + campSite3.Label);
				}
				GrudgeLog($"SUPPLY {gang.Name}: their cache at {campSite3.Label} ({num:0} m) - unguarded");
				try
				{
					Kit.Spawn(campSite3, gang.Id, supply: true);
				}
				catch (Exception ex)
				{
					GrudgeLog("CAMPKIT failed: " + ex.Message);
				}
				_unguardedCaches.Add(campSite3.Id);
				try
				{
					SpawnSupplies(campSite3);
					break;
				}
				catch (Exception ex2)
				{
					GrudgeLog("SUPPLY cache stores failed: " + ex2.Message);
					break;
				}
			}
		}
	}

	private void DespawnUnguardedCache(string siteId, string why)
	{
		if (_unguardedCaches.Remove(siteId))
		{
			try
			{
				DespawnSupplies(siteId);
			}
			catch (Exception ex)
			{
				GrudgeLog("SUPPLY cache delete failed: " + ex.Message);
			}
			try
			{
				DespawnCampKit(siteId);
			}
			catch (Exception ex2)
			{
				GrudgeLog("CAMPKIT delete failed: " + ex2.Message);
			}
			GrudgeLog("SUPPLY cache at " + (Camps.ById(siteId)?.Label ?? siteId) + ": " + why + " - taken down");
		}
	}

	private void DespawnSupplyCaches()
	{
		foreach (string item in _unguardedCaches.ToList())
		{
			DespawnUnguardedCache(item, "cleanup");
		}
	}

	private void FoundSupplyCache(Gang g, CampSite site)
	{
		Hold.KnowSupplies(g, site);
		SaveWorld();
		RefreshCacheBlips();
		GrudgeLog("SUPPLY " + g.Name + ": you found their cache - " + site.Label);
		ReplyNotice("You've found the " + OutfitPoss(g) + " supplies. Marked on your map.");
	}

	private void RevealSupplyCache(Gang g, CampSite site, string by)
	{
		Hold.KnowSupplies(g, site);
		SaveWorld();
		RefreshCacheBlips();
		GrudgeLog("SUPPLY " + g.Name + ": you know the cache now - " + site.Label + " (from " + by + ")");
	}

	private unsafe void RefreshCacheBlips()
	{
		if (!MapSettled())
		{
			_mapPending.Add(RefreshCacheBlips);
			return;
		}
		if (_mapHidden)
		{
			CleanupCacheBlips();
			return;
		}
		Dictionary<string, string> dictionary = new Dictionary<string, string>();
		foreach (string key in SupplyCaches.Keys)
		{
			Gang g = Gangs.ById(key);
			CampSite campSite = SupplyCampOf(g);
			if (campSite != null && SupplyCacheKnown(g))
			{
				bool flag = (CacheGuardsDue(g) && !IsCleared(campSite) && SupplyKeeper(g) != null) || _liveCamps.ContainsKey(campSite.Id);
				dictionary[campSite.Id] = MemberWord(g) + " Supplies - cache" + (flag ? "" : " (unguarded)") + (SupplyRaidedRecently(g) ? " (raided)" : "");
			}
		}
		foreach (string item2 in _cacheBlips.Keys.ToList())
		{
			if (!dictionary.TryGetValue(item2, out var value) || !(value == _cacheBlips[item2].label))
			{
				int item = _cacheBlips[item2].blip;
				Crumbs.Native("supply cache blip remove");
				MAP.REMOVE_BLIP(&item);
				_cacheBlips.Remove(item2);
			}
		}
		foreach (KeyValuePair<string, string> item3 in dictionary)
		{
			if (!_cacheBlips.ContainsKey(item3.Key))
			{
				CampSite campSite2 = Camps.ById(item3.Key);
				Crumbs.Native("supply cache blip add");
				bool flag2 = item3.Value.Contains("(unguarded)");
				int num = MAP.BLIP_ADD_FOR_COORDS(flag2 ? 2545348716u : 2339406903u, campSite2.X, campSite2.Y, campSite2.Z);
				if (num != 0)
				{
					MAP.SET_BLIP_SPRITE(num, MISC.GET_HASH_KEY("blip_chest"), p2: true);
					Function.Call(11290983183885202434uL, num, new InputArgument(UiDraw.ForeverVarString(item3.Value)));
					_cacheBlips[item3.Key] = (num, item3.Value);
					GrudgeLog("SUPPLY cache marker: \"" + item3.Value + "\" at " + campSite2.Label + " (" + (flag2 ? "white" : "red") + ")");
				}
			}
		}
	}

	private unsafe void CleanupCacheBlips()
	{
		foreach (string item2 in _cacheBlips.Keys.ToList())
		{
			int item = _cacheBlips[item2].blip;
			MAP.REMOVE_BLIP(&item);
		}
		_cacheBlips.Clear();
	}

	private void UpdateSupplyCamps(Ped player)
	{
		if (!Config.CampsEnabled)
		{
			return;
		}
		try
		{
			UpdateSupplyCaches(player);
		}
		catch (Exception ex)
		{
			GrudgeLog("SUPPLY cache failed: " + ex.Message);
		}
		UpdateSupplyHits(player);
		try
		{
			UpdateCampObjectives(player);
		}
		catch (Exception ex2)
		{
			GrudgeLog("OBJECTIVE failed: " + ex2.Message);
		}
	}

	private void SetCrateAlight(LiveSupply ls, Vector3 at, bool big)
	{
		try
		{
			Crumbs.Native("supply crate fire");
			int num = FIRE.START_SCRIPT_FIRE(at.X, at.Y, at.Z + 0.2f, big ? 12 : 6, big ? 2f : 1f, p5: false, "", 0f, 0);
			if (num != 0)
			{
				ls.Fires.Add(num);
			}
			ls.Burned = true;
			ls.FireSpots.Add((at, Game.GameTime));
		}
		catch (Exception ex)
		{
			GrudgeLog("SUPPLY crate fire failed: " + ex.Message);
		}
	}

	private void PutOutCrateFires(LiveSupply ls)
	{
		foreach (int fire in ls.Fires)
		{
			try
			{
				Crumbs.Native("supply fire out");
				Function.Call(8719291874861989993uL, fire);
			}
			catch
			{
			}
		}
		ls.Fires.Clear();
	}

	private void AddLooseCrate(LiveSupply ls, Vector3 at)
	{
		_propModel.TryGetValue("loosecrate", out var value);
		int num = MakeCheckpointProp(LooseCrateModels, at, _rng.Next(360), ref value, freeze: false);
		if (value != null)
		{
			_propModel["loosecrate"] = value;
		}
		if (num != 0)
		{
			int num2 = ENTITY.GET_ENTITY_HEALTH(num);
			ls.Crates.Add(new SupplyCrate
			{
				Obj = num,
				At = at,
				Start = num2,
				Last = num2
			});
		}
	}

	internal static bool OpenGround(Vector3 at, float reach)
	{
		Vector3 vector = at + new Vector3(0f, 0f, 0.6f);
		if (Ray.Blocked(vector, vector + new Vector3(0f, 0f, 5f), 17, 0))
		{
			return false;
		}
		Vector3[] array = new Vector3[4]
		{
			new Vector3(reach, 0f, 0f),
			new Vector3(0f - reach, 0f, 0f),
			new Vector3(0f, reach, 0f),
			new Vector3(0f, 0f - reach, 0f)
		};
		foreach (Vector3 vector2 in array)
		{
			if (Ray.Blocked(vector, vector + vector2, 17, 0))
			{
				return false;
			}
		}
		return true;
	}

	private void SpawnSupplies(CampSite site)
	{
		Gang gang = SupplyGangOf(site);
		if (gang == null || _liveSupplies.ContainsKey(site.Id))
		{
			return;
		}
		LiveSupply liveSupply = new LiveSupply
		{
			SiteId = site.Id,
			Gang = gang
		};
		_liveSupplies[site.Id] = liveSupply;
		bool flag = SupplyRaidedRecently(gang);
		Vector3 c = Kit.Centre(site);
		int num = (flag ? 2 : 4);
		double num2 = _rng.NextDouble() * Math.PI * 2.0;
		int moved = 0;
		int dropped = 0;
		for (int i = 0; i < num; i++)
		{
			Vector3 vector = Edge(num2 + (double)i * 0.55, 7.5f + (float)_rng.NextDouble() * 2f);
			if (vector == Vector3.Zero || !Dry(vector))
			{
				continue;
			}
			if (i < 2)
			{
				_propModel.TryGetValue("crate", out var value);
				int num3 = MakeCheckpointProp(BigCrateModels, vector, _rng.Next(360), ref value);
				if (value != null)
				{
					_propModel["crate"] = value;
				}
				if (num3 != 0)
				{
					liveSupply.Crates.Add(new SupplyCrate
					{
						Obj = num3,
						At = vector,
						Big = true
					});
				}
				continue;
			}
			for (int j = 0; j < 2; j++)
			{
				Vector3 vector2 = ((j == 0) ? vector : GroundOnSpot(vector + new Vector3(1.1f, 0.6f, 0f)));
				if (!(vector2 == Vector3.Zero) && (j <= 0 || OpenGround(vector2, 0.7f)))
				{
					AddLooseCrate(liveSupply, vector2);
				}
			}
		}
		for (int k = 0; k < 2; k++)
		{
			Vector3 vector3 = Edge(num2 + (double)num * 0.55 + (double)k * 0.4, 8f);
			if (!(vector3 == Vector3.Zero))
			{
				_propModel.TryGetValue("barrel", out var value2);
				int num4 = MakeCheckpointProp(BarrelModels, vector3, _rng.Next(360), ref value2);
				if (value2 != null)
				{
					_propModel["barrel"] = value2;
				}
				if (num4 != 0)
				{
					liveSupply.Barrels.Add(num4);
				}
			}
		}
		Vector3 vector4 = Pick(num2 + Math.PI, 11f, 3.2f);
		string text = null;
		if (!flag && vector4 != Vector3.Zero && Dry(vector4))
		{
			foreach (string item in SupplyWagonModels.OrderBy((string _) => _rng.Next()).Concat(new string[2] { "wagon04x", "cart03" }))
			{
				uint num5 = MISC.GET_HASH_KEY(item);
				if (STREAMING.IS_MODEL_IN_CDIMAGE(num5) && STREAMING.IS_MODEL_A_VEHICLE(num5))
				{
					Crumbs.Native("supply wagon");
					Vehicle vehicle = SpawnVehicle((VehicleHash)num5, vector4 + new Vector3(0f, 0f, 0.3f), _rng.Next(360));
					if (!(vehicle == null))
					{
						MakeOurs(vehicle.Handle);
						VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(vehicle.Handle, p1: false);
						liveSupply.Wagon = vehicle;
						liveSupply.WagonAt = vehicle.Position;
						text = item;
						break;
					}
				}
			}
		}
		int num6 = (flag ? 1 : (2 + _rng.Next(2)));
		for (int num7 = 0; num7 < num6; num7++)
		{
			Vector3 vector5 = Pick(num2 + Math.PI + 0.45 + (double)num7 * 0.22, 13f, 1.6f);
			if (vector5 == Vector3.Zero)
			{
				continue;
			}
			Crumbs.Native("supply horse");
			Ped ped = null;
			for (int num8 = 0; num8 < 3; num8++)
			{
				if (!(ped == null))
				{
					break;
				}
				ped = SpawnPed(RiderHorses[_rng.Next(RiderHorses.Length)], vector5, _rng.Next(360));
			}
			if (!(ped == null))
			{
				MakeOurs(ped.Handle);
				TASK.TASK_STAND_STILL(ped.Handle, -1);
				liveSupply.Horses.Add((ped, vector5));
			}
		}
		GrudgeLog(string.Format("SUPPLY {0}: {1} - {2} crate stacks, {3}, {4} horses{5}; supplies {6}; open ground: {7} moved, {8} dropped", gang.Name, site.Label, liveSupply.Crates.Count, (liveSupply.Wagon != null) ? ("a wagon (" + text + ")") : "no wagon", liveSupply.Horses.Count, flag ? " (raided - not restocked yet)" : "", SuppliesOf(gang), moved, dropped));
		Vector3 Edge(double a, float r)
		{
			return Pick(a, r, 1.1f);
		}
		Vector3 Pick(double a, float r, float reach)
		{
			for (int l = 0; l < 10; l++)
			{
				Vector3 vector6 = Raw((l == 0) ? a : (a + (_rng.NextDouble() - 0.5) * 1.0), (l == 0) ? r : Math.Max(5f, r + ((float)_rng.NextDouble() - 0.5f) * 5f));
				if (!(vector6 == Vector3.Zero) && OpenGround(vector6, reach) && Kit.ClearOf(site.Id, vector6, reach))
				{
					if (l > 0)
					{
						moved++;
					}
					return vector6;
				}
			}
			dropped++;
			return Vector3.Zero;
		}
		Vector3 Raw(double a, float r)
		{
			return GroundOnSpot(c + new Vector3((float)Math.Cos(a) * r, (float)Math.Sin(a) * r, 0f));
		}
	}

	private unsafe void DespawnSupplies(string siteId)
	{
		ClearObjectives(siteId);
		if (siteId == null || !_liveSupplies.TryGetValue(siteId, out var value))
		{
			return;
		}
		foreach (int debugBlip in value.DebugBlips)
		{
			int current = debugBlip;
			Crumbs.Native("town crate debug blip remove");
			if (MAP.DOES_BLIP_EXIST(current))
			{
				MAP.REMOVE_BLIP(&current);
			}
		}
		value.DebugBlips.Clear();
		PutOutCrateFires(value);
		_liveSupplies.Remove(siteId);
		foreach (Ped man in value.Men)
		{
			if (man != null && man.Exists())
			{
				if (!man.IsDead && SafeToDelete(man))
				{
					man.Delete();
					continue;
				}
				int handle = man.Handle;
				ReleaseIfOurs(&handle);
			}
		}
		value.Men.Clear();
		if (_crateOpening != null && value.Crates.Contains(_crateOpening))
		{
			_crateOpening = null;
		}
		Ped character = Game.Player.Character;
		DropProps((from x in value.Crates
			where x.Obj != 0
			select x.Obj).Concat(value.Barrels).ToList(), character, wipe: false);
		if (value.Wagon != null && value.Wagon.Exists())
		{
			if (!PED.IS_PED_IN_VEHICLE(character.Handle, value.Wagon.Handle, p2: false) && SafeToDeleteVehicle(value.Wagon))
			{
				value.Wagon.Delete();
			}
			else
			{
				int handle2 = value.Wagon.Handle;
				ReleaseIfOurs(&handle2);
			}
		}
		foreach (var horse in value.Horses)
		{
			Ped item = horse.horse;
			if (item != null && item.Exists())
			{
				if (!item.IsDead && SafeToDelete(item))
				{
					item.Delete();
					continue;
				}
				int handle3 = item.Handle;
				ReleaseIfOurs(&handle3);
			}
		}
	}

	internal bool SafeToDeleteVehicle(Vehicle v)
	{
		Ped character = Game.Player.Character;
		if (v != null && v.Exists() && BelongsToUs(v.Handle))
		{
			if (!(character.Position.DistanceTo(v.Position) > 80f))
			{
				return HiddenFromView(character, v.Position);
			}
			return true;
		}
		return false;
	}

	private unsafe void UpdateSupplyHits(Ped player)
	{
		if (_liveSupplies.Count == 0 || Game.GameTime < _nextSupplyCheck)
		{
			return;
		}
		_nextSupplyCheck = Game.GameTime + 300;
		foreach (LiveSupply item in _liveSupplies.Values.ToList())
		{
			Gang gang = item.Gang;
			foreach (SupplyCrate cr in item.Crates)
			{
				if (cr.Gone)
				{
					continue;
				}
				bool flag = cr.Obj != 0 && ENTITY.DOES_ENTITY_EXIST(cr.Obj);
				bool flag2 = FIRE.IS_EXPLOSION_IN_SPHERE(-1, cr.At.X, cr.At.Y, cr.At.Z, cr.Big ? 5f : 4f);
				bool flag3 = (flag && FIRE.IS_ENTITY_ON_FIRE(cr.Obj)) || FIRE.GET_NUMBER_OF_FIRES_IN_RANGE(cr.At.X, cr.At.Y, cr.At.Z, cr.Big ? 2.4f : 1.6f) > 0;
				if (flag3 && item.FireSpots.Any(((Vector3 at, int t) s) => Game.GameTime - s.t < 20000 && s.at.DistanceTo2D(cr.At) < 3.5f))
				{
					flag3 = false;
				}
				cr.FireTicks = (flag3 ? (cr.FireTicks + 1) : 0);
				bool flag4 = cr.FireTicks >= 5;
				bool flag5 = false;
				if (!cr.Big)
				{
					int num = (flag ? ENTITY.GET_ENTITY_HEALTH(cr.Obj) : 0);
					if (flag && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(cr.Obj, player.Handle, p2: true, p3: true))
					{
						cr.Hits++;
						try
						{
							ENTITY.CLEAR_ENTITY_LAST_DAMAGE_ENTITY(cr.Obj);
						}
						catch
						{
						}
					}
					if (num != cr.Last)
					{
						cr.Last = num;
					}
					flag5 = !flag || num <= 0 || cr.Hits >= 2 || (cr.Start > 0 && (double)num <= (double)cr.Start * 0.85);
				}
				if (flag2 || flag5 || flag4)
				{
					cr.Gone = true;
					Vector3 at = (flag ? ENTITY.GET_ENTITY_COORDS(cr.Obj, p1: true, p2: true) : cr.At);
					SetCrateAlight(item, at, cr.Big);
					NemesisMod nemesisMod = this;
					LiveSupply ls = item;
					Ped player2 = player;
					int amount = (cr.Big ? 12 : 5);
					string why;
					if (cr.Big)
					{
						why = ((flag4 && !flag2) ? "you burned their stores" : "you blew up their stores");
					}
					else if (flag2)
					{
						why = "you blew their crates apart";
					}
					else
					{
						why = (flag4 ? "you set their crates burning" : "you shot their crates to pieces");
					}
					nemesisMod.SupplyHit(ls, player2, amount, why);
				}
			}
			if (item.Town && !item.Destroyed && item.Crates.Count > 0 && item.Crates.All((SupplyCrate x) => x.Gone))
			{
				item.Destroyed = true;
				string text = TownNear(item.Crates[0].At);
				ShowNotification("You destroyed the " + ShortOutfit(gang) + " stash" + ((text != null) ? (" in " + text) : "") + ".");
				foreach (int debugBlip in item.DebugBlips)
				{
					int current2 = debugBlip;
					if (MAP.DOES_BLIP_EXIST(current2))
					{
						MAP.REMOVE_BLIP(&current2);
					}
				}
				item.DebugBlips.Clear();
				GrudgeLog("SUPPLY " + (text ?? item.SiteId) + ": the " + OutfitPoss(gang) + " stash is destroyed - every crate gone");
			}
			if (!item.WagonCounted && item.Wagon != null)
			{
				bool flag6 = !item.Wagon.Exists() || VEHICLE.IS_VEHICLE_WRECKED(item.Wagon.Handle) || ENTITY.GET_ENTITY_HEALTH(item.Wagon.Handle) <= 0;
				bool flag7 = item.Wagon.Exists() && item.Wagon.Position.DistanceTo(item.WagonAt) > 120f;
				if (flag6 | flag7)
				{
					item.WagonCounted = true;
					SupplyHit(item, player, 15, flag6 ? "you wrecked their supply wagon" : "you made off with their supply wagon", flag6 ? ("You destroyed the " + ShortOutfit(item.Gang) + " supply wagon.") : ("You made off with the " + ShortOutfit(item.Gang) + " supply wagon."));
				}
			}
			foreach (var (ped, position) in item.Horses)
			{
				if (!(ped == null) && !item.HorsesCounted.Contains(ped.Handle))
				{
					if (!ped.Exists() || ped.IsDead)
					{
						item.HorsesCounted.Add(ped.Handle);
						SupplyHit(item, player, 4, "you killed one of their horses");
					}
					else if (ped.Position.DistanceTo(position) > 60f)
					{
						item.HorsesCounted.Add(ped.Handle);
						SupplyHit(item, player, 3, "you ran off one of their horses");
					}
				}
			}
		}
	}

	private void SupplyHit(LiveSupply ls, Ped player, int amount, string why, string say = null)
	{
		Gang gang = ls.Gang;
		Vector3 vector;
		if (ls.Town)
		{
			vector = ((ls.Crates.Count > 0) ? ls.Crates[0].At : player.Position);
		}
		else
		{
			CampSite campSite = Camps.ById(ls.SiteId);
			vector = ((campSite != null) ? SitePos(campSite) : player.Position);
		}
		Vector3 position = vector;
		int mount = PED.GET_MOUNT(player.Handle);
		if (!(player.Position.DistanceTo(position) < 90f) && (!_liveCamps.TryGetValue(ls.SiteId, out var value) || !value.Engaged) && (!(ls.Wagon != null) || !ls.Wagon.Exists() || !PED.IS_PED_IN_VEHICLE(player.Handle, ls.Wagon.Handle, p2: false)) && (mount == 0 || !ls.Horses.Any(((Ped horse, Vector3 at) h) => h.horse != null && h.horse.Handle == mount)))
		{
			int val = (ls.Town ? amount : Math.Max(0, 40 - ls.Lost));
			int num = Math.Min(amount, val);
			if (!ls.Town)
			{
				ls.Lost += num;
			}
			if (num > 0)
			{
				AddSupplies(gang, -num, why.Replace("you ", "someone ") + " (not you)");
			}
			GrudgeLog($"SUPPLY {gang.Name}: -{num} at {ls.SiteId} with you {player.Position.DistanceTo(position):0} m off - not put on you");
			return;
		}
		if (!ls.Town)
		{
			int num2 = Math.Max(0, 40 - ls.Lost);
			if (amount > num2)
			{
				GrudgeLog($"SUPPLY raid cap: {why} -{amount} cut to -{num2} ({ls.Lost} of {40} taken this raid)");
			}
			amount = Math.Min(amount, num2);
		}
		int num3 = SuppliesOf(gang);
		if (amount > 0 && num3 > 0)
		{
			AddSupplies(gang, -amount, why);
			amount = num3 - SuppliesOf(gang);
			if (!ls.Town)
			{
				ls.Lost += amount;
			}
			string text = $"The {OutfitPoss(gang)} supplies: {SuppliesOf(gang)} - {SupplyState(SuppliesOf(gang)).ToLowerInvariant()}.";
			if (say != null)
			{
				ShowNotification(say);
			}
			else
			{
				GrudgeNotice(text);
			}
			Feed($"SUPPLIES {gang.Name}: -{amount} ({why})", gang.Accent);
		}
		else if (say != null)
		{
			ShowNotification(say);
		}
		else if (!ls.CapSaid)
		{
			ls.CapSaid = true;
			GrudgeNotice("The " + gang.Name + " have lost all they can here - the rest is just wreckage.");
		}
		if (ls.Hit)
		{
			return;
		}
		ls.Hit = true;
		foreach (Ped item in ls.Men.Where((Ped m) => m != null && m.Exists() && !m.IsDead))
		{
			item.BlockPermanentEvents = false;
			TASK.CLEAR_PED_TASKS(item.Handle, p1: true, p2: true);
			TASK.TASK_COMBAT_PED(item.Handle, player.Handle, 0, 16);
		}
		if (ls.Town)
		{
			AddNotoriety(gang, 1, "you broke into their crates in town");
			Vector3 vector2 = ((ls.Crates.Count > 0) ? ls.Crates[0].At : player.Position);
			string text2 = TownNear(vector2);
			try
			{
				ChronicleDeed("supplies", "You broke into the " + OutfitPoss(gang) + " crates" + ((text2 != null) ? (" in " + text2) : ""), (text2 != null) ? ("in " + text2) : ("near " + GetZoneName(vector2)), vector2, gang.Id);
				return;
			}
			catch
			{
				return;
			}
		}
		Hold.RecordRaid(gang, ls.SiteId);
		CampSite campSite2 = Camps.ById(ls.SiteId);
		if (campSite2 != null)
		{
			Hold.KnowSupplies(gang, campSite2);
		}
		SaveWorld();
		AddNotoriety(gang, 3, "you hit their supplies");
		CampSite campSite3 = Camps.ById(ls.SiteId);
		NemesisRecord nemesisRecord = ((campSite3 != null) ? (HolderOf(campSite3) ?? (_liveCamps.TryGetValue(campSite3.Id, out var value2) ? value2.Boss : null)) : null);
		if (nemesisRecord != null)
		{
			nemesisRecord.AddHate(10);
			History(nemesisRecord, "RAIDED: you hit the supplies he kept at " + campSite3.Label, Theme.Blood);
			SaveRoster();
		}
		if (IsSupplyCache(gang))
		{
			RefreshCacheBlips();
		}
		try
		{
			ChronicleDeed("supplies", "You hit the " + OutfitPoss(gang) + " supplies", (campSite3 != null) ? ("at " + campSite3.Label) : "", (campSite3 != null) ? new Vector3?(SitePos(campSite3)) : ((Vector3?)null), gang.Id);
		}
		catch
		{
		}
		if (campSite3 != null)
		{
			RedoCampBlip(campSite3.Id);
		}
	}

	private unsafe void CrateBreaking(Ped player)
	{
		if (_crateOpening != null)
		{
			if (player.IsDead || player.Position.DistanceTo(_crateOpening.At) > 2.8f || !_liveSupplies.ContainsValue(_crateOpeningIn))
			{
				_crateOpening = null;
			}
			else
			{
				if (Game.GameTime < _crateOpenUntil)
				{
					return;
				}
				SupplyCrate crateOpening = _crateOpening;
				LiveSupply crateOpeningIn = _crateOpeningIn;
				_crateOpening = null;
				try
				{
					TASK.CLEAR_PED_TASKS(player.Handle, p1: false, p2: false);
				}
				catch
				{
				}
				if (!crateOpening.Gone)
				{
					crateOpening.Gone = true;
					int num = 2 + _rng.Next(5);
					PayPlayer(num * 100);
					if (crateOpening.Obj != 0 && ENTITY.DOES_ENTITY_EXIST(crateOpening.Obj))
					{
						int obj2 = crateOpening.Obj;
						OBJECT.DELETE_OBJECT(&obj2);
						crateOpening.Obj = 0;
					}
					SupplyHit(crateOpeningIn, player, 6, "you broke open their crates");
					GrudgeNotice($"You broke open a crate - ${num} and their stores spoiled.");
				}
			}
