			text += " (its horse was spooked - calmed)";
		}
		goto IL_0821;
		void Drive(Vector3 to3)
		{
			if (_supplyWagonWander)
			{
				WagonWander(drv, _supplyWagon);
			}
			else
			{
				WagonDrive(drv, _supplyWagon, to3);
			}
		}
	}

	private unsafe void EndSupplyWagon(Ped player, bool wipe)
	{
		if (_supplyWagon == null && _supplyWagonMen.Count == 0)
		{
			return;
		}
		foreach (Ped item in _supplyWagonMen.ToList())
		{
			if (!(item == null) && item.Exists())
			{
				if (wipe)
				{
					Wipe(item);
				}
				else
				{
					DeleteOrRelease(item);
				}
			}
		}
		_supplyWagonMen.Clear();
		foreach (Ped supplyWagonHorse in _supplyWagonHorses)
		{
			if (supplyWagonHorse == null || !supplyWagonHorse.Exists())
			{
				continue;
			}
			if (wipe)
			{
				if (BelongsToUs(supplyWagonHorse.Handle))
				{
					Wipe(supplyWagonHorse);
				}
			}
			else
			{
				int handle = supplyWagonHorse.Handle;
				ReleaseIfOurs(&handle);
			}
		}
		_supplyWagonHorses.Clear();
		DropSupplyWagonBlip();
		if (_supplyWagon != null && _supplyWagon.Exists())
		{
			if (!PED.IS_PED_IN_VEHICLE(player.Handle, _supplyWagon.Handle, p2: false) && BelongsToUs(_supplyWagon.Handle) && (wipe || SafeToDeleteVehicle(_supplyWagon)))
			{
				_supplyWagon.Delete();
			}
			else
			{
				int handle2 = _supplyWagon.Handle;
				ReleaseIfOurs(&handle2);
			}
		}
		GrudgeLog("SUPPLY wagon: over" + (_supplyWagonCounted ? " (hit)" : ""));
		_supplyWagon = null;
		_supplyWagonGang = null;
		_supplyWagonAllowed = Game.GameTime + 360000;
	}

	private void DropSupplyWagonBlip()
	{
		if (_supplyWagonBlip == null)
		{
			return;
		}
		Crumbs.Native("supply wagon blip remove");
		try
		{
			if (_supplyWagonBlip.Exists())
			{
				_supplyWagonBlip.Delete();
			}
		}
		catch
		{
		}
		_supplyWagonBlip = null;
	}

	private void UpdateTownCrates(Ped player)
	{
		string currentTown = _currentTown;
		if (_townCratesFor != null && currentTown != _townCratesFor)
		{
			DespawnTownStashes(_townCratesFor);
			_townCratesFor = null;
		}
		if (currentTown != null && !(_townCratesFor == currentTown) && !MISC.GET_MISSION_FLAG() && !WorldBusy(player) && InTownForArrivals(player, currentTown))
		{
			_townCratesFor = currentTown;
			if (_rng.Next(100) >= 50)
			{
				GrudgeLog("SUPPLY " + currentTown + ": no outfit's crates on the street this visit");
			}
			else if (SpawnTownCrates(player, currentTown) && _rng.Next(100) < 30)
			{
				SpawnTownCrates(player, currentTown);
			}
		}
	}

	private IEnumerable<string> TownStashKeys(string town)
	{
		return _liveSupplies.Keys.Where((string k) => k == "town:" + town || k.StartsWith("town:" + town + "#")).ToList();
	}

	private void DespawnTownStashes(string town)
	{
		foreach (string item in TownStashKeys(town))
		{
			DespawnSupplies(item);
		}
	}

	private string FreeTownStashKey(string town)
	{
		for (int i = 1; i <= 2; i++)
		{
			string text = ((i == 1) ? ("town:" + town) : $"town:{town}#{i}");
			if (!_liveSupplies.ContainsKey(text))
			{
				return text;
			}
		}
		return null;
	}

	private bool SpawnTownCrates(Ped player, string town)
	{
		District d = DistrictAt(TownCore(town, out var centre, out var _) ? centre : player.Position);
		Gang gang = TownHolder(town, out var _) ?? ((d == null) ? null : (from x in Gangs.All
			where !x.StoryOnly && !IsDestroyed(x) && HoldOf(d, x.Id) > 0
			orderby HoldOf(d, x.Id) descending
			select x).FirstOrDefault());
		if (gang == null)
		{
			return false;
		}
		string text = FreeTownStashKey(town);
		if (text == null)
		{
			return false;
		}
		List<Vector3> list = (from k in TownStashKeys(town)
			select _liveSupplies[k] into o
			where o.Crates.Count > 0
			select o.Crates[0].At).ToList();
		Vector3 position = player.Position;
		List<StashSpot> list2 = StashSpots.Where((StashSpot x) => x.Town == town).ToList();
		if (list2.Count == 0)
		{
			GrudgeLog("SUPPLY " + town + ": no stash spots placed here - no stash");
			return false;
		}
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		StashSpot stashSpot = null;
		foreach (StashSpot sp in list2.OrderBy((StashSpot _) => _rng.Next()))
		{
			if (sp.Pos.DistanceTo(position) < 30f)
			{
				num2++;
				continue;
			}
			if (list.Any((Vector3 o) => o.DistanceTo2D(sp.Pos) < 150f))
			{
				num3++;
				continue;
			}
			if (!HiddenFromView(player, sp.Pos + new Vector3(0f, 0f, 1f)))
			{
				num++;
				continue;
			}
			stashSpot = sp;
			break;
		}
		if (stashSpot == null)
		{
			GrudgeLog($"SUPPLY {town}: no placed spot fits the {OutfitPoss(gang)} stash ({list2.Count} here: {num} in view, {num2} too near you, {num3} too near the other stash)");
			return false;
		}
		LiveSupply liveSupply = new LiveSupply
		{
			SiteId = text,
			Gang = gang,
			Town = true
		};
		_liveSupplies[liveSupply.SiteId] = liveSupply;
		Vector3 best = stashSpot.Pos;
		double num4 = (double)stashSpot.H * Math.PI / 180.0;
		Vector3 vector = new Vector3(0f - (float)Math.Sin(num4), (float)Math.Cos(num4), 0f);
		Vector3 vector2 = new Vector3(0f - vector.Y, vector.X, 0f);
		if (_rng.Next(100) < 60)
		{
			Vector3 vector3 = GroundOnSpot(best - vector * 1f);
			if (vector3 != Vector3.Zero && Math.Abs(vector3.Z - best.Z) < 0.8f)
			{
				_propModel.TryGetValue("crate", out var value);
				int num5 = MakeCheckpointProp(BigCrateModels, vector3, stashSpot.H + (float)_rng.Next(-8, 9), ref value);
				if (value != null)
				{
					_propModel["crate"] = value;
				}
				if (num5 != 0)
				{
					liveSupply.Crates.Add(new SupplyCrate
					{
						Obj = num5,
						At = vector3,
						Big = true
					});
				}
			}
		}
		(float, float)[] array = new (float, float)[7]
		{
			(0f, 0.4f),
			(0.9f, 0.3f),
			(-0.9f, 0.3f),
			(0.45f, 1.2f),
			(-0.45f, 1.2f),
			(1.6f, -0.4f),
			(-1.6f, -0.4f)
		};
		int num6 = 3 + _rng.Next(3);
		int num7 = 0;
		(float, float)[] array2 = array;
		for (int num8 = 0; num8 < array2.Length; num8++)
		{
			var (num9, num10) = array2[num8];
			if (num7 >= num6)
			{
				break;
			}
			Vector3 vector4 = GroundOnSpot(best + vector2 * num9 + vector * num10);
			if (!(vector4 == Vector3.Zero) && !(Math.Abs(vector4.Z - best.Z) > 0.6f))
			{
				AddLooseCrate(liveSupply, vector4);
				num7++;
			}
		}
		if (liveSupply.Crates.Count == 0)
		{
			DespawnSupplies(liveSupply.SiteId);
			GrudgeLog("SUPPLY " + town + ": no room at the placed spot for the " + OutfitPoss(gang) + " stash");
			return false;
		}
		string text2 = null;
		if (_rng.Next(100) < 40 && FactionModels.ContainsKey(gang.Id))
		{
			Vector3 vector5 = GroundOnSpot(best - vector2 * 2.2f + vector * 1.2f);
			if (vector5 != Vector3.Zero && Math.Abs(vector5.Z - best.Z) < 1f)
			{
				Ped ped = CheckpointMan(gang, vector5, HeadingTo(vector5, best + vector * 4f), (_rng.Next(2) == 0) ? "WORLD_HUMAN_LEAN_WALL_LEFT" : "WORLD_HUMAN_SMOKE");
				if (ped != null)
				{
					liveSupply.Men.Add(ped);
					text2 = "a lookout";
				}
			}
		}
		if (Config.DebugEnabled && !_mapHidden)
		{
			Crumbs.Native("town crate debug blip");
			int num11 = MAP.BLIP_ADD_FOR_COORDS(2545348716u, best.X, best.Y, best.Z);
			if (num11 != 0)
			{
				MAP.SET_BLIP_SPRITE(num11, MISC.GET_HASH_KEY("blip_chest"), p2: true);
				Function.Call(11290983183885202434uL, num11, new InputArgument(UiDraw.ForeverVarString(ShortOutfit(gang) + " stash (debug)")));
				liveSupply.DebugBlips.Add(num11);
			}
		}
		int num12 = Enumerable.Count(liveSupply.Crates, (SupplyCrate x) => x.Big);
		GrudgeLog(string.Format("SUPPLY {0}: the {1} stash at a placed spot {2:0},{3:0}{4} - {5} crates{6}{7}", town, OutfitPoss(gang), best.X, best.Y, (list.Count > 0) ? $" ({list.Min((Vector3 o) => o.DistanceTo2D(best)):0} m from the other)" : "", liveSupply.Crates.Count - num12, (num12 > 0) ? ", a big crate" : "", (text2 != null) ? ", a lookout" : ""));
		return true;
	}

	private void DebugSupplyWagon(Ped p)
	{
		if (_supplyWagon != null)
		{
			SpawnerSays("a supply wagon is already on the road.");
			return;
		}
		Gang gang = TopHolderHere(p);
		if (gang == null || !FactionModels.ContainsKey(gang.Id))
		{
			gang = Gangs.All.FirstOrDefault((Gang x) => !x.StoryOnly && !IsDestroyed(x) && FactionModels.ContainsKey(x.Id));
		}
		if (gang == null)
		{
			SpawnerSays("no outfit with men to send.");
		}
		else
		{
			SpawnerSays(SpawnSupplyWagon(p, gang) ? ("the " + OutfitPoss(gang) + " supply wagon is coming up the road ahead.") : "no road out of your view ahead - face down a road and try again.");
		}
	}

	private void DebugTownCrates(Ped p)
	{
		string text = SpawnerTown(p);
		if (text != null)
		{
			if (FreeTownStashKey(text) == null)
			{
				DespawnTownStashes(text);
			}
			_townCratesFor = text;
			int num = TownStashKeys(text).Count();
			bool flag = SpawnTownCrates(p, text);
			SpawnerSays(flag ? $"a stash is down somewhere in town ({num + 1} of {2} - debug markers on the map, grudges.log says where)." : "no placed stash spot fits right now (in view, too near you, or near the other stash - grudges.log says) - place more with 'Place a town stash spot here'.");
		}
	}

	private void MaybeSpawnSurvivors(WorldEvent e, Ped player, Vector3 center)
	{
		if ((!e.ForceSurvivors && _rng.Next(100) >= Config.WorldSurvivorChance) || e.Gangs == null)
		{
			return;
		}
		List<string> list = e.Gangs.Where((string g) => !string.IsNullOrEmpty(g) && Gangs.ById(g) != null).Distinct().ToList();
		if (list.Count == 0)
		{
			return;
		}
		List<string> source = list.OrderBy(Dead).ToList();
		string text = source.First();
		string text2 = source.Last();
		bool flag = list.Count == 1 || _rng.Next(2) == 0;
		Gang gang = Gangs.ById(flag ? text : text2);
		if (gang == null || gang.TroopModels.Length == 0)
		{
			return;
		}
		List<NemesisRecord> list2 = (from _ in (from p in e.People
				where p.Gang == gang.Id && (p.Outcome == "UNHURT" || p.Outcome == "WOUNDED" || p.Outcome == "DISTINGUISHED")
				select Roster.FirstOrDefault((NemesisRecord r) => r.Id == p.Id) into r
				where r != null && r.IsAlive && !r.PresumedDead && r.CanHunt && !Resting(r) && r != ActiveRecord && !_worldNemeses.ContainsValue(r)
				select r).Distinct()
			orderby _rng.Next()
			select _).Take(2).ToList();
		int num = Math.Max(list2.Count, 2 + _rng.Next(3));
		if (_survivorGroup == 0)
		{
			_survivorGroup = World.AddRelationshipGroup("NEMESIS_SURVIVORS");
		}
		_survivorGang = gang;
		_survivorsHostile = false;
		SetSurvivorRelation(player);
		List<string> list3 = new List<string>();
		if (!flag)
		{
			list3.Add("mourn");
			if (num >= 4 && _rng.Next(100) < 30)
			{
				list3.Add("mourn");
			}
		}
		else
		{
			list3.Add("search");
		}
		list3.Add("watch");
		List<string> list4 = new List<string> { "smoke", "wander", "lazy", "talk", "drink", "watch" }.OrderBy((string _) => _rng.Next()).ToList();
		while (list3.Count < num && list4.Count > 0)
		{
			list3.Add(list4[0]);
			list4.RemoveAt(0);
		}
		while (list3.Count < num)
		{
			list3.Add("wander");
		}
		list3 = (from _ in list3.Take(num)
			orderby _rng.Next()
			select _).ToList();
		HashSet<int> usedBodies = new HashSet<int>();
		for (int num2 = 0; num2 < num; num2++)
		{
			string role = list3[num2];
			double num3 = _rng.NextDouble() * Math.PI * 2.0;
			float num4 = 4f + (float)_rng.NextDouble() * 12f;
			Vector3 pos = GroundOnSpot(center + new Vector3((float)Math.Cos(num3) * num4, (float)Math.Sin(num3) * num4, 0f));
			float heading = _rng.Next(360);
			Ped ped;
			if (num2 < list2.Count)
			{
				NemesisRecord nemesisRecord = list2[num2];
				ped = SpawnNemesisPed(nemesisRecord, pos, heading, _survivorGroup, out var _, (uint)gang.TroopModels[0]);
				if (ped == null)
				{
					continue;
				}
				_worldNemeses[ped.Handle] = nemesisRecord;
				nemesisRecord.Touch();
				History(nemesisRecord, flag ? ("STILL HOLDING the field after it: " + e.Title) : ("WENT BACK for his dead after it: " + e.Title), gang.Accent);
			}
			else
			{
				ped = SpawnPed(gang.TroopModels[_rng.Next(gang.TroopModels.Length)], pos, heading);
				if (ped == null)
				{
					continue;
				}
				MakeOurs(ped.Handle);
				ArmTroop(ped, gang);
				ped.Accuracy = gang.TroopAccuracy;
				ped.RelationshipGroup = _survivorGroup;
				ApplyFactionStyle(ped, gang.Id);
			}
			ped.BlockPermanentEvents = false;
			role = SurvivorRole(ped, role, gang, center, usedBodies);
			GrudgeLog("SURVIVORS a " + MemberWord(gang) + " man: " + role);
			_survivors.Add(ped);
		}
		GrudgeLog(string.Format("SURVIVORS at {0}: {1} {2} ({3}), ", e.Title, _survivors.Count, gang.Name, flag ? "the winners still hold it" : "the losers came back") + string.Format("{0} named ({1}), after you: {2}", list2.Count, string.Join(", ", list2.Select((NemesisRecord n) => n.Name)), AfterYou(gang)));
		Feed(string.Format("AFTERMATH {0}: {1} men still at the battlefield ({2})", gang.Name, _survivors.Count, flag ? "holding it" : "came back for their dead"), gang.Accent);
		int Dead(string g)
		{
			int value;
			return Enumerable.Count(e.People, (WorldPart p) => p.Gang == g && p.Outcome == "KILLED") + (e.UnnamedDead.TryGetValue(g, out value) ? value : 0);
		}
	}

	private string SurvivorRole(Ped p, string role, Gang gang, Vector3 center, HashSet<int> usedBodies)
	{
		switch (role)
		{
		case "mourn":
		case "search":
		{
			Ped ped2 = Body(role == "mourn");
			if (ped2 == null)
			{
				Scenario("WORLD_HUMAN_GUARD_LAZY");
				return "lazy (no body for him)";
			}
			usedBodies.Add(ped2.Handle);
			double num2 = _rng.NextDouble() * Math.PI * 2.0;
			Vector3 vector2 = ped2.Position + new Vector3((float)Math.Cos(num2) * 0.9f, (float)Math.Sin(num2) * 0.9f, 0f);
			MoveTo(vector2, HeadingTo(vector2, ped2.Position));
			Scenario((role == "mourn") ? "WORLD_HUMAN_GRAVE_MOURNING_KNEEL" : "WORLD_HUMAN_CROUCH_INSPECT");
			if (!(role == "mourn"))
			{
				return "goes through the dead's pockets";
			}
			return "kneels by his dead";
		}
		case "watch":
		{
			double num3 = _rng.NextDouble() * Math.PI * 2.0;
			Vector3 vector3 = center + new Vector3((float)Math.Cos(num3) * (12f + (float)_rng.NextDouble() * 5f), (float)Math.Sin(num3) * (12f + (float)_rng.NextDouble() * 5f), 0f);
			MoveTo(vector3, HeadingTo(center, vector3));
			Scenario("WORLD_HUMAN_GUARD_SCOUT");
			return "keeps watch";
		}
		case "wander":
			Function.Call(16164602603745899285uL, p.Handle, center.X, center.Y, center.Z, 10f, 2f, 8f, 0);
			return "walks among the bodies";
		case "talk":
		{
			Ped ped = _survivors.LastOrDefault((Ped s) => s != null && s.Exists());
			if (ped == null)
			{
				Scenario("WORLD_HUMAN_SMOKE");
				return "smokes";
			}
			double num = _rng.NextDouble() * Math.PI * 2.0;
			Vector3 vector = ped.Position + new Vector3((float)Math.Cos(num) * 1.5f, (float)Math.Sin(num) * 1.5f, 0f);
			MoveTo(vector, HeadingTo(vector, ped.Position));
			TASK.TASK_LOOK_AT_ENTITY(p.Handle, ped.Handle, -1, 0, 51, 0);
			return "talks with another man";
		}
		case "drink":
			Scenario("WORLD_HUMAN_DRINKING");
			return "drinks";
		case "smoke":
			Scenario("WORLD_HUMAN_SMOKE");
			return "smokes";
		default:
			Scenario("WORLD_HUMAN_GUARD_LAZY");
			return "leans on his rifle";
		}
		Ped Body(bool own)
		{
			return (from _ in _aftermathPeds
				where _ != null && _.Exists() && !usedBodies.Contains(_.Handle) && gang.IsMemberModel((uint)_.Model.Hash) == own
				orderby _rng.Next()
				select _).FirstOrDefault();
		}
		void MoveTo(Vector3 at, float heading)
		{
			Vector3 vector4 = GroundOnSpot(at);
			ENTITY.SET_ENTITY_COORDS(p.Handle, vector4.X, vector4.Y, vector4.Z, p4: false, p5: false, p6: false, p7: false);
			ENTITY.SET_ENTITY_HEADING(p.Handle, heading);
		}
		void Scenario(string s)
		{
			TASK.TASK_START_SCENARIO_IN_PLACE_HASH(p.Handle, MISC.GET_HASH_KEY(s), -1, p3: true, 0u, -1f, p6: false);
		}
	}

	private void SetSurvivorRelation(Ped player)
	{
		if (_survivorGroup != 0 && _survivorGang != null)
		{
			eRelationshipType relationship;
			if (_survivorsHostile || (_survivorGang.NeedsReason && ReasonMet(_survivorGang)))
			{
				relationship = (eRelationshipType)6;
			}
			else
			{
				relationship = (_survivorGang.NeedsReason ? ((eRelationshipType)3) : ((eRelationshipType)4));
			}
			World.SetRelationshipBetweenGroups(relationship, _survivorGroup, player.RelationshipGroup);
		}
	}

	private void UpdateSurvivors(Ped player)
	{
		if (_survivors.Count == 0 || Game.GameTime < _nextSurvivorCheck)
		{
			return;
		}
		_nextSurvivorCheck = Game.GameTime + 300;
		if (_survivorsHostile)
		{
			return;
		}
		List<Ped> list = _survivors.Where((Ped p) => p != null && p.Exists() && !p.IsDead).ToList();
		string text = null;
		Sight s = SightFor(player, Config.WorldSurvivorSpotRange);
		foreach (Ped item in list)
		{
			if (ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(item.Handle, player.Handle, p2: true, p3: true))
			{
				text = "you hurt one of them";
				break;
			}
			if (!_survivorGang.NeedsReason)
			{
				float d = item.Position.DistanceTo(player.Position);
				if (Sees(item, player, s, out d))
				{
					text = $"they saw you at {d:0} m ({s.Stance})";
					break;
				}
				if (FiredInAnger && d < 80f)
				{
					text = "you fired";
					break;
				}
			}
		}
		if (text == null && list.Count < Enumerable.Count(_survivors, (Ped p) => p != null && p.Exists()))
		{
			text = "one of them went down";
		}
		if (text == null)
		{
			return;
		}
		_survivorsHostile = true;
		SetSurvivorRelation(player);
		foreach (Ped item2 in list)
		{
			TASK.CLEAR_PED_TASKS(item2.Handle, p1: true, p2: true);
			TASK.TASK_COMBAT_PED(item2.Handle, player.Handle, 0, 16);
		}
		GrudgeLog("SURVIVORS turned on you: " + text);
		Feed("AFTERMATH the " + _survivorGang.Name + " at the battlefield turned on you (" + text + ")", Theme.Blood);
	}

	private void DespawnSurvivors()
	{
		foreach (Ped survivor in _survivors)
		{
			if (!(survivor != null) || !survivor.Exists())
			{
				continue;
			}
			if (_worldNemeses.TryGetValue(survivor.Handle, out var value) && ReallyDead(survivor) && value.IsAlive && !value.PresumedDead && Roster.Contains(value))
			{
				try
				{
					ResolveNemesisDeath(survivor, value, Executed(survivor.Handle));
				}
				catch (Exception ex)
				{
					GrudgeLog("SURVIVORS death resolve failed: " + ex.Message);
				}
			}
			_worldNemeses.Remove(survivor.Handle);
			DeleteOrRelease(survivor);
		}
		_survivors.Clear();
		_survivorGang = null;
		_survivorsHostile = false;
	}

	private void UpdateTelegraph(Ped player)
	{
		if (Game.GameTime >= _nextTelegraphCheck)
		{
			_nextTelegraphCheck = Game.GameTime + 5000;
			DeliverTelegrams();
		}
		if (_tg != null)
		{
			UpdateTelegraphPanel(player);
			return;
		}
		if (_paperShown != null)
		{
			HideTelegraphPrompt();
			return;
		}
		if (Game.GameTime >= _nextClerkScan)
		{
			_nextClerkScan = Game.GameTime + 400;
			_clerkNear = (from p in PedsAround(player)
				where p != null && p.Exists() && !p.IsDead && p.IsHuman && p.Position.DistanceTo(player.Position) < 3.2f && ClerkTokens.Any(Models.Name(p).Contains)
				orderby p.Position.DistanceTo(player.Position)
				select p).FirstOrDefault();
		}
		Ped clerkNear = _clerkNear;
		if (clerkNear == null || !clerkNear.Exists() || clerkNear.IsDead || clerkNear.Position.DistanceTo(player.Position) > 3.5f || player.IsInCombat || _menu.IsOpen || _convo != null)
		{
			HideTelegraphPrompt();
			return;
		}
		int num = HUD._UI_PROMPT_GET_GROUP_ID_FOR_TARGET_ENTITY(clerkNear.Handle);
		if (_pTelegraph == 0 || !PromptValid(_pTelegraph) || _pTelegraphFor != clerkNear.Handle || _pTelegraphGroup != num)
		{
			Crumbs.Native("Telegraph prompt delete");
			if (PromptValid(_pTelegraph))
			{
				HUD._UI_PROMPT_DELETE(_pTelegraph);
			}
			int num2 = Enumerable.Count(Telegrams, (Telegram t) => t.Arrived && !t.Read);
			_pTelegraph = MakePrompt((eInputType)1980406895u, (num2 > 0) ? $"Telegraph ({num2} new)" : "Telegraph", hold: true, num);
			_pTelegraphFor = clerkNear.Handle;
			_pTelegraphGroup = num;
		}
		HUD._UI_PROMPT_SET_VISIBLE(_pTelegraph, p1: true);
		HUD._UI_PROMPT_SET_ENABLED(_pTelegraph, p1: true);
		PaperPrompt(clerkNear, num, player);
		if (_paperShown == null)
		{
			if (!HUD._UI_PROMPT_HAS_HOLD_MODE_COMPLETED(_pTelegraph))
			{
				_tgArmed = true;
			}
			else if (_tgArmed)
			{
				_tgArmed = false;
				OpenTelegraph(clerkNear, player);
			}
		}
	}

	private void HideTelegraphPrompt()
	{
		HidePaperPrompt();
		if (_pTelegraph != 0)
		{
			Crumbs.Native("Telegraph prompt delete");
			if (PromptValid(_pTelegraph))
			{
				HUD._UI_PROMPT_DELETE(_pTelegraph);
			}
			_pTelegraph = 0;
			_pTelegraphFor = 0;
		}
	}

	private bool OnTelegraphKey()
	{
		if (_tg != null || _clerkNear == null || !_clerkNear.Exists() || _clerkNear.Position.DistanceTo(Game.Player.Character.Position) > 3.5f)
		{
			return false;
		}
		OpenTelegraph(_clerkNear, Game.Player.Character);
		return true;
	}

	private void OpenTelegraph(Ped clerk, Ped player)
	{
		HideTelegraphPrompt();
		string text = TownAt(player.Position) ?? _currentTown ?? GetZoneName(player.Position) ?? "the station";
		_tg = new TelegraphPanel
		{
			Clerk = clerk,
			Town = text
		};
		int num = Enumerable.Count(Telegrams, (Telegram t) => t.Arrived && !t.Read);
		_tg.Line = ((num > 0) ? $"Wire came in for you - {num} of 'em. Or you sending?" : "Wire's open. Who you sending to?");
		TelegraphRows();
		TASK.TASK_TURN_PED_TO_FACE_ENTITY(clerk.Handle, player.Handle, 2000, 0f, 0f, 0f);
		GrudgeLog($"TELEGRAPH opened at {text} station ({num} unread, {Enumerable.Count(Telegrams, (Telegram t) => !t.Arrived)} on the wire)");
	}

	private void CloseTelegraph()
	{
		_tg = null;
		_panelClosedAt = Game.GameTime;
	}

	private void TelegraphRows()
	{
		TelegraphPanel tg = _tg;
		tg.Rows.Clear();
		tg.Info.Clear();
		if (BuildCivicTelegraphRows(tg)) return;
		switch (tg.Page)
		{
		case "main":
		{
			int num = Enumerable.Count(Telegrams, (Telegram telegram2) => telegram2.Arrived && !telegram2.Read);
			int num2 = Enumerable.Count(Telegrams, (Telegram telegram2) => telegram2.Arrived);
			bool item3 = CashDollars >= 1;
			Row((key: "send", text: "Send a telegram  ($1)", enabled: item3, note: "not enough money"));
			Row((key: "inbox", text: (num2 == 0) ? "Check telegrams" : $"Check telegrams  ({num} new)", enabled: num2 > 0, note: "nothing for you"));
			Row((key: "sentlist", text: "Recently sent", enabled: Telegrams.Any((Telegram telegram2) => !telegram2.Spontaneous), note: "nothing sent yet"));
			int num3 = Enumerable.Count(Telegrams, (Telegram telegram2) => !telegram2.Arrived);
			if (num3 > 0)
			{
				Telegram telegram = (from telegram2 in Telegrams
					where !telegram2.Arrived
					orderby telegram2.ArriveAt
					select telegram2).First();
				Row((key: "wire", text: $"On the wire: {num3} waiting for an answer  -  the next about {GameDate.FromMinutes(telegram.ArriveAt):MMM d}", enabled: false, note: null));
			}
			Row((key: "leave", text: "Leave", enabled: true, note: null));
			AppendCivicTelegraphMainRow();
			break;
		}
		case "to":
		{
			List<NemesisRecord> list = RecipientMen().ToList();
			List<Acquaintance> list2 = RecipientFolk().ToList();
			if (list.Count > 0)
			{
				foreach (NemesisRecord r in list)
				{
					bool flag6 = Telegrams.Any((Telegram telegram2) => !telegram2.Arrived && telegram2.ToId == r.Id);
					var (b3, c, bc3) = OutfitAndRank(r);
					Row((key: "to:n:" + r.Id, text: r.FullName, enabled: !flag6, note: "already on the wire"), new TgInfo
					{
						A = r.FullName,
						B = b3,
						Bc = bc3,
						C = c,
						Cc = Theme.Text,
						D = r.HateTier.ToString(),
						Dc = UiDraw.HateColor(r.HateTier),
						Wait = flag6,
						Detail = RecipientDetail(r, flag6)
					});
				}
			}
			if (list2.Count > 0)
			{
				foreach (Acquaintance a in list2)
				{
					bool flag7 = Telegrams.Any((Telegram telegram2) => !telegram2.Arrived && telegram2.ToId == a.Id);
					var (d3, dc) = FeelingOf(a);
					var (b4, c2, bc4) = OutfitAndRank(a);
					Row((key: "to:p:" + a.Id, text: a.FullName, enabled: !flag7, note: "already on the wire"), new TgInfo
					{
						A = a.FullName,
						B = b4,
						Bc = bc4,
						C = c2,
						Cc = Theme.Text,
						D = d3,
						Dc = dc,
						Wait = flag7,
						Detail = RecipientDetail(a, flag7)
					});
				}
			}
			if (tg.Rows.Count == 0)
			{
				Row((key: "none", text: "Nobody you know well enough to wire", enabled: false, note: null));
			}
			break;
		}
		case "what":
			foreach (TgOption item4 in TelegramOptions(tg.To))
			{
				string text3 = OptionPurpose(item4.Key, tg.To.nemesis);
				bool flag8 = CashDollars >= 1 + item4.Cost;
				bool flag9 = item4.Ok & flag8;
				string text4 = item4.Text;
				string input = item4.Text;
				int num4 = item4.Text.LastIndexOf("\"  - ", StringComparison.Ordinal);
				if (num4 >= 0)
				{
					text4 = item4.Text.Substring(0, num4 + 1);
					input = item4.Text.Substring(num4 + 5);
				}
				input = Regex.Replace(input, ",\\s*\\$\\d+$", "").Trim();
				if (input.Length > 0)
				{
					input = char.ToUpperInvariant(input[0]) + input.Substring(1);
				}
				Row((key: "what:" + item4.Key, text: item4.Text, enabled: flag9, note: (!item4.Ok) ? item4.Note : "not enough money"), new TgInfo
				{
					A = input,
					B = (flag9 ? text4 : ((!item4.Ok) ? item4.Note : "not enough money")),
					Bc = (flag9 ? Theme.Dim : Theme.Faint),
					C = $"${1 + item4.Cost}",
					Cc = ((item4.Cost > 0) ? (r: 215, g: 178, b: 95) : Theme.Dim),
					Right = true,
					Detail = ((text3 == null) ? null : Pron.Her(text3, ToFemale(tg.To)))
				});
			}
			break;
		case "inbox":
			foreach (Telegram t in (from telegram2 in Telegrams
				where telegram2.Arrived
				orderby telegram2.Read, telegram2.ArriveAt descending
				select telegram2).Take(30))
			{
				string d = InboxNote(t);
				bool fem = (t.ToNemesis ? Models.Female(Roster.FirstOrDefault((NemesisRecord nemesisRecord) => nemesisRecord.Id == t.ToId)?.ModelHash ?? 0) : Models.Female(People.FirstOrDefault((Acquaintance acquaintance) => acquaintance.Id == t.ToId)?.Model ?? 0));
				string arg = (t.Spontaneous ? TelegramContext(t, fem) : string.Format("You wrote {0} from {1} on {2:MMM d}", Quote(t.Text), t.From ?? "a station", GameDate.FromMinutes(t.SentAt)));
				string b;
				string text;
				(int, int, int) bc;
				if (!t.ToNemesis)
				{
					(b, text, bc) = OutfitAndRank(People.FirstOrDefault((Acquaintance acquaintance) => acquaintance.Id == t.ToId));
				}
				else
				{
					(b, text, bc) = OutfitAndRank(Roster.FirstOrDefault((NemesisRecord nemesisRecord) => nemesisRecord.Id == t.ToId));
				}
				bool flag3 = CorrespondentDead(t);
				Row((key: "read:" + t.Id, text: "From " + t.ToName, enabled: true, note: null), new TgInfo
				{
					A = t.ToName,
					B = b,
					Bc = bc,
					C = (flag3 ? "Dead" : text),
					Cc = (flag3 ? Theme.Blood : Theme.Text),
					D = d,
					Dc = ((t.Money > 0 && !t.Read) ? (r: 215, g: 178, b: 95) : (t.NoAnswer ? Theme.Faint : (t.Spontaneous ? Theme.Text : Theme.Dim))),
					New = !t.Read,
					Detail = $"Arrived {GameDate.FromMinutes(t.ArriveAt):MMM d}  -  {arg}"
				});
			}
			break;
		case "sent":
			foreach (Telegram t2 in (from telegram2 in Telegrams
				where !telegram2.Spontaneous
				orderby telegram2.SentAt descending
				select telegram2).Take(30))
			{
				string b2;
				string text2;
				(int, int, int) bc2;
				if (!t2.ToNemesis)
				{
					(b2, text2, bc2) = OutfitAndRank(People.FirstOrDefault((Acquaintance acquaintance) => acquaintance.Id == t2.ToId));
				}
				else
				{
					(b2, text2, bc2) = OutfitAndRank(Roster.FirstOrDefault((NemesisRecord nemesisRecord) => nemesisRecord.Id == t2.ToId));
				}
				bool flag4 = CorrespondentDead(t2);
				bool flag5 = t2.Arrived && (t2.Effect == "gone" || (t2.Reply ?? "").StartsWith("WESTERN UNION REGRETS"));
				string d2;
				if (t2.Arrived)
				{
					if (flag5)
					{
						d2 = "Never delivered";
					}
					else
					{
						d2 = (t2.NoAnswer ? "No reply came" : string.Format("Answered {0:MMM d}{1}", GameDate.FromMinutes(t2.ArriveAt), t2.Read ? "" : " - unread"));
					}
				}
				else
				{
					d2 = $"On the wire - due {GameDate.FromMinutes(t2.ArriveAt):MMM d}";
				}
				Row((key: "sent:" + t2.Id, text: t2.ToName, enabled: true, note: null), new TgInfo
				{
					A = t2.ToName,
					B = b2,
					Bc = bc2,
					C = (flag4 ? "Dead" : text2),
					Cc = (flag4 ? Theme.Blood : Theme.Text),
					D = d2,
					Dc = ((!t2.Arrived) ? Theme.Dim : ((flag5 || t2.NoAnswer) ? Theme.Faint : (t2.Read ? Theme.Text : (r: 215, g: 178, b: 95)))),
					Detail = string.Format("You wrote {0} from {1} on {2:MMM d}", Quote(t2.Text), t2.From ?? "a station", GameDate.FromMinutes(t2.SentAt))
				});
			}
			break;
		case "read":
		{
			Telegram rt = tg.Reading;
			bool flag = rt != null && (rt.ToNemesis ? Roster.Any((NemesisRecord nemesisRecord) => nemesisRecord.Id == rt.ToId && nemesisRecord.IsAlive && !nemesisRecord.PresumedDead) : People.Any((Acquaintance acquaintance) => acquaintance.Id == rt.ToId && !acquaintance.Dead));
			bool flag2 = rt != null && Telegrams.Any((Telegram x) => !x.Arrived && x.ToId == rt.ToId);
			bool item = flag && !flag2 && CashDollars >= 1;
			string item2;
			if (flag)
			{
				item2 = (flag2 ? "already on the wire" : "not enough money");
			}
			else
			{
				item2 = "can't be reached";
			}
			Row((key: "reply", text: "Write back  ($1)", enabled: item, note: item2));
			Row((key: "back", text: "Back", enabled: true, note: null));
			break;
		}
		}
		tg.Sel = Math.Max(0, Math.Min(tg.Sel, tg.Rows.Count - 1));
		while (tg.Sel < tg.Rows.Count && !tg.Rows[tg.Sel].enabled && tg.Rows.Any(((string key, string text, bool enabled, string note) tuple8) => tuple8.enabled))
		{
			tg.Sel = (tg.Sel + 1) % tg.Rows.Count;
		}
		void Row((string key, string text, bool enabled, string note) item4, TgInfo info = null)
		{
			tg.Rows.Add(item4);
			tg.Info.Add(info);
		}
	}

	private IEnumerable<NemesisRecord> RecipientMen()
	{
		return (from n in Roster
			where n.IsAlive && !n.PresumedDead && n.Id != null && !IsArmy(n) && (n.Gang == null || n.TimesAmbushed > 0 || n.TimesKilledPlayer > 0 || n.Origin != GrudgeOrigin.GangMember || n.TemperKnown)
			orderby n.LastInteraction descending
			select n).Take(40);
	}

	private IEnumerable<Acquaintance> RecipientFolk()
	{
		return (from a in People
			where a.Met && !a.Dead && a.Id != null && Roster.All((NemesisRecord r) => r.Name != a.Name)
			orderby a.LastSeen descending
			select a).Take(40);
	}

	private static (string, (int r, int g, int b)) FeelingOf(Acquaintance a)
	{
		if (a.Like < 40)
		{
			if (a.Fear < 40)
			{
				if (a.Grudge < 25 || a.GrudgeSettled)
				{
					if (a.Like < 15)
					{
						if (a.Like < 5)
						{
							return ("Neutral", Theme.Dim);
						}
						return ("Warming to you", (160, 180, 145));
					}
					return ("Likes you", (170, 200, 150));
				}
				return ("Holds a grudge", Theme.Warn);
			}
			return ("Afraid of you", (150, 170, 210));
		}
		return ("Likes you a lot", Theme.Good);
	}

	private string TierOf(NemesisRecord r, Gang g)
	{
		if (r.Id != null && r.Id == SuccessorId(g))
		{
			return "Leader";
		}
		string text = OfficerTitle(r);
		if (!string.IsNullOrEmpty(text))
		{
			return text;
		}
		return null;
	}

	private string AgoText(long gm)
	{
		if (gm <= 0)
		{
			return null;
		}
		long num = (GameMinutesNow() - gm) / 1440;
		if (num > 0)
		{
			if (num != 1)
			{
				return $"{num} days ago";
			}
			return "yesterday";
		}
		return "today";
	}

	private string RecipientDetail(NemesisRecord r, bool busy)
	{
		List<string> list = new List<string>();
		if (busy)
		{
			list.Add("Waiting for his answer");
		}
		list.Add(IntentOf(r) switch
		{
			Intent.WontHunt => "Won't come looking", 
			Intent.Hunts => "Hunts you", 
			_ => "Only if you start it", 
		});
		if (r.TemperKnown && r.Personality.HasValue)
		{
			list.Add(r.Personality.Value.ToString());
		}
		if (!string.IsNullOrEmpty(r.KillLocation))
		{
			list.Add("from " + r.KillLocation);
		}
		string text = AgoText(r.LastGameMin);
		if (text != null)
		{
			list.Add("last dealt with " + text);
		}
		return Pron.Her(string.Join("  -  ", list), Models.Female(r.ModelHash));
	}

	private string RecipientDetail(Acquaintance a, bool busy)
	{
		List<string> list = new List<string>();
		if (busy)
		{
			list.Add("Waiting for his answer");
		}
		if (!string.IsNullOrEmpty(a.Temper))
		{
			list.Add(a.Temper);
		}
		if (IsPenPal(a))
		{
			list.Add("Pen pal");
		}
		if (_debugOn)
		{
			list.Add($"like {a.Like} / fear {a.Fear}");
		}
		string text = AgoText(a.LastGameMin);
		if (text != null)
		{
			list.Add("last seen " + text);
		}
		if (a.Favours > 0)
		{
			list.Add("you did him " + ((a.Favours == 1) ? "a favour" : (a.Favours + " favours")));
		}
		if (a.Lookout)
		{
			list.Add("watching for trouble");
		}
		return Pron.Her(string.Join("  -  ", list), Models.Female(a.Model));
	}

	private (string outfit, string rank, (int r, int g, int b) c) OutfitAndRank(NemesisRecord r)
	{
		if (r == null)
		{
			return (outfit: "", rank: "", c: Theme.Dim);
		}
		Gang gang = ((r.Gang != null) ? Gangs.ById(r.Gang) : null);
		if (gang == null)
		{
			return (outfit: "Rides alone", rank: "Loner", c: Theme.Dim);
		}
		return (outfit: gang.Name, rank: TierOf(r, gang) ?? "Member", c: gang.Accent);
	}

	private bool CorrespondentDead(Telegram t)
	{
		if (t.ToNemesis)
		{
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord x) => x.Id == t.ToId);
			if (nemesisRecord != null)
			{
				if (nemesisRecord.IsAlive)
				{
					return nemesisRecord.PresumedDead;
				}
				return true;
			}
			return false;
		}
		Acquaintance acquaintance = People.FirstOrDefault((Acquaintance x) => x.Id == t.ToId);
		if (acquaintance != null)
		{
			return acquaintance.Dead;
		}
		NemesisRecord nemesisRecord2 = Roster.FirstOrDefault((NemesisRecord x) => x.Name == t.ToName);
		if (nemesisRecord2 != null)
		{
			if (nemesisRecord2.IsAlive)
			{
				return nemesisRecord2.PresumedDead;
			}
			return true;
		}
		return false;
	}

	private (string outfit, string rank, (int r, int g, int b) c) OutfitAndRank(Acquaintance a)
	{
		if (a != null)
		{
			return (outfit: a.Town ?? "Met on the road", rank: "Townsfolk", c: Theme.Dim);
		}
		return (outfit: "", rank: "", c: Theme.Dim);
	}

	private static string OptionPurpose(string key, bool nemesis)
	{
		if (nemesis)
		{
			switch (key)
			{
			case "peace":
				return "Asks him to let it go. A scared or tired man may take it and ease off; a proud or hot-headed one gets angrier.";
			case "sorry":
				return "Owns up to it. If he takes it he eases off, and his outfit thinks a little better of you.";
			case "money":
				return "$10 for his trouble - a small softening, more for a greedy man. Proud men send it back. Each one this week is worth less.";
			case "payoff":
				return "$25 to call it square. Greedy, poor or scared men may take it and ease right off; if not, the money comes back.";
			case "threat":
				return "Tries to scare him off. Cowards back away; braver men get angrier.";
			case "coming":
				return "Tells him you're on your way. Scares a coward; makes a braver man ready for you.";
			case "taunt":
				return "Mocks him. A proud man or a hothead takes it hard; others shrug it off.";
			case "family":
				return "Threatens his family. Terrifies a frightened man - and enrages a brave one.";
			case "boss":
				return "Asks where his boss rides from. A greedy, scared or disloyal man may give the camp away.";
			case "distrust":
				return "Says his boss is selling him out. A disloyal or ambitious man may turn on him.";
			case "kin":
				return "Gloats about the relative you killed. Pure hate - or grief, if he's scared enough.";
			case "wish":
				return "No hard feelings. Plain men soften a little; proud men and hotheads scorn it.";
			case "condole":
				return "Condolences for someone he lost. He eases off - a loyal man most of all.";
			case "gift":
				return "$25 for his outfit's leader. A greedy leader takes it gladly; a proud one sends it back. Can lower your notoriety with them.";
			}
		}
		else
		{
			switch (key)
			{
			case "regards":
				return "Keeps you on good terms - he'll like you a little more.";
			case "news":
				return "Asks what's going on round his way - fights, men with a grudge, the talk of the town.";
			case "asking":
				return "Finds out if anyone's been asking after you in his town.";
			case "thanks":
				return "Thanks him for what he did - he'll like you more.";
			case "drink":
				return "$2 for a drink on you - he'll like you more, unless he holds a grudge.";
			case "loan":
				return "Asks him to wire you $10. A friend who owes you may; others won't - and it costs a little goodwill.";
			case "lookout":
				return "Asks him to watch for trouble - if he agrees, he'll wire you when a nemesis turns up near him.";
			case "sorry":
				return "Apologises - eases a grudge and some of his fear.";
			case "checkin":
				return "A friendly word - he'll like you a little more and hold a little less against you.";
			case "letter":
				return "A proper letter - if he likes you he writes back with his own news. Write too often and he tires of it.";
			case "pgift":
				return "$5 for him - he'll like you more. A proud man may send it back.";
			case "pcondole":
				return "Condolences for a friend he lost - unless he knows it was you.";
			case "warn":
				return "Warns him to keep quiet about what he saw. He's more afraid of you and less likely to tell the law - but he'll like you less.";
			}
		}
		return null;
	}

