	private static string Quote(string text)
	{
		if (string.IsNullOrEmpty(text))
		{
			return "";
		}
		int num = text.LastIndexOf("\"  - ", StringComparison.Ordinal);
		if (num < 0)
		{
			return text;
		}
		return text.Substring(0, num + 1);
	}

