	internal bool CampHeldOff(string siteId)
	{
		if (siteId != null && _campHeldOff.TryGetValue(siteId, out var value))
		{
			return Game.GameTime < value;
		}
		return false;
	}

	internal static bool IsTestSite(string id)
	{
		if (id != null)
		{
			if (!id.StartsWith("look_") && !id.StartsWith("debug_camp_"))
			{
				return id == "debug_kit";
			}
			return true;
		}
		return false;
	}

	private void AddTestCampBlip(CampSite site, Gang g, NemesisRecord boss, Vector3? at = null)
	{
		RemoveTestCampBlip(site.Id);
		Vector3 vector = at ?? Kit.Centre(site);
		Crumbs.Native("test camp blip add");
		int num = MAP.BLIP_ADD_FOR_COORDS(2339406903u, vector.X, vector.Y, vector.Z);
		if (num != 0)
		{
			MAP.SET_BLIP_SPRITE(num, MISC.GET_HASH_KEY("blip_region_hideout"), p2: true);
			string text = ((g != null) ? (MemberWord(g) + " ") : "") + "Camp" + ((boss != null) ? (" - " + (OfficerTitle(boss) + " " + boss.Name).Trim()) : "") + " (test)";
			Function.Call(11290983183885202434uL, num, new InputArgument(UiDraw.ForeverVarString(text)));
			_testCampBlips[site.Id] = num;
		}
	}

	internal unsafe void RemoveTestCampBlip(string siteId)
	{
		if (siteId != null && _testCampBlips.TryGetValue(siteId, out var value))
		{
			_testCampBlips.Remove(siteId);
			Crumbs.Native("test camp blip remove");
			if (MAP.DOES_BLIP_EXIST(value))
			{
				MAP.REMOVE_BLIP(&value);
			}
		}
	}

	internal void DebugCampLookAtNearest(Ped player, Gang g)
	{
		Vector3 pos = player.Position;
		CampSite campSite = (from x in Camps.AllSites
			where !x.Hideout
			orderby pos.DistanceTo2D(new Vector3(x.X, x.Y, x.Z))
			select x).FirstOrDefault();
		float num = ((campSite == null) ? float.MaxValue : pos.DistanceTo2D(new Vector3(campSite.X, campSite.Y, campSite.Z)));
		DespawnTestCamps();
		if (num > 250f)
		{
			Vector3 vector = pos + player.ForwardVector * 20f;
			campSite = new CampSite("here_" + Game.GameTime, 0u, vector.X, vector.Y, vector.Z, CurrentDistrict?.Name ?? "here", hideout: false, null, g.Id);
			GrudgeLog("CAMPLOOK no camp site within 250 m" + ((num < float.MaxValue) ? $" (nearest {num:0} m)" : "") + " - the " + g.Name + " camp goes 20 m ahead of you");
			num = 20f;
		}
		if (_liveCamps.TryGetValue(campSite.Id, out var value))
		{
			DespawnCamp(value, delete: true);
		}
		if (!campSite.Id.StartsWith("here_"))
		{
			_campHeldOff[campSite.Id] = int.MaxValue;
		}
		CampSite campSite2 = new CampSite("look_" + campSite.Id, 0u, campSite.X, campSite.Y, campSite.Z, campSite.Region, hideout: false, null, g.Id);
		Kit.ForgetCentre(campSite2.Id);
		NemesisRecord nemesisRecord = (_lookPropsOnly ? null : (from n in Roster
			where n.Gang == g.Id && n.IsAlive && !n.PresumedDead && n.Rank >= 2 && OffStage(n)
			orderby n.Rank descending
			select n).FirstOrDefault());
		if (nemesisRecord == null)
		{
			Kit.Spawn(campSite2, g.Id, IsSupplyCamp(campSite2));
			AddTestCampBlip(campSite2, g, null);
			string text = (_lookPropsOnly ? "props only" : "props only - no officer of theirs free");
			GrudgeLog("CAMPLOOK " + campSite.Id + ": the " + g.Name + " look, " + text);
			SpawnerSays($"the {g.Name} camp at {campSite.Region} ({num:0} m) - {text}, marked on your map. 'Despawn' takes it away.");
		}
		else
		{
			SpawnCamp(campSite2, nemesisRecord, player);
			AddTestCampBlip(campSite2, g, nemesisRecord);
			GrudgeLog("CAMPLOOK " + campSite.Id + ": the " + g.Name + " under " + nemesisRecord.Name);
			SpawnerSays($"a {g.Name} camp under {nemesisRecord.Name} at {campSite.Region} ({num:0} m), marked on your map. 'Despawn' takes it away.");
		}
	}

	private int DespawnTestCamps()
	{
		int num = 0;
		foreach (LiveCamp item in _liveCamps.Values.Where((LiveCamp c) => c.Site.Id.StartsWith("look_") || c.Site.Id.StartsWith("debug_camp_")).ToList())
		{
			DespawnCamp(item, delete: true);
			num++;
		}
		foreach (string item2 in Kit.Keys.Where((string k) => k.StartsWith("look_") || k == "debug_kit").ToList())
		{
			DespawnCampKit(item2);
			num++;
		}
		foreach (string item3 in _campHeldOff.Keys.ToList())
		{
			if (_campHeldOff[item3] == int.MaxValue)
			{
				_campHeldOff[item3] = Game.GameTime + 180000;
			}
		}
		return num;
	}

	private void TidyTestKits(Vector3 me)
	{
		foreach (string item in Kit.Keys.Where((string k) => IsTestSite(k) && !_liveCamps.ContainsKey(k)).ToList())
		{
			Vector3? vector = Kit.FirstSpot(item);
			if (!vector.HasValue || vector.GetValueOrDefault().DistanceTo2D(me) <= 260f)
			{
				continue;
			}
			DespawnCampKit(item);
			if (item.StartsWith("look_"))
			{
				string key = item.Substring("look_".Length);
				if (_campHeldOff.TryGetValue(key, out var value) && value == int.MaxValue)
				{
					_campHeldOff[key] = Game.GameTime + 180000;
				}
			}
			GrudgeLog("CAMPLOOK " + item + ": you rode off - the test camp is gone");
		}
	}

	internal void DebugDespawnCamp(Ped player)
	{
		int num = DespawnTestCamps();
		if (num > 0)
		{
			GrudgeLog($"CAMPLOOK despawned {num} test camp(s)");
			ShowNotification("enRAGE: test camp taken away.");
			return;
		}
		Vector3 pos = player.Position;
		LiveCamp liveCamp = _liveCamps.Values.OrderBy((LiveCamp c) => pos.DistanceTo(SitePos(c.Site))).FirstOrDefault();
		if (liveCamp == null)
		{
			ShowNotification("enRAGE: no camp is up near you.");
			return;
		}
		string id = liveCamp.Site.Id;
		DespawnCamp(liveCamp, delete: true);
		_campHeldOff[id] = Game.GameTime + 180000;
		GrudgeLog("CAMPLOOK despawned " + id + " (held off 3 minutes)");
		ShowNotification("enRAGE: " + liveCamp.Site.Label + " taken away - it won't come back for 3 minutes.");
	}

	internal static void FixLore(List<LoreRow> rows)
	{
		if (rows == null)
		{
			return;
		}
		foreach (LoreRow row in rows)
		{
			if (row != null)
			{
				if (row.Title == "The Blackwater ferry job" && (row.Year != 1899 || row.Month != 2))
				{
					row.Year = 1899;
					row.Month = 2;
					row.YearsAgo = 0;
				}
				if (row.Title == "The O'Driscoll - Van der Linde feud" && row.Year != 1889)
				{
					row.Year = 1889;
					row.YearsAgo = 0;
					row.When = "About 1889";
				}
			}
		}
	}

	private void ValidateTimeline()
	{
		if (StoryBuildError != null)
		{
			GrudgeLog("STORY gang failed to build: " + StoryBuildError);
		}
		else
		{
			GrudgeLog($"STORY Van der Linde gang: {StoryRoster.Count} people");
		}
		int num = GameYear();
		int num2 = GameMonth();
		int num3 = 0;
		int num4 = 0;
		int num5 = 0;
		int num6 = 0;
		foreach (NemesisRecord item in Roster.Concat(StoryRoster))
		{
			NemesisRecord r = item;
			if (r.Past == null || r.BornYear <= 0)
			{
				continue;
			}
			int count = r.Past.Count;
			List<PastEntry> list = r.Past.Where(Bad).ToList();
			foreach (PastEntry item2 in list)
			{
				GrudgeLog(string.Format("TIMELINE {0} (born {1}): dropped '{2}' ({3}{4}, {5})", r.Name, r.BornYear, item2.Text, item2.Year, (item2.Month > 0) ? ("/" + item2.Month) : "", item2.Kind));
			}
			r.Past.RemoveAll(list.Contains);
			if (r.Past.Count != count)
			{
				num3++;
				num4 += count - r.Past.Count;
			}
			bool Bad(PastEntry e)
			{
				if (e.Year <= 0)
				{
					return false;
				}
				if (e.Year < r.BornYear)
				{
					return true;
				}
				if (r.Story)
				{
					return false;
				}
				if (!Grown(e.Kind) || e.Year >= r.BornYear + 14)
				{
					if (e.Kind == "war")
					{
						return e.Year < r.BornYear + 15;
					}
					return false;
				}
				return true;
			}
		}
		foreach (WorldEvent ev in Chronicle.Past ?? new List<WorldEvent>())
		{
			if (ev.Title == "The Blackwater ferry job" && ev.Day / 10000 != 1899)
			{
				DateTime d = new DateTime(1899, 2, 10, 22, 0, 0);
				ev.GameMin = GameDate.ToMinutes(d);
				ev.Day = 18990110;
				ev.When = "Feb 1899";
				num6++;
			}
			int num7 = ev.Day / 10000;
			foreach (WorldPart p in ev.People.ToList())
			{
				NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == p.Id);
				if (nemesisRecord != null && nemesisRecord.BornYear > 0 && num7 < nemesisRecord.BornYear + 14)
				{
					ev.People.Remove(p);
					nemesisRecord.Past?.RemoveAll((PastEntry e) => e.WorldId == ev.Id);
					num5++;
					GrudgeLog($"TIMELINE {nemesisRecord.Name} (born {nemesisRecord.BornYear}) was too young for '{ev.Title}' ({num7}) - taken out of it");
				}
			}
		}
		if (num3 + num5 + num6 > 0)
		{
			SaveRoster();
			SaveWorld();
		}
		GrudgeLog($"TIMELINE checked {Roster.Count + StoryRoster.Count} lives and {Chronicle.Past?.Count ?? 0} past events for {num}/{num2}: " + $"{num4} lines dropped from {num3} lives, {num5} men taken out of events too early for them, {num6} lore dates fixed");
		static bool Grown(string kind)
		{
			switch (kind)
			{
			default:
				return kind == "weave";
			case "gang":
			case "rank":
			case "crime":
			case "work":
			case "war":
			case "world":
				return true;
			}
		}
	}

	private void HealFutureTimeline(long now)
	{
		List<long> list = new List<long>();
		foreach (NemesisRecord item in Roster)
		{
			list.Add(Math.Max(item.LastGameMin, item.LastCameAt));
		}
		foreach (Acquaintance person in People)
		{
			list.Add(person.LastGameMin);
		}
		foreach (WorldEvent @event in Chronicle.Events)
		{
			list.Add(@event.GameMin);
		}
		list = (from x in list
			where x > 0
			orderby x descending
			select x).ToList();
		if (list.Count != 0)
		{
			long num = list[Math.Min(9, list.Count - 1)];
			if (num - now >= 1440)
			{
				GrudgeLog($"TIMESHIFT the world is ahead of your clock: newest {GameDate.FromMinutes(num):MMM d HH:mm}, clock {GameDate.FromMinutes(now):MMM d HH:mm}");
				ShiftTimeline(now - num, "the world was ahead of this save's clock");
				ShowNotification("enRAGE: the world was ahead of this save's clock - its timers moved back to fit.");
			}
		}
	}

	private void ShiftTimeline(long delta, string why)
	{
		if (delta == 0L)
		{
			return;
		}
		int n = 0;
		foreach (NemesisRecord item in Roster)
		{
			item.RestUntil = S(item.RestUntil);
			item.LastCameAt = S(item.LastCameAt);
			item.LastGameMin = S(item.LastGameMin);
			item.SocialDoneAt = S(item.SocialDoneAt);
			item.BargainAt = S(item.BargainAt);
			item.InformedDay = D(item.InformedDay);
			if (item.Thoughts != null)
			{
				foreach (Thought thought in item.Thoughts)
				{
					thought.At = S(thought.At);
					thought.Until = S(thought.Until);
				}
			}
			if (item.Memories != null)
			{
				foreach (Memory memory in item.Memories)
				{
					memory.At = S(memory.At);
				}
			}
			if (item.Goals == null)
			{
				continue;
			}
			foreach (Goal goal in item.Goals)
			{
				goal.Since = S(goal.Since);
			}
		}
		WorldState chronicle = Chronicle;
		chronicle.NextEventAt = S(chronicle.NextEventAt);
		chronicle.StoryChapterAt = S(chronicle.StoryChapterAt);
		chronicle.FortClearedAt = S(chronicle.FortClearedAt);
		chronicle.LastFearFadeDay = D(chronicle.LastFearFadeDay);
		foreach (WorldEvent @event in chronicle.Events)
		{
			@event.GameMin = S(@event.GameMin);
			@event.AftermathUntil = S(@event.AftermathUntil);
			@event.Day = D(@event.Day);
		}
		foreach (Plan item2 in chronicle.Plans ?? new List<Plan>())
		{
			item2.DueAt = S(item2.DueAt);
		}
		foreach (DeathNews item3 in (chronicle.DeathNews ?? new List<DeathNews>()).Concat(chronicle.PeopleNews ?? new List<DeathNews>()))
		{
			item3.At = S(item3.At);
			item3.DueAt = S(item3.DueAt);
		}
		foreach (Telegram item4 in chronicle.Telegrams ?? new List<Telegram>())
		{
			item4.SentAt = S(item4.SentAt);
			item4.ArriveAt = S(item4.ArriveAt);
		}
		foreach (PenPal value in (chronicle.PenPals ?? new Dictionary<string, PenPal>()).Values)
		{
			value.LastAt = S(value.LastAt);
		}
		if (chronicle.CompanionHurt != null)
		{
			foreach (string item5 in chronicle.CompanionHurt.Keys.ToList())
			{
				chronicle.CompanionHurt[item5] = S(chronicle.CompanionHurt[item5]);
			}
		}
		if (chronicle.Leaders != null)
		{
			foreach (LeaderSeat value2 in chronicle.Leaders.Values)
			{
				if (value2 != null)
				{
					value2.At = S(value2.At);
					value2.FillAt = S(value2.FillAt);
				}
			}
		}
		if (chronicle.NotorietyGainDay != null)
		{
			foreach (string item6 in chronicle.NotorietyGainDay.Keys.ToList())
			{
				chronicle.NotorietyGainDay[item6] = D(chronicle.NotorietyGainDay[item6]);
			}
		}
		if (chronicle.TownWord != null)
		{
			foreach (TownTalk value3 in chronicle.TownWord.Values)
			{
				if (value3 != null)
				{
					value3.LastWordDay = D(value3.LastWordDay);
				}
			}
		}
		if (chronicle.Destroyed != null)
		{
			foreach (string item7 in chronicle.Destroyed.Keys.ToList())
			{
				chronicle.Destroyed[item7] = S(chronicle.Destroyed[item7]);
			}
		}
		if (chronicle.WarEndedAt != null)
		{
			foreach (string item8 in chronicle.WarEndedAt.Keys.ToList())
			{
				chronicle.WarEndedAt[item8] = S(chronicle.WarEndedAt[item8]);
			}
		}
		if (chronicle.Agendas != null)
		{
			foreach (Agenda value4 in chronicle.Agendas.Values)
			{
				value4.SetAt = S(value4.SetAt);
				value4.ReviewAt = S(value4.ReviewAt);
			}
		}
		if (chronicle.Beaten != null)
		{
			foreach (string item9 in chronicle.Beaten.Keys.ToList())
			{
				chronicle.Beaten[item9] = S(chronicle.Beaten[item9]);
			}
		}
		if (chronicle.CampTakeovers != null)
		{
			foreach (CampTakeover value5 in chronicle.CampTakeovers.Values)
			{
				value5.DueAt = S(value5.DueAt);
			}
		}
		chronicle.WildFreshAt = S(chronicle.WildFreshAt);
		chronicle.LastWarStartAt = S(chronicle.LastWarStartAt);
		if (chronicle.SleepRollWindow >= 0)
		{
			chronicle.SleepRollWindow = S(chronicle.SleepRollWindow * 720) / 720;
		}
		if (chronicle.Wars != null)
		{
			foreach (WarRecord war in chronicle.Wars)
			{
				war.StartMin = S(war.StartMin);
				war.LastReportDay = D(war.LastReportDay);
				war.LastBattleAt = S(war.LastBattleAt);
				war.BattleDay = D(war.BattleDay);
			}
		}
		if (chronicle.PastWars != null)
		{
			foreach (WarRecord pastWar in chronicle.PastWars)
			{
				pastWar.StartMin = S(pastWar.StartMin);
				pastWar.EndMin = S(pastWar.EndMin);
			}
		}
		chronicle.Truces = ShiftLast(chronicle.Truces);
		chronicle.Alliances = ShiftLast(chronicle.Alliances);
		foreach (Acquaintance person in People)
		{
			person.LastGameMin = S(person.LastGameMin);
			person.LastScaredMin = S(person.LastScaredMin);
		}
		foreach (string item10 in _cardUsedAt.Keys.ToList())
		{
			_cardUsedAt[item10] = S(_cardUsedAt[item10]);
		}
		try
		{
			n += _bulletImpact.ShiftGameMinutes(delta);
		}
		catch
		{
		}
		foreach (Print value6 in Prints.Values)
		{
			value6.LastGameMin = S(value6.LastGameMin);
		}
		Config.LastSuccessionDay = D(Config.LastSuccessionDay);
		Config.NextSuccessionDay = D(Config.NextSuccessionDay);
		if (Chronicle.NextShakeUp != null)
		{
			foreach (string item11 in Chronicle.NextShakeUp.Keys.ToList())
			{
				Chronicle.NextShakeUp[item11] = D(Chronicle.NextShakeUp[item11]);
			}
		}
		Config.LastDecayDay = D(Config.LastDecayDay);
		if (!string.IsNullOrEmpty(Config.ClearedCamps))
		{
			Config.ClearedCamps = string.Join(",", Config.ClearedCamps.Split(',').Select((string e) =>
			{
				int num = e.LastIndexOf(':');
				int result;
				return (num <= 0 || !int.TryParse(e.Substring(num + 1), out result)) ? e : (e.Substring(0, num + 1) + D(result));
			}));
		}
		_cleared = null;
		_lastMurderousAt = S(_lastMurderousAt);
		_lastMindHour = -1L;
		_lastMindDay = -1L;
		_nextUnaskedAt = 0L;
		try
		{
			Config.Save();
		}
		catch
		{
		}
		SaveRoster();
		SaveWorld();
		_peopleDirty = true;
		_printsDirty = true;
		GrudgeLog($"TIMESHIFT {n} timers moved {(double)delta / 60.0:+0.#;-0.#} h ({why}) - rest, cooldowns, news, telegrams, plans, world events, shake-up dates");
		int D(int key)
		{
			if (key <= 0)
			{
				return key;
			}
			try
			{
				n++;
				return GameDate.DayKey(GameDate.FromDayKey(key).AddMinutes(delta));
			}
			catch
			{
				return key;
			}
		}
		long S(long t)
		{
			if (t <= 0)
			{
				return t;
			}
			n++;
			return t + delta;
		}
		List<string> ShiftLast(List<string> list)
		{
			return list?.Select((string e) =>
			{
				int num = e.LastIndexOf('|');
				long result;
				return (num <= 0 || !long.TryParse(e.Substring(num + 1), out result)) ? e : (e.Substring(0, num + 1) + S(result));
			}).ToList();
		}
	}

	private void TrackTownVisit()
	{
		if (_currentTown == _visitTown)
		{
			_visitLeftAt = -1;
			return;
		}
		if (_currentTown == null && _visitTown != null)
		{
			if (_visitLeftAt < 0)
			{
				_visitLeftAt = Game.GameTime;
			}
			if (Game.GameTime - _visitLeftAt < 60000)
			{
				return;
			}
		}
		_visitLeftAt = -1;
		if (_currentTown != null)
		{
			GrudgeLog("TOWNCALM new visit: " + _currentTown);
		}
		_visitTown = _currentTown;
		_visitStartedAt = Game.GameTime;
		_arrivalRetried.Clear();
		_visitAggressors = 0;
		_visitLastFightAt = -1000000;
		_visitSecondRolled = false;
	}

	private bool TakeAggressorSlot(out string why)
	{
		if (_visitAggressors == 0)
		{
			_visitAggressors = 1;
			why = "first this visit";
			return true;
		}
		if (_visitAggressors >= 2)
		{
			why = "two already this visit";
			return false;
		}
		if (_townMen.Any((TownMan t) => t.Engaged) || (_enc != null && _enc.Kind == EncounterKind.Callout))
		{
			why = "one is still on";
			return false;
		}
		int num = Balance.TownQuietAfterFight * 1000 - (Game.GameTime - _visitLastFightAt);
		if (num > 0)
		{
			why = $"quiet for {num / 1000}s more";
			return false;
		}
		if (_visitSecondRolled)
		{
			why = "the second chance was rolled already";
			return false;
		}
		_visitSecondRolled = true;
		int num2 = _rng.Next(100);
		bool flag = num2 < Balance.TownSecondAggressorPct;
		GrudgeLog(string.Format("TOWNCALM second aggressor in {0}: {1}%, rolled {2} -> {3}", _visitTown, Balance.TownSecondAggressorPct, num2, flag ? "yes" : "no"));
		if (flag)
		{
			_visitAggressors = 2;
		}
		why = (flag ? "a rare second" : "no second this visit");
		return flag;
	}

	private void NoteTownFightOver()
	{
		_visitLastFightAt = Game.GameTime;
	}

	internal (int chance, string why) WaitOutsideChance(NemesisRecord r)
	{
		List<string> parts = new List<string>();
		int c = Balance.TownWaitOutsideBase;
		switch (r.Personality)
		{
		case Personality.Cold:
			Add(25, "cold");
			break;
		case Personality.Coward:
			Add(25, "coward");
			break;
		case Personality.Loyal:
			Add(10, "loyal");
			break;
		case Personality.Drifter:
			Add(10, "drifter");
			break;
		case Personality.Greedy:
			Add(5, "greedy");
			break;
		case Personality.Proud:
			Add(-20, "proud");
			break;
		case Personality.Hothead:
			Add(-30, "hothead");
			break;
		}
		if (r.MindRolled)
		{
			Add(-(Mind.F(r, "Anger") - 50) / 2, "anger");
			Add((50 - Mind.F(r, "Bravery")) / 3, "bravery");
			Add(-(Mind.F(r, "Pride") - 50) / 4, "pride");
			Add(Mind.V(r, "Law") * 4, "the law");
			if (r.Stress >= 70)
			{
				Add(-10, "on edge");
			}
			if (Mind.HasAgainstYou(r, "Prove"))
			{
				Add(-10, "wants to prove it");
			}
			if (Mind.HasAgainstYou(r, "Avenge"))
			{
				Add(-5, "wants it now");
			}
		}
		if (r.TimesKilledPlayer > 0)
		{
			Add(-5, "killed you before");
		}
		c = Math.Max(5, Math.Min(90, c));
		return (chance: c, why: string.Join(", ", parts));
		void Add(int v, string w)
		{
			if (v != 0)
			{
				c += v;
				parts.Add($"{w} {v:+0;-0}");
			}
		}
	}

	private bool RollWaitOutside(NemesisRecord rec, string town, Ped ped, Ped player, bool callout = false)
	{
		if (rec == null || _roadAmbush != null || rec.HateTier != HateTier.Murderous)
		{
			return false;
		}
		if (ped != null && ped.Exists() && (ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(ped.Handle, player.Handle, p2: true, p3: true) || PED.IS_PED_IN_COMBAT(ped.Handle, player.Handle) || (_hitByYouAt.TryGetValue(ped.Handle, out var value) && Game.GameTime - value < 60000)))
		{
			GrudgeLog("TOWNCALM " + rec.Name + ": no taking it outside - you've already hurt him / he's fighting you");
			return false;
		}
		(int chance, string why) tuple = WaitOutsideChance(rec);
		int item = tuple.chance;
		string item2 = tuple.why;
		int num = _rng.Next(100);
		bool flag = num < item;
		GrudgeLog(string.Format("TOWNCALM {0} saw you in {1}: wait outside {2}% ({3}), rolled {4} -> {5}", rec.Name, town, item, item2, num, flag ? "he'll wait on the road" : (callout ? "he'll do it here" : "he stays put, holding it")));
		Feed(string.Format("TOWN {0}: take it outside? {1}%, rolled {2} -> {3}", rec.Name, item, num, flag ? "he walks off - he'll be waiting" : (callout ? "here and now" : "he stays put")), flag ? Theme.Warn : Theme.Blood, rec);
		if (!flag)
		{
			return false;
		}
		string text;
		if (rec.Personality == Personality.Coward)
		{
			text = "...Not here. Not with the law about.";
		}
		else if (rec.Personality == Personality.Cold)
		{
			text = "Not here. Too many eyes.";
		}
		else
		{
			text = ((rec.Personality == Personality.Loyal) ? "Not in town. You'll keep." : "Not here. You ride out of this town - I'll be waiting.");
		}
		ShowSubtitle(rec.Name + ": \"" + text + "\"");
		if (ped != null && ped.Exists())
		{
			_toldToFlee[ped.Handle] = Game.GameTime;
		}
		if (ped != null && ped.Exists())
		{
			TASK.CLEAR_PED_TASKS(ped.Handle, p1: true, p2: true);
			TASK.TASK_TURN_PED_TO_FACE_ENTITY(ped.Handle, player.Handle, 2500, 0f, 0f, 0f);
			TASK.TASK_WANDER_STANDARD(ped.Handle, 10f, 10);
		}
		_roadAmbush = new RoadAmbush
		{
			Rec = rec,
			Town = town,
			Until = Game.GameTime + Balance.RoadAmbushMinutes * 60000
		};
		History(rec, "SAW YOU IN " + town.ToUpperInvariant() + " - and went to wait for you on the road out", Theme.Warn);
		Remember(rec, "Anger", 40, "let you walk through " + town);
		rec.Touch();
		SaveRoster();
		return true;
	}

	private void UpdateRoadAmbush(Ped player)
	{
		RoadAmbush ra = _roadAmbush;
		if (ra == null)
		{
			return;
		}
		Vector3 centre;
		float radius;
		if (Game.GameTime > ra.Until || !ra.Rec.IsAlive || ra.Rec.PresumedDead || !Roster.Contains(ra.Rec) || !HasReason(ra.Rec))
		{
			GrudgeLog("TOWNCALM " + ra.Rec.Name + " gave up waiting outside " + ra.Town);
			_roadAmbush = null;
		}
		else if (_currentTown != null || !TownCore(ra.Town, out centre, out radius) || !(player.Position.DistanceTo2D(centre) > radius + 120f))
		{
			ra.SpawnAt = -1;
		}
		else
		{
			if (_enc != null || _menu.IsOpen || NoSpawnReason(player) != null)
			{
				return;
			}
			if (TownCore(ra.Town, out var centre2, out var radius2) && player.Position.DistanceTo2D(centre2) > radius2 + 1500f)
			{
				GrudgeLog("TOWNCALM " + ra.Rec.Name + " waited outside " + ra.Town + ", but you never rode out that way");
				_roadAmbush = null;
			}
			else if (ra.SpawnAt < 0)
			{
				ra.SpawnAt = Game.GameTime + 15000 + _rng.Next(35000);
			}
			else
			{
				if (Game.GameTime < ra.SpawnAt)
				{
					return;
				}
				foreach (int item in (from kv in _worldNemeses
					where kv.Value == ra.Rec
					select kv.Key).ToList())
				{
					Ped ped = Entity.FromHandle(item) as Ped;
					if (ped != null && ped.Exists() && ped.Position.DistanceTo(player.Position) < 120f)
					{
						return;
					}
					if (ped != null && ped.Exists() && SafeToDelete(ped))
					{
						ped.Delete();
					}
					_worldNemeses.Remove(item);
				}
				bool flag = PED.IS_PED_ON_MOUNT(player.Handle);
				string stage = (flag ? "ahead" : "idle");
				EncounterCard encounterCard = Cards.FirstOrDefault((EncounterCard c) => c.Enabled && c.Id == stage) ?? BuiltInCards().First((EncounterCard c) => c.Id == stage);
				_roadAmbush = null;
				GrudgeLog("TOWNCALM " + ra.Rec.Name + " was waiting outside " + ra.Town + ": " + stage);
				History(ra.Rec, "WAITED FOR YOU outside " + ra.Town, Theme.Blood);
				Feed("ENCOUNTER " + ra.Rec.Name + " was waiting for you outside " + ra.Town, Theme.Blood, ra.Rec);
				SpawnEncounter(ra.Rec, StageKind(encounterCard.Stage), player, encounterCard);
				if (ActiveRecord != ra.Rec)
				{
					GrudgeLog("TOWNCALM " + ra.Rec.Name + "'s road ambush failed to spawn (" + encounterCard.Id + ") - dropped");
				}
			}
		}
	}

	private TownMan TownManFor(int handle)
	{
		return _townMen.FirstOrDefault((TownMan t) => t.Ped != null && t.Ped.Exists() && t.Ped.Handle == handle);
	}

	private void OnEnterTownPresence(string town, Ped player)
	{
		if (NoSpawnReason(player) != null)
		{
			_heldTownEntry = town;
			return;
		}
		if (!InTownForArrivals(player, town))
		{
			_heldTownEntry = town;
			GrudgeLog("TOWN arrival in " + town + " waits - you're at the edge of its zone");
			return;
		}
		if (_townCooldown.TryGetValue(town, out var value) && Game.GameTime < value)
		{
			int num = 0;
			_townArrivals.Clear();
			_townArrivalsFor = town;
			_arrivalStep = 0f;
			_lastArrivalAt = Game.GameTime;
			_nextTownArrival = Game.GameTime + 2000 + _rng.Next(4000);
			if (_townLastMen.TryGetValue(town, out var value2))
			{
				foreach (string id in value2.ToList())
				{
					if (_townMen.Count >= Balance.TownMaxMen)
					{
						break;
					}
					NemesisRecord rec = Roster.FirstOrDefault((NemesisRecord n) => n.Id == id);
					if (rec != null && rec.IsAlive && !rec.PresumedDead && rec.CanHunt && !IsArmy(rec) && !_worldNemeses.ContainsValue(rec) && rec != ActiveRecord && !_townMen.Any((TownMan t) => t.Rec == rec) && _roadAmbush?.Rec != rec)
					{
						_townArrivals.Add(rec);
						num++;
					}
				}
			}
			GrudgeLog($"TOWN back in {town} within its cooldown ({(value - Game.GameTime) / 1000}s left): {num} of the same men still about, no new arrivals");
			return;
		}
		_townLastMen[town] = new List<string>();
		_regularsToCome = 0;
		for (int num2 = 0; num2 < 3; num2++)
		{
			if ((float)_rng.Next(100) < (float)Config.RegularChance * NightTownMult())
			{
				_regularsToCome++;
			}
		}
		_townCooldown[town] = Game.GameTime + 480000;
		int num3 = Math.Min(Balance.TownMaxMen, _rng.Next(Balance.TownArrivalMin, Balance.TownArrivalMax + 1));
		if (NightTownMult() < 1f)
		{
			num3 = Math.Max(1, num3 / 2);
		}
		List<NemesisRecord> list = (from n in TownCandidates(town, player)
			where TownTierPercent(n) > 0
			select n).ToList();
		_townArrivals.Clear();
		_townArrivalsFor = town;
		_arrivalStep = 0f;
		_lastArrivalAt = Game.GameTime;
		_nextTownArrival = Game.GameTime + 2000 + _rng.Next(4000);
		int num4 = 0;
		while (_townArrivals.Count + _townMen.Count < num3 && list.Count > 0 && num4++ < 20)
		{
			List<NemesisRecord> pool = list;
			if (list.Any((NemesisRecord n) => HomeTown(n, town, player)) && _rng.Next(100) >= Balance.TownPassingPercent)
			{
				pool = list.Where((NemesisRecord n) => HomeTown(n, town, player)).ToList();
			}
			NemesisRecord nemesisRecord = PickTownMan(pool);
			list.Remove(nemesisRecord);
			if (LoreTownRoll(nemesisRecord, town))
			{
				_townArrivals.Add(nemesisRecord);
			}
		}
		if (_townArrivals.Count + _townMen.Count < num3)
		{
			foreach (NemesisRecord item in (from n in TownCandidates(town, player)
				where !_townArrivals.Contains(n) && CoolingOff(n) && n.HateTier != HateTier.Murderous
				orderby HomeTown(n, town, player) descending, _rng.Next()
				select n).ToList())
			{
				if (_townArrivals.Count + _townMen.Count >= num3)
				{
					break;
				}
				if (LoreTownRoll(item, town))
				{
					_townArrivals.Add(item);
					GrudgeLog("TOWN " + item.Name + " came lately, but " + (HomeTown(item, town, player) ? "he lives here" : "he's about") + " - in town again");
				}
			}
		}
		_loadInVisit = Game.GameTime - Math.Max(Math.Max(_loadedAt, _loadScreenAt), _lastJumpAt) < 60000;
		_nextTownArrival = Game.GameTime + 2000 + _rng.Next(4000);
		TryHiddenInTown(town, player);
		GrudgeLog(string.Format("TOWN arrival in {0}: {1} of {2} will turn up as you walk in ({3}; {4} left over)", town, _townArrivals.Count, num3, string.Join(", ", _townArrivals.Select((NemesisRecord r) => r.Name)), list.Count));
		if (_townArrivals.Count < num3)
		{
			GrudgeLog("TOWN pool for " + town + ": " + TownPoolNote(town, player));
		}
	}

	internal bool InTownForArrivals(Ped player, string town)
	{
		if (town != null && TownCore(town, out var centre, out var radius))
		{
			return new Vector3(player.Position.X - centre.X, player.Position.Y - centre.Y, 0f).Length() < radius * 0.95f + 20f;
		}
		return false;
	}

	private void UpdateTownArrivals(Ped player)
	{
		if ((_townArrivals.Count == 0 && _regularsToCome == 0) || Game.GameTime < _nextTownArrival)
		{
			return;
		}
		if (_currentTown != _townArrivalsFor)
		{
			_townArrivals.Clear();
			_regularsToCome = 0;
			return;
		}
		if (NoSpawnReason(player) != null || !InTownForArrivals(player, _currentTown))
		{
			_nextTownArrival = Game.GameTime + 3000;
			return;
		}
		if (Game.GameTime - _quietEndedAt < 8000 || Game.GameTime - _lastJumpAt < 15000)
		{
			_nextTownArrival = Game.GameTime + 1000;
			return;
		}
		if (_arrivalStep > 0f)
		{
			Vector3 position = player.Position;
			bool flag = new Vector3(position.X - _arrivalFrom.X, position.Y - _arrivalFrom.Y, 0f).Length() >= _arrivalStep;
			bool flag2 = Game.GameTime - _lastArrivalAt > (_loadInVisit ? (12 + _rng.Next(10)) : Balance.TownArrivalIdleSeconds) * 1000;
			if ((!flag && !flag2) || Game.GameTime - _lastArrivalAt < 10000)
			{
				_nextTownArrival = Game.GameTime + 1000;
				return;
			}
		}
		if (!Travelling(player, out var dir))
		{
			if (_loadInVisit)
			{
				double num = _rng.NextDouble() * Math.PI * 2.0;
				dir = new Vector3((float)Math.Cos(num), (float)Math.Sin(num), 0f);
			}
			else
			{
				Vector3 direction = GameplayCamera.Direction;
				dir = new Vector3(direction.X, direction.Y, 0f);
			}
		}
		if (dir.Length() > 0.01f)
		{
			dir.Normalize();
			TownToward = player.Position + dir * 70f;
		}
		else
		{
			TownToward = null;
		}
		Vector3? townToward = TownToward;
		if (townToward.HasValue)
		{
			Vector3 valueOrDefault = townToward.GetValueOrDefault();
			if (TownCore(_currentTown, out var centre, out var radius))
			{
				Vector3 vector = new Vector3(valueOrDefault.X - centre.X, valueOrDefault.Y - centre.Y, 0f);
				if (vector.Length() > radius * 0.85f)
				{
					vector.Normalize();
					TownToward = new Vector3(centre.X + vector.X * radius * 0.85f, centre.Y + vector.Y * radius * 0.85f, player.Position.Z);
				}
			}
		}
		_arrivalFrom = player.Position;
		_arrivalStep = Balance.TownArrivalWalkMin + _rng.Next(Math.Max(1, Balance.TownArrivalWalkMax - Balance.TownArrivalWalkMin + 1));
		_lastArrivalAt = Game.GameTime;
		try
		{
			UpdateTownArrivalsSpawn(player);
		}
		finally
		{
			TownToward = null;
		}
	}

	private void UpdateTownArrivalsSpawn(Ped player)
	{
		if (_regularsToCome > 0 && (_townArrivals.Count == 0 || _rng.Next(2) == 0))
		{
			_regularsToCome--;
			TrySpawnRegular(player, _currentTown);
			_nextTownArrival = Game.GameTime + 1000;
			return;
		}
		NemesisRecord nemesisRecord = _townArrivals[0];
		_townArrivals.RemoveAt(0);
		if (nemesisRecord.IsAlive && !nemesisRecord.PresumedDead && !_worldNemeses.ContainsValue(nemesisRecord) && nemesisRecord != ActiveRecord && _townMen.Count < Balance.TownMaxMen)
		{
			GrudgeLog($"TOWN arrival: {nemesisRecord.Name} turns up ({_townArrivals.Count} still to come)");
			if (!SpawnTownPresence(nemesisRecord, _currentTown, player, hunter: false, arrival: true) && _arrivalRetried.Add(nemesisRecord.Id))
			{
				_townArrivals.Add(nemesisRecord);
			}
		}
		_nextTownArrival = Game.GameTime + 1000;
	}

	private bool LoreTownRoll(NemesisRecord rec, string town)
	{
		Gang gang = Gangs.Of(rec);
		if (gang == null || town == null)
		{
			return true;
		}
		Gang gang2 = TownHolder(town, out var _);
		if (gang2 != null && gang2 != gang && AtWarNow(gang.Id, gang2.Id))
		{
			GrudgeLog("TOWN " + rec.Name + " (" + gang.Name + ") in " + town + "? the " + gang2.Name + " hold it and they're at war - stays away");
			return false;
		}
		if ((gang.JobTowns != null && gang.JobTowns.Contains(town)) || gang.HomeTown == town || rec.KillLocation == town)
		{
			return true;
		}
		if (gang.OnlyDistricts != null && TownCore(town, out var centre, out var _))
		{
			District district = DistrictAt(centre);
			if (district != null && !district.Hashes.Any(gang.OnlyDistricts.Contains))
			{
				GrudgeLog("TOWN " + rec.Name + " (" + gang.Name + ") in " + town + "? outside the outfit's own country (" + district.Name + ") - stays away");
				return false;
			}
		}
		bool flag = _rng.Next(100) < Balance.TownOffLorePercent;
		GrudgeLog(string.Format("TOWN {0} ({1}) in {2}? not one of his outfit's towns - {3} ({4}%)", rec.Name, gang.Name, town, flag ? "comes anyway" : "stays away", Balance.TownOffLorePercent));
		return flag;
	}

	private IEnumerable<NemesisRecord> TownCandidates(string town, Ped player)
	{
		return from n in Roster.Where((NemesisRecord n) => n.CanHunt && !n.PresumedDead && !Resting(n) && !_worldNemeses.ContainsValue(n) && n != ActiveRecord && !IsArmy(n) && !NoTowns(n) && n != _roadAmbush?.Rec).Where((NemesisRecord n) =>
			{
				Intent intent = IntentOf(n);
				return intent == Intent.WontHunt || intent == Intent.ProvokedOnly || intent == Intent.Hunts;
			})
			where HomeTown(n, town, player) || !n.HasOrigin || new Vector3(n.OriginX, n.OriginY, n.OriginZ).DistanceTo(player.Position) < Balance.TownPassingRange
			select n;
	}

	private string TownPoolNote(string town, Ped player)
	{
		List<NemesisRecord> source = Roster.Where((NemesisRecord n) => n.IsAlive && !n.PresumedDead).ToList();
		int num = Enumerable.Count(source, (NemesisRecord n) => n.CanHunt);
		int num2 = Enumerable.Count(source, (NemesisRecord n) => n.CanHunt && IsArmy(n));
		List<NemesisRecord> source2 = source.Where((NemesisRecord n) => n.CanHunt && !IsArmy(n)).ToList();
		int num3 = Enumerable.Count(source2, Resting);
		int num4 = Enumerable.Count(source2, (NemesisRecord n) => !Resting(n) && (_worldNemeses.ContainsValue(n) || n == ActiveRecord));
		int num5 = Enumerable.Count(source2, NoTowns);
		List<NemesisRecord> list = (from n in source2.Where((NemesisRecord n) => !NoTowns(n)).ToList()
			where !Resting(n) && !_worldNemeses.ContainsValue(n) && n != ActiveRecord
			select n).ToList();
		int num6 = Enumerable.Count(list, (NemesisRecord n) => IntentOf(n) == Intent.None);
		List<NemesisRecord> list2 = list.Where((NemesisRecord n) => IntentOf(n) != Intent.None && (HomeTown(n, town, player) || !n.HasOrigin || new Vector3(n.OriginX, n.OriginY, n.OriginZ).DistanceTo(player.Position) < Balance.TownPassingRange)).ToList();
		int num7 = Enumerable.Count(list2, CoolingOff);
		int num8 = Enumerable.Count(list2, (NemesisRecord n) => !CoolingOff(n) && n.HateTier == HateTier.Murderous && n.Hate < Balance.TownMurderousMinHate);
		return $"{num} can come ({num2} Army/squads never, {num5} never in towns), {num3} lying low, {num4} already out, {num6} no grudge, {list.Count - num6 - list2.Count} too far away, " + $"{list2.Count} near: {num7} cooling off (came lately), {num8} murderous under {Balance.TownMurderousMinHate}, {Enumerable.Count(list2, (NemesisRecord n) => TownTierPercent(n) > 0)} could come";
	}

	private static bool HomeTown(NemesisRecord n, string town, Ped player)
	{
		if (!(n.KillLocation == town))
		{
			if (n.HasOrigin)
			{
				return new Vector3(n.OriginX, n.OriginY, n.OriginZ).DistanceTo(player.Position) < 600f;
			}
			return false;
		}
		return true;
	}

	private int TownTierPercent(NemesisRecord r)
	{
		if (CoolingOff(r))
		{
			return 0;
		}
		if (r.HateTier == HateTier.Murderous && r.Hate < Balance.TownMurderousMinHate)
		{
			return 0;
		}
		int num;
		if (r.HateTier == HateTier.Murderous)
		{
			num = Balance.TownMurderousPct;
		}
		else
		{
			num = ((r.HateTier == HateTier.Vengeful) ? Balance.TownVengefulPct : 100);
		}
		if (r.HateTier == HateTier.Murderous && _townMen.Any((TownMan t) => t.Rec.HateTier == HateTier.Murderous))
		{
			num = num * Balance.TownSecondMurderousPct / 100;
		}
		return num;
	}

	private NemesisRecord PickTownMan(List<NemesisRecord> pool)
	{
		double num = ((IEnumerable<NemesisRecord>)pool).Sum((Func<NemesisRecord, double>)((NemesisRecord n) => TownTierPercent(n)));
		if (num <= 0.0)
		{
			return pool[_rng.Next(pool.Count)];
		}
		double num2 = _rng.NextDouble() * num;
		foreach (NemesisRecord item in pool)
		{
			num2 -= (double)TownTierPercent(item);
			if (num2 <= 0.0)
			{
				return item;
			}
		}
		return pool[pool.Count - 1];
	}

	private static float NightTownMult()
	{
		int cLOCK_HOURS = CLOCK.GET_CLOCK_HOURS();
		if (cLOCK_HOURS < 22 && cLOCK_HOURS >= 5)
		{
			return 1f;
		}
		return 0.5f;
	}

	internal bool SpawnTownHunter(Ped player)
	{
		string text = _currentTown ?? TownAt(player.Position);
		if (text == null)
		{
			return false;
		}
		if (_townMen.Count >= Balance.TownMaxMen)
		{
			return SpawnTestRegular(player, text, $"{_townMen.Count} nemeses are already in {text}");
		}
		List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.CanHunt && !n.PresumedDead && !IsArmy(n) && !NoTowns(n) && !_worldNemeses.ContainsValue(n) && n != ActiveRecord).ToList();
		if (list.Count == 0)
		{
			return SpawnTestRegular(player, text, "no nemesis free to come into town");
		}
		if (list.Any((NemesisRecord n) => TownTierPercent(n) > 0))
		{
			list = list.Where((NemesisRecord n) => TownTierPercent(n) > 0).ToList();
		}
		NemesisRecord rec = PickTownMan(list);
		SpawnTownPresence(rec, text, player);
		return true;
	}

	private bool SpawnTestRegular(Ped player, string town, string why)
	{
		if (TrySpawnRegular(player, town, force: true))
		{
			return true;
		}
		int num = Enumerable.Count(People, (Acquaintance a) => !a.Dead && a.Town == town);
		string text;
		if (Config.RememberPeople)
		{
			if (Enumerable.Count(_regulars, (Ped r) => r.Exists()) >= Config.RegularsMax)
			{
				text = $"{Config.RegularsMax} people you know are already around";
			}
			else
			{
				text = ((num == 0) ? ("you don't know anyone from " + town + " yet") : ("everyone you know from " + town + " is already here"));
			}
		}
		else
		{
			text = "remembering people is off";
		}
		ShowNotification(char.ToUpper(why[0]) + why.Substring(1) + " - and " + text + ".");
		return true;
	}

	private bool SpawnTownPresence(NemesisRecord rec, string town, Ped player, bool hunter = false, bool arrival = false)
	{
		bool flag = hunter || IntentOf(rec) == Intent.WontHunt;
		int num = _rng.Next(100);
		bool num2 = num >= Balance.TownSeatPercent && num < Balance.TownSeatPercent + Balance.TownStrollPercent;
		bool flag2 = num >= Balance.TownSeatPercent + Balance.TownStrollPercent;
		(Vector3, float, int)? tuple = ((num2 | flag2) ? (((Vector3, float, int)?)null) : FindTownSeat(player, town, flag ? (Math.Max(Balance.WontHuntSpotRange, 32f) + 12f) : 12f));
		string text;
		Vector3 vector2;
		if (!tuple.HasValue)
		{
			Vector3? vector;
			if (flag2)
			{
				vector = TownEdgeSpot(player, town);
				if (vector.HasValue)
				{
					Vector3 valueOrDefault = vector.GetValueOrDefault();
					if (valueOrDefault != Vector3.Zero)
					{
						text = "on the edge of town";
						vector2 = valueOrDefault;
						goto IL_0171;
					}
				}
			}
			vector = AheadStreetSpot(player, town);
			if (vector.HasValue)
			{
				Vector3 valueOrDefault2 = vector.GetValueOrDefault();
				text = "about town";
				vector2 = valueOrDefault2;
			}
			else
			{
				vector = NearStreetSpot(player, town);
				if (!vector.HasValue)
				{
					(vector2, text) = NaturalTownSpot(player, town);
				}
				else
				{
					Vector3 valueOrDefault3 = vector.GetValueOrDefault();
					text = "about town";
					vector2 = valueOrDefault3;
				}
			}
		}
		else
		{
			Vector3 vector3 = StandIn(tuple.Value.Item1, tuple.Value.Item2);
			text = "on a seat";
			vector2 = vector3;
		}
		goto IL_0171;
		IL_0171:
		if (num2 && vector2 != Vector3.Zero)
		{
			text = "strolling the streets";
		}
		if (vector2 == Vector3.Zero)
		{
			GrudgeLog("TOWN " + rec.Name + ": no spot in " + town + " - not placed");
			return false;
		}
		if (arrival && vector2.DistanceTo(player.Position) > 110f)
		{
			GrudgeLog($"TOWN {rec.Name}: the only spot was {vector2.DistanceTo(player.Position):0} m off - he turns up later");
			return false;
		}
		GrudgeLog("TOWN spot for " + rec.Name + " (" + (hunter ? "hunter" : IntentOf(rec).ToString()) + "): " + text + " - " + SpotNote(vector2, town, player));
		if (_townRelGroup == 0)
		{
			_townRelGroup = World.AddRelationshipGroup("NEMESIS_TOWN");
		}
		bool flag3 = NoTowns(rec);
		uint modelOverride = (flag3 ? PlainModelOf(rec) : 0u);
		Ped ped = SpawnNemesisPed(rec, vector2, tuple.HasValue ? tuple.Value.Item2 : ((float)_rng.Next(360)), _townRelGroup, out var _, 424175505u, releaseModel: true, blockEvents: false, factionStyle: false, modelOverride);
		if (ped == null)
		{
			return false;
		}
		World.SetRelationshipBetweenGroups((eRelationshipType)4, _townRelGroup, player.RelationshipGroup);
		if ((rec.Gang == null) | flag3)
		{
			ped.RelationshipGroup = PED.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH(ped.Handle);
			ForgetSwitch(ped.Handle);
		}
		Vector3 centre;
		float radius;
		if (tuple.HasValue)
		{
			SitAt(ped, tuple.Value.Item3, tuple.Value.Item1, tuple.Value.Item2);
		}
		else if (text == "strolling the streets" && TownCore(town, out centre, out radius))
		{
			Function.Call(16164602603745899285uL, ped.Handle, centre.X, centre.Y, centre.Z, radius * 0.7f, 4f, 10f, 0);
		}
		else
		{
			PlaceNaturally(ped, vector2, text != "at the saloon bar");
		}
		MakeSociable(ped);
		if (!hunter)
		{
			HandToGame(ped);
		}
		TownMan townMan = new TownMan
		{
			Ped = ped,
			Rec = rec,
			Intent = IntentOf(rec),
			Town = town,
			Hunter = hunter,
			SpawnedAt = Game.GameTime,
			Disguised = flag3
		};
		if (!flag3 && HasReason(rec) && _rng.Next(100) < 5 && (rec.HateTier != HateTier.Murderous || _rng.Next(100) < 30))
		{
			townMan.Comes = true;
			GrudgeLog($"TOWN {rec.Name} ({rec.HateTier}) will come for you when he sees you");
		}
		NoteCame(rec);
		if (hunter)
		{
			rec.Touch();
			Feed("ENCOUNTER TOWN: " + rec.FullName + " is in " + town + ", looking for you (" + text + ")", Theme.Warn, rec);
		}
		_townMen.Add(townMan);
		_worldNemeses[ped.Handle] = rec;
		if (rec.Id != null)
		{
			if (!_townLastMen.TryGetValue(town, out var value))
			{
				value = (_townLastMen[town] = new List<string>());
			}
			if (!value.Contains(rec.Id))
			{
				value.Add(rec.Id);
			}
		}
		if (flag3 && !rec.CoverBlown)
		{
			townMan.DotName = null;
		}
		else if (flag3)
		{
			townMan.DotName = rec.FullName + " (" + Gangs.ById(rec.Gang)?.Name + ", out of his robe)";
		}
		else
		{
			townMan.DotName = (HasReason(rec) ? (rec.FullName + " (holds a grudge)") : (rec.FullName + " (" + Gangs.ById(rec.Gang)?.Name + ")"));
			if (HasReason(rec))
			{
				GrudgeNotice(rec.FullName + " is in " + town + ". He won't start anything - but he hasn't forgotten.");
			}
		}
		GrudgeLog($"TOWN {rec.Name} in {town} {text}: {townMan.Intent} (hate {rec.Hate}, fear {EffectiveFear(rec)}) - {_townMen.Count} in town");
		TownHappening(rec.Name + " turned up in " + town);
		return true;
	}

	private Vector3? AheadStreetSpot(Ped player, string town)
	{
		Vector3? townToward = TownToward;
		if (townToward.HasValue)
		{
			Vector3 valueOrDefault = townToward.GetValueOrDefault();
			if (TownCore(town, out var centre, out var radius))
			{
				for (int i = 0; i < 16; i++)
				{
					double num = _rng.NextDouble() * Math.PI * 2.0;
					float num2 = 5f + (float)_rng.NextDouble() * 40f;
					Vector3 position = new Vector3(valueOrDefault.X + (float)Math.Cos(num) * num2, valueOrDefault.Y + (float)Math.Sin(num) * num2, player.Position.Z);
					if (!(new Vector3(position.X - centre.X, position.Y - centre.Y, 0f).Length() > radius))
					{
						Vector3 safeCoordForPed = World.GetSafeCoordForPed(position);
						if ((safeCoordForPed.X != 0f || safeCoordForPed.Y != 0f) && !(safeCoordForPed.DistanceTo(position) > 20f) && Dry(safeCoordForPed) && !UpHigh(safeCoordForPed) && Outdoors(safeCoordForPed) && !(safeCoordForPed.DistanceTo(player.Position) < 20f) && HiddenFromView(player, safeCoordForPed) && !OurPeopleNear(safeCoordForPed, TownSpread(town)))
						{
							return safeCoordForPed;
						}
					}
				}
				return null;
			}
		}
		return null;
	}

	private Vector3? NearStreetSpot(Ped player, string town, int tries = 20, bool hidden = true)
	{
		if (!TownCore(town, out var centre, out var radius))
		{
			return null;
		}
		double num = Math.Atan2(Forward(player).Y, Forward(player).X);
		for (int i = 0; i < tries; i++)
		{
			double num2 = ((i < tries * 3 / 5) ? (num + (_rng.NextDouble() - 0.5) * Math.PI * 1.4) : (_rng.NextDouble() * Math.PI * 2.0));
			float num3 = 35f + (float)_rng.NextDouble() * 65f;
			Vector3 position = new Vector3(player.Position.X + (float)Math.Cos(num2) * num3, player.Position.Y + (float)Math.Sin(num2) * num3, player.Position.Z);
			if (new Vector3(position.X - centre.X, position.Y - centre.Y, 0f).Length() > radius)
			{
				continue;
			}
			Vector3 safeCoordForPed = World.GetSafeCoordForPed(position);
			if ((safeCoordForPed.X != 0f || safeCoordForPed.Y != 0f) && !(safeCoordForPed.DistanceTo2D(position) > 20f) && Dry(safeCoordForPed) && !UpHigh(safeCoordForPed) && Outdoors(safeCoordForPed))
			{
				float num4 = safeCoordForPed.DistanceTo(player.Position);
				if (!(num4 < 30f) && !(num4 > 105f) && (!hidden || HiddenFromView(player, safeCoordForPed)) && !OurPeopleNear(safeCoordForPed, TownSpread(town)))
				{
					return safeCoordForPed;
				}
			}
		}
		return null;
	}

	private Vector3? TownEdgeSpot(Ped player, string town)
	{
		if (!TownCore(town, out var centre, out var radius))
		{
			return null;
		}
		for (int i = 0; i < 10; i++)
		{
			double num = _rng.NextDouble() * Math.PI * 2.0;
			float num2 = radius * (0.85f + (float)_rng.NextDouble() * 0.25f);
			Vector3 position = new Vector3(centre.X + (float)Math.Cos(num) * num2, centre.Y + (float)Math.Sin(num) * num2, centre.Z);
			Vector3 safeCoordForPed = World.GetSafeCoordForPed(position);
			if ((safeCoordForPed.X != 0f || safeCoordForPed.Y != 0f) && !(safeCoordForPed.DistanceTo(position) > 25f) && Dry(safeCoordForPed) && !UpHigh(safeCoordForPed) && Outdoors(safeCoordForPed) && !(safeCoordForPed.DistanceTo(player.Position) < 25f) && HiddenFromView(player, safeCoordForPed) && !OurPeopleNear(safeCoordForPed, TownSpread(town)))
			{
				return safeCoordForPed;
			}
		}
		return null;
	}

	private void UpdateTownDots(Ped player)
	{
		if (Game.GameTime < _nextTownDots)
		{
			return;
		}
		_nextTownDots = Game.GameTime + 400;
		foreach (TownMan townMan in _townMen)
		{
			if (townMan.Engaged || townMan.Leaving || townMan.Ped == null || !townMan.Ped.Exists())
			{
				continue;
			}
			if (townMan.Disguised && townMan.Rec.CoverBlown && townMan.DotName == null)
			{
				townMan.DotName = townMan.Rec.FullName + " (" + Gangs.ById(townMan.Rec.Gang)?.Name + ", out of his robe)";
			}
			if (townMan.DotName == null)
			{
				continue;
			}
			bool flag = townMan.Blip != null && townMan.Blip.Exists();
			float num = townMan.Ped.Position.DistanceTo(player.Position);
			bool flag2 = _debugOn || num < Balance.TownDotNear || (flag && num < Balance.TownDotFar);
			if (flag2 && !flag)
			{
				Crumbs.Native("TownPresence blip add (V2)");
				townMan.Blip = townMan.Ped.AddBlip((BlipType)2545348716u);
				if (townMan.Blip != null)
				{
					Function.Call(11290983183885202434uL, townMan.Blip.Handle, new InputArgument(UiDraw.ForeverVarString(townMan.DotName)));
				}
			}
			else if (!flag2 & flag)
			{
				Crumbs.Native("TownPresence blip remove (V2)");
				townMan.Blip.Delete();
				townMan.Blip = null;
			}
		}
	}

	private void UpdateTownPresence(Ped player)
	{
		TrackTownVisit();
		UpdateTownDots(player);
		UpdateTownArrivals(player);
		UpdateRoadAmbush(player);
		if (_currentTown != null && Game.GameTime >= _nextTownTopUp && InTownForArrivals(player, _currentTown))
		{
			_nextTownTopUp = Game.GameTime + Balance.TownTopUpSeconds * 1000;
			if (_townArrivalsFor != _currentTown)
			{
				_townArrivals.Clear();
				_regularsToCome = 0;
				_townArrivalsFor = _currentTown;
				_arrivalStep = 0f;
				_lastArrivalAt = Game.GameTime;
			}
			if (NoSpawnReason(player) == null && (float)_rng.Next(100) < (float)Config.RegularChance * NightTownMult() && _regularsToCome < 2)
			{
				_regularsToCome++;
			}
			if (_townMen.Count < Balance.TownMaxMen && NoSpawnReason(player) == null && (float)_rng.Next(100) < (float)Balance.TownTopUpChance * NightTownMult())
			{
				List<NemesisRecord> list = (from n in TownCandidates(_currentTown, player)
					where TownTierPercent(n) > 0
					select n).ToList();
				if (list.Count > 0 && list.Any((NemesisRecord n) => HomeTown(n, _currentTown, player)) && _rng.Next(100) >= Balance.TownPassingPercent)
				{
					list = list.Where((NemesisRecord n) => HomeTown(n, _currentTown, player)).ToList();
				}
				list.RemoveAll((NemesisRecord n) => _townArrivals.Contains(n));
				if (list.Count > 0 && _townArrivals.Count + _townMen.Count < Balance.TownMaxMen)
				{
					NemesisRecord nemesisRecord = PickTownMan(list);
					if (LoreTownRoll(nemesisRecord, _currentTown))
					{
						GrudgeLog("TOWN top-up: " + nemesisRecord.Name + " will turn up as you walk about " + _currentTown);
						_townArrivals.Add(nemesisRecord);
					}
				}
			}
		}
		if (_heldTownEntry != null && _currentTown != _heldTownEntry)
		{
			_heldTownEntry = null;
		}
		if (_heldTownEntry != null && NoSpawnReason(player) == null && InTownForArrivals(player, _heldTownEntry))
		{
			string heldTownEntry = _heldTownEntry;
			_heldTownEntry = null;
			OnEnterTownPresence(heldTownEntry, player);
		}
		if (Game.GameTime < _nextTownScan)
		{
			return;
		}
		_nextTownScan = Game.GameTime + 250;
		try
		{
			TownFolkStayOut(player);
		}
		catch (Exception ex)
		{
			GrudgeLog("TOWN folk check failed: " + ex.Message);
		}
		for (int num = _townMen.Count - 1; num >= 0; num--)
		{
			TownMan townMan = _townMen[num];
			if (townMan.Ped == null || !townMan.Ped.Exists() || !Roster.Contains(townMan.Rec) || !townMan.Rec.IsAlive || townMan.Ped.IsDead)
			{
				if (townMan.Engaged)
				{
					NoteTownFightOver();
				}
				ClearTownMan(townMan, delete: false);
				continue;
			}
			float num2 = townMan.Ped.Position.DistanceTo(player.Position);
			if (num2 > 220f && !townMan.Engaged)
			{
				ClearTownMan(townMan, delete: true);
			}
			else if (townMan.Engaged && num2 > 300f)
			{
				NoteTownFightOver();
				ClearTownMan(townMan, delete: false);
			}
			else
			{
				if (townMan.Engaged && UnderArrest(townMan.Ped.Handle))
				{
					continue;
				}
				if (townMan.Engaged)
				{
					try
					{
						UnstickTownFighter(townMan, player, num2);
					}
					catch (Exception ex2)
					{
						GrudgeLog("TOWN unstick failed: " + ex2.Message);
					}
					continue;
				}
				if (townMan.EngageAt > 0 && (Game.GameTime >= townMan.EngageAt || PED.IS_PED_IN_COMBAT(townMan.Ped.Handle, player.Handle) || ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(townMan.Ped.Handle, player.Handle, p2: true, p3: true)))
				{
					townMan.EngageAt = 0;
					GrudgeLog("TOWN " + townMan.Rec.Name + ": after the words, the fight");
					EngageTownMan(townMan, player);
					continue;
				}
				try
				{
					if (TownBackup(townMan, player) || TownNoPanic(townMan, player))
					{
						continue;
					}
					goto IL_0525;
				}
				catch (Exception ex3)
				{
					GrudgeLog("TOWN backup failed: " + ex3.Message);
					goto IL_0525;
				}
			}
			continue;
			IL_0525:
			if (Game.GameTime - townMan.SpawnedAt < 10000)
			{
				continue;
			}
			if (townMan.Leaving)
			{
				if (num2 > 70f || Game.GameTime - townMan.LeftAt > 45000)
				{
					GrudgeLog("TOWNCALM " + townMan.Rec.Name + " left " + townMan.Town);
					ClearTownMan(townMan, delete: true);
				}
				else if (PED.IS_PED_IN_COMBAT(townMan.Ped.Handle, player.Handle) && JoinsTheFight(townMan, player))
				{
					townMan.Leaving = false;
					if (_roadAmbush?.Rec == townMan.Rec)
					{
						_roadAmbush = null;
					}
					EngageTownMan(townMan, player);
				}
				continue;
			}
			if (townMan.Approaching)
			{
				TownManApproach(townMan, player, num2);
				continue;
			}
			if (townMan.Comes && !townMan.Spotted && num2 < 50f && Sees(townMan.Ped, player, SightFor(player, 30f), out var d))
			{
				townMan.Spotted = true;
				string why = "a man is already waiting outside";
				if (_roadAmbush == null && TakeAggressorSlot(out why))
				{
					townMan.Approaching = true;
					townMan.ApproachAt = Game.GameTime;
					Crumbs.Native("Town man comes over");
					TASK.CLEAR_PED_TASKS(townMan.Ped.Handle, p1: true, p2: true);
					TASK.TASK_GO_TO_ENTITY(townMan.Ped.Handle, player.Handle, -1, 3f, 1.4f, 0f, 0);
					GrudgeLog($"TOWN {townMan.Rec.Name} saw you in {townMan.Town} - he comes over ({num2:0} m, {townMan.Rec.HateTier})");
					Feed("TOWN " + townMan.Rec.FullName + " saw you - he's coming over", Theme.Blood, townMan.Rec);
				}
				else
				{
					GrudgeLog("TOWN " + townMan.Rec.Name + " would have come for you - " + why);
				}
				continue;
			}
			if (!townMan.Spotted && !townMan.Disguised && townMan.Rec.HateTier == HateTier.Murderous && HasReason(townMan.Rec) && num2 < 50f && Sees(townMan.Ped, player, SightFor(player, 30f), out d))
			{
				townMan.Spotted = true;
				if (_roadAmbush == null && TakeAggressorSlot(out var _))
				{
					if (RollWaitOutside(townMan.Rec, townMan.Town, townMan.Ped, player))
					{
						townMan.Leaving = true;
						townMan.LeftAt = Game.GameTime;
						if (townMan.Blip != null && townMan.Blip.Exists())
						{
							townMan.Blip.Delete();
						}
						townMan.Blip = null;
					}
					else
					{
						_visitAggressors--;
					}
				}
			}
			if (PED.IS_PED_IN_COMBAT(townMan.Ped.Handle, player.Handle) && JoinsTheFight(townMan, player))
			{
				EngageTownMan(townMan, player);
			}
		}
	}

	private bool JoinsTheFight(TownMan tm, Ped player)
	{
		int handle = tm.Ped.Handle;
		if (ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(handle, player.Handle, p2: true, p3: true))
		{
			BystanderLog(tm, "joined: you hurt him");
			return true;
		}
		if (PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(Game.Player.Handle, handle) || PLAYER.IS_PLAYER_TARGETTING_ENTITY(Game.Player.Handle, handle, p2: false))
		{
			BystanderLog(tm, "joined: you drew on him");
			return true;
		}
		if (tm.Calmed)
		{
			return false;
		}
		if (tm.StayedOutAt != 0)
		{
			if (Game.GameTime - tm.StayedOutAt > 3000)
			{
				tm.StayedOutAt = Game.GameTime;
				TASK.CLEAR_PED_TASKS(handle, p1: true, p2: true);
				if (tm.Leaving)
				{
					TASK.TASK_WANDER_STANDARD(handle, 10f, 10);
				}
			}
			return false;
		}
		List<NemesisRecord> list = (from o in _townMen
			where o != tm && o.Engaged && o.Rec != null
			select o.Rec).ToList();
		NemesisRecord nemesisRecord = list.FirstOrDefault((NemesisRecord o) => tm.Rec.Gang != null && o.Gang == tm.Rec.Gang);
		if (nemesisRecord != null)
		{
			BystanderLog(tm, "joined: backs up " + nemesisRecord.Name + ", his outfit's man");
			return true;
		}
		NemesisRecord nemesisRecord2 = list.FirstOrDefault((NemesisRecord o) =>
		{
			List<string> friendIds = tm.Rec.FriendIds;
			if (friendIds == null || !friendIds.Contains(o.Id))
			{
				List<string> friendIds2 = o.FriendIds;
				if ((friendIds2 == null || !friendIds2.Contains(tm.Rec.Id)) && !(o.KinId == tm.Rec.Id))
				{
					return tm.Rec.KinId == o.Id;
				}
			}
			return true;
		});
		if (nemesisRecord2 != null)
		{
			BystanderLog(tm, "joined: backs up " + nemesisRecord2.Name + ", a friend");
			return true;
		}
		if (list.Count == 0 && _peaceAggressor == 0)
		{
			BystanderLog(tm, "joined: no other fight on - the game's combat stands");
			return true;
		}
		bool flag = Mind.F(tm.Rec, "Bravery") >= 60;
		tm.StayedOutAt = Game.GameTime;
		Crumbs.Native("Town bystander stays out");
		TASK.CLEAR_PED_TASKS(handle, p1: true, p2: true);
		tm.Ped.BlockPermanentEvents = true;
		if (flag)
		{
			TASK.TASK_TURN_PED_TO_FACE_ENTITY(handle, player.Handle, 4000, 0f, 0f, 0f);
			BystanderLog(tm, "stayed out: not his fight (" + FightersText(list) + ") - he stands and watches");
		}
		else
		{
			TASK.TASK_WANDER_STANDARD(handle, 10f, 10);
			tm.Leaving = true;
			tm.LeftAt = Game.GameTime;
			if (tm.Blip != null && tm.Blip.Exists())
			{
				tm.Blip.Delete();
			}
			tm.Blip = null;
			BystanderLog(tm, "stayed out: not his fight (" + FightersText(list) + ") - he leaves town");
		}
		return false;
	}

	private bool TownBackup(TownMan tm, Ped player)
	{
		if (tm.Engaged || tm.Leaving || tm.BackupDecided || tm.Disguised || (tm.Rec.Gang == null && (tm.Rec.FriendIds == null || tm.Rec.FriendIds.Count == 0) && tm.Rec.KinId == null))
		{
			return false;
		}
		TownMan townMan = _townMen.FirstOrDefault((TownMan o) => o != tm && o.Engaged && o.Rec != null && o.Ped != null && o.Ped.Exists() && !o.Ped.IsDead && Tied(tm.Rec, o.Rec) != null);
		if (townMan == null)
		{
			return false;
		}
		Sight s = SightFor(player, 60f);
		bool flag = Sees(tm.Ped, player, s, out var d);
		bool flag2 = !flag && Sees(tm.Ped, townMan.Ped, s, out var _);
		if (!flag && !flag2)
		{
			return false;
		}
		tm.BackupDecided = true;
		string text = Tied(tm.Rec, townMan.Rec);
		int num = Mind.F(tm.Rec, "Loyalty");
		int num2 = Mind.F(tm.Rec, "Bravery");
		if (num >= 40 || num2 >= 40)
		{
			GrudgeLog(string.Format("TOWN backup {0} saw {1} ({2:0} m) - joins {3}, {4} (loyalty {5}, bravery {6})", tm.Rec.Name, flag ? "you" : townMan.Rec.Name, d, townMan.Rec.Name, text, num, num2));
			Feed("TOWN " + tm.Rec.FullName + " comes to back up " + townMan.Rec.Name, Theme.Blood, tm.Rec);
			EngageTownMan(tm, player);
			return true;
		}
		GrudgeLog(string.Format("TOWN backup {0} saw {1} ({2:0} m) - won't back {3}, {4} (loyalty {5}, bravery {6}) - hangs back", tm.Rec.Name, flag ? "you" : townMan.Rec.Name, d, townMan.Rec.Name, text, num, num2));
		tm.Calmed = true;
		KeepOutOfIt(tm, player, num2 < 25);
		return true;
	}

	private static string Tied(NemesisRecord a, NemesisRecord b)
	{
		if (a.Gang != null && a.Gang == b.Gang)
		{
			return "his outfit's man";
		}
		if (a.KinId == b.Id || b.KinId == a.Id)
		{
			return "his kin";
		}
		List<string> friendIds = a.FriendIds;
		if (friendIds == null || !friendIds.Contains(b.Id))
		{
			List<string> friendIds2 = b.FriendIds;
			if (friendIds2 == null || !friendIds2.Contains(a.Id))
			{
				return null;
			}
		}
		return "a friend";
	}

	private bool TownNoPanic(TownMan tm, Ped player)
	{
		if (tm.Engaged || tm.Leaving || tm.Calmed || !PED.IS_PED_FLEEING(tm.Ped.Handle))
		{
			return false;
		}
		if (!_townMen.Any((TownMan o) => o.Engaged) && _peaceAggressor == 0 && !PED.IS_PED_IN_MELEE_COMBAT(player.Handle) && PLAYER.GET_PLAYER_WANTED_LEVEL(Game.Player.Handle) <= 0 && !GunMelee.PlayerFiredRecently)
		{
			return false;
		}
		tm.Calmed = true;
		bool flag = Mind.F(tm.Rec, "Bravery") >= 60;
		GrudgeLog("TOWN " + tm.Rec.Name + " started to run from the fight (the game's townsfolk panic) - " + (flag ? "he stands and watches instead" : "he walks off instead"));
		KeepOutOfIt(tm, player, !flag);
		return true;
	}

	private void KeepOutOfIt(TownMan tm, Ped player, bool leave)
	{
		int handle = tm.Ped.Handle;
		Crumbs.Native("Town man keeps out of it");
		TASK.CLEAR_PED_TASKS(handle, p1: true, p2: true);
		tm.Ped.BlockPermanentEvents = true;
		if (leave)
		{
			TASK.TASK_WANDER_STANDARD(handle, 10f, 10);
			tm.Leaving = true;
			tm.LeftAt = Game.GameTime;
			if (tm.Blip != null && tm.Blip.Exists())
			{
				tm.Blip.Delete();
			}
			tm.Blip = null;
		}
		else
		{
			TASK.TASK_TURN_PED_TO_FACE_ENTITY(handle, player.Handle, 4000, 0f, 0f, 0f);
		}
	}

	private void TownFolkStayOut(Ped player)
	{
		if (!_townMen.Any((TownMan t) => t.Engaged))
		{
			if (_folkRolled || _folkOut.Count > 0)
			{
				_folkRolled = false;
				_folkMayJoin = false;
				_folkJoined = 0;
				_folkOut.Clear();
			}
		}
		else
		{
			if (Game.GameTime < _nextFolkScan)
			{
				return;
			}
			_nextFolkScan = Game.GameTime + 500;
			if (!_folkRolled)
			{
				_folkRolled = true;
				_folkMayJoin = _rng.Next(100) < 25;
			}
			foreach (Ped item in PedsAround(player))
			{
				if (item == null || !item.Exists() || item.IsDead || item.IsPlayer || !item.IsHuman)
				{
					continue;
				}
				int handle = item.Handle;
				if (item.Position.DistanceTo(player.Position) > 80f || !PED.IS_PED_IN_COMBAT(handle, player.Handle) || TownManFor(handle) != null || RecordAt(handle) != null || IsOurs(handle) || IsLawman(item) || Kids.IsChild(item) || IsStoryPed(item) || GameOwned(item) || OutfitFighter(handle) || Gangs.ForModel((uint)item.Model.Hash) != null || ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(handle, player.Handle, p2: true, p3: true) || PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(Game.Player.Handle, handle))
				{
					continue;
				}
				_fighters.TryGetValue(handle, out var value);
				string text = NameOf(handle);
				string text2 = value?.Temper ?? "Plain";
				bool flag = Tempers.Of(text2).Nerve >= 15;
				if (_folkOut.TryGetValue(handle, out var value2))
				{
					if (value2 != int.MinValue && Game.GameTime - value2 > 3000)
					{
						_folkOut[handle] = Game.GameTime;
						TASK.CLEAR_PED_TASKS(handle, p1: true, p2: true);
					}
					continue;
				}
				if ((_folkMayJoin && _folkJoined == 0) & flag)
				{
					_folkJoined = 1;
					_folkOut[handle] = int.MinValue;
					GrudgeLog($"TOWN folk {text} ({text2}) stays in the fight - the one townsman this fight ({25}% roll)");
					continue;
				}
				_folkOut[handle] = Game.GameTime;
				if (value != null)
				{
					value.Done = true;
					value.DoneAt = Game.GameTime;
				}
				_peaceWaiting.Remove(handle);
				Crumbs.Native("Town folk stays out");
				TASK.CLEAR_PED_TASKS(handle, p1: true, p2: true);
				item.BlockPermanentEvents = true;
				if (flag)
				{
					TASK.TASK_TURN_PED_TO_FACE_ENTITY(handle, player.Handle, 4000, 0f, 0f, 0f);
				}
				else
				{
					TASK.TASK_WANDER_STANDARD(handle, 10f, 10);
				}
				GrudgeLog("TOWN folk " + text + " (" + text2 + ") was pulled into the fight by the game - stays out, " + (flag ? "stands and watches" : "backs off") + ((!_folkMayJoin) ? " (no townsman joins this fight)" : ((_folkJoined > 0) ? " (this fight's one townsman is already in)" : " (not a tough temper)")));
			}
		}
	}

	private string FightersText(List<NemesisRecord> f)
	{
		if (f.Count != 0)
		{
			return "you're fighting " + string.Join(", ", f.Select((NemesisRecord x) => x.Name));
		}
		return "a stranger's fight";
	}

	private void BystanderLog(TownMan tm, string what)
	{
		GrudgeLog("TOWN bystander " + tm.Rec.Name + " (" + (Gangs.ById(tm.Rec.Gang)?.Name ?? "no outfit") + "): " + what);
