	private void TownManApproach(TownMan tm, Ped player, float d)
	{
		if (!tm.Spoke && d < 12f)
		{
			tm.Spoke = true;
			string[] array;
			if (tm.Rec.HateTier != HateTier.Resentful)
			{
				array = ((tm.Rec.HateTier != HateTier.Vengeful) ? new string[3] { "Nobody's going to save you this time.", "I'm going to bury you in this street.", "Say your prayers, mister." } : new string[3] { "Thought I'd never find you? Here I am.", "You don't walk away from me twice.", "This ends now, you hear?" });
			}
			else
			{
				array = new string[3] { "You and me. Right here.", "I been waiting on you. Put 'em up.", "Remember me? I sure remember you." };
			}
			ShowSubtitle(tm.Rec.Name + ": \"" + array[_rng.Next(array.Length)] + "\"");
			Say(tm.Ped, "CHALLENGE_THREATEN", player);
		}
		if (d < 4f || Game.GameTime - tm.ApproachAt > 25000 || PED.IS_PED_IN_COMBAT(tm.Ped.Handle, player.Handle))
		{
			tm.Approaching = false;
			GrudgeLog($"TOWN {tm.Rec.Name} has it out with you ({d:0} m)");
			EngageTownMan(tm, player);
		}
		else if (Game.GameTime - tm.ApproachAt > 1000 && Game.GameTime / 1000 % 4 == 0)
		{
			TASK.TASK_GO_TO_ENTITY(tm.Ped.Handle, player.Handle, -1, 3f, 1.4f, 0f, 0);
		}
	}

	private bool TownProvoked(int target, bool insult)
	{
		TownMan townMan = TownManFor(target);
		if (townMan == null || townMan.Engaged)
		{
			return false;
		}
		if (!insult)
		{
			ShowSubtitle(townMan.Rec.Name + ": \"" + Taunts.AntagonizeReply(_rng) + "\"");
			return true;
		}
		if (townMan.Disguised)
		{
			townMan.Rec.TimesAntagonized++;
			HiddenSlip(townMan.Rec, "antagonize");
			if (townMan.Disguised)
			{
				ShowSubtitle(townMan.Rec.Name + ": \"" + Taunts.AntagonizeReply(_rng) + "\"");
			}
			SaveRoster();
			return true;
		}
		int allies = townMan.Rec.TimesAntagonized++;
		int hate = townMan.Rec.Hate;
		townMan.Rec.AddHate(5);
		CapScuffle(townMan.Rec, hate);
		float num = OpeningNerve(townMan.Ped, townMan.Rec, out var temper, out var _, out allies, out var _, out var _);
		if (num < 30f)
		{
			int fear = townMan.Rec.Fear;
			townMan.Rec.AddFear(3);
			string[] array = ((!(temper == "Coward")) ? new string[3] { "Not here. Not like this.", "Another time, mister.", "You'll keep. I'm leaving." } : new string[3] { "Not here, mister... not today.", "I- I got no quarrel with you. Not now.", "You ain't worth it. I'm going." });
			ShowSubtitle(townMan.Rec.Name + ": \"" + array[_rng.Next(array.Length)] + "\"");
			GrudgeLog($"TOWN {townMan.Rec.Name} ({temper}) backs down at the words - nerve {num:0}, under 30: he walks off (hate {Delta(hate, townMan.Rec.Hate)}, fear {Delta(fear, townMan.Rec.Fear)})");
			Feed("ANTAGONIZE " + townMan.Rec.Name + " in " + townMan.Town + ": he won't take the bait - he walks off", Theme.Warn, townMan.Rec);
			townMan.Calmed = true;
			KeepOutOfIt(townMan, Game.Player.Character, leave: true);
			SaveRoster();
			return true;
		}
		Feed("ANTAGONIZE " + townMan.Rec.Name + " in " + townMan.Town + ": hate " + Delta(hate, townMan.Rec.Hate) + " -> he fights", Theme.Blood, townMan.Rec);
		if (townMan.EngageAt == 0)
		{
			townMan.EngageAt = Game.GameTime + 2200;
		}
		return true;
	}

	private void EngageTownMan(TownMan tm, Ped player)
	{
		HiddenSlip(tm.Rec, "fight");
		tm.Engaged = true;
		ClaimBack(tm.Ped);
		if (_townFightGroup == 0)
		{
			_townFightGroup = World.AddRelationshipGroup("NEMESIS_TOWN_FIGHT");
		}
		tm.Ped.RelationshipGroup = _townFightGroup;
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _townFightGroup, player.RelationshipGroup);
		tm.Ped.BlockPermanentEvents = true;
		tm.EngagedAt = Game.GameTime;
		tm.StuckTries = 0;
		bool flag = PED.IS_PED_USING_ANY_SCENARIO(tm.Ped.Handle);
		bool flag2 = ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(tm.Ped.Handle, player.Handle, p2: true, p3: true);
		if (flag & flag2)
		{
			Crumbs.Native("TownPresence out of seat");
			TASK.CLEAR_PED_TASKS_IMMEDIATELY(tm.Ped.Handle, p1: false, p2: true);
			GrudgeLog("TOWN " + tm.Rec.Name + " gets up out of his seat to fight (hurt - at once)");
		}
		else if (flag)
		{
			Crumbs.Native("TownPresence out of seat");
			TASK.CLEAR_PED_TASKS(tm.Ped.Handle, p1: false, p2: false);
			GrudgeLog("TOWN " + tm.Rec.Name + " gets up out of his seat to fight");
		}
		if (tm.Blip != null && tm.Blip.Exists())
		{
			tm.Blip.Delete();
		}
		Crumbs.Native("TownPresence blip add (V2)");
		tm.Blip = tm.Ped.AddBlip((BlipType)831283580u);
		if (flag && !flag2)
		{
			QueueFight(tm.Ped, player, 900);
		}
		else
		{
			TASK.TASK_COMBAT_PED(tm.Ped.Handle, player.Handle, 0, 16);
		}
		PED.SET_PED_KEEP_TASK(tm.Ped.Handle, p1: true);
		tm.Rec.TimesAmbushed++;
		tm.Rec.Touch();
		SaveRoster();
		GrudgeLog("TOWN " + tm.Rec.Name + " engaged");
		try
		{
			TownFightReaction(tm.Ped, player, tm.Town, Loadout.BandOf(tm.Rec) == Loadout.Band.Gun);
		}
		catch (Exception ex)
		{
			GrudgeLog("FIGHT town reaction failed: " + ex.Message);
		}
		Feed($"FIGHT {tm.Rec.Name} in {tm.Town} ({tm.Intent})", Theme.Blood, tm.Rec);
	}

	private void UnstickTownFighter(TownMan tm, Ped player, float d)
	{
		int handle = tm.Ped.Handle;
		if (tm.EngagedAt == 0 || tm.StuckTries >= 2 || d < 3f || d > 60f || NerveOut(handle) || _runners.ContainsKey(handle) || tm.Ped.IsHogtied || tm.Ped.IsRagdoll || LooksKnockedOut(tm.Ped) || PED.IS_PED_FLEEING(handle) || (_fighters.TryGetValue(handle, out var value) && (value.Broke || value.Done)) || (PED.IS_PED_IN_COMBAT(handle, player.Handle) && !PED.IS_PED_USING_ANY_SCENARIO(handle)))
		{
			return;
		}
		int num = Game.GameTime - tm.EngagedAt;
		if (tm.StuckTries == 0 && num > 5000)
		{
			tm.StuckTries = 1;
			Crumbs.Native("TownPresence unstick 1");
			TASK.CLEAR_PED_TASKS_IMMEDIATELY(handle, p1: false, p2: true);
			TASK.TASK_COMBAT_PED(handle, player.Handle, 0, 16);
			GrudgeLog(string.Format("TOWN {0} engaged 5 s ago but isn't fighting ({1:0} m, {2}) - pulled out and sent again", tm.Rec.Name, d, PED.IS_PED_USING_ANY_SCENARIO(handle) ? "still in a scenario" : "standing"));
		}
		else
		{
			if (tm.StuckTries != 1 || num <= 10000)
			{
				return;
			}
			tm.StuckTries = 2;
			Vector3 position = tm.Ped.Position;
			bool flag = !Walkable(position) || position.Z - player.Position.Z > 2.5f;
			if (flag)
			{
				Vector3 safeCoordForPed = World.GetSafeCoordForPed(player.Position + (position - player.Position) * 0.5f);
				if (safeCoordForPed != Vector3.Zero && Outdoors(safeCoordForPed) && HiddenFromView(player, safeCoordForPed + new Vector3(0f, 0f, 1f)))
				{
					Crumbs.Native("TownPresence unstick move");
					tm.Ped.Position = safeCoordForPed;
				}
				else
				{
					GrudgeLog("TOWN " + tm.Rec.Name + ": no hidden walkable spot to move him to");
				}
			}
			TASK.CLEAR_PED_TASKS_IMMEDIATELY(handle, p1: false, p2: true);
			TASK.TASK_COMBAT_PED(handle, player.Handle, 0, 16);
			GrudgeLog(string.Format("TOWN {0} still not fighting after 10 s ({1:0} m, {2}) - sent again, last try", tm.Rec.Name, d, flag ? "off the walkways - moved" : "on walkable ground"));
		}
	}

	private unsafe void ClearTownMan(TownMan tm, bool delete)
	{
		if (tm.Blip != null && tm.Blip.Exists())
		{
			tm.Blip.Delete();
		}
		tm.Blip = null;
		if (tm.Ped != null && tm.Ped.Exists())
		{
			if (delete && SafeToDelete(tm.Ped))
			{
				_worldNemeses.Remove(tm.Ped.Handle);
				_knockedOutWorld.Remove(tm.Ped.Handle);
				tm.Ped.Delete();
			}
			else
			{
				int handle = tm.Ped.Handle;
				ReleaseIfOurs(&handle);
			}
		}
		else if (tm.Ped != null)
		{
			_worldNemeses.Remove(tm.Ped.Handle);
			_knockedOutWorld.Remove(tm.Ped.Handle);
		}
		_townMen.Remove(tm);
	}

	private void ClearTownPresence(bool delete)
	{
		foreach (TownMan item in _townMen.ToList())
		{
			ClearTownMan(item, delete);
		}
	}

	internal TownRepParts TownRep(string town)
	{
		if (string.IsNullOrEmpty(town))
		{
			return default;
		}
		if (_townRepCache.TryGetValue(town, out (TownRepParts, int) value) && UiDraw.RealMs - value.Item2 < 1000)
		{
			return value.Item1;
		}
		TownRepParts townRepParts = TownRepNow(town);
		_townRepCache[town] = (townRepParts, UiDraw.RealMs);
		return townRepParts;
	}

	internal int TownReputation(string town)
	{
		return TownRep(town).Rep;
	}

	private TownRepParts TownRepNow(string town)
	{
		TownRepParts result = default;
		List<Acquaintance> list = People.Where((Acquaintance a) => !a.Dead && a.Town == town).ToList();
		result.Known = list.Count;
		float num = 0f;
		float num2 = 0f;
		foreach (Acquaintance item in list)
		{
			float num3 = (float)item.Like + (float)item.Favours * 12f;
			float num4 = ((item.SawFace == false) ? 0f : ((float)Math.Max(item.Grudge, 0))) * (item.GrudgeSettled ? 0.5f : 1f) + (float)item.Fear * (SawFirstHand(item) ? 0.6f : 0.3f);
			num += num3;
			num2 += num4;
			if (num3 - num4 >= 10f)
			{
				result.Liked++;
			}
			else if (num4 - num3 >= 10f)
			{
				result.Disliked++;
			}
		}
		if (Chronicle.TownWord != null && Chronicle.TownWord.TryGetValue(town, out var value))
		{
			num2 += value.Word;
		}
		num2 += Roster.Where((NemesisRecord n) => n.IsAlive && !n.PresumedDead && n.KillLocation == town && n.Origin != GrudgeOrigin.GangMember && !Gangs.Orders(n)).Sum((NemesisRecord n) => (float)n.Hate * 0.8f);
		float num5 = (TownCore(town, out var _, out var radius) ? Math.Max(1f, radius / 130f * (radius / 130f)) : 1f);
		result.Goodwill = (int)Math.Round(100f * (1f - (float)Math.Exp((0f - num) / (120f * num5))));
		result.Illwill = (int)Math.Round(100f * (1f - (float)Math.Exp((0f - num2) / (100f * num5))));
		result.Law = LawPart();
		result.Deeds = ((Chronicle.TownWord != null && Chronicle.TownWord.TryGetValue(town, out var value2)) ? ((int)Math.Round(value2.Good)) : 0);
		result.Rep = Math.Max(-100, Math.Min(100, result.Goodwill - result.Illwill + result.Law + result.Deeds));
		return result;
	}

	private int LawPart()
	{
		int num;
		try
		{
			num = BountyDollars;
		}
		catch
		{
			num = 0;
		}
		return -Math.Min(35, num / 6);
	}

	internal int OverallReputation()
	{
		double num = 0.0;
		double num2 = 0.0;
		foreach (string repTown in RepTowns)
		{
			TownRepParts townRepParts = TownRep(repTown);
			if (townRepParts.Known != 0 || townRepParts.Illwill != 0)
			{
				double num3 = 1 + townRepParts.Known;
				num += (double)townRepParts.Rep * num3;
				num2 += num3;
			}
		}
		if (!(num2 <= 0.0))
		{
			return (int)Math.Round(num / num2);
		}
		return LawPart();
	}

	internal static string RepWord(int r)
	{
		if (r > -60)
		{
			if (r > -20)
			{
				if (r < 60)
				{
					if (r < 20)
					{
						return "Known";
					}
					return "Liked";
				}
				return "Admired";
			}
			return "Disliked";
		}
		return "Hated";
	}

	internal static (int r, int g, int b) RepColor(int r)
	{
		if (r > -60)
		{
			if (r > -20)
			{
				if (r < 20)
				{
					return Theme.Dim;
				}
				return Theme.Good;
			}
			return Theme.Warn;
		}
		return Theme.Blood;
	}

	internal float GoodRepLikeMult(string town)
	{
		int num = TownReputation(town);
		if (num > 0)
		{
			return 1f + (float)num / 200f;
		}
		return 1f;
	}

	internal float GoodRepGrudgeMult(string town)
	{
		int num = TownReputation(town);
		if (num > 0)
		{
			return 1f - (float)num / 300f;
		}
		return 1f;
	}

	internal string TownRepLine(string town)
	{
		TownRepParts townRepParts = TownRep(town);
		return $"{town} {townRepParts.Rep:+0;-0;0} {RepWord(townRepParts.Rep)} (goodwill {townRepParts.Goodwill}, ill will {townRepParts.Illwill}, law {townRepParts.Law}, deeds {townRepParts.Deeds}; {townRepParts.Liked} like you, {townRepParts.Disliked} don't, {townRepParts.Known} known)";
	}

	private static int RepTier(int r)
	{
		if (r < 20)
		{
			if (r > -70)
			{
				if (r > -40)
				{
					if (r > -10)
					{
						return 0;
					}
					return -1;
				}
				return -2;
			}
			return -3;
		}
		return 2;
	}

	private static string RepModifier(int tier)
	{
		if (tier < 2)
		{
			if (tier != -1)
			{
				if (tier != -2)
				{
					if (tier > -3)
					{
						return null;
					}
					return "BLIP_MODIFIER_HOSTILITY_COLOR_3";
				}
				return "BLIP_MODIFIER_HOSTILITY_COLOR_2";
			}
			return "BLIP_MODIFIER_HOSTILITY_COLOR_1";
		}
		return "BLIP_MODIFIER_FRIENDLY";
	}

	private void UpdateTownRepBlips()
	{
		if (Game.GameTime < _nextTownRepBlips || !MapSettled())
		{
			return;
		}
		_nextTownRepBlips = Game.GameTime + 10000;
		if (!Config.TownRepMarkers || _mapHidden)
		{
			ClearTownRepBlips();
			return;
		}
		foreach (string repTown in RepTowns)
		{
			TownRepParts townRepParts = TownRep(repTown);
			string text = null;
			try
			{
				Gang gang = TownHolder(repTown, out var d);
				(Gang, Gang)? tuple = ((d != null) ? WarIn(d) : (((Gang, Gang)?)null));
				if (gang != null && tuple.HasValue)
				{
					text = ShortOutfit(gang) + " town, at war";
				}
			}
			catch
			{
			}
			bool flag = townRepParts.Known > 0 || townRepParts.Illwill > 0;
			if (!flag && text == null)
			{
				DropTownRepBlip(repTown);
			}
			else
			{
				if (!TownCore(repTown, out var centre, out var _))
				{
					continue;
				}
				string s;
				if (text == null)
				{
					s = $"{repTown} - reputation {townRepParts.Rep:+0;-0;0} ({RepWord(townRepParts.Rep)})";
				}
				else
				{
					s = (flag ? $"{repTown} - {text}, rep {townRepParts.Rep:+0;-0;0}" : (repTown + " - " + text));
				}
				string text2 = UiDraw.TheFix(s);
				int num = RepTier(townRepParts.Rep);
				if (_townRepBlips.TryGetValue(repTown, out (int, string, int) value) && !MAP.DOES_BLIP_EXIST(value.Item1))
				{
					_townRepBlips.Remove(repTown);
				}
				if (_townRepBlips.TryGetValue(repTown, out (int, string, int) value2) && value2.Item2 == text2 && value2.Item3 == num)
				{
					continue;
				}
				if (_townRepBlips.TryGetValue(repTown, out value2) && value2.Item3 == num)
				{
					Function.Call(11290983183885202434uL, value2.Item1, new InputArgument(UiDraw.ForeverVarString(text2)));
					_townRepBlips[repTown] = (value2.Item1, text2, num);
					continue;
				}
				DropTownRepBlip(repTown);
				Crumbs.Native("TownRep blip add");
				int num2 = MAP.BLIP_ADD_FOR_COORDS(3911271093u, centre.X, centre.Y, centre.Z);
				Crumbs.Native("TownRep blip sprite");
				try
				{
					MAP.SET_BLIP_SPRITE(num2, MISC.GET_HASH_KEY("blip_town"), p2: true);
				}
				catch
				{
				}
				string text3 = RepModifier(num);
				Crumbs.Native("TownRep blip modifier");
				if (text3 != null)
				{
					try
					{
						Function.Call<bool>(7362600660482055727uL, new InputArgument[2]
						{
							num2,
							MISC.GET_HASH_KEY(text3)
						});
					}
					catch
					{
					}
				}
				Function.Call(11290983183885202434uL, num2, new InputArgument(UiDraw.ForeverVarString(text2)));
				_townRepBlips[repTown] = (num2, text2, num);
				GrudgeLog("REPUTATION map: " + TownRepLine(repTown));
			}
		}
	}

	private unsafe void DropTownRepBlip(string town)
	{
		if (!_townRepBlips.TryGetValue(town, out (int, string, int) value))
		{
			return;
		}
		var (p, _, _) = value;
		Crumbs.Native("TownRep blip remove");
		try
		{
			if (MAP.DOES_BLIP_EXIST(p))
			{
				MAP.REMOVE_BLIP(&p);
			}
		}
		catch
		{
		}
		_townRepBlips.Remove(town);
	}

	internal void ClearTownRepBlips()
	{
		foreach (string item in _townRepBlips.Keys.ToList())
		{
			DropTownRepBlip(item);
		}
	}

	internal void ForgetTownRepBlips()
	{
		bool flag = false;
		try
		{
			flag = CAM.IS_SCREEN_FADED_OUT();
		}
		catch
		{
		}
		if (!flag)
		{
			ClearTownRepBlips();
		}
		else
		{
			_townRepBlips.Clear();
		}
		_nextTownRepBlips = 0;
	}

	private void UpdateTrainRobbery(Ped player)
	{
		if (Game.GameTime < _nextTrainCheck)
		{
			return;
		}
		_nextTrainCheck = Game.GameTime + 1000;
		try
		{
			CheckTrainUnmasked(player);
		}
		catch (Exception ex)
		{
			GrudgeLog("TRAIN unmask check failed: " + ex.Message);
		}
		int num;
		try
		{
			num = LAW.GET_BOUNTY(Game.Player.Handle);
		}
		catch
		{
			return;
		}
		int trainBountyWas = _trainBountyWas;
		_trainBountyWas = num;
		if (Game.GameTime >= _nextTrainScan)
		{
			_nextTrainScan = Game.GameTime + 2000;
			_trainsNear.Clear();
			_trainsAtStation = 0;
			Vector3 position = player.Position;
			bool flag = false;
			try
			{
				flag = PED.IS_PED_IN_ANY_TRAIN(player.Handle);
			}
			catch
			{
			}
			try
			{
				Vehicle[] allVehicles = World.GetAllVehicles();
				foreach (Vehicle vehicle in allVehicles)
				{
					if (vehicle != null && vehicle.Exists() && Function.Call<bool>(18160986468102566260uL, new InputArgument[1] { ENTITY.GET_ENTITY_MODEL(vehicle.Handle) }) && vehicle.Position.DistanceTo(position) < 35f)
					{
						bool flag2 = false;
						try
						{
							flag2 = Function.Call<bool>(16755568960454759414uL, new InputArgument[1] { vehicle.Handle });
						}
						catch
						{
						}
						if (!flag2 | flag)
						{
							_trainsNear.Add(vehicle.Handle);
						}
						else
						{
							_trainsAtStation++;
						}
					}
				}
			}
			catch
			{
			}
		}
		if (_trainsNear.Count == 0)
		{
			_trainNearSince = -1;
		}
		else if (_trainNearSince < 0)
		{
			_trainNearSince = Game.GameTime;
		}
		if (trainBountyWas < 0 || num <= trainBountyWas)
		{
			return;
		}
		string text = TrainNotCounted(player);
		if (text != null)
		{
			if (_trainsNear.Count > 0 || _trainsAtStation > 0)
			{
				GrudgeLog($"TRAIN bounty +${(num - trainBountyWas) / 100} by a train - not a robbery: {text}");
			}
		}
		else
		{
			TrainRobberyCounted(player, num, trainBountyWas);
		}
	}

	private string TrainNotCounted(Ped player)
	{
		if (Game.GameTime - _lastFadeAt < 17000 || Game.GameTime - _lastJumpAt < 30000)
		{
			return "just after a fade / load / fast travel";
		}
		if (_trainsNear.Count == 0)
		{
			return "the only train near stands at its station (and you're not aboard)";
		}
		if (Game.GameTime - _trainNearSince < 15000)
		{
			return $"near the train only {(Game.GameTime - _trainNearSince) / 1000} s (15 s)";
		}
		if (Game.GameTime - _lastTrainRobWhen < 900000 && player.Position.DistanceTo(_lastTrainRobAt) < 300f)
		{
			return "the same robbery (15 min, 300 m)";
		}
		bool flag = false;
		try
		{
			flag = MISC.GET_MISSION_FLAG();
		}
		catch
		{
		}
		if (flag)
		{
			return "a mission";
		}
		foreach (int item in (from kv in _trainsRobbed
			where Game.GameTime - kv.Value > 900000
			select kv.Key).ToList())
		{
			_trainsRobbed.Remove(item);
		}
		if (_trainsNear.Any(_trainsRobbed.ContainsKey))
		{
			return "this train was robbed already";
		}
		return null;
	}

	private void TrainRobberyCounted(Ped player, int bounty, int was)
	{
		foreach (int item in _trainsNear.ToList())
		{
			_trainsRobbed[item] = Game.GameTime;
		}
		_lastTrainRobAt = player.Position;
		_lastTrainRobWhen = Game.GameTime;
		TrainRobbed(player, (bounty - was) / 100);
	}

	private void TrainRobbed(Ped player, int bountyUp)
	{
		Vector3 pos = player.Position;
		bool flag = false;
		try
		{
			flag = PlayerMasked(player);
		}
		catch
		{
		}
		string text = TownNear(pos) ?? NearestRepTown(pos);
		string zoneName = GetZoneName(pos);
		GrudgeLog(string.Format("TRAIN robbed near {0}{1} - bounty +${2}{3}", zoneName, (text != null) ? (" (" + text + ")") : "", bountyUp, flag ? ", masked" : ""));
		WorldEvent deed = null;
		try
		{
			deed = ChronicleDeed("train", flag ? ("A masked man robbed the train near " + zoneName) : ("You robbed the train near " + zoneName), "near " + zoneName, pos, null);
		}
		catch (Exception ex)
		{
			GrudgeLog("TRAIN deed failed: " + ex.Message);
		}
		if (flag)
		{
			_maskedTrain = new MaskedTrainJob
			{
				At = pos,
				When = Game.GameTime,
				Town = text,
				Place = zoneName,
				Deed = deed
			};
		}
		if (text != null)
		{
			Dictionary<string, TownTalk> dictionary = Chronicle.TownWord ?? (Chronicle.TownWord = new Dictionary<string, TownTalk>());
			if (!dictionary.TryGetValue(text, out var value))
			{
				value = (dictionary[text] = new TownTalk());
			}
			float word = value.Word;
			float num = (flag ? 6f : 24f);
			value.Word = Math.Min(100f, value.Word + num * (1f - value.Word / 100f));
			value.LastWordDay = GameDayKey();
			_townWordCache.Remove(text);
			_townRepCache.Remove(text);
			GrudgeLog(string.Format("TRAIN {0} talks of it: word {1:0} -> {2:0}{3}", text, word, value.Word, flag ? " (a masked man - they don't know it was you)" : ""));
			RepNote($"{text}: the train robbery - word {word:0} -> {value.Word:0}");
		}
		foreach (Gang item in Gangs.All.Where((Gang x) => !x.StoryOnly && !x.OrdersNotFeelings && !IsDestroyed(x) && Gangs.InEra(x) && NotorietyOf(x) > 0))
		{
			LowerNotoriety(item, 1, "you robbed a train", "train", 2);
		}
		Gang army = Gangs.Army;
		if (army != null && Gangs.InEra(army) && !IsDestroyed(army))
		{
			AddNotoriety(army, 3, "you robbed a train");
		}
		int num2 = 0;
		try
		{
			foreach (Ped item2 in (from p in PedsAround(player)
				where p != null && p.Exists() && !p.IsDead && p.IsHuman && !p.IsPlayer && !Kids.Protected(p) && p.Position.DistanceTo(pos) < 25f
				orderby p.Position.DistanceTo(pos)
				select p).Take(10).ToList())
			{
				bool flag2 = false;
				try
				{
					flag2 = PED.IS_PED_IN_ANY_TRAIN(item2.Handle);
				}
				catch
				{
				}
				if (flag2 || !(item2.Position.DistanceTo(pos) > 12f))
				{
					OnRobAttempt(item2.Handle);
					num2++;
				}
			}
		}
		catch (Exception ex2)
		{
			GrudgeLog("TRAIN passengers failed: " + ex2.Message);
		}
		GrudgeLog($"TRAIN {num2} aboard held up - a stick-up each");
		SaveWorld();
	}

	private void CheckTrainUnmasked(Ped player)
	{
		MaskedTrainJob maskedTrain = _maskedTrain;
		if (maskedTrain == null)
		{
			return;
		}
		if (Game.GameTime - maskedTrain.When > 600000)
		{
			_maskedTrain = null;
			return;
		}
		bool flag = true;
		try
		{
			flag = PlayerMasked(player);
		}
		catch
		{
		}
		if (flag || player.Position.DistanceTo(maskedTrain.At) > 50f)
		{
			return;
		}
		Vector3 me = player.Position;
		Ped ped = PedsAround(player).FirstOrDefault((Ped p) => p != null && p.Exists() && !p.IsDead && p.IsHuman && !p.IsPlayer && p.Position.DistanceTo(me) < 20f && ENTITY.HAS_ENTITY_CLEAR_LOS_TO_ENTITY(p.Handle, player.Handle, 17));
		if (!(ped == null))
		{
			_maskedTrain = null;
			if (maskedTrain.Deed != null)
			{
				maskedTrain.Deed.Title = "You robbed the train near " + maskedTrain.Place;
				maskedTrain.Deed.Lines.Add("A masked man - until he took the mask off in front of them. They saw your face.");
			}
			if (maskedTrain.Town != null && Chronicle.TownWord != null && Chronicle.TownWord.TryGetValue(maskedTrain.Town, out var value))
			{
				float word = value.Word;
				value.Word = Math.Min(100f, value.Word + 18f * (1f - value.Word / 100f));
				_townWordCache.Remove(maskedTrain.Town);
				_townRepCache.Remove(maskedTrain.Town);
				GrudgeLog($"TRAIN {maskedTrain.Town}: they know it was you - word {word:0} -> {value.Word:0}");
			}
			Gang army = Gangs.Army;
			if (army != null && Gangs.InEra(army) && !IsDestroyed(army))
			{
				AddNotoriety(army, 2, "they saw your face after the train robbery");
			}
			SaveWorld();
			GrudgeLog($"TRAIN unmasked: someone saw your face {ped.Position.DistanceTo(me):0} m off, {player.Position.DistanceTo(maskedTrain.At):0} m from the robbery - the World tab says it was you");
			ReplyNotice("They saw your face. Word is out that you robbed that train.");
		}
	}

	private string NearestRepTown(Vector3 p)
	{
		string result = null;
		float num = float.MaxValue;
		foreach (string repTown in RepTowns)
		{
			if (TownCore(repTown, out var centre, out var _))
			{
				float num2 = new Vector3(p.X - centre.X, p.Y - centre.Y, 0f).Length();
				if (num2 < num)
				{
					num = num2;
					result = repTown;
				}
			}
		}
		if (!(num < 2500f))
		{
			return null;
		}
		return result;
	}

	private static int CapOf(Gang g)
	{
		if (g == null || !g.OrdersNotFeelings)
		{
			return 5000;
		}
		return 12000;
	}

	private double TaperOf(Gang g)
	{
		return Math.Max(0.2, 1.0 - (double)PurseOf(g) / ((g != null && g.OrdersNotFeelings) ? 10000.0 : 2000.0));
	}

	internal bool HasPurse(Gang g)
	{
		if (g != null)
		{
			return !g.StoryOnly;
		}
		return false;
	}

	internal int PurseOf(Gang g)
	{
		if (!HasPurse(g))
		{
			return int.MaxValue;
		}
		if (!Treasury.TryGetValue(g.Id, out var value))
		{
			value = (StartPurse.TryGetValue(g.Id, out var value2) ? value2 : 300);
			Treasury[g.Id] = value;
		}
		return value;
	}

	internal void AddPurse(Gang g, int amount, string why)
	{
		if (!HasPurse(g) || amount == 0 || IsDestroyed(g))
		{
			return;
		}
		if (amount > 0)
		{
			amount = Math.Max(1, (int)Math.Round((double)amount * TaperOf(g)));
		}
		int num = PurseOf(g);
		int num2 = Math.Max(0, Math.Min(CapOf(g), num + amount));
		if (num2 == num)
		{
			return;
		}
		Treasury[g.Id] = num2;
		GrudgeLog($"PURSE {g.Name}: ${num} -> ${num2} ({why})");
		SaveWorld();
		List<string> list = Chronicle.BrokeSaid ?? (Chronicle.BrokeSaid = new List<string>());
		if (num2 < 60 && num >= 60 && !list.Contains(g.Id))
		{
			list.Add(g.Id);
			WorldEvent worldEvent = NewEvent("TURMOIL", GameMinutesNow());
			worldEvent.Gangs.Add(g.Id);
			worldEvent.Title = "The " + g.Name + " are out of money";
			worldEvent.Lines.Add("No pay, no new men - their empty seats will stay empty, and fewer ride with each crew.");
			worldEvent.Heard = true;
			Chronicle.Events.Add(worldEvent);
			if (Config.WorldNews >= 2)
			{
				WorldNotice("The " + g.Name + " are out of money.");
			}
		}
		else if (num2 >= 180 && list.Contains(g.Id))
		{
			list.Remove(g.Id);
		}
	}

	internal static string PurseWord(int v)
	{
		if (v != int.MaxValue)
		{
			if (v >= 60)
			{
				if (v >= 200)
				{
					if (v >= 700)
					{
						if (v >= 1200)
						{
							return "Rich";
						}
						return "Flush";
					}
					return "Steady";
				}
				return "Thin";
			}
			return "Broke";
		}
		return "";
	}

	internal static (int r, int g, int b) PurseColor(int v)
	{
		if (v >= 60)
		{
			if (v >= 200)
			{
				if (v >= 1200)
				{
					return (r: 215, g: 178, b: 95);
				}
				return Theme.Text;
			}
			return Theme.Warn;
		}
		return Theme.Blood;
	}

	internal int PurseCrewShift(Gang g)
	{
		if (!HasPurse(g))
		{
			return 0;
		}
		int num = PurseOf(g);
		int num2 = ((num < 60) ? (-1) : ((num >= 1200) ? 1 : 0));
		if (MenShare(g) < 0.4)
		{
			num2--;
		}
		if (LowSupplies(g))
		{
			num2--;
		}
		return Math.Max(-2, num2);
	}

	internal static int RecruitCost(int tier)
	{
		if (tier != 0)
		{
			return 60;
		}
		return 30;
	}

	internal int HireBudget(Gang g)
	{
		if (!HasPurse(g))
		{
			return int.MaxValue;
		}
		int num = PurseOf(g);
		if (g.OrdersNotFeelings)
		{
			return num;
		}
		double num2;
		if (num < 60)
		{
			num2 = 0.25;
		}
		else if (num < 250)
		{
			num2 = 0.35;
		}
		else
		{
			num2 = ((num < 600) ? 0.4 : 0.5);
		}
		return (int)((double)num * num2);
	}

	private void DailyPurses(int days)
	{
		foreach (Gang g in Gangs.All.Where(HasPurse))
		{
			if (!IsDestroyed(g))
			{
				List<NemesisRecord> list = Roster.Where((NemesisRecord n) => n.Gang == g.Id && n.IsAlive && !n.PresumedDead).ToList();
				int count = list.Count;
				double num = list.Sum((NemesisRecord n) =>
				{
					double result = ((n.Rank < 4) ? ((n.Rank < 2) ? 2.5 : 5.0) : 10.0);
					return result;
				});
				int num2 = WarsOf(g);
				num += (double)(15 * num2);
				int num3 = MenOf(g);
				num += 0.04 * (double)num3 * Math.Min(1.0, 450.0 / (double)Math.Max(1, MenStart(g)));
				double num4 = 15.0 + 60.0 * Math.Min(1.3, TerritoryShare(g));
				if (!g.OrdersNotFeelings)
				{
					num4 *= Math.Max(1.0, Math.Sqrt((double)MenStart(g) / 450.0));
				}
				if (g.OrdersNotFeelings)
				{
					num4 += 250.0;
				}
				if (AgendaOf(g)?.Kind == "rich")
				{
					num4 *= 1.25;
				}
				int num5 = PurseOf(g);
				string text = null;
				if (!g.OrdersNotFeelings && num5 < 60)
				{
					num *= 0.5;
					text = "half pay - they're broke";
				}
				else if (!g.OrdersNotFeelings && num5 < 150)
				{
					num *= 0.75;
					text = "short pay - money's tight";
				}
				int num6 = Math.Min(days, 30);
				double num7 = TaperOf(g);
				int num8 = (int)Math.Round((num4 * num7 - num) * (double)num6);
				try
				{
					BrokeDay(g, num6, num5 + num8);
				}
				catch (Exception ex)
				{
					GrudgeLog("PURSE broke check failed: " + ex.Message);
				}
				if (num8 != 0)
				{
					AddPurseRaw(g, num8, string.Format("{0} day(s): takings from its ground ({1:0}/day), {2} named + {3} men to keep{4} ({5:0}/day{6})", num6, num4 * num7, count, num3, (num2 > 0) ? string.Format(" + {0} war{1}", num2, (num2 == 1) ? "" : "s") : "", num, (text != null) ? (", " + text) : ""));
				}
			}
		}
		try
		{
			DailyHiring(days);
		}
		catch (Exception ex2)
		{
			GrudgeLog("MEN hiring failed: " + ex2.Message);
		}
		try
		{
			DailySupplies(days);
		}
		catch (Exception ex3)
		{
			GrudgeLog("SUPPLIES daily failed: " + ex3.Message);
		}
	}

	private void AddPurseRaw(Gang g, int amount, string why)
	{
		if (amount <= 0)
		{
			AddPurse(g, amount, why);
			return;
		}
		int num = PurseOf(g);
		Treasury[g.Id] = Math.Min(CapOf(g), num + amount);
		GrudgeLog($"PURSE {g.Name}: ${num} -> ${Treasury[g.Id]} ({why})");
		SaveWorld();
	}

	internal void PurseForJob(Gang g, bool ok, bool youThere, bool desperate = false)
	{
		if (!HasPurse(g))
		{
			return;
		}
		if (youThere)
		{
			AddPurse(g, -30, "you broke up its job");
			return;
		}
		if (!ok)
		{
			AddPurse(g, -25, desperate ? "a desperate job that went wrong" : "a job that went wrong");
			return;
		}
		int num = 60 + _rng.Next(81);
		if (AgendaOf(g)?.Kind == "rich")
		{
			num = (int)((double)num * 1.4);
		}
		if (desperate)
		{
			num *= 2;
		}
		AddPurse(g, num, desperate ? "a desperate job that paid" : "a job that paid");
	}

	private void BrokeDay(Gang g, int days, int purseAfter)
	{
		if (g == null || g.OrdersNotFeelings || IsDestroyed(g))
		{
			return;
		}
		BrokeDays.TryGetValue(g.Id, out var value);
		if (purseAfter >= 60)
		{
			if (value > 0)
			{
				BrokeDays[g.Id] = 0;
				GrudgeLog($"PURSE {g.Name}: out of the red after {value} broke day(s)");
			}
			return;
		}
		int num = value + Math.Max(1, days);
		BrokeDays[g.Id] = num;
		if (num >= 3)
		{
			int num2 = (int)Math.Ceiling((double)MenOf(g) * (0.01 + _rng.NextDouble() * 0.01) * (double)Math.Min(days, 7));
			if (num2 > 0)
			{
				LoseMen(g, num2, "unpaid men walked away");
			}
			if (value < 3)
			{
				BrokeEvent(g, "Men are leaving the " + g.Name, $"No pay for {num} days - the {g.Name}'s men are drifting off. More will go until the money comes back.");
			}
		}
		if (value < 5 && num >= 5)
		{
			Dictionary<string, int> nextShakeUp = Chronicle.NextShakeUp;
			if (nextShakeUp != null && nextShakeUp.ContainsKey(g.Id))
			{
				try
				{
					nextShakeUp[g.Id] = GameDate.DayKey(DayOf(GameDayKey()).AddDays(1.0));
				}
				catch
				{
				}
				GrudgeLog($"SUCCESSION {g.Id}: broke {num} days - the men want change, a shake-up tomorrow");
			}
		}
		if (num >= 7 && num % 3 == 1 && _rng.Next(100) < 25)
		{
			BossUnderPressure(g, num);
		}
		SaveWorld();
	}

	private void BossUnderPressure(Gang g, int broke)
	{
		string text = g.LeaderName ?? "the boss";
		NemesisRecord nemesisRecord = (from n in Roster
			where n.Gang == g.Id && n.IsAlive && !n.PresumedDead && OffStage(n) && n.Rank >= 2 && n.Id != SuccessorId(g) && !LoreProtected(n)
			orderby Mind.F(n, "Ambition") descending, n.Rank descending
			select n).FirstOrDefault();
		int num = _rng.Next(100);
		if (num < 50 || nemesisRecord == null)
		{
			Agenda agenda = AgendaOf(g);
			if (agenda?.Kind != "rich")
			{
				Chronicle.Agendas[g.Id] = new Agenda
				{
					Kind = "rich",
					By = text,
					ById = agenda?.ById,
					SetAt = GameMinutesNow(),
					ReviewAt = GameMinutesNow() + 14400
				};
				BrokeEvent(g, text + "'s men lean on him over the empty purse", $"{broke} days without pay. Money comes first now: the {g.Name} mean to get rich.");
				return;
			}
			num = 50;
		}
		if (num < 80 && nemesisRecord != null)
		{
			WorldEvent worldEvent = NewEvent("TURMOIL", GameMinutesNow());
			worldEvent.Gangs.Add(g.Id);
			worldEvent.Title = nemesisRecord.Name + " talked against " + text + " - and paid for it";
			WorldPart worldPart = PartFor(nemesisRecord, "PUT DOWN", "spoke against the boss");
			worldEvent.People.Add(worldPart);
			OffscreenDeath(nemesisRecord, worldEvent, worldPart, text + "'s men", gun: true);
			worldEvent.Lines.Add($"{broke} days without pay, and {nemesisRecord.Name} said so once too often.");
			worldEvent.Heard = true;
			Chronicle.Events.Add(worldEvent);
			GrudgeLog($"PURSE {g.Name}: broke {broke} days - {nemesisRecord.Name} moved against {text} and was put down");
		}
		else
		{
			int num2 = 100 + _rng.Next(101);
			AddPurse(g, num2, text + " paid his men out of his own pocket");
			BrokeDays[g.Id] = 0;
			BrokeEvent(g, text + " pays the " + g.Name + " out of his own pocket", $"{broke} days without pay - he dug into his own stash (${num2}) to keep them.");
		}
	}

	private void BrokeEvent(Gang g, string title, string line)
	{
		WorldEvent worldEvent = NewEvent("TURMOIL", GameMinutesNow());
		worldEvent.Gangs.Add(g.Id);
		worldEvent.Title = title;
		worldEvent.Lines.Add(line);
		worldEvent.Heard = true;
		Chronicle.Events.Add(worldEvent);
		GrudgeLog("PURSE " + g.Name + ": " + title + " - " + line);
		Feed("WORLD " + title, Theme.Warn);
	}

	internal void PurseForClash(Gang winner, Gang loser)
	{
		AddPurse(winner, 20 + _rng.Next(31), "loot from a clash with the " + loser?.Name);
		AgendaClashWon(winner, loser);
		AddPurse(loser, -(20 + _rng.Next(21)), "lost a clash to the " + winner?.Name);
	}

	internal void PurseRobbed(int victim)
	{
		if (!_purseRobbedAt.TryGetValue(victim, out var value) || Game.GameTime - value >= 10000)
		{
			Gang g = Gangs.ById(RecordAt(victim)?.Gang) ?? ((Entity.FromHandle(victim) is Ped ped && ped.Exists()) ? Gangs.ForModel((uint)ped.Model.Hash) : null);
			if (HasPurse(g))
			{
				_purseRobbedAt[victim] = Game.GameTime;
				AddPurse(g, -(10 + _rng.Next(21)), "you robbed one of its men");
			}
		}
	}

	internal void PurseCampCleared(Gang g, string label)
	{
		if (HasPurse(g))
		{
			int num = PurseOf(g);
			AddPurse(g, -Math.Max(40, num / 5), "you cleared " + label + " - what they kept there is gone");
		}
	}

	internal string PurseLine()
	{
		return "purses: " + string.Join(", ", from g in Gangs.All
			where HasPurse(g) && !IsDestroyed(g)
			select $"{g.Id} ${PurseOf(g)} ({PurseWord(PurseOf(g))})");
	}

	private NemesisRecord HolderOf(CampSite s)
	{
		if (s != null)
		{
			return (from n in Roster
				where n.CampId == s.Id && Mans(n)
				orderby n.Rank descending
				select n).FirstOrDefault();
		}
		return null;
	}

	private void UpdateTreasuries(Ped player)
	{
		if (Config.CampsEnabled)
		{
			UpdateStashes(player);
			UpdateStrongboxes(player);
		}
	}

	internal bool RevealTreasury(Gang g, string from)
	{
		CampSite campSite = TreasuryOf(g);
		if (campSite == null || TreasuryKnown(g))
		{
			return false;
		}
		Hold.KnowTreasury(g);
		SaveWorld();
		NemesisRecord nemesisRecord = HolderOf(campSite);
		if (nemesisRecord != null && !nemesisRecord.CampKnown)
		{
			RevealCamp(nemesisRecord, found: false);
		}
		RedoCampBlip(campSite.Id);
		RefreshStashBlips();
		try
		{
			FlashCampBlip(campSite.Id);
		}
		catch
		{
		}
		GrudgeLog("TREASURY " + g.Name + ": you know it now - " + campSite.Label + " (from " + from + ")");
		ReplyNotice("INTEL: the " + g.Name + " keep their money at " + campSite.Label + ". Marked on your map.");
		Feed("TREASURY " + g.Name + ": " + campSite.Label, Theme.Gold);
		return true;
	}

	private (Acquaintance a, Gang g, CampSite site) TreasuryTraitor()
	{
		foreach (Acquaintance item in from _ in People
			where !_.Dead && _.Id != null && _.Like >= 40
			orderby _rng.Next()
			select _)
		{
			Gang gang = Gangs.ById(item.Affil) ?? Gangs.ForModel(item.Model);
			if (gang != null && HoldsCamps(gang) && !TreasuryKnown(gang) && !TreasuryRobbedNow(gang))
			{
				CampSite campSite = TreasuryOf(gang);
				if (campSite != null)
				{
					return (a: item, g: gang, site: campSite);
				}
			}
		}
		return (a: null, g: null, site: null);
	}

	private void SpawnStrongboxes(CampSite site)
	{
		Gang gang = TreasuryGangOf(site);
		if (gang == null)
		{
			return;
		}
		LiveTreasury liveTreasury = new LiveTreasury
		{
			SiteId = site.Id,
			Gang = gang
		};
		_liveTreasuries[site.Id] = liveTreasury;
		if (TreasuryRobbedNow(gang))
		{
			GrudgeLog("TREASURY " + gang.Name + ": " + site.Label + " - you emptied it; nothing in it until they move it");
			return;
		}
		int num = (int)((double)PurseOf(gang) * 0.4);
		if (num < 20)
		{
			GrudgeLog($"TREASURY {gang.Name}: {site.Label} - the purse is too thin to fill a box (${PurseOf(gang)})");
			return;
		}
		int num2 = ((num >= 150) ? 3 : 2);
		int num3 = 0;
		Vector3 vector = Kit.Centre(site);
		double num4 = _rng.NextDouble() * Math.PI * 2.0;
		for (int i = 0; i < num2; i++)
		{
			double num5 = num4 + (double)i * (Math.PI * 2.0 / (double)num2) + (_rng.NextDouble() - 0.5) * 0.6;
			float num6 = 4.5f + (float)_rng.NextDouble() * 2f;
			Vector3 vector2 = Vector3.Zero;
			for (int j = 0; j < 8; j++)
			{
				if (!(vector2 == Vector3.Zero))
				{
					break;
				}
				Vector3 vector3 = GroundOnSpot(vector + new Vector3((float)Math.Cos(num5 + (double)j * 0.5) * (num6 + (float)j * 0.3f), (float)Math.Sin(num5 + (double)j * 0.5) * (num6 + (float)j * 0.3f), 0f));
				if (vector3 != Vector3.Zero && Kit.ClearOf(site.Id, vector3, 0.8f))
				{
					vector2 = vector3;
				}
			}
			if (!(vector2 == Vector3.Zero))
			{
				int num7 = MakeStrongbox(vector2);
				if (num7 == 0)
				{
					break;
				}
				int num8 = ((i == num2 - 1) ? (num - num3) : ((int)((float)num / (float)num2 * (0.8f + (float)_rng.NextDouble() * 0.4f))));
				num3 += num8;
				liveTreasury.Boxes.Add(new Strongbox
				{
					Obj = num7,
					Amount = Math.Max(1, num8),
					At = vector2
				});
			}
		}
		GrudgeLog(string.Format("TREASURY {0}: {1} - {2} strongboxes ({3}), ${4} of their ${5}", gang.Name, site.Label, liveTreasury.Boxes.Count, _boxModel ?? "none", liveTreasury.Boxes.Sum((Strongbox b) => b.Amount), PurseOf(gang)));
	}

	private int MakeStrongbox(Vector3 at)
	{
		string[] array = ((_boxModel == null) ? StrongboxModels : new string[1] { _boxModel });
		foreach (string text in array)
		{
			Model m = new Model(text);
			if (m.IsValid && m.IsInCdImage && LoadModelSafe(m, 1500))
			{
				Crumbs.Native("treasury: create box");
				int num = OBJECT.CREATE_OBJECT((uint)m.Hash, at.X, at.Y, at.Z, p4: false, p5: false, p6: false, p7: false, p8: true);
				STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED((uint)m.Hash);
				if (num != 0)
				{
					OBJECT.PLACE_OBJECT_ON_GROUND_PROPERLY(num, p1: false);
					ENTITY.SET_ENTITY_HEADING(num, _rng.Next(360));
					ENTITY.FREEZE_ENTITY_POSITION(num, p1: true);
					ENTITY.SET_ENTITY_AS_MISSION_ENTITY(num, p1: true, p2: true);
					_boxModel = text;
					return num;
				}
			}
		}
		if (!_boxModelLogged)
		{
			_boxModelLogged = true;
			GrudgeLog("TREASURY none of the strongbox models could be made: " + string.Join(", ", StrongboxModels));
		}
		return 0;
	}

	private unsafe void DespawnStrongboxes(string siteId)
	{
		ClearObjectives(siteId);
		if (siteId == null || !_liveTreasuries.TryGetValue(siteId, out var value))
		{
			return;
		}
		_liveTreasuries.Remove(siteId);
		if (_boxOpening != null && value.Boxes.Contains(_boxOpening))
		{
			_boxOpening = null;
		}
		foreach (Strongbox box in value.Boxes)
		{
			int obj = box.Obj;
			box.Obj = 0;
			if (obj != 0 && ENTITY.DOES_ENTITY_EXIST(obj))
			{
				Crumbs.Native("treasury: delete box");
				OBJECT.DELETE_OBJECT(&obj);
			}
		}
	}

	private void UpdateStrongboxes(Ped player)
	{
		if (_liveTreasuries.Count == 0)
		{
			HideBoxPrompt();
			return;
		}
		if (_boxOpening != null)
		{
			if (player.IsDead || player.Position.DistanceTo(_boxOpening.At) > 2.6f || !_liveTreasuries.ContainsValue(_boxOpeningIn))
			{
				GrudgeLog("TREASURY you left the strongbox before it was open");
				_boxOpening = null;
			}
			else if (Game.GameTime >= _boxOpenUntil)
			{
				Strongbox boxOpening = _boxOpening;
				LiveTreasury boxOpeningIn = _boxOpeningIn;
				_boxOpening = null;
				try
				{
					TASK.CLEAR_PED_TASKS(player.Handle, p1: false, p2: false);
				}
				catch
				{
				}
				OpenStrongbox(boxOpeningIn, boxOpening, player);
			}
			return;
		}
		if (player.IsDead || player.IsInVehicle || player.IsOnMount || _menu.IsOpen || _convo != null || _tg != null || _interro != null)
		{
			HideBoxPrompt();
			return;
		}
		Strongbox near = null;
		LiveTreasury liveTreasury = null;
		float num = 1.9f;
		foreach (LiveTreasury value2 in _liveTreasuries.Values)
		{
			foreach (Strongbox box in value2.Boxes)
			{
				if (!box.Opened && box.Obj != 0)
				{
					float num2 = player.Position.DistanceTo(box.At);
					if (num2 < num)
					{
						num = num2;
						near = box;
						liveTreasury = value2;
					}
				}
			}
		}
		if (near == null)
		{
			HideBoxPrompt();
			return;
		}
		if (_pBox == 0 || !PromptValid(_pBox))
		{
			_pBox = MakePrompt((eInputType)1980406895u, "Break It Open", hold: true, 8280593);
			_boxArmed = false;
		}
		HUD._UI_PROMPT_SET_VISIBLE(_pBox, p1: true);
		HUD._UI_PROMPT_SET_ENABLED(_pBox, p1: true);
		Function.Call(14292813145410643495uL, 8280593u, new InputArgument(UiDraw.VarString("Strongbox")), 0, 0, 0, 0);
		if (!HUD._UI_PROMPT_HAS_HOLD_MODE_COMPLETED(_pBox))
		{
			_boxArmed = true;
		}
		else if (_boxArmed)
		{
			_boxArmed = false;
			HideBoxPrompt();
			ENTITY.SET_ENTITY_HEADING(player.Handle, HeadingTo(player.Position, near.At));
			Crumbs.Native("treasury: crouch");
			TASK.TASK_START_SCENARIO_IN_PLACE_HASH(player.Handle, MISC.GET_HASH_KEY("WORLD_HUMAN_CROUCH_INSPECT"), 0, p3: true, 0u, -1f, p6: false);
			_boxOpening = near;
			_boxOpeningIn = liveTreasury;
			_boxOpenUntil = Game.GameTime + 2500;
			if (_liveCamps.TryGetValue(liveTreasury.SiteId, out var value) && !value.Engaged && value.Peds.Any((Ped p) => p.Exists() && !p.IsDead && !LooksKnockedOut(p) && p.Position.DistanceTo(near.At) < 35f))
			{
				GrudgeLog("TREASURY " + liveTreasury.Gang.Name + ": they heard you at the strongbox - the camp turns on you");
				EngageCamp(value, player);
			}
		}
	}

	private void OpenStrongbox(LiveTreasury lt, Strongbox box, Ped player)
	{
		if (box.Opened)
		{
			return;
		}
		box.Opened = true;
		Gang gang = lt.Gang;
		CampSite campSite = Camps.ById(lt.SiteId);
		int num = Math.Max(0, Math.Min(box.Amount, PurseOf(gang)));
		bool flag = !TreasuryRobbedNow(gang);
		if (num > 0)
		{
			AddPurse(gang, -num, "you robbed their treasury at " + campSite?.Label);
			PayPlayer(num * 100);
			lt.Taken += num;
		}
		int num2 = Enumerable.Count(lt.Boxes, (Strongbox b) => !b.Opened && b.Obj != 0);
		GrudgeLog($"TREASURY {gang.Name}: you broke a strongbox open - ${num} (${lt.Taken} so far, {num2} left)");
		GrudgeNotice((num > 0) ? $"${num} from the {MemberWord(gang)} strongbox." : "The strongbox is empty.");
		Feed(string.Format("TREASURY ${0} from the {1} strongbox{2}", num, OutfitPoss(gang), (num2 > 0) ? $" - {num2} more" : ""), Theme.Gold);
		if (flag)
		{
			Hold.RecordRobbery(gang, lt.SiteId);
			try
			{
				RefreshStashBlips();
			}
			catch
			{
			}
			SaveWorld();
			AddNotoriety(gang, 6, "you robbed their treasury");
			NemesisRecord nemesisRecord = ((campSite != null) ? (HolderOf(campSite) ?? (_liveCamps.TryGetValue(campSite.Id, out var value) ? value.Boss : null)) : null);
			if (nemesisRecord != null)
			{
				nemesisRecord.AddHate(15);
				History(nemesisRecord, "ROBBED: you broke open the strongboxes he kept at " + campSite.Label, Theme.Blood);
				SaveRoster();
			}
			try
			{
				ChronicleDeed("treasury", "You robbed the " + OutfitPoss(gang) + " treasury", (campSite != null) ? ("at " + campSite.Label) : "", (campSite != null) ? new Vector3?(SitePos(campSite)) : ((Vector3?)null), gang.Id);
			}
			catch (Exception ex)
			{
				GrudgeLog("TREASURY deed failed: " + ex.Message);
			}
			if (campSite != null)
			{
				RedoCampBlip(campSite.Id);
			}
		}
	}

