	{
		if (_pBox != 0 && PromptValid(_pBox))
		{
			HUD._UI_PROMPT_SET_VISIBLE(_pBox, p1: false);
			HUD._UI_PROMPT_SET_ENABLED(_pBox, p1: false);
		}
