	private void Liking(int handle, GrudgeAction a)
	{
		if (a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet)
		{
			try
			{
				NoteGreetScene(handle);
			}
			catch
			{
			}
		}
		if (a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet)
		{
			try
			{
				NoteGreetReply(handle);
			}
			catch
			{
			}
		}
		if (a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet || a == GrudgeAction.Insult || a == GrudgeAction.Taunt)
		{
			PressedAfterLeaving(handle, a);
		}
		if ((a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet || a == GrudgeAction.Defuse) && _likeGreetAt.TryGetValue(handle, out var value) && Game.GameTime - value < 300000)
		{
			return;
		}
		if (a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet || a == GrudgeAction.Defuse)
		{
			_likeGreetAt[handle] = Game.GameTime;
		}
		int num;
		switch (a)
		{
		default:
			num = ((CrimeOf(a) != null) ? (-20) : 0);
			break;
		case GrudgeAction.Insult:
		case GrudgeAction.Taunt:
			num = -5;
			break;
		case GrudgeAction.Defuse:
			num = 4;
			break;
		case GrudgeAction.EmoteGreet:
			num = 3;
			break;
		case GrudgeAction.Greet:
			num = 4;
			break;
		}
		int num2 = num;
		if (num2 == 0)
		{
			return;
		}
		if (!_acqOf.ContainsKey(handle))
		{
			RememberPerson(handle, a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet);
		}
		if (!_acqOf.TryGetValue(handle, out var value2))
		{
			return;
		}
		if (a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet || a == GrudgeAction.Defuse)
		{
			int num3 = GameDate.TodayKey();
			if (value2.LastGreetDay != num3)
			{
				value2.LastGreetDay = num3;
				num2 = Math.Max(num2, 5);
			}
		}
		num2 = LikeDelta(handle, num2);
		if (num2 > 0)
		{
			num2 = (int)Math.Round((float)num2 * GoodRepLikeMult(value2.Town));
		}
		int like = value2.Like;
		value2.Like = Math.Max(0, Math.Min(100, value2.Like + num2));
		if (value2.Like != like)
		{
			_peopleDirty = true;
			GrudgeLog($"LIKE {value2.Name}: {like} -> {value2.Like} ({a})");
			RepNote($"LIKE {value2.Name}: {like} to {value2.Like} ({a})");
		}
		SpreadLiking(value2, like);
		if (a == GrudgeAction.Greet || a == GrudgeAction.EmoteGreet)
		{
			NervousGreet(handle);
		}
	}

	internal void LikeBy(int handle, int delta, string why)
	{
		if (_acqOf.TryGetValue(handle, out var value))
		{
			delta = LikeDelta(handle, delta);
			int like = value.Like;
			value.Like = Math.Max(0, Math.Min(100, value.Like + delta));
			if (value.Like != like)
			{
				_peopleDirty = true;
				GrudgeLog($"LIKE {value.Name}: {like} -> {value.Like} ({why})");
				RepNote($"LIKE {value.Name}: {like} to {value.Like} ({why})");
			}
			SpreadLiking(value, like);
		}
	}

	private void SpreadLiking(Acquaintance acq, int before)
	{
		if (acq == null || acq.LikeSpread || before >= 40 || acq.Like < 40 || acq.Circle == null)
		{
			return;
		}
		acq.LikeSpread = true;
		_peopleDirty = true;
		List<string> list = new List<string>();
		foreach (string key in acq.Circle)
		{
			Acquaintance acquaintance = People.FirstOrDefault((Acquaintance x) => x.Id == key && !x.Dead);
			if (acquaintance != null && acquaintance != acq)
			{
				int like = acquaintance.Like;
				acquaintance.Like = Math.Min(100, acquaintance.Like + 5);
				if (acquaintance.Like != like)
				{
					list.Add($"{acquaintance.Name} {like} -> {acquaintance.Like}");
				}
			}
		}
		if (list.Count > 0)
		{
			GrudgeLog("LIKE " + acq.Name + " speaks well of you to his friends: " + string.Join(", ", list));
		}
	}

	private static float CardBarStep(float s)
	{
		return 0.011407407f;
	}

	private static float CardBarsHeight(float s, float fear, float like, float hate)
	{
		int num = ((fear >= 1f) ? 1 : 0) + ((like >= 1f) ? 1 : 0) + ((hate >= 1f) ? 1 : 0);
		if (num != 0)
		{
			return (float)num * CardBarStep(s) + 0.004f + ((hate >= 1f) ? (0.012f * (s / 0.25f)) : 0f);
		}
		return 0f;
	}

	private string HateBarWhy(NemesisRecord rec, Provocation p)
	{
		if (rec != null)
		{
			HistoryEntry historyEntry = rec.History?.LastOrDefault();
			if (historyEntry == null)
			{
				return null;
			}
			TimeSpan t = DateTime.Now - historyEntry.At;
			return Trim(historyEntry.Text, 34) + " - " + Ago(t) + " ago";
		}
		if (p == null || p.Ledger.Count == 0)
		{
			return null;
		}
		int num = Math.Max(0, (Game.GameTime - p.LastActionAt) / 1000);
		return Trim(p.Ledger[p.Ledger.Count - 1], 30) + " - " + ((num < 60) ? (num + " s") : (num / 60 + " min")) + " ago";
	}

	private static string Trim(string t, int n)
	{
		if (!string.IsNullOrEmpty(t))
		{
			if (t.Length > n)
			{
				return t.Substring(0, n - 1) + "...";
			}
			return t;
		}
		return "";
	}

	private void DrawCardBars(float x, float y, float s, int a, float fear, float like, float hate, bool nemesis, string why = null)
	{
		if (fear < 1f && like < 1f && hate < 1f)
		{
			return;
		}
		float w = 0.046f * (s / 0.25f);
		float h = 0.0037037036f;
		float num = 0.026f * (s / 0.25f);
		float left = x - (w + num) / 2f;
		float bx = left + num;
		float yy = y + 0.006f;
		if (fear >= 1f)
		{
			Bar("FEAR", fear, (r: 120, g: 160, b: 235));
		}
		if (like >= 1f)
		{
			Bar("LIKES", like, (r: 110, g: 200, b: 110));
		}
		if (hate >= 1f)
		{
			(int, int, int) c = (nemesis ? UiDraw.HateColor(Hate.TierOf((int)hate)) : GrudgeColor(hate));
			Bar(nemesis ? "HATE" : "DISLIKE", hate, c);
			if (!string.IsNullOrEmpty(why))
			{
				float scale = 0.14f * (s / 0.25f);
				UiDraw.Text(why, x - Theme.MixedWidth(why, scale, 0.0222f) / 2f, yy - 0.003f, scale, c.Item1, c.Item2, c.Item3, (int)((float)a * 0.85f));
			}
		}
		void Bar(string label, float v, (int r, int g, int b) tuple)
		{
			UiDraw.Text(label, left, yy - 0.0045f, 0.15f * (s / 0.25f), tuple.r, tuple.g, tuple.b, (int)((float)a * 0.9f));
			UiDraw.Rect(bx, yy, w, h, 15, 15, 18, (int)((float)a * 0.75f));
			UiDraw.Rect(bx, yy, w * Math.Min(1f, v / 100f), h, tuple.r, tuple.g, tuple.b, a);
			yy += CardBarStep(s);
		}
	}

	internal void NoteMaskedWitness(Ped p, string crime, string text, int fear, Vector3 at)
	{
		if (!(p == null) && p.Exists() && (!_maskedSeen.TryGetValue(p.Handle, out var value) || value.Fear < fear || Game.GameTime - value.At >= 600000))
		{
			_maskedSeen[p.Handle] = new MaskedSighting
			{
				Crime = crime,
				Text = text,
				Fear = fear,
				At = Game.GameTime,
				Where = at
			};
		}
	}

	private void UpdateUnmasking(Ped player)
	{
		if (Game.GameTime < _nextUnmaskCheck)
		{
			return;
		}
		_nextUnmaskCheck = Game.GameTime + 500;
		foreach (int item in (from kv in _maskedSeen
			where Game.GameTime - kv.Value.At > 600000
			select kv.Key).ToList())
		{
			_maskedSeen.Remove(item);
		}
		bool flag;
		try
		{
			flag = PlayerMasked(player);
		}
		catch
		{
			return;
		}
		if (flag)
		{
			return;
		}
		_ = player.Position;
		foreach (KeyValuePair<int, MaskedSighting> item2 in _maskedSeen.ToList())
		{
			Ped ped = Entity.FromHandle(item2.Key) as Ped;
			if (ped == null || !ped.Exists() || ped.IsDead)
			{
				_maskedSeen.Remove(item2.Key);
			}
			else if (SeesYourFace(ped, player))
			{
				_maskedSeen.Remove(item2.Key);
				Recognised(ped, player, item2.Value);
			}
		}
		foreach (KeyValuePair<int, Provocation> item3 in _provoked.ToList())
		{
			Provocation value = item3.Value;
			if (value.SawFace || !value.SeenMasked || value.Record != null || Game.GameTime - value.LastActionAt > 600000)
			{
				continue;
			}
			Ped ped2 = Entity.FromHandle(item3.Key) as Ped;
			if (!(ped2 == null) && ped2.Exists() && !ped2.IsDead && SeesYourFace(ped2, player))
			{
				value.SawFace = true;
				if (_acqOf.TryGetValue(item3.Key, out var value2))
				{
					value2.SawFace = true;
					_peopleDirty = true;
				}
				bool settled = value.Settled;
				if (settled)
				{
					value.Settled = false;
					value.LastActionAt = Game.GameTime - Balance.GsSettleSeconds * 1000;
				}
				GrudgeLog(string.Format("UNMASKED {0} saw your face - the masked man was you (grudge {1:0}{2})", WhoIs(item3.Key), value.Score, settled ? ", decides again" : ""));
				Feed(Pron.Her($"UNMASKED {WhoIs(item3.Key)} saw your face - he knows it was you (grudge {value.Score:0})", Pron.FemaleAt(item3.Key)), Theme.Warn);
				OutfitLearnsYourName(ped2, WhoIs(item3.Key));
			}
		}
	}

	private static bool SeesYourFace(Ped p, Ped player)
	{
		float num = p.Position.DistanceTo(player.Position);
		if (num > 20f)
		{
			return false;
		}
		if (!(num < 4f))
		{
			return ENTITY.HAS_ENTITY_CLEAR_LOS_TO_ENTITY_IN_FRONT(p.Handle, player.Handle, 17);
		}
		return true;
	}

	private void Recognised(Ped p, Ped player, MaskedSighting s)
	{
		NemesisRecord nemesisRecord = RecordAt(p.Handle);
		if (nemesisRecord != null)
		{
			int fear = nemesisRecord.Fear;
			nemesisRecord.AddFear(Math.Max(1, s.Fear / 3));
			History(nemesisRecord, "SAW YOUR FACE - the masked man who " + s.Text.Replace("saw you ", "") + " was you", Theme.Warn);
			GrudgeLog($"UNMASKED {nemesisRecord.Name} (nemesis) saw your face - fear {fear} -> {nemesisRecord.Fear}");
			Feed($"UNMASKED {nemesisRecord.Name} saw your face - fear {fear} -> {nemesisRecord.Fear}", Theme.Warn, nemesisRecord);
			OutfitLearnsYourName(p, nemesisRecord.Name);
			return;
		}
		if (!_named.ContainsKey(p.Handle) && LookReadable(p))
		{
			_named[p.Handle] = NameByLook(p);
			_namesGiven++;
		}
		_rememberingWitness = true;
		try
		{
			RememberPerson(p.Handle, met: false);
		}
		finally
		{
			_rememberingWitness = false;
		}
		if (_acqOf.TryGetValue(p.Handle, out var value))
		{
			float num = ShadowOf(p).FearGainMult * Balance.FearGainScale;
			int fear2 = value.Fear;
			value.Fear = Math.Min(100, value.Fear + Math.Max(1, (int)Math.Round((float)s.Fear * num)));
			value.LastScaredMin = GameMinutesNow();
			value.SawFace = true;
			(value.Witnessed ?? (value.Witnessed = new List<string>())).Add(s.Text + " (masked) - then saw your face - " + GetZoneName(s.Where) + ", " + GameDateShort());
			TrimWitnessed(value);
			_peopleDirty = true;
			MarkNamed(p.Handle, 3);
			NoteWitness(p.Handle, value, s.Text);
			GrudgeLog(string.Format("UNMASKED {0} saw your face - the masked man who {1} was you: fear {2} -> {3}", value.Name, s.Text.Replace("saw you ", ""), fear2, value.Fear));
			Feed(Pron.Her($"UNMASKED {value.Name} saw your face - he knows it was you (fear {fear2} -> {value.Fear})", Pron.FemaleAt(p.Handle)), Theme.Warn);
			OutfitLearnsYourName(p, value.Name);
		}
	}

	private void OutfitLearnsYourName(Ped p, string who)
	{
		Gang gang = Gangs.ById(RecordAt(p.Handle)?.Gang) ?? Gangs.ForModel((uint)p.Model.Hash);
		if (gang != null && Chronicle.MaskedWithheld != null && Chronicle.MaskedWithheld.TryGetValue(gang.Id, out var value) && !(value < 0.5f))
		{
			Chronicle.MaskedWithheld[gang.Id] = 0f;
			SaveWorld();
			AddNotoriety(gang, (int)Math.Round(value), who + " knows the masked man was you");
		}
	}

	internal void FaceSeenInQuestioning(Ped p, Ped player)
	{
		if (p == null || !p.Exists())
		{
			return;
		}
		bool flag;
		try
		{
			flag = PlayerMasked(player);
		}
		catch
		{
			return;
		}
		if (flag)
		{
			return;
		}
		_maskedSeen.TryGetValue(p.Handle, out var value);
		if (value != null)
		{
			_maskedSeen.Remove(p.Handle);
			Recognised(p, player, value);
		}
		Provocation provocation = ((RecordAt(p.Handle) == null) ? RememberStranger(p.Handle) : null);
		if (provocation != null && !provocation.SawFace)
		{
			provocation.SawFace = true;
			if (provocation.Settled && provocation.Score > 0f)
			{
				provocation.Settled = false;
				provocation.LastActionAt = Game.GameTime - Balance.GsSettleSeconds * 1000;
			}
			GrudgeLog($"UNMASKED {WhoIs(p.Handle)} has seen your face - you questioned him barefaced (grudge {provocation.Score:0})");
			if (provocation.SeenMasked)
			{
				OutfitLearnsYourName(p, WhoIs(p.Handle));
			}
		}
		if (_acqOf.TryGetValue(p.Handle, out var value2) && value2.SawFace != true)
		{
			value2.SawFace = true;
			_peopleDirty = true;
		}
	}

	private WorldEvent SimVanDerLinde(long now)
	{
		string[] array = new string[7] { "Valentine", "Rhodes", "Saint Denis", "Strawberry", "Annesburg", "Van Horn", "Blackwater" };
		string text = array[_rng.Next(array.Length)];
		bool flag = Gangs.Era >= 1907;
		string text2 = (flag ? VdlRumours1907[_rng.Next(VdlRumours1907.Length)] : VdlRumours[_rng.Next(VdlRumours.Length)]);
		if (!text2.Contains("{t}") && text2.Contains("Rhodes"))
		{
			text = "Rhodes";
		}
		WorldEvent worldEvent = NewEvent("VDL", now);
		worldEvent.Gangs.Add("vdl");
		worldEvent.Title = text2.Replace("{t}", text);
		worldEvent.Place = "in " + text;
		if (TownCore(text, out var centre, out var _))
		{
			worldEvent.HasPos = true;
			worldEvent.X = centre.X;
			worldEvent.Y = centre.Y;
			worldEvent.Z = centre.Z;
		}
		NemesisRecord nemesisRecord = (flag ? null : (from _ in Roster
			where _.Gang == Gangs.ODriscolls.Id && _.IsAlive && OffStage(_)
			orderby _rng.Next()
			select _).FirstOrDefault());
		if (nemesisRecord != null && _rng.Next(100) < 50)
		{
			worldEvent.Gangs.Add(nemesisRecord.Gang);
			WorldPart worldPart = PartFor(nemesisRecord, "SWORE ON IT", "Dutch's boys will pay");
			worldEvent.People.Add(worldPart);
			AddThought(nemesisRecord, "Bitter", "Dutch van der Linde's gang", -2, 48, now, worldPart);
			int hate = nemesisRecord.Hate;
			nemesisRecord.Hate = Math.Min(100, nemesisRecord.Hate + 2);
			CapScuffle(nemesisRecord, hate);
			worldPart.Effects.Add($"hate {hate} -> {nemesisRecord.Hate}");
		}
		return worldEvent;
	}

	private void UpdateMissionDeeds(Ped player)
	{
		if (!_oldMissionDeedsCleared)
		{
			_oldMissionDeedsCleared = true;
			int num = Chronicle.Events.RemoveAll((WorldEvent e) => e.Kind == "YOU" && e.Title == "You rode with the gang");
			if (num > 0)
			{
				SaveWorld();
				GrudgeLog($"VDL {num} old 'You rode with the gang' entries taken out of the World tab");
			}
		}
		bool mISSION_FLAG = MISC.GET_MISSION_FLAG();
		if (mISSION_FLAG && !_missionOn)
		{
			_missionSince = Game.GameTime;
			_missionStartPos = player.Position;
			_missionTrail.Clear();
			_missionTrailAt = 0;
			_missionCast.Clear();
		}
		if (mISSION_FLAG && Game.GameTime - _missionTrailAt > 5000 && _missionTrail.Count < 400)
		{
			_missionTrail.Add(player.Position);
			_missionTrailAt = Game.GameTime;
			Vector3 position = player.Position;
			foreach (KeyValuePair<int, Named> item in _named.Where((KeyValuePair<int, Named> x) => x.Value.Story).ToList())
			{
				if (ENTITY.DOES_ENTITY_EXIST(item.Key) && !ENTITY.IS_ENTITY_DEAD(item.Key) && !(ENTITY.GET_ENTITY_COORDS(item.Key, p1: true, p2: true).DistanceTo(position) > 30f) && StoryCast.TryGet(ModelName(ENTITY.GET_ENTITY_MODEL(item.Key)), out var p) && !string.IsNullOrEmpty(p.Name))
				{
					_missionCast.TryGetValue(p.Name, out (int, bool) value);
					_missionCast[p.Name] = (value.Item1 + 1, p.Gang == "vdl");
				}
			}
		}
		if (!mISSION_FLAG && _missionOn)
		{
			ClearCampsTheMissionCleared(player);
		}
		if (!mISSION_FLAG && _missionOn && Game.GameTime - _missionSince > 90000 && Config.WorldEvents)
		{
			int num2 = (Game.GameTime - _missionSince) / 1000;
			List<KeyValuePair<string, (int, bool)>> list = (from x in _missionCast
				where x.Value.seen >= 2
				orderby x.Value.seen descending
				select x).ToList();
			List<string> list2 = list.Where((KeyValuePair<string, (int seen, bool gang)> x) => x.Value.gang).Select((KeyValuePair<string, (int seen, bool gang)> x) => x.Key).ToList();
			List<string> list3 = list.Where((KeyValuePair<string, (int seen, bool gang)> x) => !x.Value.gang).Select((KeyValuePair<string, (int seen, bool gang)> x) => x.Key).ToList();
			if (list.Count == 0)
			{
				GrudgeLog($"VDL mission over after {num2}s - no story character with you: not chronicled");
			}
			else
			{
				WorldEvent worldEvent = NewEvent("YOU", GameMinutesNow());
				worldEvent.Heard = true;
				if (list2.Count > 0)
				{
					worldEvent.Tag = "mission";
					worldEvent.Title = "Rode out with " + Two(list2);
					worldEvent.Gangs.Add("vdl");
				}
				else
				{
					worldEvent.Tag = "stranger";
					worldEvent.Title = "A stranger mission with " + Two(list3);
				}
				worldEvent.Place = "near " + GetZoneName(_missionStartPos);
				worldEvent.HasPos = true;
				worldEvent.X = _missionStartPos.X;
				worldEvent.Y = _missionStartPos.Y;
				worldEvent.Z = _missionStartPos.Z;
				List<string> list4 = list2.Concat(list3).ToList();
				if (list4.Count > 2)
				{
					worldEvent.Lines.Add("With " + string.Join(", ", list4.Take(list4.Count - 1).Take(5)) + " and " + list4.Last() + ".");
				}
				string zoneName = GetZoneName(_missionStartPos);
				string zoneName2 = GetZoneName(player.Position);
				worldEvent.Lines.Add(string.Format("{0} minutes{1}.", Math.Max(1, num2 / 60), (zoneName == zoneName2) ? (", around " + zoneName) : (", from " + zoneName + " to " + zoneName2)));
				Chronicle.Events.Add(worldEvent);
				SaveWorld();
				GrudgeLog(string.Format("VDL mission over after {0}s - chronicled: {1} ({2})", num2, worldEvent.Title, string.Join(", ", list.Select((KeyValuePair<string, (int seen, bool gang)> x) => $"{x.Key} x{x.Value.seen}"))));
			}
		}
		_missionOn = mISSION_FLAG;
		static string Two(List<string> l)
		{
			if (l.Count != 1)
			{
				return l[0] + " and " + l[1];
			}
			return l[0];
		}
	}

	private void NoteGoodLine(string line)
	{
		if (!GoodLines.Add(line))
		{
			return;
		}
		try
		{
			SafeFile.Write(VoicesPath, string.Join("\r\n", GoodLines.OrderBy((string x) => x)));
		}
		catch (Exception ex)
		{
			GrudgeLog("VOICE voices.txt not saved: " + ex.Message);
		}
	}

	private string[] GoodFirst(string[] lines)
	{
		return lines.OrderBy((string l) => (!GoodLines.Contains(l)) ? 1 : 0).ToArray();
	}

	private string KnownVoice(string model)
	{
		if (!VoiceNames.TryGetValue(model, out var value))
		{
			if (!BuiltInVoices.TryGetValue(model, out var value2))
			{
				return null;
			}
			return value2;
		}
		return value;
	}

	internal string BorrowedVoice(uint modelHash)
	{
		string key = Models.Name(modelHash);
		if (!BorrowVoice.TryGetValue(key, out var value))
		{
			return null;
		}
		string[] array = value;
		foreach (string model in array)
		{
			string text = KnownVoice(model);
			if (text != null)
			{
				return text;
			}
		}
		return null;
	}

	internal void GiveVoice(Ped p)
	{
		if (p == null || !p.Exists())
		{
			return;
		}
		string text = BorrowedVoice((uint)p.Model.Hash);
		if (text == null)
		{
			return;
		}
		try
		{
			AUDIO.SET_AMBIENT_VOICE_NAME(p.Handle, text);
		}
		catch
		{
			return;
		}
		string text2 = Models.Name(p);
		if (_borrowLogged.Add(text2))
		{
			bool flag = false;
			try
			{
				flag = AUDIO.DOES_CONTEXT_EXIST_FOR_THIS_PED(p.Handle, "GREET_GENERAL_STRANGER", p2: false);
			}
			catch
			{
			}
			GrudgeLog("VOICE " + text2 + " borrows '" + text + "' - greeting now " + (flag ? "there" : "still missing"));
		}
	}

	private void NoteVoiceName(string model, string voice)
	{
		VoiceNames[model] = voice;
		try
		{
			SafeFile.Write(VoiceNamesPath, string.Join(Environment.NewLine, VoiceNames.Select((KeyValuePair<string, string> kv) => kv.Key + "|" + kv.Value)));
		}
		catch (Exception ex)
		{
			GrudgeLog("VOICE voicenames.txt not saved: " + ex.Message);
		}
	}

	private static ulong VoiceBuf(string voice)
	{
		if (_voiceBuf == IntPtr.Zero)
		{
			_voiceBuf = Marshal.AllocHGlobal(96);
		}
		byte[] bytes = Encoding.ASCII.GetBytes(voice);
		int num = Math.Min(bytes.Length, 95);
		Marshal.Copy(bytes, 0, _voiceBuf, num);
		Marshal.WriteByte(_voiceBuf, num, 0);
		return (ulong)_voiceBuf.ToInt64();
	}

	private unsafe bool TrySayVoice(Ped speaker, string line, string voice, Ped listener)
	{
		if (speaker == null || !speaker.Exists())
		{
			return false;
		}
		ulong* ptr = stackalloc ulong[8];
		for (int i = 0; i < 8; i++)
		{
			ptr[i] = 0uL;
		}
		*ptr = UiDraw.CString(line);
		ptr[1] = VoiceBuf(voice);
		ptr[3] = MISC.GET_HASH_KEY("SPEECH_PARAMS_FORCE_NORMAL_CLEAR");
		ptr[4] = ((listener != null && listener.Exists()) ? ((uint)listener.Handle) : 0);
		ptr[6] = 1uL;
		ptr[7] = 1uL;
		return Function.Call<bool>(10233584479118828642uL, new InputArgument[2]
		{
			speaker.Handle,
			new InputArgument((ulong)ptr)
		});
	}

	private string VoiceState(Ped p)
	{
		int handle = p.Handle;
		bool flag = ENTITY.IS_ENTITY_A_MISSION_ENTITY(handle);
		bool flag2 = false;
		bool flag3 = false;
		bool flag4 = false;
		try
		{
			flag2 = AUDIO.IS_AMBIENT_SPEECH_DISABLED(handle);
		}
		catch
		{
		}
		try
		{
			flag3 = AUDIO.DOES_CONTEXT_EXIST_FOR_THIS_PED(handle, "GREET_GENERAL_STRANGER", p2: false);
		}
		catch
		{
		}
		try
		{
			flag4 = AUDIO.DOES_CONTEXT_EXIST_FOR_THIS_PED(handle, "CHALLENGE_THREATEN", p2: false);
		}
		catch
		{
		}
		return $"mission entity {flag}, speech off {flag2}, has GREET_GENERAL_STRANGER {flag3}, has CHALLENGE_THREATEN {flag4}";
	}

	private void DebugVoiceProbe(Ped player)
	{
		Ped ped = (from p in PedsAround(player)
			where p != null && p.Exists() && !p.IsPlayer && p.IsHuman && !p.IsDead && p.Position.DistanceTo(player.Position) < 20f
			orderby p.Position.DistanceTo(player.Position)
			select p).FirstOrDefault();
		if (ped == null)
		{
			SpawnerSays("nobody within 20 m to test.");
			return;
		}
		string text = ((_named.TryGetValue(ped.Handle, out var value) && !string.IsNullOrEmpty(value.Name)) ? value.Name : Models.Name(ped));
		_probe = new VoiceProbe
		{
			Who = ped,
			Name = text,
			Next = Game.GameTime + 500,
			Todo = ProbeSets.SelectMany(((string kind, string[] lines) s) => s.lines.Select((string l) => (kind: s.kind, l: l))).ToList()
		};
		GrudgeLog(string.Format("VOICE test: {0} ({1}{2}) tries {3} lines - {4}", text, Models.Name(ped), IsOurs(ped.Handle) ? ", one of the mod's" : ", the game's", _probe.Todo.Count, VoiceState(ped)));
		SpawnerSays($"voice test: {text} tries {_probe.Todo.Count} lines - stay close; the ones he says go in the log.");
	}

	private void UpdateVoiceProbe(Ped player)
	{
		VoiceProbe probe = _probe;
		if (probe == null || Game.GameTime < probe.Next)
		{
			return;
		}
		if (probe.Who == null || !probe.Who.Exists() || probe.Who.IsDead || probe.Who.Position.DistanceTo(player.Position) > 40f)
		{
			GrudgeLog($"VOICE test: {probe.Name} is gone - stopped after {probe.Tried} lines");
			EndProbe();
		}
		else if (AUDIO.IS_ANY_SPEECH_PLAYING(probe.Who.Handle))
		{
			probe.Next = Game.GameTime + 300;
		}
		else if (probe.Tried >= probe.Todo.Count)
		{
			if (probe.Played.Count == 0 && !probe.Repaired)
			{
				probe.Repaired = true;
				try
				{
					AUDIO.STOP_PED_SPEAKING(probe.Who.Handle, p1: false);
				}
				catch (Exception ex)
				{
					GrudgeLog("VOICE STOP_PED_SPEAKING failed: " + ex.Message);
				}
				List<string> list = ((GoodLines.Count > 0) ? GoodLines.ToList() : GreetLines.ToList());
				probe.Todo.AddRange(list.Select((string l) => ("again", l: l)));
				GrudgeLog($"VOICE test: {probe.Name} said nothing - speech let on (STOP_PED_SPEAKING false), {list.Count} lines again - {VoiceState(probe.Who)}");
				probe.Next = Game.GameTime + 400;
				return;
			}
			_ = probe.Search;
			_ = 0;
			if (probe.Search >= 0 && probe.Search < 3000 * VoiceSuffixes.Length)
			{
				int num = 0;
				while (num < 240 && probe.Search < 3000 * VoiceSuffixes.Length)
				{
					string text = $"{probe.Search % 3000:0000}_{probe.Model}{VoiceSuffixes[probe.Search / 3000]}";
					if (TrySayVoice(probe.Who, probe.Line, text, player))
					{
						if (probe.Played.Count > 0 && !probe.Played.Any((string x) => x.StartsWith("voice:")))
						{
							GrudgeLog("VOICE test: " + probe.Name + "'s model answers to the voice name '" + text + "' (the form for " + probe.Model + ")");
							NoteVoiceName(probe.Model.ToLowerInvariant(), text);
							probe.Search = int.MaxValue;
							probe.Next = Game.GameTime + 2500;
							return;
						}
						NoteVoiceName(probe.Model.ToLowerInvariant(), text);
						bool flag = false;
						try
						{
							flag = AUDIO.DOES_CONTEXT_EXIST_FOR_THIS_PED(probe.Who.Handle, "GREET_GENERAL_STRANGER", p2: false);
						}
						catch
						{
						}
						try
						{
							AUDIO.SET_AMBIENT_VOICE_NAME(probe.Who.Handle, text);
						}
						catch (Exception ex2)
						{
							GrudgeLog("VOICE SET_AMBIENT_VOICE_NAME failed: " + ex2.Message);
						}
						GrudgeLog($"VOICE test: found {probe.Model}'s voice - '{text}' ({probe.Name} said '{probe.Line}'); given to him - {VoiceState(probe.Who)} (before: has GREET {flag})");
						probe.Played.Add("voice:" + text);
						probe.Search = int.MaxValue;
						probe.Next = Game.GameTime + 2500;
						return;
					}
					num++;
					probe.Search++;
				}
				if (probe.Search >= 3000 * VoiceSuffixes.Length)
				{
					GrudgeLog($"VOICE test: no voice name NNNN_{probe.Model} answered ({probe.Search} tried)");
				}
				probe.Next = Game.GameTime + 50;
			}
			else
			{
				EndProbe();
			}
		}
		else
		{
			var (text2, text3) = probe.Todo[probe.Tried++];
			if (TrySay(probe.Who, text3, player))
			{
				probe.Played.Add(text2 + ":" + text3);
				NoteGoodLine(text3);
				GrudgeLog("VOICE test: " + probe.Name + " said '" + text3 + "' (" + text2 + ")");
				probe.Next = Game.GameTime + 2500;
			}
			else
			{
				probe.Next = Game.GameTime + 120;
			}
		}
	}

	private void EndProbe()
	{
		VoiceProbe probe = _probe;
		_probe = null;
		if (probe != null)
		{
			GrudgeLog(string.Format("VOICE test done: {0} said {1} of {2}: {3}", probe.Name, probe.Played.Count, probe.Tried, (probe.Played.Count > 0) ? string.Join(", ", probe.Played) : "none"));
			ShowNotification((probe.Played.Count > 0) ? $"Voice test: {probe.Name} said {probe.Played.Count} of {probe.Tried} lines (in the log)." : $"Voice test: {probe.Name} said none of {probe.Tried} lines.");
		}
	}

