				GrudgeLog(string.Format("VOICECENSUS {0} ({1}): {2} (greet {3}, challenge {4}){5}", text, flag ? "the mod's" : "the game's", (flag2 | flag3) ? "has a voice" : "NO voice", flag2, flag3, (!flag) ? "" : (ENTITY.IS_ENTITY_A_MISSION_ENTITY(item.Handle) ? ", held" : ", released")));
			}
		}
	}

	private void DebugModelVoices(Ped player)
	{
		Dictionary<uint, List<string>> dictionary = new Dictionary<uint, List<string>>();
		Gang[] all = Gangs.All;
		foreach (Gang gang in all)
		{
			foreach (PedHash item in (gang.Seed ?? new (int, int, PedHash[])[0]).SelectMany(((int Rank, int Count, PedHash[] Models) s) => s.Models ?? new PedHash[0]).Concat(gang.TroopModels ?? new PedHash[0]))
			{
				if (!dictionary.TryGetValue((uint)item, out var value))
				{
					value = (dictionary[(uint)item] = new List<string>());
				}
				if (!value.Contains(gang.Id))
				{
					value.Add(gang.Id);
				}
			}
		}
		PedHash[] array = new PedHash[2]
		{
			(PedHash)977834008u,
			(PedHash)2949314393u
		};
		foreach (PedHash key in array)
		{
			if (!dictionary.ContainsKey((uint)key))
			{
				dictionary[(uint)key] = new List<string> { "townsfolk" };
			}
		}
		_modelCheck = dictionary.Select((KeyValuePair<uint, List<string>> kv) => (Key: kv.Key, string.Join("/", kv.Value))).ToList();
		_modelCheckNo.Clear();
		_modelCheckAt = Game.GameTime + 300;
		_modelCheckPed = null;
		GrudgeLog($"MODELVOICE checking {_modelCheck.Count} outfit models");
		SpawnerSays($"checking {_modelCheck.Count} outfit models for a voice - a few seconds each, nothing shows.");
	}

	private unsafe void UpdateModelVoices(Ped player)
	{
		if (_modelCheck == null || Game.GameTime < _modelCheckAt)
		{
			return;
		}
		if (_modelCheckPed != null)
		{
			Ped modelCheckPed = _modelCheckPed;
			(uint model, string outfits) tuple = _modelCheck[0];
			uint item = tuple.model;
			string item2 = tuple.outfits;
			bool flag = false;
			bool flag2 = false;
			if (modelCheckPed.Exists())
			{
				try
				{
					flag = AUDIO.DOES_CONTEXT_EXIST_FOR_THIS_PED(modelCheckPed.Handle, "GREET_GENERAL_STRANGER", p2: false);
				}
				catch
				{
				}
				try
				{
					flag2 = AUDIO.DOES_CONTEXT_EXIST_FOR_THIS_PED(modelCheckPed.Handle, "CHALLENGE_THREATEN", p2: false);
				}
				catch
				{
				}
			}
			string mn = Models.Name(item);
			string text = mn.ToUpperInvariant();
			BorrowVoice.Values.Any((string[] ds) => ds.Contains(mn));
			_modelSearch = -1;
			_modelCheckPed = null;
			_modelCheck.RemoveAt(0);
			if (modelCheckPed.Exists())
			{
				int handle = modelCheckPed.Handle;
				ENTITY.SET_ENTITY_AS_MISSION_ENTITY(handle, p1: true, p2: true);
				PED.DELETE_PED(&handle);
			}
			if (!flag && !flag2)
			{
				_modelCheckNo.Add(mn);
			}
			GrudgeLog(string.Format("MODELVOICE {0} ({1}): {2} (greet {3}, challenge {4}){5}", mn, item2, (flag | flag2) ? "has a voice" : "NO voice", flag, flag2, VoiceNames.TryGetValue(mn, out var value) ? (" - '" + value + "'") : ""));
			_modelCheckAt = Game.GameTime + 200;
			if (_modelCheck.Count == 0)
			{
				GrudgeLog(string.Format("MODELVOICE done: {0} outfit model(s) with no voice: {1}", _modelCheckNo.Count, string.Join(", ", _modelCheckNo)));
				ShowNotification($"Voice check: {_modelCheckNo.Count} outfit model(s) with no voice (in the log).");
				_modelCheck = null;
			}
		}
		else if (_modelCheck.Count == 0)
		{
			_modelCheck = null;
		}
		else
		{
			Vector3 pos = player.Position + new Vector3(0f, 0f, -12f);
			Ped ped = SpawnPed((PedHash)_modelCheck[0].model, pos, 0f);
			if (ped == null)
			{
				GrudgeLog("MODELVOICE " + Models.Name(_modelCheck[0].model) + ": couldn't be made");
				_modelCheck.RemoveAt(0);
				_modelCheckAt = Game.GameTime + 200;
			}
			else
			{
				ENTITY.FREEZE_ENTITY_POSITION(ped.Handle, p1: true);
				ENTITY.SET_ENTITY_VISIBLE(ped.Handle, p1: false);
				ENTITY.SET_ENTITY_COLLISION(ped.Handle, p1: false, p2: false);
				_modelCheckPed = ped;
				_modelCheckAt = Game.GameTime + 1000;
			}
		}
	}

	internal void NoteGreetReply(int handle)
	{
		if (IsOurs(handle) && ENTITY.DOES_ENTITY_EXIST(handle) && !ENTITY.IS_ENTITY_DEAD(handle) && !PED.IS_PED_IN_COMBAT(handle, 0) && !_greetTalks.ContainsKey(handle) && ENTITY.IS_ENTITY_A_MISSION_ENTITY(handle))
		{
			NemesisRecord nemesisRecord = RecordAt(handle);
			_greetTalks[handle] = new GreetTalk
			{
				Man = handle,
				Stage = 0,
				At = Game.GameTime + 400,
				Curt = ((nemesisRecord?.Hate ?? 0) >= 55),
				Who = (nemesisRecord?.Name ?? (_named.TryGetValue(handle, out var value) ? value.Name : $"ped {handle}"))
			};
		}
	}

	private void UpdateGreetReplies(Ped player)
	{
		if (_greetTalks.Count == 0)
		{
			return;
		}
		foreach (GreetTalk item in _greetTalks.Values.ToList())
		{
			if (Game.GameTime < item.At && item.Stage != 1 && item.Stage != 2 && item.Stage != 4)
			{
				continue;
			}
			int man = item.Man;
			if (!ENTITY.DOES_ENTITY_EXIST(man) || ENTITY.IS_ENTITY_DEAD(man) || PED.IS_PED_IN_COMBAT(man, 0) || player.IsDead || ENTITY.GET_ENTITY_COORDS(man, p1: true, p2: true).DistanceTo(player.Position) > 20f)
			{
				_greetTalks.Remove(man);
				continue;
			}
			Ped ped = new Ped(man);
			switch (item.Stage)
			{
			case 0:
				if (AUDIO.IS_ANY_SPEECH_PLAYING(player.Handle))
				{
					item.YouSpoke = true;
					item.YourLine = "(the game's)";
					item.Stage = 2;
					item.At = Game.GameTime;
					break;
				}
				if (item.Queue == null)
				{
					item.Queue = Attempts(player, YourGreetLines(ped), null);
				}
				item.Stage = (StartLine(player, ped, item) ? 1 : 2);
				item.At = Game.GameTime;
				break;
			case 1:
				if (AUDIO.IS_ANY_SPEECH_PLAYING(player.Handle))
				{
					item.YouSpoke = true;
					item.YourLine = item.Trying.line;
					Heard(player, "you", item.Trying);
					item.Stage = 2;
					item.At = Game.GameTime;
				}
				else if (Game.GameTime - item.At > 900)
				{
					item.Stage = ((item.Tries < 4 && StartLine(player, ped, item)) ? 1 : 2);
					item.At = Game.GameTime;
				}
				break;
			case 2:
				if (!AUDIO.IS_ANY_SPEECH_PLAYING(player.Handle) || Game.GameTime - item.At >= 4000)
				{
					item.Stage = 3;
					item.At = Game.GameTime + 250;
					item.Queue = null;
					item.Tries = 0;
				}
				break;
			case 3:
				if (AUDIO.IS_ANY_SPEECH_PLAYING(man))
				{
					item.HeSpoke = true;
					item.HisLine = "(the game's)";
					item.Stage = 5;
				}
				else
				{
					TASK.TASK_LOOK_AT_ENTITY(man, player.Handle, 3500, 0, 51, 0);
					item.Queue = Attempts(ped, item.Curt ? HisCurtLines() : HisGreetLines(), BorrowedVoice((uint)ped.Model.Hash));
					item.Stage = (StartLine(ped, player, item) ? 4 : 5);
					item.At = Game.GameTime;
				}
				break;
			case 4:
				if (AUDIO.IS_ANY_SPEECH_PLAYING(man))
				{
					item.HeSpoke = true;
					item.HisLine = item.Trying.line + ((item.Trying.voice != null) ? " (borrowed voice)" : "");
					Heard(ped, "he", item.Trying);
					item.Stage = 5;
				}
				else if (Game.GameTime - item.At > 900)
				{
					item.Stage = ((item.Tries < 4 && StartLine(ped, player, item)) ? 4 : 5);
					item.At = Game.GameTime;
				}
				break;
			}
			if (item.Stage == 5)
			{
				_greetTalks.Remove(man);
				NemesisRecord nemesisRecord = RecordAt(man);
				GrudgeLog(Pron.Her("GREETREPLY " + item.Who + ": you " + (item.YouSpoke ? ("said " + item.YourLine) : "said nothing - none of your lines was heard") + "; he " + (item.HeSpoke ? ((item.Curt ? "answered curtly" : "answered") + " " + item.HisLine) : "said nothing - none of his lines was heard (run the voice test by him)") + ((nemesisRecord != null) ? $" (hate {nemesisRecord.Hate})" : ""), !PED.IS_PED_MALE(man)));
			}
		}
	}

	private bool StartLine(Ped speaker, Ped listener, GreetTalk g)
	{
		while (g.Queue != null && g.Queue.Count > 0 && g.Tries < 4)
		{
			(string, string, int, string) trying = g.Queue[0];
			g.Queue.RemoveAt(0);
			if (SayOnce(speaker, trying.Item1, listener, trying.Item2, trying.Item3, trying.Item4))
			{
				g.Trying = trying;
				g.Tries++;
				return true;
			}
		}
		return false;
	}

	private List<(string line, string param, int variation, string voice)> Attempts(Ped speaker, IEnumerable<string> lines, string borrowed)
	{
		List<(string, string, int, string)> list = new List<(string, string, int, string)>();
		List<string> list2 = lines.Distinct().ToList();
		if (_heardLine.TryGetValue(VoiceKey(speaker), out (string, string, int, string) value) && list2.Contains(value.Item1))
		{
			list.Add(value);
		}
		foreach (string item in list2)
		{
			list.Add((item, "SPEECH_PARAMS_FORCE_NORMAL_CLEAR", 0, null));
			list.Add((item, "SPEECH_PARAMS_FORCE", 1, null));
		}
		if (borrowed != null)
		{
			foreach (string item2 in lines.Take(3))
			{
				list.Add((item2, "SPEECH_PARAMS_FORCE_NORMAL_CLEAR", 0, borrowed));
			}
		}
		return list;
	}

	private void Heard(Ped speaker, string who, (string line, string param, int variation, string voice) a)
	{
		_heardLine[VoiceKey(speaker)] = a;
		NoteGoodLine(a.line);
	}

	private static string VoiceKey(Ped p)
	{
		return (uint)p.Model.Hash + (p.IsPlayer ? "|you" : "|him");
	}

	private static IEnumerable<string> YourGreetLines(Ped to)
	{
		bool flag = PED.IS_PED_MALE(to.Handle);
		int cLOCK_HOURS = CLOCK.GET_CLOCK_HOURS();
		string sex = (flag ? "MALE" : "FEMALE");
		if (cLOCK_HOURS >= 5 && cLOCK_HOURS < 12)
		{
			yield return "GREET_MORNING_" + sex;
		}
		else if (cLOCK_HOURS >= 17)
		{
			yield return "GREET_EVENING_" + sex;
		}
		yield return "GREET_" + sex;
		yield return "GREET_" + sex + "_MED";
		yield return "GREET_GENERAL";
	}

	private IEnumerable<string> HisGreetLines()
	{
		int hour = CLOCK.GET_CLOCK_HOURS();
		yield return "GREET_GENERAL_STRANGER";
		if (hour >= 5 && hour < 12)
		{
			yield return "GREET_MORNING_MALE";
		}
		else if (hour >= 17)
		{
			yield return "GREET_EVENING_MALE";
		}
		yield return "GREET_MALE";
		yield return "GREET_GENERAL_FAMILIAR";
		string[] array = GoodFirst(GreetLines);
		for (int i = 0; i < array.Length; i++)
		{
			yield return array[i];
		}
	}

	private IEnumerable<string> HisCurtLines()
	{
		yield return "GREET_REJECT";
		string[] array = GoodFirst(CurtLines);
		for (int i = 0; i < array.Length; i++)
		{
			yield return array[i];
		}
		yield return "GREET_GENERAL_STRANGER";
	}

	private unsafe bool SayOnce(Ped speaker, string line, Ped listener, string param, int variation, string voice)
	{
		if (speaker == null || !speaker.Exists() || DeadNow(speaker))
		{
			return false;
		}
		ulong* ptr = stackalloc ulong[8];
		for (int i = 0; i < 8; i++)
		{
			ptr[i] = 0uL;
		}
		*ptr = UiDraw.CString(line);
		if (voice != null)
		{
			ptr[1] = VoiceBuf(voice);
		}
		ptr[2] = (ulong)variation;
		ptr[3] = MISC.GET_HASH_KEY(param);
		ptr[4] = ((listener != null && listener.Exists()) ? ((uint)listener.Handle) : 0);
		ptr[6] = 1uL;
		ptr[7] = 1uL;
		return Function.Call<bool>(10233584479118828642uL, new InputArgument[2]
		{
			speaker.Handle,
			new InputArgument((ulong)ptr)
		});
	}

	internal void WagonDrive(Ped driver, Vehicle v, Vector3 to, float speed = 5f, int way = -1)
	{
		if (way < 0)
		{
			way = _wagonDriveWay;
		}
		if (way == 2)
		{
			Function.Call(9161476185454364035uL, driver.Handle, v.Handle, to.X, to.Y, to.Z, speed, 524564, 6, 8f, 8f, false);
		}
		else
		{
			TASK.TASK_VEHICLE_DRIVE_TO_COORD(driver.Handle, v.Handle, to.X, to.Y, to.Z, speed, 0uL, ENTITY.GET_ENTITY_MODEL(v.Handle), (way == 1) ? 524564 : 786603, 8f, 10f);
		}
	}

	internal void WagonWander(Ped driver, Vehicle v, float speed = 5f)
	{
		Function.Call(5188501456062479616uL, driver.Handle, v.Handle, speed, (_wagonDriveWay == 0) ? 786603 : 524564);
	}

	internal unsafe string WagonState(Vehicle v, Ped driver)
	{
		string text = "?";
		try
		{
			ulong* ptr = stackalloc ulong[2];
			*ptr = (ptr[1] = 0uL);
			if (Function.Call<bool>(11643009930546700959uL, new InputArgument[3]
			{
				v.Handle,
				new InputArgument((ulong)ptr),
				new InputArgument((ulong)(ptr + 1))
			}))
			{
				text = $"{(int)ptr[1]} of {(int)(*ptr)}";
			}
		}
		catch
		{
		}
		string text2 = "?";
		try
		{
			int num = VEHICLE.GET_PED_IN_VEHICLE_SEAT(v.Handle, -1);
			if (num != 0)
			{
				text2 = ((driver != null && num == driver.Handle) ? "the driver" : "someone else");
			}
			else
			{
				text2 = "NOBODY";
			}
		}
		catch
		{
		}
		float num2 = -1f;
		try
		{
			num2 = Function.Call<float>(14328164591691327233uL, new InputArgument[1] { v.Handle });
		}
		catch
		{
		}
		bool flag = true;
		try
		{
			flag = Function.Call<bool>(16880874006136878045uL, new InputArgument[1] { v.Handle });
		}
		catch
		{
		}
		return string.Format("speed {0:0.0} m/s, horses in harness {1}, reins: {2}, team speed {3:0.0}{4}, driven with {5}", ENTITY.GET_ENTITY_SPEED(v.Handle), text, text2, num2, flag ? "" : ", NOT a draft vehicle", WagonWays[_wagonDriveWay]);
	}

	internal string WagonTry(int n, Ped driver, Vehicle v, ref Vector3 to, ref bool wandering)
	{
		switch (n)
		{
		case 1:
			if (wandering)
			{
				WagonWander(driver, v);
				return "the wander again";
			}
			WagonDrive(driver, v, to);
			return "the order again";
		case 2:
			WagonWander(driver, v);
			wandering = true;
			return "driving on wherever the road goes (no goal)";
		case 3:
			Function.Call(882441092585915516uL, v.Handle, 5f);
			if (wandering)
			{
				WagonWander(driver, v);
			}
			else
			{
				WagonDrive(driver, v, to);
			}
			return "the team's own speed set, the order again";
		case 4:
		{
			Vector3? vector = RoadNodeNear(to, 120f, out var _, 0);
			string text = (vector.HasValue ? $"a main road {vector.Value.DistanceTo(to):0} m from where it was going" : "no main road near - the same place");
			if (vector.HasValue)
			{
				to = vector.Value;
			}
			WagonDrive(driver, v, to, 5f, 1);
			return "R*'s driving flags, to " + text;
		}
		case 5:
			WagonDrive(driver, v, to, 5f, 2);
			return "R*'s own drive-to-destination order";
		default:
			return null;
		}
	}

	internal Vector3? WagonGoal(Vector3 at, float reach)
	{
		float heading;
		return RoadNodeNear(at, reach, out heading, 0);
	}

	internal void WagonRolled(string who, int n, string what)
	{
		GrudgeLog($"WAGONDIAG {who}: rolling again after try {n} - {what}");
		int num = n switch
		{
			5 => 2, 
			4 => 1, 
			_ => -1, 
		};
		if (num > 0 && num != _wagonDriveWay)
		{
			_wagonDriveWay = num;
			GrudgeLog("WAGONDIAG the mod's wagons drive with " + WagonWays[num] + " from now on (this session)");
		}
	}

	private bool WarCardStage(string stage)
	{
		if (!(stage == "warband") && !(stage == "ambush"))
		{
			return stage == "aftermath";
		}
		return true;
	}

	private bool RunWarCard(string stage, Ped player)
	{
		(Gang, Gang)? warHere = WarHere;
		if (!warHere.HasValue)
		{
			return false;
		}
		Gang gang;
		Gang gang2;
		if (_rng.Next(2) != 0)
		{
			Gang item = warHere.Value.Item2;
			Gang item2 = warHere.Value.Item1;
			gang = item2;
			gang2 = item;
		}
		else
		{
			Gang item3 = warHere.Value.Item1;
			Gang item2 = warHere.Value.Item2;
			gang = item2;
			gang2 = item3;
		}
		if (stage == "aftermath")
		{
			return StartJustAfter(player, gang2, gang);
		}
		if (_skirmish.Count > 0 || _warKind != null)
		{
			return false;
		}
		if (!FactionModels.ContainsKey(gang2.Id) || !FactionModels.ContainsKey(gang.Id))
		{
			return false;
		}
		if (!(stage == "warband"))
		{
			return StartAmbush(player, gang2, gang);
		}
		return StartWarband(player, gang2, gang);
	}

	private void PrepareWarSides(Ped player, Gang a, Gang b, bool hateNow)
	{
		if (_sideA == 0)
		{
			_sideA = World.AddRelationshipGroup("SKIRMISH_A");
			_sideB = World.AddRelationshipGroup("SKIRMISH_B");
		}
		int relationship = (hateNow ? 6 : 3);
		World.SetRelationshipBetweenGroups((eRelationshipType)relationship, _sideA, _sideB);
		World.SetRelationshipBetweenGroups((eRelationshipType)relationship, _sideB, _sideA);
		World.SetRelationshipBetweenGroups((eRelationshipType)4, _sideA, player.RelationshipGroup);
		World.SetRelationshipBetweenGroups((eRelationshipType)4, _sideB, player.RelationshipGroup);
		_skirmishGangA = a.Id;
		_skirmishGangB = b.Id;
	}

	private List<Ped> SideMen(uint grp)
	{
		return _skirmish.Where((Ped p) => p != null && p.Exists() && !p.IsDead && ModGroupOf(p.Handle) == grp).ToList();
	}

	private void Mount(List<Ped> men)
	{
		foreach (Ped man in men)
		{
			Ped ped = MountOnHorse(man);
			if (!(ped == null))
			{
				_encHorses.Remove(ped);
				_warHorses.Add(ped);
			}
		}
	}

	private void RideTo(List<Ped> men, Vector3 to, float speed)
	{
		int num = 0;
		foreach (Ped man in men)
		{
			Vector3 vector = new Vector3((float)((num % 2 == 0) ? 1 : (-1)) * 2.5f * (float)(num / 2 + 1), -2f * (float)num, 0f);
			TASK.TASK_GO_TO_COORD_ANY_MEANS(man.Handle, to.X + vector.X, to.Y + vector.Y, to.Z, speed, 0, p6: false, 786603, 0f);
			num++;
		}
	}

	private bool StartWarband(Ped player, Gang a, Gang b)
	{
		Vector3 fwd = Forward(player);
		Vector3 vector = GoodSpot(player, () =>
		{
			double num2 = Math.Atan2(fwd.Y, fwd.X) + Math.PI * (0.55 + _rng.NextDouble() * 0.9) * (double)((_rng.Next(2) == 0) ? 1 : (-1));
			float num3 = 140f + (float)_rng.NextDouble() * 50f;
			return Ground(player.Position + new Vector3((float)Math.Cos(num2) * num3, (float)Math.Sin(num2) * num3, 0f));
		}, 16);
		if (vector == Vector3.Zero)
		{
			GrudgeLog("WAR warband: no hidden dry ground - not sent");
			return false;
		}
		Vector3 vector2 = player.Position - vector;
		vector2.Z = 0f;
		vector2.Normalize();
		_warSpot = Ground(player.Position + vector2 * 200f);
		_warDir = vector2;
		PrepareWarSides(player, a, b, hateNow: true);
		int num = SpawnSide(a, _sideA, vector);
		List<Ped> list = SideMen(_sideA);
		if (list.Count == 0)
		{
			GrudgeLog("WAR warband: nobody spawned");
			return false;
		}
		Mount(list);
		RideTo(list, _warSpot, 6f);
		_warKind = "warband";
		_warTriggered = false;
		_warSince = Game.GameTime;
		_skirmishAt = _warSpot;
		_skirmishEnds = Game.GameTime + 480000;
		SkirmishNote = $"{a.Name} warband ({num}) riding to hit the {b.Name}";
		Feed($"ENCOUNTER WARBAND: {num} {a.Name} ride past you to hit the {b.Name} - follow them", a.Accent);
		GrudgeNotice("Riders of the " + a.Name + " go by - they're out for the " + b.Name + ".");
		GrudgeLog($"WAR warband {a.Name} x{num} from {vector.DistanceTo(player.Position):0} m, riding to {_warSpot.X:0},{_warSpot.Y:0} ({_warSpot.DistanceTo(player.Position):0} m) for the {b.Name}");
		return true;
	}

	private bool StartAmbush(Ped player, Gang a, Gang b)
	{
		(Vector3, float, string)? tuple = RoadAhead(player);
		if (!tuple.HasValue)
		{
			GrudgeLog("WAR ambush: no road ahead");
			return false;
		}
		(Vector3, float, string) value = tuple.Value;
		Vector3 spot = value.Item1;
		float item = value.Item2;
		string item2 = value.Item3;
		float num = item * (float)Math.PI / 180f;
		Vector3 along = new Vector3(0f - (float)Math.Sin(num), (float)Math.Cos(num), 0f);
		Vector3 across = new Vector3((float)Math.Cos(num), (float)Math.Sin(num), 0f);
		if (_rng.Next(2) == 0)
		{
			across = -across;
		}
		_warSpot = spot;
		_warDir = along;
		Vector3 vector = GoodSpot(player, () => Ground(spot + across * (14f + (float)_rng.NextDouble() * 10f) * ((_rng.Next(2) == 0) ? 1f : (-1f)) + along * ((float)_rng.NextDouble() * 16f - 8f)), 12);
		Vector3 vector2 = Vector3.Zero;
		foreach (float item3 in new float[2] { 1f, -1f }.OrderByDescending((float s) => (spot + along * (130f * s)).DistanceTo(player.Position)))
		{
			float[] array = new float[3] { 130f, 110f, 150f };
			foreach (float num3 in array)
			{
				Vector3 vector3 = Ground(spot + along * (num3 * item3));
				float num4 = vector3.DistanceTo(player.Position);
				if (!(num4 < 80f) && !(num4 > 210f) && Dry(vector3) && HiddenFromView(player, vector3))
				{
					vector2 = vector3;
					break;
				}
			}
			if (vector2 != Vector3.Zero)
			{
				break;
			}
		}
		if (vector == Vector3.Zero || vector2 == Vector3.Zero)
		{
			GrudgeLog("WAR ambush: no spot out of your sight for " + ((vector == Vector3.Zero) ? "the men lying in wait" : "the riders") + " - not now");
			return false;
		}
		PrepareWarSides(player, a, b, hateNow: false);
		int num5 = SpawnSide(a, _sideA, vector);
		foreach (Ped item4 in SideMen(_sideA))
		{
			TASK.CLEAR_PED_TASKS(item4.Handle, p1: true, p2: false);
			ENTITY.SET_ENTITY_HEADING(item4.Handle, HeadingTo(item4.Position, spot));
			TASK.TASK_START_SCENARIO_IN_PLACE_HASH(item4.Handle, MISC.GET_HASH_KEY((_rng.Next(2) == 0) ? "WORLD_HUMAN_GUARD_SCOUT" : "WORLD_HUMAN_CROUCH_INSPECT"), -1, p3: true, 0u, -1f, p6: false);
		}
		int num6 = SpawnSide(b, _sideB, vector2);
		List<Ped> list = SideMen(_sideB);
		_warWagon = null;
		bool num7 = _forceWarWagon || _rng.Next(100) < 40;
		_forceWarWagon = false;
		(Vector3, float)? tuple2 = (num7 ? WagonRoadStart(player, spot, along, vector2) : (((Vector3, float)?)null));
		if (num7 && !tuple2.HasValue)
		{
			GrudgeLog("WAR ambush: no road out of your sight for the wagon - riders instead");
		}
		if (tuple2.HasValue && list.Count > 0 && WarWagon(list, tuple2.Value.Item1, tuple2.Value.Item2, spot))
		{
			List<Ped> second = list.Where((Ped p) => PED.IS_PED_IN_ANY_VEHICLE(p.Handle, p1: false)).ToList();
			List<Ped> list2 = list.Except(second).ToList();
			Mount(list2);
			int num8 = 0;
			foreach (Ped item5 in list2)
			{
				Vector3 vector4 = _warWagon.Position - _warWagon.ForwardVector * (7f + 3f * (float)num8) + _warWagon.RightVector * ((num8 % 2 == 0) ? 1.5f : (-1.5f));
				ENTITY.SET_ENTITY_COORDS((PED.GET_MOUNT(item5.Handle) != 0) ? PED.GET_MOUNT(item5.Handle) : item5.Handle, vector4.X, vector4.Y, vector4.Z, p4: false, p5: false, p6: false, p7: false);
				TASK.TASK_FOLLOW_TO_OFFSET_OF_ENTITY(item5.Handle, _warWagon.Handle, (num8 % 2 == 0) ? 1.5f : (-1.5f), -7f - 3f * (float)num8, 0f, 3f, -1, 3f, p8: true, p9: false, p10: false, p11: false, p12: false, p13: false);
				num8++;
			}
		}
		else
		{
			Mount(list);
			RideTo(list, spot, 4.5f);
		}
		if (num5 == 0 || num6 == 0)
		{
			GrudgeLog("WAR ambush: a side didn't spawn");
		}
		_warKind = "ambush";
		_warTriggered = false;
		_warSince = Game.GameTime;
		_skirmishAt = spot;
		_skirmishEnds = Game.GameTime + 480000;
		SkirmishNote = $"{a.Name} ({num5}) lying in wait for the {b.Name} ({num6})";
		Feed($"ENCOUNTER AMBUSH: {num5} {a.Name} wait by the road ahead for {num6} {b.Name} riders - warn them, join in or ride on", a.Accent);
		GrudgeLog($"WAR ambush {a.Name} x{num5} by the road at {spot.X:0},{spot.Y:0} ({spot.DistanceTo(player.Position):0} m, {item2}), {b.Name} x{num6} riding in from {vector2.DistanceTo(spot):0} m");
		return true;
	}

	private bool UpdateWarBuildUp(Ped player)
	{
		if (_warKind == null || _warTriggered)
		{
			return false;
		}
		Vector3 me = player.Position;
		List<Ped> list = SideMen(_sideA);
		List<Ped> list2 = SideMen(_sideB);
		if ((list.Count == 0 && list2.Count == 0) || (me.DistanceTo(_warSpot) > 450f && (list.Count == 0 || list.Min((Ped p) => p.Position.DistanceTo(me)) > 450f)))
		{
			GrudgeLog("WAR " + _warKind + " left behind - it plays out without you");
			EndWarBuildUp(player);
			return true;
		}
		int num = Game.GameTime - _warSince;
		if (_warKind == "warband")
		{
			Ped ped = list.OrderBy((Ped p) => p.Position.DistanceTo(_warSpot)).FirstOrDefault();
			bool flag = ped != null && ped.Position.DistanceTo(_warSpot) < 50f;
			bool flag2 = num > 180000;
			if ((flag | flag2) && me.DistanceTo(ped?.Position ?? _warSpot) < 300f)
			{
				Vector3 at = (flag ? _warSpot : ped.Position);
				Gang gang = Gangs.ById(_skirmishGangB);
				Vector3 vector = GoodSpot(player, () =>
				{
					double num6 = _rng.NextDouble() * Math.PI * 2.0;
					float num7 = 22f + (float)_rng.NextDouble() * 23f;
					return Ground(at + new Vector3((float)Math.Cos(num6) * num7, (float)Math.Sin(num6) * num7, 0f));
				}, 16);
				if (vector == Vector3.Zero)
				{
					if (num > 240000)
					{
						GrudgeLog("WAR warband: nowhere out of your sight for the other side - it never happens");
						EndWarBuildUp(player);
					}
					return true;
				}
				int num2 = SpawnSide(gang, _sideB, vector);
				TriggerWarFight(player, string.Format("the {0} warband hit {1} {2} {3}", Gangs.ById(_skirmishGangA)?.Name, num2, gang?.Name, flag ? "where they were headed" : "on the way"));
				_skirmishAt = at;
			}
			else if (flag2 && me.DistanceTo(ped?.Position ?? _warSpot) >= 300f)
			{
				GrudgeLog("WAR warband rode out of your life");
				EndWarBuildUp(player);
				return true;
			}
		}
		else if (_warKind == "ambush")
		{
			if (_warWagon != null && _warWagon.Exists() && _warWagon.Position.DistanceTo(_warSpot) < 25f)
			{
				Vector3 forwardVector = _warWagon.ForwardVector;
				Vector3 vector2 = _warWagon.Position + new Vector3(forwardVector.X, forwardVector.Y, 0f) * 5f;
				ModExplosion(vector2, (me.DistanceTo(vector2) < 60f) ? 0.3f : 0f, BoomOwner(_skirmish, vector2), "war ambush dynamite");
				GrudgeLog($"WAR ambush: dynamite by the wagon ({me.DistanceTo(vector2):0} m from you)");
				TriggerWarFight(player, "dynamite on the road - they hit the wagon");
				return true;
			}
			bool flag3 = _warWagon != null && _warWagon.Exists() && !VEHICLE.IS_VEHICLE_WRECKED(_warWagon.Handle);
			if (flag3 && Game.GameTime - _wagonOrderAt > 10000)
			{
				_wagonOrderAt = Game.GameTime;
				float num3 = ENTITY.GET_ENTITY_SPEED(_warWagon.Handle);
				float num4 = _warWagon.Position.DistanceTo(_warSpot);
				int num5 = VEHICLE.GET_PED_IN_VEHICLE_SEAT(_warWagon.Handle, -1);
				GrudgeLog(string.Format("WAR ambush: wagon {0:0} m from the spot, {1:0.0} m/s, {2:0} m from you{3}", num4, num3, me.DistanceTo(_warWagon.Position), (num5 == 0) ? " - NO DRIVER" : ""));
				if (num3 < 1f && num5 != 0)
				{
					TASK.TASK_VEHICLE_DRIVE_TO_COORD(num5, _warWagon.Handle, _warSpot.X, _warSpot.Y, _warSpot.Z, 6f, 0uL, ENTITY.GET_ENTITY_MODEL(_warWagon.Handle), 786603, 4f, 10f);
				}
			}
			bool flag4 = !flag3 && list2.Any((Ped p) => p.Position.DistanceTo(_warSpot) < 30f);
			bool flag5 = list.Concat(list2).Any((Ped p) => ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(p.Handle, player.Handle, p2: true, p3: true)) || (PED.IS_PED_SHOOTING(player.Handle) && me.DistanceTo(_warSpot) < 120f);
			if ((flag4 | flag5) || num > 120000)
			{
				NemesisMod nemesisMod = this;
				Ped player2 = player;
				string why;
				if (flag4)
				{
					why = "the riders rode into it";
				}
				else
				{
					why = (flag5 ? "you fired first" : "the riders smelled it - it starts early");
				}
				nemesisMod.TriggerWarFight(player2, why);
			}
		}
		return true;
	}

	private void TriggerWarFight(Ped player, string why)
	{
		_warTriggered = true;
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _sideA, _sideB);
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _sideB, _sideA);
		foreach (Ped item in _skirmish.Where((Ped p) => p.Exists() && !p.IsDead))
		{
			TASK.CLEAR_PED_TASKS(item.Handle, p1: false, p2: false);
			TASK.TASK_COMBAT_HATED_TARGETS_AROUND_PED(item.Handle, 90f, 0, 0uL);
		}
		if (_skirmishBlip == 0)
		{
			_skirmishBlip = AddFightBlip(_skirmishAt, Gangs.ById(_skirmishGangA)?.Name + " vs " + Gangs.ById(_skirmishGangB)?.Name);
		}
		_skirmishEnds = Game.GameTime + 300000;
		Feed("WAR the fight starts: " + why, Theme.Warn);
		GrudgeLog("WAR " + _warKind + " -> skirmish: " + why);
		_warKind = null;
	}

	private unsafe void EndWarBuildUp(Ped player)
	{
		_warKind = null;
		_warTriggered = false;
		foreach (Ped item in _skirmish)
		{
			if (!(item == null) && item.Exists())
			{
				int handle = item.Handle;
				ReleaseIfOurs(&handle);
			}
		}
		_skirmish.Clear();
		_skirmishNamed.Clear();
		ReleaseWarHorses();
		SkirmishNote = "";
	}

	private unsafe (Vector3 pos, float heading)? WagonRoadStart(Ped player, Vector3 spot, Vector3 along, Vector3 fallback)
	{
		ulong* ptr = stackalloc ulong[3];
		ulong* ptr2 = stackalloc ulong[1];
		Vector3 me = player.Position;
		foreach (float item in new float[2] { 1f, -1f }.OrderByDescending((float s) => (spot + along * (140f * s)).DistanceTo(me)))
		{
			float[] array = new float[4] { 70f, 55f, 90f, 40f };
			foreach (float num2 in array)
			{
				Vector3 position = spot + along * (num2 * item);
				*ptr = (ptr[1] = (ptr[2] = 0uL));
				*ptr2 = 0uL;
				if (!Function.Call<bool>(2580559617774072660uL, new InputArgument[8]
				{
					position.X,
					position.Y,
					position.Z,
					new InputArgument((ulong)ptr),
					new InputArgument((ulong)ptr2),
					1,
					3f,
					0f
				}))
				{
					continue;
				}
				Vector3 vector = new Vector3(*(float*)ptr, *(float*)(ptr + 1), *(float*)(ptr + 2));
				if (!(vector.DistanceTo(position) > 30f) && !(vector.DistanceTo(me) < 80f) && !(vector.DistanceTo(me) > 200f))
				{
					Vector3 vector2 = Ground(vector);
					if (!(Math.Abs(vector2.Z - vector.Z) > 3f) && HiddenFromView(player, vector))
					{
						return (new Vector3(vector.X, vector.Y, vector2.Z + 0.3f), HeadingTo(vector, spot));
					}
				}
			}
		}
		return null;
	}

	private bool WarWagon(List<Ped> men, Vector3 at, float heading, Vector3 to)
	{
		string text = (new string[3] { "wagon02x", "wagon04x", "cart01" })[_rng.Next(3)];
		uint num = MISC.GET_HASH_KEY(text);
		if (!STREAMING.IS_MODEL_IN_CDIMAGE(num))
		{
			GrudgeLog("WAR ambush: " + text + " not in the game files - riders instead");
			return false;
		}
		Vehicle vehicle = SpawnVehicle((VehicleHash)num, at, heading);
		if (vehicle == null)
		{
			GrudgeLog("WAR ambush: no " + text + " - riders instead");
			return false;
		}
		MakeOurs(vehicle.Handle);
		VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(vehicle.Handle, p1: false);
		_warWagon = vehicle;
		PED.SET_PED_INTO_VEHICLE(men[0].Handle, vehicle.Handle, -1);
		for (int i = 1; i < men.Count && i <= 2; i++)
		{
			PED.SET_PED_INTO_VEHICLE(men[i].Handle, vehicle.Handle, i - 1);
		}
		men[0].BlockPermanentEvents = true;
		TASK.TASK_VEHICLE_DRIVE_TO_COORD(men[0].Handle, vehicle.Handle, to.X, to.Y, to.Z, 6f, 0uL, num, 786603, 4f, 10f);
		_wagonOrderAt = Game.GameTime;
		GrudgeLog($"WAR ambush: the other side comes on a {text} ({Math.Min(3, men.Count)} aboard), {at.DistanceTo(to):0} m down the road, {at.DistanceTo(Game.Player.Character.Position):0} m from you");
		return true;
	}

	private unsafe void ReleaseWarHorses()
	{
		if (_warWagon != null && _warWagon.Exists() && BelongsToUs(_warWagon.Handle) && PED.GET_VEHICLE_PED_IS_IN(Game.Player.Character.Handle, p1: false) != _warWagon.Handle)
		{
			int handle = _warWagon.Handle;
			ReleaseIfOurs(&handle);
		}
		_warWagon = null;
		foreach (Ped warHorse in _warHorses)
		{
			if (!(warHorse == null) && warHorse.Exists())
			{
				int handle2 = warHorse.Handle;
				ReleaseIfOurs(&handle2);
			}
		}
		_warHorses.Clear();
	}

	private bool StartJustAfter(Ped player, Gang a, Gang b)
	{
		Vector3 fwd = Forward(player);
		Vector3 vector = GoodSpot(player, () =>
		{
			double num3 = Math.Atan2(fwd.Y, fwd.X) + (_rng.NextDouble() * 2.0 - 1.0) * 1.0;
			float num4 = 150f + (float)_rng.NextDouble() * 40f;
			return Ground(player.Position + new Vector3((float)Math.Cos(num3) * num4, (float)Math.Sin(num3) * num4, 0f));
		}, 16);
		if (vector == Vector3.Zero)
		{
			GrudgeLog("WAR aftermath: no hidden dry ground");
			return false;
		}
		long num = GameMinutesNow();
		_historyAt = num;
		WorldEvent worldEvent;
		try
		{
			worldEvent = SimClash(player, num, (a, b, "near " + GetZoneName(vector), vector));
		}
		finally
		{
			_historyAt = null;
		}
		if (worldEvent == null)
		{
			return false;
		}
		worldEvent.Heard = true;
		worldEvent.ForceSurvivors = true;
		if (worldEvent.AftermathUntil <= num)
		{
			worldEvent.AftermathUntil = num + (long)Config.WorldAftermathHours * 60L;
		}
		worldEvent.Lines.Add("You came upon it as the shooting stopped.");
		Chronicle.Events.Add(worldEvent);
		SaveWorld();
		int num2 = Enumerable.Count(worldEvent.People, (WorldPart p) => p.Outcome == "KILLED") + worldEvent.UnnamedDead.Values.Sum();
		Feed($"ENCOUNTER JUST AFTER: {worldEvent.Title} - {num2} dead, {vector.DistanceTo(player.Position):0} m ahead", a.Accent);
		GrudgeNotice("Shots ahead - then quiet. " + worldEvent.Title + ".");
		GrudgeLog($"WAR aftermath: {worldEvent.Title} at {vector.X:0},{vector.Y:0} ({vector.DistanceTo(player.Position):0} m), {num2} dead");
		return true;
	}

	private void TestWarCard(int step, Ped player)
	{
		string text = step switch
		{
			2 => "ambush", 
			1 => "warband", 
			_ => "aftermath", 
		};
		GrudgeLog("WAR test (Alt+F10): " + text + " - war here: " + (WarHere.HasValue ? (WarHere.Value.a.Id + " vs " + WarHere.Value.b.Id) : "none") + ", district " + (CurrentDistrict?.Name ?? "unknown"));
		(Gang, Gang)? warHere = WarHere;
		(Gang, Gang) tuple;
		if (warHere.HasValue)
		{
			tuple = warHere.Value;
		}
		else
		{
			District currentDistrict = CurrentDistrict;
			Dictionary<string, int> holds = ((currentDistrict != null) ? ControlMap[currentDistrict.Key] : new Dictionary<string, int>());
			(Gang, Gang) tuple2 = (from x in Gangs.All
				from y in Gangs.All
				select (x: x, y: y) into t
				where t.x.Id != t.y.Id && AtWarWith(t.x.Id, t.y.Id) && FactionModels.ContainsKey(t.x.Id) && FactionModels.ContainsKey(t.y.Id)
				orderby (holds.TryGetValue(t.x.Id, out var value) ? value : 0) + (holds.TryGetValue(t.y.Id, out var value2) ? value2 : 0) descending
				select t).FirstOrDefault();
			if (tuple2.Item1 != null)
			{
				tuple = (tuple2.Item1, tuple2.Item2);
			}
			else
			{
				tuple = (Gangs.InEra(Gangs.ODriscolls) ? (Gangs.ODriscolls, Gangs.LemoyneRaiders) : (Gangs.LaramieGang, Gangs.DelLobos));
			}
		}
		if (text != "aftermath" && (_skirmish.Count > 0 || _warKind != null))
		{
			ShowNotification("A skirmish is already on - wait for it to end.");
			return;
		}
		Gang gang;
		Gang gang2;
		if (_rng.Next(2) == 0)
		{
			(gang, gang2) = tuple;
		}
		else
		{
			Gang item = tuple.Item2;
			Gang item2 = tuple.Item1;
			gang2 = item2;
			gang = item;
		}
		bool flag;
		if (text == "warband")
		{
			flag = StartWarband(player, gang, gang2);
		}
		else
		{
			flag = ((text == "ambush") ? StartAmbush(player, gang, gang2) : StartJustAfter(player, gang, gang2));
		}
		ShowNotification(flag ? ("Test: " + text + " - the " + gang.Name + " and the " + gang2.Name + ".") : ("Test: " + text + " couldn't start here (see grudges.log)."));
	}

	internal string WarEncounterLine()
	{
		if (_warKind != null)
		{
			return $"NOW WAR {_warKind.ToUpperInvariant()}: {SkirmishNote} - {(Game.GameTime - _warSince) / 1000}s, the spot {Game.Player.Character.Position.DistanceTo(_warSpot):0} m from you";
		}
		return null;
	}

	internal void InitHeat(WarRecord w)
	{
		if (w != null && !w.HeatSet)
		{
			int num = Relation(w.A, w.B);
			w.Heat = Math.Max(25, Math.Min(80, 35 + Math.Min(25, Math.Max(0, (-num - 35) / 2)) + GrievanceOf(w.A, w.B) / 4));
			w.HeatSet = true;
			if (w.GoalLog == null)
			{
				w.GoalLog = new List<string>();
			}
			if (w.GoalLog.Count == 0 && w.GoalText != null)
			{
				w.GoalLog.Add($"{GameDate.FromMinutes(w.StartMin):MMM d}: {w.GoalText}");
			}
		}
	}

	internal void AddHeat(WarRecord w, int n, string why)
	{
		if (w != null && n != 0)
		{
			InitHeat(w);
			int heat = w.Heat;
			w.Heat = Math.Max(0, Math.Min(100, w.Heat + n));
			if (w.Heat != heat)
			{
				GrudgeLog($"WAR heat {w.District}: {heat} -> {w.Heat} ({why})");
				SaveWorld();
			}
		}
	}

	internal static string HeatWord(int h)
	{
		if (h >= 20)
		{
			if (h >= 40)
			{
				if (h >= 60)
				{
					if (h >= 80)
					{
						return "at its worst";
					}
					return "raging";
				}
				return "burning";
			}
			return "smouldering";
		}
		return "dying down";
	}

	internal static (int r, int g, int b) HeatColor(int h)
	{
		if (h >= 20)
		{
			if (h >= 40)
			{
				if (h >= 60)
				{
					return Theme.Blood;
				}
				return Theme.Warn;
			}
			return (r: 190, g: 160, b: 90);
		}
		return Theme.Dim;
	}

	private float HeatPeaceMult(WarRecord w)
	{
		InitHeat(w);
		if (w.Heat >= 20)
		{
			if (w.Heat >= 35)
			{
				if (w.Heat <= 75)
				{
					return 1f;
				}
				return 0.5f;
			}
			return 1.6f;
		}
		return 2.5f;
	}

	private WarRecord WarOf(Gang g, Vector3 at)
	{
		District d = DistrictAt(at);
		if (g == null || d == null)
		{
			return null;
		}
		return Wars.FirstOrDefault((WarRecord x) => x.Result == null && x.District == d.Key && (x.A == g.Id || x.B == g.Id));
	}

	private void DailyWarTurn(WarRecord w, District d, WorldEvent ev, long days)
	{
		InitHeat(w);
		Gang gang = Gangs.ById(w.A);
		Gang gang2 = Gangs.ById(w.B);
		AddHeat(w, -((days >= 10) ? 8 : ((days >= 6) ? 6 : 4)), "a day of war wears them down");
		(Gang, bool)[] array = new (Gang, bool)[2]
		{
			(gang, true),
			(gang2, false)
		};
		for (int i = 0; i < array.Length; i++)
		{
			(Gang, bool) tuple = array[i];
			Gang item = tuple.Item1;
			bool item2 = tuple.Item2;
			LeaderSeat leaderSeat = SeatOf(item);
			if (leaderSeat != null && leaderSeat.Fallen != null && leaderSeat.At >= w.StartMin && !(item2 ? w.LeaderFellA : w.LeaderFellB))
			{
				if (item2)
				{
					w.LeaderFellA = true;
				}
				else
				{
					w.LeaderFellB = true;
				}
				Personality? personality = LeaderTemper(item);
				if (!personality.HasValue)
				{
					AddHeat(w, -15, "the " + item.Name + " have nobody in the leader's seat");
					ev.Lines.Add("The " + item.Name + " have lost their leader and nobody leads them now - the fight is going out of them.");
				}
				else if (personality == Personality.Hothead || personality == Personality.Proud)
				{
					AddHeat(w, 15, "the " + OutfitPoss(item) + " new leader wants blood");
					ev.Lines.Add("The " + OutfitPoss(item) + " new leader, " + item.LeaderName + ", swears to avenge the old one.");
				}
				else
				{
					AddHeat(w, -6, "the " + OutfitPoss(item) + " new leader is cautious");
				}
				if (!item2 && w.Goal != "drive")
				{
					SetWarAim(w, "drive", null, "they mean to drive the leaderless " + gang2.Name + " out of " + d.Name, ev, "the " + gang2.Name + " lost their leader");
				}
			}
		}
		ShiftWarGoal(w, d, ev);
		if (w.YouKilledA + w.YouKilledB > 0)
		{
			string item3 = $"Your part: you've killed {w.YouKilledA} of the {gang.Name} and {w.YouKilledB} of the {gang2.Name}" + ((w.OfficersA + w.OfficersB > 0) ? $", {w.OfficersA + w.OfficersB} of them senior officers" : "") + ".";
			ev.Lines.Add(item3);
		}
		ev.Lines.Add($"The war is {HeatWord(w.Heat)} ({w.Heat}).");
	}

	private void SetWarAim(WarRecord w, string goal, string site, string text, WorldEvent ev, string why)
	{
		if (!(w.Goal == goal) || !(w.GoalSite == site))
		{
			w.Goal = goal;
			w.GoalSite = site;
			w.GoalText = text;
			if (w.GoalLog == null)
			{
				w.GoalLog = new List<string>();
			}
			w.GoalLog.Add($"{GameDate.FromMinutes(GameMinutesNow()):MMM d}: {text} ({why})");
			while (w.GoalLog.Count > 8)
			{
				w.GoalLog.RemoveAt(0);
			}
			Gang gang = Gangs.ById(w.A);
			ev?.Lines.Add("The " + gang?.Name + " change their aim: " + text + " (" + why + ").");
			GrudgeLog("WAR aim " + w.District + ": " + text + " (" + why + ")");
			SaveWorld();
		}
	}

	private bool RetargetWar(WarRecord w, District d, string why)
	{
		Gang gang = Gangs.ById(w.B);
		if (gang == null || d == null)
		{
			return false;
		}
		CampSite campSite = (from _ in SitesHeldBy(gang.Id)
			where !TakeoverPending(_) && _.Id != w.GoalSite && DistrictAt(new Vector3(_.X, _.Y, _.Z)) == d
			orderby _rng.Next()
			select _).FirstOrDefault();
		if (campSite != null)
		{
			SetWarAim(w, "camp", campSite.Id, "they want the camp at " + campSite.Label, null, why);
		}
		else
		{
			SetWarAim(w, "ground", null, "they want more of " + d.Name, null, why);
		}
		return true;
	}

	private void ShiftWarGoal(WarRecord w, District d, WorldEvent ev)
	{
		Gang gang = Gangs.ById(w.B);
		int num = HoldOf(d, w.A);
		int num2 = HoldOf(d, w.B);
		if (w.Goal == "camp")
		{
			CampSite campSite = ((w.GoalSite != null) ? Camps.ById(w.GoalSite) : null);
			if (campSite == null || SiteOwner(campSite) != w.B)
			{
				RetargetWar(w, d, "the camp they came for is gone");
				return;
			}
		}
		if (w.Goal != "hold" && num <= w.HoldA0 - 5)
		{
			SetWarAim(w, "hold", null, "they're holding on to what's left of " + d.Name, ev, "the war is going against them");
		}
		else if (w.Goal == "hold" && num >= w.HoldA0)
		{
			SetWarAim(w, "ground", null, "they want more of " + d.Name, ev, "they've won their ground back");
		}
		else if (w.Goal == "ground" && num >= w.HoldA0 + 6 && num2 <= w.HoldB0 - 6)
		{
			SetWarAim(w, "drive", null, "they mean to drive the " + gang?.Name + " out of " + d.Name, ev, "they smell victory");
		}
	}

	private void NoteWarKill(Gang g, int rank, Vector3 at)
	{
		WarRecord w = WarOf(g, at);
		if (w == null)
		{
			return;
		}
		InitHeat(w);
		bool flag = w.A == g.Id;
		bool flag2 = rank >= 4;
		if (flag)
		{
			w.YouKilledA++;
			if (flag2)
			{
				w.OfficersA++;
			}
		}
		else
		{
			w.YouKilledB++;
			if (flag2)
			{
				w.OfficersB++;
			}
		}
		Gang gang = Gangs.ById(flag ? w.B : w.A);
		if (flag2)
		{
			AddHeat(w, -6, "you killed a " + g.Name + " senior officer");
			Feed("WAR you killed one of the " + OutfitPoss(g) + " senior officers - their war in " + Districts.FirstOrDefault((District x) => x.Key == w.District)?.Name + " falters", Theme.Warn);
		}
		int num = (flag ? w.YouKilledA : w.YouKilledB);
		int num2 = (flag ? w.YouKilledB : w.YouKilledA);
		if (!w.FavourSaid && num >= 5 && num2 <= 1 && gang != null)
		{
			w.FavourSaid = true;
			if (Config.Notoriety.TryGetValue(gang.Id, out var value) && value > 0)
			{
				Config.Notoriety[gang.Id] = Math.Max(0, value - 3);
				Config.Save();
			}
			Feed("WAR the " + gang.Name + " hear you've been killing the " + OutfitPoss(g) + " men - they're glad of it (notoriety with them -3)", Theme.Good);
			GrudgeLog($"WAR {w.District}: you've picked a side - the {gang.Name} ({num} of the {g.Name} killed, {num2} of theirs)");
		}
		SaveWorld();
	}

	private void WarBattles(Ped player, long now)
	{
		int num = GameDate.DayKey(FromGameMinutes(now));
		foreach (WarRecord w in Wars.Where((WarRecord x) => x.Result == null).ToList())
		{
			District district = Districts.FirstOrDefault((District x) => x.Key == w.District);
			Gang gang = Gangs.ById(w.A);
			Gang gang2 = Gangs.ById(w.B);
			if (district == null || gang == null || gang2 == null || IsDestroyed(gang) || IsDestroyed(gang2) || TruceBetween(gang.Id, gang2.Id))
			{
				continue;
			}
			InitHeat(w);
			if (w.BattleDay != num)
			{
				w.BattleDay = num;
				w.BattlesToday = 0;
			}
			if (w.BattlesToday < Math.Min(4, 1 + w.Heat / 30) && (w.LastBattleAt <= 0 || now - w.LastBattleAt < 0 || now - w.LastBattleAt >= 180) && !(_rng.NextDouble() * 100.0 >= (double)w.Heat * 0.25))
			{
				_historyAt = now;
				try
				{
					SimWarBattle(w, district, gang, gang2, now, player);
				}
				finally
				{
					_historyAt = null;
				}
			}
		}
	}

	private WorldEvent SimWarBattle(WarRecord w, District d, Gang a, Gang b, long now, Ped player, Vector3? at = null)
	{
		Vector3 vector = at ?? Vector3.Zero;
		for (int i = 0; i < 10; i++)
		{
			if (!(vector == Vector3.Zero))
			{
				break;
			}
			double num = _rng.NextDouble() * Math.PI * 2.0;
			float num2 = 150f + (float)_rng.NextDouble() * 500f;
			Vector3 vector2 = new Vector3(d.X + (float)Math.Cos(num) * num2, d.Y + (float)Math.Sin(num) * num2, 100f);
			if ((!(player != null) || !(new Vector3(vector2.X - player.Position.X, vector2.Y - player.Position.Y, 0f).Length() < Config.WorldMinDistance)) && !InsideAnyTown(vector2) && OnLand(vector2))
			{
				vector = vector2;
			}
		}
		if (vector == Vector3.Zero)
		{
			return null;
		}
		if (_rng.Next(2) == 0)
		{
			Gang gang = b;
			b = a;
			a = gang;
		}
		string text = "near " + GetZoneName(vector);
		NemesisRecord nemesisRecord = Named(a);
		NemesisRecord nemesisRecord2 = Named(b);
		int num3 = 3 + _rng.Next(4);
		int num4 = 3 + _rng.Next(4);
		float num5 = ((float)num3 * 1.5f + ((nemesisRecord != null) ? (2f + (float)nemesisRecord.Rank) : 0f) + (float)_rng.NextDouble() * 6f) * Stretched(a) * MenPower(a) - Malus(a);
		float num6 = ((float)num4 * 1.5f + ((nemesisRecord2 != null) ? (2f + (float)nemesisRecord2.Rank) : 0f) + (float)_rng.NextDouble() * 6f) * Stretched(b) * MenPower(b) - Malus(b);
		bool flag = num5 >= num6;
		Gang gang2 = (flag ? a : b);
		Gang gang3 = (flag ? b : a);
		int hour = FromGameMinutes(now).Hour;
		string[] array = ((hour >= 21 || hour < 5) ? NightTitles : BattleTitles);
		WorldEvent worldEvent = NewEvent("CLASH", now);
		worldEvent.Place = text;
		worldEvent.HasPos = true;
		worldEvent.X = vector.X;
		worldEvent.Y = vector.Y;
		worldEvent.Z = vector.Z;
		worldEvent.Gangs.Add(a.Id);
		worldEvent.Gangs.Add(b.Id);
		worldEvent.Title = array[_rng.Next(array.Length)].Replace("{a}", a.Name).Replace("{b}", b.Name).Replace("{p}", text);
		worldEvent.Lines.Add($"Part of the war in {d.Name}. {a.Name}: {num3 + ((nemesisRecord != null) ? 1 : 0)} men.  {b.Name}: {num4 + ((nemesisRecord2 != null) ? 1 : 0)} men.");
		worldEvent.Lines.Add("The " + gang2.Name + " had the better of it.");
		(NemesisRecord, Gang, bool)[] array2 = new (NemesisRecord, Gang, bool)[2]
		{
			(nemesisRecord, a, flag),
			(nemesisRecord2, b, !flag)
		};
		for (int j = 0; j < array2.Length; j++)
		{
			var (nemesisRecord3, gang4, flag2) = array2[j];
			if (nemesisRecord3 != null)
			{
				ResolveFighter(nemesisRecord3, flag2, worldEvent, "the " + ((gang4 == a) ? b : a).Name, gun: true, 0.5f);
			}
			int num7 = (int)Math.Round((float)((flag2 ? _rng.Next(2) : (1 + _rng.Next(2))) * Config.WorldLethality) / 100f);
			if (num7 > 0)
			{
				worldEvent.UnnamedDead[gang4.Id] = num7;
			}
		}
		if (worldEvent.People.Any((WorldPart p) => p.Outcome == "KILLED") || worldEvent.UnnamedDead.Count > 0)
		{
			worldEvent.AftermathUntil = now + (long)Config.WorldAftermathHours * 60L;
		}
		ShiftControl(d, gang2, 2, "won a fight with the " + gang3.Name);
		ShiftControl(d, gang3, -LossDown(d, gang3, 2), "lost a fight to the " + gang2.Name);
		w.BattlesToday++;
		w.LastBattleAt = now;
		worldEvent.Heard = WordReachesYou(worldEvent, player);
		Chronicle.Events.Add(worldEvent);
		try
		{
			NoteClashForWars(worldEvent);
		}
		catch (Exception ex)
		{
			GrudgeLog("RELATION clash note failed: " + ex.Message);
		}
		int num8 = Enumerable.Count(worldEvent.People, (WorldPart p) => p.Outcome == "KILLED") + worldEvent.UnnamedDead.Values.Sum();
		GrudgeLog($"WAR battle {d.Name}: {worldEvent.Title} - {num8} dead (heat {w.Heat}, {w.BattlesToday} today)");
		Feed("WAR " + worldEvent.Title + ((num8 > 0) ? $" ({num8} dead)" : ""), KindColor("CLASH"));
		SaveWorld();
		return worldEvent;
		float Malus(Gang g)
		{
			return 1.5f * (float)Math.Min(4, (g.Id == w.A) ? w.OfficersA : w.OfficersB);
		}
		NemesisRecord Named(Gang g)
		{
			if (_rng.Next(100) < 35)
			{
				return (from n in Roster
					where n.Gang == g.Id && OffStage(n) && !n.Paralyzed && n.IsAlive && !n.PresumedDead
					orderby ((n.Rank >= 4) ? 200 : 0) + _rng.Next(100)
					select n).FirstOrDefault();
			}
			return null;
		}
	}

	internal bool SkirmishForWar(Vector3 at, Gang winner, Gang loser, int loserDead, int winnerDead, List<string> lines)
	{
		WarRecord warRecord = WarOf(winner, at);
		if (warRecord == null || (warRecord.A != loser.Id && warRecord.B != loser.Id))
		{
			return false;
		}
		District district = DistrictByKey(warRecord.District);
		if (district == null)
		{
			return false;
		}
		int num = Math.Max(2, Math.Min(6, loserDead));
		ShiftControl(district, winner, num, $"won a fight with the {loser.Name} ({loserDead} of theirs down)");
		ShiftControl(district, loser, -LossDown(district, loser, num), "lost a fight to the " + winner.Name);
		try
		{
			PurseForClash(winner, loser);
		}
		catch
		{
		}
		AddHeat(warRecord, Math.Min(6, loserDead + winnerDead), $"a fight you heard - {loserDead + winnerDead} men down");
		lines?.Add($"Part of {WarName(warRecord)}: the {winner.Name} took ground in {district.Name} (+{num}).");
		GrudgeLog($"WAR {WarName(warRecord)}: a live fight - the {winner.Name} +{num} ground, {loserDead} of the {loser.Name} and {winnerDead} of theirs down");
		SaveWorld();
		return true;
	}

	private void UpdateRoadBodies(Ped player)
	{
		if (Game.GameTime < _nextRoadBodies)
		{
			return;
		}
		_nextRoadBodies = Game.GameTime + 90000;
		if (Game.GameTime < _roadBodiesAllowed || !PED.IS_PED_ON_MOUNT(player.Handle) || _skirmish.Count > 0 || _warKind != null || FightHoldsWar() || WorldBusy(player) || MISC.GET_MISSION_FLAG() || InsideAnyTown(player.Position))
		{
			return;
		}
		int num = PED.GET_MOUNT(player.Handle);
		if (num == 0 || ENTITY.GET_ENTITY_SPEED(num) < 4f)
		{
			return;
		}
		District d = CurrentDistrict;
		WarRecord warRecord = ((d == null) ? null : Wars.FirstOrDefault((WarRecord x) => x.Result == null && x.District == d.Key));
		if (warRecord != null && !TruceBetween(warRecord.A, warRecord.B))
		{
			InitHeat(warRecord);
			if (!(_rng.NextDouble() * 100.0 >= (double)warRecord.Heat / 4.0 * (WarNight ? 1.5 : 1.0)))
			{
				RoadBodiesNow(player, warRecord, d);
			}
		}
	}

	private bool RoadBodiesNow(Ped player, WarRecord w, District d)
	{
		Gang gang = Gangs.ById(w.A);
		Gang gang2 = Gangs.ById(w.B);
		if (gang == null || gang2 == null || !FactionModels.ContainsKey(gang.Id) || !FactionModels.ContainsKey(gang2.Id))
		{
			return false;
		}
		Vector3 fwd = Forward(player);
		Vector3 vector = GoodSpot(player, () =>
		{
			double num2 = Math.Atan2(fwd.Y, fwd.X) + (_rng.NextDouble() * 2.0 - 1.0) * 0.6;
			float num3 = 150f + (float)_rng.NextDouble() * 40f;
			return Ground(player.Position + new Vector3((float)Math.Cos(num2) * num3, (float)Math.Sin(num2) * num3, 0f));
		}, 14);
		if (vector == Vector3.Zero || InsideAnyTown(vector))
		{
			return false;
		}
		long num = GameMinutesNow();
		_historyAt = num;
		WorldEvent worldEvent;
		try
		{
			worldEvent = SimWarBattle(w, d, gang, gang2, num, player, vector);
		}
		finally
		{
			_historyAt = null;
		}
		if (worldEvent == null)
		{
			return false;
		}
		if (Enumerable.Count(worldEvent.People, (WorldPart p) => p.Outcome == "KILLED") + worldEvent.UnnamedDead.Values.Sum() < 2)
		{
			string key = ((worldEvent.Gangs.Count > 1) ? worldEvent.Gangs[_rng.Next(2)] : w.B);
			worldEvent.UnnamedDead[key] = (worldEvent.UnnamedDead.TryGetValue(key, out var value) ? value : 0) + 2;
		}
		worldEvent.Heard = true;
		worldEvent.ForceSurvivors = true;
		if (worldEvent.AftermathUntil <= num)
		{
			worldEvent.AftermathUntil = num + (long)Config.WorldAftermathHours * 60L;
		}
		worldEvent.Lines.Add("You rode up on it not long after.");
		_roadBodiesAllowed = Game.GameTime + 360000;
		_nextAftermathCheck = 0;
		GrudgeLog($"WAR road bodies: {worldEvent.Title} - {vector.DistanceTo(player.Position):0} m ahead (heat {w.Heat})");
		SaveWorld();
		return true;
	}

	internal int WarsOf(Gang g)
	{
		if (g != null)
		{
			return Enumerable.Count(Wars, (WarRecord w) => w.Result == null && (w.A == g.Id || w.B == g.Id) && !TruceBetween(w.A, w.B));
		}
		return 0;
	}

	internal bool StretchedThin(Gang g)
	{
		return WarsOf(g) >= 2;
	}

	internal string WarDefenders(WarRecord w)
	{
		Gang gang = Gangs.ById(w.A);
		Gang gang2 = Gangs.ById(w.B);
		District district = Districts.FirstOrDefault((District x) => x.Key == w.District);
		if (gang == null || gang2 == null)
		{
			return null;
		}
		int num = ((district != null) ? HoldOf(district, gang2.Id) : w.HoldB0);
		Personality? personality = LeaderTemper(gang2);
		Agenda agenda = AgendaOf(gang2);
		string text;
		if (!personality.HasValue || w.LeaderFellB)
		{
			text = "Leaderless - holding on as best they can";
		}
		else if (agenda?.Kind == "revenge" && agenda.Target == gang.Id)
		{
			text = "Out to break the " + gang.Name + " in turn";
		}
		else if (num >= w.HoldB0 + 3)
		{
			text = $"Holding firm - they've gained ground (+{num - w.HoldB0})";
		}
		else
		{
			text = ((num <= w.HoldB0 - 6) ? $"Giving ground - {w.HoldB0 - num} lost so far" : (personality.Value switch
			{
				Personality.Hothead => "Hitting back hard", 
				Personality.Proud => "Won't give an inch", 
				Personality.Cold => "Dug in and waiting", 
				Personality.Coward => "Looking for a way out", 
				Personality.Greedy => "Fighting for what pays", 
				Personality.Loyal => "Standing by their own", 
				_ => "Not much heart for it", 
			}));
		}
		if (StretchedThin(gang2))
		{
			text += " - stretched thin by another war";
		}
		if (HasPurse(gang2) && PurseOf(gang2) < 60)
		{
			text += " - short of money";
		}
		return text;
	}

	internal string WarOutlook(WarRecord w)
	{
		Gang gang = Gangs.ById(w.A);
		Gang gang2 = Gangs.ById(w.B);
		District district = Districts.FirstOrDefault((District x) => x.Key == w.District);
		if (gang == null || gang2 == null)
		{
			return null;
		}
		if (TruceBetween(w.A, w.B))
		{
			return "A truce holds - for now";
		}
		long num = WarDay(w);
		int num2 = Math.Max(30, 100 - 6 * w.OfficersA);
		int num3 = ((district != null) ? HoldOf(district, gang.Id) : w.HoldA0);
		int num4 = ((district != null) ? HoldOf(district, gang2.Id) : w.HoldB0);
		string text;
		if (!w.LeaderFellA && LeaderTemper(gang).HasValue)
		{
			if (w.LeaderFellB || !LeaderTemper(gang2).HasValue)
			{
				text = "Leaderless - the " + gang2.Name + " may break";
			}
			else if (num4 < 8 && num > 1)
			{
				text = "The " + gang2.Name + " are close to being driven out";
			}
			else if (num3 < 8 && num > 1)
			{
				text = "The " + gang.Name + " are close to losing their foothold";
			}
			else if (Strength(gang) < 30)
			{
				text = "The " + gang.Name + " are close to breaking - men and money running out";
			}
			else if (Strength(gang2) < 30)
			{
				text = "The " + gang2.Name + " are close to breaking - men and money running out";
			}
			else if (num >= num2 - 5)
			{
				text = "Wearing thin - talk of peace";
			}
			else if (HasPurse(gang) && PurseOf(gang) < 60)
			{
				text = "The " + gang.Name + " are running out of money";
			}
			else if (HasPurse(gang2) && PurseOf(gang2) < 60)
			{
				text = "The " + gang2.Name + " are running out of money";
			}
			else if (num <= 2)
			{
				text = "Just begun";
			}
			else if (w.Heat >= 75)
			{
				text = "Raging - no end in sight";
			}
			else
			{
				text = ((w.Heat >= 35 || num < 4) ? "No end in sight yet" : "Cooling - both sides tired");
			}
		}
		else
		{
			text = "Leaderless - the " + gang.Name + " may break";
		}
		if (DebugOn)
		{
			text += $"  (Day {num}, heat {w.Heat}, strength {Strength(gang)} / {Strength(gang2)}, gives up day {num2})";
		}
		return text;
	}

	internal float Stretched(Gang g)
	{
		if (!StretchedThin(g))
		{
			return 1f;
		}
		return 0.85f;
	}

	private bool KeenForWar(Gang g, Gang on)
	{
		if (LeaderTemper(g) != Personality.Hothead)
		{
			if (AgendaOf(g)?.Kind == "revenge")
			{
				return AgendaOf(g)?.Target == on?.Id;
			}
			return false;
		}
		return true;
	}

	private bool NearWar(Ped player)
	{
		if (WarHere.HasValue)
		{
			return true;
		}
		Vector3 me = player.Position;
		return Wars.Any((WarRecord w) =>
		{
			if (w.Result == null && !TruceBetween(w.A, w.B))
			{
				District district = DistrictByKey(w.District);
				if (district != null)
				{
					return new Vector3(district.X - me.X, district.Y - me.Y, 0f).Length() < 1800f;
				}
			}
			return false;
		});
	}

	private void WatchCamped(Ped player)
	{
		if (!PED.IS_PED_USING_ANY_SCENARIO(player.Handle) || PED.IS_PED_ON_MOUNT(player.Handle) || PED.IS_PED_IN_ANY_VEHICLE(player.Handle, p1: false))
		{
			_restSince = 0;
			if (_upSince == 0)
			{
				_upSince = Game.GameTime;
			}
			if (Game.GameTime - _upSince > 30000)
			{
				_restRolled = false;
			}
			return;
		}
		_upSince = 0;
		if (_restSince == 0)
		{
			_restSince = Game.GameTime;
		}
		if (!_restRolled && Game.GameTime - _restSince >= 8000 && WarNight && _sleepBattleAt == 0 && !FightHoldsWar() && Config.DistantBattles && _skirmish.Count <= 0 && _warKind == null && !WorldBusy(player) && !MISC.GET_MISSION_FLAG() && !LawAfterYou() && !InsideAnyTown(player.Position) && !AtGangCamp(player) && NearWar(player))
		{
			_restRolled = true;
			int num = _rng.Next(100);
			bool flag = num < 75;
			GrudgeLog(string.Format("WAR camped at night near a war: {0}% - rolled {1}: {2}", 75, num, flag ? "gunfire soon" : "a quiet night"));
			if (flag)
			{
				_sleepBattleAt = Game.GameTime + 15000 + _rng.Next(25000);
			}
		}
	}

	internal bool InAFight()
	{
		if (!_combatants.Values.Any((int t) => Game.GameTime - t < 10000) && (_enc == null || !_enc.Engaged))
		{
			return _liveCamps.Values.Any((LiveCamp c) => c.Engaged && !c.Cleared);
		}
		return true;
	}

	internal bool PatrolInTheFight(Ped player)
	{
		return _raids.Any((Raid r) => r.Men.Any((Ped m) => m != null && m.Exists() && !m.IsDead && m.Position.DistanceTo(player.Position) < 400f));
	}

	internal bool FightHoldsWar()
	{
		return InAFight();
	}

	private void UpdateWarPatrolRoll(Ped player)
	{
		if (Game.GameTime < _nextWarPatrolRoll)
		{
			return;
		}
		_nextWarPatrolRoll = Game.GameTime + 60000;
		(Gang, Gang)? warHere = WarHere;
		if (!warHere.HasValue || Game.GameTime < _warPatrolAllowed || (FightHoldsWar() && PatrolInTheFight(player)) || WorldBusy(player) || MISC.GET_MISSION_FLAG() || InsideAnyTown(player.Position) || NoSpawnReason(player) != null || Enumerable.Count(_raids, (Raid r) => r.CampId == null) >= 2)
		{
			return;
		}
		District d = CurrentDistrict;
		WarRecord warRecord = ((d == null) ? null : Wars.FirstOrDefault((WarRecord x) => x.Result == null && x.District == d.Key));
		int num = 40;
		if (warRecord != null)
		{
			InitHeat(warRecord);
			num = warRecord.Heat;
		}
		double num2 = (double)num / 4.0 * (WarNight ? 2.0 : 1.0);
		double num3 = _rng.NextDouble() * 100.0;
		if (num3 >= num2)
		{
			return;
		}
		List<Gang> list = new Gang[2]
		{
			warHere.Value.Item1,
			warHere.Value.Item2
		}.Where((Gang g) => g != null && FactionModels.ContainsKey(g.Id) && !_raids.Any((Raid r) => r.Gang == g && r.CampId == null) && SuppliesOf(g) > 0).ToList();
		if (list.Count != 0)
		{
			Gang gang = list[_rng.Next(list.Count)];
			if (SpawnRoadPatrol(player, force: false, gang))
			{
				_warPatrolAllowed = Game.GameTime + (WarNight ? 120000 : 180000);
				GrudgeLog(string.Format("WAR patrol roll: heat {0}, {1:0}%{2} - rolled {3:0}: the {4} ride the road", num, num2, WarNight ? " (night)" : "", num3, gang.Name));
			}
		}
	}

	private void UpdateWarEncounterRoll(Ped player)
	{
		if (Game.GameTime < _nextWarEncRoll)
		{
			return;
		}
		_nextWarEncRoll = Game.GameTime + 90000;
		if (!WarHere.HasValue || Game.GameTime < _warEncAllowed || _skirmish.Count > 0 || _warKind != null || FightHoldsWar() || WorldBusy(player) || MISC.GET_MISSION_FLAG() || LawAfterYou() || InsideAnyTown(player.Position) || NoSpawnReason(player) != null || _enc != null)
		{
			return;
		}
		District d = CurrentDistrict;
		WarRecord warRecord = ((d == null) ? null : Wars.FirstOrDefault((WarRecord x) => x.Result == null && x.District == d.Key));
		int num = 40;
		if (warRecord != null)
		{
			InitHeat(warRecord);
			num = warRecord.Heat;
		}
		CLOCK.GET_CLOCK_HOURS();
		double num2 = (double)num / 5.0 * (WarNight ? 2.0 : 1.0);
		double num3 = _rng.NextDouble() * 100.0;
		if (num3 >= num2)
		{
			GrudgeLog($"WAR encounter roll: heat {num}, {num2:0}% - rolled {num3:0}, nothing");
			return;
		}
		bool mounted = PED.IS_PED_ON_MOUNT(player.Handle);
		List<(EncounterCard, int)> list = (from c in Cards
			where (WarCardStage(c.Stage) || c.Stage == "skirmish") && CardFits(c, null, town: false, mounted, test: false)
			select (c: c, wgt: Math.Max(1, CardChance(c)))).ToList();
		while (list.Count > 0)
		{
			int t = _rng.Next(list.Sum(((EncounterCard c, int wgt) x) => x.wgt));
			(EncounterCard, int) tuple = list.First(((EncounterCard c, int wgt) x) => (t -= x.wgt) < 0);
			list.Remove(tuple);
			var (encounterCard, _) = tuple;
			if ((encounterCard.Stage == "skirmish") ? TrySkirmish(player, town: false, test: false, rolled: true) : RunWarCard(encounterCard.Stage, player))
			{
				UseCard(encounterCard);
				_warEncAllowed = Game.GameTime + (WarNight ? 180000 : 300000);
				GrudgeLog(string.Format("WAR encounter roll: heat {0}, {1:0}% - rolled {2:0}: {3} played ({4})", num, num2, num3, encounterCard.Id, (encounterCard.Stage == "skirmish") ? SkirmishNote : encounterCard.Stage));
				return;
			}
		}
		GrudgeLog($"WAR encounter roll: heat {num}, {num2:0}% - rolled {num3:0}, but nothing fitted or could be placed");
	}

	private void UpdateDistantBattle(Ped player)
	{
		WatchSleep(player);
		try
		{
			WatchCamped(player);
		}
		catch (Exception ex)
		{
			GrudgeLog("WAR camped failed: " + ex.Message);
		}
		try
		{
			UpdateRoadBodies(player);
		}
		catch (Exception ex2)
		{
			GrudgeLog("WAR road bodies failed: " + ex2.Message);
		}
		try
		{
			UpdateWarEncounterRoll(player);
		}
		catch (Exception ex3)
		{
			GrudgeLog("WAR encounter roll failed: " + ex3.Message);
		}
		try
		{
			UpdateWarPatrolRoll(player);
		}
		catch (Exception ex4)
		{
			GrudgeLog("WAR patrol roll failed: " + ex4.Message);
		}
		try
		{
			UpdateNightShelling(player);
		}
		catch (Exception ex5)
		{
			GrudgeLog("WAR night blasts failed: " + ex5.Message);
		}
		if (Game.GameTime < _nextDistantCheck)
		{
			return;
		}
		_nextDistantCheck = Game.GameTime + 60000;
		if (!Config.DistantBattles)
		{
			DistantNo("turned off ([World] DistantBattles)");
			return;
		}
		if (Game.GameTime < _nextDistantAllowed)
		{
			DistantNo($"too soon after the last ({(_nextDistantAllowed - Game.GameTime) / 1000} s to wait)");
			return;
		}
		if (_skirmish.Count > 0 || _warKind != null)
		{
			DistantNo("a skirmish / war encounter is already on");
			return;
		}
		if (_wildCameAt != 0 && Game.GameTime - _wildCameAt < 300000)
		{
			DistantNo("an encounter came less than 5 minutes ago");
			return;
		}
		if (FightHoldsWar())
		{
			DistantNo("you're in a fight");
			return;
		}
		if (WorldBusy(player))
		{
			DistantNo("the world is busy (fade / no control)");
			return;
		}
		if (MISC.GET_MISSION_FLAG())
		{
			DistantNo("on a mission");
			return;
		}
		if (LawAfterYou())
		{
			DistantNo("the law is after you");
			return;
		}
		if (InsideAnyTown(player.Position))
		{
			DistantNo("in a town");
			return;
		}
		string text = NoSpawnReason(player);
		if (text != null && (text.StartsWith("on a mission") || text.StartsWith("settling") || text.StartsWith("on a train")))
		{
			DistantNo(text);
			return;
		}
		if (_enc != null && _enc.Engaged)
		{
			DistantNo("your own encounter is on");
			return;
		}
		District currentDistrict = CurrentDistrict;
		Vector3 position = player.Position;
		WarRecord warRecord = null;
		List<string> list = new List<string>();
		foreach (WarRecord w in Wars.Where((WarRecord x) => x.Result == null))
		{
			District district = Districts.FirstOrDefault((District x) => x.Key == w.District);
			if (district == null)
			{
				continue;
			}
			string text2 = WarName(w);
			if (TruceBetween(w.A, w.B))
			{
				list.Add(text2 + ": a truce");
				continue;
			}
			if (!FactionModels.ContainsKey(w.A) || !FactionModels.ContainsKey(w.B))
			{
				list.Add(text2 + ": a side has no troops");
				continue;
			}
			float num = new Vector3(district.X - position.X, district.Y - position.Y, 0f).Length();
			if (district != currentDistrict && num >= 1800f)
			{
				list.Add($"{text2}: {num:0} m off (needs under 1800)");
				continue;
			}
			InitHeat(w);
			if (warRecord == null || w.Heat > warRecord.Heat)
			{
				warRecord = w;
			}
		}
		if (warRecord == null)
		{
			DistantNo((list.Count == 0) ? "no war on" : ("no war near you - " + string.Join("; ", list)));
			return;
		}
		int cLOCK_HOURS = CLOCK.GET_CLOCK_HOURS();
		double num2 = (double)warRecord.Heat / 5.0 * (WarNight ? 2.0 : 1.0);
		double num3 = _rng.NextDouble() * 100.0;
		_distantNoWhy = null;
		string text3 = string.Format("WAR distant battle roll: {0}, heat {1}{2} - {3:0}%, rolled {4:0}", WarName(warRecord), warRecord.Heat, WarNight ? ", night" : "", num2, num3);
		if (num3 >= num2)
		{
			GrudgeLog(text3 + ": no");
			return;
		}
		Gang gang = Gangs.ById(warRecord.A);
		Gang gang2 = Gangs.ById(warRecord.B);
		if (gang != null && gang2 != null)
		{
			if (_rng.Next(2) == 0)
			{
				Gang gang3 = gang2;
				gang2 = gang;
				gang = gang3;
			}
			GrudgeLog(text3 + ": yes");
			_distantSpotNote = null;
			if (TrySkirmish(player, town: false, test: false, rolled: true, (gang, gang2), distant: true))
			{
				_nextDistantAllowed = Game.GameTime + (WarNight ? 150000 : 240000);
				GrudgeLog(string.Format("WAR distant battle: the {0} and the {1}, {2} (heat {3}{4})", gang.Name, gang2.Name, Away(position, _skirmishAt), warRecord.Heat, (cLOCK_HOURS >= 21 || cLOCK_HOURS < 5) ? ", night" : ""));
			}
			else
			{
				_nextDistantAllowed = Game.GameTime + 120000;
				GrudgeLog("WAR distant battle: didn't happen - " + (_distantSpotNote ?? "the skirmish wouldn't start") + " (next try in 2 min)");
			}
		}
	}

	private void DistantNo(string why)
	{
		if (!(why == _distantNoWhy) || Game.GameTime - _distantNoAt >= 300000)
		{
			_distantNoWhy = why;
			_distantNoAt = Game.GameTime;
			GrudgeLog("WAR distant battle roll: skipped - " + why);
		}
	}

	private void WatchSleep(Ped player)
	{
		if (Game.GameTime < _nextSleepWatch)
		{
			return;
		}
		_nextSleepWatch = Game.GameTime + 2000;
		long num = GameMinutesNow();
		long sleepWatchMin = _sleepWatchMin;
		_sleepWatchMin = num;
		if (_sleepBattleAt != 0 && Game.GameTime >= _sleepBattleAt)
		{
			_sleepBattleAt = 0;
			WakeBattle(player);
		}
		if (sleepWatchMin < 0 || num - sleepWatchMin < 120 || num - sleepWatchMin > 4320 || Game.GameTime - _loadScreenAt < 30000 || Game.GameTime - _lastJumpAt < 30000 || InsideAnyTown(player.Position))
		{
			return;
		}
		long val = sleepWatchMin / 720;
		long num2 = num / 720;
		long num3 = Math.Max(val, Chronicle.SleepRollWindow + 1);
		int num4 = (int)Math.Max(0L, Math.Min(2L, num2 - num3 + 1));
		Chronicle.SleepRollWindow = Math.Max(Chronicle.SleepRollWindow, num2);
		SaveWorld();
		if (num4 == 0)
		{
			GrudgeLog($"WAR sleep {(num - sleepWatchMin) / 60}h: this half day already rolled");
			return;
		}
		bool flag = false;
		bool flag2 = (num - sleepWatchMin >= 480 || WarNightAt(sleepWatchMin) || WarNightAt(num)) && NearWar(player);
		if (flag2)
		{
			num4 = 1;
			flag = _rng.Next(100) < 75;
		}
		else
		{
			for (int i = 0; i < num4; i++)
			{
				if (flag)
				{
					break;
				}
				flag = _rng.Next(100) < 25;
			}
		}
		GrudgeLog(string.Format("WAR sleep {0}h: {1} roll{2} at {3}%{4} - {5}", (num - sleepWatchMin) / 60, num4, (num4 == 1) ? "" : "s", flag2 ? 75 : 25, flag2 ? " (a night near a war)" : "", flag ? "gunfire when you wake" : "a quiet night"));
		if (flag)
		{
			_sleepBattleAt = Game.GameTime + 25000 + _rng.Next(35000);
		}
	}

	private bool WarNightAt(long gameMin)
	{
		int hour = FromGameMinutes(gameMin).Hour;
		if (hour < 21)
		{
			return hour < 5;
		}
		return true;
	}

	private void WakeBattle(Ped player)
	{
		if (!Config.DistantBattles || _skirmish.Count > 0 || _warKind != null || WorldBusy(player) || MISC.GET_MISSION_FLAG() || LawAfterYou() || InsideAnyTown(player.Position))
		{
			GrudgeLog("WAR wake battle: not now (busy / mission / wanted / town / a fight on) - skipped");
			return;
		}
		Vector3 me = player.Position;
		(Gang, Gang)? force = null;
		WarRecord warRecord = Wars.Where((WarRecord x) => x.Result == null && !TruceBetween(x.A, x.B) && FactionModels.ContainsKey(x.A) && FactionModels.ContainsKey(x.B)).OrderBy((WarRecord x) =>
		{
			District district2 = DistrictByKey(x.District);
			return (district2 != null) ? new Vector3(district2.X - me.X, district2.Y - me.Y, 0f).Length() : 1E+09f;
		}).FirstOrDefault();
		District district = ((warRecord != null) ? DistrictByKey(warRecord.District) : null);
		if (district != null && (district == CurrentDistrict || new Vector3(district.X - me.X, district.Y - me.Y, 0f).Length() < 2500f))
		{
			force = (Gangs.ById(warRecord.A), Gangs.ById(warRecord.B));
		}
		if (!force.HasValue)
		{
			District here = CurrentDistrict;
			if (here != null)
			{
				(Gang, Gang) tuple = (from x in Gangs.All
					where !x.StoryOnly && !IsDestroyed(x) && FactionModels.ContainsKey(x.Id) && HoldOf(here, x.Id) >= 3
					from y in from y in Gangs.All
						where string.CompareOrdinal(x.Id, y.Id) < 0 && !y.StoryOnly && !IsDestroyed(y) && FactionModels.ContainsKey(y.Id) && HoldOf(here, y.Id) >= 3 && Relation(x.Id, y.Id) <= Config.ClashLine && !TruceBetween(x.Id, y.Id)
						select y
					select (x: x, y: y) into t
					orderby Relation(t.x.Id, t.y.Id)
					select t).FirstOrDefault();
				if (tuple.Item1 != null)
				{
					force = (tuple.Item1, tuple.Item2);
				}
			}
		}
		if (!force.HasValue || force.Value.Item1 == null || force.Value.Item2 == null)
		{
			GrudgeLog("WAR wake battle: no war or cold outfits near you - nothing");
		}
		else if (TrySkirmish(player, town: false, test: false, rolled: true, force, distant: true))
		{
			_nextDistantAllowed = Game.GameTime + 240000;
			GrudgeLog("WAR wake battle: the " + force.Value.Item1.Name + " and the " + force.Value.Item2.Name + ", " + Away(me, _skirmishAt));
		}
		else
		{
			GrudgeLog("WAR wake battle: no hidden, loaded ground 200-250 m away");
		}
	}

	private Vector3 DistantSpot(Ped player)
	{
		Vector3 position = player.Position;
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		int num5 = 0;
		for (int i = 0; i < 16; i++)
		{
			double num6 = _rng.NextDouble() * Math.PI * 2.0;
			float num7 = 200f + (float)_rng.NextDouble() * 35f;
			Vector3 raw = new Vector3(position.X + (float)Math.Cos(num6) * num7, position.Y + (float)Math.Sin(num6) * num7, position.Z);
			STREAMING.REQUEST_COLLISION_AT_COORD(raw.X, raw.Y, raw.Z);
			if (!GroundOk(raw, out var p))
			{
				num++;
				continue;
			}
			if (InsideAnyTown(p))
			{
				num2++;
				continue;
			}
			if (!OnLand(p) || !Dry(p))
			{
				num3++;
				continue;
			}
			if (GangCamps.Any((Vector3 c) => new Vector3(c.X - p.X, c.Y - p.Y, 0f).Length() < 190f))
			{
				num4++;
				continue;
			}
			if (!HiddenFromView(player, p))
			{
				num5++;
				continue;
			}
			return p;
		}
		_distantSpotNote = $"no spot 200-235 m off out of your sight (16 tried: {num} no loaded ground, {num2} in a town, {num3} water, {num4} near the gang's camp, {num5} in view)";
		return Vector3.Zero;
	}

	private static string Adjective(Gang g)
	{
		string text = (g.Name.StartsWith("The ") ? g.Name.Substring(4) : g.Name);
		if (text.EndsWith("s") && !text.EndsWith("ss"))
		{
			text = text.Substring(0, text.Length - 1);
		}
		return text;
	}

	internal string NameWar(WarRecord w, District d, Gang a, Gang b, string cause)
	{
		HashSet<string> used = new HashSet<string>(from x in Wars.Concat(Chronicle.PastWars ?? new List<WarRecord>())
			where x != w && x.Name != null
			select x.Name);
		int num = Enumerable.Count(Chronicle.PastWars ?? new List<WarRecord>(), (WarRecord x) => x.District == w.District);
		string text = d?.Name ?? w.District;
		if (text.StartsWith("the ", StringComparison.OrdinalIgnoreCase))
		{
			text = text.Substring(4);
		}
		List<(string, int)> list = new List<(string, int)>();
		string text2 = Ordinals[Math.Min(num, Ordinals.Length - 1)];
		list.Add(("The " + text2 + text + " War", 3));
		string text3 = (cause ?? "").ToLowerInvariant() + " " + (w.GoalText ?? "").ToLowerInvariant();
		(string, string)[] causeWords = CauseWords;
		for (int num2 = 0; num2 < causeWords.Length; num2++)
		{
			var (value, text4) = causeWords[num2];
			if (text3.Contains(value))
			{
				list.Add(("The " + text4 + " War", 4));
				break;
			}
		}
		if (w.Goal == "camp" && w.GoalSite != null)
		{
			CampSite campSite = Camps.ById(w.GoalSite);
			if (campSite != null)
			{
				list.Add(("The War for " + campSite.Label.Replace("the ", "").Replace("The ", ""), 4));
			}
		}
		list.Add(("The " + Adjective(a) + "-" + Adjective(b) + " War", 2));
		if (Relation(a.Id, b.Id) <= -70)
		{
			list.Add(("The " + text + " Blood Feud", 3));
		}
		string leaderName = a.LeaderName;
		if (!string.IsNullOrEmpty(leaderName) && leaderName.Contains(" "))
		{
			list.Add((leaderName.Substring(leaderName.LastIndexOf(' ') + 1) + "'s War", 2));
		}
		int month = GameDate.FromMinutes(GameMinutesNow()).Month;
		string text5;
		if (month <= 2 || month == 12)
		{
			text5 = "Winter";
		}
		else if (month <= 5)
		{
			text5 = "Spring";
		}
		else
		{
			text5 = ((month <= 8) ? "Summer" : "Autumn");
		}
		list.Add(("The " + text5 + " War in " + text, 1));
		int cLOCK_HOURS = CLOCK.GET_CLOCK_HOURS();
		if (cLOCK_HOURS >= 21 || cLOCK_HOURS < 5)
		{
			list.Add(("The Night Riders' War", 1));
		}
		List<(string, int)> list2 = list.Where(((string name, int weight) o) => !used.Contains(o.name)).ToList();
		if (list2.Count == 0)
		{
			return "The " + Ordinals[Math.Min(num + 1, Ordinals.Length - 1)] + text + " War";
		}
		int num3 = _rng.Next(list2.Sum(((string name, int weight) o) => o.weight));
		foreach (var item in list2)
		{
			if ((num3 -= item.Item2) < 0)
			{
				return item.Item1;
			}
		}
		return list2[0].Item1;
	}

	internal string WarName(WarRecord w)
	{
		if (w == null)
		{
			return "the war";
		}
		if (string.IsNullOrEmpty(w.Name))
		{
			Gang gang = Gangs.ById(w.A);
			Gang gang2 = Gangs.ById(w.B);
			if (gang != null && gang2 != null)
			{
				w.Name = NameWar(w, DistrictByKey(w.District), gang, gang2, w.Cause);
				SaveWorld();
			}
		}
		if (w.Name != null && w.Name.Contains("The the "))
		{
			w.Name = w.Name.Replace("The the ", "The ");
			SaveWorld();
		}
		return w.Name ?? "the war";
	}

	internal void DebugStartWar(Ped player)
	{
		District d = CurrentDistrict;
		if (d == null)
		{
			ShowNotification("enRAGE: this isn't a district the mod knows - no war here.");
			return;
		}
		List<string> warZones = Chronicle.WarZones;
		if (warZones != null && warZones.Any((string t) => t.StartsWith(d.Key + ":")))
		{
			ShowNotification("enRAGE: there's already a war in " + d.Name + ".");
			return;
		}
		List<Gang> list = (from g in Gangs.All
			where !g.StoryOnly && g.TurfWars && !IsDestroyed(g) && FactionModels.ContainsKey(g.Id)
			orderby HoldOf(d, g.Id) descending
			select g).Take(2).ToList();
		if (list.Count < 2)
		{
			ShowNotification("enRAGE: not two outfits to fight over " + d.Name + ".");
			return;
		}
		Gang a = list[0];
		Gang b = list[1];
		Gang[] array = new Gang[2] { a, b };
		foreach (Gang gang in array)
		{
			if (HoldOf(d, gang.Id) < 20)
			{
				ShiftControl(d, gang, 20 - HoldOf(d, gang.Id), "a war started from the spawner (debug)");
			}
		}
		Truces.RemoveAll((string s) =>
		{
			string[] array2 = s.Split('|');
			return (array2[0] == a.Id && array2[1] == b.Id) || (array2[0] == b.Id && array2[1] == a.Id);
		});
		int num2 = Relation(a.Id, b.Id);
		if (num2 > -50)
		{
			ShiftRelation(a.Id, b.Id, -50 - num2, "a war started from the spawner (debug)", force: true);
		}
		Chronicle.WarEndedAt?.Remove(d.Key);
		DeclareWar(d, a, b, "it was started from the spawner (debug)");
		WarRecord w = Wars.FirstOrDefault((WarRecord x) => x.District == d.Key);
		ShowNotification("enRAGE: " + WarName(w) + " - the " + a.Name + " vs the " + b.Name + " in " + d.Name + ".");
	}

	internal void DebugDistantBattle(Ped player)
	{
		if (_skirmish.Count > 0)
		{
			ShowNotification("enRAGE: a fight is already going on.");
			return;
		}
		Vector3 me = player.Position;
		WarRecord warRecord = Wars.Where((WarRecord x) => x.Result == null && FactionModels.ContainsKey(x.A) && FactionModels.ContainsKey(x.B)).OrderBy((WarRecord x) =>
		{
			District district = DistrictByKey(x.District);
			return (district != null) ? new Vector3(district.X - me.X, district.Y - me.Y, 0f).Length() : 1E+09f;
		}).FirstOrDefault();
		if (warRecord == null)
		{
			ShowNotification("enRAGE: no war with men to send - start one first.");
			return;
		}
		Gang gang = Gangs.ById(warRecord.A);
		Gang gang2 = Gangs.ById(warRecord.B);
		if (TrySkirmish(player, town: false, test: false, rolled: true, (gang, gang2), distant: true))
		{
			_nextDistantAllowed = Game.GameTime + 240000;
			ShowNotification("enRAGE: a battle " + Away(me, _skirmishAt) + " - listen.");
			GrudgeLog("WAR distant battle (debug): the " + gang.Name + " and the " + gang2.Name + ", " + Away(me, _skirmishAt));
		}
		else
		{
			ShowNotification("enRAGE: no hidden, loaded ground 200-250 m away - try again elsewhere.");
		}
	}

	internal List<(WarRecord w, bool live)> WarList()
	{
		List<WarRecord> list = Wars.Where((WarRecord x) => x.Result == null || (Chronicle.WarZones?.Any((string t) => t.StartsWith(x.District + ":")) ?? false)).ToList();
		foreach (WarRecord item in list)
		{
			InitHeat(item);
		}
		List<(WarRecord x, bool)> list2 = (from x in list
			orderby x.Heat descending
			select (x: x, true)).ToList();
		list2.AddRange(from x in Chronicle.PastWars ?? new List<WarRecord>()
			orderby x.EndMin descending
			select (x: x, false));
		return list2;
	}

	internal District DistrictByKey(string key)
	{
		return Districts.FirstOrDefault((District x) => x.Key == key);
	}

	internal List<WorldEvent> WarTimeline(WarRecord w, int max)
	{
		long end = ((w.EndMin > 0) ? (w.EndMin + 60) : long.MaxValue);
		return (from e in Chronicle.Events
			where !e.IsPast && e.GameMin >= w.StartMin - 5 && e.GameMin <= end && e.Gangs.Contains(w.A) && e.Gangs.Contains(w.B) && (e.Kind == "WAR" || WarOfFight(w.A, w.B, e.HasPos ? DistrictAt(new Vector3(e.X, e.Y, e.Z)) : null, e.GameMin, liveOnly: false) == w)
			orderby e.GameMin descending
			select e).Take(max).ToList();
	}

	internal int WarCampsTaken(WarRecord w)
	{
		return Enumerable.Count(WarTimeline(w, 200), (WorldEvent e) => e.Kind == "CAMP OVERRUN");
	}

	internal List<(WorldEvent e, int dead)> WarFights(WarRecord w)
	{
		return (from e in WarTimeline(w, 200)
			where FightKinds.Contains(e.Kind)
			select (e: e, Enumerable.Count(e.People, (WorldPart p) => p.Outcome == "KILLED") + (e.UnnamedDead?.Values.Sum() ?? 0))).ToList();
	}

	internal List<(string name, Gang side, string rank, string when)> WarNamedDead(WarRecord w)
	{
		List<(string, Gang, string, string)> list = new List<(string, Gang, string, string)>();
		foreach (var item3 in WarFights(w))
		{
			WorldEvent item = item3.e;
			foreach (WorldPart item4 in item.People.Where((WorldPart p) => p.Outcome == "KILLED"))
			{
				NemesisRecord nemesisRecord = FindRecord(item4.Id);
				Gang item2 = Gangs.ById(item4.Gang ?? nemesisRecord?.Gang);
				string text = ((nemesisRecord != null) ? RosterMenu.RankText(nemesisRecord) : "");
				int num = text.IndexOf(" (");
				if (num > 0)
				{
					text = text.Substring(0, num);
				}
				list.Add((item4.Name ?? nemesisRecord?.Name ?? "a man", item2, text, GameDate.FromMinutes(item.GameMin).ToString("MMM d")));
			}
		}
		return list;
	}

	internal string WarLeader(Gang g)
	{
		if (g == null)
		{
			return null;
		}
		Personality? personality = LeaderTemper(g);
		if (personality.HasValue)
		{
			return string.Format("{0} ({1})", g.LeaderName ?? "their leader", personality.Value);
		}
		return "None - the seat is empty";
	}

	internal string WarAim(Gang g)
	{
		if (g != null && AgendaOf(g) != null)
		{
			return Cap1(AgendaText(g));
		}
		return null;
	}

	internal string WarPurse(Gang g)
	{
		if (g == null || !HasPurse(g))
		{
			return null;
		}
		int num = PurseOf(g);
		return $"${num:N0}  -  {PurseWord(num)}";
	}

	internal string WarCosts(Gang g)
	{
		if (g == null || !HasPurse(g))
		{
			return null;
		}
		int num = PurseOf(g);
		int num2 = WarsOf(g);
		List<string> list = new List<string>();
		if (num2 > 0)
		{
			list.Add(string.Format("${0} a day{1}", 15 * num2, (num2 > 1) ? $" ({num2} wars)" : ""));
		}
		if (num < 60)
		{
			list.Add("smaller crews, recruits fail");
		}
		else if (num >= 1200)
		{
			list.Add("bigger crews");
		}
		if (list.Count != 0)
		{
			return string.Join("  -  ", list);
		}
		return null;
	}

	private static string Cap1(string s)
	{
		if (!string.IsNullOrEmpty(s))
		{
			return char.ToUpperInvariant(s[0]) + s.Substring(1);
		}
		return s;
	}

	private void DrawWarHud(Ped player)
	{
		if (!Config.WarHud)
		{
			return;
		}
		if (Game.IsControlPressed((eInputType)3481947850u) || Game.IsDisabledControlPressed((eInputType)3481947850u))
		{
			_warHudPressedAt = Game.GameTime;
		}
		District d = CurrentDistrict;
		(Gang, Gang)? tuple = ((d != null) ? WarIn(d) : (((Gang, Gang)?)null));
