			string text2 = null;
			float warHudW = Config.WarHudW;
			float num = ((Config.WarHudX < 0f) ? ((1f - warHudW) / 2f) : Config.WarHudX);
			float warHudY = Config.WarHudY;
			float sc = 0.23f;
			float num2 = 0.3f;
			float num3 = 0.24f;
			float scale = 0.21f;
			while (Theme.CapsWidth(s, num2) > warHudW - 0.024f && num2 > 0.2f)
			{
				num2 -= 0.01f;
			}
