	private bool TrySkirmish(Ped player, bool town, bool test, bool rolled = false, (Gang a, Gang b)? force = null, bool distant = false)
	{
		if (_skirmish.Count > 0 || (town && !test))
		{
			return false;
		}
		if (force.HasValue)
		{
			rolled = true;
		}
		(Gang, Gang)? tuple = WarHere;
		if (tuple.HasValue && (!FactionModels.ContainsKey(tuple.Value.Item1.Id) || !FactionModels.ContainsKey(tuple.Value.Item2.Id)))
		{
			tuple = null;
		}
		if (!test && !rolled && _rng.Next(100) >= Balance.SkirmishChance * ((!tuple.HasValue) ? 1 : 3))
		{
			return false;
		}
		List<(Gang, Gang)> list = new List<(Gang, Gang)>();
		if (force.HasValue)
		{
			list.Add(force.Value);
		}
		else if (tuple.HasValue)
		{
			list.Add((tuple.Value.Item1, tuple.Value.Item2));
		}
		else
		{
			District currentDistrict = CurrentDistrict;
			if (currentDistrict != null)
			{
				Gang[] all = Gangs.All;
				foreach (Gang gang in all)
				{
					Gang[] all2 = Gangs.All;
					foreach (Gang gang2 in all2)
					{
						if (string.CompareOrdinal(gang.Id, gang2.Id) < 0 && !gang.StoryOnly && !gang2.StoryOnly && FactionModels.ContainsKey(gang.Id) && FactionModels.ContainsKey(gang2.Id) && Relation(gang.Id, gang2.Id) <= Config.ClashLine)
						{
							int num = HoldOf(currentDistrict, gang.Id);
							int num2 = HoldOf(currentDistrict, gang2.Id);
							if ((num >= 5 && num2 >= 5) || (gang.OrdersNotFeelings && num2 >= 10) || (gang2.OrdersNotFeelings && num >= 10))
							{
								list.Add((gang, gang2));
							}
						}
					}
				}
			}
		}
		if (test && list.Count == 0)
		{
			(Gang, Gang) tuple2 = (from x in Gangs.All
				where !x.StoryOnly && FactionModels.ContainsKey(x.Id) && !IsDestroyed(x)
				from y in from y in Gangs.All
					where string.CompareOrdinal(x.Id, y.Id) < 0 && !y.StoryOnly && FactionModels.ContainsKey(y.Id) && !IsDestroyed(y)
					select y
				select (x: x, y: y) into t
				orderby Relation(t.x.Id, t.y.Id)
				select t).FirstOrDefault();
			if (tuple2.Item1 != null)
			{
				list.Add((tuple2.Item1, tuple2.Item2));
			}
		}
		if (list.Count == 0)
		{
			return false;
		}
		list.RemoveAll(((Gang a, Gang b) p) => TruceBetween(p.a.Id, p.b.Id) || IsDestroyed(p.a) || IsDestroyed(p.b));
		if (list.Count == 0)
		{
			return false;
		}
		var (gang3, gang4) = list[_rng.Next(list.Count)];
		if (distant && _rng.Next(2) == 0)
		{
			Gang gang5 = gang4;
			gang4 = gang3;
			gang3 = gang5;
		}
		_skirmishGangA = gang3.Id;
		_skirmishGangB = gang4.Id;
		Vector3 fwd = Forward(player);
		Vector3 vector = new Vector3(fwd.Y, 0f - fwd.X, 0f);
		_skirmishAt = (distant ? DistantSpot(player) : GoodSpot(player, () =>
		{
			double num6 = Math.Atan2(fwd.Y, fwd.X) + (_rng.NextDouble() * 2.0 - 1.0) * 1.4;
			float num7 = 110f + (float)_rng.NextDouble() * 50f;
			return Ground(player.Position + new Vector3((float)Math.Cos(num6) * num7, (float)Math.Sin(num6) * num7, 0f));
		}, 14));
		if (_skirmishAt == Vector3.Zero)
		{
			GrudgeLog("SKIRMISH no dry ground near you - not sent");
			return false;
		}
		if (_sideA == 0)
		{
			_sideA = World.AddRelationshipGroup("SKIRMISH_A");
			_sideB = World.AddRelationshipGroup("SKIRMISH_B");
		}
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _sideA, _sideB);
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _sideB, _sideA);
		int relationship = (distant ? 3 : 4);
		World.SetRelationshipBetweenGroups((eRelationshipType)relationship, _sideA, player.RelationshipGroup);
		World.SetRelationshipBetweenGroups((eRelationshipType)relationship, _sideB, player.RelationshipGroup);
		SkirmishDistant = distant;
		float num3 = (distant ? 22f : 12f);
		int num4 = SpawnSide(gang3, _sideA, _skirmishAt + vector * (0f - num3), distant ? 12 : 50, distant ? 2 : 0);
		int num5 = 0;
		if (distant)
		{
			_pendingSide = (gang4, _skirmishAt + vector * num3);
			_pendingSideAt = Game.GameTime + 2000;
		}
		else
		{
			num5 = SpawnSide(gang4, _sideB, _skirmishAt + vector * num3);
			foreach (Ped item in _skirmish.Where((Ped p) => p.Exists()))
			{
				TASK.TASK_COMBAT_HATED_TARGETS_AROUND_PED(item.Handle, 80f, 0, 0uL);
			}
		}
		_skirmishEnds = Game.GameTime + (distant ? 480000 : 300000);
		SkirmishNote = string.Format("{0} ({1}) vs {2} ({3}) in {4}{5}", gang3.Name, num4, gang4.Name, num5, RegionName, distant ? $" - distant, {_skirmishAt.DistanceTo(player.Position):0} m off" : "");
		if (distant)
		{
			Feed("WAR gunfire, far off to the " + Compass(player.Position, _skirmishAt) + " - the " + gang3.Name + " and the " + gang4.Name, Theme.Warn);
			GrudgeLog("SKIRMISH " + SkirmishNote);
			return true;
		}
		_skirmishBlip = AddFightBlip(_skirmishAt, gang3.Name + " vs " + gang4.Name);
		GrudgeNotice("Gunfire ahead: the " + gang3.Name + " and the " + gang4.Name + " are at each other's throats.");
		GrudgeLog("SKIRMISH " + SkirmishNote);
		return true;
	}

	private void ChronicleSkirmish(Ped player)
	{
		Gang gang = Gangs.ById(_skirmishGangA);
		Gang gang2 = Gangs.ById(_skirmishGangB);
		if (gang == null || gang2 == null || !_skirmish.Any((Ped p) => p != null && p.Exists()))
		{
			return;
		}
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		foreach (Ped item2 in _skirmish.Where((Ped p) => p != null && p.Exists()))
		{
			bool flag = ModGroupOf(item2.Handle) == _sideA;
			bool flag2 = item2.IsDead && !LooksKnockedOut(item2);
			if (flag)
			{
				if (flag2)
				{
					num3++;
				}
				else
				{
					num++;
				}
			}
			else if (flag2)
			{
				num4++;
			}
			else
			{
				num2++;
			}
		}
		List<WorldPart> list = new List<WorldPart>();
		int num5 = 0;
		int num6 = 0;
		foreach (KeyValuePair<int, NemesisRecord> item3 in _skirmishNamed)
		{
			NemesisRecord value = item3.Value;
			Ped ped = Entity.FromHandle(item3.Key) as Ped;
			bool flag3 = !value.IsAlive || value.PresumedDead || (ped != null && ped.Exists() && ped.IsDead && !LooksKnockedOut(ped));
			bool flag4 = !flag3 && ped != null && ped.Exists() && (float)ped.Health < (float)ped.MaxHealth * 0.6f;
			if (flag3)
			{
				if (value.Gang == gang.Id)
				{
					num5++;
				}
				else
				{
					num6++;
				}
			}
			NemesisMod nemesisMod = this;
			NemesisRecord r = value;
			string outcome;
			if (flag3)
			{
				outcome = "KILLED";
			}
			else
			{
				outcome = (flag4 ? "WOUNDED" : "UNHURT");
			}
			WorldPart worldPart = nemesisMod.PartFor(r, outcome, value.Title);
			worldPart.SecretlyLived = flag3 && value.IsAlive;
			list.Add(worldPart);
		}
		bool flag5 = _skirmish.Any((Ped p) => p != null && p.Exists() && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(p.Handle, player.Handle, p2: true, p3: true));
		List<string> list2 = new List<string>();
		List<string> list3 = list2;
		string item;
		if (num > num2)
		{
			item = "The " + gang.Name + " held the field.";
		}
		else
		{
			item = ((num2 > num) ? ("The " + gang2.Name + " held the field.") : "Neither side came out ahead.");
		}
		list3.Add(item);
		list2.Add($"{gang.Name}: {num3} down.  {gang2.Name}: {num4} down.");
		List<string> list4 = list2;
		if (flag5)
		{
			list4.Add("You joined in.");
		}
		else if (SkirmishDistant)
		{
			list4.Add((player.Position.DistanceTo(_skirmishAt) > 120f) ? "You heard it from a way off." : "You heard it, and rode over to see.");
		}
		Dictionary<string, int> dictionary = new Dictionary<string, int>
		{
			[gang.Id] = Math.Max(0, num3 - num5),
			[gang2.Id] = Math.Max(0, num4 - num6)
		};
		LoseMen(gang, Math.Max(0, dictionary[gang.Id] - YoursOf(_sideA)), "a skirmish");
		LoseMen(gang2, Math.Max(0, dictionary[gang2.Id] - YoursOf(_sideB)), "a skirmish");
		bool flag6 = false;
		if (num != num2)
		{
			try
			{
				flag6 = SkirmishForWar(_skirmishAt, (num > num2) ? gang : gang2, (num > num2) ? gang2 : gang, (num > num2) ? num4 : num3, (num > num2) ? num3 : num4, list4);
			}
			catch (Exception ex)
			{
				GrudgeLog("WAR skirmish note failed: " + ex.Message);
			}
		}
		ChronicleWitness((SkirmishDistant && !flag5) ? ("Gunfire in the distance: the " + gang.Name + " and the " + gang2.Name) : ("The " + gang.Name + " and the " + gang2.Name + " fought"), "near " + GetZoneName(_skirmishAt), _skirmishAt, new string[2] { gang.Id, gang2.Id }, list, dictionary, list4);
		NoteLiveClash(gang.Id, gang2.Id, num5 + num6, "near " + GetZoneName(_skirmishAt), _skirmishAt);
		if (num == num2 || flag6)
		{
			return;
		}
		try
		{
			ControlAfterSkirmish(_skirmishAt, (num > num2) ? gang : gang2, (num > num2) ? gang2 : gang);
		}
		catch
		{
		}
		int YoursOf(uint grp)
		{
			return Enumerable.Count(_skirmish, (Ped p) => p != null && p.Exists() && p.IsDead && ModGroupOf(p.Handle) == grp && PED.GET_PED_SOURCE_OF_DEATH(p.Handle) == player.Handle && !_worldNemeses.ContainsKey(p.Handle));
		}
	}

	private int SpawnSide(Gang g, uint group, Vector3 at, int namedPct = 50, int extra = 0)
	{
		int num = 3 + _rng.Next(3) + extra;
		PedHash[] array = FactionModels[g.Id];
		NemesisRecord nemesisRecord = ((_rng.Next(100) < namedPct) ? (from _ in Roster
			where _.Gang == g.Id && _.CanHunt && !_.PresumedDead && !_worldNemeses.ContainsValue(_) && _ != ActiveRecord && (_.Id == null || !_.Id.StartsWith("lore_")) && _.LoreModel == null && SeatOf(g)?.Successor != _.Id
			orderby _rng.Next()
			select _).FirstOrDefault() : null);
		int num2 = 0;
		for (int num3 = 0; num3 < num; num3++)
		{
			float num4 = ((extra > 0) ? 14f : 8f);
			Vector3 pos = Ground(at + new Vector3((float)_rng.NextDouble() * num4 - num4 / 2f, (float)_rng.NextDouble() * num4 - num4 / 2f, 0f));
			NemesisRecord nemesisRecord2 = ((num3 == 0) ? nemesisRecord : null);
			Crumbs.Native($"skirmish spawn {g.Id} {num3 + 1}/{num}");
			Ped ped = SpawnPed((PedHash)(((int?)nemesisRecord2?.ModelHash) ?? ((int)array[_rng.Next(array.Length)])), pos, _rng.Next(360));
			if (!(ped == null))
			{
				MakeOurs(ped.Handle);
				WEAPON.REMOVE_ALL_PED_WEAPONS(ped.Handle, p1: true, p2: true);
				if (g.TribalKit)
				{
					ArmTroop(ped, g);
				}
				else
				{
					ped.GiveWeapon(g.TroopLongGuns ? ((eWeapon)4111948705u) : ((eWeapon)379542007u), 120, g.TroopLongGuns ? ((eWeaponAttachPoint)9) : ((eWeaponAttachPoint)2), equipNow: true, isAmmoLoaded: false, a6: false);
				}
				ped.RelationshipGroup = group;
				ped.BlockPermanentEvents = false;
				ApplyFactionStyle(ped, g.Id);
				if (nemesisRecord2 != null)
				{
					_worldNemeses[ped.Handle] = nemesisRecord2;
					_skirmishNamed[ped.Handle] = nemesisRecord2;
					ApplyScars(ped, nemesisRecord2);
				}
				_skirmish.Add(ped);
				num2++;
			}
		}
		if (num2 < num)
		{
			GrudgeLog($"SKIRMISH {g.Id}: {num2} of {num} men spawned");
		}
		return num2;
	}

	private void HeatTheDistantBattle()
	{
		Gang ga = Gangs.ById(_skirmishGangA);
		WarRecord warRecord = ((ga != null) ? WarOf(ga, _skirmishAt) : null);
		if (warRecord == null && ga != null && _skirmishGangB != null)
		{
			warRecord = Wars.FirstOrDefault((WarRecord x) => x.Result == null && ((x.A == ga.Id && x.B == _skirmishGangB) || (x.B == ga.Id && x.A == _skirmishGangB)));
		}
		if (warRecord != null)
		{
			InitHeat(warRecord);
		}
		int num = warRecord?.Heat ?? 0;
		ref int boomsLeft = ref _boomsLeft;
		int num2;
		if (num >= 75)
		{
			num2 = 4;
		}
		else
		{
			num2 = ((num >= 55) ? 3 : 2);
		}
		boomsLeft = num2;
		_nextBoomAt = Game.GameTime + 6000 + _rng.Next(8000);
		if (num < 45)
		{
			GrudgeLog($"SKIRMISH distant: heat {num} - no riflemen, {_boomsLeft} explosion(s) to come");
			return;
		}
		int num3 = ((num < 70) ? 1 : 2);
		uint[] array = new uint[2] { _sideA, _sideB };
		foreach (uint grp in array)
		{
			foreach (Ped item in (from _ in _skirmish
				where _.Exists() && !_.IsDead && ModGroupOf(_.Handle) == grp
				orderby _rng.Next()
				select _).Take(num3))
			{
				item.GiveWeapon((_rng.Next(2) == 0) ? ((eWeapon)1999408598u) : ((eWeapon)1676963302u), 60, (eWeaponAttachPoint)9, equipNow: true, isAmmoLoaded: false, a6: false);
				PED.SET_PED_COMBAT_RANGE(item.Handle, 2);
				PED.SET_PED_ACCURACY(item.Handle, 25 + _rng.Next(15));
			}
		}
		GrudgeLog($"SKIRMISH distant: heat {num} - {num3} rifleman a side, {_boomsLeft} explosion(s) to come");
	}

	private void DistantBooms(Ped player)
	{
		if (_boomsLeft <= 0 || Game.GameTime < _nextBoomAt)
		{
			return;
		}
		if (player.Position.DistanceTo(_skirmishAt) < 120f || WorldBusy(player) || !MapSettled())
		{
			_nextBoomAt = Game.GameTime + 5000;
			return;
		}
		List<Ped> list = _skirmish.Where((Ped p) => p.Exists() && !p.IsDead).ToList();
		if (list.Count == 0)
		{
			_boomsLeft = 0;
			return;
		}
		Vector3 position = list[_rng.Next(list.Count)].Position;
		double num = _rng.NextDouble() * Math.PI * 2.0;
		float num2 = 5f + (float)_rng.NextDouble() * 4f;
		Vector3 vector = new Vector3(position.X + (float)Math.Cos(num) * num2, position.Y + (float)Math.Sin(num) * num2, position.Z);
		Ped owner = BoomOwner(list, vector);
		if (!ModExplosion(vector, 0f, owner, "skirmish explosion"))
		{
			_nextBoomAt = Game.GameTime + 5000;
			return;
		}
		QueueVolley(vector, owner, "skirmish explosion");
		_boomsLeft--;
		_nextBoomAt = Game.GameTime + 10000 + _rng.Next(15000);
		GrudgeLog($"SKIRMISH boom at {vector.X:0},{vector.Y:0} ({player.Position.DistanceTo(vector):0} m from you, tag {DistantExplosionTag}), {_boomsLeft} left");
	}

	private void SkirmishTurnsOnYou(Ped player)
	{
		if ((_turnedA && _turnedB) || Game.GameTime < _nextTurnCheck)
		{
			return;
		}
		_nextTurnCheck = Game.GameTime + 400;
		List<Ped> list = _skirmish.Where((Ped p) => p != null && p.Exists() && !p.IsDead).ToList();
		if (list.Count == 0)
		{
			return;
		}
		Vector3 me = player.Position;
		bool flag = false;
		bool flag2 = false;
		foreach (Ped item in _skirmish)
		{
			if (!(item == null) && item.Exists() && ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(item.Handle, player.Handle, p2: true, p3: true))
			{
				if (ModGroupOf(item.Handle) == _sideA)
				{
					flag = true;
				}
				else
				{
					flag2 = true;
				}
			}
		}
		if (!flag && !flag2 && (GunMelee.PlayerFiredRecently || PED.IS_PED_SHOOTING(player.Handle)) && !GameEventGunfire)
		{
			Ped ped = (from p in list
				where p.Position.DistanceTo(me) < 60f
				orderby p.Position.DistanceTo(me)
				select p).FirstOrDefault();
			if (ped != null)
			{
				if (ModGroupOf(ped.Handle) == _sideA)
				{
					flag = true;
				}
				else
				{
					flag2 = true;
				}
			}
		}
		if (flag && !_turnedA)
		{
			_turnedA = true;
			TurnSide(_sideA, player, list);
		}
		if (flag2 && !_turnedB)
		{
			_turnedB = true;
			TurnSide(_sideB, player, list);
		}
	}

	private void TurnSide(uint grp, Ped player, List<Ped> alive)
	{
		Crumbs.Native("skirmish turns on you");
		World.SetRelationshipBetweenGroups((eRelationshipType)6, grp, player.RelationshipGroup);
		World.SetRelationshipBetweenGroups((eRelationshipType)6, player.RelationshipGroup, grp);
		int num = 0;
		foreach (Ped item in alive)
		{
			if (ModGroupOf(item.Handle) == grp)
			{
				PED.SET_PED_ACCURACY(item.Handle, 25 + _rng.Next(15));
				if (!(item.Position.DistanceTo(player.Position) > 120f))
				{
					TASK.TASK_COMBAT_PED(item.Handle, player.Handle, 0, 16);
					num++;
				}
			}
		}
		string arg = ((grp == _sideA) ? "first" : "second");
		GrudgeLog(string.Format("SKIRMISH you joined in - the {0} side turns on you ({1} men coming{2})", arg, num, SkirmishDistant ? ", a distant battle" : ""));
	}

	private unsafe void UpdateSkirmish(Ped player)
	{
		if (_skirmish.Count == 0)
		{
			_pendingSide = null;
			_turnedA = (_turnedB = false);
			return;
		}
		if (_pendingSide.HasValue)
		{
			if (Game.GameTime < _pendingSideAt)
			{
				return;
			}
			(Gang, Vector3) value = _pendingSide.Value;
			_pendingSide = null;
			int num = SpawnSide(value.Item1, _sideB, value.Item2, 12, 2);
			Crumbs.Native("skirmish combat tasks");
			foreach (Ped item2 in _skirmish.Where((Ped p) => p.Exists()))
			{
				PED.SET_PED_ACCURACY(item2.Handle, 8 + _rng.Next(10));
				TASK.TASK_COMBAT_HATED_TARGETS_AROUND_PED(item2.Handle, 120f, 0, 0uL);
			}
			GrudgeLog($"SKIRMISH distant: the {value.Item1.Name} ({num}) are there too - fighting");
			HeatTheDistantBattle();
			return;
		}
		if (SkirmishDistant)
		{
			DistantBooms(player);
		}
		if (UpdateWarBuildUp(player))
		{
			return;
		}
		SkirmishTurnsOnYou(player);
		bool flag = (_turnedA || _turnedB) && _skirmish.Any((Ped p) => p.Exists() && !p.IsDead && p.Position.DistanceTo(player.Position) < 250f && ((_turnedA && ModGroupOf(p.Handle) == _sideA) || (_turnedB && ModGroupOf(p.Handle) == _sideB)));
		bool flag2 = !_skirmish.Any((Ped p) => p.Exists() && !p.IsDead && ModGroupOf(p.Handle) == _sideA) || !_skirmish.Any((Ped p) => p.Exists() && !p.IsDead && ModGroupOf(p.Handle) == _sideB);
		if ((Game.GameTime <= _skirmishEnds || (flag && Game.GameTime <= _skirmishEnds + 180000)) && !(player.Position.DistanceTo(_skirmishAt) > 400f) && (!flag2 || flag))
		{
			return;
		}
		int num2 = Enumerable.Count(_skirmish, (Ped p) => p != null && p.Exists() && p.IsDead && ModGroupOf(p.Handle) == _sideA);
		int num3 = Enumerable.Count(_skirmish, (Ped p) => p != null && p.Exists() && p.IsDead && ModGroupOf(p.Handle) == _sideB);
		GrudgeLog(string.Format("SKIRMISH ending{0}: {1} + {2} dead of {3}, {4:0} m from you, {5}", SkirmishDistant ? " (distant)" : "", num2, num3, _skirmish.Count, player.Position.DistanceTo(_skirmishAt), (Game.GameTime > _skirmishEnds) ? "time up" : ((player.Position.DistanceTo(_skirmishAt) > 400f) ? "you rode off" : "one side is down")));
		try
		{
			ChronicleSkirmish(player);
		}
		catch (Exception ex)
		{
			GrudgeLog("WORLD skirmish chronicle failed: " + ex.Message);
		}
		_skirmishNamed.Clear();
		List<Ped> list = new List<Ped>();
		List<Ped> list2 = new List<Ped>();
		foreach (Ped item3 in _skirmish)
		{
			if (item3 == null || !item3.Exists())
			{
				continue;
			}
			int handle = item3.Handle;
			if (!item3.IsDead && !ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(handle, player.Handle, p2: true, p3: true))
			{
				try
				{
					((ModGroupOf(handle) == _sideA) ? list : list2).Add(item3);
					PED.SET_PED_RELATIONSHIP_GROUP_HASH(handle, PED.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH(handle));
					ForgetSwitch(handle);
					TASK.CLEAR_PED_TASKS(handle, p1: false, p2: false);
					Flee(handle, player.Handle, 300f, -1, 1f);
				}
				catch
				{
				}
			}
			ReleaseIfOurs(&handle);
		}
		_skirmish.Clear();
		(List<Ped>, string)[] array = new (List<Ped>, string)[2]
		{
			(list, _skirmishGangA),
			(list2, _skirmishGangB)
		};
		for (int num4 = 0; num4 < array.Length; num4++)
		{
			(List<Ped>, string) tuple = array[num4];
			List<Ped> item = tuple.Item1;
			Gang gang = Gangs.ById(tuple.Item2);
			RegisterBand(item, gang, (gang != null) ? ("the " + OutfitWord(gang) + " men left from the skirmish") : "the men left from the skirmish");
		}
		if (_sideA != 0)
		{
			World.SetRelationshipBetweenGroups((eRelationshipType)3, _sideA, player.RelationshipGroup);
			World.SetRelationshipBetweenGroups((eRelationshipType)3, _sideB, player.RelationshipGroup);
			World.SetRelationshipBetweenGroups((eRelationshipType)3, player.RelationshipGroup, _sideA);
			World.SetRelationshipBetweenGroups((eRelationshipType)3, player.RelationshipGroup, _sideB);
		}
		_turnedA = (_turnedB = false);
		Crumbs.Native("World blip remove");
		if (_skirmishBlip != 0)
		{
			int skirmishBlip = _skirmishBlip;
			MAP.REMOVE_BLIP(&skirmishBlip);
			_skirmishBlip = 0;
		}
		ReleaseWarHorses();
		GrudgeLog("SKIRMISH over");
		SkirmishDistant = false;
		_boomsLeft = 0;
		SkirmishNote = "";
	}

	internal bool HiresHunters(NemesisRecord r)
	{
		if (r.CanHunt && !r.PresumedDead && r.Wealth == Wealth.Rich && r.HateTier != HateTier.Resentful && (r.Personality == Personality.Coward || EffectiveFear(r) >= 50))
		{
			return IntentOf(r) != Intent.Hunts;
		}
		return false;
	}

	private void SendBountyHunters(NemesisRecord rec, Ped player)
	{
		if (_hunters.Count > 0)
		{
			return;
		}
		_huntersBy = rec;
		NoteCame(rec);
		SetWorldPaused(paused: false);
		Vector3 fwd = Forward(player);
		Vector3 vector = GoodSpot(player, () => Ground(player.Position - fwd * 110f + new Vector3(fwd.Y, 0f - fwd.X, 0f) * ((float)_rng.NextDouble() * 60f - 30f)));
		if (vector == Vector3.Zero)
		{
			GrudgeLog("HUNTERS no dry ground behind you - not sent");
			return;
		}
		if (_huntersGroup == 0)
		{
			_huntersGroup = World.AddRelationshipGroup("NEMESIS_HUNTERS");
		}
		World.SetRelationshipBetweenGroups((eRelationshipType)6, _huntersGroup, player.RelationshipGroup);
		int num = 3 + CrewBonus(Gangs.ById(rec.Gang));
		for (int num2 = 0; num2 < num; num2++)
		{
			Ped ped = SpawnPed((PedHash)427032133u, Ground(vector + new Vector3((float)num2 * 2f, (float)num2 * 1.5f, 0f)), HeadingTo(vector, player.Position));
			if (!(ped == null))
			{
				MakeOurs(ped.Handle);
				WEAPON.REMOVE_ALL_PED_WEAPONS(ped.Handle, p1: true, p2: true);
				ped.GiveWeapon((num2 == 0) ? ((eWeapon)834124286u) : ((eWeapon)2823250668u), 120, (eWeaponAttachPoint)9, equipNow: true, isAmmoLoaded: false, a6: false);
				ped.Accuracy = 35;
				ped.BlockPermanentEvents = true;
				ped.RelationshipGroup = _huntersGroup;
				Ped ped2 = MountOnHorse(ped);
				if (ped2 != null)
				{
					_encHorses.Remove(ped2);
					_hunterHorses.Add(ped2);
				}
				TASK.TASK_COMBAT_PED(ped.Handle, player.Handle, 0, 16);
				PED.SET_PED_KEEP_TASK(ped.Handle, p1: true);
				_followerOf[ped.Handle] = rec;
				Crumbs.Native("World blip add (V2)");
				_hunterBlips.Add(ped.AddBlip((BlipType)831283580u));
				_hunters.Add(ped);
			}
		}
		_huntersEnd = Game.GameTime + 240000;
		rec.TimesAmbushed++;
		rec.Touch();
		SaveRoster();
		GrudgeNotice("Bounty hunters on your trail - paid for by " + rec.FullName + ".");
		GrudgeLog($"HUNTERS x{num} hired by {rec.Name} (rich {rec.Personality}, fear {EffectiveFear(rec)})");
	}

	private unsafe void UpdateHunters(Ped player)
	{
		if (_hunters.Count == 0 || (Game.GameTime < _huntersEnd && _hunters.Any((Ped h) => h.Exists() && !h.IsDead && h.Position.DistanceTo(player.Position) < 350f)))
		{
			return;
		}
		List<Ped> list = _hunters.Where((Ped h) => h != null && h.Exists() && h.IsDead && PED.GET_PED_SOURCE_OF_DEATH(h.Handle) == player.Handle).ToList();
		if (list.Count > 0)
		{
			try
			{
				Vector3 position = list[0].Position;
				string text = ((_huntersBy != null) ? (" sent by " + _huntersBy.Name) : "");
				ChronicleDeed("hunters", (list.Count == 1) ? ("You killed a bounty hunter" + text) : $"You killed {list.Count} bounty hunters{text}", "near " + GetZoneName(position), position, _huntersBy?.Gang, (_huntersBy == null) ? new WorldPart[0] : new WorldPart[1] { PartFor(_huntersBy, "SENT THEM", "hired the posse") });
			}
			catch
			{
			}
		}
		_huntersBy = null;
		foreach (Ped hunter in _hunters)
		{
			if (!(hunter == null) && hunter.Exists())
			{
				int handle = hunter.Handle;
				ReleaseIfOurs(&handle);
			}
		}
		_hunters.Clear();
		foreach (Ped hunterHorse in _hunterHorses)
		{
			if (!(hunterHorse == null) && hunterHorse.Exists())
			{
				int handle2 = hunterHorse.Handle;
				ReleaseIfOurs(&handle2);
			}
		}
		_hunterHorses.Clear();
		foreach (Blip hunterBlip in _hunterBlips)
		{
			if (hunterBlip != null && hunterBlip.Exists())
			{
				hunterBlip.Delete();
			}
		}
		_hunterBlips.Clear();
	}

	private void SaveWorld()
	{
		_worldDirty = true;
	}

	private void FlushWorld()
	{
		if (_worldDirty && Game.GameTime >= _nextWorldSave && Game.GameTime - _lastRosterFlushAt >= 4000 && !Slicing("world"))
		{
			_nextWorldSave = Game.GameTime + 60000;
			SaveWorldNow(background: true, sliced: true);
		}
	}

	internal void CleanMixedTimeline(long now)
	{
		WorldState chronicle = Chronicle;
		long lo;
		long hi;
		if (!chronicle.MixedTimelineCleaned && now > 0)
		{
			chronicle.MixedTimelineCleaned = true;
			lo = now - 43200;
			hi = now + 60;
			int num = chronicle.Events.RemoveAll((WorldEvent e) => !e.IsPast && Out(e.GameMin));
			int num2 = chronicle.Telegrams?.RemoveAll((Telegram t) => Out(t.SentAt)) ?? 0;
			int num3 = (chronicle.DeathNews?.RemoveAll((DeathNews n) => Out(n.DueAt)) ?? 0) + (chronicle.PeopleNews?.RemoveAll((DeathNews n) => Out(n.DueAt)) ?? 0);
			int num4 = chronicle.Plans?.RemoveAll((Plan p) => Out(p.DueAt)) ?? 0;
			SaveWorld();
			GrudgeLog($"TIMELINE clean-up: {num} events, {num2} telegrams, {num3} news and {num4} plans from another playthrough taken out (more than {30} days from {GameDate.FromMinutes(now):MMM d})");
		}
		bool Out(long m)
		{
			if (m > 0)
			{
				if (m >= lo)
				{
					return m > hi;
				}
				return true;
			}
			return false;
		}
	}

	private void SaveWorldNow(bool background = false, bool sliced = false)
	{
		if (sliced && Slicing("world"))
		{
			return;
		}
		if (!background && !SafeFile.WaitWrites())
		{
			background = true;
		}
		try
		{
			WorldState chronicle = Chronicle;
			if (chronicle.Events.Count > 5000)
			{
				chronicle.Events.RemoveRange(0, chronicle.Events.Count - 5000);
			}
			StampEventShifts(0L);
			foreach (WorldEvent @event in chronicle.Events)
			{
				if (@event.Title != null && @event.Title.Contains("he The "))
				{
					@event.Title = UiDraw.TheFix(@event.Title);
				}
				if (@event.Place != null && @event.Place.Contains("he The "))
				{
					@event.Place = UiDraw.TheFix(@event.Place);
				}
				if (@event.Lines == null)
				{
					continue;
				}
				for (int i = 0; i < @event.Lines.Count; i++)
				{
					if (@event.Lines[i] != null && @event.Lines[i].Contains("he The "))
					{
						@event.Lines[i] = UiDraw.TheFix(@event.Lines[i]);
					}
				}
			}
			if (chronicle.RelationWhy != null)
			{
				foreach (string item in chronicle.RelationWhy.Keys.ToList())
				{
					if (chronicle.RelationWhy[item] != null && chronicle.RelationWhy[item].Contains("he The "))
					{
						chronicle.RelationWhy[item] = UiDraw.TheFix(chronicle.RelationWhy[item]);
					}
				}
			}
			if (sliced)
			{
				_worldDirty = false;
				StartSlice("world", WorldPath, chronicle, _worldGen, (Exception err) =>
				{
					if (err != null)
					{
						_worldDirty = true;
					}
				});
				return;
			}
			_worldGen++;
			string text = JsonConvert.SerializeObject(chronicle);
			if (background)
			{
				_worldDirty = false;
				SafeFile.WriteLater(WorldPath, text, keepBak: true, (Exception err) =>
				{
					if (err != null)
					{
						_worldDirty = true;
					}
				});
			}
			else
			{
				SafeWrite(WorldPath, text);
				_worldDirty = false;
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("WORLD save failed: " + ex.Message);
		}
	}

	internal static void SafeWrite(string path, string text)
	{
		SafeFile.Write(path, text, keepBak: true);
	}

	internal void KeepBadFile(string path, Exception ex)
	{
		GrudgeLog("LOAD failed for " + Path.GetFileName(path) + ": " + ex.Message + " - kept as .bad");
		try
		{
			byte[] array = File.ReadAllBytes(path);
			string[] files = Directory.GetFiles(Path.GetDirectoryName(path) ?? ".", Path.GetFileName(path) + ".bad-*");
			foreach (string text in files)
			{
				if (new FileInfo(text).Length == array.Length && File.ReadAllBytes(text).SequenceEqual(array))
				{
					return;
				}
			}
			File.Copy(path, path + $".bad-{DateTime.Now:yyyyMMdd-HHmmss}", overwrite: true);
		}
		catch
		{
		}
	}

	private void PruneSideCopies()
	{
		int gone = 0;
		try
		{
			foreach (string item in new List<string>
			{
				_saveDir,
				ContentDir,
				Path.Combine(ContentDir, "encounters")
			})
			{
				Prune(item, ".before-update-", 1);
				Prune(item, ".unreadable-", 2);
				Prune(item, ".bad-", 2);
				Prune(item, ".before-restore-", 2);
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("LOAD side-copy prune failed: " + ex.Message);
		}
		if (gone > 0)
		{
			GrudgeLog($"LOAD removed {gone} old side copies (.before-update / .unreadable / .bad / .before-restore)");
		}
		void Prune(string dir, string tag, int keep)
		{
			if (!Directory.Exists(dir))
			{
				return;
			}
			foreach (IGrouping<string, string> item2 in from f in Directory.GetFiles(dir, "*" + tag + "*")
				group f by f.Substring(0, f.IndexOf(tag, StringComparison.Ordinal)))
			{
				foreach (string item3 in item2.OrderByDescending((string f) => Path.GetFileName(f), StringComparer.Ordinal).Skip(keep))
				{
					try
					{
						File.Delete(item3);
						gone++;
					}
					catch
					{
					}
				}
			}
		}
	}

	private void UpdateWorldSim(Ped player)
	{
		if (!Config.WorldEvents || Game.GameTime < _nextWorldCheck)
		{
			return;
		}
		_nextWorldCheck = Game.GameTime + 2000;
		FadeWitnessFear();
		if (_menu.IsOpen || _bulletImpact.ViewerOpen)
		{
			return;
		}
		long num = GameMinutesNow();
		if (num <= 0)
		{
			return;
		}
		WorldState chronicle = Chronicle;
		long num2 = (long)Config.WorldMaxHours * 60L;
		if (chronicle.NextEventAt == 0L || chronicle.NextEventAt - num > num2 * 2)
		{
			chronicle.NextEventAt = num + NextWorldGap();
			SaveWorld();
		}
		else
		{
			if (num < chronicle.NextEventAt)
			{
				return;
			}
			long num3 = num - chronicle.NextEventAt;
			bool flag = num3 >= 60 || _catchUpHours > 0;
			if (flag && (WorldBusy(player) || Game.GameTime - _loadedAt < 15000 || Game.GameTime - _quietEndedAt < 5000))
			{
				return;
			}
			if (num3 > (long)Config.WorldCatchUpMax * 60L)
			{
				chronicle.NextEventAt = num - (long)(Config.WorldCatchUpMax - 1) * 60L;
			}
			HashSet<WorldEvent> had = new HashSet<WorldEvent>(Chronicle.Events);
			int num4 = 0;
			_worldCatchingUp = flag;
			try
			{
				Crumbs.Mark(flag ? "world catch-up" : "world batch");
				while (chronicle.NextEventAt <= num && num4 < (flag ? 3 : Config.WorldCatchUpMax))
				{
					RunWorldBatch(player, chronicle.NextEventAt);
					num4++;
					chronicle.NextEventAt += NextWorldGap();
				}
			}
			finally
			{
				_worldCatchingUp = false;
			}
			if (flag)
			{
				_catchUpHours += num4;
				_catchUpEvents.AddRange(Chronicle.Events.Where((WorldEvent e) => !had.Contains(e)));
				if (chronicle.NextEventAt <= num)
				{
					SaveWorld();
					return;
				}
				List<WorldEvent> list = _catchUpEvents.ToList();
				int catchUpHours = _catchUpHours;
				_catchUpEvents.Clear();
				_catchUpHours = 0;
				int num5 = list.Sum((WorldEvent e) => Enumerable.Count(e.People, (WorldPart p) => p.Outcome == "KILLED"));
				GrudgeLog($"WORLD caught up {catchUpHours} hours: {list.Count} events, {num5} named dead");
				Feed(string.Format("WORLD while you were away: {0} events over {1} hours{2}", list.Count, catchUpHours, (num5 > 0) ? $", {num5} named dead" : ""), Theme.Gold);
				string text = string.Format("While you were away: {0} things happened{1}. See the World tab.", list.Count, (num5 > 0) ? $" - {num5} named men dead" : "");
				if (Config.WorldNews >= ((num5 > 0) ? 1 : 2))
				{
					WorldNotice(text);
				}
			}
			if (chronicle.NextEventAt <= num)
			{
				chronicle.NextEventAt = num + NextWorldGap();
			}
			SaveRoster();
			SaveWorld();
		}
	}

	private static DateTime FromGameMinutes(long m)
	{
		return GameDate.FromMinutes(m);
	}

	private long NextWorldGap()
	{
		return Math.Max(25L, (long)(60.0 * ((double)Config.WorldMinHours + _rng.NextDouble() * (double)Math.Max(0, Config.WorldMaxHours - Config.WorldMinHours))) + _rng.Next(-20, 21));
	}

	internal string NextWorldEventText()
	{
		long num = Chronicle.NextEventAt - GameMinutesNow();
		if (num > 0)
		{
			if (num < 60)
			{
				return $"{num}m";
			}
			return $"{num / 60}h {num % 60:00}m";
		}
		return "soon";
	}

	private void RunWorldBatch(Ped player, long now)
	{
		int num = ((_rng.Next(100) < Config.WorldBigBatchChance) ? (Config.WorldBigBatchMin + _rng.Next(Math.Max(1, Config.WorldBigBatchMax - Config.WorldBigBatchMin + 1))) : (Config.WorldBatchMin + _rng.Next(Math.Max(1, Config.WorldBatchMax - Config.WorldBatchMin + 1))));
		bool flag = false;
		DateTime d = FromGameMinutes(now);
		int day = GameDate.DayKey(d);
		int num2 = Enumerable.Count(Chronicle.Events, (WorldEvent e) => e.Day == day && (e.Kind == "CLASH" || e.Kind == "CAMP OVERRUN"));
		int count = Chronicle.Events.Count;
		for (int num3 = 0; num3 < num; num3++)
		{
			string text = PickWorldKind();
			if (text == "CLASH" && (flag || num2 >= Config.WorldMaxClashesPerDay))
			{
				text = "LIFE";
			}
			if (text == "CLASH")
			{
				flag = true;
			}
			RunWorldEvent(player, now - ((num3 == 0) ? _rng.Next(0, 6) : _rng.Next(0, 50)), text);
		}
		try
		{
			WarBattles(player, now);
		}
		catch (Exception ex)
		{
			GrudgeLog("WAR battles failed: " + ex.Message);
		}
		if (Chronicle.Events.Count > count)
		{
			int num4 = Math.Max(0, count - 8);
			List<WorldEvent> list = (from e in Chronicle.Events.Skip(num4)
				orderby e.GameMin
				select e).ToList();
			Chronicle.Events.RemoveRange(num4, list.Count);
			Chronicle.Events.AddRange(list);
		}
	}

	private string PickWorldKind()
	{
		int turmoilWeight = TurmoilWeight;
		int val = Config.WorldClashWeight + Config.WorldFeudWeight + Config.WorldBrawlWeight + Config.WorldLifeWeight + Config.WorldRivalryWeight + Config.WorldVdlWeight + Config.WorldWordWeight + turmoilWeight;
		int num = _rng.Next(Math.Max(1, val));
		if ((num -= turmoilWeight) < 0)
		{
			return "TURMOIL";
		}
		if ((num -= Config.WorldWordWeight) < 0)
		{
			return "WORD";
		}
		if ((num -= Config.WorldClashWeight) < 0)
		{
			return "CLASH";
		}
		if ((num -= Config.WorldRivalryWeight) < 0)
		{
			return "RIVALRY";
		}
		if ((num -= Config.WorldVdlWeight) < 0)
		{
			return "VDL";
		}
		if ((num -= Config.WorldFeudWeight) < 0)
		{
			return "FEUD";
		}
		if ((num -= Config.WorldBrawlWeight) < 0)
		{
			return "BRAWL";
		}
		return "LIFE";
	}

	internal void SimulateWorldEventNow()
	{
		RunWorldBatch(Game.Player.Character, GameMinutesNow());
		SaveRoster();
		SaveWorld();
	}

	private void RunWorldEvent(Ped player, long now, string force)
	{
		_historyAt = now;
		try
		{
			RunWorldEventAt(player, now, force);
		}
		finally
		{
			_historyAt = null;
		}
	}

	private void RunWorldEventAt(Ped player, long now, string force)
	{
		string text = force ?? PickWorldKind();
		WorldEvent worldEvent = null;
		try
		{
			switch (text)
			{
			case "CLASH":
				worldEvent = SimClash(player, now);
				break;
			case "FEUD":
				worldEvent = SimFeud(now);
				break;
			case "BRAWL":
				worldEvent = SimBrawl(player, now);
				break;
			case "RIVALRY":
				worldEvent = SimRivalry(now);
				break;
			case "VDL":
				worldEvent = SimVanDerLinde(now);
				break;
			case "WORD":
				worldEvent = SimWord(now);
				break;
			case "TURMOIL":
				worldEvent = SimTurmoil(player, now);
				break;
			}
			if (worldEvent == null)
			{
				worldEvent = SimLife(now);
			}
		}
		catch (Exception ex)
		{
			GrudgeLog("WORLD event failed: " + ex);
		}
		if (worldEvent == null)
		{
			return;
		}
		worldEvent.Heard = WordReachesYou(worldEvent, player);
		if (!Chronicle.Events.Contains(worldEvent))
		{
			Chronicle.Events.Add(worldEvent);
		}
		try
		{
			NoteClashForWars(worldEvent);
		}
		catch (Exception ex2)
		{
			GrudgeLog("RELATION clash note failed: " + ex2.Message);
		}
		int num = Enumerable.Count(worldEvent.People, (WorldPart p) => p.Outcome == "KILLED");
		GrudgeLog("WORLD " + worldEvent.Kind + " " + worldEvent.Title + ((string.IsNullOrEmpty(worldEvent.Place) || (worldEvent.Title != null && worldEvent.Title.Contains(worldEvent.Place))) ? "" : (" " + ((worldEvent.Place != null && (worldEvent.Place.StartsWith("in ") || worldEvent.Place.StartsWith("at ") || worldEvent.Place.StartsWith("near ") || worldEvent.Place.StartsWith("outside "))) ? worldEvent.Place : ("at " + worldEvent.Place)))) + ((worldEvent.People.Count == 0) ? "" : (": " + string.Join("; ", worldEvent.People.Select((WorldPart p) => p.Name + " " + p.Outcome + (p.SecretlyLived ? " (lived)" : ""))))) + ((worldEvent.UnnamedDead.Count > 0) ? (" | unnamed dead " + string.Join(", ", worldEvent.UnnamedDead.Select((KeyValuePair<string, int> kv) => kv.Key + " " + kv.Value))) : "") + $" | heard {worldEvent.Heard}");
		Feed("WORLD " + worldEvent.Kind + ": " + worldEvent.Title + ((worldEvent.Place != null) ? (" - " + worldEvent.Place) : "") + ((num > 0) ? $" ({num} dead)" : ""), KindColor(worldEvent.Kind));
		if (!_worldCatchingUp && worldEvent.Heard && worldEvent.Kind != "LIFE" && Config.MessageLevel >= 2)
		{
			string title;
			if (worldEvent.Kind == "VDL")
			{
				title = "Van der Linde";
			}
			else if (worldEvent.Kind == "JOB")
			{
				title = "Word on the trail";
			}
			else
			{
				title = ((worldEvent.Kind == "RIVALRY") ? "Rivals" : "Word on the trail");
			}
			UiFeed.Toast(title, worldEvent.Title);
		}
		if (_worldCatchingUp || !worldEvent.Heard)
		{
			return;
		}
		int worldNews = Config.WorldNews;
		string text2 = TitleWithPlace(worldEvent);
		if (num > 0 && worldNews >= 1)
		{
			WorldNotice(text2 + ". " + string.Join(", ", from p in worldEvent.People
				where p.Outcome == "KILLED"
				select p.Name) + " dead.");
		}
		else if (num == 0 && ((worldEvent.Kind != "LIFE" && worldNews >= 2) || (worldEvent.Kind == "LIFE" && worldNews >= 3)))
		{
			WorldNotice(text2 + ".");
		}
	}

	private bool WordReachesYou(WorldEvent ev, Ped player)
	{
		if (ev.HasPos && player != null && new Vector3(ev.X, ev.Y, ev.Z).DistanceTo(player.Position) < 1500f)
		{
			return true;
		}
		foreach (WorldPart p in ev.People)
		{
			NemesisRecord nemesisRecord = Roster.FirstOrDefault((NemesisRecord n) => n.Id == p.Id);
			if (nemesisRecord != null && (nemesisRecord.TimesAmbushed > 0 || nemesisRecord.PersonalityKnown || nemesisRecord.TimesInterrogated > 0 || nemesisRecord.Origin != GrudgeOrigin.GangMember))
			{
				return true;
			}
		}
		return _rng.Next(100) < 35;
	}

	internal static string TitleWithPlace(WorldEvent ev)
	{
		if (!string.IsNullOrEmpty(ev.Place) && (ev.Title ?? "").IndexOf(ev.Place, StringComparison.OrdinalIgnoreCase) < 0)
		{
			return ev.Title + " " + ev.Place;
		}
		return ev.Title;
	}

	internal static string LoreNow(string s)
	{
		if (string.IsNullOrEmpty(s) || !s.Contains("Favours"))
		{
			return s;
		}
		string text = Gangs.Army?.LeaderName;
		if (text == null || text.Contains("Favours"))
		{
			return s;
		}
		string newValue = (text.Contains(' ') ? text.Substring(text.LastIndexOf(' ') + 1) : text);
		return s.Replace("Colonel Favours", text).Replace("Favours", newValue);
	}

	internal static string KindLabel(string kind)
	{
		string text;
		switch (kind)
		{
		default:
			text = kind;
			if (text == null)
			{
				return "";
			}
			break;
		case "YOU":
			return "YOUR DOING";
		case "TURMOIL":
			return "UPHEAVAL";
		case "WORD":
			return "RUMOUR";
		case "VDL":
			return "THE GANG";
		case "ERA":
			text = "EIGHT YEARS LATER";
			break;
		}
		return text;
	}

	internal static (int r, int g, int b) KindColor(string kind)
	{
		switch (kind)
		{
		default:
			return (r: 170, g: 180, b: 150);
		case "DUTY":
			return (r: 140, g: 150, b: 110);
		case "CRIME":
			return (r: 214, g: 150, b: 80);
		case "RAID":
			return (r: 200, g: 96, b: 80);
		case "LORE":
			return (r: 196, g: 170, b: 120);
		case "VDL":
			return (r: 170, g: 140, b: 110);
		case "WORD":
			return (r: 150, g: 170, b: 210);
		case "RIVALRY":
			return (r: 205, g: 120, b: 90);
		case "JOB":
			return (r: 200, g: 160, b: 90);
		case "WAR":
			return (r: 214, g: 72, b: 52);
		case "RANKS":
			return (r: 170, g: 150, b: 220);
		case "WITNESSED":
			return (r: 110, g: 160, b: 210);
		case "YOU":
			return (r: 215, g: 178, b: 95);
		case "FEUD":
		case "BRAWL":
		case "DUEL":
			return Theme.Warn;
		case "CLASH":
		case "CAMP OVERRUN":
			return Theme.Blood;
		case "ERA":
			return Theme.Gold;
		}
	}

	internal WorldEvent ChronicleDeed(string tag, string title, string place, Vector3? pos, string gangId, params WorldPart[] parts)
	{
		if (!Config.WorldEvents)
		{
			return null;
		}
		long num = GameMinutesNow();
		WorldState chronicle = Chronicle;
		if ((tag == "kill" || tag == "nemesis") && pos.HasValue)
		{
			int num2 = ((tag == "kill") ? 20 : 90);
			WorldEvent worldEvent = chronicle.Events.Skip(Math.Max(0, chronicle.Events.Count - 30)).LastOrDefault((WorldEvent e) => e.Tag == tag);
			if (worldEvent != null && num - worldEvent.GameMin <= num2 && num >= worldEvent.GameMin && worldEvent.HasPos && new Vector3(worldEvent.X, worldEvent.Y, worldEvent.Z).DistanceTo(pos.Value) < 400f)
			{
				foreach (WorldPart p in parts)
				{
					if (!worldEvent.People.Any((WorldPart x) => x.Id != null && x.Id == p.Id))
					{
						worldEvent.People.Add(p);
					}
				}
				if (gangId != null && !worldEvent.Gangs.Contains(gangId))
				{
					worldEvent.Gangs.Add(gangId);
				}
				if (tag == "kill")
				{
					List<string> list = (from x in worldEvent.People
						where x.Outcome == "KILLED"
						select x.Name).ToList();
					worldEvent.Title = ((list.Count <= 3) ? ("You killed " + string.Join(", ", list)) : $"You killed {list.Count} men");
				}
				else
				{
					List<string> list2 = (from x in worldEvent.People
						select x.Name into x
						where x != null
						select x).ToList();
					WorldEvent worldEvent2 = worldEvent;
					string title2;
					if (list2.Count == 1)
					{
						title2 = list2[0] + " swore vengeance on you";
					}
					else
					{
						title2 = ((list2.Count <= 3) ? (string.Join(", ", list2.Take(list2.Count - 1)) + " and " + list2.Last() + " swore vengeance on you") : $"{list2.Count} men swore vengeance on you");
					}
					worldEvent2.Title = title2;
				}
				SaveWorld();
				return worldEvent;
			}
		}
		WorldEvent worldEvent3 = NewEvent("YOU", num);
		worldEvent3.Tag = tag;
		worldEvent3.Title = title;
		worldEvent3.Place = place;
		worldEvent3.Heard = true;
		if (pos.HasValue)
		{
			worldEvent3.HasPos = true;
			worldEvent3.X = pos.Value.X;
			worldEvent3.Y = pos.Value.Y;
			worldEvent3.Z = pos.Value.Z;
		}
		worldEvent3.Gangs.Add(gangId ?? "");
		worldEvent3.People.AddRange(parts);
		chronicle.Events.Add(worldEvent3);
		SaveWorld();
		return worldEvent3;
	}

	internal WorldPart PartFor(NemesisRecord r, string outcome, string note = null)
	{
		WorldPart worldPart = new WorldPart
		{
			Id = r?.Id,
			Name = (r?.Name ?? "a stranger"),
			Gang = r?.Gang,
			Outcome = outcome,
			Note = note
		};
		if (r != null)
		{
			(string mood, List<Thought> thoughts) tuple = MoodOf(r);
			var (text, _) = tuple;
			if (tuple.thoughts.Count > 0 && r.IsAlive && !r.PresumedDead)
			{
				worldPart.Effects.Add(text ?? "");
			}
		}
		return worldPart;
	}

	internal void ChronicleWitness(string title, string place, Vector3 pos, IEnumerable<string> gangs, List<WorldPart> parts, Dictionary<string, int> unnamedDead, List<string> lines)
	{
		if (!Config.WorldEvents)
		{
			return;
		}
		WorldEvent worldEvent = NewEvent("WITNESSED", GameMinutesNow());
		worldEvent.Title = title;
		worldEvent.Place = place;
		worldEvent.Heard = true;
		worldEvent.HasPos = true;
		worldEvent.X = pos.X;
		worldEvent.Y = pos.Y;
		worldEvent.Z = pos.Z;
		worldEvent.Gangs.AddRange(gangs.Distinct());
		worldEvent.People.AddRange(parts);
		foreach (KeyValuePair<string, int> item in unnamedDead)
		{
			if (item.Value > 0)
			{
				worldEvent.UnnamedDead[item.Key] = item.Value;
			}
		}
		worldEvent.Lines.AddRange(lines);
		Chronicle.Events.Add(worldEvent);
		SaveWorld();
		Feed("WORLD WITNESSED: " + title + " " + place, KindColor("WITNESSED"));
	}

	internal void ChronicleRanks(Gang g, List<WorldPart> parts, string title = null)
	{
		if (Config.WorldEvents && parts.Count != 0)
		{
			WorldEvent worldEvent = NewEvent("RANKS", GameMinutesNow());
			worldEvent.Title = title ?? ("The " + g.Name + " shook up their ranks");
			worldEvent.Place = "";
			worldEvent.Heard = true;
			worldEvent.Gangs.Add(g.Id);
			worldEvent.People.AddRange(parts);
			Chronicle.Events.Add(worldEvent);
			SaveWorld();
		}
	}

	private WorldEvent NewEvent(string kind, long now)
	{
		DateTime d = FromGameMinutes(now);
		WorldEvent worldEvent = new WorldEvent();
		worldEvent.Id = NewId(10);
		worldEvent.Kind = kind;
		worldEvent.GameMin = now;
		worldEvent.Day = GameDate.DayKey(d);
		worldEvent.When = $"{Months[d.Month - 1]} {d.Day}  {d.Hour:00}:{d.Minute:00}";
		return worldEvent;
	}

	private bool OffStage(NemesisRecord r)
	{
		if (r != null && r.IsAlive && !r.PresumedDead && r != ActiveRecord && r != _sightingRec && !_worldNemeses.ContainsValue(r) && !_townMen.Any((TownMan t) => t.Rec == r))
		{
			return !_liveCamps.Values.Any((LiveCamp c) => c.Boss == r);
		}
		return false;
	}

	private WorldEvent SimClash(Ped player, long now, (Gang a, Gang b, string place, Vector3 pos)? forced = null)
	{
		(Gang, Gang, string, Vector3)? tuple = forced ?? ((_rng.Next(100) < 50) ? WarClash(player) : (((Gang, Gang, string, Vector3)?)null));
		Gang gang;
		Gang gang2;
		(string, Vector3, CampSite)? tuple2;
		if (tuple.HasValue)
		{
			gang = tuple.Value.Item1;
			gang2 = tuple.Value.Item2;
			tuple2 = (tuple.Value.Item3, tuple.Value.Item4, null);
			if (!forced.HasValue)
			{
				District d = DistrictAt(tuple.Value.Item4);
				CampSite campSite = WarGoalCamp(gang, gang2, d);
				if (campSite == null)
				{
					CampSite campSite2 = WarGoalCamp(gang2, gang, d);
					if (campSite2 != null)
					{
						campSite = campSite2;
						Gang gang3 = gang;
						gang = gang2;
						gang2 = gang3;
					}
				}
				if (campSite != null && _rng.Next(100) < 70 && (player == null || new Vector3(campSite.X, campSite.Y, campSite.Z).DistanceTo(player.Position) >= Config.WorldMinDistance))
				{
					tuple2 = ("at " + campSite.Label, new Vector3(campSite.X, campSite.Y, campSite.Z), campSite);
				}
			}
			goto IL_01d6;
		}
		(Gang, Gang, District)? tuple3 = PickClashPair();
		if (tuple3.HasValue)
		{
			(string, Vector3, CampSite)? tuple4 = ClashPlace(tuple3.Value.Item1, tuple3.Value.Item2, tuple3.Value.Item3, player);
			if (tuple4.HasValue)
			{
				gang = tuple3.Value.Item1;
				gang2 = tuple3.Value.Item2;
				tuple2 = tuple4;
				goto IL_01d6;
			}
		}
		return null;
		IL_01d6:
		if (!tuple2.HasValue)
		{
			return null;
		}
		if (TruceBetween(gang.Id, gang2.Id) || IsDestroyed(gang) || IsDestroyed(gang2))
		{
			return null;
		}
		(string, Vector3, CampSite) value = tuple2.Value;
		string item = value.Item1;
		Vector3 item2 = value.Item2;
		CampSite site = value.Item3;
		List<NemesisRecord> list = Side(gang, defending: false);
		List<NemesisRecord> list2 = Side(gang2, defending: true);
		List<Gang> list3 = AlliesAgainst(gang, gang2).ToList();
		List<Gang> list4 = AlliesAgainst(gang2, gang).ToList();
		foreach (Gang item6 in list3)
		{
			list.AddRange(Side(item6, defending: false));
		}
		foreach (Gang item7 in list4)
		{
			list2.AddRange(Side(item7, defending: false));
		}
		if (list.Count + list2.Count == 0)
		{
			return null;
		}
		int num = 2 + _rng.Next(4);
		int num2 = 2 + _rng.Next(4);
		float num3 = Power(list, num) * Stretched(gang) * MenPower(gang);
		float num4 = Power(list2, num2) * Stretched(gang2) * MenPower(gang2) + ((site != null) ? 3f : 0f);
		bool flag = num3 >= num4;
		Gang gang4 = (flag ? gang : gang2);
		Gang loser = (flag ? gang2 : gang);
		WorldEvent worldEvent = NewEvent("CLASH", now);
		worldEvent.Place = item;
		worldEvent.HasPos = true;
		worldEvent.X = item2.X;
		worldEvent.Y = item2.Y;
		worldEvent.Z = item2.Z;
		worldEvent.Gangs.Add(gang.Id);
		worldEvent.Gangs.Add(gang2.Id);
		WorldEvent worldEvent2 = worldEvent;
